var CARDS = [{"id":"prof01","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הגדירו מהי פסיכולוגיה (היעזרו בארבעת המרכיבים: התנהגות, יחיד, פעילות מנטאלית, מדע).","a":"מדע שחוקר התנהגות ומחשבות (תהליכים מנטליים) של יחיד.","explain":"ההגדרה הרשמית (עמ' 6-7 בספר, פתיחת פרק 1): פסיכולוגיה היא המדע החוקר את ההתנהגות של היחיד ואת התהליכים המנטליים שהוא חווה. חשוב להבין שאלו ארבעה מרכיבים נפרדים שחייבים להופיע יחד: <b>מדע</b> - מבוסס על ראיות אמפיריות ושיטה מדעית, לא ניחוש או אינטואיציה. <b>יחיד</b> - מתמקד באדם (או בבעל-חיים) בודד, לא בקבוצה כמו בסוציולוגיה. <b>התנהגות</b> - כל מה שאפשר לצפות בו מבחוץ (תנועה, דיבור, פעולה). <b>תהליכים מנטליים</b> - מה שקורה 'בפנים' ואי-אפשר לצפות בו ישירות (מחשבה, זיכרון, רגש), אך משפיע על ההתנהגות. אם משמיטים אחד מהמרכיבים, ההגדרה כבר לא שלמה - זו הסיבה שהשאלה מבקשת במפורש להיעזר בכל הארבעה.","mnemo":"🎬 דמיינו מדען בחלוק לבן (מדע) שעוקב במיקרוסקופ אחרי אדם בודד אחד (יחיד), שרוקד בטירוף (התנהגות) עם בועת-מחשבה ענקית מעל הראש (מנטלי). כל 4 המרכיבים בתמונה אחת."},{"id":"prof02","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"במה דומה הפסיכולוגיה לתחומי דעת אחרים ובמה היא שונה מהם?","a":"הייחוד: 4 המרכיבים ביחד (מדע+התנהגות+מנטלי+יחיד). דומה לסוציולוגיה (אך היא בקבוצות), לביולוגיה (אך רק המוח), לרפואה (אך רק הגוף), לחינוך (אך יישומי בלבד).","explain":"השאלה מבקשת השוואה, לא רק הגדרה - כל תחום-דעת שכן עוסק ברכיב אחד מהארבעה, אך לא בכולם יחד. <b>סוציולוגיה</b> חוקרת גם התנהגות, אבל ברמת <b>הקבוצה</b> (חברה, מוסדות) ולא היחיד. <b>ביולוגיה</b> חוקרת גם תהליכים פנימיים, אבל ברמת <b>המנגנון הפיזי</b> (תאים, הורמונים) בלי הקשר לתהליכי-חשיבה או משמעות. <b>רפואה</b> מתמקדת <b>בגוף</b> בלבד, גם אם משפיעה על התנהגות. <b>חינוך</b> הוא תחום <b>יישומי-נורמטיבי</b> (מה צריך לקרות בכיתה), לא תחום שמנסה קודם-כל לתאר/להסביר מדעית איך אנשים פועלים. רק פסיכולוגיה משלבת את כל ארבעת המרכיבים גם יחד - זה בדיוק מה שהופך אותה לתחום עצמאי, לא סניף של תחום אחר.","mnemo":"🍕 דמיינו פיצה שלמה (=פסיכולוגיה, כל 4 הפרוסות). כל תחום אחר \"גנב\" רק פרוסה אחת: סוציולוגיה=פרוסת הקבוצה, ביולוגיה=פרוסת המוח, רפואה=פרוסת הגוף, חינוך=פרוסת היישום."},{"id":"prof03","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהן ארבע מטרות הפסיכולוגיה?","a":"לתאר (מה קרה) → להסביר (למה) → לנבא (מה יקרה) → לפקח (לשנות).","explain":"ארבע המטרות מסודרות בסדר לוגי-מדעי קבוע, וכל שלב נשען על הקודם לו: <b>לתאר</b> (מה קורה בפועל, בלי לשפוט או לפרש) → <b>להסביר</b> (לזהות את הגורמים - למה זה קורה) → <b>לנבא</b> (מתי/למי זה יקרה שוב, על סמך ההסבר) → <b>לפקח</b> (להשתמש בידע כדי לשנות בפועל את ההתנהגות - להתחיל/לעצור/לשנות אותה). אי-אפשר לדלג על שלב: אי-אפשר להסביר משהו שלא תיארת קודם במדויק, ואי-אפשר לפקח על משהו בלי לדעת קודם לנבא מתי הוא יקרה.","mnemo":"🕵️ כמו בלש בזירת פשע: 1) מתאר מה קרה, 2) מסביר למה קרה, 3) מנבא מה יקרה הבא, 4) פועל למנוע (לפקח). סדר טבעי של חוקר."},{"id":"prof04","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"יישמו את ארבע מטרות הפסיכולוגיה על התנהגות מוכרת מחיי היום־יום (למשל, אלימות ברשתות חברתיות).","a":"דוגמה - אלימות ברשת: לתאר=לתעד תדירות. להסביר=למה (אימפולסיביות+אנונימיות). לנבא=השערה נבדקת. לפקח=לשנות (חינוך/פלטפורמה).","explain":"השאלה מבקשת יישום מעשי של ארבע המטרות על מקרה קונקרטי, לא רק שינון ההגדרות. הדגם קבוע לכל דוגמה: <b>לתאר</b>=לאסוף נתונים אובייקטיביים (כמה פעמים, אילו סוגים) בלי לשפוט. <b>להסביר</b>=לזהות מנגנון פנימי או חיצוני שגורם להתנהגות (למשל, אנונימיות באינטרנט מפחיתה בושה חברתית). <b>לנבא</b>=לנסח השערה הניתנת לבדיקה אמפירית (אם X גובר, Y יגבר גם-כן). <b>לפקח</b>=ליישם שינוי אמיתי בעולם (לעצב פלטפורמה אחרת, לחנך). זו בדיוק המיומנות שנדרשת בבחינה - לקחת תרחיש חדש ולמפות אותו לארבע המטרות, לא רק לשנן אותן בהפשטה.","mnemo":"🔁 אותו סדר של הבלש (תאר→הסבר→נבא→פקח) - הפעם על אלימות ברשת."},{"id":"prof05","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"דונו בעקרונות הגישה הסטרוקטורליסטית ובשיטות המחקר שלה.","a":"סטרוקטורליזם (טיצ'נר) - חוקר את ה\"מה\" של התודעה: מרכיבי היסוד שלה. שיטה: אינטרוספקציה (התבוננות פנימית). ביקורת: מפרק לחלקים קטנים מדי, מתעלם מהלא-מודע.","explain":"<b>סטרוקטורליזם</b> - הגישה הראשונה בהיסטוריה של הפסיכולוגיה כמדע (סוף המאה ה-19), בהובלת אדוארד טיצ'נר שהביא לארה\"ב את מורשת וילהלם וונדט. השאלה המרכזית: <b>מה</b> מרכיבי היסוד של החוויה המנטלית? הגישה ניסתה 'לפרק' חוויה מורכבת (כמו טעימת תפוח) לרכיבים חושיים הכי בסיסיים - בדיוק כמו שכימאי מפרק חומר ליסודות. השיטה: <b>אינטרוספקציה</b> - הנבדק מתבונן בעצמו ומדווח מילולית על החוויה הפנימית שלו. הביקורת המרכזית: השיטה לא-אמינה (שני אנשים מדווחים אחרת על אותה חוויה), מפרקת לחלקים קטנים-מדי עד שמאבדת משמעות, ומתעלמת לגמרי מתהליכים לא-מודעים.","mnemo":"🧱 סטרוקטורה = בניין מלגו. סטרוקטורליזם שואל \"מאילו קוביות (מרכיבים) התודעה בנויה?\" - מפרקים אותה כמו לגו, ולכן מבקרים אותם שהם \"שוברים\" הכל לחלקים קטנים מדי."},{"id":"prof06","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"דונו בעקרונות הגישה הפונקציונליסטית ובשיטות המחקר שלה.","a":"פונקציונליזם (ג'יימס; דיואי בארה\"ב) - חוקר את ה\"למה\" של התודעה: איך היא עוזרת להסתגל לסביבה. פחות מעבדה, יותר הסבר מעשי.","explain":"<b>פונקציונליזם</b> - הגישה שהתפתחה כתגובה-נגד לסטרוקטורליזם, בהובלת ויליאם ג'יימס (וג'ון דיואי בארה\"ב - חשוב: בספר הזה, דיואי, לא ג'יימס, מוצג כאבי הפונקציונליזם האמריקאי). השאלה המרכזית שונה לגמרי מהסטרוקטורליזם: לא 'מה' מרכיבי התודעה, אלא <b>למה</b> - איזו תכלית/תפקיד ממלאת התודעה בחיי האדם? איך היא עוזרת לו להסתגל לסביבתו ולשרוד? מכיוון שהעניין היה בתפקוד ולא במבנה מדויק, הגישה הייתה פחות תלויה במעבדה קפדנית והדגישה יותר תובנה מעשית - וזו הסיבה שהשפיעה כל-כך חזק על תחום החינוך.","mnemo":"🔧 פונקציה = תפקיד של כלי. שואלים \"בשביל מה זה טוב?\" - כמו לשאול לא מה זה פטיש, אלא למה הוא משמש. ג'יימס+דיואי (D למעשה=Do=לעשות)."},{"id":"prof07","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"השוו בין הגישות הסטרוקטורליסטית לגישה הפונקציונליסטית: מה משותף ביניהן ובמה הן שונות זו מזו?","a":"משותף: שתיים עסקו בתודעה, שתיים מהמאה ה-19. שונה: סטרוקטורליזם=מה (מבנה), פונקציונליזם=למה (תפקיד).","explain":"שאלת השוואה קלאסית - צריך גם דמיון וגם הבדל, לא רק אחד מהם. <b>הדמיון</b>: שתי הגישות צמחו יחד בסוף המאה ה-19, כשהפסיכולוגיה בדיוק נפרדה מהפילוסופיה והפכה למדע עצמאי, ושתיהן ראו <b>בתודעה</b> (לא בהתנהגות חיצונית, לא בלא-מודע) את נושא-המחקר המרכזי. <b>ההבדל</b> הוא בשאלה שנשאלת: סטרוקטורליזם שואל 'מה' (המבנה הסטטי, מרכיבי-היסוד) ומשתמש באינטרוספקציה קפדנית; פונקציונליזם שואל 'למה' (התפקיד הדינמי, ההסתגלות) ומתעניין בתוצאה המעשית. שני ההיבטים (מבנה+תפקוד) ממשיכים להיחקר יחד בפסיכולוגיה המודרנית - המחלוקת ההיסטורית לא נעלמה, היא פשוט השתלבה.","mnemo":"🍎🍊 שני פירות שונים מאותו העץ (סוף המאה ה-19, שניהם על התודעה): סטרוקטורליזם=מה בפנים (המבנה), פונקציונליזם=למה זה טוב (התפקיד)."},{"id":"prof08","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד מסבירה כל אחת משבע הגישות המודרניות את ההתנהגות האנושית?","a":"7 גישות ✕ מקור ההסבר: פסיכודינמית=לא-מודע. ביהביוריסטית=סביבה/גירויים. הומניסטית=בחירה חופשית. קוגניטיבית=מחשבה. ביולוגית=גוף/מוח. אבולוציונית=הישרדות המין. חברתית-תרבותית=תרבות.","explain":"שבע הגישות המודרניות (עמ' 16-24) הן שבע 'עדשות' שונות להסביר את אותה התנהגות - חשוב להבין מהו <b>מקור-ההסבר</b> הייחודי של כל אחת, לא רק לשנן שם. <b>פסיכודינמית</b> (פרויד) - כוחות לא-מודעים ודחפים ביולוגיים מתנגשים עם דרישות החברה. <b>ביהביוריסטית</b> (ווטסון, סקינר) - היסטוריית חיזוקים מהסביבה, בלי צורך במושג 'תודעה' כלל. <b>הומניסטית</b> (רוג'רס, מסלו) - נטייה מולדת חיובית לצמיחה ומימוש-עצמי. <b>קוגניטיבית</b> - איך אדם מפרש/חושב על המצב קובע איך יתנהג. <b>ביולוגית</b> - גנים, מוח, הורמונים. <b>אבולוציונית</b> - מה שסייע לאבותינו לשרוד ולהתרבות. <b>חברתית-תרבותית</b> - נורמות וציפיות מהחברה שבה גדלנו. אותה התנהגות (למשל אלימות) מקבלת הסבר שונה לגמרי מכל גישה - וזו בדיוק הסיבה שיש בכלל 'גישות' מרובות, לא תיאוריה אחת מוסכמת.","mnemo":"🎭 חשבו על 7 \"חשודים\" בחקירת משטרה על התנהגות שלכם: 1)הלא-מודע (פסיכודינמית) 2)הסביבה (ביהביוריסטית) 3)הרצון החופשי (הומניסטית) 4)המחשבה (קוגניטיבית) 5)הביולוגיה (ביולוגית) 6)האבולוציה (אבולוציונית) 7)התרבות (חברתית-תרבותית)."},{"id":"prof09","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"על פי הסעיף \"חשיבה ביקורתית בחיינו\", כיצד מסייעת לנו הפסיכולוגיה המודרנית להבין מדוע חברויות מסתיימות?","a":"3 סיבות לסיום חברויות: תחרות רומנטית, זלזול, בגידת אמון - אך הסדר משתנה בין תרבויות (ארה\"ב≠רוסיה). לקח: לבדוק תרבות לפני הכללה.","explain":"שאלה המבקשת יישום של החשיבה הביקורתית (עמ' 25-29) על תחום מוכר מהחיים. חוקרים בדקו מדוע חברויות מסתיימות ומצאו שלוש קטגוריות חוזרות: <b>תחרות רומנטית</b> (מישהו 'גנב' בן/בת-זוג), <b>זלזול</b> (חוסר-כבוד הדדי), ו<b>בגידת-אמון</b> (חשיפת סוד). הנקודה הביקורתית החשובה: <b>הסדר/החשיבות היחסית</b> של שלוש הסיבות משתנה בין תרבויות שונות (למשל ארה\"ב מול רוסיה) - כלומר, אי-אפשר להכליל ממצא ממקום אחד על כל בני-האדם. הלקח המתודולוגי: לפני שמכלילים מסקנה פסיכולוגית, יש לבדוק אם היא נבחנה גם בהקשרים תרבותיים שונים - זו בדיוק המחשה למגבלות ולחשיבות של הגישה החברתית-תרבותית שנלמדה בשאלה הקודמת.","mnemo":"💔 חושבו: \"הוא גנב לי, זלזל בי, ובגד בי\" - 3 סיבות לסיום חברות (תחרות רומנטית, זלזול, בגידת אמון), אך הסדר שונה בין תרבויות."},{"id":"prof10","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"השוו בין שבע הגישות לפי: חוקרים מרכזיים, כוחות מעצבים, שיטת מחקר, יחס למודע, ודגש על זמן.","a":"טבלת 7 הגישות (איש+דגש+זמן): פסיכודינמית=פרויד,לא-מודע,עבר. ביהביוריסטית=ווטסון/סקינר,סביבה,הווה. הומניסטית=רוג'רס/מאסלו,בחירה,הווה-עתיד. קוגניטיבית=מחשבה,הווה. ביולוגית=ביוכימיה,הווה. אבולוציונית=דארווין,הסתגלות,עבר-רחוק. חברתית-תרבותית=מלינובסקי,תרבות,הווה.","explain":"טבלת-סיכום המשווה את שבע הגישות לפי חמישה קריטריונים אחידים - חשוב לזכור את <b>המבנה</b> (5 העמודות), לא רק את התוכן: <b>חוקרים מרכזיים</b> (מי מזוהה עם הגישה), <b>כוחות מעצבים</b> (מה גורם להתנהגות - לא-מודע/סביבה/בחירה/מחשבה/ביוכימיה/הסתגלות/תרבות), <b>שיטת מחקר</b> מועדפת, <b>יחס למודע</b> (האם מתעניינים בו בכלל), ו<b>דגש זמני</b> (עבר/הווה/עתיד). ⚠️ שימו לב שהדגש-הזמני מבדיל יפה בין גישות שנראות דומות: פסיכודינמית ואבולוציונית שתיהן מסתכלות אחורה, אבל האחת לעבר-האישי (ילדות) והשנייה לעבר-המיני של המין האנושי כולו.","mnemo":"🎭 אותם 7 \"חשודים\", הפעם עם שם ותאריך: פרויד=עבר, ווטסון/סקינר=הווה חיצוני, רוג'רס/מאסלו=הווה-עתיד פנימי, קוגניטיבית=הווה מחשבתי, ביולוגית=הווה גופני, דארווין=עבר-רחוק, מלינובסקי=הווה תרבותי."},{"id":"prof11","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"לכל אחת מהשאלות הבאות, התאימו מטרה מתוך 4 מטרות הפסיכולוגיה: (1) \"כיצד מאוחסנים זיכרונות במוח?\" (2) \"כיצד תלמדו כלב להישמע להוראות?\" (3) \"מדוע אני תמיד נחנק במהלך משחקי כדורסל חשובים?\"","a":"זיכרון במוח→לתאר+להסביר. אילוף כלב→לפקח (+לנבא). חנק בספורט→להסביר (לחץ)+לפקח (שיפור).","explain":"תרגיל התאמה בין תרחיש מהחיים למטרה המתאימה מתוך ארבע מטרות הפסיכולוגיה - וחשוב להבין שלעיתים <b>יותר ממטרה אחת</b> רלוונטית לאותה שאלה. 'איך זיכרונות מאוחסנים במוח?' - שאלה על מנגנון פנימי, ללא כוונה לשנות התנהגות, לכן בעיקר <b>תיאור+הסבר</b>. 'איך מאלפים כלב?' - כאן המטרה המוצהרת היא לשנות התנהגות בפועל, לכן בעיקר <b>פיקוח</b> (גם אם צריך לנבא איך הכלב יגיב לחיזוקים). 'למה אני נחנק במשחקים חשובים?' - קודם צריך <b>להסביר</b> (לזהות שהלחץ/החרדה הוא הגורם), ורק אז אפשר <b>לפקח</b> (ליישם טכניקת-הרגעה לשיפור הביצוע). המסר: המטרות לא בלעדיות זו לזו - צריך לחשוב באיזו מטרה השאלה מתמקדת בעיקר.","mnemo":"🕵️ שוב הבלש מ-4 המטרות: זיכרון-במוח=מתאר+מסביר. אילוף-כלב=מפקח. חנק-בספורט=מסביר+מפקח."},{"id":"quiz01","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"ארבעת מילות המפתח בהגדרת הפסיכולוגיה הינן: (מחקר, התנהגות, אתיקה ומדע / נתונים, נפש, אדם וגוף / מדע, תהליכים מנטליים, יחיד והתנהגות / מחשבות, רגשות, התנהגויות ותחושות / אדם, קבוצה, רגש ומוח)","a":"מדע, תהליכים מנטליים, יחיד והתנהגות (ההגדרה הרשמית משלבת את ארבעת המרכיבים גם יחד)","explain":"זו ניסוח-מחדש (בפורמט 'מלא-החסר') של ההגדרה הרשמית מהעמודים הראשונים של הספר. הטריק בשאלה: יש כמה תשובות-מסיחות שמכילות מילים 'נשמעות-נכון' אך לא מדויקות - למשל 'אתיקה' ו'פוליטיקה' לא חלק מההגדרה הרשמית, ו'רגשות ותחושות' הן דוגמאות לתהליכים-מנטליים אבל לא המונח המדויק שהספר משתמש בו. חשוב לזהות את ארבעת המונחים המדויקים כפי שהם מנוסחים בספר: מדע, תהליכים מנטליים, יחיד, והתנהגות - כל שינוי-ניסוח קטן שנשמע 'קרוב' הוא בדרך-כלל תשובה שגויה בכוונה.","mnemo":"🎬 אותה תמונת המדען (יחיד/התנהגות/מנטלי) + \"מדע\" בחלוק הלבן."},{"id":"quiz02","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"לפי רוג'רס, המטפל צריך לנהוג כ______ (סמכות עליונה כל יודעת / אנליטיקן / מעצב התנהגות / מקדם צמיחה)","a":"מקדם צמיחה (רוג'רס - גישה הומניסטית, לא מנתח/קובע עבור המטופל)","explain":"השאלה בודקת האם מזהים סגנון-טיפול ייחודי לגישה ההומניסטית, מבלי לומר את המילה 'הומניסטית' במפורש. רוג'רס טבע את המושג 'מקדם צמיחה' (growth facilitator) כדי להדגיש שהמטפל <b>אינו</b> סמכות-עליונה שקובעת מה נכון למטופל (זה יהיה פסיכודינמי/דירקטיבי), ואינו רק מעצב-התנהגות חיצוני (זה יהיה ביהביוריסטי). התפקיד: לספק סביבה בטוחה (הערכה-חיובית-בלתי-מותנית, אמפתיה, כנות) שבתוכה המטופל <b>בעצמו</b> מגלה את כוחות-הצמיחה הטבעיים שכבר קיימים בו - ההנחה ההומניסטית הבסיסית היא שכל אדם נושא בתוכו נטייה מולדת למימוש-עצמי, והמטפל רק מסיר מכשולים בדרך.","mnemo":"🌱 רוג'רס = גנן. הוא לא חותך את הצמח (לא מנתח/שופט) - רק משקה אותו (מקדם צמיחה)."},{"id":"quiz03","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"אם את/ה מסכים/ה עם המשפט \"הפעולה הינה תוצר של החשיבה\", אזי אתה מקבל את עקרונות הגישה ה_____ (אבולוציונית / קוגניטיבית / התנהגותית / פסיכודינאמית)","a":"קוגניטיבית (מחשבה קודמת לפעולה - העיקרון המרכזי של הגישה)","explain":"המשפט 'הפעולה הינה תוצר של החשיבה' הוא ניסוח כמעט-מילולי של ההנחה המרכזית בגישה הקוגניטיבית: לפני שאדם מתנהג, הוא <b>מפרש</b>, <b>מעריך</b> ו<b>מחליט</b> - וההתנהגות היא התוצאה של תהליך המחשבה הזה, לא תגובה אוטומטית לגירוי (זה יהיה ביהביוריסטי) ולא ביטוי של דחף לא-מודע (זה יהיה פסיכודינמי). שימו לב לכיוון-החץ בשאלה: 'חשיבה←פעולה', לא ההפך - זה בדיוק מה שמבדיל את הקוגניטיבית משאר הגישות שראינו.","mnemo":"💭➡️🏃 חשבו על בועת-מחשבה שדוחפת רגליים לרוץ: קודם חושבים (קוגניציה מלטינית=\"לדעת/לחשוב\"), אז זזים."},{"id":"quiz04","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"הגישה הקוגניטיבית מתמקדת ב: (מחשבות / רגשות / התנהגות / רגשות שמובילות למחשבות)","a":"מחשבות (הגישה הקוגניטיבית עוסקת בתהליכי חשיבה, לא בהתנהגות ישירות)","explain":"שאלה זו בודקת יכולת להבחין בין 'מוקד-ההתעניינות' של הגישה הקוגניטיבית לבין הגישות השכנות לה. הגישה הקוגניטיבית עוסקת <b>בתהליכי-חשיבה עצמם</b> (תפיסה, זיכרון, פתרון-בעיות, קבלת-החלטות) - לא בהתנהגות הנצפית-מבחוץ (זה ביהביוריזם) ולא ברגשות כנקודת-מוצא (למרות שרגשות יכולים להיות תוצר של מחשבה, לא הפוך, לפי גישה זו). ⚠️ ההבחנה הזו חוזרת בכמה שאלות בפרק - אם השאלה מזכירה 'תפיסה/פרשנות/ציפייה/אמונה' זה כמעט תמיד קוגניטיבי.","mnemo":"💭 קוגניטיבי נשמע כמו \"קוגניציה\"=חשיבה. תחשבו על מוח עם גלגלי שיניים מסתובבים בפנים."},{"id":"quiz05","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"לגילי וגילה ישנם קשיים בחיי הזוגיות. סביר כי הם יפנו ל________ (פסיכולוג קליני / פסיכיאטר / אחות פסיכיאטרית / פסיכולוג חברתי / פסיכולוג חינוכי)","a":"פסיכולוג קליני (פסיכולוג קליני מטפל בבעיות אישיות/בין-אישיות, לא רק ייעוץ)","explain":"שאלת-סיווג בין תתי-התחומים המקצועיים של הפסיכולוגיה (עמ' 12-13) - צריך לדעת מי מטפל במה. <b>פסיכולוג קליני</b> מוסמך לאבחן ולטפל בקשת רחבה של קשיים אישיים ובין-אישיים, כולל בעיות זוגיות - זה תחום-הטיפול הרחב ביותר. <b>פסיכיאטר</b> הוא רופא (בעל תואר רפואי) המתמקד בטיפול תרופתי/ביורפואי, לאו-דווקא יעוץ-זוגי. <b>פסיכולוג חברתי</b> חוקר תהליכים חברתיים כלליים במעבדה, לא מטפל בפרטים. <b>פסיכולוג חינוכי</b> מתמקד בהקשר הלימודי-בית-ספרי. קשיים בזוגיות = קליני, כי זה בדיוק ליבת-העיסוק של התחום.","mnemo":"💑🏥 קליני = כמו \"קלינִיקה\" - מרפאה לבעיות אישיות/זוגיות אמיתיות, לא ייעוץ קליל."},{"id":"quiz06","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"סביר כי פסיכולוג_________ עורך מחקרים הקשורים למקום העבודה (ייעוצי / ארגוני-תעשייתי / חברתי / התפתחותי / ניסויי)","a":"ארגוני-תעשייתי (מתמחה במקום העבודה - גיוס, מוטיבציה, ביצועים)","explain":"פסיכולוג <b>תעשייתי-ארגוני</b> (I/O - Industrial/Organizational) הוא התחום שבוחן התנהגות ספציפית <b>במקום העבודה</b>: תהליכי גיוס וקליטה, מוטיבציה של עובדים, שביעות-רצון, ביצועים ויעילות ארגונית. זהו תחום יישומי שמשלב עקרונות פסיכולוגיים עם ניהול וכלכלת-ארגונים - שונה מפסיכולוגיה חברתית (שחוקרת התנהגות חברתית כללית, לא דווקא בהקשר עבודה) ומפסיכולוגיה קלינית (טיפול בבעיות אישיות, לא ארגוניות).","mnemo":"🏢 דמיינו משרד עם עובדים - זה בדיוק \"ארגוני-תעשייתי\" (המילה \"ארגון\" נמצאת ממש בתוך השם)."},{"id":"quiz07","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"אם פרופסור ברוק חוקרת אודות תהליכי הזיכרון, אזי סביר להניח שהיא פסיכולוגית (חברתית / אישיותית / קוגניטיבית / התפתחותית / נוירו-פסיכולוגית)","a":"קוגניטיבית (זיכרון הוא תהליך מנטלי מרכזי הנחקר בגישה זו)","explain":"מחקר <b>זיכרון</b> הוא דוגמה קלאסית לתחום-עניין של הפסיכולוגיה הקוגניטיבית - זיכרון הוא בדיוק סוג של 'תהליך מנטלי פנימי' (איך מידע נקלט, מאוחסן ונשלף) שהגישה הקוגניטיבית שמה במרכז. ⚠️ טעות נפוצה: לבלבל עם נוירו-פסיכולוגיה, שגם היא עוסקת בזיכרון אבל ברמת <b>המנגנון המוחי הפיזי</b> (איזה אזור-מוח אחראי), לא ברמת <b>התהליך המנטלי-קוגניטיבי</b> עצמו (איך המידע מעובד). מכיוון שהשאלה לא מזכירה מוח/נוירונים, זו קוגניטיבית.","mnemo":"🧠💭 זיכרון קורה בתוך הראש (תהליך מחשבתי) = קוגניטיבי."},{"id":"quiz08","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"הגדרת הפסיכולוגיה מתמקדת גם ב___________ וגם ב________ (תהליכים מנטליים; מבנים / התנהגות; תהליכים מנטליים / תהליכים מנטליים; פונקציות / התנהגות; מבנים)","a":"התנהגות; תהליכים מנטליים (ההגדרה כוללת את שני המרכיבים גם יחד)","explain":"שאלה זו בודקת שוב, בניסוח שונה, שני מרכיבים מתוך ארבעת מרכיבי ההגדרה הרשמית - הפעם ספציפית התנהגות+תהליכים-מנטליים גם יחד (בהשמטת 'מדע' ו'יחיד' מהאפשרויות המוצעות). זו נקודה שהספר מדגיש שוב ושוב: הפסיכולוגיה לא מסתפקת רק בתיעוד מה שרואים מבחוץ (התנהגות) ולא רק במה שקורה בפנים (תהליכים מנטליים) - היא חייבת את שניהם יחד, כי הם משפיעים זה על זה.","mnemo":"⚖️ מאזניים עם 2 כפות: כף אחת \"מה שרואים מבחוץ\" (התנהגות), כף שנייה \"מה שקורה בפנים\" (מנטלי) - שתיהן תמיד ביחד."},{"id":"quiz09","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"לאיזה מטרה בפסיכולוגיה רלוונטית \"רמת הניתוח\" יותר מכול? (לתאר מה קרה / להסביר מה קרה / לנבא מה יקרה / לשלוט במה שקורה)","a":"לתאר מה קרה (רמת ניתוח=פירוט ההתרחשות עצמה, לא ההסבר/ניבוי)","explain":"<b>רמת הניתוח</b> (level of analysis) - עד כמה 'מזמזמים-פנימה' לפרטים, מהרמה הכללית-הוליסטית (למשל: 'הוא כעס') ועד לרמה המפורטת ביותר (למשל: 'שחרור אדרנלין הפעיל את מערכת העצבים הסימפתטית'). המושג הזה שייך בעיקר לשלב <b>התיאור</b>, כי הבחירה ברמת-הניתוח קובעת <b>איך בדיוק</b> נתעד את מה שקורה - עוד לפני שמתחילים בכלל להסביר, לנבא או לפקח. זה מושג-כלים (methodological), לא הסבר-תוכן.","mnemo":"📸 \"רמת ניתוח\" = כמה מפורטת התמונה שאתה מצלם. תמונה=תיאור, לא הסבר/ניבוי."},{"id":"quiz10","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"אם אתם רוצים ________ מה שיקרה, עליכם בראש ובראשונה להיות מסוגלים ________ מה שיקרה. (להסביר את ; לנבא את / לשלוט ב ; לנבא את / לתאר את ; לשלוט ב / לתאר את ; להסביר את)","a":"לשלוט ב ; לנבא את (שליטה דורשת תחילה יכולת לחזות את מה שיקרה)","explain":"שאלה זו בודקת את <b>סדר-התלות</b> בין ארבע המטרות - לא מספיק לדעת מה כל מטרה אומרת, צריך לדעת גם מה תלוי במה. <b>שליטה/פיקוח</b> (להתחיל, לעצור, לשנות התנהגות) היא המטרה השאפתנית ביותר - ואי-אפשר לשלוט במשהו בלי לדעת קודם <b>לנבא</b> מתי ובאילו תנאים הוא יקרה. ובאותה לוגיקה (לא נשאלת כאן אך שווה לזכור): אי-אפשר לנבא בלי להסביר קודם, ואי-אפשר להסביר בלי לתאר קודם. זו שרשרת חד-כיוונית: תיאור→הסבר→ניבוי→פיקוח.","mnemo":"🚦 לפני שדוחסים על הבלם (לשלוט), חייבים לראות את האור האדום מגיע מרחוק (לנבא). ניבוי קודם לשליטה."},{"id":"quiz11","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"שאלון נטיות התעסוקה של סטרונג הצליח לעזור: (לבני אדם לבחור תעסוקה מתאימה / לחוקרים לבחור את ההתנהגויות שיחקרו / לבני אדם להעריך את רמת התאמתם האישית לארגון / לחוקרים לחקור בעזרת הגישה הביולוגית)","a":"לבני אדם לבחור תעסוקה מתאימה (שאלון נטיות מסייע בהתאמת אישיות לתפקיד מתאים)","explain":"שאלון-נטיות-מקצועיות של סטרונג (1927) הוא כלי הערכה ותיק ומוכר בתחום הפסיכולוגיה התעסוקתית: הוא משווה את תשובות הנבחן לדפוסי-תשובות של אנשים <b>מצליחים ומרוצים</b> במקצועות שונים, ומזהה איזה תחום-עיסוק מתאים סטטיסטית לפרופיל-האישיות/העניינים של הנבחן. ⚠️ שימו לב להבחנה מהמסיח 'להעריך התאמה לארגון' - זה שונה: השאלון עוזר לבחור <b>איזה תחום/מקצוע</b> מתאים לאדם, לא <b>איזה ארגון ספציפי</b>.","mnemo":"💪 סטרונג = \"חזק/חוזק\" באנגלית - שאלון הכוח/ההתאמה שלך לתפקיד."},{"id":"quiz12","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"הפסיכולוגיה מנסה ל______ תהליכים מנטליים (לתאר בלבד / להסביר בלבד / לפקח בלבד / לנבא בלבד / כל התהליכים נכונים)","a":"כל התהליכים נכונים (הפסיכולוגיה שואפת גם לתאר, גם להסביר, גם לנבא, גם לפקח)","explain":"שאלה זו מדגישה שארבע המטרות (תיאור, הסבר, ניבוי, פיקוח) <b>אינן סותרות</b> ואינן בררה-אחת-מארבע - הפסיכולוגיה שואפת אליהן <b>כולן יחד</b>, גם ביחס לתהליכים מנטליים (לא רק להתנהגות נצפית). זה חוזר לרעיון-הליבה שכבר ראינו: ארבע המטרות הן שלבים מצטברים בתהליך מדעי אחד, לא ארבע אופציות-נפרדות שבוחרים אחת מהן.","mnemo":"🍕 שוב הפיצה השלמה - כל 4 הפרוסות (לתאר+להסביר+לנבא+לפקח) תמיד ביחד, אף פעם רק פרוסה אחת."},{"id":"quiz13","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"מי ייסד את המעבדה הראשונה שיוחדה לפסיכולוגיה ניסיונית? (מקס ורטהיימר / וילאם ג'יימס / וילהלם וונט / ג'ון גיואי)","a":"וילהלם וונט (ייסד את המעבדה הראשונה ב-1879, אבי הסטרוקטורליזם)","explain":"<b>וילהלם וונדט</b> ייסד ב-1879 בלייפציג, גרמניה, את המעבדה הראשונה בעולם שהוקדשה במיוחד למחקר פסיכולוגי-ניסיוני. אירוע זה נחשב באופן מוסכם כ'תאריך-הלידה' הרשמי של הפסיכולוגיה כמדע עצמאי, נפרד מהפילוסופיה שממנה צמחה. וונדט הוא גם אבי-הרעיון שהוביל בהמשך לסטרוקטורליזם (אם כי טיצ'נר, תלמידו, הוא זה שפיתח וייבא את הגישה לארה\"ב). ⚠️ אל תתבלבלו עם ג'ון דיואי (פונקציונליזם) או מקס ורטהיימר (גשטלט) - שני שמות אלו שייכים לגישות אחרות שנלמדו באותו פרק.","mnemo":"🥇 וונט = \"וא-ן-ד\" נשמע כמו \"ראשון\" (One באנגלית=וא(ן)). 1879, המעבדה הראשונה בהיסטוריה."},{"id":"quiz14","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"חוקרת מספרת לכם, כי מטרתה העיקרית היא להבין התנסויות מנטליות כצירוף של מרכיבים בסיסיים. סביר להניח שתמצאו את שורשיו ההיסטוריים של מחקרה ב: (הגישה האבולוציונית / פונקציונליזם / הגישה ההומניסטית / סטרוקטורליזם)","a":"סטרוקטורליזם (חקר מרכיבי היסוד של החוויה המנטלית)","explain":"'מרכיבים בסיסיים' של החוויה המנטלית = בדיוק המילים-מפתח של הסטרוקטורליזם. הגישה הזו (וונדט, טיצ'נר) שאלה 'ממה מורכבת חוויה מנטלית?' וניסתה לפרק אותה ליחידות-היסוד שלה (תחושות בסיסיות, רגשות פשוטים) - בדיוק כמו שכימאי מפרק תרכובת ליסודות. השיטה: אינטרוספקציה. ⚠️ הבדילו מפונקציונליזם (ששאל 'למה' התודעה קיימת, לא 'ממה' היא בנויה) - המילה 'צירוף של מרכיבים בסיסיים' היא הרמז המכריע כאן.","mnemo":"🧱 \"מרכיבים בסיסיים\" = מילת-קסם לסטרוקטורליזם (חשבו על בניין לגו שמפורק לקוביות)."},{"id":"quiz15","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"שני פרופסורים מאוניברסיטאות בבוסטון ובבומביי משתפים ביניהם פעולה במסגרת מיזם מחקר, שבו יקבעו כיצד הסטודנטים שלהם, בארצות-הברית ובהודו, מגיבים לאותן הבעיות. סביר להניח, כי ישתמשו במחקרם בגישה ה__________ (ביולוגית / הומניסטית / פסיכודינמית / חברתית-תרבותית)","a":"חברתית-תרבותית (השוואה בין תרבויות שונות - ארה\"ב מול הודו)","explain":"השוואה שיטתית בין תגובות של אנשים משתי תרבויות שונות (ארה\"ב והודו) לאותן בעיות בדיוק - זו בדיוק ההגדרה המעשית של מחקר בגישה <b>החברתית-תרבותית</b>. הגישה הזו מתמקדת בזיהוי הבדלים ודמיון בין-תרבותיים בהתנהגות ובתהליכים מנטליים, מתוך הנחה שהתרבות שבה גדלנו מעצבת חלק משמעותי ממי שאנחנו. ⚠️ שימו לב: המילה-המכרעת בשאלה היא 'שתי אוניברסיטאות משתי מדינות' - כל פעם שיש השוואה בין-תרבותית מפורשת, זה כמעט תמיד סימן לגישה החברתית-תרבותית.","mnemo":"🌍 בוסטון (ארה\"ב) + בומביי (הודו) = 2 דגלים שונים על המפה = חברתית-תרבותית."},{"id":"quiz16","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"הגישה ה __________ מושתתת על הדרכים, שבהן יכולות מנטליות אנושיות משרתות מטרות הסתגלות. (קוגניטיבית / חברתית-תרבותית / אבולוציונית / הומניסטית)","a":"אבולוציונית (מתמקדת בהסתגלות/שרידות של יכולות מנטליות)","explain":"הגישה <b>האבולוציונית</b> שואלת: איך יכולת מנטלית מסוימת (פחד, קנאה, משיכה מינית) עזרה לאבותינו הקדמונים <b>לשרוד ולהתרבות</b>? הכלי המרכזי הוא הברירה-הטבעית של דארווין, מיושמת לא רק על תכונות פיזיות אלא גם על תכונות פסיכולוגיות/מנטליות. ⚠️ אל תתבלבלו עם ביולוגית: ביולוגית שואלת 'מה קורה במוח/בגוף עכשיו' (המנגנון), בעוד אבולוציונית שואלת 'למה זה התפתח ככה מלכתחילה' (ההיסטוריה ההסתגלותית) - ההבדל הוא בין הווה למקור-רחוק.","mnemo":"🐒 דארווין+קוף על עץ מתפתח = אבולוציונית, תמיד על שרידה/הסתגלות."},{"id":"quiz17","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"בעת שהייתם מרותקים למיטה בעקבות שפעת, וצפיתם בטלוויזיה בסדרת בית משפט, לא התפלאתם לגלות פסיכולוג ________ מעיד במהלך המשפט. (משפטי / התפתחותי / חברתי / רפואי)","a":"משפטי (פסיכולוגיה משפטית עוסקת בהיבטים חוקיים/עדות בבתי משפט)","explain":"פסיכולוג <b>משפטי (forensic)</b> מיישם עקרונות פסיכולוגיים בהקשר משפטי: הערכת כשירות נאשמים לעמוד לדין, בדיקת מהימנות עדי-ראייה, ייעוץ לבתי-משפט, ולעיתים מתן עדות-מומחה בעצמו במהלך משפט. השאלה נותנת רמז ברור - 'עדות במהלך משפט' - שמכוון ישירות לתת-תחום הזה, בניגוד לפסיכולוגיה התפתחותית/חברתית/רפואית שלא קשורות ישירות להליך המשפטי.","mnemo":"⚖️👨‍⚖️ פטיש שופט + פסיכולוג ליד דוכן העדים = משפטי (המילה עצמה ברורה)."},{"id":"quiz18","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"איזה סוג של פסיכולוג יתמקד פחות ככל האפשר בהיבטים הגנטיים של הפסיכולוגיה האנושית? (פסיכולוג התפתחותי / פסיכולוג תעשייתי-ארגוני / פסיכולוג אישיותי / פסיכולוג ביולוגי)","a":"פסיכולוג תעשייתי-ארגוני (תחום יישומי-חברתי, לא מבוסס תורשה/גנטיקה)","explain":"שאלה זו דורשת חשיבה-שלילית: איזה סוג-פסיכולוג <b>הכי-פחות</b> מתעניין בגנטיקה? פסיכולוג <b>תעשייתי-ארגוני</b> עוסק ביישום עקרונות פסיכולוגיים במקום-העבודה (גיוס, מוטיבציה, ביצועים) - תחום יישומי-חברתי שכמעט ולא נשען על גורמים תורשתיים. לעומתו, שלושת האחרים (התפתחותי, אישיותי, ביולוגי) עוסקים <b>ישירות</b> בשאלות של תורשה כחלק מרכזי מהתחום עצמו - פסיכולוגיה התפתחותית שואלת כמה מהתפתחות הילד מולד וכמה נרכש, פסיכולוגיה אישיותית בוחנת מקורות תורשתיים לתכונות-אופי, וביולוגית עוסקת בגנטיקה ישירות.","mnemo":"🏢💼 תעשייתי-ארגוני = חליפה ועניבה במשרד - הכי רחוק מ-DNA/גנטיקה שאפשר."},{"id":"quiz19","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"איזה סוג שאלה סביר שפסיכולוג קוגנטיבי ישאל? (מדוע לילדים, לפעמים, חברים דמיוניים? / מדוע סטודנטים אחדים נופלים למשכב בכל פעם שהם עומדים לפני בחינות חשובות? / כיצד נוכל לעצב מקלדת למחשב, שתאפשר לאנשים להקליד יותר מהר? / כיצד מצליחים אנשים דו-לשוניים לעבור משפה לשפה?)","a":"כיצד מצליחים אנשים דו-לשוניים לעבור משפה לשפה? (שאלה על תהליך מנטלי-קוגניטיבי, לא רגשי/חברתי)","explain":"צריך לזהות איזו מבין ארבע השאלות-לדוגמה היא <b>קוגניטיבית מובהקת</b>, כלומר עוסקת בתהליך-מחשבה פנימי. 'חברים דמיוניים' נוגע יותר להתפתחות-רגשית/חברתית. 'נופלים למשכב לפני בחינות' נוגע ללחץ/חרדה (תחום קליני/פיזיולוגי). 'עיצוב מקלדת' הוא הנדסת-גורמי-אנוש, לא שאלה פסיכולוגית-תיאורטית. 'איך דו-לשוניים עוברים בין שפות' - זו שאלה על <b>מנגנון עיבוד-שפה פנימי</b>, שהוא בדיוק סוג התהליך המנטלי שהפסיכולוגיה הקוגניטיבית חוקרת (יחד עם זיכרון, קשב, פתרון-בעיות).","mnemo":"🗣️🔄 2 דגלי שפות מתחלפים בראש = תהליך מחשבתי = קוגניטיבי."},{"id":"quiz20","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"השורשים של הפסיכולוגיה נעוצים בעיקר ב: (דת / פילוסופיה / פיזיקה / פוליטיקה / סוציולוגיה)","a":"פילוסופיה (שאלות על תודעה/ידע - השורש ההיסטורי לפני שהפכה למדע)","explain":"השורשים ההיסטוריים של הפסיכולוגיה נעוצים ב<b>פילוסופיה</b>, לא בדת/פיזיקה/פוליטיקה/סוציולוגיה. פילוסופים יווניים כמו סוקרטס, אפלטון ואריסטו כבר שאלו שאלות יסוד על הנפש, התודעה, הידע והחופש-הרצוני - מאות שנים לפני שהפסיכולוגיה נפרדה והפכה למדע ניסיוני עצמאי במאה ה-19, עם ייסוד המעבדה של וונדט ב-1879. הפסיכולוגיה, במילים אחרות, 'ירשה' את השאלות מהפילוסופיה, אך פיתחה שיטת-מחקר אמפירית חדשה כדי לענות עליהן.","mnemo":"🏛️ פסל יווני חושב (\"החושב\" של רודן) = פילוסופיה, אבי כל השאלות על התודעה לפני שהיו מדע."},{"id":"quiz21","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"______ שייך לגישה הסטרוקטורליסטית (וויליאם ג'יימס / זיגמונד פרויד / צ'רלס דארווין / וויליאם וונדט / ג'ון ווטסון)","a":"וויליאם וונדט (מייסד הסטרוקטורליזם - חקר מרכיבי החוויה)","explain":"<b>וילהלם וונדט</b> הוא מייסד המעבדה הראשונה (1879) שממנה צמח, בהמשך, הסטרוקטורליזם - אך שימו לב: השיטתיות והפיתוח המלא של הגישה עצמה יוחסו יותר לתלמידו אדוארד טיצ'נר, שהביא את הרעיונות מאירופה לארה\"ב. ⚠️ בין המסיחים: ג'יימס=פונקציונליזם, פרויד=פסיכודינמית, דארווין=אבולוציונית (בהשראתו), ווטסון=ביהביוריזם - כל שם שייך לגישה שונה לגמרי, לכן חשוב לזכור את הזיווג המדויק.","mnemo":"🥇🧱 וונט (הראשון) = לגו (סטרוקטורליזם) - אותו אדם, אותה תמונה."},{"id":"quiz22","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"אם את/ה \"מתבונן/נת בעצמך\" בכדי לענות על השאלה, אז את/ה מבצע (שליטה עצמית פנימית / הגיון פנימי / פסיכואנליזה / אינטרוספקציה / מימוש עצמי)","a":"אינטרוספקציה (התבוננות פנימית בחוויה המנטלית של עצמך)","explain":"<b>אינטרוספקציה</b> (introspection, מילולית 'הבטה-פנימה') היא שיטת-המחקר המזוהה עם הסטרוקטורליזם: הנבדק מתבונן בתהליכים המנטליים הפנימיים שלו ברגע-ההתרחשות, ומדווח עליהם במילים לחוקר. השיטה ננטשה בהמשך בשל בעיית-אמינות מהותית - שני אנשים חווים גירוי זהה אך מדווחים עליו אחרת לגמרי, ואין דרך אובייקטיבית לבדוק מי 'צודק' יותר. ⚠️ אל תתבלבלו עם 'פסיכואנליזה' (שיטה טיפולית של פרויד) או 'מימוש עצמי' (מושג הומניסטי) - שתי אלו מסיחים מכוונים.","mnemo":"🪞 אינטרו=\"פנימה\" (כמו אינטרנט=בין, אינטרוברט=פנימה). אינטרוספקציה=מבט פנימה אל עצמך."},{"id":"quiz23","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"אחד היישומים החשובים של הפונקציונליזם בא לידי ביטוי בתחום ה______ (חינוך / פוליטיקה / מודעות סביבתית / מערכת המשפט / בריאות)","a":"חינוך (פונקציונליזם התמקד ביישומים מעשיים כמו חינוך)","explain":"היישום המרכזי של הפונקציונליזם היה בתחום ה<b>חינוך</b>. מכיוון שהגישה התעניינה ב'למה' תהליכים מנטליים עוזרים לאדם להסתגל לסביבתו, זה הוביל באופן טבעי לשאלה מעשית ביותר: איך תלמידים לומדים בצורה הטובה ביותר, ואיך אפשר לעצב את מערכת-החינוך כדי לתמוך בכך? ג'ון דיואי (מוצג בספר כאבי-הפונקציונליזם האמריקאי) השפיע ישירות על פדגוגיה מתקדמת - 'למידה מתוך עשייה' - שעדיין משפיעה על שיטות-הוראה כיום.","mnemo":"🎓🔧 פונקציונליזם=כלי מעשי (בשביל מה זה טוב) → הכלי המעשי ביותר בחיים=בית ספר=חינוך."},{"id":"quiz24","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"אדם האומר כי \"השלם הוא יותר מסכום חלקיו\" מבטא את הרעיון המרכזי ב______ (גישת הגשטאלט / סטרוקטורליזם / ביהביוריזם / פונקציונליזם / פסיכודינאמית)","a":"גישת הגשטאלט (העיקרון המרכזי: התפיסה כוללת יותר מסכום החלקים)","explain":"⚠️ המשפט 'השלם הוא יותר מסכום חלקיו' הוא <b>הניסוח-הקלאסי המילולי</b> של עקרון-היסוד בגישת <b>הגשטלט</b> (Gestalt, גרמנית: 'צורה/תבנית'). הרעיון: כאשר אנו תופסים סצנה או חפץ, אנחנו לא קולטים אותו כאוסף-חלקים נפרדים שאחר-כך 'מתחברים' - אנחנו קולטים ישר תבנית שלמה, הוליסטית, שיש בה משהו יותר מסך-כל-החלקים המרכיבים אותה (למשל, מנגינה נשארת 'אותה מנגינה' גם כשמנגנים אותה בטונציה אחרת, למרות שכל התווים שונים). ⚠️ אל תתבלבלו עם סטרוקטורליזם, שדווקא עשה את ההפך - ניסה לפרק חוויה ליחידות-קטנות. הגשטלט הוא בדיוק המרד-הנגדי לרעיון הזה.","mnemo":"🧩➕1 פאזל עם חלק אחד נוסף מוסתר: השלם (התמונה המורכבת) תמיד > סכום החלקים הבודדים. זו ההגדרה של גשטלט מילה במילה."},{"id":"quiz25","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"כל הפסיכולוגים הבאים קשורים לגישה ההתנהגותית (ביהביוריסטית) פרט ל_____ (אדלר / סקינר / ווטסון / תורנדייק)","a":"אדלר (אדלר שייך לפסיכודינמית/ניאו-פרוידיאנית, לא ההתנהגותית)","explain":"שלושת השמות הראשונים (סקינר, ווטסון, תורנדייק) הם ביהביוריסטים מרכזיים שהתמקדו אך ורק בהתנהגות-נצפית ובגירויים-סביבתיים, ודחו מחקר של 'תודעה' כבלתי-מדעי. <b>אדלר</b> שונה לחלוטין: הוא היה תלמידו-לשעבר של פרויד, ומייסד הפסיכולוגיה-האינדיבידואלית (ענף בתוך הגישה הפסיכודינמית/ניאו-פרוידיאנית). אדלר התמקד במניעים לא-מודעים, בתחושת-נחיתות ובשאיפה-לעליונות - בדיוק ההפך מהגישה ההתנהגותית שמסתפקת בגירוי-תגובה נצפים.","mnemo":"🍎🍐 3 תפוחים ואגס אחד: סקינר, ווטסון, תורנדייק = תפוחים (ביהביוריזם). אדלר = האגס החריג (פסיכודינמי)."},{"id":"quiz26","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"הקליניקה של ד\"ר אושר מתמקדת בטיפול ממוקד קליינט (client-centered therapy), כלומר בכזה המדגיש את הכוחות ויכולת הצמיחה של המטופל. סביר מכאן כי ד\"ר אושר מסכים עם הגישה ה: (הגישה הפסיכודינמית / הגישה הקוגניטבית / הגישה ההתנהגותית / הגישה ההומניסטית)","a":"הגישה ההומניסטית (מדגישה כוחות/צמיחה של האדם, כמו רוג'רס)","explain":"טיפול-ממוקד-לקוח (client-centered therapy) הוא שיטת-הטיפול שפיתח <b>קרל רוג'רס</b> - נציג מרכזי של הגישה <b>ההומניסטית</b>. המונח עצמו ('לקוח', לא 'חולה') כבר מרמז על הפילוסופיה: המטופל אינו 'פגום' שצריך לתקן, אלא אדם עם כוחות-צמיחה טבעיים שהמטפל רק מסייע לשחרר. זה מנוגד לגישה הפסיכודינמית (שרואה את האדם נשלט בעיקרו על-ידי דחפים לא-מודעים שצריך לחשוף) ולגישה ההתנהגותית (שרואה את ההתנהגות כתוצר של חיזוקים חיצוניים, לא כוחות פנימיים).","mnemo":"🌱 שוב הגנן (רוג'רס) = טיפול ממוקד-קליינט = הומניסטית."},{"id":"prof2_01","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תארו את השלב הראשון בעריכת מחקר.","a":"השלב הראשון הוא תצפית ראשונית או הצגת שאלה. השאלה נובעת מתצפית ישירה או מסוגיה קלאסית, וחוקר יצירתי מגלה אמת חדשה, לעיתים בחיבור בין רעיונות ישנים.","explain":"השלב הראשון בתהליך המחקר הוא <b>הצגת השאלה</b>, המבוססת על <b>תצפית ראשונית</b>. תהליך המחקר מתחיל כאשר תצפיות, אמונות, מידע או ידע כללי מעוררים בחוקר רצון להציע רעיון חדש או לחשוב על תופעה בדרך שונה מהמקובל. מקור השאלות: לעיתים <b>תצפית ישירה</b> באירועים, בבני אדם או בבעלי חיים; לעיתים <b>סוגיות קלאסיות</b> — \"שאלות חשובות שאין עליהן תשובה\" העוברות מדור חוקרים למשנהו. חוקר יצירתי הוא מי שמגלה <b>אמת חדשה</b>, לעיתים קרובות על־ידי חיבור בין רעיונות ישנים בדרך ייחודית.","mnemo":"👀 שלב 1 = \"רואה\" - תצפית/שאלה ראשונית. 🔄 מעגל המדען: 1)רואה→2)מנחש→3)בודק→4)מבין→5)מספר לעולם→6)שואל מה עוד→7)ממשיך (וחוזר ל-1)."},{"id":"prof2_02","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהם \"תיאוריה\" ו\"דטרמיניזם\"? עמדו על הקשר בין שניהם.","a":"תיאוריה = מערכת מאורגנת של מושגים המסבירה תופעה. דטרמיניזם = ההנחה שכל האירועים נובעים מגורמים סיבתיים ספציפיים. הקשר: הדטרמיניזם הוא הנחת היסוד של רוב התיאוריות — בלעדיו אין טעם לחפש הסברים סיבתיים קבועים.","explain":"<b>תיאוריה</b> — מערכת מאורגנת של מושגים, המסבירה תופעה או קבוצה של תופעות, ומספקת את ההקשר לניסוח שאלות מחקר. <b>דטרמיניזם</b> — ההנחה שכל האירועים (פיזיים, מנטליים והתנהגותיים) הם תוצאה של גורמים סיבתיים ספציפיים, המוגבלים לסביבת היחיד או לתוכו. <b>הקשר ביניהם:</b> דטרמיניזם הוא הנחת היסוד העומדת בבסיס רוב התיאוריות הפסיכולוגיות. חוקרים מניחים כי תהליכים מנטליים והתנהגותיים פועלים על־פי דפוסים בעלי חוקים, הניתנים לגילוי במחקר — ותיאוריות פסיכולוגיות הן, על־פי־רוב, טענות בדבר הגורמים הסיבתיים העומדים בבסיס דפוסים סדורים אלה. ללא הנחת הדטרמיניזם, לא היה טעם לחפש הסברים תיאורטיים.","mnemo":"🎯 תיאוריה = מפה שלמה של איזור. דטרמיניזם = ההנחה שיש כביש (סיבה) שהוביל לכל מקום במפה - בלי כבישים, המפה חסרת טעם."},{"id":"prof2_03","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תארו את השלב השני בעריכת המחקר.","a":"השלב השני הוא ניסוח השערה — טענה זמנית וניתנת לבחינה, בצורת \"אם—אז\", המקשרת גורמים לתוצאות. על המחקר לאשש או להפריך אותה.","explain":"השלב השני בתהליך המחקר הוא <b>ניסוח השערה</b>. השערה היא <b>טענה זמנית, הניתנת לבחינה</b>, המקשרת בין גורמים לבין תוצאות. השערות מנוסחות, לרוב, בצורת ניבוי \"<b>אם — אז</b>\", ומפרטות אילו תוצאות ספציפיות יתקבלו בתנאים מסוימים. דוגמה מהספר: \"אם ילדים יצפו בתכניות טלוויזיה שהמסרים שלהן אלימים ביותר, אז יהיו מעורבים במעשי תוקפנות רבים יותר כלפי חבריהם.\" על המחקר לאשש (או להפריך) את הקשר \"אם — אז\" הזה.","mnemo":"🤔 שלב 2 = \"מנחש\" - השערה היא ניחוש חכם בצורת אם-אז. 🔄 מעגל המדען: 1)רואה→2)מנחש→3)בודק→4)מבין→5)מספר לעולם→6)שואל מה עוד→7)ממשיך (וחוזר ל-1)."},{"id":"prof2_04","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד ההשערה או ההשערות במחקר קשורות לתיאוריה של המחקר?","a":"התיאוריה מולידה את ההשערה — ההשערה היא טענה זמנית וניתנת לבחינה, הנגזרת מהתיאוריה הרחבה. הקשר דו־כיווני: אם הנתונים לא תומכים בהשערה, יש לחשוב מחדש על התיאוריה עצמה.","explain":"ההשערה נגזרת מהתיאוריה: כאשר מציעים תיאוריה בפסיכולוגיה, מצפים שתסביר עובדות ידועות אך גם תציג השערות חדשות. ההשערה היא טענה זמנית וניתנת לבחינה, המנוסחת בצורת \"אם — אז\", והיא הדרך המעשית והממוקדת לבחון אם התיאוריה הרחבה נכונה. הקשר הוא דו־כיווני: אם הנתונים אינם תומכים בהשערה באופן מלא, על החוקרים לחשוב מחדש על היבטים מסוימים בתיאוריה עצמה — כלומר יש אינטראקציה מתמדת בין התיאוריה לבין המחקר: התיאוריה מולידה השערות הניתנות למבחן, ותוצאות המבחן עשויות לחייב תיקון של התיאוריה.","mnemo":"🌳 תיאוריה = העץ (הרעיון הגדול). השערה = ענף בודד שבודקים אם הוא חזק. אם הענף נשבר (לא מאושש), בודקים את העץ כולו מחדש."},{"id":"prof2_05","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תארו את השלבים, החל בשלב השלישי וכלה בשלב השביעי של עריכת המחקר.","a":"שלב 3 — תכנון המחקר (שיטה מדעית לצמצום טעויות). שלב 4 — ניתוח תוצאות והסקת מסקנות. שלב 5 — דיווח/פרסום (עם תיעוד מלא, ללא חשאיות). שלב 6 — שאלות פתוחות (מה עוד לא הוסבר). שלב 7 — המשך העבודה, פתיחת מחזור מחקר חדש.","explain":"<b>שלב 3 (תכנון המחקר):</b> החוקרים נשענים על השיטה המדעית — סדרה כללית של נהלים לאיסוף ראיות ולפירושן, שנועדו לצמצם מקורות טעויות ולהניב מסקנות מוצקות. <b>שלב 4 (ניתוח התוצאות והסקת מסקנות):</b> החוקרים מנתחים את הנתונים שנאספו ומגיעים למסקנות. <b>שלב 5 (דיווח על הממצאים):</b> אם למסקנות יש השפעה על התחום, מגישים את העבודה לפרסום בכתב־עת מדעי — בתנאי שנשמר תיעוד מלא, כדי שחוקרים אחרים יוכלו לבדוק, לשחזר או להפריך את הממצאים; אין מקום לחשאיות בתהליך המחקר. <b>שלב 6 (שאלות פתוחות):</b> הקהילה המדעית מזהה שאלות שנותרו בלא מענה, לרוב בפרק הדיון של המאמר; אם הנתונים אינם תומכים בהשערה במלואה, יש לחשוב מחדש על התיאוריה. <b>שלב 7 (המשך העבודה):</b> החוקרים המקוריים או עמיתיהם עשויים לעבוד על השאלות הפתוחות ולפתוח מחזור מחקר חדש — יש אינטראקציה מתמדת בין התיאוריה למחקר.","mnemo":"🔄 מעגל המדען: 1)רואה→2)מנחש→3)בודק→4)מבין→5)מספר לעולם→6)שואל מה עוד→7)ממשיך (וחוזר ל-1). שלבים 3-7: בודק(תכנון)→מבין(ניתוח)→מספר(דיווח)→שואל(פתוחות)→ממשיך."},{"id":"prof2_06","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"בחרו דוגמה מקורית (שונה מזו שבספר) ויישמו אותה על 7 שלבי תהליך המחקר.","a":"דוגמה — מוזיקה בזמן למידה: (1) תצפית: סטודנטים מדווחים שהם מתרכזים טוב יותר עם מוזיקה. (2) השערה: מוזיקה אינסטרומנטלית תשפר זיכרון. (3) תכנון: חלוקה אקראית לשתי קבוצות + מבחן זיכרון. (4) ניתוח: השוואת ציונים. (5) דיווח: פרסום בכתב־עת. (6) שאלות פתוחות: תלוי בסוג המוזיקה? (7) המשך: מחקר חדש.","explain":"דוגמה: מוזיקה בזמן למידה. שלב 1 (תצפית ראשונית או שאלה): מרצה שם לב כי סטודנטים המאזינים למוזיקה בזמן הלמידה מדווחים לעיתים קרובות כי הם מתרכזים טוב יותר. שלב 2 (ניסוח השערה): אם סטודנטים ילמדו תוך כדי האזנה למוזיקה אינסטרומנטלית שקטה, אז הם יזכרו יותר פרטים ממבחן על החומר, בהשוואה ללמידה בשקט מוחלט. שלב 3 (תכנון המחקר): מחלקים באקראי קבוצת סטודנטים לשתיים — קבוצה הלומדת פרק טקסט תוך כדי מוזיקה אינסטרומנטלית, וקבוצה הלומדת אותו הפרק בשקט; לאחר מכן שתי הקבוצות עורכות אותו מבחן זיכרון. שלב 4 (ניתוח התוצאות והסקת מסקנות): משווים את הציונים הממוצעים בין שתי הקבוצות ובודקים אם ההבדל משמעותי סטטיסטית. שלב 5 (דיווח על הממצאים): אם התוצאות מעניינות, המחקר מוגש לפרסום בכתב־עת פסיכולוגי, עם תיעוד מלא של השיטה כדי שניתן יהיה לשחזרו. שלב 6 (שאלות פתוחות): נשאלת השאלה — האם התוצאה תלויה בסוג המוזיקה (עם מילים לעומת בלי), או בסוג המשימה הנלמדת? שלב 7 (המשך העבודה): חוקרים נוספים עשויים לבחון משתנים אלה במחקר חדש. (דוגמה מקורית של הסטודנט — לא מהספר; המסגרת של 7 השלבים בלבד מהספר.)","mnemo":"🔄 מעגל המדען: 1)רואה→2)מנחש→3)בודק→4)מבין→5)מספר לעולם→6)שואל מה עוד→7)ממשיך (וחוזר ל-1). (דוגמת המוזיקה עוברת בדיוק את אותו המעגל)"},{"id":"prof2_07","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי הטיית הצופה? הציגו דוגמה.","a":"טעות הנובעת ממניעים וציפיות אישיות של הצופה — רואים את מה שמצפים לראות, לא בהכרח את המציאות. דוגמה: עיתונאים שצפו באותו נאום (מונסטרברג) נתנו תיאורים סותרים לחלוטין.","explain":"הטיית הצופה (observer bias) היא טעות הנובעת ממניעיו האישיים של הצופה ומציפיותיו — אנשים רואים ושומעים לעיתים קרובות את מה שהם מצפים לראות ולשמוע, ולא בהכרח את מה שקורה במציאות. הטיות פועלות כמסננים: חלק מהדברים הנצפים נתפסים כרלוונטיים ובעלי משמעות, וחלקם נדחים כלא רלוונטיים. דוגמה מהספר: הפסיכולוג הוגו מונסטרברג נשא נאום על שלום בפני קהל שכלל עיתונאים רבים. דיווחיהם על אותו האירוע היו סותרים לחלוטין — אחד כתב שהקהל קיבל את הנאום בשקט מוחלט מרוב הפתעה, אחר כתב שמחיאות כפיים קטעו את הנאום לאורך זמן; אחד ציין שהמרצה חייך בלא הרף, אחר ציין שפניו היו רציניות ללא צל של חיוך. כל העיתונאים צפו באותו האירוע ממש, אך תיארו אותו באופן שונה לחלוטין בהתאם לציפיותיהם.","mnemo":"👓 הטיית הצופה = משקפיים צבעוניות שאתה לא יודע שאתה חובש - רואה את מה שאתה מצפה לראות, לא את המציאות."},{"id":"prof2_08","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"חשבו על הסיבות ועל התנאים שבהם יכולה להיווצר הטיית הצופה.","a":"נוצרת כאשר: (1) לצופה ציפיות מוקדמות, (2) יש לו מניעים אישיים כלפי הנושא, (3) אין הגדרה מדויקת מראש של מה יש לתעד, (4) התיעוד נסמך על זיכרון מאוחר ולא רישום בזמן אמת.","explain":"הטיית הצופה עלולה להיווצר במספר תנאים: (1) כאשר לצופה יש ציפיות מוקדמות או תיאוריה קודמת לגבי מה שאמור לקרות. (2) כאשר לצופה יש מניעים אישיים או עמדה רגשית/פוליטית כלפי הנושא הנצפה. (3) כאשר אין הגדרה ברורה ומדויקת מראש של מה בדיוק יש לתעד — כך שכל צופה \"ממלא את החסר\" לפי הבנתו. (4) כאשר הצפייה אינה מתועדת באופן שיטתי בזמן אמת, אלא מסתמכת על זיכרון מאוחר יותר, הרגיש יותר לעיוותים. (רשימה זו היא הסקה של הסטודנט מהעקרונות שבספר, לא ציטוט מילולי.)","mnemo":"👓 המשקפיים הצבעוניות (הטיית הצופה) מתחזקות כש: יש לך ציפייה, יש לך אינטרס אישי, אין כללים ברורים מראש, ואתה כותב מהזיכרון (לא בזמן אמת)."},{"id":"prof2_09","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו משתנה?","a":"משתנה הוא כל גורם שחל שינוי בכמותו או באיכותו — כל דבר שניתן למדוד ושמקבל ערכים שונים (גובה, משקל, חרדה, אינטליגנציה).","explain":"משתנה (variable) הוא כל גורם שחל שינוי בכמותו או באיכותו — כל דבר שאנו מודדים ויכול לקבל ערכים שונים. לדוגמה, \"מקום לידה\" הוא משתנה, וערכיו האפשריים הם ישראל, מרוקו, גרמניה וכו'. יש הבחנה בין משתנה שערכיו נתונים מראש (כמו מקום לידה), לבין משתנה שאת ערכיו החוקר יוצר בעצמו (למשל, סוג התרופה שניתנת לכל קבוצת חולים בניסוי). כל מדידה פיזיולוגית (גובה, משקל, לחץ דם) וכל מדידה של תופעה פסיכולוגית (חרדה, אינטליגנציה, הישגיות) היא משתנה.","mnemo":"📏 משתנה = כל דבר שיש לו סרגל - אפשר למדוד אותו ולקבל מספרים/ערכים שונים."},{"id":"prof2_10","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו משתנה תלוי?","a":"המשתנה התלוי הוא משתנה התוצאה — מה שהנסיין מודד. ערכיו תלויים בערכי המשתנה הבלתי־תלוי (למשל: ביצוע במבחן זיכרון).","explain":"המשתנה התלוי (dependent variable) הוא משתנה התוצאה בקשר של סיבה־תוצאה — זהו מה שהנסיין מודד. אם השערת החוקר נכונה, הערכים של המשתנה התלוי יהיו תלויים בערכים של המשתנה הבלתי־תלוי. בדוגמת הקפאין מהספר: המשתנה הבלתי־תלוי הוא סוג הקפה (עם קפאין / נטול קפאין) שהחוקרים הפעילו על המשתתפים; המשתנה התלוי הוא הביצוע במבחן זיכרון (מספר התשובות הנכונות) — זה מה שנמדד כדי לבדוק את השפעת הקפאין.","mnemo":"🎯 תלוי = \"התוצאה תלויה בך\" - זה מה שאתה מודד בסוף, זה ה\"יעד\" של הניסוי."},{"id":"prof2_11","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו משתנה בלתי תלוי?","a":"הגורם שהחוקר מפעיל/משנה בכוונה — המשתנה המשמש כסיבה. קביעתו נקראת \"מניפולציה\" (למשל: סוג הקפה שניתן למשתתפים).","explain":"המשתנה הבלתי־תלוי (independent variable) הוא הגורם שהחוקר מפעיל בקשר שבין שני המשתנים — המשתנה המשמש כסיבה. ההליך של קביעת ערך המשתנה והפעלתו נקרא \"מניפולציה\". אם טענות החוקר על סיבה ותוצאה נכונות, המשתנה הבלתי־תלוי הוא זה שגורם לשינוי בערכי המשתנה התלוי. בדוגמת הקפאין מהספר: המשתנה הבלתי־תלוי הוא סוג הקפה (עם קפאין / נטול קפאין) שהחוקרים בחרו לתת לכל קבוצת משתתפים.","mnemo":"🎮 בלתי-תלוי = \"היד על הג'ויסטיק\" - זה מה שהחוקר עצמו שולט ומשנה בכוונה (הסיבה)."},{"id":"prof2_12","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הציעו דוגמה של מחקר וציינו את המשתנה הבלתי־תלוי והמשתנה התלוי בו.","a":"דוגמה: השפעת שעות שינה על ריכוז. משתנה בלתי־תלוי = מספר שעות השינה (4 מול 8). משתנה תלוי = הציון במבחן ריכוז.","explain":"דוגמה: מחקר הבודק את השפעת שעות השינה על ריכוז בלימודים. משתנה בלתי־תלוי: מספר שעות השינה שהחוקר קובע לכל קבוצת משתתפים (למשל, קבוצה אחת ישנה 4 שעות, קבוצה שנייה 8 שעות — זהו הגורם שהחוקר מפעיל). משתנה תלוי: הציון שמקבלים המשתתפים במבחן ריכוז (למשל, מספר משימות שהושלמו נכון בזמן נתון) — זהו מה שהחוקר מודד כדי לבדוק אם השינוי במשתנה הבלתי־תלוי (שעות שינה) משפיע על התוצאה. (דוגמה מקורית של הסטודנט; ההגדרות עצמן מהספר.)","mnemo":"😴 \"שינה קובעת ריכוז\": היד על הג'ויסטיק=שעות שינה (4/8). התוצאה שנמדדת=ציון ריכוז."},{"id":"prof2_13","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"נסחו הגדרות אופרציונליות למשתנה הבלתי־תלוי ולמשתנה התלוי במחקר שהצעתם.","a":"משתנה בלתי־תלוי (שעות שינה): מספר שעות שינה רצופות שנמדדו במכשיר, ב-2 קבוצות. משתנה תלוי (ריכוז): מספר משימות נכונות במבחן ריכוז סטנדרטי, תחת תנאים זהים.","explain":"הגדרה אופרציונלית היא הגדרה הכוללת את כל הפעולות או התהליכים הספציפיים שבהם משתמשים כדי למדוד את המושג. במחקר שהוצע (השפעת שעות שינה על ריכוז): משתנה בלתי־תלוי — \"שעות שינה\" מוגדר אופרציונלית כמספר השעות הרצופות שהמשתתף ישן בלילה שקדם למבחן, כפי שנרשם על־ידי מכשיר מדידת שינה, עם שתי קבוצות: \"שינה קצרה\" (4 שעות) ו\"שינה מלאה\" (8 שעות). משתנה תלוי — \"ריכוז\" מוגדר אופרציונלית כמספר המשימות הנכונות שהמשתתף משלים במבחן ריכוז סטנדרטי בן 10 דקות, הנערך תחת אותם תנאי חדר וזמן לכל המשתתפים.","mnemo":"📐 הגדרה אופרציונלית = \"איך בדיוק מודדים את זה במספרים\" - לא \"שינה\" באופן כללי, אלא \"שעות רצופות במכשיר\"."},{"id":"prof2_14","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"נסחו דרכים להבטיח סטנדרטיזציה במחקר — הן בתנאי המחקר והן בתהליך עריכתו.","a":"סטנדרטיזציה = הליכים אחידים בכל שלבי איסוף הנתונים. בתנאי המחקר: הצגת שאלות/סיטואציה זהה לכולם. בתהליך: ניקוד לפי כללים קבועים + תיעוד תוצאות.","explain":"סטנדרטיזציה (standardization) היא השימוש בהליכים אחידים ועקביים בכל שלבי איסוף הנתונים במחקר. יש להשיג סטנדרטיזציה בשני תחומים עיקריים: (1) תנאי המחקר — כל האפיונים של הסיטואציה הניסויית (למשל, אופן הצגת השאלות) חייבים להיות זהים לכל המשתתפים, כדי שכולם יחוו אותם מצבי ניסוי בדיוק. (2) תהליך עריכת המחקר — ניקוד התשובות (scoring) חייב להתבצע לפי כללים אחידים שנקבעו מראש, וגם התצפיות עצמן חייבות לעבור סטנדרטיזציה. הדפסה או הקלטה של התוצאות מסייעות להבטיח שניתן יהיה להשוות אותן לתוצאות שיתקבלו במועדים אחרים, עם משתתפים וחוקרים שונים — כך מצמצמים את הטיית הצופה ומגבירים את מהימנות המחקר.","mnemo":"🏭 סטנדרטיזציה = פס-ייצור במפעל: לכל משתתף בדיוק אותו התהליך, בלי יוצא מן הכלל."},{"id":"prof2_15","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו כיצד סטנדרטיזציה ואופרציונליזציה יכולות לשפר את האובייקטיביות במחקר שהצעתם.","a":"סטנדרטיזציה — כל המשתתפים עוברים אותו הליך, כך שהבדלים לא נובעים מתנאים שונים. אופרציונליזציה — הופכת מושג מעורפל למדידה ברורה, כך ששני חוקרים יגיעו לאותה תוצאה.","explain":"במחקר שהוצע, הסטנדרטיזציה משפרת את האובייקטיביות משום שכל המשתתפים בקבוצת \"שינה קצרה\" יעברו בדיוק את אותו הליך (אותה שעת התחלה ואותה שעת סיום שינה, אותו חדר מבחן, אותה הצגת הוראות), כך שלא ניתן יהיה לייחס הבדלים בתוצאות לתנאים חיצוניים שהשתנו בין המשתתפים. האופרציונליזציה משפרת את האובייקטיביות משום שהיא הופכת מושג מעורפל כמו \"ריכוז\" למדידה ברורה, קבועה ובלתי תלויה בפרשנות אישית של החוקר — כל בודק, בכל מקום, יידע בדיוק כיצד לספור \"תשובה נכונה\" במבחן, ולכן שני חוקרים בלתי תלויים המודדים את אותם המשתתפים יגיעו לאותה התוצאה, מה שמפחית את הסיכוי להטיית הצופה.","mnemo":"🔗 סטנדרטיזציה (פס-הייצור) + הגדרה אופרציונלית (מדידה מדויקת) = כל חוקר אחר יגיע לאותה התוצאה."},{"id":"prof2_16","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הערכת הצעות להגדרה אופרציונלית של \"רמת תוקפנות\" — אילו טובות ואילו לא?","a":"טובות (מדידה קונקרטית): מספר צעקות בשעה, עוצמת מכה מדודה במכשיר, ציון בשאלון. לא טובות (עדיין מופשטות): \"מידת האלימות\" ו\"מידת העצבנות\" — לא מפרטות כיצד נמדד המושג בפועל.","explain":"הערכת חמש ההצעות להגדרה אופרציונלית של \"רמת תוקפנות\": (א) \"מידת האלימות שהפגין האדם בשעה\" — אינה הגדרה אופרציונלית טובה; \"מידת האלימות\" נשאר מושג מופשט ולא מוגדר, ללא ציון כיצד בדיוק היא נמדדת. (ב) \"מספר הצעקות שהנבדק השמיע בשעה\" — הגדרה אופרציונלית טובה: פעולה ספציפית, נצפית וניתנת לספירה מדויקת. (ג) \"עוצמת המכה שהנבדק נתן לשק אגרוף\" — הגדרה אופרציונלית טובה, בתנאי שמצוין כלי מדידה מוגדר (למשל חיישן). (ד) \"מידת העצבנות של האדם רבע שעה אחרי שחווה תסכול\" — אינה טובה: \"מידת העצבנות\" מופשט בדיוק כמו \"רמת תוקפנות\" עצמה, ולא מתורגם לפעולה נמדדת. (ה) \"ציון בשאלון המיועד למדוד תוקפנות\" — הגדרה אופרציונלית טובה: כלי מדידה קונקרטי המניב ציון אחיד וניתן להשוואה. מסקנה: הגדרה אופרציונלית טובה חייבת לפרט פעולה או תהליך מדידה קונקרטי — לא רק לחזור על המושג המופשט במילים אחרות. (ניתוח של הסטודנט על סמך העקרונות שבספר.)","mnemo":"📏 טובה=יש לה סרגל (מספר צעקות, עוצמת מכה). רעה=אין לה סרגל (\"מידת האלימות\" - מופשט מדי, אין יחידת מדידה)."},{"id":"prof2_17","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי המטרה של שיטת הניסוי?","a":"לטעון טענה סיבתית מוצקה על השפעת משתנה בלתי־תלוי (שהחוקר מפעיל) על משתנה תלוי (שהחוקר מודד) — ולהתגבר על עמימות ההסברים היום־יומיים.","explain":"מטרת שיטת הניסוי היא לטעון טענה סיבתית מוצקה בדבר השפעתו של משתנה בלתי־תלוי על משתנה תלוי. החוקרים מפעילים (עושים מניפולציה על) המשתנה הבלתי־תלוי, ובודקים את השפעתו על המשתנה התלוי. מטרת השיטה היא להתגבר על העמימות הקיימת בהסברים יום־יומיים — שבהם אפשר להציע מגוון סיבות לאותה תוצאה — ולהגיע למסקנה מדויקת ומבוססת על קשר סיבה־תוצאה.","mnemo":"⚖️ שיטת הניסוי = בית משפט שבודק \"מי אשם\" (סיבה) - לא רק \"מי היה שם\" (קורלציה)."},{"id":"prof2_18","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד יכולים הסברים חלופיים לפגוע ביכולת להסיק על סיבה ותוצאה בניסוי?","a":"ככל שיש יותר הסברים חלופיים, כך פוחת הביטחון בהשערה. אם גורם נוסף (משתנה מתערב) משנה את התנהגות המשתתף, אי אפשר לדעת מה גרם באמת לתוצאה.","explain":"ככל שמספר ההסברים החלופיים לתוצאה גדל, כך פוחת הביטחון שההשערה הראשונית מדויקת. הבעיה מתעוררת כאשר גורם נוסף, שאינו חלק ממה שהנסיין הכניס במכוון למערך המחקר, משנה את התנהגות המשתתף ומוסיף בלבול לפרשנות הנתונים (משתנה מתערב) — במקרה כזה החוקר לא יכול לקבוע בוודאות האם התוצאה נובעת מהמשתנה הבלתי־תלוי או מהגורם הנוסף. דוגמה מהספר: אם סצנות אלימות בטלוויזיה קולניות יותר ומכילות יותר תנועה מסצנות לא אלימות, אי אפשר לדעת אם התוקפנות שנצפתה נובעת מהאלימות עצמה, או מהקול והתנועה שהתערבו בה.","mnemo":"🎩 כל הסבר חלופי = קוסם נוסף שמסביר את הטריק אחרת. ככל שיש יותר קוסמים מתחרים, פחות בטוחים מי צדק."},{"id":"prof2_19","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו משתנה מתערב וכיצד הוא קשור להסבר החלופי?","a":"גורם שלא הוכנס במכוון למחקר אך משנה את התנהגות המשתתף ומבלבל את פרשנות הנתונים. הוא יוצר הסבר חלופי: אי אפשר לדעת אם התוצאה נובעת מהמשתנה הבלתי־תלוי או מהמשתנה המתערב.","explain":"משתנה מתערב הוא גורם שאינו חלק ממה שהנסיין הכניס במכוון למערך המחקר, אך משנה את התנהגות המשתתף ומוסיף בלבול לפרשנות הנתונים. הוא קשור ישירות להסבר החלופי: כאשר משתנה מתערב קיים, נוצר הסבר חלופי אפשרי לתוצאות — הקושר אותן לא למשתנה הבלתי־תלוי שהחוקר בדק, אלא לגורם הנוסף שהתערב. דוגמה מהספר: אלימות בטלוויזיה מלווה לרוב בקול חזק ותנועה רבה — לכן אי אפשר לדעת אם התוקפנות שנצפתה נובעת מהאלימות עצמה, או מהקול והתנועה (המשתנים המתערבים).","mnemo":"🚪 משתנה מתערב = אורח לא-קרוא שנכנס למסיבה בלי הזמנה ומבלבל את כל התמונה."},{"id":"prof2_20","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו כיצד אפקט הציפייה ואפקט הפלסבו יכולים להשפיע על תוצאות המחקר.","a":"אפקט ציפייה — הנסיין \"משדר\" בלי משים ציפיות למשתתפים (דוגמה: חולדות \"מצטיינות\"). אפקט פלסבו — המשתתף משנה התנהגות רק מתוך אמונה בטיפול, גם ללא מניפולציה אמיתית (כדור פלסבו).","explain":"אפקט הציפייה מתרחש כאשר החוקר או הצופה מצפים שהמשתתפים יתנהגו בצורה מסוימת, ומבלי להיות מודעים לכך \"משדרים\" ציפייה זו למשתתפים, הגורמים להם להתאים את התנהגותם אליה — כך שהתוצאה נובעת מציפיות הנסיין ולא מהמשתנה הבלתי־תלוי עצמו. דוגמה: סטודנטים שהאמינו שהחולדות שלהם \"מצטיינות\" טיפלו בהן אחרת, וזה השפיע על ביצועי החולדות. אפקט הפלסבו מתרחש כאשר משתתפים משנים את התנהגותם בהעדר כל מניפולציה ניסויית ממשית — רק בגלל אמונתם ביעילות הטיפול. דוגמה: משתתפים שנטלו כדור פלסבו הראו שיפור זהה לאלה שנטלו תוסף אמיתי, מה שמראה שהשיפור לא נבע מהחומר הפעיל אלא מהציפייה/מהתרגול. שני האפקטים הם סוגי משתנים מתערבים העלולים לסלף את תוצאות הניסוי.","mnemo":"🐭 אפקט ציפייה = הנסיין \"משדר\" ציפיות בלי לשים לב (חולדות \"מצטיינות\"). אפקט פלסבו = המשתתף עצמו מאמין ומשתנה, גם בלי טיפול אמיתי."},{"id":"prof2_21","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהם הליכי בקרה וכיצד הם מסייעים לפתור את בעיית המשתנים המתערבים?","a":"שיטות המחזיקות קבועים את כל המשתנים שאינם קשורים להשערה. כך השינוי היחיד בין המשתתפים נובע רק מהמשתנה הבלתי־תלוי.","explain":"הליכי בקרה הם שיטות המנסות להחזיק קבוע את כל המשתנים והתנאים שאינם קשורים להשערה העומדת למבחן. מרבית אפיוני הניסוי (הנחיות, טמפרטורת החדר, לבוש הנסיין, הקצאת הזמן, אופן תיעוד התגובות) חייבים להיות זהים לכל המשתתפים — כדי שהשינוי היחיד בהתנסותם ינבע רק מהמשתנה הבלתי־תלוי. כך פותרים את בעיית המשתנים המתערבים: אם כל התנאים האחרים קבועים, אפשר לייחס כל הבדל בתוצאות למשתנה הבלתי־תלוי בלבד, ולא לגורם נוסף כלשהו שהתערב במהלך הניסוי.","mnemo":"🔒 הליכי בקרה = נועלים הכל במקום חוץ מדבר אחד - כך שכל שינוי בתוצאה בא רק מהדבר האחד הזה."},{"id":"prof2_22","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תארו את הליכי הבקרה שבעזרתם אפשר להפחית את ההשפעה של אפקט הציפייה.","a":"בקרת כפל־עיוורון — גם המשתתפים וגם עוזר הניסוי אינם יודעים לאיזה תנאי נחשף כל משתתף.","explain":"כדי להפחית את השפעת אפקט הציפייה, החוקרים משתמשים בבקרת כפל־עיוורון: גם עוזר הניסוי (המעריך את התגובות) וגם המשתתפים אינם יודעים לאיזה תנאי ניסוי נחשף כל משתתף. כך אף אחד מהם אינו יכול \"לשדר\" ציפיות מודעות או לא־מודעות שישפיעו על התוצאות. דוגמה מהספר (מחקר הקפאין): המשתתפים לא ידעו איזה סוג קפה שתו, וגם הנסיינים שהעריכו את ביצועי הזיכרון לא ידעו זאת. לביסוס נוסף, ביקשו מהמשתתפים לנחש איזה קפה שתו — הם לא הצליחו, מה שמוכיח שהתוצאות לא נבעו מציפיותיהם.","mnemo":"🙈 כפל-עיוורון = 2 סוגי כיסויי עיניים: גם למשתתף וגם לעוזר הניסוי - אף אחד לא רואה מי מקבל מה."},{"id":"prof2_23","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תארו את הליכי הבקרה שבעזרתם אפשר להפחית את ההשפעה של אפקט פלסבו.","a":"בקרת פלסבו — כוללים קבוצה המקבלת טיפול דמה ללא מרכיב פעיל. אם קבוצה זו מראה שיפור דומה, זה מוכיח שהשיפור לא נבע מהחומר עצמו.","explain":"כדי להפחית את השפעת אפקט הפלסבו, החוקרים כוללים בניסוי קבוצת בקרה שאינה מקבלת כל טיפול ממשי, אלא טיפול דמה (פלסבו) ללא מרכיב פעיל. בקרת הפלסבו מספקת בסיס להשוואה — אם קבוצת הפלסבו מראה שיפור דומה לקבוצת הטיפול האמיתי, ניתן להסיק שהשיפור לא נבע מהחומר הפעיל עצמו אלא מהאמונה בטיפול או מגורמים אחרים. דוגמה מהספר: משתתפים שנטלו כדור פלסבו הראו שיפור זהה (14%) לאלה שנטלו את תוסף גינקו־בילובה האמיתי.","mnemo":"💊 בקרת פלסבו = כדור-דמה. אם קבוצת הכדור-הדמה משתפרת כמו קבוצת הכדור-האמיתי, הכל היה באמונה, לא בכימיה."},{"id":"prof2_24","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו מערך מחקר בין־נבדקי?","a":"מערך שבו כל משתתף מוקצה באופן מקרי לקבוצה אחת בלבד (ניסוי או ביקורת). ההקצאה המקרית מנטרלת הבדלים אישיים.","explain":"מערך בין נבדקים הוא מערך מחקר שבו כל משתתף מוקצה, בהליך מקרי (אקראי), לקבוצה אחת בלבד — קבוצת הניסוי (המקבלת טיפול ניסויי אחד או יותר) או קבוצת הביקורת (שאינה מקבלת טיפול). ההקצאה המקרית היא אמצעי מרכזי לנטרל משתנים מתערבים הקשורים להבדלים אישיים בין משתתפים, שכן לכל משתתף יש סיכוי זהה להימצא בכל אחת מהקבוצות — כך הקבוצות דומות זו לזו בתחילת הניסוי, ואם נמצאים הבדלים בממצאים, ניתן לייחס אותם למה שהתרחש בניסוי ולא להבדלים שהיו קיימים מראש בין המשתתפים.","mnemo":"🎲 בין-נבדקי = 2 קבוצות נפרדות של אנשים, כל אחד בקוביה אחת (הגרלה אקראית לקבוצה אחת בלבד)."},{"id":"prof2_25","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד הקצאה מקרית במערך מחקר בין־נבדקי פועלת כהליך בקרה במחקר?","a":"לכל משתתף סיכוי זהה להימצא בכל קבוצה, כך הקבוצות דומות מראש. הבדל בתוצאות מיוחס למשתנה הבלתי־תלוי ולא להבדלים אישיים.","explain":"ההקצאה המקרית משמשת כהליך בקרה מכיוון שהיא מנטרלת משתנים מתערבים הקשורים להבדלים אישיים בין המשתתפים. כאשר כל משתתף מוקצה לקבוצה על בסיס מקרי, לכל אחד יש סיכוי זהה להימצא בכל אחת מהקבוצות — כך הקבוצות דומות זו לזו במאפיינים חשובים כבר בתחילת הניסוי. כתוצאה מכך, אם נמצא הבדל בממצאים בין הקבוצות בסוף הניסוי, אפשר לייחס אותו באמון רב יותר למה שהתרחש בניסוי עצמו (המשתנה הבלתי־תלוי), ולא להבדלים שהתקיימו בין המשתתפים עוד לפני שהניסוי החל.","mnemo":"🎲 ההגרלה לקבוצות הוגנת - סיכוי שווה לכל קבוצה, אז ההבדל שנשאר בסוף הוא רק מהמשתנה הבלתי-תלוי."},{"id":"prof2_26","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו מדגם מייצג ומה החשיבות לכך בתהליך המחקר?","a":"מדגם התואם את מאפייני האוכלוסייה הכללית. חשוב כי מחקר משתמש במדגם קטן, אך רוצה להכליל לכל האוכלוסייה — הכללה תקפה רק אם המדגם מייצג אותה.","explain":"מדגם מייצג הוא מדגם שתואם, במידה רבה, את המאפיינים הכלליים של האוכלוסייה שהוא בא לייצג (למשל, התפלגות מגדר, קבוצות אתניות, גזעים). החשיבות: מחקר טיפוסי מזמן רק 20-100 משתתפים, אך החוקרים רוצים להכליל (להקיש) מתוצאות המדגם הקטן לכלל האוכלוסייה. הכללה כזו תקפה רק אם המדגם אכן מייצג את האוכלוסייה בצורה נאותה — אחרת, ההכללה תהיה שגויה. לדוגמה: אם במחקר על שקרים השתתפו בנים בלבד, זו תהיה טעות להסיק ממנו מסקנות גם על התנהגות בנות.","mnemo":"🖼️ מדגם מייצג = תמונה מוקטנת אך נאמנה של כל האוכלוסייה - כמו דגימת צבע קטנה שמייצגת את כל הקיר."},{"id":"prof2_27","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו מערך תוך־נבדקי?","a":"מערך שבו כל משתתף משמש כביקורת של עצמו — משווים את התנהגותו לפני ואחרי ההתערבות (או בין שני תנאים).","explain":"מערך תוך־נבדקי הוא מערך מחקר שבו כל משתתף משמש כביקורת של עצמו — משווים את התנהגותו של אותו משתתף לפני ההתערבות הניסויית לבין התנהגותו אחריה (או בין שני תנאים שונים), ולא בין שתי קבוצות נפרדות של אנשים. דוגמה מהספר: במחקר על תינוקות בני שנה, הושוותה התנהגותם של אותם התינוקות עצמם בשני מצבים — כאשר צפו בסרטון בו שחקנית מתארת חפץ בטון ניטרלי, לעומת סרטון בו היא מתארת אותו בטון שלילי. נמצא שהתינוקות נגעו פחות בחפץ כאשר הובע כלפיו רגש שלילי.","mnemo":"🪞 תוך-נבדקי = מראה - אותו אדם מושווה מול עצמו (לפני/אחרי), לא מול אדם אחר."},{"id":"prof2_28","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"במה נבדל מערך בין־נבדקי ממערך תוך־נבדקי?","a":"בין־נבדקים — משווים בין קבוצות שונות של משתתפים. תוך־נבדקים — משווים את אותם משתתפים בשני תנאים שונים.","explain":"ההבדל המרכזי: במערך בין־נבדקים משווים בין קבוצות שונות של משתתפים (הוקצו אליהן באופן מקרי), ואילו במערך תוך־נבדקים משווים את אותם המשתתפים עצמם בשני תנאים שונים — כל משתתף משמש כביקורת של עצמו. יתרון מערך תוך־נבדקים: מנטרל לגמרי הבדלים אישיים בין אנשים. דוגמאות מהספר: מחקר הקפאין השתמש במערך בין־נבדקים (קבוצה ששתתה קפה עם קפאין מול קבוצה ששתתה בלי), ואילו מחקר התינוקות השתמש במערך תוך־נבדקי (אותם תינוקות הושוו בין צפייה בטון ניטרלי לצפייה בטון שלילי).","mnemo":"🎲🪞 בין-נבדקים=קוביה (2 קבוצות שונות). תוך-נבדקים=מראה (אותו אדם, 2 מצבים)."},{"id":"prof2_29","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע השוואה בין גברים לנשים אינה עונה על ההגדרה של שיטת הניסוי?","a":"שיטת הניסוי דורשת מניפולציה על המשתנה הבלתי־תלוי. מין הוא מאפיין קיים מראש שהחוקר לא יכול להקצות. לכן זו שיטה מתאמית, לא ניסוי.","explain":"השוואה בין גברים לנשים אינה עונה על הגדרת שיטת הניסוי, כי הגדרת שיטת הניסוי דורשת שהחוקר יבצע מניפולציה על המשתנה הבלתי־תלוי — כלומר, יקבע ויפעיל בעצמו את הערכים של אותו משתנה. מין (זכר/נקבה) הוא מאפיין קיים מראש של המשתתף — החוקר אינו יכול \"להקצות\" למישהו להיות גבר או אישה; הוא רק בוחר או מתבונן בקבוצות שכבר קיימות. מכיוון שאין כאן מניפולציה אמיתית על המשתנה, ההשוואה אינה ניסוי אמיתי, אלא שיטה מתאמית (קורלטיבית).","mnemo":"🚫🎮 אי אפשר \"להקצות\" מין ליד-הג'ויסטיק - זה כבר קיים מראש, אז זה מתאמי, לא ניסוי."},{"id":"prof2_30","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"לכל אחת מ-4 שאלות מחקר, זהו האם מתאימה שיטה ניסויית או מתאמית: נוער ועמדות פוליטיות; הוראת מתמטיקה בגיל הגן; שיח מול סרט להפחתת אלימות; עושר ואושר.","a":"(1) נוער ופוליטיקה — מתאמי (גיל קיים, לא ניתן להקצאה). (2) מתמטיקה בגיל הגן — ניסוי (ניתן להקצות מתי מתחילים). (3) שיח/סרט — ניסוי (ניתן להקצות התערבויות). (4) עושר ואושר — מתאמי (עושר קיים מראש).","explain":"(1) נוער ועמדות פוליטיות — שיטה מתאמית. הגיל הוא מאפיין קיים מראש של המשתתפים; החוקר אינו יכול להקצות אנשים להיות \"מתבגרים\" או \"מבוגרים\" — הוא רק משווה קבוצות גיל קיימות. (2) הוראת מתמטיקה בגיל הגן — שיטת ניסוי. החוקר יכול לבצע מניפולציה אמיתית: להקצות באופן מקרי קבוצת ילדים שתתחיל ללמוד מתמטיקה בגיל הגן, וקבוצת ביקורת שתתחיל בגיל מאוחר יותר. (3) שיח מול סרט להפחתת אלימות — שיטת ניסוי. אלה שתי התערבויות ספציפיות שהחוקר יכול להפעיל בפועל, ולמדוד את ההשפעה על רמת האלימות. (4) עושר ואושר — שיטה מתאמית. אי אפשר להקצות אנשים באופן מקרי להיות \"עשירים\" או \"לא עשירים\" — זהו מאפיין קיים, ולכן בודקים את הקשר הטבעי בין שני המשתנים. (ניתוח של הסטודנט המיישם את קריטריון המניפולציה מהספר.)","mnemo":"🎮 השאלה: \"האם היד שלי (החוקר) יכולה לקבוע את זה מראש?\" אם כן=ניסוי. אם זה כבר קיים (גיל/עושר/מין)=מתאמי."},{"id":"prof2_31","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהן שיטות מתאמיות ובאילו תנאים ייעשה בהן שימוש?","a":"שיטות לקביעת מידת הקשר בין שני משתנים. משתמשים בהן כשאי אפשר לבצע מניפולציה על המשתנה (מסיבות מעשיות או אתיות).","explain":"פסיכולוגים משתמשים בשיטות מתאמיות כאשר הם רוצים לקבוע באיזו מידה שני משתנים או שתי תכונות קשורים זה בזה. משתמשים בהן במיוחד כאשר אי אפשר לבצע מניפולציה על המשתנים, גם מסיבות אתיות. דוגמאות מהספר: האם אינטליגנציה קשורה ליצירתיות? האם אנשים אופטימיים בריאים יותר מפסימיים? היש קשר בין מחלות נפש להתעללות שחוו החולים בילדותם? במקרים כאלה אי אפשר להקצות משתתפים באופן מקרי לתנאים שונים (למשל, לא ניתן ליצור קבוצת ילדים \"שעברו התעללות\" וקבוצה ש\"לא עברה\"), ולכן משתמשים בשיטה מתאמית, שבה בודקים את הקשר בין משתנים כפי שהם קיימים באופן טבעי.","mnemo":"🚫🎮 שיטה מתאמית = כשאסור/אי-אפשר לגעת בג'ויסטיק (מטעמים מעשיים/אתיים) - רק מסתכלים על מה שכבר קיים."},{"id":"prof2_32","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו מקדם מתאם?","a":"מדד סטטיסטי (r) לרמת הקשר בין שני משתנים, נע בין +1.0 ל -1.0; 0.0 = אין קשר. ככל שקרוב יותר לקצוות, כך הקשר חזק וניתן לנבא יותר.","explain":"<b>מקדם-מתאם (r)</b> - מדד-סטטיסטי המכמת את <b>עוצמת-הקשר</b> בין שני-משתנים, נע בטווח <b>קבוע</b> בין <b>1.0+</b> (קשר-חיובי-מושלם) ל<b>1.0-</b> (קשר-שלילי-מושלם); <b>0.0</b> = העדר-קשר-כלשהו. ⚠️ נקודת-המפתח-לזכור: <b>העוצמה</b> נמדדת לפי <b>הערך-המוחלט</b> (המרחק-מ-0), <b>לא</b> לפי-הסימן (+/-) - ככל שקרוב-יותר <b>לקצוות</b> (בין-אם +1 או -1), כך הקשר <b>חזק-יותר</b> וניתן-לניבוי-מדויק-יותר. מתאם של -0.9 חזק-יותר ממתאם של +0.5, למרות-הסימן-השונה - זו נקודה שקל-להתבלבל-בה.","mnemo":"📊 מקדם מתאם (r) = סרגל מ-1- עד 1+. קצוות (רחוק מ-0) = קשר חזק וניתן לניבוי. אמצע (0) = אין קשר."},{"id":"prof2_33","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"על איזה קשר מצביע מקדם מתאם שלילי?","a":"כאשר ערכי משתנה אחד עולים, ערכי המשתנה האחר יורדים (למשל: יותר פעילות גופנית, פחות משקל).","explain":"מקדם מתאם שלילי מציין קשר שבו כאשר הערכים של משתנה אחד עולים, הערכים של המשתנה האחר יורדים. דוגמה מהספר: ככל שעולה מספר שעות הפעילות הגופנית, יורד המשקל. דוגמה נוספת: בגולף, ככל שהשחקן צובר פחות נקודות (תוצאה טובה יותר במשחק זה), הוא מרוויח יותר כסף — קשר שלילי בין נקודות לרווח.","mnemo":"📉 שלילי = מגלשה - אחד עולה, השני יורד (יותר ספורט, פחות משקל)."},{"id":"prof2_34","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"על איזה קשר מצביע מקדם מתאם חיובי?","a":"כאשר ערכי משתנה אחד עולים, גם ערכי המשתנה האחר עולים (למשל: יותר גובה, יותר משקל).","explain":"<b>מתאם חיובי</b> - קשר שבו כאשר ערכי-משתנה-אחד <b>עולים</b>, גם ערכי-המשתנה-האחר <b>עולים</b> (שני-המשתנים 'זזים באותו-כיוון'). הדוגמה: ככל-שהגובה עולה, גם-המשקל נוטה-לעלות. ⚠️ אל-תתבלבלו עם 'חזק' - מתאם-חיובי יכול-להיות חלש (+0.2) או-חזק (+0.9) - 'חיובי' מתאר רק את <b>כיוון</b> הקשר (שני-המשתנים עולים-יחד), לא-את-עוצמתו. ההפך המדויק הוא מתאם-שלילי (עולה-אחד, יורד-השני).","mnemo":"📈 חיובי = מדרגות - שניהם עולים ביחד (יותר גובה, יותר משקל)."},{"id":"prof2_35","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי המגבלה המרכזית של מחקר מתאמי?","a":"מתאם אינו מבטיח סיבתיות — הוא מציין רק ששני משתנים קשורים באופן שיטתי. אותו מתאם יכול להתפרש במספר דרכים סיבתיות שונות.","explain":"המגבלה המרכזית של מחקר מתאמי היא שמתאם אינו מבטיח סיבתיות — אין להקיש מקיומו של מתאם על קיומו של קשר סיבה־תוצאה. מתאם גבוה מציין רק ששתי קבוצות נתונים קשורות זו בזו באופן שיטתי, אך אינו מבטיח שאחת גורמת לשנייה. המתאם יכול לשקף מגוון אפשרויות של סיבה־תוצאה, וייתכן גם שאין קשר סיבתי כלל בין המשתנים. דוגמה מהספר: מתאם חיובי בין שעות שינה לממוצע ציונים יכול להתפרש בלפחות שלוש דרכים שונות — (1) סטודנטים הלומדים ביעילות (ולכן מצליחים יותר) הולכים לישון מוקדם יותר; (2) סטודנטים החרדים מלימודיהם (ולכן ציוניהם נמוכים) מתקשים להירדם; (3) סטודנטים הלומדים קורסים קלים (ולכן מצליחים יותר) מצליחים גם לישון טוב יותר. כל שלוש ההסברים מתאימים לאותו מתאם — ולכן יש צורך במחקר נוסף כדי לזהות את ההסבר האמיתי.","mnemo":"🚫➡️ מתאם ≠ סיבתיות! (שוב 2 קוסמים מתחרים - הקשר יכול להיות מוסבר בכמה דרכים)."},{"id":"prof2_36","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"לכל הליך בקרה (כפל־עיוורון, פלסבו, הקצאה מקרית) — מהי הבעיה שהוא פותר, וכיצד יושם במחקר על מסרים תת־סיפיים?","a":"כפל־עיוורון — פותר אפקט ציפייה; החוקרים לא ידעו איזו קלטת קיבל כל משתתף. בקרת פלסבו — פותרת אפקט פלסבו; תוצאות אובייקטיביות לא השתפרו כלל, רק האמונה השתנתה. הקצאה מקרית — פותרת הבדלים אישיים; חולקו אקראית לאחת משתי קלטות.","explain":"בקרת כפל־עיוורון — פותרת את בעיית אפקט הציפייה — גם המשתתף וגם הנסיין/עוזר הניסוי אינם יודעים לאיזה תנאי ניסוי נחשף כל משתתף. במחקר: החוקרים עצמם לא ידעו איזו קלטת (זיכרון או ערך־עצמי) קיבל כל אחד מן המשתתפים — כך לא יכלו \"לשדר\" ציפיות שישפיעו על תוצאות המבחנים. בקרת פלסבו — פותרת את בעיית אפקט הפלסבו — כוללים תנאי המאפשר להשוות אם השינוי נובע מהתוכן הממשי או רק מהאמונה בטיפול. במחקר: התוצאות האובייקטיביות (זיכרון וערך־עצמי) לא השתפרו כלל; ההוכחה לאפקט פלסבו: כאשר תייגו קלטת זיכרון בטעות כ\"ערך־עצמי\" (ולהפך), המשתתפים האמינו שהמאפיין המתאים להם השתפר — לפי התווית, לא לפי תוכן הקלטת בפועל. הקצאה מקרית — פותרת את בעיית הבדלים אישיים בין משתתפים — הקצאה אקראית לתנאים מבטיחה שהקבוצות דומות מראש. במחקר: לאחר המבחנים הראשוניים, חילקו את המשתתפים באופן אקראי לאחד משני מצבי הניסוי (קלטת זיכרון תת־ספית / קלטת ערך־עצמי תת־ספית).","mnemo":"🎧 מסרים תת-סיפיים: כפל-עיוורון (לא ידעו איזו קלטת) + פלסבו (התוצאות לא השתפרו) + הגרלה (חולקו אקראית ל-2 קלטות)."},{"id":"prof2_37","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי השערת המחקר (סקר וטוני בלייר)?","a":"שאלות בסקר (גם ניטרליות לכאורה) יכולות להשפיע על עמדות. מספר התכונות (2 מול 5) והערכיות שלהן ישפיעו על רמת האהדה כלפי בלייר.","explain":"השערת המחקר: שאלות בסקר, גם ניטרליות לכאורה, יכולות להשפיע על עמדות האנשים כלפי מועמד פוליטי. באופן ספציפי — התבקשות למנות מספר מסוים של תכונות (שתיים או חמש) בעלות ערכיות מסוימת (חיוביות או שליליות) על טוני בלייר, תשפיע על רמת האהדה של המשתתפים כלפיו לאחר מכן. ההנחה המרכזית: קושי במשימה (למשל, קושי למנות 5 תכונות שליליות) עלול להוביל למסקנה הפוכה מהמצופה — \"אם אינני מסוגל למצוא 5 תכונות שליליות, ייתכן שהוא בעצם מוצלח למדי.\"","mnemo":"📞 סקר טוני בלייר: גם שאלות \"נייטרליות\" משנות עמדות - זה כל ההשערה."},{"id":"prof2_38","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהם משתני המחקר (סקר וטוני בלייר)?","a":"משתנה בלתי־תלוי: מספר התכונות (2/5) כפול ערכיותן (חיובי/שלילי) — 4 גרסאות. משתנה תלוי: רמת אהדה כלפי בלייר, בסולם 7 נקודות.","explain":"המשתנה הבלתי־תלוי הוא שילוב של שני גורמים: מספר התכונות שהתבקשו המשתתפים למנות (שתיים או חמש), וערכיות התכונות (חיוביות או שליליות) — יחד יוצרים ארבע גרסאות שונות של השאלון (2 חיוביות, 5 חיוביות, 2 שליליות, 5 שליליות). המשתנה התלוי הוא רמת האהדה של המשתתפים כלפי טוני בלייר, שנמדדה על סולם של שבע נקודות, כאשר ניקוד גבוה יותר משקף הערכה חיובית רבה יותר.","mnemo":"🎮 יד-הג'ויסטיק=מספר תכונות(2/5)×סוג(חיובי/שלילי)=4 גרסאות. תוצאה נמדדת=ציון אהדה 1-7."},{"id":"prof2_39","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהן ההגדרות האופרציונליות של המשתנים במחקר טוני בלייר?","a":"משתנה בלתי־תלוי = ההוראה הספציפית שקיבל כל משתתף. משתנה תלוי = הציון (1-7) שנתן המשתתף לרמת אהדתו.","explain":"ההגדרה האופרציונלית של המשתנה הבלתי־תלוי: ההוראה הספציפית שקיבל כל משתתף בשאלון — לדוגמה, \"מנו שתי תכונות חיוביות של טוני בלייר\" או \"מנו חמש תכונות שליליות של טוני בלייר\" (בסך הכול ארבע הוראות אפשריות שונות). ההגדרה האופרציונלית של המשתנה התלוי: הציון המספרי (בין 1 ל-7) שנתן כל משתתף כאשר התבקש לדרג את רמת אהדתו כלפי בלייר על סולם בן שבע נקודות.","mnemo":"🔗 אותם 2 משתנים (הוראה שהתקבלה / ציון שניתן) - רק מוגדרים כאן במדויק ובמספרים."},{"id":"prof2_40","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"זהו את מערך המחקר (סקר וטוני בלייר).","a":"מערך ניסויי בין־נבדקים — כל משתתף קיבל גרסה אחת בלבד מתוך 4 גרסאות, והחוקרים קבעו זאת במכוון.","explain":"מדובר במערך בין־נבדקים ניסויי: כל משתתף נחשף לגרסה אחת בלבד מתוך ארבע גרסאות השאלון (שילוב של מספר תכונות וערכיותן), ולכן ההשוואה נעשית בין קבוצות שונות של משתתפים, ולא בין אותם משתתפים בתנאים שונים. זהו מערך ניסויי (ולא מתאמי) מכיוון שהחוקרים ביצעו מניפולציה אמיתית — הם קבעו איזו גרסת שאלון יקבל כל משתתף.","mnemo":"🎲 כל משתתף קיבל רק 1 מתוך 4 גרסאות = הקצאה מקרית = מערך בין-נבדקים."},{"id":"prof2_41","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"אילו הליכי בקרה הופעלו במחקר (סקר וטוני בלייר)?","a":"(1) הקצאה מקרית — כל משתתף קיבל רק אחת מ-4 גרסאות. (2) שיחת הבהרה בסיום הניסוי.","explain":"במחקר הופעלו שני הליכי בקרה עיקריים: (1) הקצאה מקרית — כל משתתף קיבל גרסה אחת בלבד מתוך ארבע גרסאות השאלון, כדי להבטיח שהקבוצות יהיו דומות זו לזו בתחילת המחקר. (2) שיחת הבהרה (debriefing) — בסיום הניסוי במעבדה, החוקרים חייבים לקיים שיחת הבהרה עם המשתתפים, שבה הם מספקים להם מידע שיסייע להם להבין כיצד השתתפותם במחקר הייתה עשויה להשפיע על דרך חשיבתם או הרגשתם.","mnemo":"🎲💬 הגרלה ל-4 גרסאות + שיחת הבהרה בסוף (לספר למשתתפים על מה שקרה באמת)."},{"id":"prof2_42","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהן תוצאות המחקר (סקר וטוני בלייר)?","a":"התוצאות תמכו בניבוי רק בתת־קבוצה שלא התעניינה בפוליטיקה: מי שנדרש להיזכר בתכונות שליליות דירג את בלייר חיובי יותר.","explain":"התוצאות תמכו בניבויים רק בתת־קבוצה של המשתתפים — אלה שלא התעניינו רבות בפוליטיקה הבריטית. בתת־קבוצה זו, משתתפים שהתבקשו להיזכר בתכונות שליליות של בלייר דירגו אותו באופן חיובי יותר (בהתאם לניבוי, שהקושי במשימה הוביל למסקנה הפוכה). לעומת זאת, אצל סטודנטים שהתעניינו בפוליטיקה הבריטית — שלהם היה קל יותר לשלוף מידע על בלייר — המניפולציה לא השפיעה על עמדותיהם כלל.","mnemo":"🎯 התוצאה \"פגעה\" רק בקבוצה ספציפית: מי שלא התעניין בפוליטיקה - שם ההשערה אוששה."},{"id":"prof2_43","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהן מסקנות המחקר (סקר וטוני בלייר)?","a":"סקרים טלפוניים, גם ניטרליים לכאורה, יכולים להשפיע ממש על עמדות. עורכי סקר לא חושפים כוונות אמיתיות ולא מספקים הסבר, בניגוד לחוקרי מעבדה.","explain":"המסקנה המרכזית של המחקר היא שסקרים טלפוניים, גם אם נשמעים ניטרליים או \"תמימים\", עלולים להשפיע באמת על עמדותיהם של האנשים. בניגוד לחוקרים במעבדה, שמחויבים לקיים שיחת הבהרה בתום הניסוי, עורכי סקר טלפוני אינם נוטלים על עצמם את אותה האחריות ואינם חושפים תמיד את כוונותיהם האמיתיות — הם עשויים לבקש לשנות את עמדות המשיבים כדי שגם התנהגותם תשתנה בהמשך (כגון הצבעה בבחירות), מבלי לספק להם הסבר או הבהרה כלשהי.","mnemo":"📞⚠️ סקרים \"תמימים\" בטלפון יכולים לשנות עמדות בלי שתדע - ובניגוד למעבדה, לא מסבירים לך את זה אחר-כך."},{"id":"prof2_44","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"זהו מהימנות או תוקף בדוגמאות: (1) חוסר הסכמה בין מראיינים, (2) מבחן אינטליגנציה הדורש ריכוז, (3) שאלות מילוליות במבחן מתמטיקה, (4) מדידת שיער בס\"מ מול מ\"מ.","a":"(1) מהימנות — בין־שופטים. (2) תוקף — מודד גם ריכוז. (3) תוקף — מודד גם שפה. (4) מהימנות — כלי גס מדי.","explain":"(1) חוסר הסכמה בין מראיינים — בעיית מהימנות (בין־שופטים): כלי המדידה אינו נותן ציונים עקביים כאשר משתמשים בו שופטים/מראיינים שונים. (2) מבחן אינטליגנציה הדורש ריכוז — בעיית תוקף: המבחן אינו מודד רק אינטליגנציה — הוא מודד גם יכולת ריכוז, ולכן אינו מודד באמת את המשתנה התיאורטי עבור אוכלוסייה זו. (3) שאלות מילוליות במבחן מתמטיקה — בעיית תוקף: החלק המילולי אינו מודד רק ידע מתמטי — הוא מודד גם שליטה בשפה העברית. (4) מדידת אורך שיער בס\"מ מול מ\"מ — בעיית מהימנות: כלי מדידה גס מדי אינו מספק תוצאות עקביות ומדויקות מספיק, ולכן חוקרים שונים המשתמשים בו עלולים לקבל תוצאות שונות זו מזו.","mnemo":"🎯 דארטס! מהימנות=כל החיצים נוחתים באותו המקום (עקבי, גם אם לא במרכז). תוקף=החיצים פוגעים בול-עין (מודדים בדיוק את מה שרוצים)."},{"id":"prof2_45","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"האם מצאתם בעיות המשפיעות גם על המהימנות וגם על התוקף? כיצד?","a":"כן — ראיון לא עקבי עם סגנון שיפוט שונה פוגע גם בתוקף. כלל: בעיית מהימנות חמורה תמיד פוגעת גם בתוקף, אך כלי יכול להיות מהימן מבלי להיות תקף.","explain":"כן — דוגמה 1 (חוסר הסכמה בין מראיינים) עשויה לפגוע גם בתוקף: אם שני מראיינים מגיעים למסקנות שונות באופן עקבי (למשל, אחד תמיד מחמיר ואחד תמיד מקל), הראיון אינו רק בלתי־מהימן — הוא גם עלול שלא למדוד את התכונה האמיתית (התאמה לתפקיד) אלא את סגנון השיפוט האישי של כל מראיין. כלל כללי: בעיית מהימנות חמורה (חוסר עקביות) תמיד תפגע גם בתוקף — אם כלי המדידה אינו יציב ועקבי, אי אפשר לסמוך עליו כלל שהוא מודד את המשתנה התיאורטי הנכון. לעומת זאת, ייתכן כלי מדידה מהימן (עקבי) שאינו תקף (למשל, דוגמאות 2 ו-3, שבהן הכלי עקבי אך מודד גם משתנה נוסף שאינו רצוי).","mnemo":"🎯 אם החיצים מפוזרים בלי עקביות (לא מהימן) - אי אפשר בכלל לדעת אם הם פוגעים בבול-עין. חוסר-מהימנות תמיד פוגע גם בתוקף."},{"id":"prof2_46","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"סכמו את המדדים המרכזיים (דיווח־עצמי והתנהגות) עם דוגמה לכל אחד.","a":"דיווח־עצמי: שאלון פתוח, שאלון רב־ברירה, ריאיון מובנה, ריאיון פתוח. התנהגות: תצפית ישירה, תצפית בסביבה טבעית, נתונים ארכיוניים, ניתוח מקרה.","explain":"מדדי דיווח־עצמי (self-report) — תשובות מילוליות, בכתב או בעל־פה, על שאלות החוקר; משמשים לחקור חוויות שאינן ניתנות לצפייה ישירה או התנהגויות רגישות. שאלון/סקר שאלות פתוחות — תשובה חופשית במילים; דוגמה: \"כיצד אתה מרגיש לגבי עבודתך?\". שאלון/סקר שאלות רב־ברירה — תשובות חלופיות קבועות מראש; דוגמה: \"האם אתה מרוצה מעבודתך?\" (כן/לא/לא החלטתי). ריאיון מובנה — שאלון קבוע מראש לכל המרואיינים; דוגמה: ריאיון עבודה עם רשימת שאלות זהה. ריאיון פתוח — שיחה חופשית עם שאלות נוספות בהתאם למהלכה. מדדי התנהגות — דרכים לחקור פעולות גלויות. תצפית ישירה — כשההתנהגות גלויה וקלה לתיעוד, לרוב במעבדה; דוגמה: תיעוד הבעות פנים. תצפית בסביבה הטבעית — התבוננות ללא התערבות; דוגמה: מחקר השימפנזים של ג'יין גודול. נתונים ארכיוניים — שימוש במידע קיים ומתועד; דוגמה: אחוז הנשים לעומת גברים בארגון \"רופאי העולם\". ניתוח מקרה — ניתוח אינטנסיבי של אדם אחד או קבוצה קטנה; דוגמה: תצפיות במטופלים בעלי נזק מוחי.","mnemo":"🗣️👁️ 2 משפחות מדדים: דיווח-עצמי=מה שהוא אומר (שאלון/ריאיון). התנהגות=מה שהוא עושה (תצפית/ארכיון/מקרה)."},{"id":"prof2_47","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"(1) איזה מדד השתמשו בו החוקרים (טוני בלייר)? (2) בעיית \"ענו לפי מה שמצפים\" — מהימנות או תוקף? (3) מהו סוג המדד החלופי (תרומה)? (4) יתרונות/חסרונות.","a":"(1) דיווח־עצמי (שאלון). (2) תוקף. (3) מדד התנהגות (תרומה). (4) שאלון: מהיר אך פגיע לרצייה חברתית. תרומה: קשה לזייף אך מושפעת ממצב כלכלי.","explain":"(1) החוקרים השתמשו במדד דיווח־עצמי — שאלון: המשתתפים דירגו את מידת אהדתם לבלייר על סולם של שבע נקודות. (2) זוהי טענת תוקף: הבעיה אינה שהמדידה בלתי יציבה, אלא שהמדד אינו בהכרח מודד את המשתנה התיאורטי האמיתי (האהדה האמיתית), אלא מודד דבר אחר — ציות לציפיות הנחזות של החוקר. (3) זהו מדד התנהגות — תיעוד של פעולה גלויה וממשית (סכום הכסף שנתרם בפועל). (4) מדד הדיווח־העצמי (שאלון) — יתרונו: מהיר, פשוט וקל להשוואה מספרית. חסרונו: פגיע לרצייה חברתית ולניחוש ציפיות החוקר — פוגע בתוקף. מדד ההתנהגות (תרומת כסף) — יתרונו: התנהגות אמיתית ו\"יקרה\" (כרוכה בוויתור על כסף אמיתי), קשה יותר לזייף — תוקף גבוה יותר. חסרונו: הסכום מושפע גם ממצבו הכלכלי של המשתתף (פוגע בתוקף — מודד גם משתנה נוסף), וייתכן שרוב המשתתפים כלל לא יתרמו (אפקט רצפה, פוגע ברגישות/במהימנות המדד).","mnemo":"🔗 בלייר: שאלון=דיווח-עצמי (בעיית תוקף - האם מודד רצייה חברתית ולא אהדה אמיתית). תרומה בפועל=מדד התנהגות חלופי."},{"id":"prof2_48","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תארו 4 סוגיות אתיות במחקר בבני אדם וכיצד הן קשורות לעיקרון עשיית הטוב והימנעות מנזק.","a":"(1) הערכת רווח מול הפסד. (2) הסכמה מדעת. (3) הטעיה מכוונת — מותרת רק אם הכרחית. (4) שיחת הבהרה. כולן מאזנות תועלת מדעית מול מזעור נזק.","explain":"(1) הערכת רווח מול הפסד — לפני אישור מחקר, שוקלים את הסיכונים הפוטנציאליים למשתתפים מול התועלת הצפויה למדע ולחברה. (2) הסכמה מדעת — מציגים למשתתפים תיאור מלא של ההליכים, הסיכונים והתועלת; המשתתפים חותמים כי הם מסכימים ורשאים לפרוש בכל עת ללא סנקציה. (3) הטעיה מכוונת — מותרת רק בתנאים מחמירים: חשיבות המחקר חייבת להצדיק אותה, אין הליך יעיל אחר, יש להסביר אותה בסיום, והמשתתפים רשאים להוציא את נתוניהם לאחר הגילוי. (4) שיחת הבהרה — בסיום כל ניסוי, מסבירים למשתתף את מטרת המחקר ותוצאותיו, ומוודאים שאינו מבולבל או נבוך. בכל ארבע הסוגיות, המכנה המשותף זהה: על החוקר למקסם את התועלת מן המחקר ובמקביל למזער ככל האפשר כל נזק אפשרי למשתתפים (עקרון Beneficence and Nonmaleficence).","mnemo":"⚖️ 4 שומרי-סף אתיים לפני ניסוי: שוקלים רווח/הפסד, מסבירים הכל מראש (הסכמה מדעת), משקרים רק אם חייבים (הטעיה), ומסבירים אחר-כך (הבהרה)."},{"id":"prof2_49","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"התאימו מונח מהפרק לכלל חשיבה ביקורתית: אפקט הפלסבו, בקרה ניסויית, הטיית הצופה, הגדרות אופרציונליות, משתנים מתערבים, אפקט הציפייה.","a":"פלסבו-מצאו בסיס השוואה. בקרה ניסויית-הימנעו מהיקש מתאם=סיבתיות. הטיית הצופה-הטיות אישיות משנות תפיסה. הגדרות אופרציונליות-הגדירו מונחים בבירור. משתנים מתערבים-חפשו הסברים חלופיים. אפקט הציפייה-נסו להפריך לא רק לאשש.","explain":"(א) הימנעו מן ההיקש שלפיו מתאם הוא סיבתיות ↔ (2) בקרה ניסויית — בקרה ניסויית (הקצאה מקרית, מניפולציה) היא בדיוק מה שמאפשר להסיק סיבתיות; בלעדיה יש רק מתאם. (ב) דאגו שמונחים חשובים יוגדרו אופרציונלית ↔ (4) הגדרות אופרציונליות — התאמה ישירה. (ג) קודם שמחפשים ראיות לאישוש, נסו להפריך ↔ (6) אפקט הציפייה — הנטייה לחפש רק אישור מקבילה לאופן שבו ציפיות מובילות לראות רק את מה שמצפים לו. (ד) חפשו הסברים חלופיים ↔ (5) משתנים מתערבים — משתנה מתערב הוא בדיוק הסבר חלופי אפשרי לתוצאה. (ה) שימו לב כיצד הטיות אישיות משנות תפיסת מציאות ↔ (3) הטיית הצופה — התאמה ישירה. (ו) הטילו ספק ביעילות טיפול; מצאו בסיס השוואה ↔ (1) אפקט הפלסבו — בקרת פלסבו היא בדיוק בסיס ההשוואה הדרוש כדי לדעת אם טיפול יעיל באמת. (ניתוח התאמה של הסטודנט.)","mnemo":"🔗 6 מונחים, 6 כללי-זהב: פלסבו→מצא קבוצת-השוואה. בקרה→אל תבלבל מתאם עם סיבה. הטיית-צופה→היזהר מהמשקפיים הצבעוניות. הגדרות-אופרציונליות→תגדיר במדויק. משתנה-מתערב→חפש אורח-לא-קרוא. ציפייה→נסה להפריך, לא רק לאשש."},{"id":"prof2_50","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"באיזה שלב מתוך 7 שלבי תהליך המחקר עוסק הקטע על ביקורת עמיתים?","a":"שלב 5 — דיווח על הממצאים. כתב יד עובר ביקורת של 2-5 מומחים לפני שהוא מתקבל לפרסום.","explain":"תהליך זה נקרא ביקורת עמיתים (peer review), והוא שייך לשלב 5 מתוך שבעת שלבי תהליך המחקר — דיווח על הממצאים. כתב יד המוגש לפרסום נשלח לשניים עד חמישה מומחים בתחום, העורכים ניתוח מפורט של הרציונל, המתודולוגיה והממצאים. רק אם המומחים מאשרים את כתב היד, הוא מתקבל לפרסום. תהליך זה אינו מושלם, אך באופן כללי מבטיח שרוב המחקרים שמתפרסמים בכתבי עת מדעיים עמדו בקריטריונים מחמירים — בניגוד למידע המופיע באינטרנט, שלעיתים קרובות לא עבר בדיקה של מומחה.","mnemo":"📰 שלב 5=\"מספר לעולם\" (דיווח) - וכמו כתבה בעיתון, קודם עורך (2-5 מומחים) בודק שהיא ראויה לפרסום."},{"id":"quiz2_01","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"_______________ הוא הצעד השני בתהליך המחקר (ניתוח התוצאות / ניסוח השערה / ניסוח שאלת מחקר / הסקת מסקנות / תצפית על נתונים)","a":"ניסוח השערה (אחרי שאלת המחקר, לפני איסוף הנתונים)","explain":"השלב השני בתהליך המחקר הוא <b>ניסוח השערה</b>. השערה היא <b>טענה זמנית, הניתנת לבחינה</b>, המקשרת בין גורמים לבין תוצאות. השערות מנוסחות, לרוב, בצורת ניבוי \"<b>אם — אז</b>\", ומפרטות אילו תוצאות ספציפיות יתקבלו בתנאים מסוימים. דוגמה מהספר: \"אם ילדים יצפו בתכניות טלוויזיה שהמסרים שלהן אלימים ביותר, אז יהיו מעורבים במעשי תוקפנות רבים יותר כלפי חבריהם.\" על המחקר לאשש (או להפריך) את הקשר \"אם — אז\" הזה.","mnemo":"🔄 שלב 2 = \"מנחש\" (השערה), אחרי \"רואה\" (שאלה) ולפני איסוף נתונים."},{"id":"quiz2_02","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"______ הם מספרים שסוכמו ומעידים על הבדלים או דפוסים שנאספו במדידות (נתונים / מחקרים / תיאורים / סטטיסטיקות / הגדרות אופרציונליות)","a":"סטטיסטיקות (סיכום מספרי של נתונים גולמיים שנאספו)","explain":"<b>סטטיסטיקות</b> הן מספרים <b>שסוכמו</b> ומעידים-על הבדלים/דפוסים שנאספו-במדידות - למשל, ממוצע, חציון, סטיית-תקן. הן הכלי שהופך כמות-עצומה-של תצפיות-בודדות-וגולמיות (נתונים) למידע <b>מובן וניתן-לניתוח</b>. ⚠️ אל-תתבלבלו עם 'נתונים' - נתונים הם התצפיות-הגולמיות-הבודדות (לפני-סיכום); סטטיסטיקות הן <b>התוצר-המעובד</b> שמתקבל <b>אחרי</b> שמסכמים-ומחשבים-על-הנתונים.","mnemo":"🔢 סטטיסטיקות = נתונים גולמיים אחרי שעברו \"בלנדר\" - סוכמו למספרים ברורים."},{"id":"quiz2_03","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"אם נכנסת לקבוצת פלסבו, אז את/ה מקבל (תרופות לא פעילות / לא מקבל כלום / תרופות מסוכנות / תרופות ניסויית)","a":"תרופות לא פעילות (קבוצת הביקורת מקבלת פלסבו, לא את הטיפול הנבדק)","explain":"קבוצת-פלסבו מקבלת <b>תרופה לא-פעילה</b> (חסרת-מרכיב-טיפולי-אמיתי) - זו-בדיוק מטרתה: לשמש <b>בסיס-השוואה</b> לקבוצת-הטיפול-האמיתי. אם קבוצת-הפלסבו מראה שיפור <b>דומה</b> לקבוצת-הטיפול, זה מעיד שהשיפור נבע מ<b>האמונה/הציפייה</b> בטיפול, ולא-מהחומר-הפעיל-עצמו. ⚠️ אל-תתבלבלו: פלסבו <b>אינו</b> 'לא-מקבל-כלום' - המשתתפים מקבלים משהו-פיזי (כדור/זריקה), רק-ללא-המרכיב-הפעיל - חשוב כדי-שהם-לא-ידעו-להבחין (עיוורון) שהם-בקבוצת-הביקורת.","mnemo":"💊 קבוצת-הכדור-הדמה מקבלת כדור ריק, לא שום דבר."},{"id":"quiz2_04","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"בתגובה לשאלה האם יש להשתמש בבעלי-חיים לצורכי מחקר בפסיכולוגיה, רוב הפסיכולוגים מסכימים ש____ (מדובר על שאלה שאינה רלוונטית לדיון / הדבר אתי בכל מצב / קיימות הגבלות אתיות על השימוש בנעשה / הדבר לא אתי בכל מצב)","a":"קיימות הגבלות אתיות על השימוש בנעשה (לא איסור מוחלט, אך יש כללים מחמירים)","explain":"למחקר ניסויי שלוש מגבלות עיקריות. ראשית, ההתנהגות נבחנת לעיתים בסביבה מלאכותית עם בקרה כה מחמירה שהיא עצמה עלולה לסלף את ההתנהגות, ולכן לא תהיה דומה להתנהגות בסביבה טבעית — חלק מהעושר והמורכבות של ההתנהגות הולך לאיבוד. שנית, המשתתפים יודעים שהם נבחנים, ולכן עלולים לשנות את התנהגותם: לנסות לרצות את החוקר בניסיון \"לנחש\" את מטרת המחקר, או להתנהג אחרת מכפי שהיו מתנהגים ללא פיקוח. שלישית, קיימות סוגיות מחקר חשובות שאי אפשר לחקור בניסוי בשל בעיות אתיות — למשל, אי אפשר לבדוק בניסוי האם נטייה להתעלל בילדים עוברת מדור לדור.","mnemo":"🐭⚖️ בעלי-חיים במחקר: לא איסור מוחלט, לא הכל-מותר - יש חוקי-משחק אתיים באמצע."},{"id":"quiz2_05","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"______ מייצגת/ים תצפיות אובייקטיביות (השערות / נתונים / משתנים / תיאוריות)","a":"נתונים (עובדות/מדידות גולמיות, בניגוד לתיאוריה/השערה)","explain":"נתונים (data) הם התצפיות/המדידות הגולמיות והאובייקטיביות שנאספות במחקר - המספרים או העובדות הישירות, לפני כל פרשנות. חשוב להבחין: <b>משתנה</b> הוא הקטגוריה הנמדדת (למשל 'זמן תגובה'), <b>נתונים</b> הם הערכים הספציפיים שנאספו בפועל (למשל 0.3 שניות, 0.5 שניות...) עבור אותו משתנה אצל כל משתתף. <b>השערה</b> ו<b>תיאוריה</b> הן טענות/הסברים - דברים שהחוקר <b>מנסח</b> לפני או אחרי המחקר, לא מה שהוא <b>צופה בו</b> ישירות. לכן התשובה הנכונה היא 'נתונים' - הם הדבר היחיד מבין הארבעה שמייצג תצפית אובייקטיבית-גולמית, ללא כל פרשנות תיאורטית.","mnemo":"📏 נתונים = מה שהסרגל מראה בפועל (עובדות גולמיות), לא תיאוריה/השערה."},{"id":"quiz2_06","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"תיאוריה_______ יכולה להידחות בהנחה והשערותיה אינן מאוששות (לא יישומית / תקפה / אופרציונלית / מוצדקת / שגויה)","a":"שגויה (תיאוריה נדחית אם ההשערות הנגזרות ממנה לא מאוששות)","explain":"תיאוריה נחשבת <b>שגויה</b> ונדחית כאשר ההשערות-הספציפיות שנגזרו-ממנה נבדקו-במחקר <b>ולא-אוששו</b> (לא-נתמכו-על-ידי-הנתונים) - זהו עיקרון-ההפרכה-המדעי המרכזי: תיאוריה טובה חייבת-להיות <b>ניתנת-לבדיקה-ולהפרכה</b> (falsifiable). ⚠️ אם תיאוריה מנוסחת-כך-שאין-שום-תוצאה-אפשרית-שיכולה-להפריך-אותה, היא <b>לא-מדעית</b> מלכתחילה - זו-בדיוק הסיבה שהפרכה (לא-רק-אישוש) היא כלי-מרכזי-בשיטה-המדעית.","mnemo":"🌳 הענף נשבר (ההשערה לא אוששה) = התיאוריה שגויה."},{"id":"quiz2_07","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"חוקר ביקש לבדוק את המידה שבה נבדקים הולכים ישר לאחר שתיית 0, 3 או 5 כוסות של בירה. במחקר זה המשתנה הבלתי תלוי הינו (מידת הסבילות של הנבדק לאלכוהול / הנבדקים בקבוצה שלא שתתה בירה / מידת היכולת של הנבדק ללכת ישר / מספר הבירות שנצרכו / הנבדקים ששתו בירות)","a":"מספר הבירות שנצרכו (המשתנה שהחוקר משנה/שולט בו ישירות)","explain":"המשתנה-הבלתי-תלוי הוא הגורם שהחוקר <b>עצמו קובע ומשנה-במכוון</b> (מבצע-עליו מניפולציה). כאן, <b>מספר-כוסות-הבירה</b> (0, 3, או 5) הוא בדיוק-מה-שהחוקר-בוחר-ומקצה לכל-קבוצת-נבדקים - זהו הגורם הנחשב ל'סיבה' הנבדקת-במחקר. ⚠️ אל-תתבלבלו עם 'מידת-היכולת-ללכת-ישר' - זה יהיה המשתנה <b>התלוי</b> (מה-שהחוקר <b>מודד</b> כתוצאה, לא-מה-שהוא-קובע-מראש).","mnemo":"🎮 יד-הג'ויסטיק כאן = כמות הבירות (0/3/5) - זה מה שהחוקר בעצמו קובע."},{"id":"quiz2_08","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"משתנה_____מהווה אספקט נוסף של הסביבה, אשר עשוי להשפיע באופן מורכב על הנתונים, עליו החוקר בחר לשלוט. (תלוי / מתערב / בלתי תלוי / ניסויי / בקרה)","a":"בקרה (משתנה נוסף שהחוקר מנטרל כדי לא לבלבל תוצאות)","explain":"<b>משתנה-בקרה</b> הוא היבט-נוסף-של הסביבה/המחקר, <b>עליו החוקר בוחר לשלוט</b> ולהחזיק-קבוע לאורך-כל-המחקר - כדי-שהוא-לא-ישתנה-בין-הקבוצות ולא-יבלבל את-הפרשנות-של-התוצאות. ⚠️ אל-תתבלבלו עם משתנה-מתערב - זה יהיה גורם <b>שהחוקר לא-שם-לב-אליו-ולא-שלט-בו</b> (בעיה בלתי-מכוונת); משתנה-בקרה הוא-בדיוק ההפך: גורם ש<b>כן זוהה מראש ונשלט-במכוון</b> על-ידי-החוקר, כדי-למנוע-בעיה.","mnemo":"🔒 משתנה-בקרה = מה שנועלים קבוע בכוונה, לא נותנים לו להשתנות בכלל."},{"id":"quiz2_09","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"במחקר נבדקה רמת האושר הכללית של חולי איידס בהשוואה לחולי סרטן. במחקר זה סביר להניח שהחוקר יבחר במערך מחקר ________ (ניסויי / מתאמי / תצפית בסביבה הטבעית)","a":"מתאמי (אי אפשר לחלק אנשים אקראית לקבוצות מחלה)","explain":"המגבלה המרכזית של מחקר מתאמי היא שמתאם אינו מבטיח סיבתיות — אין להקיש מקיומו של מתאם על קיומו של קשר סיבה־תוצאה. מתאם גבוה מציין רק ששתי קבוצות נתונים קשורות זו בזו באופן שיטתי, אך אינו מבטיח שאחת גורמת לשנייה. המתאם יכול לשקף מגוון אפשרויות של סיבה־תוצאה, וייתכן גם שאין קשר סיבתי כלל בין המשתנים. דוגמה מהספר: מתאם חיובי בין שעות שינה לממוצע ציונים יכול להתפרש בלפחות שלוש דרכים שונות — (1) סטודנטים הלומדים ביעילות (ולכן מצליחים יותר) הולכים לישון מוקדם יותר; (2) סטודנטים החרדים מלימודיהם (ולכן ציוניהם נמוכים) מתקשים להירדם; (3) סטודנטים הלומדים קורסים קלים (ולכן מצליחים יותר) מצליחים גם לישון טוב יותר. כל שלוש ההסברים מתאימים לאותו מתאם — ולכן יש צורך במחקר נוסף כדי לזהות את ההסבר האמיתי.","mnemo":"🚫🎮 אי אפשר להקצות \"מחלה\" ליד-הג'ויסטיק - זה כבר קיים = מתאמי."},{"id":"quiz2_10","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"כאשר חוקר מתמקד במחקרו באדם אחד הוא עורך (ניתוח מקרה / מערך מחקר מתאמי / מערך מחקר ניסויי / תצפית ישירה)","a":"ניתוח מקרה (מחקר מעמיק על יחיד אחד, לא קבוצה)","explain":"כשחוקר מתמקד באדם-אחד (או קבוצה-קטנה-מאוד) הוא עורך <b>ניתוח-מקרה (case study)</b> - מחקר מעמיק ואינטנסיבי, המאפשר להבין-לעומק מקרה-ספציפי-ומורכב, גם-אם אי-אפשר-להכליל-ממנו לכלל-האוכלוסייה. ⚠️ אל-תתבלבלו עם מערך-מתאמי/ניסויי (אלה בודקים-קבוצות-גדולות-יותר, לא-פרט-אחד) או תצפית-ישירה (יכולה-להיות-על-קבוצה, לא-בהכרח-אדם-בודד-בלבד) - ניתוח-מקרה מוגדר-ספציפית לפי המיקוד-ביחיד/קבוצה-זעירה.","mnemo":"🔍 ניתוח מקרה = זכוכית מגדלת על אדם אחד בלבד, לא קבוצה."},{"id":"quiz2_11","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"איזה ממקדמי המתאם הבאים יחשב לחזק ביותר? (+.65 / 0 / -.78)","a":"-.78 (הערך המוחלט הגדול ביותר)","explain":"מבין +0.65, 0, ו--0.78, מקדם-המתאם <b>-0.78</b> הוא-החזק-ביותר - כי עוצמת-הקשר נמדדת לפי <b>הערך-המוחלט</b> (המרחק-מ-0), לא-לפי-הסימן. |-0.78| = 0.78, גדול-מ-|+0.65| = 0.65. ⚠️ 0 הוא-תמיד החלש-ביותר (העדר-קשר-מוחלט) - זה-בדיוק העיקרון שנלמד קודם בפרק: הסימן (+/-) מציין רק <b>כיוון</b> הקשר, בעוד <b>הערך-המספרי</b> (בהתעלם-מהסימן) מציין <b>עוצמה</b>.","mnemo":"📊 -.78 רחוק יותר מ-0 מכל האחרים (ערך מוחלט = 0.78, הגדול ביותר)."},{"id":"quiz2_12","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"על כל החוקרים לדעת שמתאם______ (מצביע על משמעותיות / לא מעיד על סיבתיות / מעיד על סיבתיות / אינו מעיד על נכונות / לא מצביע על חשיבות)","a":"לא מעיד על סיבתיות (מתאם מראה קשר, לא מוכיח שאחד גורם לשני)","explain":"מתאם <b>לא-מעיד-על-סיבתיות</b> - גם-כאשר שני-משתנים קשורים-באופן-שיטתי-וחזק, ייתכן שגורם-שלישי-נסתר מסביר-את-שניהם, או שהקשר-הפוך-ממה-שחשבנו. ⚠️ זהו אחד-העקרונות-המרכזיים-ביותר-בפרק (ונשנה בכמה שאלות): לפני-שמסיקים סיבתיות ממתאם, יש-תמיד לחפש הסברים-חלופיים - מתאם-בלבד, ללא-מניפולציה-ניסויית (הקצאה-מקרית וכו'), לעולם-לא-מספיק-כדי-להוכיח-שאחד-גורם-לשני.","mnemo":"🚫➡️ מתאם מראה שני חיצים שמצביעים זה על זה, לא שאחד דוחף את השני."},{"id":"quiz2_13","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"________ היא/הוא מערך מאורגן של מושגים, המסביר/ה תופעה או סדרה של תופעות. (הגדרה אופרציונלית / השערה / מתאם / תיאוריה)","a":"תיאוריה (מסגרת מושגים רחבה המסבירה תופעה, לא השערה בודדת)","explain":"<b>תיאוריה</b> — מערכת מאורגנת של מושגים, המסבירה תופעה או קבוצה של תופעות, ומספקת את ההקשר לניסוח שאלות מחקר. <b>דטרמיניזם</b> — ההנחה שכל האירועים (פיזיים, מנטליים והתנהגותיים) הם תוצאה של גורמים סיבתיים ספציפיים, המוגבלים לסביבת היחיד או לתוכו. <b>הקשר ביניהם:</b> דטרמיניזם הוא הנחת היסוד העומדת בבסיס רוב התיאוריות הפסיכולוגיות. חוקרים מניחים כי תהליכים מנטליים והתנהגותיים פועלים על־פי דפוסים בעלי חוקים, הניתנים לגילוי במחקר — ותיאוריות פסיכולוגיות הן, על־פי־רוב, טענות בדבר הגורמים הסיבתיים העומדים בבסיס דפוסים סדורים אלה. ללא הנחת הדטרמיניזם, לא היה טעם לחפש הסברים תיאורטיים.","mnemo":"🌳 תיאוריה = העץ השלם, לא ענף (השערה) בודד."},{"id":"quiz2_14","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"חוקר בחן את ההשערה שלפיה אנשים ישתפו פעולה פחות כאשר יימצאו בקבוצה גדולה. בניסוי שהוא מתכנן הוא ישנה את מספר האנשים בכל קבוצה. שינוי זה יהיה: (בקרת פלסבו / בקרת כפל-עיוורון / משתנה תלוי / משתנה בלתי-תלוי)","a":"משתנה בלתי-תלוי (מה שהחוקר משנה בכוונה - גודל הקבוצה)","explain":"החוקר <b>משנה בכוונה</b> את גודל-הקבוצה (בונה-קבוצות-בגדלים-שונים) - זהו בדיוק המשתנה <b>הבלתי-תלוי</b>: הגורם שהחוקר-קובע-ומשנה-במכוון, הנחשב ל'סיבה' הנבדקת (כאן, האם גודל-הקבוצה משפיע-על-שיתוף-הפעולה). ⚠️ אל-תתבלבלו עם בקרת-פלסבו/כפל-עיוורון (אלה הליכי-בקרה-ספציפיים, לא-קשורים-לגודל-קבוצה) או משתנה-תלוי (זה יהיה 'מידת-שיתוף-הפעולה' עצמה - מה-שהחוקר <b>מודד</b>, לא-מה-שהוא-קובע-מראש).","mnemo":"🎮 גודל-הקבוצה = יד-הג'ויסטיק שהחוקר עצמו משנה = בלתי-תלוי."},{"id":"quiz2_15","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"איתמר הוא עוזר מחקר. בשלב הראשון הוא נותן לכל משתתף לשתות קולה רגילה או קולה נטולת קפאין. בשלב השני הוא מודד עם שעון עצר את הזמן שלוקח למשתתפים לשחק משחק וידאו. נראה כי במחקר זה חסר/ה: (מערך מתאם / בקרת פלסבו / בקרת כפל-עיוורון / הגדרה אופרציונלית)","a":"בקרת כפל-עיוורון (לא צוין שהנבדק/הבודק לא ידעו מי קיבל מה)","explain":"בקרת כפל-עיוורון פירושה שאף המשתתף ואף עוזר המחקר אינם יודעים לאיזה תנאי (קפאין/נטול-קפאין) הוקצה כל משתתף. כאן איתמר עצמו נותן את המשקה ומודד את הזמן - הוא יודע מי קיבל מה, ולכן עלול (גם בלי כוונה) למדוד/לפרש את הביצועים באופן שונה בהתאם לציפיותיו (אפקט ציפייה של הבודק) - זה מה שחסר, לא בקרת פלסבו (ששני המשקאות כאן הם תנאים פעילים אמיתיים, לא תרופת דמה).","mnemo":"🙈 איתמר עצמו יודע מי שתה מה - חסר לו כיסוי-עיניים (כפל-עיוורון)."},{"id":"quiz2_16","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"שירלי מבקרת בחנות עתיקות. בעל החנות מסביר לה, כי ככל שחפץ קטן יותר המחיר שהוא יכול לגבות בעבורו גדול יותר. זוהי דוגמה ל: (מתאם שלילי / מקדם מתאם / מתאם חיובי / אפקט פלסבו)","a":"מתאם שלילי (ככל שגודל קטן יותר, מחיר גדול יותר - כיוונים הפוכים)","explain":"ככל שהחפץ-העתיק <b>קטן-יותר</b>, מחירו <b>גבוה-יותר</b> - שני-המשתנים (גודל ומחיר) נעים ב<b>כיוונים מנוגדים</b> - זו-בדיוק ההגדרה של <b>מתאם שלילי</b>. ⚠️ אל-תתבלבלו עם 'מקדם-מתאם' (זה-המדד-הכללי-הסטטיסטי-עצמו, לא-סוג-ספציפי-של-קשר) - השאלה מבקשת לזהות את <b>כיוון</b> הקשר (עולה-אחד-יורד-השני), וזה-בדיוק מתאם-שלילי, לא-רק 'מקדם-מתאם' באופן-כללי.","mnemo":"📉 קטן יותר ↔ יקר יותר = מגלשה הפוכה = מתאם שלילי."},{"id":"quiz2_17","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"סמדר איננה מתעניינת בסרטים. ראובן רוצה לשנות את גישתה לסרט האהוב עליו: \"בית הספר לרוקנרול\". לראובן סיכוי טוב יותר אם יבקש מסמדר לציין _______ מאפיינים ________ של הסרט. (עשרה, חיוביים / חמישה, שליליים / חמישה, חיוביים / שני, שליליים)","a":"חמישה, שליליים (הכי מעט פריטים, בכיוון שלילי - מגביר סיכוי לשינוי עמדה)","explain":"כאשר מבקשים ממישהו למנות מספר רב (חמישה) של תכונות שליליות על נושא מסוים, קשה יותר למצוא כל כך הרבה נקודות שליליות אמיתיות - קושי זה עצמו עלול לגרום לאדם להסיק ש\"אם לא הצלחתי למצוא חמישה דברים שליליים, אולי זה לא כזה נורא\", וכך העמדה שלו הופכת חיובית יותר, לא שלילית יותר.","mnemo":"🍋 הכי מעט (5, לא 10) והכי שלילי = הכי קשה למצוא, אז נראה \"סביר\" יותר בסוף = משנה עמדה."},{"id":"quiz2_18","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"ד\"ר כוהן מפתח מדד לרעב. הוא אומר: \"אני זקוק למדד אשר ינבא בדייקנות כמה מזון יאכלו אנשים בארוחה הבאה שלהם\". בדבריו מתייחס ד\"ר כוהן ל __________ של המדד (הגדרה אופרציונלית / סטנדרטיזציה / תוקף / מהימנות)","a":"תוקף (המדד צריך למדוד את מה שהוא טוען למדוד)","explain":"ד'ר-כהן זקוק למדד שינבא-<b>בדייקנות</b> את התנהגות-האכילה-בפועל (לא-רק ידווח-על-תחושת-רעב-סובייקטיבית) - זוהי-בדיוק שאלת <b>תוקף (validity)</b>: המידה-שבה מדד <b>באמת-מודד/מנבא</b> את-מה-שהוא-טוען-למדוד. ⚠️ אל-תתבלבלו עם מהימנות (זו-הייתה-שאלה-של <b>עקביות</b> המדידה - האם-מקבלים-אותה-תוצאה-שוב-ושוב, לא-שאלה-של-דיוק-בניבוי-בפועל).","mnemo":"🎯 \"ינבא בדייקנות\" = בול-עין = תוקף."},{"id":"quiz2_19","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"תמר מוטרדת מן העובדה, שרצונם של המשתתפים במחקר שלה לעשות רושם חיובי עלול להשפיע על תוצאות הניסוי. נראה שהיא משתמשת במדדים _________ (של דיווח-עצמי / תקפים / אופרציונלים / מהימנים)","a":"של דיווח-עצמי (הנבדקים מדווחים בעצמם, חשופים להטיית רצייה חברתית)","explain":"תמר מודאגת שרצון-המשתתפים-לעשות-רושם-חיובי (רצייה-חברתית) ישפיע-על-התוצאות - זו-בדיוק הבעיה-האופיינית למדדי <b>דיווח-עצמי</b> (כמו שאלונים): הנבדקים מדווחים <b>בעצמם</b> על-עצמם, ולכן חשופים-להטיית-רצייה-חברתית (עונים-לפי-מה-שנראה-להם-רצוי/מקובל, לא-לפי-האמת). ⚠️ זו הסיבה שמדדי-התנהגות (תצפית-ישירה) נחשבים-לעיתים אמינים-יותר בהקשרים-רגישים - הם לא-תלויים-בדיווח-כן-של-הנבדק-על-עצמו.","mnemo":"🗣️ \"רוצים לעשות רושם טוב\" = בעיה בדיווח-העצמי (מה שאומרים, לא מה שעושים)."},{"id":"quiz2_20","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"אלדד רוצה לבחון את ההשערה, שלפיה אנשים נוטים לתרום לצדקה ביד רחבה יותר, כאשר מזג האוויר נאה. כדי לאשש את השערתו עליו להשתמש, כנראה ב _________ (בקרת כפל-עיוורון / נתוני ארכיון / אפקט הציפייה / תצפית במעבדה)","a":"נתוני ארכיון (מידע קיים על מזג אוויר/תרומות, לא ניסוי חדש)","explain":"כדי-לבחון קשר בין מזג-אוויר לתרומה-לצדקה <b>בלי להתערב</b> במצב-הטבעי, הפתרון המעשי הוא <b>נתוני-ארכיון</b> - רישומים-קיימים (של-תרומות מארגון-צדקה) שניתן להצליב עם נתוני-מזג-אוויר-היסטוריים, מבלי ליצור מצב-מלאכותי של תצפית/ניסוי-חדש. ⚠️ אל-תתבלבלו עם 'תצפית-במעבדה' - אי-אפשר-לשלוט-במזג-האוויר-במעבדה; זהו בדיוק תרחיש-אופייני-לשימוש-בשיטה-מתאמית עם נתונים-קיימים-מהעולם-האמיתי, לא-ניסוי-מבוקר.","mnemo":"📂 מזג-אוויר+תרומות כבר קיימים בעולם = נתוני-ארכיון, לא ניסוי חדש."},{"id":"quiz2_21","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"קודם שאתם משתתפים בניסוי, על החוקר לספק לכם מידע על ההליכים, הסיכונים האפשריים והרווחים הצפויים. כל זה יאפשר לכם: (הערכת רווח מול הפסד / שיחת הבהרה / הגדרות אופרציונליות / הסכמת מדעת)","a":"הסכמת מדעת (הבנת הסיכונים/התהליך לפני הסכמה להשתתף)","explain":"מתן מידע-מלא (הליכים, סיכונים, רווחים-צפויים) <b>לפני</b> תחילת-המחקר הוא-בדיוק-מה-שמאפשר ומהווה <b>הסכמה מדעת (informed consent)</b> - המשתתפים חותמים על-הסכמתם מרצון-חופשי-ובידיעה-מלאה, ורשאים-לפרוש-בכל-עת-ללא-סנקציה. ⚠️ אל-תתבלבלו עם 'שיחת-הבהרה' (debriefing) - זו-מתרחשת <b>אחרי</b> המחקר (מסבירים-מה-קרה-בפועל), בעוד הסכמה-מדעת היא-לפני-המחקר (מסבירים-מה-עומד-לקרות).","mnemo":"📋 מידע-מראש-על-הכל = הסכמה מדעת (\"דעת\"=לפני שמתחילים, לא אחרי)."},{"id":"quiz2_22","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"בסקר שבו נשאלו חברים באגודה האמריקנית לפסיכולוגיה לדעתם על השימוש בבעלי חיים במחקר, רובם חשבו, כי: (הטעיה מכוונת איננה אתית בניסויים בבעלי חיים / אין להשתמש בבעלי חיים בניסויים בלימודי תואר ראשון / מחקרי תצפית בסביבה טבעית הם ראויים / לעולם אין להשתמש בבעלי חיים כתחליף לנבדקים אנושיים)","a":"מחקרי תצפית בסביבה טבעית הם ראויים (פחות מתערבים ומלאכותיים מניסויים מעבדתיים)","explain":"סקר שהקיף 1,188 סטודנטים לפסיכולוגיה ו-3,982 חברי האגודה האמריקנית לפסיכולוגיה מצא כי קרוב ל-80% מהמשתתפים דיווחו שמחקרי תצפית בסביבה טבעית ראויים בעיניהם. קבוצה קטנה יותר (30%-70%, תלוי בסוג בעל החיים) תמכה בכליאת חיות בכלובים למחקר. רוב המשתתפים בשתי הקבוצות (כ-60%) תמכו בשימוש בבעלי חיים בקורסי תואר ראשון, אך רק שליש חשבו שזה צריך להיות חובה. גם הסטודנטים וגם המרצים התנגדו למחקרים הכרוכים בכאב גופני או במוות.","mnemo":"🌳 סביבה-טבעית = הכי פחות מתערבים = הכי \"ראוי\" אתית."},{"id":"quiz2_23","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"חפשו תמיד הסברים ________ להסברים הברורים מאליהם (אופטימיים / שליליים / מנוגדים / חלופיים)","a":"חלופיים (תמיד לשקול הסברים נוספים, לא להסתפק במובן מאליו)","explain":"אחד-מכללי-החשיבה-הביקורתית-המרכזיים: חפשו-תמיד הסברים <b>חלופיים</b> לאלה-המובנים-מאליהם. קל למצוא-הוכחות-לאישוש כשמחפשים-הצדקה, ולכן יש-לחפש-באופן-פעיל הסברים-אחרים - במיוחד אם-ההסבר-המוצג מועיל-למי-שמציע-אותו (חשד-אינטרסים). ⚠️ עיקרון זה קשור-ישירות לבעיית-'מתאם-אינו-סיבתיות' שנלמדה-קודם - תמיד-לשקול-שהתופעה-הנצפית יכולה-להיות-מוסברת-אחרת מהמובן-מאליו-הראשוני.","mnemo":"🎩 תמיד לחפש קוסם-מתחרה נוסף (הסבר חלופי) לפני שמקבלים את ההסבר המובן-מאליו."},{"id":"quiz2_24","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"ככלל, כאשר מגישים מאמרים לפרסום בכתבי עת, הם נשלחים למומחים לצורך ניתוח מפורט. תהליך זה ידוע כ: (שיחת הבהרה / הסכמה מדעת / ביקורת עמיתים / תהליכי בקרה)","a":"ביקורת עמיתים (מומחים בתחום בודקים את המחקר לפני פרסום)","explain":"תהליך זה נקרא ביקורת עמיתים (peer review), והוא שייך לשלב 5 מתוך שבעת שלבי תהליך המחקר — דיווח על הממצאים. כתב יד המוגש לפרסום נשלח לשניים עד חמישה מומחים בתחום, העורכים ניתוח מפורט של הרציונל, המתודולוגיה והממצאים. רק אם המומחים מאשרים את כתב היד, הוא מתקבל לפרסום. תהליך זה אינו מושלם, אך באופן כללי מבטיח שרוב המחקרים שמתפרסמים בכתבי עת מדעיים עמדו בקריטריונים מחמירים — בניגוד למידע המופיע באינטרנט, שלעיתים קרובות לא עבר בדיקה של מומחה.","mnemo":"📰 מומחים בודקים כתבה לפני שהיא מתפרסמת = ביקורת עמיתים (\"עמיתים\"=מומחים מאותו תחום)."},{"id":"prof3_01","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו את תהליך האבולוציה (על־פי דארווין). התמקדו בתשובתכם בקשר שבין תורשה לסביבה בתהליך הברירה הטבעית.","a":"ברירה טבעית = הסביבה \"בוררת\" מתוך שונות תורשתית קיימת אילו פרטים ישרדו ויתרבו. תורשה (גנוטיפ) קובעת את טווח התכונות האפשריות; הסביבה קובעת אילו מהן מועילות שם. פרטים מותאמים מעמידים יותר צאצאים - תכונותיהם מתפשטות באוכלוסייה. הפנוטיפ (התוצאה בפועל) = תוצר המפגש בין תורשה לסביבה, לא של התורשה לבדה.","explain":"תהליך האבולוציה, על־פי דארווין, מתרחש באמצעות ברירה טבעית: בתוך כל אוכלוסייה קיימת שונות טבעית בתכונות (למשל, צורת המקור אצל פרושים). כאשר אוכלוסייה מתפזרת לבתי גידול שונים (הנבדלים במקורות המזון ובתנאי המחיה), הסביבה בכל בית גידול \"בוררת\" אילו פרטים ישרדו ויתרבו — אלה שתכונותיהם מתאימות טוב יותר לסביבה הספציפית שלהם. פרטים בעלי התאמה טובה יותר מעמידים יותר צאצאים, ובמרוצת הדורות עולה שכיחות התכונות המועילות באוכלוסייה, עד שנוצרים מינים חדשים ונבדלים מאותו אב קדמון משותף.\n\nהקשר בין תורשה לסביבה: התורשה (הגנוטיפ, המבנה הגנטי שיורש הפרט מהוריו) קובעת את מגוון התכונות האפשריות (למשל, טווח צורות המקור האפשריות). אך הסביבה היא זו שקובעת אילו מתוך התכונות התורשתיות הללו יתרמו להישרדות ולהצלחה רבייתית באותו מקום ספציפי — כלומר, הסביבה \"בוררת\" מתוך המגוון התורשתי הקיים. התוצאה הסופית (הפנוטיפ — ההופעה החיצונית וההתנהגות בפועל) נובעת אפוא ממפגש בין הגנוטיפ לסביבה, ולא מהגנוטיפ בלבד.\n\nדוגמה ממחקר הזוג גרנט: בצורת (1977) העדיפה פרושים גדולים בעלי מקור עבה (התאמה סביבתית לגרעינים קשים), אך שנה גשומה (1983) הפכה את המגמה לטובת פרושים קטנים — כלומר, אותה תורשה \"נבחרת\" אחרת בהתאם לשינוי בסביבה.","mnemo":"🌾 דמיינו שדה חיטה בבצורת: רק הצמחים עם שורשים עמוקים (תורשה) שורדים בקרקע היבשה הזו (סביבה). הניצולים מעבירים את הגנים שלהם הלאה - זו הברירה הטבעית."},{"id":"prof3_02","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהם גנוטיפ ופנוטיפ ומה הקשר ביניהם?","a":"גנוטיפ = המבנה הגנטי שיורשים מההורים. פנוטיפ = ההופעה החיצונית וההתנהגות בפועל. הקשר: הפנוטיפ הוא תוצר המפגש בין הגנוטיפ לסביבה - לא הגנוטיפ בלבד.","explain":"גנוטיפ הוא המבנה הגנטי שפרט יורש מהוריו בעת ההזדווגות; בסביבה מסוימת קובע הגנוטיפ את אופן התפתחות הפרט ואת התנהגותו. פנוטיפ הוא ההופעה החיצונית של הפרט ואוסף ההתנהגויות שלו בפועל. הקשר ביניהם: הפנוטיפ הוא תוצר של המפגש בין הגנוטיפ לבין הסביבה — לא הגנוטיפ בלבד קובע את הפנוטיפ, אלא ה\"מגע\" שלו עם תנאי הסביבה הספציפיים. דוגמה מהספר: הגנוטיפ של פרוש קבע את הפוטנציאל שלו, ובמגע עם הסביבה שבה גדל התפתח הפנוטיפ שלו בפועל — מקור קטן ויכולת לנקר גרעינים קטנים.","mnemo":"🧬➕🌍=👤 גנוטיפ (המתכון הכתוב) + סביבה (התנאים) = פנוטיפ (העוגה שיוצאת בפועל). לא ניתן לאפות עוגה רק מהמתכון."},{"id":"prof3_03","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו את המשפט: \"לו הייתה הסביבה משופעת בגרעינים מכל הסוגים, לא הייתה לפנוטיפ זה השפעה מיוחדת על סיכויי הישרדותו\".","a":"הפנוטיפ משנה לסיכויי ההישרדות רק כשיש תחרות על משאבים מוגבלים. בשפע (כל הגרעינים זמינים), כל פנוטיפ מוצא מזון מתאים - אין יתרון סלקטיבי. במחסור (רק גרעינים קשים), רק הפנוטיפ המתאים (מקור עבה) שורד.","explain":"המשפט מבהיר תנאי הכרחי לפעולת הברירה הטבעית: הפנוטיפ (למשל, צורת המקור) משפיע על סיכויי ההישרדות רק כאשר קיימת תחרות על משאבים מוגבלים. אילו הסביבה הייתה מספקת גרעינים מכל הסוגים והגדלים בשפע, לא הייתה נוצרת תחרות — כל פרוש, יהיה מבנה מקורו אשר יהיה, היה מוצא גרעינים מתאימים לו, ולכן צורת המקור שלו לא הייתה משנה לסיכויי הישרדותו. לעומת זאת, כאשר המשאבים מוגבלים (כמו בבצורת, שבה נותרו רק גרעינים גדולים וקשים), נוצרת תחרות בין הפרושים על אותם המשאבים המצומצמים — ואז דווקא כן משנה אילו פרטים בעלי הפנוטיפ המתאים (מקור עבה, מסוגל לפצח גרעינים קשים) ישרדו ויתרבו. מכאן: פנוטיפ נותן \"יתרון סלקטיבי\" רק בהקשר של תחרות על משאבים מוגבלים — ולא כתכונה בעלת ערך מוחלט בפני עצמה.","mnemo":"🥜 מסעדה עם כל סוגי האוכל (שפע) - כל אחד מוצא מה שמתאים לו, אין יתרון. מסעדה עם תפריט אחד קשה (מחסום) - רק מי שמתאים לתפריט שורד."},{"id":"prof3_04","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד השפיעו עמידה זקופה, הגדלת נפח המוח והתפתחות השפה על ההתפתחות האנושית וההסתגלות?","a":"עמידה זקופה - שחררה ידיים לשימוש בכלים ולחקירת סביבות חדשות. הגדלת נפח המוח - אפשרה חשיבה מופשטת, הסקת מסקנות ותכנון. שפה - איפשרה למידה מניסיון הזולת והעברת חוכמה בין דורות. יחד הובילו להתפתחות תרבותית - הסתגלות מהירה באמצעות למידה, התלויה עדיין בבסיס גנטי (יכולת ללמוד ולחשוב).","explain":"עמידה זקופה על שתי רגליים — שחררה את הידיים לאחיזה בכלים ולשימושם, ואפשרה לחקור סביבות חדשות ולנצל משאבים חדשים. הגדלת נפח המוח — אפשרה תהליכים מוחיים מורכבים יותר: חשיבה מופשטת, הסקת מסקנות, זכירה ותכנון; אך גודל המוח לבדו אינו מבטיח אינטליגנציה — סוג הרקמה חשוב לא פחות. התפתחות השפה — ציון הדרך החשוב ביותר לאחר השתיים הקודמות: איפשרה מתן הוראות, אזהרה מפני סכנה, למידה מניסיון הזולת (במקום ניסוי וטעייה אישי), חיזוק קשרים חברתיים, והכי חשוב — העברת חוכמה מצטברת מדור לדור.\n\nההשלכה המשותפת על יכולת ההסתגלות: שילוב שלוש התכונות הוביל להתפתחות תרבותית — נטייתן של תרבויות להגיב לשינויים בסביבה על־ידי הסתגלות באמצעות למידה, ולא רק שינוי גנטי איטי. כך יכול המין האנושי להסתגל במהירות רבה לשינויים סביבתיים (למשל, ההסתגלות למחשבים אישיים תוך 20 שנה בלבד). עם זאת, ההתפתחות התרבותית עצמה תלויה בבסיס ביולוגי: אף התפתחות תרבותית לא הייתה יכולה להתרחש בלא הצפנת הגנוטיפ של היכולות ללמוד ולחשוב באופן מופשט.","mnemo":"🚶🧠🗣️ 3 שלבים בסדר עולה: קודם קמים על 2 רגליים (עמידה זקופה, ידיים משתחררות) → אז המוח גדל (חושבים) → אז מדברים ומלמדים אחד את השני (שפה+תרבות)."},{"id":"prof3_05","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו את הקשר בין המונחים: גן, דנ\"א, כרומוזום, תא, כרומוזומי מין.","a":"בגרעין כל תא נמצא דנ\"א, המאורגן ביחידות הנקראות גנים (מכילים הוראות לייצור חלבונים). הגנים ממוקמים על כרומוזומים (46 בסך הכול - 23 מהאם, 23 מהאב). כרומוזומי המין (זוג X/Y) קובעים זכריות (XY) או נקביות (XX).","explain":"בתוך הגרעין של כל תא בגוף נמצא חומר גנטי הנקרא דנ\"א. הדנ\"א מאורגן ביחידות קטנטנות הנקראות גנים, המכילים הוראות לייצור חלבונים — חלבונים אלה מווסתים תהליכים פיזיולוגיים בגוף ומביאים לידי ביטוי תכונות פנוטיפיות (מבנה גוף, כוח פיזי, אינטליגנציה ודפוסי התנהגות). הגנים נמצאים על גבי מבנים דמויי מקלות הנקראים כרומוזומים. כבר ברגע ההפריה, כל אחד יורש מהוריו 46 כרומוזומים — 23 מן האם ו-23 מן האב; כל כרומוזום מכיל אלפי גנים. הכרומוזומים של המין הם אלה המכילים את הצופן הגנטי להתפתחות תכונות זכריות או נקביות: יורשים כרומוזום X מן האם, וכרומוזום X או Y מן האב — הצירוף XX מייצר מאפיינים נקביים, והצירוף XY מייצר מאפיינים זכריים.\n\nסדר ההיררכיה מהקטן לגדול: דנ\"א (החומר הגנטי הבסיסי) — מאורגן ביחידות הנקראות גנים — הגנים ממוקמים על כרומוזומים — הכרומוזומים (46 בסך הכול, כולל זוג כרומוזומי מין) נמצאים בגרעין של כל תא בגוף.","mnemo":"📦📦📦 קופסאות בתוך קופסאות: תא ⊃ גרעין ⊃ כרומוזום (46 מקלות, חצי מכל הורה) ⊃ דנ\"א ⊃ גנים. הקופסה האחרונה (זוג X/Y) קובעת מין."},{"id":"prof3_06","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו מהם תאומים מונוזיגוטים ובמה הם נבדלים מתאומים דיזיגוטים.","a":"מונוזיגוטים = מביצית אחת שהתפצלה - זהים גנטית ב-100%. דיזיגוטים = משתי ביציות נפרדות - זהים רק ב-50% (כמו אחים רגילים).","explain":"תאומים מונוזיגוטים (MZ) נוצרים מביצית אחת שהופרתה על־ידי זרע אחד ואז התפצלה לשניים — ולכן החומר הגנטי שלהם זהה לחלוטין, ללא כל הבדל. תאומים דיזיגוטים (DZ) נוצרים משתי ביציות נפרדות, שכל אחת הופרתה על־ידי זרע נפרד — ולכן רק כ-50% מהחומר הגנטי שלהם זהה, בדיוק כמו בין כל זוג אחים או אחיות רגיל (הם אינם דומים זה לזה יותר מאחים רגילים).","mnemo":"🥚➡️👥 ביצית אחת מתפצלת לשתיים = תאומים זהים 100% (מונו=1). שתי ביציות נפרדות = תאומים כמו אחים רגילים, 50% (די=2)."},{"id":"prof3_07","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד אפשר להיעזר בתאומים מונוזיגוטים ודיזיגוטים כדי ללמוד על מידת התורשתיות של תכונות או התנהגויות?","a":"משווים עד כמה מונוזיגוטים (זהים ב-100%) דומים בתכונה מסוימת יותר מדיזיגוטים (זהים ב-50%). דמיון גבוה יותר אצל המונוזיגוטים מרמז על מרכיב גנטי חזק (תורשתיות גבוהה). דוגמה: מחקר על זיהוי זיוף במנגינות - מתאם 0.67 (MZ) מול 0.44 (DZ) - תורשתיות 0.71.","explain":"כדי לחשב אומדני תורשתיות, החוקרים קובעים באיזו מידה תאומים מונוזיגוטים דומים זה לזה בתכונה מסוימת יותר מתאומים דיזיגוטים. ההיגיון: מכיוון שמונוזיגוטים זהים גנטית לחלוטין ודיזיגוטים דומים רק ב-50%, אם המונוזיגוטים דומים משמעותית יותר מהדיזיגוטים בתכונה מסוימת, זה מרמז על מרכיב גנטי חזק בתכונה זו.\n\nדוגמה מהספר: מחקר על 136 זוגות תאומים מונוזיגוטים ו-148 זוגות דיזיגוטים, שהאזינו ל-26 מנגינות קצרות וציינו אם היו מדויקות או מעוותות. המתאם בין ציוני התאומים הזהים היה 0.67, ואילו אצל הלא-זהים היה 0.44 — הפער בין שני המתאמים הוביל לאומדן תורשתיות של 0.71, המרמז על מרכיב גנטי חזק ביכולת להבחין בצליל מדויק. חשוב לזכור: תורשתיות גבוהה אינה אומרת שלכל בני המשפחה תהיה אותה יכולת — היא רק מעידה שההבדלים בין אנשים בתכונה זו מוסברים במידה רבה על־ידי גנטיקה ולא על־ידי ניסיון חיים.","mnemo":"🎵 מחקר הזיוף המוזיקלי: זהים (100%) התאימו ב-0.67; לא-זהים (50%) רק ב-0.44. ככל שיותר גנים משותפים, יותר דמיון - זה מוכיח תורשתיות."},{"id":"prof3_08","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו נוירון?","a":"תא עצב המתמחה בקבלת מידע, עיבודו ו/או העברתו לתאים אחרים בגוף. קיימים מעל 200 סוגים, ובמוח האדם 10 בחזקת 11 עד 10 בחזקת 12 נוירונים.","explain":"נוירון הוא תא עצב המתמחה בקבלת מידע, עיבודו ו/או העברתו לתאים אחרים בגוף. הנוירונים שונים בצורתם, בגודלם, בהרכבם הכימי ובתפקודם — למעלה מ-200 סוגים שונים זוהו במוחות של יונקים, אך לכולם אותו מבנה בסיסי. במוחו של אדם קיימים בין 10 בחזקת 11 ל-10 בחזקת 12 נוירונים.","mnemo":"📮 נוירון = דוור. מקבל מכתב (מידע), קורא אותו (מעבד), ומעביר הלאה לדוור הבא. 200+ סוגי דוורים, מאות מיליארדים במוח."},{"id":"prof3_10","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו תפקיד כל אחד ממבני הנוירון: גוף התא, הדנדריטים, האקסון, הכפתורים הסופיים?","a":"דנדריטים=קבלת גירויים. גוף התא=זיהוי עוצמת הגירוי והעברתו. אקסון=הולכת המידע לאורך. כפתורים סופיים=גירוי בלוטות/שרירים/נוירונים אחרים.","explain":"דנדריטים — תפקידם הבסיסי לקבל גירויים מאיברי החוש או מנוירונים אחרים. גוף התא — מכיל את גרעין התא ואת הציטופלזמה; מזהה את אופי ועצמת הגירוי המתקבל מהדנדריטים ומעביר אותו לאקסון. אקסון — מוביל את המידע לכל אורכו (עד מטר במוח השדרה, פחות ממ\"מ במוח הגולגולת) אל הכפתורים הסופיים. כפתורים סופיים — מבנים דמויי פקעות בקצה האקסון, שבאמצעותם הנוירון מגרה בלוטות סמוכות, שרירים או נוירונים אחרים. הכיוון תמיד אחיד: מהדנדריטים, דרך גוף התא, אל האקסון ומשם לכפתורים הסופיים.","mnemo":"📮 מסע המכתב: דנדריטים=תיבת-דואר (קולט) → גוף התא=הדוור קורא (מזהה עוצמה) → אקסון=הדרך שהדוור הולך בה → כפתורים=מוסר את המכתב ליעד (שריר/בלוטה/נוירון)."},{"id":"prof3_11","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהם שלושת סוגי הנוירונים ומה תפקידם?","a":"חישתיים/סנסוריים=מהחושים למע' העצבים המרכזית. תנועתיים/מוטוריים=מהמע' המרכזית לשרירים/בלוטות. אינטרנוירונים=רוב נוירוני המוח, מקשרים בין חישתיים למוטוריים.","explain":"נוירונים חישתיים/סנסוריים — מעבירים מסרים מקולטני החושים למערכת העצבים המרכזית. נוירונים תנועתיים/מוטוריים — מעבירים מסרים ממערכת העצבים המרכזית לשרירים ולבלוטות. אינטרנוירונים — חלק הארי של הנוירונים במוח, מעבירים מסרים מנוירונים חישתיים לאינטרנוירונים אחרים או לנוירונים מוטוריים (לפחות 5,000 אינטרנוירונים לכל נוירון מוטורי).","mnemo":"➡️🧠➡️ חושי=מביא חדשות פנימה (מהעולם למוח). תנועתי=מוציא פקודות החוצה (מהמוח לשריר). אינטרנוירון=השליח שמחבר בין שני אלה בפנים (הרוב המכריע)."},{"id":"prof3_12","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו את התהליך העצבי העומד בבסיס רפלקס הרתיעה מכאב ודונו בתוך כך בכל המרכיבים המופיעים בתרשים 3.7.","a":"קולטני כאב בעור - נוירון סנסורי - אינטרנוירון במוח השדרה - נוירון מוטורי - שרירים מתכווצים ומתרחקים מהחפץ. 3 נוירונים בלבד מעורבים.","explain":"כאשר קולטני הכאב הקרובים לפני השטח של העור קולטים גירוי כאב שנגרם באמצעות חפץ חד, הם משגרים שדרים דרך נוירונים סנסוריים לאינטרנוירון במוח השדרה. האינטרנוירון מגיב בגירוי נוירונים מוטוריים, אשר מעוררים שרירים באזור המתאים בגוף. השרירים מתכווצים וגורמים לנו להתרחק מהחפץ הגורם כאב. שלושת הנוירונים בלבד מעורבים: נוירון סנסורי, אינטרנוירון, נוירון מוטורי.","mnemo":"🔥✋ נוגעים באש: קולטן כאב בעור → שליח-חוץ (סנסורי) → שליח-פנימי (אינטרנוירון בעמוד השדרה) → שליח-פעולה (מוטורי) → היד קופצת. רק 3 שליחים, בלי המוח."},{"id":"prof3_13","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע איננו מודעים לתחושת הכאב לפני הרתיעה ומדוע אין לנו שליטה על תגובת הרתיעה ברפלקס זה?","a":"הרפלקס מתבצע כולו במוח השדרה (סנסורי-אינטרנוירון-מוטורי), ללא מעורבות המוח. המוח מקבל מידע רק אחרי שהגוף כבר הגיב - לכן אין שליטה מודעת, וזה מאפשר תגובה זריזה יותר להישרדות.","explain":"רק לאחר רצף ההתרחשויות העצביות (סנסורי-אינטרנוירון במוח השדרה-מוטורי), ולאחר שהגוף כבר התרחק מהחפץ המגרה, מקבל המוח מידע על המצב. הרפלקס מתבצע כולו במוח השדרה דרך שלושת הנוירונים — ללא מעורבות המוח כלל בשלב הביצוע. לכן אין לנו שליטה מודעת: ההחלטה \"לברוח\" מתקבלת באינטרנוירון במוח השדרה, לא במוח. תחושת הכאב עצמה מתעכבת כי היא דורשת שהמידע יטפס עד למוח ויעובד שם — תהליך שלוקח זמן רב יותר מהרפלקס המהיר. במקרים שבהם ההישרדות תלויה בפעולה זריזה, זה יתרון הסתגלותי: הגוף מגיב לפני שהכאב מודע בכלל נרשם.","mnemo":"⚡ הרפלקס קורה כולו בעמוד השדרה - המוח מקבל דיווח רק אחרי המעשה, כמו הודעת SMS שמגיעה אחרי שהאירוע כבר קרה."},{"id":"prof3_14","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"היכן נמצאים תאי הגלייה, מה תפקידם המרכזי ומהם ארבעת התפקידים הנוספים שלהם?","a":"מפוזרים ברשת הנוירונים (פי 5-10 יותר מנוירונים). תפקיד מרכזי: מחזיקים נוירונים במקומם. 4 תפקידים נוספים: (1) כיוון נוירונים חדשים, (2) תחזוקה/ניקוי פסולת, (3) בידוד (מעטפת מיילין), (4) הגנה (מחסום דם-מוח).","explain":"תאי הגלייה מפוזרים בתוך רשת הנוירונים העצומה במוח — פי חמישה עד עשרה יותר מהנוירונים עצמם. תפקידם המרכזי: להחזיק את הנוירונים במקומם (מהמילה היוונית glia = דבק). ארבעה תפקידים נוספים: (1) התפתחות — עוזרים לכוון נוירונים חדשים לאזורי היעד שלהם. (2) תחזוקה — מתרבים ומנקים פסולת תאית כשנוירונים נפגעים/מתים, אוספים עודפי נוירוטרנסמיטרים. (3) בידוד — יוצרים את מעטפת המיילין סביב אקסונים, מגבירה את קצב ההולכה. (4) הגנה — מונעים מחומרים רעילים בדם להגיע למוח (אסטרוציטים יוצרים את מחסום דם־מוח).","mnemo":"👷 תאי גלייה = צוות תחזוקה של בניין (5-10 פעמים יותר מהדיירים-נוירונים). תפקיד ראשי: מחזיקים הכל במקום. + 4 עבודות: מנחים חדשים, מנקים לכלוך, מבודדים צינורות (מיילין), שומרים על השער (מחסום דם-מוח)."},{"id":"prof3_15a","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"נכון/שגוי: ככל שעצמת המוסיקה חזקה יותר, פוטנציאל הפעולה בנוירון חישה שמיעתי יהיה חזק יותר. נמקו.","a":"שגוי - חוק הכול־או־לא־כלום: גודל פוטנציאל הפעולה קבוע תמיד; עוצמה מקודדת בתדירות הירי, לא בגודל.","explain":"(א) שגוי — לפי חוק הכול־או־לא־כלום, גודלו של פוטנציאל הפעולה אינו מושפע מעצמת הגרייה לאחר שהיא עוברת את רמת הסף. כל פוטנציאל פעולה שנוצר תמיד באותו הגודל. עוצמה רבה יותר יוצרת תדירות ירי גבוהה יותר, לא פוטנציאל \"חזק יותר\".\n(ב) נכון — עוצמת הצליל אינה מקודדת בגודל פוטנציאל הפעולה (שקבוע), אלא בכמות/תדירות הפעילות העצבית. פעילות רבה יותר של הנוירונים החישתיים היא שמעידה על עוצמת הגירוי.\n(ג) שגוי — קצב התקדמות פוטנציאל הפעולה לאורך האקסון אינו אחיד בין נוירונים שונים: במהירים ביותר, 200 מטרים בשנייה; באטיים, רק 10 ס\"מ בשנייה. ההבדל תלוי בעיקר בקיום מעטפת מיילין.","mnemo":"🔊 כמו צליל אקדח - תמיד אותה העוצמה בכל ירייה (כול-או-לא-כלום), לא משנה כמה לוחצים על ההדק."},{"id":"prof3_15b","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"נכון/שגוי: בעקבות פעילות רבה יותר של נוירונים המקודדים קלט שמיעתי, נשמע צליל חזק יותר. נמקו.","a":"נכון - עוצמה מקודדת בכמות/תדירות הפעילות העצבית, לא בגודל כל פוטנציאל פעולה בודד.","explain":"התשובה <b>נכונה</b>. העיקרון החשוב כאן: פוטנציאל-הפעולה פועל לפי <b>חוק הכול-או-לא-כלום</b> - כל 'ירייה' בודדת של נוירון תמיד באותה-עוצמה, לא-משתנה. אז איך המוח מקודד <b>עוצמת-גירוי</b> (צליל-חזק לעומת-חלש)? לא דרך שינוי-גודל-הפוטנציאל-הבודד, אלא דרך <b>כמות ותדירות</b> הפעילות-העצבית הכוללת - יותר-נוירונים יורים, ובקצב-מהיר-יותר, כשהגירוי חזק-יותר. ⚠️ זו הבחנה קריטית: העוצמה מקודדת ב'קצב-האש' (rate coding), לא בגודל-האות-הבודד - כל נוירון-בודד 'צועק' באותה עוצמה תמיד, רק ה<b>תדירות</b> של הצעקות משתנה.","mnemo":"🥁 לא עוצמת כל תוף בודד, אלא כמה תופים מרעישים ביחד ובאיזו מהירות - זה מה שקובע קול חזק."},{"id":"prof3_15c","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"נכון/שגוי: תדירות פוטנציאל הפעולה לאורך האקסון זהה בכל הנוירונים. נמקו.","a":"שגוי - הקצב משתנה מאוד (200 מ' לשנייה במהירים, 10 ס\"מ לשנייה באיטיים), בעיקר בהתאם לקיום מעטפת מיילין.","explain":"התשובה <b>שגויה</b>. תדירות/מהירות פוטנציאל-הפעולה <b>משתנה מאוד</b> בין נוירונים-שונים - עד <b>200 מטר-לשנייה</b> באקסונים המהירים-ביותר, לעומת רק כ-<b>10 סנטימטר-לשנייה</b> באקסונים האיטיים-ביותר - פער עצום. הגורם-המכריע: קיום (ועובי) <b>מעטפת-המיילין</b> העוטפת את-האקסון - אקסונים <b>עטופי-מיילין</b> (הפועל כבידוד-חשמלי, כמו-ציפוי-חוט) מוליכים מהר-בהרבה מאקסונים חשופים/לא-מכוסים. ⚠️ ההיגיון האבולוציוני: אקסונים הדורשים תגובה-מהירה-קריטית (כמו רפלקסים) מכוסים-במיילין-עבה, בעוד אקסונים 'פחות-דחופים' יכולים-להסתפק בהולכה-איטית-יותר.","mnemo":"🏎️🐢 כביש-מהיר (מיילין) = 200 מ'/שנייה. כביש-עפר (חשוף) = 10 ס\"מ/שנייה. לא כל הנוירונים נוסעים באותה מהירות."},{"id":"prof3_17","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי סינפסה?","a":"רווח קטן בין הממברנה הקדם־סינפטית (כפתור סופי של הנוירון המשדר) לממברנה הבתר־סינפטית (דנדריט/גוף תא של הנוירון הקולט). שני נוירונים לעולם אינם נוגעים זה בזה ישירות.","explain":"<b>סינפסה</b> - הרווח-הזעיר בין שני-נוירונים: בין ה<b>ממברנה הקדם-סינפטית</b> (הכפתור-הסופי של הנוירון-<b>המשדר</b>, השולח-מסר) לבין ה<b>ממברנה הבתר-סינפטית</b> (פני-השטח של דנדריט/גוף-התא של הנוירון-<b>הקולט</b>, מקבל-המסר). ⚠️ נקודת-מפתח קריטית שחוזרת-ונשנית בבחינות: שני-נוירונים <b>לעולם אינם נוגעים זה-בזה ישירות</b> - יש תמיד רווח-פיזי (הסינפסה עצמה) שהמסר-הכימי (נוירוטרנסמיטר) חייב-לחצות-אותו כדי-לעבור מנוירון-לנוירון. זהו ההבדל בין 'רשת-חוטים-מחוברת' (כמו חשמל בבית) לבין המוח, שבו התקשורת היא <b>כימית</b>-בעיקרה, לא-רק חשמלית-ישירה.","mnemo":"🏝️ סינפסה = תעלת-ים קטנה בין 2 איים (נוירונים) - הם אף פעם לא נוגעים, רק שולחים \"סירות\" (נוירוטרנסמיטרים) אחד לשני."},{"id":"prof3_18","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו תהליך ההולכה הסינפטית וכיצד הוא נוצר?","a":"העברת מידע מנוירון לנוירון דרך המרווח הסינפטי. פוטנציאל הפעולה מגיע לכפתור הסופי - שלפוחיות נצמדות לממברנה - יוני סידן נכנסים - השלפוחיות פוקעות ומשחררות נוירוטרנסמיטרים - אלה חוצים את המרווח הסינפטי ונקשרים לקולטנים.","explain":"הולכה סינפטית היא העברת מידע מנוירון לנוירון דרך המרווח הסינפטי. היא נוצרת כך: כאשר פוטנציאל הפעולה מגיע לכפתור הסופי, הוא גורם לשלפוחיות סינפטיות לנוע לכיוון הממברנה הפנימית של הכפתור ולהיצמד אליה. במקביל, פוטנציאל הפעולה גורם לתעלות היונים להיפתח ולאפשר ליוני סידן להיכנס לכפתור הסופי. זרימת הסידן פנימה גורמת לפקיעת השלפוחיות ולשחרור הנוירוטרנסמיטרים שבתוכן. הנוירוטרנסמיטרים מתפזרים ועוברים את המרווח הסינפטי, ולבסוף נקשרים לקולטנים בממברנה הבתר־סינפטית.","mnemo":"📦➡️🌊➡️🔑 5 צעדים: פוטנציאל מגיע לכפתור → שלפוחיות (קופסאות) נצמדות → סידן פותח אותן → נוירוטרנסמיטר \"שוחה\" במרווח → נתפס ע\"י קולטן (כמו מפתח)."},{"id":"prof3_19","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהם שלפוחיות סינפטיות, נוירוטרנסמיטרים, מרווח סינפטי וקולטנים - והקשר ביניהם?","a":"שלפוחיות (בכפתור הסופי) מכילות נוירוטרנסמיטרים - פוקעות ומשחררות אותם - חוצים את המרווח הסינפטי - נקשרים לקולטנים בממברנה הבתר־סינפטית (כמו מפתח למנעול) - משלימים את ההולכה הסינפטית.","explain":"שלפוחיות סינפטיות — שלפוחיות עגולות קטנות בתוך הכפתור הסופי, שבתוך כל אחת מהן נמצאים נוירוטרנסמיטרים. נוירוטרנסמיטרים — חומרים ביוכימיים המגרים נוירונים אחרים; משוחררים מהשלפוחיות כשהן פוקעות. מרווח סינפטי — הרווח שבין הכפתור הסופי של נוירון אחד לממברנת התא של נוירון שני; הנוירוטרנסמיטרים חוצים אותו. קולטנים — מצויים בממברנה הבתר־סינפטית; הנוירוטרנסמיטרים נקשרים אליהם, בדומה למפתח המתאים למנעול, כדי להשלים את ההולכה הסינפטית.\n\nסיכום התהליך המלא: פוטנציאל הפעולה מגיע לכפתור הסופי — שלפוחיות סינפטיות ניצמדות לממברנה ופוקעות (בעקבות כניסת יוני סידן) — נוירוטרנסמיטרים משתחררים — חוצים את המרווח הסינפטי — נקשרים לקולטנים בממברנה הבתר־סינפטית — נותנים לנוירון הבא הוראת \"ירה!\" או \"אל תירה!\".","mnemo":"🔑🔒 נוירוטרנסמיטר = מפתח. קולטן = מנעול. רק מפתח מתאים בדיוק פותח את המנעול - זה מה שקובע לאיזה נוירון המסר מגיע."},{"id":"prof3_reflection2","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"העברת המידע לאורך הנוירון (באקסון) היא ______; העברת המידע בין נוירונים היא ______.","a":"חשמלית (זרימת יונים, פוטנציאל פעולה); כימית (נוירוטרנסמיטרים דרך הסינפסה).","explain":"העברת המידע לאורך הנוירון (באקסון) היא חשמלית — מבוססת על זרימת יונים (נתרן, אשלגן) דרך הממברנה, היוצרת דה־פולריזציה המתקדמת כאפקט דומינו לאורך האקסון (פוטנציאל הפעולה). לעומת זאת, העברת המידע בין נוירונים (דרך הסינפסה) היא כימית — מבוססת על שחרור נוירוטרנסמיטרים מהנוירון המשדר, מעבר דרך המרווח הסינפטי, והיקשרות לקולטנים בנוירון הקולט.","mnemo":"⚡ בתוך הנוירון (באקסון) = חשמל (מהיר, ישיר). בין נוירונים (בסינפסה) = כימיה (שליחים כימיים, איטי יותר)."},{"id":"prof3_20","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו תפקידו של כל אחד מהנוירוטרנסמיטרים הבאים בוויסות ההתנהגות: דופמין, אצטילכולין, גאבא, נורפינפרין, סרוטונין, אנדורפינים, גזים?","a":"דופמין=מצב רוח/דיכאון, סכיזופרניה, יכולות מוטוריות (פרקינסון), אימפולסיביות, תכנון. אצטילכולין=זיכרון(אלצהיימר)+כיווץ שרירים. גאבא=מעכב עיקרי, חרדה כשיורד, מוגבר ע\"י בנזודיאזפינים. נורפינפרין=דיכאון. סרוטונין=גזע המוח, ל.ס.ד., פרוזאק מגביר. אנדורפינים=כאב+רגשות, מתווכי דיקור/פלסבו. גזים(CO,NO)=הולכה סינפטית שונה, ללא קולטנים בתר־סינפטיים.","explain":"דופמין — מצב רוח ודיכאון (עם נורפינפרין); סכיזופרניה (רמות גבוהות מדי); יכולות מוטוריות (מחלת פרקינסון - התנוונות נוירוני הדופמין); אימפולסיביות (גנים DRD4, COMT); יציבות וגמישות קוגניטיבית (תכנון).\n\nאצטילכולין — זיכרון: אבדן הזיכרון באלצהיימר נגרם מהידרדרות נוירונים המפרישים אצטילכולין. כיווץ שרירים: משמש כמעורר בצומתי המעבר שבין עצבים לשרירים. הרעלות: רעלן בוטולינום מונע את שחרורו (בוטוליזם, עלול לגרום למוות בחנק); קוראבה נצמד לקולטניו וגורם לשיתוק שרירי הריאות.\n\nגאבא — הנוירוטרנסמיטר המעכב הנפוץ ביותר, משמש כשליח בשליש מכל הסינפסות במוח. ירידה ברמתו גורמת לפעילות־יתר עצבית המתבטאת בחרדה. הפרעות חרדה מטופלות בבנזודיאזפינים (וליום, קסנקס), המגבירים את יעילות פעולתו.\n\nנורפינפרין — קשור לסוגים מסוימים של דיכאון; תרופות המגבירות את רמתו במוח משפרות מצב רוח ומקלות דיכאון. שייך (עם דופמין) לקבוצת הקטכולאמינים.\n\nסרוטונין — כל נוירוני הסרוטונין ממוקמים בגזע המוח, הקשור בעוררות ובתהליכים אוטומטיים. השפעת ל.ס.ד. נובעת מדיכוי ההשפעות המעכבות של נוירוני הסרוטונין. תרופות נוגדות דיכאון כמו פרוזאק מגבירות את רמת פעילותו.\n\nאנדורפינים (נוירומודולטורים) — שליטה בהתנהגויות רגשיות (חרדה, פחד, מתח, הנאה) ובכאב; מתווכים חלקית את יעילותם של דיקור סיני ופלסבו בהקלת כאב (הוכח באמצעות נלוקסון).\n\nגזים (חד־תחמוצת הפחמן, תחמוצת החנקן) — קבוצה חדשה ומפתיעה; מבצעים הולכה סינפטית בצורה שונה - אינם נקשרים לקולטנים בתר־סינפטיים, אלא עוברים ישירות דרכם אל גוף הנוירון הבתר־סינפטי.","mnemo":"🎰 דופמין=מכונת-מזל (תגמול/תנועה). 💪 אצטילכולין=שריר-שזוכר (תנועה+זיכרון). 🛑 גאבא=בלם-רכב (מעכב/חרדה כשנחלש). 📉 נורפינפרין=מצב-רוח-צונח (דיכאון). 😴 סרוטונין=שינה-תיאבון-רוגע. 🩹 אנדורפינים=פלסטר-טבעי (כאב). 💨 גזים=חודרים-ישר (בלי מפתח/מנעול)."},{"id":"prof3_21","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי ההגדרה האופרציונלית של אימפולסיביות על־פי הדיון בסעיף זה? מדוע חשובה ההגדרה האופרציונלית כשבאים לבדוק את הבסיס הגנטי של תכונה זו?","a":"במחקר המתואר, אימפולסיביות מוגדרת אופרציונלית דרך ביצוע במשימות תכנון/יציבות וגמישות קוגניטיבית, הקשורות לפעילות דופמין. חשוב כי התנהגויות שונות בתוך \"אימפולסיביות\" עשויות להיות בעלות בסיסים גנטיים שונים - בלי הגדרה מדויקת, אי אפשר לדעת לאיזו התנהגות הגן קשור.","explain":"הספר אינו נותן הגדרה אחת פשוטה וסגורה — הוא מדגים דווקא את הבעיה: \"אימפולסיביות\" יכולה להתפרש בכמה דרכים שונות (חוסר תכנון מראש? אי־יכולת להימנע מהתפרצויות התנהגות מוחצנת? נטילת סיכונים מוגזמת?). ההגדרה האופרציונלית שבפועל אומצה במחקר המתואר מתמקדת בתפקוד הדופמין באזורי המוח האחראים לתכנון — כלומר, אימפולסיביות נמדדת דרך ביצועים במשימות של יציבות קוגניטיבית וגמישות קוגניטיבית, הקשורות ישירות לפעילות דופמינרגית.\n\nמדוע ההגדרה האופרציונלית חשובה למחקר גנטי: כי ייתכן שלהתנהגויות שונות המתקשרות ל\"אימפולסיביות\" (חוסר תכנון, התפרצויות, נטילת סיכונים) יש בסיסים גנטיים שונים לחלוטין. אם המחקר לא מגדיר בדיוק איזו התנהגות נמדדת, אי אפשר לדעת אם ה\"גן\" שנמצא קשור לאיזו התנהגות ספציפית — התוצאות עלולות להיות מבולבלות או מטעות.","mnemo":"📏 \"אימפולסיביות\" בלי הגדרה מדויקת = מילה מעורפלת כמו \"חם\" (חם כמה מעלות?). כאן הגדירו אותה כביצוע במשימות תכנון - סרגל מדויק."},{"id":"prof3_22","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"חשבו כיצד תורם מידע זה להבנת הצורך במחקר אובייקטיבי וברור, כפי שקראתם בפרק 2.","a":"ממחישה שמונח מעורפל (\"אימפולסיביות\") חייב הגדרה אופרציונלית מדויקת לפני מחקר מדעי - אחרת אי אפשר לדעת מה נמדד, להשוות מחקרים, או לוודא תוקף. גם מדגימה חשיבות הסבר המנגנון הסיבתי (דופמין-תכנון) ולא רק טענה כללית.","explain":"הדוגמה על אימפולסיביות ממחישה בדיוק את מה שלמדנו בפרק 2 על הגדרות אופרציונליות: מונח כללי ומעורפל כמו \"אימפולסיביות\" (בדיוק כמו \"רמת תוקפנות\" שראינו בפרק 2) חייב להיות מתורגם לפעולה מדידה קונקרטית לפני שאפשר לחקור אותו מדעית — אחרת אי אפשר לדעת מה בדיוק נחקר, ואי אפשר להשוות בין מחקרים שונים או לשחזר תוצאות.\n\nהקטע מדגים גם את חשיבות התוקף: אם כותרת עיתון אומרת \"מדענים גילו את גן האימפולסיביות\" בלי להגדיר מה נמדד בדיוק, אי אפשר לדעת אם המחקר באמת מדד את מה שהוא טוען למדוד. בנוסף, זה מדגים שהגדרה אופרציונלית ברורה מאפשרת לזהות את המנגנון הסיבתי המדויק (כאן: השפעת דופמין על יכולות תכנון) במקום להסתפק בטענה כללית (\"גן X גורם להתנהגות Y\") — בדיוק כפי שפרק 2 הדגיש שחוקרים מודרניים מעוניינים להסביר את המנגנון, לא רק לקבוע קשר.","mnemo":"🔗 אותו לקח מפרק המחקר: בלי סרגל מדויק (הגדרה אופרציונלית), אי אפשר להשוות מחקרים או לדעת מה נמדד בכלל."},{"id":"prof3_23","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד משפיעים הבדלים גנטיים על התנהגות אימפולסיבית? פרטו את האופן שבו גנים אלה משפיעים על ההתנהגות.","a":"גנים כמו DRD4 ו-COMT משפיעים על רמת הפעילות הדופמינרגית במוח. הדופמין חיוני למשימות תכנון ויציבות/גמישות קוגניטיבית. הפרעה בתפקוד הדופמין (המושפעת גנטית) - התנהגות אימפולסיבית/בלתי יציבה. ההשפעה עקיפה: גן-דופמין-תכנון-התנהגות.","explain":"ניתוחים של התנהגות אימפולסיבית התמקדו בנוירוטרנסמיטר דופמין, הפועל באזורים במוח החיוניים למשימות כמו תכנון — זהו הנוירוטרנסמיטר העוזר להגיע ליציבות קוגניטיבית ולגמישות קוגניטיבית. הפרעות בתפקוד הדופמין יכולות לגרום לבני אדם להתנהג באופן אימפולסיבי או בלתי יציב.\n\nהמנגנון המדויק: מי שרוצה למצוא בסיס גנטי לאימפולסיביות, בעצם מחפש בסיס גנטי להבדלים ברמת הפעילות הדופמינרגית המוחית בין פרטים שונים. חוקרים תיעדו וריאציות ביותר מגן אחד — DRD4 ו-COMT — המשפיעות על רמת הפעילות של הדופמין במוח. כלומר, ההשפעה אינה ישירה על \"אימפולסיביות\" כתכונה כללית, אלא עקיפה: הגן משפיע על רמת/יעילות הדופמין, זה משפיע על יכולות תכנון ויציבות קוגניטיבית, וזה בא לידי ביטוי כהתנהגות אימפולסיבית או יציבה יותר/פחות.","mnemo":"🔗⛓️ שרשרת עקיפה: גן (DRD4/COMT) ← משפיע על דופמין ← דופמין חיוני לתכנון ← בעיה בדופמין = אימפולסיביות. הגן לא \"גורם\" ישירות, הוא רק החוליה הראשונה."},{"id":"prof3_24_eeg","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי שיטת ה-EEG? מה היא בודקת ובאילו אמצעים היא משתמשת?","a":"בודקת קשר בין פעילות פסיכולוגית לתגובה מוחית ודפוסי פעילות חשמלית כוללים בקורטקס. אמצעים: אלקטרודות על פני הקרקפת, הרושמות את סך הפעילות החשמלית.","explain":"שיטות רישום והדמיה:\nEEG — בודק קשר בין פעילות פסיכולוגית לתגובה מוחית ודפוסי פעילות חשמלית כוללים בקורטקס. אמצעים: אלקטרודות על פני הקרקפת, הרושמות את סך הפעילות החשמלית.\nPET — בודק תפקוד/פעילות המוח בזמן פעילויות קוגניטיביות או התנהגותיות. אמצעים: הזרקת חומרים רדיואקטיביים בלתי מזיקים הנקלטים בתאי מוח פעילים; מכשירים מחוץ לגולגולת עוקבים אחר הרדיואקטיביות.\nMRI — בודק פרטים אנטומיים/מבניים של המוח. אמצעים: שדות מגנטיים וגלי רדיו היוצרים זרם אנרגיה.\nfMRI — בודק גם מבנה וגם תפקוד. אמצעים: גילוי שינויים מגנטיים בזרימת הדם לתאי המוח.\n\nהתערבויות במוח:\nפציעה קיימת (לדוגמה, פיניאס גייג') — בודקת קשר בין אזור שנפגע במקרה לבין שינויים בהתנהגות. אמצעים: נסיבות מקריות; אין לחוקר שליטה על מיקום/חומרת הפגיעה.\nניתוחים לאחר המוות (לדוגמה, מחקרי פול ברוקה) — בודקים קשר בין מיקום הפגיעה לליקויים בהתנהגות. אמצעים: ניתוח פתולוגי לאחר המוות.\nפגע ממוקד — בודק תפקיד אזור מוחי ספציפי. אמצעים: הסרה כירורגית/חיתוך קשרים/הרס בחום-קור-חשמל, בבעלי חיים בלבד.\nגרייה מגנטית חוזרת (rTMS) — בודקת תפקיד אזור מוחי, בהפיכות מלאה. אמצעים: פעימות גרייה מגנטית המשביתות זמנית אזור, בבני אדם.\nגרייה ישירה (לדוגמה, וולטר הס) — בודקת תגובות התנהגותיות לגירוי אזור מוחי. אמצעים: אלקטרודות מוצמדות למוח בעלי חיים, זרם חשמלי חלש.","mnemo":"🎧 EEG = אוזניות על הקרקפת שמאזינות לרעש החשמלי הכללי של כל המוח בבת אחת."},{"id":"prof3_24_pet","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי שיטת ה-PET? מה היא בודקת ובאילו אמצעים היא משתמשת?","a":"בודקת תפקוד/פעילות המוח בזמן פעילויות קוגניטיביות או התנהגותיות. אמצעים: הזרקת חומרים רדיואקטיביים בלתי מזיקים הנקלטים בתאי מוח פעילים; מכשירים מחוץ לגולגולת עוקבים אחר הרדיואקטיביות ומרכיבים תמונה דינמית.","explain":"PET (Positron Emission Tomography) — בודקת תפקוד/פעילות המוח בזמן פעילויות קוגניטיביות או התנהגותיות. אמצעים: הזרקת חומרים רדיואקטיביים בלתי-מזיקים לזרם הדם; המכשיר עוקב אחר ריכוזם באזורי מוח שונים, וכך מזהה אילו אזורים פעילים יותר בזמן משימה מסוימת.","mnemo":"💡 PET = זריקת \"נוזל זוהר\" רדיואקטיבי - האזורים הכי פעילים \"מאירים\" הכי חזק. (P=פעילות)"},{"id":"prof3_24_mri","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי שיטת ה-MRI? מה היא בודקת ובאילו אמצעים היא משתמשת?","a":"בודקת פרטים אנטומיים/מבניים של המוח. אמצעים: שדות מגנטיים וגלי רדיו היוצרים זרם אנרגיה; מקלטי רדיו עוקבים אחר תהודת האטומים בחזרתם למקומם.","explain":"<b>MRI (הדמיית תהודה מגנטית)</b> - שיטה הבודקת <b>פרטים אנטומיים/מבניים</b> של המוח (איך המוח <b>נראה</b> פיזית - לא מה-הוא-<b>עושה</b> ברגע נתון). <b>אמצעים</b>: שדות-מגנטיים-חזקים וגלי-רדיו יוצרים זרם-אנרגיה שגורם לאטומים ברקמת-המוח 'להתיישר' באופן-זמני; מקלטי-רדיו עוקבים אחר <b>תהודת-האטומים בחזרתם למקומם</b>, ומייצרים תמונה-מדויקת-של-המבנה. ⚠️ יתרון מרכזי: <b>לא-פולשני וללא-קרינה מזיקה</b> (בשונה מ-PET, המשתמש בחומרים-רדיואקטיביים) - בגלל-זה MRI בטוח-לשימוש-חוזר ולבדיקות-שגרתיות. אבל, בניגוד ל-fMRI (השאלה הבאה), MRI-רגיל <b>לא-מראה פעילות/תפקוד</b> - רק מבנה-סטטי.","mnemo":"📷 MRI = מצלמת רנטגן-מגנטית סטטית - תמונה קפואה ומדויקת של המבנה, בלי תנועה/פעילות."},{"id":"prof3_24_fmri","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי שיטת ה-fMRI? מה היא בודקת ובאילו אמצעים היא משתמשת?","a":"בודקת גם מבנה וגם תפקוד - אזורים האחראים ליכולות קוגניטיביות (קשב, תפיסה, עיבוד שפה, זיכרון). אמצעים: גילוי שינויים מגנטיים בזרימת הדם לתאי המוח (משלבת יתרונות MRI ו-PET).","explain":"<b>fMRI (הדמיה תפקודית)</b> - שיטה המשלבת <b>שני-יתרונות</b> גם-יחד: גם <b>מבנה</b> (דיוק-אנטומי-גבוה, כמו MRI-רגיל) וגם <b>תפקוד</b> (מזהה אזורים-פעילים-ברגע-נתון, כמו PET) - בודקת אילו אזורי-מוח אחראים ליכולות-קוגניטיביות ספציפיות (קשב, תפיסה, עיבוד-שפה, זיכרון) <b>בזמן-אמת</b> שהנבדק מבצע-משימה. <b>אמצעים</b>: גילוי <b>שינויים מגנטיים בזרימת-הדם</b> לתאי-המוח - כשאזור-מוחי פעיל-יותר, הוא צורך יותר-חמצן, מה-שמשנה את המאפיינים-המגנטיים של הדם-הזורם-שם, וה-fMRI מזהה שינוי-זה. ⚠️ זו הסיבה ש-fMRI היא כיום-הכלי-המועדף במחקר-קוגניטיבי: משלבת דיוק-אנטומי עם מידע-תפקודי, בלי-קרינה-מזיקה כמו PET.","mnemo":"🎥 fMRI = המצלמה (MRI) + סרט-וידאו של זרימת הדם = גם תמונה וגם סרט, מבנה+תפקוד ביחד."},{"id":"prof3_24_pציעה","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי שיטת \"פציעה קיימת\" (לדוגמה, פיניאס גייג')? מה היא בודקת ובאילו אמצעים היא משתמשת?","a":"בודקת קשר בין אזור שנפגע במקרה (תאונה) לבין שינויים בהתנהגות/אישיות. אמצעים: נסיבות מקריות בלתי מתוכננות; אין לחוקר שליטה על מיקום/חומרת הפגיעה.","explain":"שיטת \"פציעה קיימת\" — בודקת קשר בין אזור שנפגע במקרה (תאונה/פציעה טבעית) לבין שינויים בהתנהגות/אישיות שחלו לאחר מכן. אמצעים: מעקב קליני אחר המטופל, השוואת תפקודו לפני ואחרי הפגיעה. דוגמת המפתח: פיניאס גייג' - מוט חדר לאונת המצח שלו, וחל שינוי דרמטי באישיותו (הפך לקפריזי וחסר סבלנות), אך כמעט ולא נפגעו יכולותיו הפיזיות.","mnemo":"💥🎲 פציעה קיימת = תאונה אקראית (כמו פיניאס גייג') - החוקר לא תכנן כלום, רק מנתח מה שכבר קרה במקרה."},{"id":"prof3_24_ניתוחים","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי שיטת \"ניתוחים לאחר המוות\" (לדוגמה, מחקרי פול ברוקה)? מה היא בודקת ובאילו אמצעים היא משתמשת?","a":"בודקת קשר בין מיקום הפגיעה במוח לבין ליקויים בהתנהגות (כמו שפה) שהיו למטופל בחייו. אמצעים: ניתוח פתולוגי של המוח לאחר המוות, השוואה למאפייני התפקוד שתועדו בחיים.","explain":"שיטת \"ניתוחים לאחר המוות\" — בודקת קשר בין מיקום הפגיעה במוח לבין ליקויים בהתנהגות (כמו שפה) שהיו למטופל בחייו. אמצעים: לאחר מות המטופל, מנתחים את מוחו ומאתרים את מיקום הנזק המדויק, ומשווים אותו לתסמינים התנהגותיים שתועדו בחייו. דוגמת המפתח: פול ברוקה זיהה כך את האזור האחראי להפקת דיבור (אזור ברוקה) אצל מטופלו \"טאן\".","mnemo":"⚰️🔍 ניתוחים לאחר המוות (ברוקה) = בלש שפותח את הגופה אחרי המשפט, ומשווה לתסמינים שתועדו בחיים."},{"id":"prof3_24_פגע","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי שיטת \"פגע ממוקד\"? מה היא בודקת ובאילו אמצעים היא משתמשת?","a":"בודקת תפקיד אזור מוחי ספציפי על־ידי יצירת נזק מבוקר. אמצעים: הסרה כירורגית, חיתוך קשרים נוירונליים, או הרס בחום/קור/חשמל עז - בבעלי חיים בלבד (בלתי הפיך).","explain":"שיטת <b>'פגע ממוקד' (lesion)</b> - בודקת תפקיד-אזור-מוחי-ספציפי דרך <b>יצירת נזק מבוקר</b> באותו-אזור, ובחינת <b>מה-משתנה</b> בהתנהגות-בעקבות-הפגיעה - ההיגיון: אם פונקציה-מסוימת נעלמת/נפגעת אחרי-הסרת-אזור-X, סימן שאזור-X היה-אחראי-עליה. <b>אמצעים</b>: הסרה-כירורגית, חיתוך-קשרים-נוירונליים, או הרס-רקמה בעזרת חום/קור/חשמל-עז. ⚠️ מגבלה אתית קריטית: מכיוון שהנזק <b>בלתי-הפיך</b> (לא ניתן 'לתקן' לאחר-מכן), שיטה-זו מותרת <b>רק בבעלי-חיים</b>, לעולם-לא-בבני-אדם באופן-מכוון - זה בדיוק ההבדל המרכזי מ-rTMS (השאלה הבאה בפרק), שיוצרת 'פגע' <b>הפיך</b> ולכן מותרת-בבני-אדם.","mnemo":"✂️🐭 פגע ממוקד = מספריים מכוונות בכוונה - רק על בעלי-חיים (בלתי-הפיך מדי לבני-אדם)."},{"id":"prof3_24_rtms","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי שיטת הגרייה המגנטית החוזרת (rTMS)? מה היא בודקת ובאילו אמצעים היא משתמשת?","a":"בודקת תפקיד אזור מוחי בפעילות מסוימת (למשל דימוי חזותי). אמצעים: פעימות גרייה מגנטית המשביתות זמנית אזור במוח, בבני אדם, ללא נזק לרקמה.","explain":"rTMS (גרייה מגנטית חוזרת) — בודקת תפקיד אזור מוחי בפעילות מסוימת (למשל דימוי חזותי) בקרב בני אדם. אמצעים: פעימות גרייה מגנטית חוזרות דרך הגולגולת, היוצרות \"פגיעה\" זמנית והפיכה - יתרון מרכזי: מותר לשימוש בבני אדם (בשונה מפגע ממוקד קבוע), כי הנזק חולף.","mnemo":"🧲⏸️ rTMS = מגנט שלוחץ \"פאוזה\" זמנית על אזור מוחי - בטוח לבני-אדם כי זה נמחק אחרי דקות."},{"id":"prof3_24_גרייה","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי שיטת הגרייה הישירה (לדוגמה, וולטר הס)? מה היא בודקת ובאילו אמצעים היא משתמשת?","a":"בודקת אילו התנהגויות/תגובות מתעוררות כתוצאה מגירוי חשמלי של אזור מוחי מסוים. אמצעים: אלקטרודות מוצמדות למוח (בעלי חיים), שליחת זרם חשמלי חלש לאזורים ספציפיים.","explain":"שיטת הגרייה הישירה — בודקת אילו התנהגויות/תגובות מתעוררות כתוצאה מגירוי חשמלי של אזור מוחי מסוים. אמצעים: השתלת אלקטרודות במוח (בעלי חיים) והעברת זרם חשמלי חלש לאזור הנבדק, תוך תיעוד ההתנהגות שנוצרת. דוגמת המפתח: וולטר הס גרה אלפי אזורים במוחות חתולים וגילה שאפשר לחולל שינה, עוררות מינית, חרדה או אימה בהתאם למיקום הגרייה.","mnemo":"🕹️⚡ גרייה ישירה (הס) = שלט-רחוק עם חוטים למוח חתול - לוחצים כפתור, רואים איזו התנהגות קופצת."},{"id":"prof3_25a","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"איזו שיטת מחקר מתאימה לבדיקת תפקיד של מבנה מוחי כלשהו בקרב בני אדם? נמקו.","a":"rTMS - מאפשרת \"פגיעה\" זמנית והפיכה בבני אדם (בשונה מפגע ממוקד קבוע, המותר רק בבעלי חיים). אפשר לשלב עם fMRI/PET לצפייה בפעילות האזור בזמן אמת.","explain":"(א) תפקיד מבנה מוחי כלשהו בקרב בני אדם — rTMS, כיוון שהיא מאפשרת \"פגיעה\" זמנית והפיכה בבני אדם. אפשר לשלב עם fMRI/PET.\n(ב) קביעת מיקום הפגיעה במוח אדם חי — MRI, מספק תמונות מדויקות ביותר של פרטים אנטומיים, ללא פעולה פולשנית.\n(ג) רישום הפעילות החשמלית של המוח בשלמותו — EEG, אלקטרודות על הקרקפת רושמות דפוסי פעילות חשמלית כוללים.\n(ד) בדיקה לאחר המוות של מוחם של בני אדם שסבלו ממחלה — ניתוחים לאחר המוות (כמו ברוקה), השוואת מיקום הפגיעה לתסמינים שתועדו בחיים.\n(ה) בדיקת תפקוד אזור מוחי של עכברים — פגע ממוקד, מותר ליצור פגיעה בלתי הפיכה בבעלי חיים.\n(ו) גרייה של אזור במוח עכברים ובדיקת השפעתה על התנהגות — גרייה ישירה (כמו וולטר הס), אלקטרודות ושליחת זרם חשמלי חלש.","mnemo":"🧲⏸️ מקרה לבני-אדם, זמני והפיך = הפאוזה המגנטית (rTMS)."},{"id":"prof3_25b","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"איזו שיטת מחקר מתאימה לקביעת מיקום הפגיעה במוח אדם חי? נמקו.","a":"MRI - מספק תמונות מדויקות ביותר של פרטים אנטומיים/מבניים, בלי צורך בפעולה פולשנית.","explain":"לקביעת <b>מיקום-הפגיעה במוח אדם-חי</b>, השיטה המתאימה היא <b>MRI</b>: היא מספקת תמונות <b>מדויקות-ביותר</b> של פרטים-אנטומיים/מבניים, <b>בלי צורך בפעולה-פולשנית</b> (לא-חותכים, לא-מזריקים חומרים) ובלי-קרינה-מזיקה - בטוחה-לחלוטין לשימוש-על-אדם-חי. ⚠️ שימו-לב שהשאלה מבקשת <b>מיקום</b> (איפה בדיוק) ולא <b>תפקוד</b> - זו הסיבה ש-MRI (מבנה) מתאימה יותר מ-fMRI/PET (תפקוד) כאן; אם השאלה הייתה שואלת 'איזה-אזור פעיל בזמן-מטלה', התשובה הייתה משתנה.","mnemo":"📷 מיקום פגיעה, בלי לפגוע = המצלמה הסטטית (MRI)."},{"id":"prof3_25c","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"איזו שיטת מחקר מתאימה לרישום הפעילות החשמלית של המוח בשלמותו? נמקו.","a":"EEG - אלקטרודות על הקרקפת רושמות דפוסי פעילות חשמלית המהווים סך הפעילות באזורים נרחבים של קליפת המוח כולה.","explain":"לרישום <b>הפעילות-החשמלית של המוח בשלמותו</b>, השיטה המתאימה היא <b>EEG</b>: אלקטרודות המונחות על-הקרקפת (לא-פולשני) רושמות דפוסי-פעילות-חשמלית המייצגים את <b>סך-הפעילות</b> באזורים-נרחבים של קליפת-המוח-כולה, ברזולוציית-זמן גבוהה-מאוד (מזהה שינויים תוך-מילישניות). ⚠️ ⚠️ המילה-המכרעת בשאלה היא 'בשלמותו' - EEG לא-מספק דיוק-מרחבי-גבוה (לא-יודעים בדיוק איזה-נוירון-ספציפי ירה), אבל מספק תמונה-כללית-ורחבה-מאוד של הפעילות-החשמלית-הכוללת, וברזולוציית-זמן-מצוינת - זה בדיוק מה שהשאלה מבקשת.","mnemo":"🎧 כל המוח בבת אחת, חשמלי = האוזניות (EEG)."},{"id":"prof3_25d","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"איזו שיטת מחקר מתאימה לבדיקה לאחר המוות של מוחם של בני אדם שסבלו ממחלה כלשהי? נמקו.","a":"ניתוחים לאחר המוות (כמו פול ברוקה) - ניתוח פתולוגי של המוח, תוך השוואת מיקום הפגיעה לתסמינים/ליקויים שתועדו בחיי המטופל.","explain":"לבדיקה <b>לאחר-המוות</b> של מוחם-של-בני-אדם-שסבלו-ממחלה, השיטה המתאימה היא <b>ניתוחים לאחר-המוות (post-mortem)</b> - כמו-אלו שערך <b>פול ברוקה</b> ההיסטוריים: ניתוח פתולוגי-ישיר של רקמת-המוח, תוך השוואת <b>מיקום-הפגיעה</b> שנמצא (בבדיקה-פיזית-ישירה) ל<b>תסמינים/ליקויים</b> שתועדו-בחיי-המטופל (למשל, קשיי-דיבור). ⚠️ זו בעצם השיטה ההיסטורית-המקורית שהובילה לגילוי-אזור-ברוקה ואזור-ורניקה - לפני-שהיו-קיימות שיטות-הדמיה-מודרניות (MRI/fMRI), ניתוח-לאחר-מוות היה הדרך-היחידה לקשר בין-מיקום-פגיעה-מוחית לבין-תסמינים-קליניים שנצפו בחיים.","mnemo":"⚰️ אחרי המוות, השוואה לתסמינים = פתיחת הגופה (ניתוחים לאחר המוות)."},{"id":"prof3_25e","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"איזו שיטת מחקר מתאימה לבדיקת תפקוד אזור מוחי של עכברים? נמקו.","a":"פגע ממוקד - מותר ליצור פגיעה בלתי הפיכה ומבוקרת (הסרה כירורגית, חיתוך קשרים, או הרס בחום/קור/חשמל) בבעלי חיים, ולמדוד את ההשפעה על ההתנהגות.","explain":"לבדיקת <b>תפקוד אזור-מוחי-ספציפי של עכברים</b>, השיטה המתאימה היא <b>פגע ממוקד</b>: מכיוון שהבדיקה-על-בעלי-חיים (לא-בני-אדם), <b>מותר</b> ליצור פגיעה <b>בלתי-הפיכה ומבוקרת</b> (הסרה-כירורגית, חיתוך-קשרים, או הרס בחום/קור/חשמל) - ואז למדוד <b>מה-משתנה בהתנהגות</b> בעקבות-ההסרה. ⚠️ שימו-לב שההגבלה-האתית (רק-בבעלי-חיים) היא בדיוק-מה-שמכריע-כאן: אם השאלה הייתה-שואלת על אדם, פגע-ממוקד לא-היה-אפשרי-כלל, והיינו-נדרשים לשיטה-אחרת (כמו rTMS, שיוצרת נזק-הפיך-בלבד).","mnemo":"✂️🐭 עכברים, בלתי-הפיך = המספריים המכוונות (פגע ממוקד)."},{"id":"prof3_25f","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"איזו שיטת מחקר מתאימה לגרייה של אזור כלשהו במוח של עכברים ובדיקת השפעתה על התנהגותם? נמקו.","a":"גרייה ישירה (כמו וולטר הס) - הצמדת אלקטרודות למוח העכברים ושליחת זרם חשמלי חלש לאזור הנבדק, תוך תיעוד השינויים ההתנהגותיים.","explain":"ל<b>גרייה</b> של אזור-מוחי-בעכברים ובדיקת השפעתה-על-התנהגות (בניגוד-ל<b>הסרת</b>-אזור), השיטה המתאימה היא <b>גרייה ישירה</b> (כמו במחקרי <b>וולטר הס</b> ההיסטוריים): הצמדת אלקטרודות ישירות-למוח-העכברים, ושליחת <b>זרם-חשמלי-חלש</b> לאזור-הנבדק, תוך תיעוד השינויים-ההתנהגותיים-המתרחשים <b>כתוצאה מהגרייה</b> (לא מהסרתה). ⚠️ ההבדל המהותי מ'פגע-ממוקד': פגע בודק 'מה-נעלם-כשמסירים' (מסיק-לאחור); גרייה-ישירה בודקת 'מה-מתעורר-כשמפעילים' (מוכיח-קדימה) - שתי-גישות-משלימות לחקר-תפקוד-אזורי-מוח.","mnemo":"🕹️🐭 עכברים, גורמים להתנהגות לקרות = השלט-רחוק (גרייה ישירה)."},{"id":"prof3_26_מרכזית","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו תפקידה של מערכת העצבים המרכזית, ומאילו מבנים היא מורכבת?","a":"מורכבת ממוח הגולגולת ומוח השדרה. תפקידה לשלב ולתאם תפקודי הגוף, לעבד מסרים עצביים נכנסים ולשגר הוראות. מוח השדרה מתאם בין שני צדי הגוף ואחראי לרפלקסים ללא מעורבות המוח.","explain":"מערכת העצבים המרכזית (מוח הגולגולת ומוח השדרה) — תפקידה לשלב בין כל תפקודי הגוף ולתאם ביניהם, לעבד את כל המסרים העצביים הנכנסים ולשגר החוצה הוראות לחלקי הגוף השונים. מוח השדרה מתאם בין פעילות שני צדי הגוף ואחראי לרפלקסים של פעולות פשוטות ומהירות שהמוח אינו מעורב בהן.\n\nמערכת העצבים ההיקפית (רקמות עצב מחוץ למוח ולמוח השדרה) — מספקת למערכת המרכזית מידע מקולטני החישה, ומוסרת הוראות מן המוח לאיברי הגוף ולשרירים. מורכבת משתי קבוצות סיבי עצב: המערכת הסומטית והמערכת האוטונומית.\n\nמערכת העצבים הסומטית (עצבים סנסוריים ומוטוריים, רצונית) — מסדירה את פעולות שרירי השלד של הגוף (פעולות רצוניות, כמו הקלדה). שולטת בתנועה ומקבלת משוב מיידי מהגוף.\n\nמערכת העצבים האוטונומית (מערכות פנימיות, לא רצוניות) — תומכת בפעילותם התקינה של תהליכים חיוניים בסיסיים; עומדת על המשמר 24 שעות ביממה. מחולקת לשני ענפים:\nענף סימפתטי (\"פתרון בעיות מיד\") — שולט על תגובות במצבי חירום או לחץ; מעורר תגובת \"לחימה־מנוסה\": העיכול פוסק, דם זורם לשרירים, קצב הלב והנשימה מואצים.\nענף פרסימפתטי (\"תחזוקה\") — מנטר את ההפעלה השגרתית של תפקודי הגוף הפנימיים; לאחר שחלפה הסכנה, מרגיע את הגוף. מופקד על משימות תחזוקה שבשגרה כמו הרחקת פסולת, הגנה על מערכת הראייה, ושמירת אנרגיה.","mnemo":"🏛️ מע' מרכזית = \"מטה הפיקוד\" (מוח+חוט שדרה) - כאן מתקבלות כל ההחלטות והתיאום."},{"id":"prof3_26_היקפית","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו תפקידה של מערכת העצבים ההיקפית?","a":"רקמות עצב מחוץ למוח ולמוח השדרה. מספקת למערכת המרכזית מידע מקולטני חישה (עיניים, אוזניים) ומוסרת הוראות מהמוח לאיברים ולשרירים. מורכבת ממערכת סומטית ומערכת אוטונומית.","explain":"<b>מערכת העצבים ההיקפית (PNS)</b> - כוללת את <b>כל</b> רקמות-העצב <b>מחוץ</b> למוח ולחוט-השדרה (שהם המערכת-המרכזית). <b>תפקידה הכפול</b>: (1) לספק למערכת-המרכזית <b>מידע-חושי</b> מקולטני-החישה (עיניים, אוזניים, עור, וכו') - 'הכניסה'. (2) להעביר <b>הוראות-מהמוח</b> חזרה לאיברים-ולשרירים - 'היציאה'. ⚠️ המבנה החשוב-לזכור: המערכת-ההיקפית מתחלקת <b>לשתי תת-מערכות</b> - <b>סומטית</b> (רצונית, תנועות-מכוונות) ו<b>אוטונומית</b> (לא-רצונית, תפקודים-פנימיים-אוטומטיים) - שתיהן נלמדות בפירוט בשאלות-הבאות.","mnemo":"📡 היקפית = אנטנה חיצונית - מביאה חדשות מבחוץ (חושים) ומוציאה פקודות החוצה (שרירים), הכל מחוץ למטה-הפיקוד."},{"id":"prof3_26_סומטית","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו תפקידה של מערכת העצבים הסומטית?","a":"עצבים סנסוריים ומוטוריים, רצוניים - מסדירה את פעולות שרירי השלד (תנועות רצוניות), עם משוב מיידי מהגוף למוח.","explain":"<b>מערכת העצבים הסומטית</b> - תת-מערכת של המערכת-ההיקפית, הכוללת עצבים <b>סנסוריים ומוטוריים</b>, הפועלים באופן <b>רצוני</b> (בשליטה-מודעת). <b>תפקידה</b>: מסדירה את פעולת <b>שרירי-השלד</b> - כל תנועה <b>מודעת-ומכוונת</b> שאנחנו מבצעים (הליכה, הרמת-יד, כתיבה) - עם <b>משוב מיידי</b> מהגוף חזרה למוח (למשל, מרגישים-מיד את תנוחת-הזרוע תוך-כדי-תנועתה). ⚠️ 'רצונית' היא המילה-המפתח: בניגוד למערכת-האוטונומית (השאלה הבאה), כאן <b>אנחנו</b> מחליטים-במודע-מתי-ואיך-לפעול.","mnemo":"🕹️ סומטית = ג'ויסטיק ביד שלך - שרירי-שלד רצוניים, אתה שולט ומקבל משוב מיידי."},{"id":"prof3_26_אוטונומית","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו תפקידה של מערכת העצבים האוטונומית?","a":"מערכות פנימיות, לא רצוניות - תומכת בתהליכים חיוניים בסיסיים (נשימה, עיכול, עוררות) שאיננו שולטים בהם במודע. פועלת 24/7, גם בשינה ובהרדמה. מחולקת לענף סימפתטי ופרסימפתטי.","explain":"<b>מערכת העצבים האוטונומית</b> - תת-המערכת ה<b>שנייה</b> של המערכת-ההיקפית, אחראית על <b>מערכות פנימיות פועלות-לא-רצוני</b>. <b>תפקידה</b>: תומכת בתהליכים-חיוניים-בסיסיים (נשימה, עיכול, עוררות-כללית) שאיננו-שולטים-בהם-במודע - היא פועלת <b>24/7</b>, ברציפות, גם-בשינה ואפילו-בהרדמה. ⚠️ מבנה חשוב-לזכור: מתחלקת ל<b>שני ענפים מנוגדים</b> - <b>סימפתטי</b> (תגובת-חירום/לחץ, 'הילחם-או-ברח') ו<b>פרסימפתטי</b> (תחזוקה-שגרתית, הרגעה) - שני-הענפים פועלים ביחסי-איזון-הדדי, ונלמדים בפירוט בשאלות-הבאות.","mnemo":"🤖 אוטונומית = אוטומט (המילה בשם עצמו!) - פועל לבד 24/7, גם כשאתה ישן/מורדם, בלי שאתה שולט."},{"id":"prof3_26_סימפתטי","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו תפקידו של הענף הסימפתטי?","a":"\"פתרון בעיות מיד\" - שולט בתגובות חירום/לחץ (תגובת לחימה־מנוסה): עיכול פוסק, דם זורם לשרירים, קצב לב ונשימה מואצים.","explain":"הענף <b>הסימפתטי</b> - ניתן לזכור בסיסמה '<b>פתרון בעיות מיד</b>': שולט בתגובות-<b>חירום ולחץ</b>, המכונות תגובת <b>לחימה-או-מנוסה (fight-or-flight)</b>. כשהוא-פעיל: <b>העיכול פוסק</b> (זמן-לא-מתאים-לעכל כשיש-סכנה), <b>הדם זורם לשרירים</b> (מתכוננים-לפעולה-פיזית), <b>קצב-הלב והנשימה מואצים</b> (יותר-חמצן-לשרירים-מהר). ⚠️ ההיגיון האבולוציוני: כל השינויים-הפיזיולוגיים-האלה מכינים את הגוף לתגובה-מיידית-מפני-איום - זו בדיוק המערכת שפעילה-יתר-על-המידה אצל אנשים הסובלים מהפרעות-חרדה (כפי-שנלמד גם בשאלת-quiz בהמשך).","mnemo":"🚨 סימפתטי = כפתור-אזעקה אדום - לחימה-מנוסה, דם לשרירים, עיכול נעצר, הכל בשביל \"עכשיו!\"."},{"id":"prof3_26_פרסימפתטי","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו תפקידו של הענף הפרסימפתטי?","a":"\"תחזוקה\" - מנטר פעולה שגרתית של תפקודים פנימיים; לאחר חלוף הסכנה מרגיע את הגוף (עיכול מתחדש, קצב לב מואט); אחראי על הרחקת פסולת, הגנת מערכת הראייה, שימור אנרגיה.","explain":"הענף <b>הפרסימפתטי</b> - ניתן לזכור בסיסמה '<b>תחזוקה</b>': מנטר פעולה-שגרתית של תפקודים-פנימיים בזמן-רגיעה, ו<b>לאחר חלוף-הסכנה</b> (כשהענף-הסימפתטי-כבר-לא-נחוץ) מרגיע את הגוף בחזרה-למצב-רגיל - <b>העיכול מתחדש</b>, <b>קצב-הלב מואט</b>. תפקידים-נוספים: <b>הרחקת פסולת</b> מהגוף, <b>הגנת מערכת-הראייה</b> (התכווצות-אישונים ברגיעה), <b>שימור אנרגיה</b> (לא-מבזבזים-משאבים-מיותרים כשאין-סכנה). ⚠️ שני הענפים (סימפתטי+פרסימפתטי) פועלים כמו <b>מטוטלת מאוזנת</b> - כשאחד פעיל-מאוד, השני נחלש, וההפך - איזון-דינמי, לא-שני-מצבים-נפרדים-לגמרי.","mnemo":"🛋️ פרסימפתטי = כפתור-הרגעה ירוק - אחרי שהסכנה עברה, הכל חוזר לשגרה (עיכול, דופק, אנרגיה)."},{"id":"prof3_27_I","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי שכבה I במוח - מיקום, מבנים, ותפקיד מרכזי?","a":"מיקום: שקועה עמוק ביותר (הליבה). מבנים: גזע המוח, תלמוס, מוחון. תפקיד: תהליכים אוטונומיים בסיסיים (קצב לב, נשימה, בליעה, עיכול, עוררות, תנועה).","explain":"שכבה I במוח — מיקום: שקועה עמוק ביותר במוח (הליבה). מבנים: גזע המוח, תלמוס, מוחון. תפקיד מרכזי: תהליכים אוטונומיים בסיסיים ולא-רצוניים - קצב הלב, נשימה, בליעה, עיכול, עוררות ותיאום תנועה בסיסי (דרך המוחון). זוהי השכבה הקדומה ביותר מבחינה אבולוציונית, ומשותפת גם למינים פשוטים יותר.","mnemo":"🎯 שכבה I = הגרעין הכי פנימי של הבצל - גזע+תלמוס+מוחון - שרידה בסיסית (לב/נשימה/בליעה), הכי קדום אבולוציונית."},{"id":"prof3_27_II","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי שכבה II במוח - מיקום, מבנים, ותפקיד מרכזי?","a":"מיקום: עוטפת את שכבה I. מבנים: המערכת הלימבית (היפוקמפוס, אמיגדלה, היפותלמוס). תפקיד: התנהגות מוטיבציונית, מצבים רגשיים, זיכרון, ויסות חום/לחץ דם/סוכר.","explain":"<b>שכבה II</b> מתוך שלוש-שכבות-המוח (מבנה הירארכי-אבולוציוני): <b>מיקום</b> - עוטפת את שכבה-I (גזע-המוח, השכבה-הפנימית-ביותר, האחראית-על-הישרדות-בסיסית). <b>מבנים מרכזיים</b> - ה<b>מערכת הלימבית</b>: היפוקמפוס, אמיגדלה, היפותלמוס - שלושה מבנים חשובים שכל-אחד נלמד בפירוט-בשאלות-נפרדות. <b>תפקיד מרכזי</b> - <b>התנהגות מוטיבציונית</b> (רעב, עוררות-מינית), <b>מצבים-רגשיים</b> (פחד, כעס), <b>זיכרון</b> (רכישת זיכרונות-חדשים), וויסות <b>הומאוסטטי</b> (חום-גוף, לחץ-דם, סוכר-בדם). ⚠️ שכבה-II 'עוטפת' את שכבה-I ומוסיפה מעליה יכולות-רגשיות-ומוטיבציוניות מורכבות-יותר מהישרדות-בסיסית-בלבד.","mnemo":"🎯 שכבה II = השכבה האמצעית של הבצל - המערכת הלימבית - רגש+זיכרון+מוטיבציה."},{"id":"prof3_27_III","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי שכבה III במוח - מיקום, מבנים, ותפקיד מרכזי?","a":"מיקום: מקיפה את שתי השכבות הקודמות (החיצונית ביותר). מבנים: המוח הגדול, כולל קליפת המוח (קורטקס) על 4 אונותיה. תפקיד: מיקום התודעה, חשיבה מופשטת, תכנון ושפה - וגם עיבוד מידע סנסורי ותיאום תנועות (דרך אזורי הקורטקס הייעודיים - חושי/מוטורי/ראייה/שמיעה).","explain":"שכבה III במוח — מיקום: מקיפה את שתי השכבות הקודמות (החיצונית ביותר). מבנים: המוח הגדול, כולל קליפת המוח (הקורטקס) על 4 אונותיה. תפקיד: זוהי השכבה המורכבת ביותר - אחראית גם על תהליכים \"גבוהים\" (חשיבה מופשטת, תכנון, שפה, תודעה) וגם על עיבוד חושי/מוטורי (דרך הקורטקס הסומטו-סנסורי, המוטורי, הראייה והשמע - כולם חלק מאותו הקורטקס).","mnemo":"🎯 שכבה III = הקליפה החיצונית של הבצל - המוח הגדול+קורטקס - חשיבה, שפה, תודעה, וגם עיבוד חושי/תנועתי."},{"id":"prof3_28_מוארך","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו תפקיד המוח המוארך (medulla)?","a":"ממוקם בקצה העליון של מוח השדרה; מתפקד כמרכז הנשימה, לחץ הדם ופעילות הלב. נזק לו עלול לגרום למוות.","explain":"המוח המוארך (medulla) — ממוקם בקצה העליון של מוח השדרה; מתפקד כמרכז הנשימה, לחץ הדם ופעילות הלב. נזק לו עלול לגרום למוות.\nהגשר (pons) — ממוקם מעל למוח המוארך; מספק מידע למבנים אחרים בגזע המוח ולמוחון.\nתצורת הרשת (reticular formation) — רשת צפופה של תאי עצב המתפקדת כזקיף שמירה: מעוררת את הקורטקס להיות קשוב לגרייה חדשה, ושומרת על ערנות המוח גם בשינה. נזק חמור עלול לגרום לתרדמת.\nהתלמוס (thalamus) — מתעל את המידע החושי שנקלט למקום המתאים בקורטקס המוחי לעיבוד.\nהמוחון (cerebellum) — שולט על היציבה ושומר על שיווי המשקל; אחראי לתנועה חלקה ומתואמת; בעל תפקיד גם בלמידה וביצוע רצפי תנועות גוף.","mnemo":"💓 מוח מוארך = חדר-המכונות של האונייה - לב+נשימה+לחץ-דם. אם זה נפגע, האונייה טובעת (מוות)."},{"id":"prof3_28_גשר","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו תפקיד הגשר (pons)?","a":"ממוקם מעל למוח המוארך; מספק מידע למבנים אחרים בגזע המוח ולמוחון.","explain":"<b>הגשר (pons)</b> - חלק מגזע-המוח (שכבה-I), <b>ממוקם מעל למוח-המוארך</b>. <b>תפקידו</b>: מספק-מידע ומחבר-בין מבנים-שונים בגזע-המוח לבין <b>המוחון</b> - מסייע בתיאום תהליכים כמו שינה, ערנות, ותנועה. ⚠️ שם המבנה ('גשר') מרמז-בדיוק-על-תפקידו: הוא משמש כ<b>נקודת-מעבר/חיבור</b> בין אזורי-מוח-שונים - בדיוק-כמו-גשר-פיזי המחבר-בין-שני-צדדים.","mnemo":"🌉 גשר = בדיוק כמו השם - מגשר ומעביר מידע בין גזע המוח למוחון."},{"id":"prof3_28_רשת","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו תפקיד תצורת הרשת (reticular formation)?","a":"רשת צפופה של תאי עצב המתפקדת כזקיף שמירה: מעוררת את הקורטקס להיות קשוב לגרייה חדשה, ושומרת על ערנות המוח גם בשינה. נזק חמור עלול לגרום לתרדמת.","explain":"<b>תצורת הרשת (reticular formation)</b> - רשת <b>צפופה</b> של תאי-עצב, העוברת דרך-אורכו-של גזע-המוח. <b>התפקיד</b> - פועלת כ'<b>זקיף-שמירה</b>': (1) מעוררת את הקורטקס להיות <b>קשוב</b> לגרייה-חדשה/משמעותית שמופיעה. (2) שומרת על <b>ערנות-בסיסית</b> של המוח, <b>גם בשינה</b> (מוודאת שהמוח 'לא מנותק לגמרי'). ⚠️ נקודה קלינית חשובה: <b>נזק חמור</b> לתצורת-הרשת עלול לגרום ל<b>תרדמת</b> - כי המבנה הזה קריטי-לשמירה-על-רמת-הכרה-בסיסית בכלל, לא-רק-על-איכות-הקשב.","mnemo":"💂 תצורת רשת = זקיף-לילה - נשאר ער ומעיר את הקורטקס לכל גירוי חדש, גם כשאתה ישן."},{"id":"prof3_28_תלמוס","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו תפקיד התלמוס (thalamus)?","a":"מתעל את המידע החושי שנקלט למקום המתאים בקורטקס המוחי לעיבוד (למשל, מעביר מידע מהעיניים לאזורי הראייה הקורטיקליים).","explain":"<b>התלמוס (thalamus)</b> - מתפקד כ'<b>תחנת-ממסר</b>' מרכזית: <b>מתעל</b> את המידע-החושי הנקלט <b>למקום-המתאים</b> בקורטקס-המוחי לצורך-עיבוד-נוסף. הדוגמה: מעביר מידע-חזותי מהעיניים <b>ספציפית</b> לאזורי-הראייה-הקורטיקליים (לא-לאזורים-אחרים). ⚠️ יוצא-מן-הכלל חשוב-לזכור: התלמוס משמש תחנת-ממסר <b>לכל החושים חוץ מריח</b> - חוש-הריח (בניגוד לכל-שאר-החושים) עוקף את התלמוס ומגיע ישירות-למערכת-הלימבית - זו הסיבה שריחות מעוררים תגובות-רגשיות-כה-מיידיות-ועוצמתיות (זיכרון קשור-לריח).","mnemo":"🚦 תלמוס = צומת-תמרורים - מפנה כל מידע חושי לכביש הנכון בקורטקס (חוץ מריח)."},{"id":"prof3_28_מוחון","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו תפקיד המוחון (cerebellum)?","a":"שולט על היציבה ושומר על שיווי המשקל; אחראי לתנועה חלקה ומתואמת. גם בעל תפקיד בלמידה וביצוע רצפי תנועות גוף.","explain":"<b>המוחון (cerebellum)</b> - שולט על <b>היציבה</b> ושומר על <b>שיווי-המשקל</b>; אחראי ל<b>תנועה חלקה ומתואמת</b> (לא-מקוטעת/מקרטעת). <b>תפקיד-נוסף חשוב</b>: מעורב ב<b>למידת רצפי-תנועות-גוף</b> - כשלומדים מיומנות-מוטורית-מורכבת (כמו נגינה, ריקוד, נהיגה) ומתרגלים-אותה שוב-ושוב עד-שהיא-הופכת-לאוטומטית, המוחון הוא-שאחראי-לתהליך-הזה. ⚠️ קישור לפרק-הקוגניציה (פרק 7): זה בדיוק המבנה-הביולוגי שעומד מאחורי ההפיכה של 'תהליכים-מבוקרים' ל'תהליכים-אוטומטיים' דרך-תרגול, במיוחד עבור-מיומנויות-מוטוריות.","mnemo":"🤸 מוחון = מאמן-כושר - שיווי משקל, תנועה חלקה, ולומד רצפי תנועה (כמו ריקוד)."},{"id":"prof3_29_היפוקמפוס","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו תפקיד ההיפוקמפוס?","a":"הגדול במבני המערכת הלימבית; ממלא תפקיד מרכזי ברכישת זיכרונות חדשים (זיכרון לטווח ארוך). נזק לו (כמו במקרה ה\"מ) פוגע ביכולת ליצור זיכרונות חדשים, אך עדיין מאפשר לימוד מיומנויות חדשות.","explain":"ההיפוקמפוס — הגדול במבני המערכת הלימבית; ממלא תפקיד מרכזי ברכישת זיכרונות חדשים (זיכרון לטווח ארוך). נזק לו (כמו במקרה ה\"מ) פוגע ביכולת ליצור זיכרונות חדשים, אך עדיין מאפשר לימוד מיומנויות חדשות.\nהאמיגדלה — ממלאת תפקיד בבקרה רגשית וביצירת זיכרונות רגשיים; חשובה להבחנה בתוכן הרגשי של הבעות פנים, במיוחד זיהוי פחד ואיום/סכנה.\nההיפותלמוס — מבנה קטן אך חיוני; מווסת התנהגות מוטיבציונית (אכילה, שתייה, ויסות חום, עוררות מינית) ושומר על הומאוסטזיס. מווסת גם את המערכת ההורמונלית.","mnemo":"📸 היפוקמפוס = מצלמה שיוצרת זיכרונות חדשים - בלעדיה (מקרה ה\"מ), אין תמונות חדשות בכלל, אך מיומנויות ישנות נשארות."},{"id":"prof3_29_אמיגדלה","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו תפקיד האמיגדלה?","a":"ממלאת תפקיד בבקרה רגשית וביצירת זיכרונות רגשיים. חשובה להבחנה בתוכן הרגשי של הבעות פנים, במיוחד זיהוי פחד ואיום/סכנה.","explain":"<b>האמיגדלה</b> - חלק מהמערכת-הלימבית (שכבה-II), ממלאת תפקיד <b>מרכזי בבקרה-רגשית וביצירת-זיכרונות-רגשיים</b>. <b>תפקיד-ספציפי חשוב</b>: חשובה-במיוחד ל<b>הבחנה בתוכן-הרגשי</b> של הבעות-פנים - במיוחד <b>זיהוי-פחד</b> ו<b>איום/סכנה</b>. ⚠️ קישור-לפרק-ההפרעות-הפסיכולוגיות (פרק 13): כפי-שנלמד-שם, פעילות-חריגה/יתר-של-האמיגדלה קשורה-ישירות להפרעות-חרדה ולתגובות-פחד-מוגזמות - זה בדיוק המבנה-הביולוגי המסביר את הרגישות-המוגברת-לאיום שמאפיינת הפרעות-אלה.","mnemo":"🚨😨 אמיגדלה = גלאי-פחד - מזהה סכנה בהבעות פנים ויוצרת זיכרון רגשי (\"זה מפחיד!\")."},{"id":"prof3_29_היפותלמוס","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו תפקיד ההיפותלמוס?","a":"מבנה קטן אך חיוני; מווסת התנהגות מוטיבציונית (אכילה, שתייה, ויסות חום, עוררות מינית) ושומר על הומאוסטזיס (איזון פנימי). מווסת גם את המערכת ההורמונלית.","explain":"<b>ההיפותלמוס</b> - מבנה <b>קטן אך חיוני-ביותר</b> (חלק מהמערכת-הלימבית): מווסת <b>התנהגות-מוטיבציונית</b> (אכילה, שתייה, ויסות-חום-גוף, עוררות-מינית) ושומר על <b>הומאוסטזיס</b> (איזון-פנימי-כללי של הגוף). <b>תפקיד-נוסף קריטי</b>: מווסת גם את <b>המערכת ההורמונלית כולה</b>, דרך שליטה-בבלוטת-יותרת-המוח ('בלוטת-העל'). ⚠️ זה בדיוק המבנה שמקשר בין ה<b>מערכת העצבית</b> (מהירה, חשמלית) לבין ה<b>מערכת ההורמונלית</b> (איטית-יותר, כימית) - 'תחנת-הממסר' המרכזית בין שתי-המערכות-הגדולות-של-הגוף.","mnemo":"🌡️ היפותלמוס = תרמוסטט הגוף - אוכל/שותה/חום/מין - כל מה שצריך לאזן כדי לשרוד (הומאוסטזיס) + שולט בהורמונים."},{"id":"prof3_30_מצח","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו תפקיד אונת המצח (frontal lobe)?","a":"מעורבת בבקרת תנועה ובפעילויות קוגניטיביות: תכנון, קבלת החלטות, הצבת יעדים. כוללת את אזור ברוקה. פגיעה בה (כמו אצל פיניאס גייג') משנה באופן דרמטי אישיות והתנהגות.","explain":"אונת המצח — מעורבת בבקרת תנועה ובפעילויות קוגניטיביות: תכנון, קבלת החלטות, הצבת יעדים. כוללת את אזור ברוקה. פגיעה בה (כמו אצל פיניאס גייג') משנה באופן דרמטי אישיות והתנהגות.\nאונת הקדקוד — ממוקמת מאחורי המענית המרכזית; אחראית על תחושות מגע, כאב וחום.\nאונת העורף — ממוקמת בצד האחורי של הראש; היעד הסופי של מידע חזותי.\nאונת הרקה — נמצאת מתחת לחריץ הצדי; אחראית על תהליכי השמיעה. כוללת את אזור ורניקה.\nאזור ברוקה — ממוקם באונת המצח; אחראי על יצירת דיבור. פגיעה בו גורמת לאפזיית ברוקה.\nאזור ורניקה — ממוקם באונת הרקה; אחראי על הבנת השפה. פגיעה בו גורמת לשיבושים בהבנת השפה.\nהקורטקס המוטורי — נמצא לפני המענית המרכזית באונת המצח; מבקר את פעולת 600+ השרירים הרצוניים.\nהקורטקס הסומטי־סנסורי — ממוקם מאחורי המענית המרכזית באונת הקדקוד; מעבד מידע על טמפרטורה, מגע, תנוחת גוף וכאב.\nקורטקס הראייה — נמצא באונת העורף; מעבד מידע חזותי.\nקורטקס השמע — נמצא בשתי אונות הרקה; קולט מידע משתי האוזניים ואחראי על הבנת השפה.","mnemo":"📋 אונת המצח = משרד-המנהל - תכנון, החלטות, אישיות (פיניאס גייג' נפגע כאן ואישיותו השתנתה)."},{"id":"prof3_30_קדקוד","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו תפקיד אונת הקדקוד (parietal lobe)?","a":"ממוקמת מאחורי המענית המרכזית; אחראית על תחושות מגע, כאב וחום.","explain":"<b>אונת הקדקוד (parietal lobe)</b> - ממוקמת <b>מאחורי המענית-המרכזית</b> (החריץ המפריד בין אונת-המצח לאונת-הקדקוד). <b>תפקידה</b>: אחראית על עיבוד <b>תחושות מגע, כאב וחום</b> - כוללת את <b>הקורטקס הסומטו-סנסורי</b> (הנלמד בפירוט בשאלה-נפרדת בהמשך). ⚠️ מיקום מדויק-לזכור: מיד <b>מאחורי</b> המענית-המרכזית - זה מבדיל אותה מאונת-המצח (שנמצאת <b>לפני</b> אותה חריץ ואחראית-על-תנועה, לא-תחושה).","mnemo":"✋ אונת הקדקוד = חיישן-מגע על הראש (ליד הקוד-קוד שממנו השם) - מגע, כאב, חום."},{"id":"prof3_30_עורף","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו תפקיד אונת העורף (occipital lobe)?","a":"ממוקמת בצד האחורי של הראש; היעד הסופי של מידע חזותי.","explain":"<b>אונת העורף (occipital lobe)</b> - ממוקמת ב<b>צד-האחורי</b> של הראש (הכי-רחוק-מהפנים). <b>תפקידה</b>: היא ה<b>יעד הסופי</b> של <b>מידע חזותי</b> - כאן מעובד-סופית מה-שהעיניים-רואות, אחרי-שעבר-דרך התלמוס. ⚠️ 'יעד-סופי' היא מילת-המפתח: מידע-חזותי מתחיל בעיניים, עובר-דרך-התלמוס (תחנת-ממסר), ומגיע-לבסוף לעיבוד-מלא-ומודע דווקא-כאן, באונת-העורף - האזור-הרחוק-ביותר-פיזית מהעיניים-עצמן, אך זה-בדיוק-איפה-שאנחנו 'רואים' במובן-המודע-והמלא.","mnemo":"👁️ אונת העורף = מסך-הקולנוע האחורי - כל המידע החזותי \"מוקרן\" כאן בסוף המסלול."},{"id":"prof3_30_רקה","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו תפקיד אונת הרקה (temporal lobe)?","a":"נמצאת מתחת לחריץ הצדי; אחראית על תהליכי השמיעה. כוללת את אזור ורניקה.","explain":"<b>אונת הרקה (temporal lobe)</b> - נמצאת <b>מתחת לחריץ-הצדי</b> (בערך בגובה-האוזניים, בצדי-הראש). <b>תפקידה</b>: אחראית על <b>תהליכי-השמיעה</b> - כוללת את <b>אזור-ורניקה</b> (האחראי-להבנת-שפה, נלמד-בפירוט בשאלה-נפרדת). ⚠️ מיקום הגיוני-לזכור: אונת-הרקה נמצאת <b>קרוב-פיזית לאוזניים</b> - הגיוני שזהו-האזור-האחראי-על-עיבוד-שמיעתי, כולל-הבנת-דיבור (דרך-אזור-ורניקה שבתוכה).","mnemo":"👂 אונת הרקה = ליד האוזן ממש (רקה=רקת הראש, קרוב לאוזן) - שמיעה + הבנת שפה (ורניקה)."},{"id":"prof3_30_ברוקה","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו תפקיד אזור ברוקה?","a":"ממוקם באונת המצח; אחראי על יצירת דיבור. פגיעה בו גורמת לאפזיית ברוקה (קושי בהפקת שפה).","explain":"<b>אזור ברוקה</b> - ממוקם ב<b>אונת המצח</b> (לא-ברקה!). <b>תפקידו</b>: אחראי על <b>יצירת דיבור</b> - ה<b>הפקה-המוטורית</b> של שפה (איך-מדברים-בפועל, לא-הבנת-מה-ששומעים). <b>פגיעה בו</b> גורמת ל<b>אפזיית ברוקה</b> - קושי משמעותי בהפקת-דיבור-שוטף (מדברים באיטיות/קטיעה), <b>אך ההבנה נשארת תקינה-יחסית</b>. ⚠️ ההבחנה החשובה-ביותר בפרק (חוזרת-בבחינות): ברוקה=<b>הפקה</b> (אונת-מצח); ורניקה=<b>הבנה</b> (אונת-רקה) - שתי-פונקציות-שפה-שונות-לגמרי, במיקומים-שונים.","mnemo":"🗣️➡️ ברוקה = ליד הפה (אונת המצח) - בונה ומפיק דיבור. פגיעה=מדבר בקושי (\"ברוקה=שבור הדיבור\")."},{"id":"prof3_30_ורניקה","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו תפקיד אזור ורניקה?","a":"ממוקם באונת הרקה; אחראי על הבנת השפה. פגיעה בו גורמת לשיבושים בהבנת השפה (גילה קרל ורניקה ב-1874).","explain":"<b>אזור ורניקה</b> - ממוקם ב<b>אונת הרקה</b> (בניגוד-לברוקה שבאונת-המצח). <b>תפקידו</b>: אחראי על <b>הבנת השפה</b> - לא-על-הפקתה. <b>פגיעה בו</b> גורמת ל<b>אפזיית ורניקה</b> - שיבושים-קשים בהבנת-שפה, כאשר (בניגוד-לברוקה) <b>הדיבור-עצמו נשאר שוטף</b>, אך <b>חסר-משמעות-אמיתית</b> (מדברים 'בשטף' אך המשפטים לא-מסתדרים-הגיונית). ⚠️ תגלית היסטורית: <b>קרל ורניקה</b> גילה את-האזור-הזה ב-<b>1874</b> - מאוחר-יחסית לגילוי-ברוקה, וחיזק את התובנה שהמוח מחלק שפה לתת-פונקציות-נפרדות-ומקומיות.","mnemo":"👂➡️🧩 ורניקה = ליד האוזן (אונת הרקה) - מבין משמעות. פגיעה=מדבר שוטף אך חסר-הבנה/משמעות."},{"id":"prof3_30_מוטורי","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו תפקיד הקורטקס המוטורי?","a":"נמצא לפני המענית המרכזית באונת המצח; מבקר את פעולת 600+ השרירים הרצוניים. חלקים גדולים במיוחד מוקדשים לאצבעות ולשרירי הדיבור.","explain":"<b>הקורטקס המוטורי</b> - נמצא <b>לפני</b> המענית-המרכזית, ב<b>אונת המצח</b>. <b>תפקידו</b>: <b>מבקר את פעולת 600+ השרירים הרצוניים</b> בגוף - כל תנועה-מודעת שאנחנו מבצעים נשלטת מכאן. <b>חלוקת-שטח לא-שווה</b>: חלקים <b>גדולים במיוחד</b> בקורטקס-המוטורי מוקדשים ל<b>אצבעות</b> ול<b>שרירי-הדיבור</b> - הרבה יותר-שטח-יחסי מאשר, למשל, לשרירי-הגב (שהם גדולים-פיזית אך דורשים-פחות-דיוק-תנועתי). ⚠️ ההיגיון: כמות-השטח-בקורטקס תואמת את <b>מידת-הדיוק-הנדרשת</b> בשליטה על-אותו-חלק-גוף, לא-את-גודלו-הפיזי - אצבעות ושפתיים דורשים תנועות-עדינות-ומורכבות-ביותר.","mnemo":"🎹 קורטקס מוטורי = פסנתרן - שולט ב-600+ שרירים, אצבעות מקבלות הכי הרבה \"מקשים\" (שטח) כי צריך דיוק."},{"id":"prof3_30_סנסורי","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו תפקיד הקורטקס הסומטי־סנסורי?","a":"ממוקם מאחורי המענית המרכזית באונת הקדקוד; מעבד מידע על טמפרטורה, מגע, תנוחת גוף וכאב. השטח הגדול ביותר מוקדש לשפתיים, לשון, אגודל ואצבע מורה.","explain":"<b>הקורטקס הסומטו-סנסורי</b> - ממוקם <b>מאחורי</b> המענית-המרכזית, ב<b>אונת הקדקוד</b>. <b>תפקידו</b>: מעבד מידע על <b>טמפרטורה, מגע, תנוחת-גוף, וכאב</b>. <b>חלוקת-שטח לא-שווה</b> (בדיוק כמו הקורטקס-המוטורי הסמוך-לו): השטח-הגדול-ביותר מוקדש ל<b>שפתיים, לשון, אגודל ואצבע-מורה</b> - האזורים-הרגישים-ביותר-למגע בגוף-האדם. ⚠️ קורטקס-מוטורי (לפני-המענית) וקורטקס-סומטו-סנסורי (אחרי-המענית) 'שכנים' פיזית וכמעט-מראה-מדויק זה-של-זה - שני-'מפות-גוף' צמודות, אחת-לתנועה ואחת-לתחושה.","mnemo":"👄 קורטקס סנסורי = מפת-מגע - הכי הרבה שטח לשפתיים/לשון/אגודל, כי שם המגע הכי רגיש."},{"id":"prof3_30_ראייה","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו תפקיד קורטקס הראייה?","a":"נמצא באונת העורף; מעבד מידע חזותי. השטח הגדול ביותר מוקדש למידע מהמרכז המדויק ביותר של הרשתית.","explain":"<b>קורטקס הראייה</b> - נמצא ב<b>אונת העורף</b>, ומעבד <b>מידע חזותי</b> המגיע מהעיניים (דרך-התלמוס, תחנת-הממסר). <b>חלוקת-שטח לא-שווה</b>: השטח-הגדול-ביותר מוקדש למידע המגיע מה<b>מרכז המדויק-ביותר של הרשתית</b> (הפוביאה - האזור-בעל-החדות-הראייתית-הגבוהה-ביותר). ⚠️ ההיגיון זהה לקורטקס-המוטורי/סנסורי: מקדישים-יותר-'שטח-עיבוד' לאזורים-הדורשים-דיוק-גבוה - מרכז-שדה-הראייה (שבו רואים-בחדות-מרבית) מקבל ייצוג-קורטיקלי גדול-בהרבה מהיקף-שדה-הראייה (ראייה-פריפרית, מטושטשת-יותר-מטבעה).","mnemo":"🎯 קורטקס ראייה = מסך-עורף - הכי הרבה שטח למרכז הראייה החד (הפוביאה), כמו זום במצלמה."},{"id":"prof3_30_שמע","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו תפקיד קורטקס השמע?","a":"נמצא בשתי אונות הרקה; קולט מידע משתי האוזניים ואחראי על הבנת השפה.","explain":"<b>קורטקס השמע</b> - נמצא <b>בשתי אונות-הרקה</b> (משני-צידי-המוח, לא-רק-בצד-אחד). <b>תפקידו</b>: קולט מידע <b>משתי-האוזניים</b> (משולב-משני-הצדדים), ועובד <b>יחד עם אזור-ורניקה</b> (הסמוך-לו, גם-הוא-באונת-הרקה) לצורך <b>הבנת השפה הנשמעת</b>. ⚠️ שימו-לב לשילוב: קורטקס-השמע 'קולט-את-הצליל-הגולמי', ואזור-ורניקה 'מפרש-את-המשמעות' - שני-שלבים-נפרדים-אך-סמוכים-פיזית, בדיוק כמו-שקורטקס-הראייה מזין-מידע-לאזורי-עיבוד-חזותי-נוספים ברשת-הראייה-הרחבה-יותר.","mnemo":"🎧 קורטקס שמע = 2 רמקולים (שתי אונות הרקה, אחד לכל אוזן) - עובד עם ורניקה להבנת שפה."},{"id":"prof3_31","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תארו את הפרוצדורה הניסויית על חצויי מוח המתוארת בתרשים 3.23 (קואורדינציה עין-יד).","a":"יד שמאל + תמונה בשדה ראייה שמאלי = התאמה תקינה (שניהם מגיעים להמיספרה הימנית). יד ימין + תמונה בשדה ראייה שמאלי = חוסר התאמה (היד מדווחת להמיספרה שמאלית, התמונה נקלטת בימנית, וכפיס המוח המנותק לא מאפשר תקשורת ביניהן).","explain":"בניסוי המתואר, נבדק חצוי מוח מתבקש למצוא ולהתאים חפץ שתמונתו מוצגת בשדה ראייה מסוים, תוך שימוש ביד מסוימת. מצב א' (התאמה תקינה): כאשר הנבדק משתמש ביד שמאל כדי למצוא ולהתאים חפץ שתמונתו מוצגת בשדה הראייה השמאלי שלו — הקואורדינציה בין העין ליד תקינה, כי שני החפצים נקלטים באותה ההמיספרה (הימנית). מצב ב' (חוסר התאמה): כאשר הנבדק נדרש להשתמש ביד ימין עבור אותה תמונה (שדה ראייה שמאלי) — הוא אינו מסוגל, כי המסרים מהיד הימנית עוברים להמיספרה השמאלית, בעוד התמונה נקלטה בהמיספרה הימנית, וכפיס המוח המנותק לא מאפשר תקשורת ביניהן. לדוגמה, ספל עשוי להיתפס בטעות כאגס. מסקנת הניסוי: המידע שנקלט בכל המיספרה נשאר \"כלוא\" בה בלבד כאשר כפיס המוח מנותק.","mnemo":"🙌 יד ימין מדברת (שמאל=דיבור) ורואה בעצמה - תואם. יד ימין + תמונה בצד שמאל = לא תואם, כי הקו הישיר בין ההמיספרות (כפיס המוח) נותק."},{"id":"prof3_reflection4","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד אפשר להיעזר בפרוצדורה הניסויית על חצויי מוח להבנת הפעילות של כל אחד מצדי המוח?","a":"ניתוק כפיס המוח מבודד מידע חזותי לכל המיספרה בנפרד. מציגים מידע לכל צד לחוד ובודקים תגובה - דיבור (שולט בו הצד השמאלי) או מטלות ידניות ללא מילים (לבדיקת הימני) - כך חושפים הבדלי תפקוד בין הצדדים.","explain":"ניתוח חצוי מוח מנתקים את כפיס המוח, כך שמידע המוצג לשדה ראייה אחד (ימני או שמאלי) מגיע רק להמיספרה המקבילה, ואינו עובר לצד השני. כך אפשר להציג מידע לכל המיספרה בנפרד ולבחון מה כל צד \"יודע\" בלי שהצד השני יוכל \"לעזור\". כיוון שברוב האנשים הדיבור שולט על ידי ההמיספרה השמאלית, ניתן לשאול את הנבדק (דרך ההמיספרה השמאלית) מה הוא רואה/יודע, ולבדוק בנפרד את ההמיספרה הימנית באמצעות מטלות ידניות שאינן דורשות מילים. כך חושפים הבדלים בין הצדדים: ההמיספרה השמאלית אנליטית ומעבדת פרט אחר פרט, ואילו הימנית הוליסטית ומעבדת דפוסים כוללניים.","mnemo":"🔌 כפיס-המוח מנותק = כל צד \"מבודד\". דיבור=בודקים צד שמאל. משימות-יד-בלי-מילים=בודקים צד ימין."},{"id":"quiz3_1","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"בהשוואה לנשים, מבחינה גנטית יש לגברים ______. (אותם כרומוזומים / כרומוזום אחד יותר / זוג כרומוזומים שונים / יותר תכונות דומיננטיות)","a":"זוג כרומוזומים שונים (XY לעומת XX אצל נשים)","explain":"בהשוואה-לנשים (בעלות זוג-כרומוזומי-מין <b>XX זהים</b>), לגברים יש <b>זוג כרומוזומים שונים</b> - <b>X</b> אחד שהתקבל-מהאם, ו-<b>Y</b> אחד שהתקבל-מהאב. הכרומוזום-ה-Y הוא-שקובע את המאפיינים-הזכריים בהתפתחות-העובר. ⚠️ שימו-לב שזה <b>לא</b> 'כרומוזום-אחד-יותר' (זו-טעות-נפוצה) - לגברים ולנשים יש <b>אותו מספר-כרומוזומים בדיוק</b> (23 זוגות) - ההבדל הוא ב<b>סוג</b> הכרומוזום-בזוג-האחרון (XY מול XX), לא-בכמות-הכוללת.","mnemo":"🔗 XY (זכר) = זוג-שונה. XX (נקבה) = זוג-זהה."},{"id":"quiz3_2","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"אונת העורף אחראית על _______ ואונת הרקה אחראית על ________. (זיכרון ותפיסה / ראייה ושמיעה / שמיעה וראייה / מחשבות ורגשות / תפיסה וזיכרון)","a":"ראייה ושמיעה (אונת עורף=ראייה מאחור; אונת רקה=שמיעה בצד)","explain":"<b>אונת העורף</b> (הממוקמת מאחורי-הראש) אחראית על <b>ראייה</b> - היא ה'יעד-הסופי' של מידע-חזותי. <b>אונת הרקה</b> (הממוקמת בצדי-הראש, בגובה-האוזניים) אחראית על <b>שמיעה</b> - כוללת את קורטקס-השמע ואזור-ורניקה. ⚠️ שיטת-זכירה מהירה: המיקום-הפיזי מרמז-על-התפקוד - עורף (אחורי) קרוב-פחות-לאוזניים ורחוק-מהעיניים אך משמש-לראייה (בגלל-מסלול-עצבי-ארוך מהעיניים); רקה (צדדית, קרוב-לאוזניים) משמשת-לשמיעה - הקרבה-הפיזית-לאוזניים מסבירה-את-שיוך-הרקה-לשמיעה.","mnemo":"👁️ עורף=מסך-אחורי(ראייה). 👂 רקה=רמקול-בצד(שמיעה)."},{"id":"quiz3_3","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"הקורטקס הסומטי-סנסורי עוזר לך לעבד מידע _______. (מחשבתי / חושי / רגשי / מעוכב)","a":"חושי (קורטקס סומטו-סנסורי מעבד תחושות מגע/לחץ/טמפרטורה)","explain":"הקורטקס הסומטו-סנסורי (באונת-הקדקוד) מעבד מידע <b>חושי</b> - תחושות מגע, לחץ, טמפרטורה, וכאב - מידע שמגיע ישירות מקולטני-החישה בעור-ובגוף. ⚠️ אל-תתבלבלו עם 'מחשבתי' - זה יהיה מתאים-יותר לאזורים-אסוציאטיביים-גבוהים-יותר בקורטקס, לא-לקורטקס-הסומטו-סנסורי-הראשוני שמעבד קלט-חושי-ישיר-וגולמי, לפני-כל-פרשנות/חשיבה-נוספת.","mnemo":"✋ סנסורי = חושי - מגע/חום/כאב, לא מחשבה."},{"id":"quiz3_4","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"סביר כי אדם חצוי מוח סובל מ_________. (סכיזופרניה / הנטינגטון / אפילפסיה / מחלה ביפולארית / מחלת פרקינסון)","a":"אפילפסיה (ניתוח חצוי-מוח משמש לטיפול בהתקפים חמורים)","explain":"ניתוח <b>כפיס-המוח</b> (הקושר בין שתי-ההמיספרות) הוא טיפול-קיצוני המבוצע במקרים-קשים-של <b>אפילפסיה</b> שאינה-מגיבה-לתרופות - הניתוח מבודד את פעילות-ההתקף לצד-אחד-של-המוח, ומונע-ממנה-להתפשט לצד-השני. כתוצאה, החולה הופך ל'חצוי-מוח' (split-brain) - שתי-ההמיספרות שלו לא-מתקשרות-ביניהן-יותר. ⚠️ אל-תתבלבלו עם ההפרעות-האחרות (סכיזופרניה, פרקינסון, הנטינגטון, ביפולארית) - אף-אחת-מהן לא-קשורה-לניתוח-כפיס-המוח; זהו-טיפול-ספציפי-לאפילפסיה-קשה-בלבד.","mnemo":"⚡🔌 חצוי-מוח = ניתוק כפיס-המוח כדי לעצור \"קצר חשמלי\" מתפשט (אפילפסיה)."},{"id":"quiz3_5","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"חברכם טען כי המוח השמאלי אחראי על ניתוח אנליטי ומילולי, והימני אינטואיטיבי ותפיסתי - האם הוא צודק? (תלוי באדם אותו חוקרים / לא / כן / רוב בני האדם כך, אך לא כולם)","a":"רוב בני האדם כך, אך לא כולם (התמחות המיספרות אינה מוחלטת/אחידה אצל כולם)","explain":"אכן נכון עבור רוב בני האדם: ההמיספרה השמאלית נוטה להיות אנליטית יותר (מעבדת מידע פריט אחר פריט, שולטת בדיבור/שפה), וההמיספרה הימנית הוליסטית יותר (מעבדת דפוסים כוללניים, מסייעת לתובנות יצירתיות) - אך ההתמחות הזו אינה מוחלטת או זהה אצל כל האנשים (למשל, אצל חלק מהשמאליים המצב הפוך).","mnemo":"📊 כלל \"רוב אך לא כולם\" - נכון כמעט תמיד בפסיכולוגיה, גם כאן."},{"id":"quiz3_6","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"בלוטת יותרת המוח נקראת גם \"בלוטת העל\" מאחר והיא ______. (הגדולה מכל הבלוטות / שולטת בבלוטות אחרות / קשורה למערכת הפרסימפתטית / אינה מהווה חלק מהמערכת ההורמונלית)","a":"שולטת בבלוטות אחרות (יותרת המוח מפרישה הורמונים המפעילים בלוטות נוספות)","explain":"בלוטת-יותרת-המוח נקראת 'בלוטת-העל' כי היא <b>שולטת בבלוטות הורמונליות אחרות</b> - מפרישה הורמונים המפעילים/מווסתים בלוטות-נוספות ברחבי-הגוף (בלוטת-התריס, בלוטות-האדרנל, ועוד). ⚠️ שימו-לב שזה <b>לא</b> בגלל-גודלה (היא בעצם קטנה-יחסית) - זה בגלל <b>תפקידה-הבקרתי-הייחודי</b>: היא ה'מפקדה' שמכוונת-את-כל-שאר-המערכת-ההורמונלית, בהנחיית-ההיפותלמוס (שנלמד קודם בפרק כתחנת-הממסר בין-המוח-למערכת-ההורמונלית).","mnemo":"👑 יותרת-המוח = מלכה - לא הכי גדולה, אבל שולטת בכל שאר הבלוטות (הנתינים)."},{"id":"quiz3_7","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"אם אישה סובלת מסוכרת, לאילו מקרוביה הסיכוי הרב ביותר לסבול מאותה מחלה? (בן / בת / אחות / תאומה זהה)","a":"תאומה זהה (100% חומר גנטי משותף)","explain":"<b>תאום-זהה (מונוזיגוטי)</b> חולק <b>100% מהחומר-הגנטי</b> עם האחות-הסובלת-מסוכרת - הדמיון-הגנטי-המקסימלי-האפשרי בין-שני-בני-אדם. קרובי-משפחה-אחרים (בן, בת, אחות-לא-תאומה) חולקים בממוצע רק <b>כ-50%</b> מהחומר-הגנטי. ⚠️ ההיגיון הבסיסי: ככל-שהדמיון-הגנטי גבוה-יותר, כך הסיכוי-לחלות-באותה-מחלה-בעלת-רכיב-תורשתי (כמו סוכרת) עולה - ולכן תאום-זהה, עם החפיפה-הגנטית-המושלמת, נמצא בסיכון-הגבוה-ביותר מבין-כל-האפשרויות.","mnemo":"🥚 תאום-זהה = 100% אותם גנים = הכי גבוה בסיכון לאותה מחלה תורשתית."},{"id":"quiz3_8","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"קיימות בגוף ______ קבוצות עיקריות של נוירונים. (ארבע / חמש / שתי / שלוש)","a":"שלוש (חושיים, תנועתיים, אינטרנוירונים)","explain":"שלושת סוגי הנוירונים: (1) נוירונים חישתיים/סנסוריים - מעבירים מידע מהחושים למערכת העצבים המרכזית. (2) נוירונים תנועתיים/מוטוריים - מעבירים פקודות מהמערכת המרכזית לשרירים/בלוטות. (3) אינטרנוירונים - הרוב המכריע של נוירוני המוח, מקשרים בין חישתיים למוטוריים ומבצעים עיבוד פנימי.","mnemo":"3️⃣ חושי-תנועתי-אינטרנוירון = 3, כמו רמזור (אדום-צהוב-ירוק)."},{"id":"quiz3_9","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"האקסון לדנדריט הוא כמו... (המוסר לשלוח / המחליט \"למוציא לפועל\" / מעכב למעורר / מעורר למעכב)","a":"המחליט למוציא לפועל ⚠️ (הסקה לוגית מכיוון זרימת המידע בנוירון - לא ציטוט מהספר; מומלץ לוודא מול הפידבק של Moodle)","explain":"⚠️ זו הסקה-לוגית (לא-ציטוט-ישיר-מהספר) מכיוון-זרימת-המידע בנוירון: ה<b>דנדריט</b> (וגוף-התא) <b>מקבלים</b> מידע-נכנס ו'<b>מחליטים</b>' - מצטברים-האותות ונקבע-אם-לירות (לפי חוק-הכול-או-לא-כלום). ה<b>אקסון</b> הוא-זה ש<b>מבצע-בפועל</b> את ה<b>העברה/הפלט</b> של ההחלטה שהתקבלה. ⚠️ לכן ההשוואה 'המחליט למוציא-לפועל' (ולא 'המוסר לשלוח' או אנלוגיות-אחרות) - דנדריט/גוף-תא = מקבל-ההחלטה; אקסון = המבצע-אותה. מומלץ-לוודא-מול-הפידבק-של-Moodle, כי זו-שאלת-אנלוגיה-ולא-הגדרה-ישירה-מהטקסט.","mnemo":"⚠️ שאלה לא-ודאית מהספר - היגיון בלבד: אקסון=מחליט, דנדריט=מקבל."},{"id":"quiz3_10","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"המיילין דומה ל______. (ירי / רסיסים / חומר בידוד / ברזל)","a":"חומר בידוד (המיאלין מכסה את האקסון, מזרז הולכה, כמו בידוד חוט חשמל)","explain":"המיילין דומה ל<b>חומר-בידוד</b> - בדיוק כמו-הציפוי-הפלסטי-סביב-חוט-חשמל: מעטפת-המיילין העוטפת-את-האקסון מונעת 'דליפת'-זרם ומזרזת משמעותית את מהירות-ההולכה של פוטנציאל-הפעולה לאורך-האקסון. ⚠️ קישור-לשאלה-קודמת בפרק (prof3_15c): זה בדיוק ההסבר לכך-שאקסונים-עטופי-מיילין מוליכים במהירות-של-עד-200-מטר-לשנייה, לעומת רק-כ-10-סנטימטר-לשנייה באקסונים-חשופים-ולא-מבודדים.","mnemo":"🔌 מיילין = ציפוי-פלסטיק על חוט חשמל - בידוד שמזרז את הזרם."},{"id":"quiz3_11","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"ענף סימפתטי פעיל מאפיין אדם הסובל מ________. (עוינות / דיכאון / הפרעות אכילה / הפרעות חרדה)","a":"הפרעות חרדה (סימפתטי=תגובת \"הילחם או ברח\", פעיל יתר בחרדה)","explain":"פעילות-יתר של <b>הענף הסימפתטי</b> (האחראי על תגובת 'הילחם-או-ברח') מאפיינת אנשים-הסובלים <b>מהפרעות-חרדה</b>: אצל-אנשים-אלה, מערכת-ההתראה-הפיזיולוגית (דופק-מהיר, נשימה-מואצת, מוכנות-לפעולה) פעילה-גם-כשאין-סכנה-אמיתית-בפועל - זה-בדיוק המנגנון-הביולוגי שמסביר את התסמינים-הפיזיים-האופייניים-לחרדה (לב-דופק, הזעה, מתח-שרירים) גם-במצבים-שקטים-לחלוטין. ⚠️ קישור-לפרק-ההפרעות (13): זה-בדיוק המנגנון-הביולוגי מאחורי הפרעת-הפניקה וחרדה-כללית שנלמדו-שם בפירוט.","mnemo":"🚨 חרדה = אזעקה תקועה על \"דלוק\" - סימפתטי פעיל-יתר גם כשאין סכנה אמיתית."},{"id":"quiz3_12","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"כאשר אתה מרגיש כי עלייך לרוץ מגורם המהווה סכנה, המערכת ה______ תגביר את קצב פעימות ליבך. (סימפתטית / פרסימפתטית / מרכזית / סומטית)","a":"סימפתטית (מפעילה תגובת חירום - מאיצה דופק לקראת פעולה)","explain":"כשמרגישים צורך <b>לרוץ מסכנה</b>, ה<b>מערכת הסימפתטית</b> תגביר את קצב-פעימות-הלב - זו בדיוק תגובת 'הילחם-או-ברח' שמכינה את-הגוף לפעולה-מיידית מול-איום: מאיצה דופק, מרחיבה אישונים, מפנה זרימת-דם לשרירים. ⚠️ אל-תתבלבלו עם המערכת-הפרסימפתטית (זו-ההפך - מרגיעה, לא-מזרזת), הסומטית (שולטת-בתנועה-מכוונת, לא-בתגובת-חירום-פיזיולוגית), או המרכזית (מוח+חוט-שדרה, לא-חלק-מהתגובה-האוטונומית-הספציפית-הזו).","mnemo":"🏃🚨 בריחה מסכנה = כפתור-האזעקה האדום = סימפתטי."},{"id":"quiz3_13","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"איזו פעולה מבין הפעולות הבאות מצריכה פעילות רחבה ביותר של הקורטקס המוטורי? (כיפוף רגל ימין / כיפוף הזרוע מהמרפק / הקלדת מכתב / מתיחת כף הרגל)","a":"הקלדת מכתב (אצבעות מקבלות את השטח הגדול ביותר בקורטקס המוטורי)","explain":"<b>הקלדת-מכתב</b> דורשת את-הפעילות-הרחבה-ביותר בקורטקס-המוטורי - כי היא מצריכה <b>תנועות-אצבעות מדויקות ומורכבות-ביותר</b>, והאצבעות מקבלות <b>שטח-ייצוג גדול-במיוחד</b> בקורטקס-המוטורי (בדיוק כמו-השפתיים-והלשון), בשל הצורך-בשליטה-עדינה-ומדויקת בתנועותיהן. ⚠️ בהשוואה, תנועות-גסות-יותר (כיפוף-רגל, כיפוף-זרוע-מהמרפק, מתיחת-כף-הרגל) דורשות שטח-ייצוג-קורטיקלי קטן-יותר-משמעותית - כי הן פחות-דורשות-דיוק-עדין, גם-אם-מערבות-שרירים-גדולים-יותר-פיזית.","mnemo":"⌨️ אצבעות = הכי הרבה \"מקשי-פסנתר\" בקורטקס המוטורי (חשבו על פסנתרן שזז באצבעות בלבד)."},{"id":"quiz3_14","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"המענית המרכזית היא_______ במוח. (חריץ / אזור תת קורטיקלי / אונה מוחית / חלק מאונת העורף)","a":"חריץ (מענית=קפל/חריץ בקליפת המוח, לא אזור שלם)","explain":"המענית-המרכזית היא <b>חריץ</b> (קפל עמוק) בקליפת-המוח - <b>לא</b> אזור-שלם, לא-אזור-תת-קורטיקלי, ולא-חלק-מאונת-מסוימת. תפקידה: לשמש כקו-הפרדה בין <b>אונת-המצח</b> (המכילה-את-הקורטקס-המוטורי, לפניה) לבין <b>אונת-הקדקוד</b> (המכילה-את-הקורטקס-הסומטו-סנסורי, אחריה). ⚠️ 'מענית' = חריץ/קפל - זה-בדיוק המונח-האנטומי-המדויק, לא-מבנה/אזור-בעל-נפח, אלא <b>קו-גבול</b> בין-שני-אזורים-שכנים.","mnemo":"➖ מענית = קו-חריץ (כמו קו במחברת), לא אזור שלם."},{"id":"quiz3_15","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"ורד משרטטת רווח קטן בין כפתור סופי על נוירון אחד לבין הדנדריט בנוירון הסמוך. עליה לתת לרווח את התווית: (תעלת היונים / גלייה / סינפסה / מרווח ראנווייה)","a":"סינפסה (הרווח בין נוירונים שבו עובר המידע הכימי)","explain":"הרווח-הקטן שוורד משרטטת, בין כפתור-סופי-של-נוירון-אחד לדנדריט-של-נוירון-סמוך, הוא <b>סינפסה</b> - זו ההגדרה-המדויקת: הרווח-הזעיר שדרכו עובר מסר-כימי (נוירוטרנסמיטר) בין-שני-נוירונים, שלעולם-לא-נוגעים-זה-בזה-ישירות. ⚠️ אל-תתבלבלו עם 'תעלת-היונים' (מנגנון-פנימי בקרום-הנוירון, לא-רווח-בין-שני-נוירונים), 'גלייה' (סוג-תא-תומך במוח, לא-רווח), או 'מרווח-ראנווייה' (פער-במעטפת-המיילין-לאורך-אקסון-בודד, לא-בין-שני-נוירונים-שונים).","mnemo":"🏝️ הרווח בין 2 נוירונים = תעלת-הים (סינפסה)."},{"id":"quiz3_16","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"ברוריה עוברת טיפול בדיקור סיני נגד כאבי גב. חוקרים סבורים שדיקור סיני משחרר ________ במוח. (גאבא / אצטילכולין / אנדרופינים / דופמין)","a":"אנדורפינים (משככי כאבים טבעיים שהגוף מפריש)","explain":"דיקור-סיני (כמו מנגנוני-שיכוך-כאב לא-תרופתיים-אחרים, למשל פלסבו) מפעיל ומשחרר <b>אנדורפינים</b> - נוירומודולטורים המשמשים כ<b>משככי-כאבים-טבעיים</b> שהגוף מייצר-בעצמו. חסימת-האנדורפינים (למשל בעזרת-התרופה נלוקסון) מבטלת את יעילות-הדיקור-בהפחתת-כאב - הוכחה-ניסויית-חזקה שהמנגנון-בפועל עובר-דרך-מערכת-האנדורפינים. ⚠️ אל-תתבלבלו עם גאבא/אצטילכולין/דופמין - כל-אלה נוירוטרנסמיטרים-חשובים-אחרים, אך לא-אלה-הקשורים-ספציפית-לשיכוך-כאב-בהקשר-של-דיקור-סיני.","mnemo":"🩹💉 דיקור = מדקרים מחט, אבל הגוף משחרר \"פלסטר טבעי\" (אנדורפינים) שמקהה כאב."},{"id":"quiz3_17","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"להבנת הגנטיקה של אימפולסיביות, ניתן למקד את המחקר בשונויות של הגנים המשפיעות על האופן שבו המוח משתמש ב: (תאי גלייה / גאבא / תעלות יונים / דופמין)","a":"דופמין (נוירוטרנסמיטר הקשור לתגמול/דחף - רלוונטי לאימפולסיביות)","explain":"ניתוחים של התנהגות אימפולסיבית התמקדו בנוירוטרנסמיטר דופמין, הפועל באזורים במוח החיוניים למשימות כמו תכנון — זהו הנוירוטרנסמיטר העוזר להגיע ליציבות קוגניטיבית ולגמישות קוגניטיבית. הפרעות בתפקוד הדופמין יכולות לגרום לבני אדם להתנהג באופן אימפולסיבי או בלתי יציב.\n\nהמנגנון המדויק: מי שרוצה למצוא בסיס גנטי לאימפולסיביות, בעצם מחפש בסיס גנטי להבדלים ברמת הפעילות הדופמינרגית המוחית בין פרטים שונים. חוקרים תיעדו וריאציות ביותר מגן אחד — DRD4 ו-COMT — המשפיעות על רמת הפעילות של הדופמין במוח. כלומר, ההשפעה אינה ישירה על \"אימפולסיביות\" כתכונה כללית, אלא עקיפה: הגן משפיע על רמת/יעילות הדופמין, זה משפיע על יכולות תכנון ויציבות קוגניטיבית, וזה בא לידי ביטוי כהתנהגות אימפולסיבית או יציבה יותר/פחות.","mnemo":"🎰 אימפולסיביות = מכונת-מזל = דופמין (נוירוטרנסמיטר התגמול/הדחף)."},{"id":"quiz3_18","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"איזו טכניקה מאפשרת לחוקרים ליצור \"פגעים\" הפיכים? (סריקת PET / rTMS / fMRI / EEG)","a":"rTMS (גרייה מגנטית זמנית ולא-פולשנית, ניתנת לביטול בניגוד לניתוח)","explain":"<b>rTMS</b> (גרייה מגנטית חוזרת) מאפשרת ליצור 'פגעים' <b>הפיכים</b>: פעימות מגנטיות דרך-הגולגולת יוצרות השבתה-זמנית של אזור-מוחי, <b>ללא נזק-קבוע לרקמה</b> - זה בדיוק ההבדל המכריע מ'פגע-ממוקד' הקלאסי (שיוצר נזק בלתי-הפיך). ⚠️ בזכות-ההפיכות, rTMS <b>מותרת-לשימוש-בבני-אדם</b> (בניגוד-לפגע-ממוקד-קבוע, שמותר-רק-בבעלי-חיים) - זה מה-שהופך אותה-לכלי-מחקר בעל-ערך-מיוחד: אפשר-לחקות זמנית 'מה-קורה-בלי-אזור-X' אצל-בני-אדם-חיים, בלי-לגרום-נזק-קבוע.","mnemo":"🧲⏸️ הפאוזה המגנטית ההפיכה = rTMS."},{"id":"quiz3_19","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"מערכת העצבים ה_______ מעבדת מסרים עצביים שמגיעים אליה ושולחת הוראות לחלקים שונים בגוף. (היקפית / אוטונומית / סומטית / מרכזית)","a":"מרכזית (מוח וחוט שדרה - מעבדים ומורים, לא רק מעבירים)","explain":"<b>מערכת העצבים המרכזית</b> (מוח+חוט-שדרה) היא-זו ה<b>מעבדת</b> מסרים-עצביים המגיעים-אליה, ו<b>שולחת הוראות</b> לחלקים-שונים-בגוף - בניגוד-למערכת-ההיקפית, שרק <b>מעבירה</b> מידע (לא-מעבדת-אותו-בעצמה). ⚠️ ההבדל-המרכזי: המערכת-ההיקפית היא 'צינור-הולכה' (מוליכה-מידע-הלוך-ושוב), בעוד המערכת-המרכזית היא 'מרכז-העיבוד-וההחלטות' - שם-נעשית-בפועל ה<b>עבודה-הקוגניטיבית</b> על-המידע-שהגיע, ומשם-נשלחות ההוראות-בחזרה.","mnemo":"🏛️ \"מעבדת ושולחת הוראות\" = מטה-הפיקוד (מרכזית), לא רק אנטנה (היקפית)."},{"id":"quiz3_20","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"לאחר שה________ שלו נפגע/ה, היו לה\"מ קשיים ברכישת מידע חדש. (תלמוס / אזור ברוקה / תצורת הרשת / היפוקמפוס)","a":"היפוקמפוס (מרכזי ליצירת זיכרונות חדשים)","explain":"לאחר-שה<b>היפוקמפוס</b> של ה'מ נפגע, נותרו-לו קשיים-קשים ברכישת <b>מידע-חדש</b> - זה בדיוק מקרה-המבחן-הקלאסי-בפרק-הזיכרון (פרק 6): ה'מ הפך-לא-מסוגל ליצור זיכרונות-חדשים כלל, אף-שזיכרונותיו-הישנים (מלפני-הניתוח) נשארו תקינים, ויכולות-למידה-מוטורית-חדשות (זיכרון-תהליכי) גם-כן נשארו-שמורות. ⚠️ אל-תתבלבלו עם תלמוס (תחנת-ממסר-חושית, לא-ליצירת-זיכרונות), אזור-ברוקה (הפקת-דיבור), או תצורת-הרשת (ערנות-כללית) - ההיפוקמפוס הוא-ספציפית-המבנה-הקריטי-ליצירת-זיכרונות-חדשים.","mnemo":"📸 מצלמת-הזיכרונות שנשברה = היפוקמפוס (בלי מצלמה, אין תמונות זיכרון חדשות)."},{"id":"quiz3_21","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"בעודכם מפטפטים עם טלי, אתם מבחינים שהיא ימנית. אתם חושבים כי סביר יותר שיכולתה ליצור דיבור נשלטת על ידי: (אף לא אחת מן ההמיספרות / ההמיספרה השמאלית שלה / ההמיספרה הימנית שלה / שתי ההמיספרות)","a":"ההמיספרה השמאלית שלה (אצל ימנים, שפה נשלטת בדרך כלל בצד שמאל)","explain":"אצל טלי, שהיא <b>ימנית</b>, סביר-יותר שיכולתה ליצור-דיבור נשלטת על-ידי <b>ההמיספרה השמאלית</b> - זהו ממצא-עקבי: אצל <b>רוב</b> בני-האדם (כולל-רוב-השמאליים, לא-רק-הימניים), הדיבור/יצירת-שפה נשלטים בהמיספרה-השמאלית. ⚠️ רק אחוז-קטן (כ-15% מהשמאליים, פחות-מכך אצל-ימניים) שולטים-בשפה בהמיספרה-הימנית דווקא - ולכן, בהיעדר-מידע-נוסף, ההנחה-הסבירה-ביותר (בהתבסס-על-הסטטיסטיקה-הכללית) היא שגם-אצל-אדם-ימני-רגיל, שליטת-השפה נמצאת-בהמיספרה-השמאלית.","mnemo":"🗣️ ימנית = דיבור בצד שמאל (אצל רוב האנשים, גם ימניים)."},{"id":"quiz3_22","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"איזה ממבני המוח משמש כתחנת ממסר בין המוח לבין המערכת ההורמונלית? (ההיפוקמפוס / הגשר / האמיגדלה / ההיפותלמוס)","a":"ההיפותלמוס (מקשר בין המוח למערכת ההורמונלית דרך יותרת המוח)","explain":"<b>ההיפותלמוס</b> משמש כתחנת-הממסר המרכזית בין-המוח לבין-המערכת-ההורמונלית: הוא מווסת את פעילות <b>בלוטת-יותרת-המוח</b> ('בלוטת-העל'), שבתורה שולטת-בבלוטות-הורמונליות-נוספות ברחבי-הגוף. ⚠️ אל-תתבלבלו עם ההיפוקמפוס (זיכרון), הגשר (חיבור-בגזע-המוח למוחון), או האמיגדלה (עיבוד-רגשי) - כל-אלה מבנים-חשובים-אחרים במערכת-הלימבית, אך רק-ההיפותלמוס הוא-הגשר-הספציפי בין-המערכת-העצבית-למערכת-ההורמונלית.","mnemo":"🌡️➡️💊 התרמוסטט (היפותלמוס) מחובר ישירות לצינור-ההורמונים."},{"id":"quiz3_25","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"כשפטר ורוזמרי גרנט חקרו מיני פרושים של דארווין, הם גילו ששינויים קיצוניים במזג האוויר השפיעו על הישרדות אוכלוסיות פרושים מסוימות. זוהי דוגמה ל: (תורשה מול סביבה / תורשתיות / בררה טבעית / חוק הכול-או-לא-כלום)","a":"בררה טבעית (סביבה קיצונית \"בוררת\" מי שורד ומעביר גנים הלאה)","explain":"תהליך האבולוציה, על־פי דארווין, מתרחש באמצעות ברירה טבעית: בתוך כל אוכלוסייה קיימת שונות טבעית בתכונות (למשל, צורת המקור אצל פרושים). כאשר אוכלוסייה מתפזרת לבתי גידול שונים (הנבדלים במקורות המזון ובתנאי המחיה), הסביבה בכל בית גידול \"בוררת\" אילו פרטים ישרדו ויתרבו — אלה שתכונותיהם מתאימות טוב יותר לסביבה הספציפית שלהם. פרטים בעלי התאמה טובה יותר מעמידים יותר צאצאים, ובמרוצת הדורות עולה שכיחות התכונות המועילות באוכלוסייה, עד שנוצרים מינים חדשים ונבדלים מאותו אב קדמון משותף.\n\nהקשר בין תורשה לסביבה: התורשה (הגנוטיפ, המבנה הגנטי שיורש הפרט מהוריו) קובעת את מגוון התכונות האפשריות (למשל, טווח צורות המקור האפשריות). אך הסביבה היא זו שקובעת אילו מתוך התכונות התורשתיות הללו יתרמו להישרדות ולהצלחה רבייתית באותו מקום ספציפי — כלומר, הסביבה \"בוררת\" מתוך המגוון התורשתי הקיים. התוצאה הסופית (הפנוטיפ — ההופעה החיצונית וההתנהגות בפועל) נובעת אפוא ממפגש בין הגנוטיפ לסביבה, ולא מהגנוטיפ בלבד.\n\nדוגמה ממחקר הזוג גרנט: בצורת (1977) העדיפה פרושים גדולים בעלי מקור עבה (התאמה סביבתית לגרעינים קשים), אך שנה גשומה (1983) הפכה את המגמה לטובת פרושים קטנים — כלומר, אותה תורשה \"נבחרת\" אחרת בהתאם לשינוי בסביבה.","mnemo":"🌾 שדה-החיטה בבצורת שוב - מזג אוויר קיצוני בורר מי שורד (בררה טבעית)."},{"id":"quiz3_26","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"שרון עורכת מחקר שבו היא צופה בהתנהגותם של ילדים קטנים. יותר מכול היא תוכל לצפות ישירות ב ________. (כרומוזומים / דנ\"א / פנוטיפים / גנוטיפים)","a":"פנוטיפים (התכונות הנראות/ההתנהגות בפועל, לא הגנטיקה עצמה)","explain":"שרון, הצופה בהתנהגות ילדים-קטנים, יכולה לצפות ישירות רק ב<b>פנוטיפים</b> - <b>התכונות-הנראות/ההתנהגות-בפועל</b> (איך הילד משחק, מתנהג, מגיב) - <b>לא</b> בגנטיקה-הבסיסית-עצמה (גנוטיפ, דנ'א, כרומוזומים), שהיא <b>בלתי-נראית ישירות</b> ודורשת בדיקה-מעבדתית-מיוחדת לחשיפתה. ⚠️ ההבחנה החשובה: פנוטיפ = <b>התוצאה הנראית</b> (התנהגות/מראה); גנוטיפ/דנ'א/כרומוזומים = <b>הבסיס-הביולוגי-הפנימי</b> שיוצר-אותה - חוקרי-התפתחות (כמו שרון) עובדים לרוב עם-תצפיות-פנוטיפיות, גם-אם-מעוניינים-בסופו-של-דבר בהבנת-הבסיס-הגנטי.","mnemo":"👀 רואים רק את התוצאה הגלויה (עוגה=פנוטיפ), לא את המתכון הנסתר (גנוטיפ)."},{"id":"quiz3_27","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"לבדוק אם יש מרכיב גנטי ב\"חוש הומור\" - יהיה עליכם לגלות כי: (תאומים דיזיגוטים דומים תמיד יותר בחוש הומור מתאומים מונוזיגוטים / תאומים מונוזיגוטים דומים יותר בחוש ההומור שלהם מתאומים דיזיגוטים / תאומים דיזיגוטים דומים בחוש ההומור יותר ממונוזיגוטים / תאומים מונוזיגוטים תמיד בעלי חוש הומור טוב יותר)","a":"תאומים מונוזיגוטים דומים יותר בחוש ההומור שלהם מתאומים דיזיגוטים (הבדל גנטי גדול יותר בין דיזיגוטים = תומך בהשפעה תורשתית)","explain":"תאומים מונוזיגוטים (MZ) נוצרים מביצית אחת שהופרתה על־ידי זרע אחד ואז התפצלה לשניים — ולכן החומר הגנטי שלהם זהה לחלוטין, ללא כל הבדל. תאומים דיזיגוטים (DZ) נוצרים משתי ביציות נפרדות, שכל אחת הופרתה על־ידי זרע נפרד — ולכן רק כ-50% מהחומר הגנטי שלהם זהה, בדיוק כמו בין כל זוג אחים או אחיות רגיל (הם אינם דומים זה לזה יותר מאחים רגילים).","mnemo":"🥚 ביצית-אחת (תאומים זהים) דומים יותר בחוש הומור = יש מרכיב גנטי לתכונה."},{"id":"quiz3_28","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"אחד התפקידים של ה_________ הוא לקבל גרייה מנוירונים אחרים. (סינפסות / אקסונים / כפתורים סופיים / דנדריטים)","a":"דנדריטים (מקבלים אותות מנוירונים אחרים, האקסון שולח)","explain":"דנדריטים — תפקידם הבסיסי לקבל גירויים מאיברי החוש או מנוירונים אחרים. גוף התא — מכיל את גרעין התא ואת הציטופלזמה; מזהה את אופי ועצמת הגירוי המתקבל מהדנדריטים ומעביר אותו לאקסון. אקסון — מוביל את המידע לכל אורכו (עד מטר במוח השדרה, פחות ממ\"מ במוח הגולגולת) אל הכפתורים הסופיים. כפתורים סופיים — מבנים דמויי פקעות בקצה האקסון, שבאמצעותם הנוירון מגרה בלוטות סמוכות, שרירים או נוירונים אחרים. הכיוון תמיד אחיד: מהדנדריטים, דרך גוף התא, אל האקסון ומשם לכפתורים הסופיים.","mnemo":"📥 דנדריט = תיבת-דואר נכנס (מקבל), לא יוצא."},{"id":"quiz3_29","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"לאחר שיונה מושך כסף מהבנק עליו להמתין 2 דקות עד שהכרטיס יחזור להיות פעיל. דומה ל_________ בתקשורת נוירונית. (תקופה רפרקטורית / פוטנציאל פעולה / תעלות יונים / חוק הכול-או-כלום)","a":"תקופה רפרקטורית (זמן \"מנוחה\" הכרחי אחרי ירי של נוירון)","explain":"המתנת-2-הדקות של יונה עד-שכרטיס-הבנק 'יחזור-להיות-פעיל' דומה ל<b>תקופה רפרקטורית</b> בתקשורת-נוירונית - פרק-הזמן שבו נוירון <b>אינו-יכול לירות-שוב</b> מיד-לאחר-שכבר-ירה, וזקוק ל'זמן-מנוחה' הכרחי לפני-שיוכל-להגיב-לגירוי-נוסף. ⚠️ אל-תתבלבלו עם פוטנציאל-הפעולה (האירוע-עצמו, לא-'תקופת-ההמתנה' שאחריו), תעלות-יונים (מנגנון-פיזי-ברמת-הממברנה, לא-מושג-הזמן), או חוק-הכול-או-לא-כלום (עיקרון-שונה, על-עוצמת-הירייה, לא-על-תזמון-הירי-הבא).","mnemo":"💳⏳ כרטיס-בנק שצריך \"להתקרר\" 2 דקות לפני שימוש נוסף = תקופה רפרקטורית."},{"id":"prof4_01","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי תפיסה? (היעזרו במילון המונחים)","a":"תהליך כולל של הכרת עצמים והתרחשויות בסביבה — לחוש, להבין, לזהות, לקרוא בשם ולהתכונן להגיב עליהם.","explain":"ההגדרה מהמילון-מונחים בספר מדגישה ש<b>תפיסה</b> היא תהליך <b>שלם ומורכב</b>, לא רק 'ראייה' פשוטה. היא כוללת חמישה רכיבים ברצף: לחוש (הגירוי מגיע לקולטן), להבין (לתת לו מובן), לזהות (לדעת מה זה), לקרוא בשם (לשייך אותו למילה/קטגוריה), ולהתכונן להגיב (המוח כבר מכין תגובה מתאימה). ⚠️ ההבחנה החשובה ביותר לפרק כולו: תפיסה שונה מ<b>חישה</b> (sensation) - חישה היא קליטת האנרגיה הפיזית הגולמית על-ידי הקולטנים (למשל, אור הפוגע ברשתית), בעוד תפיסה היא התהליך <b>המנטלי</b> שהופך את אותה קליטה גולמית למשמעות מובנת ('זה כוס קפה', לא רק 'יש כתם חום עגול'). כל הפרק בעצם עוסק בשאלה: איך המוח הופך אנרגיה פיזית לחוויה מובנת של העולם?","mnemo":"🔍➡️🏷️ תפיסה = לראות → להבין → לתת שם. תהליך שלם, לא רק \"לראות\"."},{"id":"prof4_02","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תרשים 1 מסכם את שלושת שלבי התפיסה. הסבירו מה מתרחש בכל שלב.","a":"חישה=יצירת דחפים עצביים מגירוי חושי. ארגון=יצירת ייצוג/מתפס פנימי (גודל,צורה,מרחק). זיהוי/היכר=השוואה לזיכרון, מתן משמעות (\"מה זה/מה תפקידו\").","explain":"תרשים 1 ממחיש את שלושת השלבים <b>ברצף כרונולוגי קבוע</b> - כל שלב מזין את הבא אחריו: <b>חישה</b> - הקולטנים החושיים (בעין, באוזן, בעור) הופכים את הגירוי הפיזי (אור, גל-קול, לחץ) לדחפים עצביים - עדיין בלי שום 'משמעות'. <b>ארגון</b> - המוח מקבץ את הדחפים הבודדים ובונה מהם ייצוג-פנימי קוהרנטי - צורה, גודל, מרחק, תנועה - כלומר, 'מרכיב' עצם שלם מפיסות המידע הגולמיות. <b>זיהוי/היכר</b> - רק בשלב האחרון המתפס (הייצוג שנבנה) מושווה לזיכרונות קיימים, וניתנת לו משמעות ('זה כלב', 'זה מסוכן'). ⚠️ הטעות הנפוצה: לחשוב שתפיסה קורית 'בבת אחת' - בפועל, יש כאן שרשרת מדורגת של עיבוד, וכל שלב יכול להיכשל בנפרד (למשל, אילוזיה קורית בשלב הארגון, לא בשלב החישה).","mnemo":"📷➡️🧩➡️🏷️ 3 שלבים: מצלמה (חישה, גולמי) → פאזל מורכב (ארגון, צורה) → מדבקת-שם (זיהוי, משמעות)."},{"id":"prof4_03","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הוסיפו איור סכמתי המתאר את התהליך העצבי מאחורי שלושת שלבי התפיסה (נוירוני חישה, אינטרנוירונים, מוח השדרה, תלמוס, אונת חישה, קורטקס סומטו-סנסורי).","a":"חישה: קולטני חישה→נוירוני חישה→מוח השדרה/תלמוס→אונת חישה מתאימה (עורף=ראייה, רקה=שמיעה, סומטו-סנסורי=מגע). ארגון: אינטרנוירונים משלבים מידע לכדי מתפס קוהרנטי. זיהוי/היכר: השוואה לזיכרון באזורים אסוציאטיביים גבוהים.","explain":"המסלול העצבי ממחיש פיזית את שלושת השלבים התיאורטיים שראינו בשאלה הקודמת: בשלב <b>החישה</b>, קולטני-החישה הספציפיים (בעין/אוזן/עור) יוצרים דחף עצבי, שעובר דרך <b>נוירוני חישה</b> אל <b>מוח השדרה</b> ומשם אל <b>התלמוס</b> (תחנת-הממסר המרכזית של המוח לכל החושים חוץ מריח) - ומשם ל<b>אונת החישה המתאימה</b> בקורטקס (אונת עורף לראייה, אונת רקה לשמיעה, קורטקס סומטו-סנסורי למגע). בשלב <b>הארגון</b>, <b>אינטרנוירונים</b> (הרוב המכריע של נוירוני המוח) משלבים את חתיכות-המידע הנפרדות לכדי מתפס אחד קוהרנטי. בשלב <b>הזיהוי</b>, אזורים אסוציאטיביים 'גבוהים' יותר במוח משווים את המתפס לזיכרונות קיימים ונותנים לו משמעות. ⚠️ שימו לב שהמסלול הפיזי-עצבי (תרשים זה) הוא בדיוק ה'תרגום הביולוגי' של שלושת השלבים המושגיים שנלמדו בשאלה הקודמת - שתי הדרכים להסתכל על אותו תהליך.","mnemo":"🛤️ מסלול המידע: קולטן → נוירון-שליח → תחנת-רכבת (מוח שדרה/תלמוס) → תחנה סופית (אונה מתאימה: עורף=ראייה, רקה=שמיעה, קדקוד=מגע)."},{"id":"prof4_04","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי אילוזיה?","a":"מצב שבו מערכת התפיסה מתעתעת בנו ומציגה תבנית גירוי באופן מוטעה בעליל. רוב בני האדם חווים אותן אילוזיות (בשונה מהזיות, שאינן משותפות לכול).","explain":"<b>אילוזיה</b> היא כישלון-תפיסה <b>שיטתי וצפוי</b>: מערכת התפיסה שלנו מפרשת גירוי אמיתי וקיים באופן מוטעה, אבל <b>באופן עקבי</b> אצל כל בני-האדם (או רובם) - זה לא מקרה בודד או תקלה אקראית. ⚠️ ההבחנה הקריטית מ<b>הזיה</b> (הלוצינציה, שנלמדת בפרק ההפרעות): הזיה היא תפיסה של גירוי שלא קיים כלל במציאות, וחווית-ההזיה <b>אינה משותפת</b> לכל בני-האדם - רק אדם ספציפי (למשל בפסיכוזה) חווה אותה. אילוזיה, לעומת זאת, מתעתעת בכולנו כמעט באותה הדרך בדיוק - למשל, כמעט כל אדם שרואה אילוזיית מולר-לייר (שני חצים עם ראשי-חץ הפוכים) יתפוס קו אחד כארוך מהשני, גם כשהם זהים באורכם במדויק. זו למעשה עדות מדעית חשובה: אילוזיות מוכיחות שהמוח לא 'מצלם' את המציאות במדויק - הוא <b>בונה</b> אותה לפי כללים קבועים, וכשהכללים האלה 'נמתחים' יתר על המידה, כולנו טועים באותה הדרך.","mnemo":"🎭 אילוזיה = תעלול-קוסם שכולם רואים אותו דבר (עדשה משותפת), לא הזיה אישית."},{"id":"prof4_05","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי דו־משמעות?","a":"מצב שבו לדימוי יחיד ברמת החישה יש כמה פרשנויות שונות ובלתי־מתיישבות (ברמת התפיסה/הזיהוי) — התפיסה נעה הלוך ושוב ביניהן (חוסר יציבות תפיסתית).","explain":"<b>דו-משמעות</b> מתרחשת כשגירוי חושי אחד (זהה לחלוטין, ברמת החישה) מתפרש בכמה דרכים <b>שונות ובלתי-ניתנות-לחפיפה</b> ברמת התפיסה/הזיהוי - והתודעה 'נעה' הלוך-ושוב בין הפרשנויות, לא מצליחה 'להחליט' על אחת מהן לצמיתות. הדוגמה הקלאסית: 'אגרטל/שני-פרצופים' - אותו ציר-מתאר בדיוק, אך פעם רואים בו אגרטל לבן על רקע שחור, ופעם שני פרופילי-פנים שחורים על רקע לבן; אי-אפשר לראות את שתי הפרשנויות בו-זמנית, והתפיסה 'קופצת' ביניהן. ⚠️ ההבדל החשוב מאילוזיה: באילוזיה יש <b>פרשנות שגויה קבועה אחת</b> (כולם טועים באותו הכיוון); בדו-משמעות יש <b>כמה פרשנויות תקינות</b> באותה מידה, שהתודעה מתלבטת ביניהן - זו לא 'טעות', אלא הוכחה לכך שאותו קלט-חושי יכול להתפרש במספר דרכים לגיטימיות שונות.","mnemo":"🦆🐰 ברווז-או-ארנב! אותה תמונה, המוח קופץ בין 2 פרשנויות בלי להחליט."},{"id":"prof4_06","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"במה עוסקת הפסיכופיזיקה?","a":"חקר הקשרים בין גירויים פיזיקליים לבין ההתנהגות/החוויה המנטלית שהם מעוררים — מדידת עצמת התנסויות חושיות. פכנר טבע את המושג.","explain":"<b>פסיכופיזיקה</b> היא תחום המחקר החוקר את הקשר המדויק בין <b>עולם הגירויים הפיזיקלי</b> (עוצמת האור, גובה-הצליל, ריכוז החומר הכימי) לבין <b>עולם החוויה המנטלית/הסובייקטיבית</b> שהם מעוררים (כמה בהיר זה נראה, כמה חזק זה נשמע). המטרה: למדוד באופן מדעי-כמותי משהו שנשמע 'פנימי' לגמרי (חוויה סובייקטיבית) - כלומר, לבנות גשר מדיד בין המדידה הפיזיקלית האובייקטיבית (בעזרת מכשירים) לבין מה שהאדם באמת חווה. <b>גוסטב פכנר</b> טבע את המושג במאה ה-19, והפך את חקר-החוויה מפילוסופיה מופשטת למדע-מדיד עם נוסחאות מתמטיות מדויקות (שנראה בשאלות הבאות - סף מוחלט, חוק ובר) - זהו למעשה אחד הרגעים המכוננים בהפיכת הפסיכולוגיה למדע ניסויי.","mnemo":"📏💭 פסיכופיזיקה = סרגל (פיזי) פוגש רגש (פסיכולוגי) - כמה חזק גירוי מרגיש בפנים."},{"id":"prof4_07","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו סף מוחלט? הסבירו כיצד מזהים אותו בעזרת הפונקציה הפסיכומטרית.","a":"הכמות המינימלית של אנרגיה הנדרשת לחוויה חושית = רמת גירוי המזוהה ב-50% מהמקרים. הפונקציה הפסיכומטרית מציגה % איתור מול עצמת גירוי — בצורת S, כי המעבר אינו חד (עייפות/קשב משתנים).","explain":"<b>סף מוחלט</b> מוגדר כמות-האנרגיה המינימלית הנדרשת כדי שגירוי ייחווה <b>ב-50% מהמקרים</b> (לא 100%!) - ההגדרה ב-50% (ולא 100%) חשובה כי אין נקודה חדה שמתחתיה 'לעולם לא' ומעליה 'תמיד' מזהים - הזיהוי משתנה מניסוי-לניסוי אצל אותו אדם עצמו, בגלל תנודות בקשב, עייפות, ורעש-רקע פנימי במערכת-העצבים. <b>הפונקציה הפסיכומטרית</b> ממחישה זאת גרפית: על ציר ה-X עוצמת הגירוי, על ציר ה-Y אחוז-הזיהוי - והעקומה מקבלת צורת <b>S</b> (לא קפיצה חדה) בדיוק בגלל אי-הוודאות הזו: יש עוצמה נמוכה שבה כמעט אף פעם לא מזהים, עוצמה גבוהה שבה כמעט תמיד מזהים, ואזור-מעבר הדרגתי באמצע - וה-50% מוגדר כנקודת-הסף בדיוק במרכז אזור-המעבר הזה.","mnemo":"🕯️ נר קלוש בחושך - הנקודה שבה אתה בטוח שאתה רואה אותו ב-50% מהפעמים = סף מוחלט."},{"id":"prof4_08","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי הסתגלות חישתית? הסבירו כיצד היא משפיעה על הזיהוי של גירויים חישתיים.","a":"ירידה הדרגתית בתגובתיות של מערכת חושית לגרייה מתמשכת (למשל, ריח שנעלם עם הזמן). מאפשרת להבחין מהר יותר במידע חדש בסביבה.","explain":"<b>הסתגלות חישתית</b> היא ירידה הדרגתית ברגישות מערכת-חושית לגירוי <b>קבוע וממושך</b> - ככל שהגירוי נשאר זהה זמן רב יותר, כך התגובה העצבית אליו נחלשת (לדוגמה: ריח בישום כשנכנסים לחדר, שנעלם תוך דקות אחדות מהמודעות, למרות שהריח עצמו לא השתנה בפועל). <b>למה זה מועיל אבולוציונית</b>: אם מערכת-החישה שלנו הייתה 'צועקת' באותה עוצמה על גירוי קבוע וידוע לנצח, היינו מוצפים במידע לא-רלוונטי ומחמיצים דברים חדשים וחשובים בסביבה. ההסתגלות 'משחררת משאבים' עבור <b>גירויים חדשים</b>, שהם לרוב חשובים יותר להישרדות (שינוי=פוטנציאל סכנה או הזדמנות). ⚠️ שימו לב: הסתגלות היא תופעה פיזיולוגית (במערכת-החישה עצמה), לא הטיה פסיכולוגית - זה מבדיל אותה מ'הטיית תגובה' שנלמדת בשאלה הבאה.","mnemo":"👃 בושם בחדר - בהתחלה מריח חזק, אחרי כמה דקות \"נעלם\" - זו הסתגלות חישתית."},{"id":"prof4_09","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי הטיית תגובה?","a":"נטייה שיטתית של צופה להעדיף תגובה מסוימת מסיבות שאינן קשורות למאפייני הגירוי החושי עצמו (למשל, בשל מבנה תגמול).","explain":"<b>הטיית תגובה</b> היא נטייה <b>שיטתית ועקבית</b> של הצופה להעדיף תגובה מסוימת (למשל, לומר 'כן, זיהיתי' יותר מ'לא, לא זיהיתי') - אך <b>לא</b> מסיבה הקשורה לעוצמת-הגירוי עצמו, אלא מסיבות חיצוניות: מבנה-תגמול (למשל, אם 'לפספס' עלול לעלות ביוקר - כמו רופא שלא רוצה לפספס גידול - הוא יטה להגיד 'כן' גם כשלא בטוח), אישיות (זהיר מול פזיז), או ציפיות (אם ציפינו שיהיה גירוי, נטה לדווח שראינו אותו גם כשלא היה). ⚠️ ההבחנה המכרעת: הטיית-תגובה קשורה ל<b>תהליך-ההחלטה</b> (מה לומר), לא ל<b>תהליך-החישה</b> עצמו (מה קלטו הקולטנים בפועל) - שני נבדקים יכולים לחוש את אותו הגירוי בדיוק ברמת-החישה, אך לדווח אחרת בגלל הבדל בהטיית-התגובה שלהם - זה בדיוק הרעיון שמפותח בתיאוריית גילוי-האותות (השאלות הבאות).","mnemo":"⚖️ מאזניים מוטות מראש - עונים \"כן\" יותר, לא בגלל הגירוי, אלא בגלל הרגל/תגמול."},{"id":"prof4_10","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"רוני ויוני טעמו מיץ חדש; לרוני מתוק, ליוני לא כלל. הציעו הסבר מסף מוחלט, מהסתגלות חישתית, ומהטיית תגובה.","a":"סף מוחלט: לרוני סף נמוך יותר לזיהוי מתיקות. הסתגלות: יוני הסתגל למשהו מתוק יותר קודם לכן. הטיית תגובה: ליוני נטייה שיטתית לדווח בזהירות/ציפיות שהתאכזבו.","explain":"שאלה זו מבקשת ליישם שלושה מושגים <b>שונים לחלוטין</b> על אותו תרחיש - חשוב להבין למה כל הסבר <b>לא סותר</b> את השאר, אלא מציע זווית-הסתכלות אחרת על אותה תופעה: <b>סף מוחלט</b> - ייתכן שלרוני יש רגישות-קולטנים גבוהה יותר, ולכן סף-הזיהוי שלו למתיקות נמוך יותר - הוא 'תופס' ריכוזי-סוכר נמוכים יותר מיוני. <b>הסתגלות חישתית</b> - אם יוני שתה משהו מתוק-מאוד רגע לפני, קולטני-הטעם שלו כבר 'הסתגלו' לרמת-מתיקות גבוהה, ולכן המיץ החדש נחווה כפחות-מתוק ביחס לנקודת-ההשוואה הפנימית שלו. <b>הטיית תגובה</b> - אולי ליוני יש נטייה כללית (לא קשורה לטעם עצמו) לדווח בזהירות/ספקנות, למשל בגלל ציפיות-קודמות שהתאכזבו ('כל 'מיץ חדש' מתברר כמאכזב'). ⚠️ שימו לב: שלושת ההסברים פועלים ב<b>שלבים שונים</b> של תהליך-התפיסה - הראשון בקולטן, השני בהתאמה-לזמן, השלישי בהחלטה-לדווח - ולכן יכולים כולם לפעול בו-זמנית ולתרום יחד לאותה תוצאה נצפית.","mnemo":"🥤 רוני+יוני, אותו מיץ: סף-נמוך=רוני מרגיש מתיקות קלה. הסתגלות=יוני כבר טעם משהו מתוק. הטיה=יוני נזהר מדי בתשובות."},{"id":"prof4_11","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תארו את שני תהליכי האיתור בתיאוריית גילוי האותות: תהליך חישה ותהליך החלטה.","a":"תהליך חישה = רגישות הצופה לחוזק הגירוי עצמו. תהליך החלטה = הטיית התגובה של הצופה, נפרד מהתהליך החושי.","explain":"תיאוריית גילוי-האותות מפרקת את 'תהליך-הזיהוי' לשני שלבים <b>עצמאיים ונפרדים לחלוטין</b>, שקודם לתיאוריה זו נחשבו כמקשה-אחת: <b>תהליך חישה</b> - הרגישות האמיתית של הצופה לעוצמת-הגירוי עצמו (מה שקורה פיזיולוגית בקולטנים) - זהו הרכיב ה'אובייקטיבי'. <b>תהליך החלטה</b> - איך הצופה בוחר לדווח על מה שהוא חש - מושפע מהטיית-תגובה (ציפיות, מוטיבציות, מבנה-תגמול), ולא קשור כלל לעוצמת-הגירוי הפיזית. ⚠️ המשמעות המהפכנית: <b>שני צופים עם אותה רגישות-חושית בדיוק</b> (אותו תהליך-חישה) יכולים לדווח באופן שונה לגמרי, בגלל הבדלים בתהליך-ההחלטה שלהם בלבד - וזה בדיוק מה שמאפשר לחוקרים 'לנטרל' את השפעת ההטיה ולמדוד את הרגישות-החושית 'האמיתית' בנפרד מנטיות-הדיווח האישיות.","mnemo":"👁️➕🧠 SDT = עין (חישה, כמה חזק) + מוח (החלטה, כן/לא) - שני שלבים נפרדים."},{"id":"prof4_12","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"קשרו בין תהליכי חישה/החלטה (תיאוריית גילוי האותות) לבין מלמטה־למעלה/מלמעלה־למטה.","a":"תהליך חישה ↔ מלמטה־למעלה (מבוסס על הגירוי הגולמי בלבד). תהליך החלטה ↔ מלמעלה־למטה (מושפע מציפיות, מוטיבציות, הקשר).","explain":"החיבור בין שני הזוגות המושגיים חושף שהם למעשה <b>אותו רעיון</b>, בשני הקשרים שונים בפרק: <b>תהליך חישה</b> ↔ <b>עיבוד מלמטה-למעלה</b> - שניהם מבוססים <b>אך ורק</b> על הגירוי הפיזי הגולמי עצמו, ללא כל השפעה מציפיות/ידע-קודם. <b>תהליך החלטה</b> ↔ <b>עיבוד מלמעלה-למטה</b> - שניהם מושפעים ממה שנמצא <b>כבר בראש</b> של הצופה - ציפיות, מוטיבציות, הקשר, ידע-קודם - ולא רק מהגירוי החיצוני. ⚠️ למה זה חשוב: זה מראה שהמונחים 'מלמטה-למעלה/מלמעלה-למטה' (שנלמדים בהמשך הפרק כעקרון כללי של תפיסה) והמונחים 'תהליך חישה/החלטה' (שנלמדים ספציפית בהקשר של תיאוריית גילוי-האותות) הם למעשה <b>שתי מסגרות-שפה שונות לתאר את אותה תובנה בדיוק</b> - שהתפיסה תמיד משלבת מידע 'מהעולם' עם מידע 'מהראש'.","mnemo":"🔗 חישה=גירוי-גולמי=מלמטה-למעלה. החלטה=ציפיות-שלי=מלמעלה-למטה."},{"id":"prof4_13","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תארו את ארבעת המצבים בתיאוריית גילוי האותות (תרשים 4.7).","a":"פגיעה=אות נוכח+\"כן\". החטאה=אות נוכח+\"לא\". אזעקת שווא=אות נעדר+\"כן\". דחייה נכונה=אות נעדר+\"לא\".","explain":"תיאוריית גילוי-האותות בונה טבלת 2×2 המצליבה 'מה קרה במציאות' (האם היה אות/גירוי או לא) עם 'מה הצופה דיווח' (כן/לא) - וכך יוצרת <b>ארבע תוצאות אפשריות</b>, לא רק 'נכון/לא-נכון': <b>פגיעה (Hit)</b> - אות היה נוכח, והצופה דיווח 'כן' (זיהוי נכון). <b>החטאה (Miss)</b> - אות היה נוכח, אך הצופה דיווח 'לא' (פספוס). <b>אזעקת שווא (False Alarm)</b> - אות <b>לא</b> היה נוכח, אך הצופה דיווח 'כן' בטעות. <b>דחייה נכונה (Correct Rejection)</b> - אות לא היה נוכח, והצופה דיווח נכון 'לא'. ⚠️ הטבלה הזו קריטית כי היא מפרידה בין <b>שני סוגי טעויות שונים לגמרי</b> (החטאה מול אזעקת-שווא) - וכפי שנראה בשאלה הבאה, קריטריון-ההחלטה של הצופה (מחמיר/מקל) קובע איזה סוג-טעות יגבר, כי אי-אפשר להפחית את שניהם בו-זמנית.","mnemo":"✅✅❌❌ 2X2: יש+כן=פגיעה. יש+לא=החטאה. אין+כן=אזעקת-שווא. אין+לא=דחייה-נכונה."},{"id":"prof4_reflection1","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מוקד המשטרה: מדוע ביקשו המוקדנים הנחיה, בעזרת תיאוריית גילוי האותות?","a":"קיימת פשרה בלתי נמנעת: קריטריון מקל מפחית החטאות (פחות מצוקה אמתית מוחמצת) אך מגביר אזעקות שווא (יותר בזבוז משאבים); קריטריון מחמיר עושה ההפך. המוקדנים זקוקים להנחיה על סדר העדיפויות.","explain":"המקרה של המוקדנים מיישם ישירות את תיאוריית גילוי-האותות על דילמה ארגונית אמיתית. הבעיה: המוקדנים צריכים להחליט, על סמך מידע חלקי וקולי-מצוקה מעורפלים, האם באמת מדובר במקרה-חירום אמיתי. הפשרה הבלתי-נמנעת (כפי שראינו במושג 'קריטריון-החלטה'): קריטריון-מקל (נוטה להאמין שכן מדובר בחירום) <b>מפחית החטאות</b> - כלומר, פחות סיכוי שמצוקה-אמיתית תיפספס ותוחמץ העזרה - אך <b>מגביר אזעקות-שווא</b>, כלומר יותר משאבי-חירום מבוזבזים על התראות שווא. קריטריון-מחמיר עושה בדיוק ההפך. ⚠️ מכיוון ששני-סוגי-הטעויות לא יכולים להצטמצם בו-זמנית רק על-ידי שינוי-קריטריון (רק שיפור אמיתי בזיהוי-עצמו, לא רק בסף-ההחלטה, יכול לעשות זאת), המוקדנים <b>חייבים הנחיה ארגונית מפורשת</b> - איזה סוג-טעות חמור יותר להם למנוע, כדי לדעת לאיזה כיוון להטות את קריטריון-ההחלטה שלהם.","mnemo":"☎️ מוקדן: קריטריון-רגיש=פחות-מחמיץ+יותר-שווא-אזעקות. קריטריון-קשוח=ההפך. אין בורח מהפשרה."},{"id":"prof4_14","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו סף ההבדל?","a":"ההבדל הפיזיקלי הקטן ביותר בין שני גירויים שעדיין ניתן להבחין בו (מזוהה כשונה ב-50% מהמקרים) — נקרא גם הפער המינימלי המובחן (JND).","explain":"המקרה של המוקדנים ממחיש בעולם-אמיתי את הפשרה הבלתי-נמנעת שיוצרת תיאוריית גילוי-האותות: <b>קריטריון מקל</b> (נוטים להאמין שיש מקרה-חירום אמיתי גם מספק-קטן) מפחית <b>החטאות</b> (פחות מצוקות-אמיתיות מוחמצות - זה קריטי, כי החטאת מקרה-חירום אמיתי עלולה לעלות בחיי-אדם), אבל <b>מגביר אזעקות-שווא</b> (יותר משאבי-משטרה/אמבולנס מבוזבזים על מקרים שאינם אמיתיים). <b>קריטריון מחמיר</b> עושה בדיוק ההפך - פחות בזבוז-משאבים, אך סיכון גבוה יותר להחמיץ מקרה אמיתי. ⚠️ הנקודה המרכזית לתשובה: <b>אי-אפשר לשפר את שני הסוגים בו-זמנית</b> באמצעות שינוי-קריטריון בלבד (רק שיפור אמיתי ברגישות-החישה עצמה, כמו הכשרה טובה יותר לזיהוי מקרי-חירום אמיתיים, יכול לעשות זאת) - ולכן המוקדנים זקוקים להנחיה ברורה מלמעלה על סדר-העדיפויות הארגוני: מה חמור יותר להחמיץ מקרה אמיתי, או לבזבז משאבים.","mnemo":"⚖️ סף ההבדל = הכי קטן שהמאזניים מרגישות (JND) - 50% מהפעמים."},{"id":"prof4_15","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו חוק ובר?","a":"ההבדל הקטן ביותר שמבחינים בו בין שני גירויים הוא יחסי לעוצמת הגירוי המקורי, לא קבוע במספרים מוחלטים - ככל שהגירוי חזק יותר, צריך תוספת גדולה יותר כדי להבחין בשינוי (ΔI/I=k).","explain":"<b>סף ההבדל</b> (הנקרא גם JND - Just Noticeable Difference) הוא ההבדל הפיזיקלי <b>הקטן ביותר</b> בין שני גירויים שעדיין ניתן להבחין בו כשונה - ושוב, מוגדר סטטיסטית כנקודה שבה ההבדל מזוהה ב-<b>50%</b> מהמקרים (אותו עיקרון סטטיסטי כמו בסף-המוחלט). ⚠️ ההבדל המהותי מסף-מוחלט: סף-מוחלט שואל 'מתי בכלל מרגישים <b>נוכחות</b> של גירוי?' (השוואה מול העדר-גירוי), בעוד סף-ההבדל שואל 'מתי מרגישים <b>שינוי</b> בין שני גירויים קיימים?' (השוואה בין שני גירויים ממשיים) - שני שאלות שונות לגמרי, גם אם המתודולוגיה הסטטיסטית (50%) דומה.","mnemo":"💰 שקל אחד בכיס ריק=מורגש. שקל אחד בבנק עשיר=לא מורגש. תמיד יחסי לכמות הקיימת (חוק ובר)."},{"id":"prof4_reflection2","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הפחתת מלח בחטיפים בהדרגה — כיצד מסבירים זאת סף ההבדל וחוק ובר?","a":"לפי חוק ובר (ΔI/I=k), הפרש (ΔI) קטן ביחס לכמות הנוכחית (I) נשאר מתחת לסף ההבדל ואינו מורגש. הפחתה של 25% בבת אחת הייתה חוצה את הסף; הפחתות הדרגתיות קטנות יותר (15%, אח\"כ 10%) נשארות מתחת לסף בכל שלב.","explain":"יישום ישיר של נוסחת חוק-ובר (ΔI/I=k) לתרחיש-שיווקי מוכר: אם היצרן היה מפחית את המלח ב-25% בבת-אחת, ה-<b>ΔI</b> (ההפרש) היה גדול-מדי ביחס ל-<b>I</b> (הכמות הקיימת) - חוצה את סף-ההבדל, וצרכנים היו מבחינים מיד ומתלוננים. אך אם היצרן מפחית בהדרגה - למשל 15% תחילה, ואז 10% נוספים מתוך <b>הכמות החדשה והנמוכה-יותר</b> (לא מהכמות המקורית!) - כל שלב בנפרד נשאר <b>מתחת</b> לסף-ההבדל היחסי, ולכן לא מורגש. ⚠️ הנקודה העדינה שחשוב להבין: לפי חוק ובר, ה-25% המקורי היה חייב להיות מפוצל למספר הפחתות קטנות יותר, כי הסף היחסי (k) נשאר קבוע, אך <b>הכמות-הבסיס (I) הולכת וקטנה</b> עם כל הפחתה - כך שגם אחוז דומה יכול לחצות את הסף בשלב מאוחר יותר, אם לא ממשיכים לחלק לצעדים קטנים דיים.","mnemo":"🧂 הפחתת מלח בהדרגה = כל צעד קטן מדי (מתחת לסף ΔI/I) - אף פעם לא \"מרגישים\" את השינוי."},{"id":"prof4_16","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי התמרה?","a":"המרת צורה אחת של אנרגיה פיזיקלית (כמו אור) לצורה אחרת (דחף עצבי). המוח מבחין בין חוויות חושיות שונות באמצעות אזורים ספציפיים בקורטקס לכל חוש.","explain":"<b>התמרה (Transduction)</b> היא ההמרה הפיזיולוגית הבסיסית ביותר בתפיסה: המרת סוג-אחד של אנרגיה פיזיקלית (למשל גלי-אור, גלי-קול, לחץ מכני) לסוג-אחר לגמרי - <b>דחף עצבי חשמלי-כימי</b> - שהוא 'השפה' היחידה שהמוח יכול לעבד. כל קולטן-חישה (בעין, באוזן, בעור) מבצע התמרה מסוג שונה, מותאם לצורת-האנרגיה הספציפית שהוא קולט. ⚠️ הנקודה המרתקת: לאחר ההתמרה, <b>כל הדחפים העצביים נראים זהים מבחינה כימית</b> (אותו סוג אות חשמלי-נוירוטרנסמיטרי) - אז איך המוח מבחין בין 'רואה' ל'שומע'? התשובה: לא לפי <b>סוג</b> האות עצמו, אלא לפי <b>איזה אזור-מוח ספציפי</b> מקבל אותו (אונת-עורף=ראייה, אונת-רקה=שמיעה) - זהו עיקרון 'האנרגיות העצביות הספציפיות': המשמעות נקבעת לפי המסלול, לא לפי תוכן-האות עצמו.","mnemo":"🔌 התמרה = שקע-חשמל - ממיר אנרגיה אחת (אור/קול) לאנרגיה אחרת (חשמל עצבי) שהמוח מבין."},{"id":"prof4_17","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי בחירה ממוקדת מטרה? הציגו דוגמה.","a":"בחירת העצמים שבהם מתמקד הקשב, כפונקציה של המטרות שלנו. דוגמה: התבוננות בחלון ראווה של מאפים — ממקדים קשב רק בקינוחי שוקולד.","explain":"<b>בחירה ממוקדת-מטרה (goal-directed selection)</b> היא הצורה ה'רצונית' של קשב: אנחנו <b>בוחרים באופן מודע</b> להתמקד בעצמים מסוימים בסביבה, בהתאם למטרות ולכוונות שלנו כרגע - זהו קשב <b>'מלמעלה-למטה'</b>, כי הוא מונע מציפיות/מטרות פנימיות, לא ממאפייני-הגירוי עצמו. הדוגמה: כשמסתכלים על חלון-ראווה עם מגוון עצום של מאפים, אם המטרה שלנו כרגע היא 'קינוח שוקולד', הקשב שלנו יתמקד ספציפית בפריטי-השוקולד, ויתעלם (יחסית) מהעוגות האחרות, אף שכל הפריטים באותה מידה 'זמינים' לעין. ⚠️ בשאלה הבאה נלמד את הניגוד המושגי לזה - לכידה שמקורה בגירוי, שהיא קשב 'מלמטה-למעלה' לא-רצוני.","mnemo":"🍫 חלון-ראווה של קינוחים - העיניים שלך \"בוחרות\" להתמקד רק בשוקולד (המטרה שלך)."},{"id":"prof4_18","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי לכידה שמקורה בגירוי? הציגו דוגמה.","a":"מאפייני הגירוי עצמו לוכדים את הקשב אוטומטית, ללא קשר למטרותינו. דוגמה: שינוי פתאומי של רמזור מאדום לירוק לוכד את הקשב גם בהיסח דעת.","explain":"<b>לכידה שמקורה בגירוי (stimulus-driven capture)</b> היא ההפך המדויק מבחירה-ממוקדת-מטרה: כאן <b>מאפייני הגירוי עצמו</b> (בהירות פתאומית, תנועה חדה, שינוי-צבע) 'תופסים' את הקשב שלנו <b>אוטומטית</b>, ללא כל קשר למטרות המודעות שלנו כרגע - זהו קשב <b>'מלמטה-למעלה'</b>. הדוגמה: גם אם אנחנו שקועים לגמרי במחשבה ולא 'מתכננים' לשים לב לרמזור, ברגע שהוא עובר מאדום לירוק (שינוי פתאומי), הקשב שלנו נלכד אליו אוטומטית - זה מנגנון-הישרדותי חשוב, כי שינויים פתאומיים בסביבה עשויים לאותת על סכנה או הזדמנות שדורשת תגובה מיידית. ⚠️ בניסוי שנלמד בשאלה הבאה, החוקרים בחנו ישירות איזה משני סוגי-הקשב 'מנצח' כשהם מתחרים זה בזה.","mnemo":"🚦 רמזור שמתחלף לירוק - קופץ לך לעין אוטומטית, גם בלי לרצות."},{"id":"prof4_19","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תארו את הניסוי שהעמיד בתחרות בחירה ממוקדת מטרה מול לכידה שמקורה בגירוי (תרשים 4.25). איזה תהליך משפיע יותר?","a":"6 עיגולים אפורים, אחד משתנה צבע (מטרה=בחירה מכוונת). בחצי מהניסויים מתווסף עיגול כהה חדש (לא רלוונטי למטרה) — ומושך קשב אוטומטית. מסקנה: לכידה שמקורה בגירוי גוברת על בחירה מכוונת־מטרה.","explain":"הניסוי (תרשים 4.25) בנוי כתחרות ישירה בין שני סוגי-הקשב: המשתתפים קיבלו <b>מטרה מוגדרת מראש</b> - לעקוב אחר שישה עיגולים אפורים ולזהות מתי אחד מהם משנה צבע (זו בחירה-ממוקדת-מטרה, קשב-מלמעלה-למטה). אך בחצי מהניסויים, ברגע קריטי, הופיע פתאום <b>עיגול כהה נוסף וחדש</b> - עיגול שכלל לא היה חלק מהמטרה, ולכן לא-רלוונטי מבחינה רציונלית. <b>התוצאה</b>: העיגול הכהה-החדש 'משך' את הקשב באופן אוטומטי ופגע בביצועי-המשתתפים במשימה-המוגדרת שלהם - הם התעכבו יותר בזיהוי שינוי-הצבע כשהעיגול-החדש הופיע. <b>המסקנה</b>: לכידה-שמקורה-בגירוי (עיגול חדש) גוברת על בחירה-ממוקדת-מטרה (המשימה המוגדרת) - הראיה הניסויית לכך שקשב-אוטומטי יכול 'לעקוף' כוונות מודעות, גם כשמנסים להתרכז במשהו אחר בכוונה.","mnemo":"🎯 6 עיגולים אפורים, אתה ממוקד רק על אחד (מטרה) - אבל עיגול חדש-כהה שקופץ מנצח תמיד את הקשב שלך."},{"id":"prof4_20","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו את מודל הפילטר של ברודבנט לעיבוד מידע לא־קשוב.","a":"התודעה בעלת קיבולת מוגבלת; הקשב מסנן מידע בשלב מוקדם, לפני עיבוד המשמעות. נבדק בהאזנה דיכוטית — רק המסר הקשוב עובר דרך \"הפילטר\", השני נחסם.","explain":"<b>מודל הפילטר של ברודבנט</b> מציע פתרון-ארכיטקטוני לבעיה: לתודעה יש <b>קיבולת מוגבלת</b> - אי-אפשר לעבד באופן-מלא את כל המידע החושי המציף אותנו כל רגע. הפתרון המוצע: הקשב פועל כ'פילטר' (מסנן) שמופעל <b>בשלב מוקדם מאוד</b> - עוד <b>לפני</b> שהמוח מספיק לעבד את המשמעות של המידע. מה שנבחר לעבור את הפילטר (הערוץ הקשוב) מקבל עיבוד מלא; מה שלא נבחר (הערוץ הלא-קשוב) פשוט <b>נחסם</b> ונעלם, בלי שהמשמעות שלו נבדקת כלל. <b>הבדיקה הניסויית</b>: בשיטת ה<b>האזנה דיכוטית</b> (dichotic listening), משמיעים מסר שונה לכל אוזן בו-זמנית, ומבקשים מהנבדק לחזור בקול-רם רק על מה שנשמע באוזן אחת (המסר הקשוב) - לפי המודל, הנבדק לא אמור לזכור כמעט כלום מהמסר השני. ⚠️ בשאלה הבאה נראה תופעה שמאתגרת את המודל הזה בדיוק - מסיבת הקוקטייל.","mnemo":"🚪 מודל ברודבנט = דלת-כניסה אחת - רק מסר אחד (הקשוב) עובר, השני נחסם לפני שנכנס בכלל."},{"id":"prof4_21","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי תופעת מסיבת הקוקטייל וכיצד היא מאתגרת את מודל הפילטר?","a":"קליטת שמנו בערוץ לא־קשוב (בחדר רועש). מאתגרת את המודל כי הוא טוען שסינון קורה מוקדם, לפני עיבוד משמעות — אך שם הוא בעל משמעות ובכל זאת נקלט.","explain":"<b>תופעת מסיבת הקוקטייל</b> היא התצפית שהופכת את מודל-הפילטר של ברודבנט לבעייתי: כשאנחנו נמצאים בסביבה רועשת (מסיבה) ומרוכזים לגמרי בשיחה אחת ('הערוץ הקשוב'), ופתאום מישהו ליד אומר את <b>השם שלנו</b> ב'ערוץ הלא-קשוב' - אנחנו קולטים אותו <b>מיד</b>, גם בלי כל כוונה מודעת להקשיב לשם הזה. <b>למה זה מאתגר את המודל</b>: אם הפילטר (לפי ברודבנט) חוסם את הערוץ הלא-קשוב <b>לפני</b> שמעובדת המשמעות שלו, איך ייתכן שדווקא מילה בעלת-משמעות אישית מיוחדת (שם פרטי) 'עברה' דרך הפילטר? המשמעות הזו כבר <b>הייתה חייבת</b> להיות מעובדת (במידה מסוימת) כדי שהמוח 'ידע' שהמילה 'שם שלי' חשובה מספיק כדי לפרוץ את החסימה - סתירה ישירה להנחת-היסוד של המודל שהעיבוד-המלא קורה רק אחרי הבחירה.","mnemo":"🎉 מסיבת-קוקטייל - שומע את שמו למרות הרעש, זה \"שובר\" את דלת-הפילטר הסגורה שדיברנו עליה קודם."},{"id":"prof4_22","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"איזה תהליך תפיסתי מודגם בתופעת מסיבת הקוקטייל?","a":"לכידה שמקורה בגירוי — השם שלנו לוכד את הקשב אוטומטית, ללא כוונה מודעת להקשיב לו.","explain":"תופעת מסיבת-הקוקטייל היא בעצם <b>הדגמה חיה</b> של המושג <b>לכידה שמקורה בגירוי</b> (שנלמד קודם בפרק): השם שלנו הוא גירוי בעל תכונה מיוחדת (משמעות אישית עמוקה, נלמדה במשך כל החיים) שמצליח 'לתפוס' את הקשב <b>אוטומטית</b>, בדיוק כפי שעיגול-כהה-חדש תפס קשב בניסוי הקודם, ובדיוק כפי ששינוי-רמזור תפס קשב בדוגמה קודמת - למרות שהמטרה המודעת שלנו (מלמעלה-למטה) הייתה מכוונת לגמרי לשיחה האחרת. ⚠️ החיבור הזה חשוב כי הוא מראה שהמושג 'לכידה שמקורה בגירוי' לא מוגבל רק לגירויים <b>חזותיים</b> (כמו רמזור) - הוא חל גם על גירויים <b>שמיעתיים</b> בעלי משמעות אישית מיוחדת, כמו שמנו הפרטי.","mnemo":"🔊 השם שלך = כמו רמזור-שהתחלף - לוכד קשב אוטומטית, בלי כוונה."},{"id":"prof4_23","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד מסבירים כיום החוקרים את עיבוד המידע בערוץ הלא־קשוב?","a":"המידע עובר עיבוד חלקי, לא מספיק כדי להגיע למודעות — אלא אם כן מזוהות בו תכונות מיוחדות (כמו שמנו), ואז הוא הופך למוקד קשב מודע.","explain":"ההסבר העדכני (שהחליף את מודל-הפילטר הפשוט של ברודבנט) מציע פשרה: המידע בערוץ-הלא-קשוב <b>לא נחסם לגמרי</b> כפי שברודבנט חשב, אך גם <b>לא מעובד באופן-מלא</b> - הוא עובר <b>עיבוד חלקי, שטחי, לא-מודע</b>, ברמה נמוכה מספיק שלרוב אינו מגיע כלל לתודעה המודעת. <b>אלא אם כן</b> מזוהות בו תכונות מיוחדות במיוחד (כמו שמנו הפרטי, או מילת-אזעקה) - ואז, ורק אז, המידע 'קופץ' ומקבל עדיפות, הופך למוקד-קשב מודע ומעובד באופן מלא. ⚠️ זהו בדיוק ה'תיקון' התיאורטי שמאפשר להסביר את תופעת-מסיבת-הקוקטייל: המודל המקורי טעה לא בכך שיש סינון בכלל, אלא בכך שהניח סינון <b>מוחלט וחד-משמעי</b> - במקום המציאות המורכבת יותר של עיבוד-חלקי מתמיד ברקע.","mnemo":"🚪🔓 היום: הדלת לא סגורה לגמרי - עיבוד חלקי תמיד עובר, אבל רק תכונה מיוחדת (שם) פותחת אותה לגמרי."},{"id":"prof4_25a","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו את סוגי השינויים בניסוי עיוורון לשינוי: חילופי זהות, חילופי מקום, שינוי תצורה.","a":"חילופי זהות=עצם הוחלף באחר (מהדק→חולץ). חילופי מקום=שני עצמים החליפו מיקום. שינוי תצורה=כל העצמים סודרו מחדש בפריסה חדשה.","explain":"ניסוי ה'עיוורון-לשינוי' (change blindness) בוחן שלושה סוגים שונים של שינוי בתמונה, המוצגת פעמיים עם 'הבזק' קצר ביניהן - כדי לבדוק אילו שינויים אנחנו מבחינים בהם, ואילו לא: <b>חילופי זהות</b> - עצם אחד הוחלף לגמרי בעצם אחר (למשל, מהדק-נייר שהופך לחולץ-פקקים באותו מיקום בדיוק). <b>חילופי מקום</b> - שני עצמים <b>קיימים</b> החליפו ביניהם מיקום בתמונה, בלי ששום עצם השתנה/נעלם. <b>שינוי תצורה</b> - כל העצמים בתמונה סודרו מחדש, בפריסה כללית חדשה לגמרי - שינוי בדפוס הכולל, לא רק בפרט אחד. ⚠️ שלושת הסוגים משנים את התמונה ב'כמות' דומה של פיקסלים, אך כפי שנראה בשאלה הבאה, ההבדל ברמת-ההבחנה ביניהם עצום.","mnemo":"🔄🔀🌀 3 סוגי שינוי: זהות=חילוף-שחקן (מהדק↔חולץ). מקום=2 שחקנים מחליפים כיסאות. תצורה=כל הבמה מסתדרת מחדש."},{"id":"prof4_25b","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"אילו שינויים (מבין חילופי זהות, חילופי מקום, שינוי תצורה) זוהו טוב יותר ואילו פחות?","a":"זוהה טוב ביותר: שינוי תצורה (כמעט תמיד). זוהו פחות טוב: חילופי זהות וחילופי מקום (המשתתפים היו \"עיוורים\" להם לעיתים קרובות).","explain":"התוצאה המפתיעה: <b>שינוי תצורה</b> - שינוי בדפוס-הכולל של כל התמונה - זוהה <b>כמעט תמיד</b> על-ידי המשתתפים, בקלות יחסית. לעומת זאת, <b>חילופי זהות</b> ו<b>חילופי מקום</b> - שינויים ממוקדים בפריט אחד או שניים בלבד - זוהו הרבה פחות טוב, והמשתתפים היו לעיתים קרובות ממש 'עיוורים' להם, למרות שהביטו ישירות בתמונה. ⚠️ זו תוצאה שנוגדת אינטואיציה: היינו מצפים ש'שינוי גדול' (כל הסידור) יהיה קשה יותר להבחין ממנו ולא קל יותר - אך ההפך הוא הנכון, וההסבר לכך נמצא בשאלת-ההרהור הבאה, המקשרת זאת לעקרונות-הגשטלט.","mnemo":"🌀✅ תצורה=רואים תמיד (כל הבמה השתנתה). זהות/מקום=\"עיוורים\" לרוב (רק פרט אחד קטן השתנה)."},{"id":"prof4_reflection3","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע יש דיוק גבוה יותר בזיהוי שינוי תצורה לעומת חילופי מקום?","a":"שינוי תצורה משנה את הדפוס ההוליסטי הכללי (נתפס בקלות לפי עקרונות הגשטאלט). חילופי מקום דורשים זיכרון מדויק של מיקום כל עצם בנפרד — והזיכרון החזותי שלנו אינו שומר פרטים כאלה בדייקנות.","explain":"ההסבר לפרדוקס (למה שינוי-תצורה מזוהה בקלות, אך חילופי-מקום קשים) נשען על עקרונות-הגשטלט שנלמדו כבר בפרק 1: <b>שינוי תצורה</b> משנה את <b>הדפוס ההוליסטי הכללי</b> של כל הסצנה בבת-אחת - וכפי שראינו, אנחנו נוטים לתפוס תבניות-שלמות (הוליסטיות), לא פרטים-בודדים, ולכן שינוי בדפוס-הגלובלי בולט ונקלט בקלות, גם בלי לזכור את המיקום המדויק של כל עצם. <b>חילופי מקום</b>, לעומת זאת, משאירים את הדפוס-הכללי כמעט זהה - רק שני פרטים בודדים החליפו מיקום ביניהם. כדי לזהות שינוי כזה, יש צורך <b>לזכור במדויק</b> את המיקום הספציפי של כל עצם בנפרד - והזיכרון-החזותי שלנו אינו שומר בדייקנות פרטים-ספציפיים כאלה בכל פעם שאנחנו ממקדים מבט: אנחנו נסמכים על כך שהעולם הוא מקור-מידע יציב שאפשר 'לחזור אליו' בכל רגע, ולכן לא פיתחנו יכולת-זיכרון מדויקת למיקומים בודדים.","mnemo":"🖼️ תצורה=כל התמונה השתנתה (קל לראות). מקום=רק 2 פרטים זזו (המוח לא שומר \"מפה\" מדויקת של כל פרט)."},{"id":"prof4_26","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד תורמים הרמזים הדו־עיניים לתפיסת מרחק?","a":"שתי העיניים רואות בבואות שונות מעט (מרחק 5-7 ס\"מ ביניהן). המוח מתרגם הבדלים אלה למרחק: (1) פער בין־רשתי — ככל שההבדל בין שתי הבבואות גדול יותר, העצם נתפס קרוב יותר. (2) התכנסות — ככל שזווית פניית העיניים פנימה גדולה יותר (עד כ-3מ'), העצם נתפס קרוב יותר.","explain":"<b>רמזי-עומק דו-עיניים</b> תלויים בכך שיש לנו <b>שתי עיניים</b>, במרחק קבוע (כ-5-7 ס\"מ) אחת מהשנייה - כך שכל עין רואה זווית-מבט מעט שונה של אותה סצנה, וההבדל בין שתי הבבואות מתורגם על-ידי המוח למידע-מרחק. שני מנגנונים עיקריים: <b>פער בין-רשתי</b> - ככל שההבדל בין שתי הבבואות (ברשתית של כל עין) גדול יותר, כך העצם נתפס <b>קרוב יותר</b> (נסו: עצמו אצבע קרוב מאוד לעין ועצמו אותה בזוגות - ההבדל בין מה שכל עין רואה יהיה גדול, בניגוד לאצבע רחוקה). <b>התכנסות</b> - השרירים סביב העיניים צריכים 'לסובב' את שתי העיניים פנימה כדי להתמקד באותה נקודה - ככל שהזווית-הפנימית הזו גדולה יותר (עד כ-3 מטרים, מעבר לזה ההבדל בזווית זניח מדי כדי להיות אינפורמטיבי), כך העצם נתפס קרוב יותר. ⚠️ שני הרמזים האלה דורשים <b>שתי עיניים</b> כדי לפעול - זה מבדיל אותם מ'רמזי-תמונה' (השאלות הבאות), שפועלים גם עם עין אחת בלבד.","mnemo":"👀👀 2 עיניים = 2 מצלמות במרחק קטן. פער-גדול-בתמונות=קרוב (פער בין-רשתי). עיניים-פונות-פנימה-חזק=קרוב (התכנסות)."},{"id":"prof4_27","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו היסט תנועה יחסי וכיצד הוא מספק מידע על תפיסת המרחב?","a":"בתנועת הראש/הגוף, עצמים קרובים נראים \"זזים\" מהר ורחוק יותר מעצמים רחוקים. המרחקים היחסיים של עצמים בעולם קובעים את התנועה היחסית בבבואה הרשתית.","explain":"<b>היסט תנועה יחסי (motion parallax)</b> הוא רמז-מרחק שמתבסס על <b>תנועת הראש/הגוף שלנו</b> (לא נדרשות שתי עיניים דווקא, אלא תנועה) - כשאנחנו זזים (למשל, מסתכלים מחוץ לחלון מכונית נוסעת), עצמים <b>קרובים</b> אלינו נראים 'זזים' על הרשתית <b>מהר</b> ובכיוון מנוגד לתנועתנו, בעוד עצמים <b>רחוקים</b> (כמו ההרים באופק) נראים כמעט לא-זזים כלל, או זזים לאט מאוד ובאותו כיוון. המוח מתרגם את מהירות-התנועה-היחסית הזו על הרשתית לאומדן-מרחק: <b>ככל שהעצם נראה זז מהר יותר ביחס אלינו, כך הוא קרוב יותר בפועל</b>. ⚠️ שימו לב שזהו רמז <b>דינמי</b> (דורש תנועה כדי לפעול), בשונה מרמזי-תמונה הסטטיים שנלמדים בשאלות הבאות - וגם בשונה מהרמזים הדו-עיניים, כי הוא פועל היטב גם עם עין אחת בלבד, בתנאי שיש תנועה.","mnemo":"🚗🌳 מבט מחלון מכונית - עצים קרובים \"טסים\" מהר, הרים רחוקים כמעט לא זזים."},{"id":"prof4_28","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהם רמזי תמונה?","a":"מקורות מידע על מרחק הזמינים גם מעין אחת בלבד — אותו סוג מידע שקיים בתמונות/ציורים; משמשים אמנים ליצור עומק על משטח דו־ממדי.","explain":"<b>רמזי-תמונה</b> הם קטגוריית-מידע-מרחק שונה משני הסוגים הקודמים: הם <b>זמינים גם מעין אחת בלבד, ללא צורך בתנועה כלל</b> - כלומר, אותו סוג-מידע-בדיוק שקיים בתמונה/ציור <b>סטטי</b> ודו-ממדי (בניגוד לרמזים-דו-עיניים הדורשים שתי עיניים, ולהיסט-התנועה הדורש תזוזה). זו הסיבה שקוראים להם 'רמזי-תמונה' - הם עובדים גם על משטח שטוח לגמרי. <b>שימוש מעשי</b>: אמנים משתמשים ברמזים אלה כדי ליצור תחושת-עומק משכנעת בציור/צילום דו-ממדי - למרות שהמשטח עצמו שטוח לגמרי, המוח 'מפרש' אותו כבעל עומק תלת-ממדי בזכות רמזים אלה. בשאלה הבאה נמנה את ארבעת הסוגים הספציפיים של רמזי-תמונה.","mnemo":"🎨 רמזי תמונה = מה שצייר יכול לצייר על דף שטוח - עובד גם עם עין אחת סגורה."},{"id":"prof4_29","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מנו את ארבעת רמזי התמונה והסבירו כיצד הם משפיעים על תפיסת המרחב.","a":"הסתרה=עצם קטן יותר בבואה=רחוק יותר. גודל יחסי=עצם קטן יותר בבואה=רחוק יותר. פרספקטיבה קווית=קווים מתכנסים=מרחק גדל (אילוזיית פונזו). דחיסות מרקם=מרקם צפוף יותר=מרחק גדול יותר.","explain":"ארבעת רמזי-התמונה, כל אחד עובד לפי עיקרון-הגיוני שונה: <b>הסתרה (occlusion)</b> - כאשר עצם-אחד חוסם חלקית עצם-אחר, העצם-החוסם נתפס כקרוב יותר (עצם שלם תמיד 'מנצח' עצם חלקי-חסום). <b>גודל יחסי</b> - כשמניחים שני עצמים מאותו סוג/גודל-אמיתי, זה שנראה קטן-יותר בבבואה נתפס כרחוק יותר. <b>פרספקטיבה קווית</b> - קווים מקבילים במציאות (כמו פסי-רכבת) נראים <b>מתכנסים</b> ככל שהם מתרחקים לעבר האופק - ככל שהקווים קרובים יותר זה-לזה, המרחק נתפס גדול יותר (זהו הבסיס לאילוזיית פונזו - שני קווים זהים-באורכם, אך זה שממוקם 'קרוב' לנקודת-ההתכנסות נתפס כארוך יותר). <b>דחיסות מרקם</b> - מרקם (כמו דשא, חול, אבנים) שנראה <b>צפוף ומפורט פחות</b> נתפס כרחוק יותר, כי פרטים בודדים 'נמזגים' יחד ככל שהמרחק גדל.","mnemo":"🎨 4 טריקים של צייר: הסתרה (עצם מסתיר עצם=הוא קרוב יותר), גודל (קטן=רחוק), קווים-מתכנסים (לאופק=רחוק), מרקם-צפוף (=רחוק)."},{"id":"prof4_30","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי קביעות תפיסה ומדוע היא חשובה?","a":"נטייה לתפוס את מאפייני הגירוי הרחוק (העצם עצמו) כקבועים, למרות שינויים בגירוי הקרוב (הבבואה ברשתית). חשובה להישרדות — מאפשרת לזהות עצמים כיציבים למרות שינויים מתמידים בקלט החושי.","explain":"<b>קביעות תפיסה</b> היא היכולת המרשימה של המוח לתפוס את המאפיינים <b>האמיתיים והיציבים</b> של עצם בעולם (גודלו, צורתו, בהירותו), <b>למרות</b> שהמידע החושי הגולמי המגיע לעין (הגירוי הקרוב - הבבואה ברשתית) משתנה כל הזמן, בהתאם למרחק, לזווית, לתאורה. <b>למה זה קריטי להישרדות</b>: בלי קביעות-תפיסה, כל שינוי-קל בזווית-הראייה או בתאורה היה 'משגע' אותנו - עצם היה נראה כאילו הוא משתנה-צורה/גודל/צבע כל הזמן, ולא היינו מסוגלים לזהות עצמים כיציבים וקבועים. קביעות-התפיסה מאפשרת לנו 'לתקן' אוטומטית את השינויים בגירוי-הקרוב, ולראות את העולם כפי שהוא <b>באמת</b> (הגירוי-הרחוק היציב), לא כפי שהוא 'נראה' רגעית על הרשתית.","mnemo":"🏠 קביעות = הבית שלך \"נשאר אותו בית\" גם כשאתה מתרחק ממנו ורואה אותו קטן יותר."},{"id":"prof4_31","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי קביעות גודל? הציגו דוגמה.","a":"יכולת לתפוס גודל אמיתי של עצם למרות שינויים בגודל הבבואה ברשתית (המושפע ממרחק). דוגמה: ספר נתפס באותו גודל קרוב ורחוק; החדר של איימס מנצל כשל בקביעות זו ליצירת אילוזיה.","explain":"<b>קביעות גודל</b> - היכולת לתפוס את הגודל-האמיתי של עצם כקבוע, למרות ש<b>גודל-הבבואה ברשתית</b> משתנה משמעותית בהתאם למרחק (עצם רחוק יוצר בבואה קטנה, עצם קרוב יוצר בבואה גדולה, גם אם הגודל-האמיתי זהה). <b>הדוגמה</b>: ספר שאנחנו מחזיקים קרוב לעין, ואז מרחיקים, יוצר בבואה-רשתית שהולכת ומצטמצמת פיזית - אך אנחנו ממשיכים לתפוס אותו 'באותו גודל' לאורך כל הדרך, כי המוח משלב את מידע-הגודל עם מידע-המרחק (מהרמזים שנלמדו קודם) כדי 'לתקן' את השינוי. ⚠️ <b>חדר-איימס</b> מנצל תקלה מכוונת בקביעות-הגודל: החדר בנוי בצורה מעוותת גיאומטרית (לא באמת מלבני), כך שהמוח, שמניח בטעות שהחדר רגיל, מפרש את גדלי-הבבואות באופן שגוי - אדם באחת הפינות נראה ענק, ובפינה השנייה זעיר, למרות שבמציאות שניהם באותו גודל בערך.","mnemo":"🏰 חדר איימס = חדר-קסמים בגן שעשועים - מרמה את מוח על המרחק, ולכן אנשים \"נראים\" ענקים/ננסים."},{"id":"prof4_32","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי קביעות צורה? הציגו דוגמה.","a":"תפיסה נכונה של הצורה האמיתית של עצם למרות שהבבואה ברשתית שונה (למשל, מוטה). דוגמה: מטבע מסתובב נראה כאליפסה/מלבן צר על הרשתית, אך תמיד נתפס כעגול.","explain":"<b>קביעות צורה</b> - תפיסה נכונה של הצורה-האמיתית של עצם, למרות שהבבואה שלו ברשתית משתנה (מוטה/מעוותת) בהתאם לזווית-הצפייה. <b>הדוגמה</b>: מטבע עגול, כשמסתכלים בו מזווית (לא ישר-מלמעלה), יוצר בבואה-רשתית שהיא <b>אליפסה</b> או אפילו קו-צר כמעט-שטוח (בזווית קיצונית) - כי גיאומטרית, זו הצורה שהעיגול-המוטה 'מטיל' על משטח דו-ממדי. ובכל זאת, אנחנו ממשיכים לתפוס את המטבע כ<b>עגול</b> תמיד, לא כאליפסה - המוח 'יודע' (מניסיון) שמטבעות עגולים, ומתקן את הצורה-המעוותת-לכאורה בהתאם לזווית-הצפייה הידועה.","mnemo":"🪙 מטבע מסתובב נראה כמו אליפסה על העין, אך המוח \"מתקן\" ותמיד רואה עיגול אמיתי."},{"id":"prof4_33","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי קביעות הבהירות? הציגו דוגמה.","a":"נטייה לתפוס גוון (לבן/אפור/שחור) של עצם כקבוע, למרות שינויי תאורה. דוגמה: חולצה לבנה נראית בהירה באותה מידה בחדר חשוך ובשמש, כי אחוז האור המוחזר נשאר קבוע.","explain":"<b>קביעות הבהירות</b> - הנטייה לתפוס את הגוון (כמה בהיר/כהה, לבן/אפור/שחור) של עצם כ<b>קבוע</b>, למרות שינויים משמעותיים בתאורה-הסביבתית. <b>הדוגמה</b>: חולצה לבנה נראית 'לבנה באותה מידה בדיוק' גם בחדר-חשוך למחצה וגם בשמש-חזקה בחוץ - למרות שבמונחים פיזיקליים-טהורים, כמות-האור המוחזרת בפועל מהחולצה שונה עצומה בין שני המצבים. ⚠️ ההסבר: המוח לא מסתכל על כמות-האור <b>המוחלטת</b> המוחזרת מהעצם, אלא על ה<b>אחוז היחסי</b> של אור שהעצם מחזיר <b>ביחס לסביבתו</b> (חולצה תמיד תחזיר אחוז גבוה יותר מהאור הפוגע בה, בהשוואה לרקע כהה יותר סביבה) - ואחוז זה נשאר קבוע גם כשהתאורה-הכללית משתנה, ולכן קביעות-הבהירות נשמרת.","mnemo":"👕 חולצה לבנה = תמיד \"הכי בהירה\" בחדר, בין בשמש ובין בחושך - כי האחוז (לא הכמות) של האור שהיא מחזירה נשאר קבוע."},{"id":"prof4_34","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הבחינו בין עיבוד מלמטה־למעלה למלמעלה־למטה והשפעתם על התפיסה.","a":"מלמטה־למעלה=מתחיל בגירוי הפיזי עצמו (נתונים). מלמעלה־למטה=מושפע מציפיות/ידע/הקשר קודם. יחד הם קובעים את התפיסה הסופית.","explain":"עיבוד <b>מלמטה-למעלה (bottom-up)</b> מתחיל <b>בגירוי הפיזי הגולמי עצמו</b> - נתונים חושיים 'טהורים' שזורמים 'מלמעלה' (מהעולם החיצוני, דרך הקולטנים) ומטה (למוח), בלי שהם מושפעים מציפיות/ידע-קודם. עיבוד <b>מלמעלה-למטה (top-down)</b> הוא ההפך: הוא מושפע ממה שכבר 'נמצא בראש' - ציפיות, ידע-קודם, הקשר, מוטיבציות - שמעצבים איך אנחנו מפרשים את הגירוי-הגולמי, לפעמים עוד לפני שהניתוח-החושי-הטהור הושלם. ⚠️ הנקודה החשובה ביותר: התפיסה שלנו, בכל רגע נתון, היא <b>תמיד תוצר של שני התהליכים גם יחד</b>, לא של אחד בלבד - הגירוי-הגולמי מספק את 'חומר-הגלם', וההקשר/הידע-הקודם 'מארגן' ו'מפרש' אותו למשמעות סופית.","mnemo":"⬆️⬇️ מלמטה-למעלה=מהעולם (עובדות). מלמעלה-למטה=מהראש שלך (ציפיות). שניהם תמיד ביחד."},{"id":"prof4_35","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע עיבוד מלמעלה־למטה נקרא גם \"עיבוד שמקורו במונחים/השערות\"?","a":"כי מושגים והשערות המאוחסנים בזיכרון (לא רק הגירוי עצמו) הם שמשפיעים על פירוש הנתונים החושיים.","explain":"עיבוד מלמעלה-למטה נקרא לפעמים גם '<b>עיבוד שמקורו במונחים/השערות</b>' (conceptually-driven processing) כי הכיוון-ההפוך הוא בדיוק המפתח להבנתו: זה <b>לא</b> הגירוי-הגולמי שקובע את הפרשנות-הסופית, אלא ה<b>מושגים וההשערות</b> שכבר קיימים בזיכרון (ידע-עולם, ציפיות, הקשר-נוכחי) שמכתיבים איך אנחנו 'קוראים' את הנתונים החושיים. במילים אחרות - אנחנו לא רק 'קולטים' את המציאות באופן פסיבי; אנחנו באים אליה עם <b>השערה מוקדמת</b> על מה שאמורים לראות/לשמוע, וההשערה הזו מנחה ומעצבת את הפרשנות-בפועל, לעיתים אפילו יותר מהגירוי הגולמי עצמו.","mnemo":"🔗 מלמעלה-למטה = הזיכרון שלך \"מדבר\" עם מה שאתה רואה, לא רק הגירוי הגולמי."},{"id":"prof4_36","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד מסביר השחזור הפונמי את התפיסה מלמעלה־למטה?","a":"כשרעש מכסה חלק ממילה, ההקשר (לא רק הצלילים שנשמעו) הוא שקובע איזו מילה \"שומעים\" — ממחיש כיצד ידע/הקשר קודמים ממלאים פערים בקלט החושי.","explain":"<b>שחזור פונמי (phonemic restoration)</b> הוא הדגמה מרשימה במיוחד לעוצמת עיבוד-מלמעלה-למטה: כאשר רעש (למשל שיעול, או צליל-רקע) מכסה חלק ממילה בזרם-דיבור, אנחנו לרוב <b>לא</b> שמים לב בכלל שחלק מהמילה חסר - אנחנו 'שומעים' את המילה במלואה, כאילו לא היה שום רעש. <b>ההסבר</b>: המוח משתמש ב<b>הקשר המשפטי הכולל</b> (לא רק בצלילים שבאמת הגיעו לאוזן) כדי 'למלא' באופן פעיל את החלק החסר - אם המשפט הסובב הוא, למשל, 'אני __הב אותך', ההקשר הרגשי מכתיב שהמילה החסרה היא 'אוהב', וכך אנחנו 'שומעים' O-ה-ב שלם, גם שהחלק הראשון בפועל הוחלף ברעש. זהו הוכחה חזקה שהתפיסה השמיעתית שלנו לא רק מקליטה צלילים - היא <b>בונה באופן פעיל</b> את מה ש'צריך' להיות שם, לפי ידע-קודם והקשר.","mnemo":"📻 רעש מכסה מילה בטלפון - אתה \"משלים\" אותה לפי ההקשר, לא לפי הצליל בפועל (שחזור פונמי)."},{"id":"prof4_37","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע חשוב לשלב בין עיבוד מלמטה־למעלה למלמעלה־למטה בתפיסה?","a":"רק מלמטה־למעלה=נתקעים במציאות המוחשית של כאן ועכשיו, ללא הכללה. רק מלמעלה־למטה=עלולים ללכת לאיבוד בעולם ציפיות פרטי. שילוב=תפיסה מדויקת המשרתת את צרכינו.","explain":"שילוב שני סוגי-העיבוד הכרחי, כי כל אחד לבדו נכשל בדרך שונה: <b>רק מלמטה-למעלה</b> (ללא ציפיות/הקשר כלל) - נתקעים בקליטת המציאות המוחשית של <b>כאן-ועכשיו בלבד</b>, ללא יכולת להכליל, לצפות, או להשלים מידע חסר (כמו רעש שמכסה מילה - בלי עיבוד-מלמעלה-למטה, לא היינו מבינים מילים שנקטעו כלל). <b>רק מלמעלה-למטה</b> (ללא קלט-חושי אמיתי) - עלולים 'ללכת לאיבוד' בעולם-ציפיות-פרטי ומנותק מהמציאות - לראות/לשמוע רק את מה שאנחנו <b>מצפים</b> לראות, ולא את מה שבאמת קורה (הבסיס להטיות-קוגניטיביות ולתפיסה מוטית). <b>השילוב</b> בין השניים הוא בדיוק מה שמייצר תפיסה מדויקת ומועילה - מספיק-נאמן למציאות (בזכות מלמטה-למעלה) ומספיק-חכם/יעיל (בזכות מלמעלה-למטה שממלא פערים וחוסך משאבי-עיבוד).","mnemo":"⚖️ רק-גולמי=תקוע בהווה. רק-ציפיות=הזיות. שילוב=תפיסה נכונה - צריך את שניהם."},{"id":"prof4_38","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו את שלושת סוגי המערכים והשפעתם על תהליך התפיסה.","a":"מוטורי=מוכנות לתגובה מהירה מוכנה מראש (אצן). מנטלי=מוכנות לפתרון בעיות לפי כללים מוכרים (עלול להפריע כשהמצב חדש). תפיסתי=מוכנות לאתר גירוי בהקשר נתון (אם השומעת בכי תינוק). מערך משפיע על פירוש גירויים דו־משמעיים.","explain":"שלושת סוגי-<b>המערך (set)</b> הם צורות שונות של 'מוכנות מוקדמת' שמעצבת איך נתפוס/נגיב לגירוי הבא, עוד לפני שהוא מגיע: <b>מערך מוטורי</b> - מוכנות פיזית לבצע תגובה-מהירה שכבר 'הוכנה' מראש (למשל, אצן על קו-הזינוק, שרירים כבר במתח-מוכנות לפני יריית-הפתיחה). <b>מערך מנטלי</b> - מוכנות קוגניטיבית לפתור בעיה לפי כללים/אסטרטגיה מוכרים-מראש - עלול <b>להפריע</b> דווקא כשהמצב-בפועל שונה ודורש גישה חדשה (זו בעצם 'נוקשות מחשבתית' - נצמדים לפתרון-ישן גם כשהוא כבר לא מתאים). <b>מערך תפיסתי</b> - מוכנות לזהות גירוי ספציפי בהקשר נתון (למשל, אם מצפים לשמוע בכי-תינוק, אנחנו 'מכוונים' לזהות אותו מהר יותר גם בתוך רעש-רקע). ⚠️ המשותף לשלושתם: המערך הוא צורה של עיבוד-מלמעלה-למטה - הוא <b>לא</b> תוצר של הגירוי הבא-עצמו, אלא של מצב-מוכנות שהתקבע מראש, לפעמים בעזרה ולפעמים לרועץ.","mnemo":"🏃💭👂 3 מוכנויות: מוטורי=אצן-דרוך-בקו-זינוק. מנטלי=פותר-חידה-לפי-הרגל (עלול לתקוע על בעיה חדשה). תפיסתי=אמא-מכוונת-לבכי-תינוק."},{"id":"prof4_reflection4","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מקמו את המונחים בטבלה לפי שלב תפיסה ומסלול עיבוד: תהליך חישה, תהליך החלטה, לכידה שמקורה בגירוי, בחירה מכוונת־מטרה, שחזור פונמי, מערך, הטיית תגובה.","a":"חישה: תהליך חישה=מלמטה־למעלה; תהליך החלטה+הטיית תגובה=מלמעלה־למטה. ארגון: לכידה שמקורה בגירוי=מלמטה־למעלה; בחירה מכוונת־מטרה=מלמעלה־למטה. זיהוי/היכר: שחזור פונמי+מערך=מלמעלה־למטה.","explain":"טבלה זו מארגנת מחדש שבעה מונחים מרכזיים מהפרק לפי שני צירים גם-יחד: <b>שלב-התפיסה</b> (חישה/ארגון/זיהוי) ו<b>מסלול-העיבוד</b> (מלמטה-למעלה/מלמעלה-למטה) - תרגיל שמכריח לראות שהמונחים לא 'מפוזרים אקראית' אלא מתאימים בעקביות לתבנית. <b>בשלב החישה</b>: תהליך-חישה (הרגישות הפיזית לגירוי) הוא מלמטה-למעלה; תהליך-החלטה+הטיית-תגובה (מה מדווחים) הם מלמעלה-למטה. <b>בשלב הארגון</b>: לכידה-שמקורה-בגירוי (עיגול-חדש שתופס קשב) היא מלמטה-למעלה; בחירה-מכוונת-מטרה (מה מחפשים בכוונה) היא מלמעלה-למטה. <b>בשלב הזיהוי</b>: שחזור-פונמי (השלמת מילה חסרה לפי הקשר) ומערך (מוכנות-מוקדמת) שניהם מלמעלה-למטה - כי בשלב-הזיהוי, כמעט תמיד ידע-קודם והקשר הם שמכריעים את המשמעות הסופית. ⚠️ שימו לב: בשלב-הזיהוי אין דוגמה 'טהורה' של מלמטה-למעלה בטבלה - וזה הגיוני, כי ברגע שמגיעים לשלב של מתן-משמעות, כמעט תמיד מעורב ידע-קודם.","mnemo":"⬆️⬇️ מלמטה-למעלה=חישה+לכידה-מגירוי (הגולמי). מלמעלה-למטה=החלטה+הטיה+בחירה-מטרה+שחזור-פונמי+מערך (כולם מהראש שלך)."},{"id":"quiz4_1","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"______ הוא העצם הממשי בעולם ואילו _______ הוא הבבואה האופטית שלו על הרשתית. (גירוי קרוב, גירוי רחוק / גירוי רחוק, גירוי קרוב / גירוי פיזי, גירוי מנטאלי / גירוי מנטאלי, גירוי פיזי)","a":"גירוי רחוק, גירוי קרוב (העצם עצמו מול הדימוי שלו על הרשתית)","explain":"המונחים 'גירוי רחוק' ו'גירוי קרוב' הם בסיס-השפה של כל פרק התפיסה, וקל להתבלבל בהם כי הם מנוגדים-אינטואיטיבית לציפייה: <b>גירוי רחוק (distal stimulus)</b> = העצם <b>עצמו</b> הקיים בעולם החיצון (למשל, החתול האמיתי היושב על הספה) - נקרא 'רחוק' כי הוא נמצא <b>מחוץ</b> לגוף שלנו, במרחק מהעין. <b>גירוי קרוב (proximal stimulus)</b> = הבבואה האופטית של אותו עצם על-גבי הרשתית שלנו - נקרא 'קרוב' כי הוא ממש <b>בתוך</b> העין שלנו, קרוב פיזית ככל האפשר. ⚠️ כל אתגרי-התפיסה שנלמדים בפרק (קביעות, אילוזיות, דו-משמעות) נובעים בדיוק מהפער בין השניים: הגירוי-הרחוק (המציאות) יכול להישאר יציב, בעוד הגירוי-הקרוב (הבבואה) משתנה כל הזמן עם תנועה/תאורה/זווית - והמוח צריך 'לפענח' את הגירוי-הרחוק היציב מתוך הגירוי-הקרוב המשתנה.","mnemo":"🌍➡️👁️ רחוק=העולם האמיתי. קרוב=התמונה על העין שלך."},{"id":"quiz4_3","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"בעודכם מתקרבים ומתקרבים לעברו של פיל הוא (נראה לכם באותו הגודל / נראה לכם כגדול יותר / נראה לכם כקטן יותר / נמצא בתנועה)","a":"נראה לכם באותו הגודל (קביעות גודל)","explain":"כשמתקרבים לעברו של פיל, <b>הגירוי הקרוב</b> (הבבואה שלו על הרשתית) הולך וגדל פיזית באופן משמעותי - אלו עובדות אופטיות פשוטות. אך אנחנו <b>לא</b> תופסים את הפיל כ'גדל' לנגד עינינו - הוא נראה לנו באותו הגודל-האמיתי לאורך כל הדרך, רק <b>קרוב יותר</b>. זו ההגדרה המדויקת של <b>קביעות גודל</b>: המוח משלב את גידול-הבבואה עם רמזי-המרחק (שאנחנו יודעים שאנחנו מתקרבים) כדי 'לתקן' ולתפוס את הגודל-האמיתי-והקבוע של הפיל, למרות שהמידע הגולמי-החושי משתנה כל הזמן.","mnemo":"🐘 פיל שמתקרב \"נשאר\" באותו גודל בעיניים שלך - קביעות גודל."},{"id":"quiz4_4","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"[VRVR תבנית] הנטייה לקבץ את כל ה-V וה-R נובעת בשל עקרון ה: (סמיכות / דמיון / דמות רקע / גורל משותף)","a":"דמיון (V ו-R מקובצים כי הם דומים חזותית זה לזה)","explain":"עקרונות-הגשטלט (שנלמדו לראשונה בפרק 1, כאן ביישום קונקרטי) מתארים כללים אוטומטיים שלפיהם המוח מקבץ אלמנטים בודדים לצורות-שלמות. <b>עקרון הדמיון</b> קובע: אלמנטים ה<b>נראים דומים</b> זה-לזה (בצורה, בצבע, בגודל) נוטים להיתפס כ<b>קבוצה אחת</b> - גם אם הם לא צמודים פיזית. בתבנית של V-ים ו-R-ים מעורבים, המוח מקבץ את כל ה-V יחד (כי הם דומים חזותית זה-לזה) ואת כל ה-R יחד בנפרד - למרות שהאותיות מפוזרות ומעורבות מרחבית. ⚠️ אל תתבלבלו עם 'עקרון הסמיכות', שמקבץ לפי <b>מיקום פיזי קרוב</b>, לא לפי דמיון-חזותי.","mnemo":"🔤 V עם V, R עם R - נראים דומים, אז מתקבצים יחד (דמיון)."},{"id":"quiz4_5","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"עידן חושב כי שמע רעש, למרות שרעש זה לא הופיע. בהתאם לתיאורית גילוי אותות, התגובה של עידן הינה (החטאה / פגיעה / דחייה נכונה / אזעקת שווא)","a":"אזעקת שווא (חושב שיש גירוי, אך אין באמת)","explain":"יישום ישיר של טבלת-4-התוצאות בתיאוריית גילוי-האותות: עידן <b>חושב</b> ('מדווח: כן, שמעתי') שהוא שמע רעש, אך הרעש <b>לא באמת הופיע</b> (אין-אות במציאות). לפי הטבלה: כאשר אין-אות ונאמר 'כן' - זו בדיוק ההגדרה של <b>אזעקת-שווא</b> (False Alarm). ⚠️ אל תתבלבלו עם 'החטאה' - זה המקרה ההפוך: <b>יש</b> אות אמיתי, אבל הצופה מדווח 'לא'. כאן קורה בדיוק ההפך: <b>אין</b> אות, אבל עידן מדווח 'כן'.","mnemo":"👻 חושב ששמע, אבל לא היה כלום = רואה רוחות = אזעקת שווא."},{"id":"quiz4_6","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"הפער המינימאלי המובחן מהווה סוג של______ (פעולה / מחסום / שגיאה / נקודת סף / מתודולוגיה)","a":"נקודת סף (הפער הקטן ביותר שניתן להבחין בו)","explain":"<b>הפער המינימלי המובחן (JND - Just Noticeable Difference)</b> הוא בדיוק ההגדרה הפורמלית של <b>סף-ההבדל</b> שנלמד בפרק - שם נרדף מדויק לאותו מושג, לא מונח נפרד. זו נקודת-<b>סף</b> (threshold), בדיוק כמו סף-מוחלט - אלא שכאן מדובר בסף למציאת-<b>הבדל</b> בין שני גירויים קיימים, לא סף לזיהוי גירוי בודד מתוך העדר-גירוי. ⚠️ הטעות הנפוצה: לחשוב שזו 'שגיאה' או 'מתודולוגיה' - אלו מסיחים; JND הוא בדיוק סוג-של-<b>נקודת-סף</b> מדידה, לא הליך-מחקר ולא כישלון.","mnemo":"🚧 JND = קו-הגבול (סף) שממנו והלאה מתחילים להבחין."},{"id":"quiz4_9","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"הנטייה להשלים חלקי תמונה לכלל שלם, נקראת לפי חוקי הגשטאלט (עקרון הסמיכות / עקרון הדמיון / עקרון ההמשכיות הטובה / עקרון הסגירות / עקרון הגורל המשותף / תשובות 3+4 נכונות)","a":"עקרון הסגירות (המוח \"סוגר\" צורות חלקיות לשלמות)","explain":"<b>עקרון הסגירות</b> הוא בדיוק ההגדרה של הנטייה להשלים חלקי-תמונה לכלל-שלם: המוח 'סוגר' צורות חסרות/מקוטעות ותופס אותן כדמויות שלמות ומוכרות, גם כשחלק מהמידע-החזותי בפועל חסר. ⚠️ שימו לב לאפשרות המסיחה 'תשובות 3+4 נכונות' (המשכיות-טובה+סגירות) - זו טעות: המשכיות-טובה עוסקת בקווים/עקומות הנתפסים כממשיכים בכיוון-חלק (לא בהשלמת-חלל בתוך מתאר סגור), בעוד סגירות עוסקת ספציפית בהשלמת-צורה-שלמה מתוך חלקים-חסרים. השאלה מבקשת 'השלמת חלקי תמונה לכלל שלם' - זו ההגדרה המדויקת של סגירות בלבד.","mnemo":"🧩 חלק חסר במעגל, המוח \"סוגר\" אותו = סגירות."},{"id":"quiz4_11","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"תופעת מסיבת הקוקטייל מתייחסת ליכולת שלנו ל (חלוקת קשב / שמיעה אבסולוטית / תהליכי עיבוד ראשוניים / האזנה דיכוטית)","a":"חלוקת קשב (שם שלנו \"פורץ\" גם כשקשובים לשיחה אחרת)","explain":"תופעת מסיבת-הקוקטייל מדגימה בדיוק את היכולת ל<b>חלוקת קשב</b>: למרות שהקשב-המודע שלנו נמצא כולו על שיחה-אחת, חלק כלשהו מהמוח ממשיך 'לנטר' ברקע גם את יתר-הערוצים (הלא-קשובים) - ברמה חלקית ולא-מודעת - וכשמופיע בהם גירוי בעל-משמעות-מיוחדת (שמנו), הקשב 'מתחלק' ומתעבר אליו מיידית. ⚠️ אל תתבלבלו עם 'האזנה דיכוטית' - זו רק <b>שיטת-המחקר</b> (השמעת מסר שונה בכל אוזן) ששימשה לחקור את התופעה, לא התופעה/היכולת עצמה שהשאלה שואלת עליה.","mnemo":"🎧🎧 קוקטייל = 2 אוזניים בו-זמנית = חלוקת קשב (לא רק ערוץ אחד)."},{"id":"quiz4_13","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"באיזה שלב של התפיסה מקבל המתפס משמעות? (הסתגלות חישתית / ארגון תפיסתי / זיהוי והיכר / חישה)","a":"זיהוי והיכר (השלב שבו נותנים משמעות למה שנתפס)","explain":"שלושת שלבי-התפיסה (חישה → ארגון → זיהוי/היכר) בנויים כשרשרת שבה <b>המשמעות</b> מתווספת רק בשלב האחרון: בחישה, הקולטנים רק הופכים אנרגיה-פיזית לדחף-עצבי (עדיין בלי כל 'מובן'). בארגון, המוח בונה ייצוג-קוהרנטי (צורה/גודל/מיקום) - אבל עדיין בלי לדעת 'מה זה'. רק ב<b>זיהוי-והיכר</b>, המתפס-המאורגן מושווה לזיכרונות קיימים, וניתנת לו <b>משמעות</b> - 'זה כלב', 'זה מסוכן', 'זה בית'. זהו בדיוק השלב שבו 'מתפס' (percept) הופך ל'הבנה' של מה שאנחנו רואים.","mnemo":"🏷️ מדבקת-השם (נותנים משמעות) = שלב זיהוי/היכר."},{"id":"quiz4_14","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"אתם מוקסמים מציור; מזווית אחת רואים שני קלסתרים, מזווית אחרת אגרטל. זוהי דוגמה ל: (סף מוחלט / דו-משמעות / תהליך מנוגד / אשליית תפיסה)","a":"דו-משמעות (אותו הגירוי מתפרש בשתי דרכים תלוי בפרשנות)","explain":"כשאותו ציור-בדיוק מתפרש בשתי דרכים בלתי-ניתנות-לחפיפה בו-זמנית (שני קלסתרים / אגרטל) - זו ההגדרה המדויקת של <b>דו-משמעות</b>: הגירוי החושי (החישה) זהה לחלוטין בשני המקרים, אך התפיסה/הזיהוי 'נעה' בין שתי-פרשנויות תקינות באותה מידה, בלי יכולת לראות את שתיהן בו-זמנית. ⚠️ אל תתבלבלו עם 'אשליית-תפיסה' (אילוזיה) - באילוזיה יש פרשנות-שגויה-אחת וקבועה (כולם 'טועים' באותו הכיוון), בעוד בדו-משמעות אין 'טעות' כלל - שתי הפרשנויות נכונות ולגיטימיות באותה מידה.","mnemo":"🦆🐰 הברווז/ארנב = דו-משמעות."},{"id":"quiz4_15","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"נכנסתם לחדר והוצפתם בריח בושם. עם הזמן, המודעות שלכם לריח פחתה. זוהי דוגמה ל: (פונקציה פסיכומטרית / אילוזיה / התמרה / הסתגלות חושית)","a":"הסתגלות חושית (החושים \"מתעייפים\" מגירוי קבוע וממושך)","explain":"התחושה של 'ריח שנעלם' עם הזמן, למרות שהגירוי (הבושם) עצמו נשאר קיים בסביבה ולא השתנה, היא הדגמה קלאסית ל<b>הסתגלות חושית</b>: מערכת-החישה (כאן, קולטני-הריח) פשוט 'מתעייפת' ומאבדת רגישות לגירוי <b>קבוע וממושך</b> - זה מנגנון-הישרדותי שמשחרר משאבי-עיבוד לזיהוי גירויים <b>חדשים</b> בסביבה, שהם לרוב חשובים יותר. ⚠️ אל תתבלבלו עם 'התמרה' (המרת אנרגיה-פיזית לדחף-עצבי, לא קשור לירידה-ברגישות-עם-הזמן) או 'אילוזיה' (פרשנות-שגויה של גירוי, לא ירידה-ברגישות אליו).","mnemo":"👃 הבושם שנעלם = הסתגלות חושית."},{"id":"quiz4_16","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"למצוא סף ההבדל — הנקודה שבה מזהים גירויים כשונים ב-_____ מצעדי הניסוי. (75% / 25% / 50% / 100%)","a":"50% (נקודת סף מוגדרת כזיהוי נכון במחצית המקרים)","explain":"הגדרת-הסף (בין אם סף-מוחלט ובין אם סף-הבדל) תמיד נקבעת סטטיסטית באותה נקודה - <b>50%</b> - כי אין נקודה חדה שמתחתיה 'לעולם לא' זיהוי ומעליה 'תמיד' זיהוי; הזיהוי-בפועל משתנה בין ניסוי-לניסוי אצל אותו אדם, בגלל תנודות-פנימיות בקשב/עייפות/רעש-עצבי. לכן ה-50% מוגדר כנקודת-אמצע אזור-המעבר ההדרגתי (הצורה בצורת-S של הפונקציה-הפסיכומטרית), לא כ'רגע-קסם' מדויק שבו זיהוי הופך לוודאי.","mnemo":"5️⃣0️⃣% תמיד 50% - גם לסף מוחלט וגם לסף ההבדל."},{"id":"quiz4_17","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"החלפת צורה אחת של אנרגיה פיזיקלית באחרת נקראת בשם: (קליטה חושית / התמרה / קליטת ראייה / הסתגלות חושית)","a":"התמרה (הפיכת אנרגיה חיצונית לאות עצבי במוח)","explain":"<b>התמרה (transduction)</b> היא ההגדרה המדויקת של החלפת סוג-אחד של אנרגיה-פיזיקלית (אור, קול, לחץ) בסוג-אחר לגמרי - דחף-עצבי חשמלי-כימי, ה'שפה' היחידה שהמוח מבין. ⚠️ אל תתבלבלו עם 'קליטה חושית' או 'קליטת ראייה' - אלו מתארים רק את <b>שלב-הקליטה</b> (הגירוי פוגע בקולטן), לא את פעולת-ההמרה עצמה מסוג-אנרגיה-אחד לאחר, שהיא הליבה של מושג ההתמרה.","mnemo":"🔌 שקע-החשמל (ממיר אנרגיה) = התמרה."},{"id":"quiz4_18","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"ענת מגיעה למסיבה ומחפשת את בעלה גיורא. זוהי דוגמה ל: (הסתגלות חושית / לכידה שמקורה בגירוי / אינטגרציה בזמן / קשב שמקורו מטרה)","a":"קשב שמקורו מטרה (מחפשים במכוון, לא נתפסים גירוי אקראי)","explain":"התרחיש של ענת המחפשת את בעלה גיורא במסיבה הוא דוגמה טהורה ל<b>קשב שמקורו-מטרה</b> (בחירה ממוקדת-מטרה): ענת <b>מכוונת באופן מודע ומכוון</b> את הקשב שלה לחפש דמות ספציפית (גיורא) מתוך כל הפנים-הרבים במסיבה - זהו קשב מלמעלה-למטה, מונע על-ידי מטרה פנימית (למצוא את בעלה), ולא על-ידי איזשהו גירוי בולט-במיוחד שקורא לה. ⚠️ אל תתבלבלו עם 'לכידה-שמקורה-בגירוי' - זה יהיה המקרה ההפוך, שבו <b>גיורא עצמו</b> (או משהו בולט אחר) 'תופס' את קשבה של ענת אוטומטית, בלי שהיא מחפשת אותו בכוונה.","mnemo":"🍫 חלון-הראווה - מחפשים במכוון = קשב ממוקד-מטרה."},{"id":"quiz4_19","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"לטבעת של יואב יש סדק קטן. עקרון ה_____ מסביר מדוע רוב האנשים תופסים אותה כשלמה. (סמיכות / סגירות / המשכיות הטובה / דמיון)","a":"סגירות (המוח משלים את החלק החסר לצורה שלמה)","explain":"<b>עקרון הסגירות (closure)</b> בעקרונות-הגשטלט: המוח נוטה 'לסגור' צורות חלקיות/לא-שלמות ולהשלים אותן לכלל דמות-שלמה ומוכרת, גם כשבפועל חסר חלק מהמידע-החזותי. בטבעת עם סדק קטן, המוח 'ממלא' את הפער-הקטן באופן אוטומטי ותופס טבעת-שלמה, כי המוח 'מעדיף' דמויות-שלמות ומוכרות על-פני פרשנות-מדויקת-אך-מקוטעת של הקלט הגולמי. ⚠️ הבדילו מ'המשכיות-טובה', שעוסקת בקווים/עקומות שנתפסות כממשיכות בכיוון-חלק, לא בהשלמת-חלל בתוך צורה סגורה.","mnemo":"💍 טבעת עם סדק קטן שהמוח \"מתקן\" לשלמה = סגירות (כמו הטבעת החסרה)."},{"id":"quiz4_20","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"יד קרובה מכסה חלק מיד רחוקה יותר. זוהי דוגמת _____ כרמז של מרחק. (הסתרה / היסט תנועה יחסי / התכנסות / מרקם)","a":"הסתרה (עצם קרוב חוסם חלק מעצם רחוק - רמז עומק)","explain":"<b>הסתרה (occlusion)</b> - אחד מארבעת רמזי-התמונה - פועלת על עיקרון פשוט וישיר: כאשר עצם-אחד <b>חוסם חלקית</b> את המראה של עצם-אחר, המוח מסיק אוטומטית שהעצם-החוסם (שנראה 'שלם') נמצא <b>קרוב יותר</b> מהעצם-הנחסם (שנראה 'חלקי'/'קטוע'). כשיד קרובה מכסה חלק מיד רחוקה יותר, אין צורך בשום רמז נוסף - המוח 'יודע' מיידית שהיד-החוסמת קרובה יותר, אך ורק מעצם העובדה שהיא זו שחוסמת, לא נחסמת.","mnemo":"✋ יד קרובה מכסה יד רחוקה = הסתרה (מי שמכסה קרוב יותר)."},{"id":"quiz4_21","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"כשמישהו מתקרב אליכם, הבבואה שלו על הרשתית הולכת וגדלה, אך אינכם תופסים אותו כהולך וגדל. זוהי דוגמה ל: (הסתגלות חושית / קביעות התנועה / קביעות הגודל / תופעת פי)","a":"קביעות הגודל (התפיסה \"מתקנת\" את שינוי גודל התמונה על הרשתית)","explain":"<b>קביעות הגודל</b> היא ההסבר המדויק לתופעה: כשמישהו מתקרב אלינו, <b>הגירוי הקרוב</b> (הבבואה שלו על הרשתית) גדל פיזית ומשמעותית - עובדה אופטית טהורה. אך <b>אנחנו לא תופסים</b> אותו כ'הולך וגדל' - אלא כ'אותו אדם, פשוט מתקרב'. המוח משלב את הגדילה-בבבואה עם מידע-מרחק אחר (רמזי-עומק) כדי לתקן ולשמר את תפיסת-הגודל-האמיתי כקבוע, למרות השינוי המתמיד בקלט-החושי - זו בדיוק ההגדרה של קביעות-הגודל.","mnemo":"🚶 החבר שמתקרב ונשאר \"אותו גודל\" בעיניים = קביעות גודל."},{"id":"quiz4_22","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"ב________, נקודת המוצא היא נתונים חושיים מהסביבה (רמזי תמונה / עיבוד שמקורו בהשערה / עיבוד מלמטה-למעלה / עיבוד מלמעלה-למטה)","a":"עיבוד מלמטה-למעלה (מתחילים מהגירוי החושי הגולמי, לא מציפייה)","explain":"עיבוד <b>מלמטה-למעלה (bottom-up)</b> הוא בדיוק העיבוד שנקודת-המוצא שלו היא <b>הנתונים החושיים הגולמיים</b> מהסביבה עצמה - לא ציפיות, לא הקשר, לא ידע-קודם - אלא רק מה שבאמת מגיע מהעולם דרך הקולטנים החושיים. ⚠️ אל תתבלבלו עם 'רמזי-תמונה' - זה מונח מקטגוריה שונה לגמרי (סוגי מידע-מרחק), לא סוג-עיבוד; ועם עיבוד-מלמעלה-למטה, שהוא בדיוק ההפך - מונחה על-ידי ציפיות/השערות, לא על-ידי הגירוי הגולמי בלבד.","mnemo":"⬆️ מהעולם למעלה = מלמטה-למעלה (הגירוי הגולמי קודם)."},{"id":"quiz4_23","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"צפירת משאית כיסתה על הצליל \"או\" במילה \"אוהב\", אך מיכל הגיבה כהלכה. זוהי דוגמה ל: (עיבוד מלמטה-למעלה / המשכיות טובה / קביעות התפיסה / עיבוד מלמעלה-למטה)","a":"עיבוד מלמעלה-למטה (השלמת מילה חסרה לפי הקשר/ציפייה, לא שמיעה ישירה)","explain":"זוהי בדיוק הדגמת <b>שחזור פונמי</b>: צליל 'או' במילה 'אוהב' <b>נחסם פיזית</b> על-ידי צפירת המשאית - הקלט החושי-הגולמי (מלמטה-למעלה) לא הכיל את הצליל הזה כלל. ובכל זאת, מיכל 'שומעת' ומגיבה כאילו המילה השלמה 'אוהב' הגיעה אליה בבירור - כי המוח שלה השתמש ב<b>הקשר המשפטי</b> (עיבוד מלמעלה-למטה, מונע מציפיות/ידע-קודם) כדי 'למלא' את הפער החסר. זו בדיוק הדגמה למקרה שבו עיבוד-מלמעלה-למטה 'מנצח' ומשלים את מה שהחישה-הגולמית לא סיפקה בפועל.","mnemo":"📻 רעש-מכסה-מילה, ההקשר משלים אותה = מלמעלה-למטה."},{"id":"quiz4_24","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"לאחר שראה סרט אימה, יוסי ממשיך לראות מפלצות בכל צל. קרוב לוודאי שהוא חווה: (תופעת פי / קביעות צורה / מערך תפיסה / עקרון הדמיון)","a":"מערך תפיסה (מערך תפיסתי) (ציפייה שעוצבה מחוויה קודמת, משפיעה על התפיסה הנוכחית)","explain":"<b>מערך תפיסתי (perceptual set)</b> - מצב-מוכנות שנוצר על-סמך חוויה קודמת (סרט-אימה), ומשפיע על איך יוסי מפרש גירויים דו-משמעיים לאחר-מכן (צללים סתמיים בחדר). מכיוון שהמוח שלו כרגע 'מכוון' (בעקבות הצפייה בסרט המפחיד) לצפות למראות מאיימים, הוא נוטה לפרש צלליות רגילות ותמימות כ'מפלצות' - זהו בדיוק עיבוד-מלמעלה-למטה בפעולה: הציפייה (שנוצרה מהחוויה האחרונה) מעצבת את הפרשנות של גירוי חזותי-מעורפל, שבמצב-רוח אחר היה מתפרש בניטרליות גמורה.","mnemo":"👻 אחרי סרט-אימה, כל צל=מפלצת = מערך תפיסתי (ציפייה שנשארה \"דלוקה\")."},{"id":"prof5_01","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי למידה?","a":"תהליך שתוצאתו שינוי קבוע יחסית בהתנהגות או בפוטנציאל להתנהגות, המבוסס על התנסות.","explain":"ההגדרה הרשמית מכילה <b>שלושה מרכיבים</b> שכולם חייבים להתקיים גם-יחד כדי שנקרא למשהו 'למידה': <b>שינוי</b> - חייב להיות שינוי אמיתי (לא בהכרח בהתנהגות-בפועל, אלא לפחות ב<b>פוטנציאל</b> להתנהגות - למשל, ידע שנרכש אך עדיין לא הופגן). <b>יחסית-קבוע</b> - השינוי צריך להימשך זמן-מה, לא להיות זמני-לחלוטין (זה מבדיל למידה מעייפות זמנית או שינוי-מצב-רוח חולף). <b>מבוסס-התנסות</b> - השינוי חייב לנבוע מ<b>חוויה/תרגול</b>, לא ממקור אחר. ⚠️ הבחנה קריטית: שינוי בהתנהגות שנובע מ<b>בשלות ביולוגית</b> (למשל, תינוק שמתחיל ללכת בגיל מסוים) או מ<b>השפעה פיזיולוגית ישירה</b> (עייפות, סמים, פציעה) <b>אינו</b> למידה - כי הוא לא מבוסס על התנסות/תרגול, אלא על תהליכים פנימיים שהיו קורים בכל מקרה.","mnemo":"🔧 למידה = שדרוג-קבוע במכשיר (לא זמני), שנוצר מהתנסות - לא סתם קרה, נבנה."},{"id":"prof5_reflection1","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"3 מצבים - האם כל אחד משקף למידה (יסמין/שוקולד, צ'לו, תה מרגיע)?","a":"יסמין=כן (התניה קלאסית: ריח+שמחה, עקבי, מבוסס התנסות). צ'לו=כן (שינוי בפוטנציאל, מתרגול, עקבי). תה=לא (השפעה פיזיולוגית ישירה של החומר, לא רכישת קשר/מיומנות).","explain":"שאלה זו בודקת יישום מדויק של שלושת-מרכיבי-ההגדרה (שינוי, יחסית-קבוע, מבוסס-התנסות) על תרחישים אמיתיים - חשוב לבדוק כל מרכיב בנפרד ולא רק 'להרגיש' אינטואיטיבית: <b>יסמין/שוקולד</b> - כן למידה: יש שינוי (ריח מעורר כעת שמחה), הוא יחסית-קבוע (נמשך לאורך זמן), והוא מבוסס-התנסות (נוצר מזיווג חוזר בין הריח לחוויה המשמחת) - זו בדיוק התניה-קלאסית. <b>צ'לו</b> - כן למידה: שינוי בפוטנציאל-הביצוע (יכולת חדשה שלא הייתה קודם), נובע מתרגול חוזר, ונשאר יציב לאורך זמן. <b>תה מרגיע</b> - <b>לא</b> למידה: התחושה-המרגיעה נובעת מ<b>השפעה פיזיולוגית ישירה</b> של רכיבים כימיים בתה (למשל צמחי-מרפא) על מערכת-העצבים - לא מרכישת קשר/מיומנות דרך התנסות. ⚠️ הטריק: גם אם יש 'שינוי' במצב-הרוח, אם המקור הוא כימי-ישיר ולא תהליך-למידה, זה לא נכנס להגדרה.","mnemo":"🌸🍫 יסמין+שוקולד=כן (קשר נלמד). 🎻 צ'לו=כן (תרגול). ☕ תה-מרגיע=לא (זו כימיה ישירה של החומר, לא למידה)."},{"id":"prof5_02","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי התרגלות? הציגו דוגמה וכיצד באים לידי ביטוי בה 3 מרכיבי הגדרת הלמידה.","a":"ירידה בתגובה לגירוי חוזר. דוגמה: הפסקת התגובה לקול רכבת סמוכה לבית לאחר זמן. שינוי=הפסקת התגובה. התנסות=חשיפה חוזרת. עקביות=נמשך לאורך זמן.","explain":"<b>התרגלות (habituation)</b> היא צורת-הלמידה הפשוטה ביותר שנלמדת בפרק: ירידה הדרגתית בעוצמת-התגובה לגירוי <b>שחוזר ונשנה</b> - לא בגלל עייפות-פיזיולוגית של הקולטנים (זה יהיה 'הסתגלות חושית' מפרק 4), אלא בגלל שהמוח 'לומד' שהגירוי הזה <b>לא-רלוונטי</b> ולא דורש תגובה נוספת. הדוגמה: אדם שעבר לגור ליד פסי-רכבת מגיב בהתחלה לכל רעש-רכבת, אך אחרי זמן-מה מפסיק לשים-לב לרעש כלל. <b>יישום שלושת-מרכיבי-ההגדרה</b>: <b>שינוי</b> = הפסקת-התגובה (שהייתה קודם קיימת). <b>התנסות</b> = חשיפה חוזרת ונשנית לגירוי (לא תהליך-בשלות פנימי). <b>עקביות</b> = ההפסקה נמשכת לאורך זמן, לא רק לרגע. ⚠️ שימו לב שהתרגלות שונה מ'הכחדה' (שנלמד בהתניה-קלאסית) - כאן אין כלל תהליך-התניה קודם, זו פשוט ירידה טבעית בתגובתיות לגירוי חוזר.","mnemo":"🚂 רכבת ליד הבית - בהתחלה מקפיץ אותך, אחרי שבוע כבר לא שם לב = התרגלות."},{"id":"prof5_03","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי אינטרוספקציה?","a":"דיווח מילולי של אדם על תחושות, דימויים ורגשות פנימיים שלו. ווטסון דחה שיטה זו כסובייקטיבית מדי למחקר מדעי.","explain":"<b>אינטרוספקציה</b> - שיטת-המחקר שכבר נלמדה בפרק 1 בהקשר של הסטרוקטורליזם (וונדט, טיצ'נר) - היא דיווח מילולי של אדם על תחושותיו, דימוייו ורגשותיו הפנימיים, כפי שהוא-עצמו חווה אותם. <b>ווטסון</b>, מייסד הגישה הביהביוריסטית, <b>דחה</b> את השיטה הזו לחלוטין כבסיס למחקר-מדעי - הטענה המרכזית שלו: אי-אפשר לאמת/להפריך דיווח-פנימי-סובייקטיבי באופן אובייקטיבי, כי שני אנשים יכולים לדווח אחרת על אותה חוויה בדיוק, בלי דרך-חיצונית לבדוק מי 'צודק' יותר. ⚠️ זו נקודת-המפנה ההיסטורית שהובילה להיווסדות הביהביוריזם: ווטסון טען שפסיכולוגיה-מדעית-אמתית צריכה להתמקד <b>אך ורק</b> בהתנהגות נצפית-מבחוץ, לא בדיווחים-פנימיים שאי-אפשר לאמת.","mnemo":"🗣️💭 אינטרוספקציה = מיקרופון פנימי - מדווח במילים על מה שקורה בפנים הראש."},{"id":"prof5_04","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"איזה סוג מדדים (מפרק 2) נשען על אינטרוספקציה?","a":"מדדי דיווח־עצמי - דורשים מהאדם לדווח במילים על חוויותיו הפנימיות, כמו באינטרוספקציה.","explain":"החיבור בין הפרקים חשוב להבנת-הרצף בקורס: <b>מדדי דיווח-עצמי</b> (שנלמדו בפרק 2, שיטות-המחקר) - שאלונים, ריאיונות, כל כלי שבו הנבדק מדווח <b>במילים</b> על חוויותיו/מחשבותיו/תחושותיו הפנימיות - נשען <b>בדיוק</b> על אותו עיקרון של אינטרוספקציה: הנבדק 'מביט פנימה' ומדווח מה שהוא מוצא שם. ⚠️ החולשה המשותפת: בדיוק כמו האינטרוספקציה שווטסון דחה, מדדי-דיווח-עצמי חשופים לבעיות של סובייקטיביות, רצייה-חברתית, וחוסר-יכולת-לאימות-חיצוני - וזו הסיבה שהביהביוריסטים (בשאלה הבאה) העדיפו סוג-מדד אחר לגמרי.","mnemo":"🎙️ המיקרופון-הפנימי (אינטרוספקציה) = בדיוק מה שדיווח-עצמי עושה."},{"id":"prof5_05","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"איזה סוג מדדים תואם את הגישה הביהביוריסטית (סקינר, ווטסון)?","a":"מדדי התנהגות - מתמקדים רק בהתנהגות ניתנת לצפייה גלויה, בהתאם לדחיית האינטרוספקציה על ידי הביהביוריסטים.","explain":"<b>מדדי התנהגות</b> (behavioral measures, שגם הם נלמדו בפרק 2) - תצפית ישירה, ניתוח-מקרה, נתונים-ארכיוניים - מתאימים בדיוק לפילוסופיה הביהביוריסטית של סקינר וווטסון: הם מודדים <b>רק את מה שנצפה מבחוץ</b> - פעולות גלויות, ניתנות-לתיעוד ולאימות אובייקטיבי על-ידי כל צופה, ללא הסתמכות על דיווח-סובייקטיבי-פנימי. ⚠️ ההיגיון מלא: אם הביהביוריסטים דחו אינטרוספקציה (ולכן דחו גם דיווח-עצמי, שנשען על אותו עיקרון) כבלתי-מדעית, ברור שהכלי-המתאים היחיד עבורם הוא מדד שמודד <b>רק תנועה/פעולה נצפית</b> - זו בדיוק ההגדרה של מדדי-התנהגות.","mnemo":"📹 ביהביוריזם = מצלמת-אבטחה - רואה רק מה שקורה בחוץ (התנהגות), לא מה שבפנים."},{"id":"prof5_06","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע פסיכולוגים ביהביוריסטים עורכים מחקרים רבים בבעלי חיים?","a":"מחפשים סדירויות אוניברסליות בלמידה, החלות על כל המינים (כולל האדם) במצבים בני השוואה. מחקר בבעלי חיים מאפשר בקרה מעבדתית קפדנית ומכליל לבני אדם.","explain":"הביהביוריסטים חקרו בעלי-חיים בהיקף עצום, לא רק מנוחות-מעשית, אלא מתוך <b>הנחה תיאורטית מרכזית</b>: הם חיפשו <b>סדירויות אוניברסליות בלמידה</b> - חוקים-כלליים החלים על <b>כל המינים</b> (כלבים, יונים, חולדות, ובני-אדם) באופן דומה במצבים-ניתנים-להשוואה. אם עקרונות-הלמידה (התניה קלאסית/אופרנטית) הם אכן אוניברסליים ולא ספציפיים-למין, אז מחקר על חולדה יכול לחשוף <b>עיקרון בסיסי</b> שיחול גם על אדם. <b>היתרון המעשי הנוסף</b>: מחקר בבעלי-חיים מאפשר <b>בקרה מעבדתית קפדנית הרבה יותר</b> (שליטה מלאה בהיסטוריית-החיזוקים, בסביבה, בתזמון) שקשה או בלתי-אתי להשיג בבני-אדם - ומכיוון שהנחת-היסוד היא אוניברסליות, התוצאות נחשבו ניתנות-להכללה גם לבני-אדם.","mnemo":"🐭=🧑 חוקרים מניחים שחוק-הלמידה זהה לחולדה ולאדם - לכן בודקים על חולדה (קל/זול/מבוקר) ומכלילים לאדם."},{"id":"prof5_07","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"איזו התנהגות בלתי צפויה זיהה פבלוב בכלבים?","a":"הכלבים הפרישו רוק לפני קבלת אבקת הבשר בפועל - כבר למראה המזון, למראה העוזר, או למשמע קול צעדיו.","explain":"<b>פבלוב</b> לא התכוון כלל לחקור למידה כשגילה את התופעה - הוא היה פיזיולוג שחקר עיכול, ומדד את הפרשת-הרוק של כלבים כתגובה למזון. ההתנהגות הבלתי-צפויה שהוא זיהה (ושהפכה בסופו של דבר לתגלית המכוננת שלו): הכלבים הפרישו רוק <b>עוד לפני</b> שהמזון בפועל הגיע לפיהם - כבר <b>למראה</b> המנה, <b>למראה</b> העוזר-המטפל-בהם, או אפילו רק <b>למשמע קול-צעדיו</b> מתקרב. ⚠️ זו הייתה תופעה 'לא-הגיונית' לפי הבנת-העיכול הפשוטה (למה שהגוף 'יודע מראש' לפני שהאוכל נמצא כלל בפה?) - וההבנה שהכלבים <b>למדו</b> קישור בין אירועים-שקדמו-למזון לבין המזון עצמו היא הגרעין המושגי שהוביל לתיאוריית ההתניה-הקלאסית כולה.","mnemo":"🐕💧 כלבי-פבלוב מריירים לצעדים של העוזר, עוד לפני שראו אוכל בכלל - תגלית מקרית ומפתיעה."},{"id":"prof5_08","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי התניה קלאסית? כללו: אסוציאציה, גירוי ניטראלי, גירוי בלתי־מותנה, גירוי מותנה, תגובה בלתי־מותנית, תגובה מותנית.","a":"צורת למידה שבה גירוי ניטראלי מזווג עם גירוי בלתי־מותנה (המעורר תגובה בלתי־מותנית), עד שנוצר ביניהם קישור/אסוציאציה. הגירוי הניטראלי הופך לגירוי מותנה, המעורר תגובה מותנית דומה.","explain":"<b>התניה קלאסית</b> היא תהליך-למידה שבו <b>גירוי ניטרלי</b> (לא מעורר תגובה בהתחלה) מזווג <b>שוב ושוב</b> עם <b>גירוי בלתי-מותנה</b> (UCS - מעורר תגובה אוטומטית-טבעית, ה<b>תגובה הבלתי-מותנית</b>, ללא כל למידה נדרשת) - עד שנוצר <b>אסוציאציה/קישור</b> ביניהם במוח. כתוצאה, הגירוי-שהיה-ניטרלי הופך ל<b>גירוי מותנה</b> (CS) - כלומר, הוא-עצמו, לבדו, מתחיל לעורר תגובה דומה, הנקראת <b>תגובה מותנית</b> (CR - כי היא 'תלויה' בתהליך-הלמידה שקרה). ⚠️ נקודה מרכזית להבנה: התגובה-הבלתי-מותנית והתגובה-המותנית לרוב <b>נראות דומות</b> מבחינה גלויה (למשל, ריור בשני המקרים), אך הן <b>לא זהות מבחינה תיאורטית</b> - האחת מולדת ואוטומטית, השנייה נלמדה מהתהליך כולו.","mnemo":"🔔➡️🍖 גירוי-ניטרלי (פעמון) + גירוי-בלתי-מותנה (בשר) = ריור (בלתי-מותנה). אחרי חזרות: פעמון-לבד=ריור (עכשיו מותנה)."},{"id":"prof5_09","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"זהו את מרכיבי ההתניה הקלאסית בסיפור אלכסנדרה (יסמין/שוקולד).","a":"גירוי ניטראלי/מותנה=ניחוח יסמין. גירוי בלתי־מותנה=שוקולד/ביקור סבתא. תגובה בלתי־מותנית=שמחה. אחרי ההתניה: ניחוח יסמין לבדו מעורר תגובה מותנית=שמחה.","explain":"יישום ישיר של מרכיבי-ההתניה-הקלאסית על תרחיש קונקרטי - חשוב לזהות כל רכיב לפי <b>תפקידו בתהליך</b>, לא רק לפי 'התחושה' שלו: <b>גירוי ניטרלי/מותנה</b> = ניחוח היסמין (בהתחלה סתם ריח, ללא משמעות רגשית - ולאחר-הלמידה, הופך למעורר-שמחה בעצמו). <b>גירוי בלתי-מותנה</b> = השוקולד/ביקור-הסבתא (מעורר שמחה <b>באופן טבעי ואוטומטי</b>, ללא כל צורך בלמידה מוקדמת). <b>תגובה בלתי-מותנית</b> = השמחה שמעורר השוקולד/הביקור עצמם, <b>לפני</b> תהליך-ההתניה. <b>אחרי</b> ההתניה: ניחוח היסמין <b>לבדו</b> (בלי השוקולד/הסבתא נוכחים) מעורר שמחה - וזו כעת <b>תגובה מותנית</b>, כי היא נלמדה מהזיווג החוזר בין הריח לחוויה המשמחת.","mnemo":"🌸🍫 סיפור אלכסנדרה: יסמין=הפעמון (יהפוך למותנה). שוקולד/סבתא=הבשר (הבלתי-מותנה). שמחה=הריור (התגובה)."},{"id":"prof5_10","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מה ההבדל בין תגובה מותנית לתגובה בלתי־מותנית?","a":"תגובה בלתי־מותנית=אוטומטית, טבעית, ללא למידה. תגובה מותנית=נלמדת, מתעוררת רק לאחר תהליך התניה (זיווג) - אף שהתגובות דומות באופיין הנצפה.","explain":"ההבדל בין שני סוגי-התגובה הוא בדיוק <b>מקור-התגובה</b>, לא סוג-התגובה עצמה: <b>תגובה בלתי-מותנית</b> - אוטומטית וטבעית, קיימת <b>ללא כל למידה</b> - הגוף 'מתוכנת' מראש להגיב כך (למשל, ריור אוטומטי למראה מזון). <b>תגובה מותנית</b> - נלמדת, ומתעוררת <b>רק לאחר</b> תהליך-התניה (זיווג חוזר) בין גירוי-ניטרלי לגירוי-בלתי-מותנה - היא לא הייתה קיימת קודם, ונרכשה דרך התנסות. ⚠️ הנקודה המבלבלת ביותר לתלמידים: <b>שתי התגובות יכולות להיראות זהות-לחלוטין</b> מבחינה גלויה-נצפית (למשל, כלב מריר בשני המקרים) - ההבדל הוא <b>רק</b> בשאלה מה גרם לה: גירוי טבעי (בלתי-מותנה) או גירוי-שנלמד (מותנה). זה מדגיש שהתגובה-בפועל לא 'מגלה' לנו לבד אם היא נלמדה או לא - צריך לדעת את ההיסטוריה.","mnemo":"🎁 בלתי-מותנה = מתנה-חינם (מגיע אוטומטית, בלי ללמוד). מותנה = צריך \"לעבוד\" בשביל זה (נלמד בהתניה)."},{"id":"prof5_11","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"בניסוי היפותטי על צליל ומזון, זהו את השלב (רכישה/הכחדה/החלמה ספונטנית) בכל תרחיש: (א) פעמון חדש, צליל נמשך עם הגשת מזון. (ב) צליל בלבד ללא מזון. (ג) מזון בלבד ללא צליל. (ד) שבוע לאחר מכן, צליל בלבד, ריור מועט.","a":"(א) רכישה - זיווג CS+UCS (התניה מושהית). (ב) הכחדה - CS בלבד, ללא UCS. (ג) לא שייך לשלבים - אין CS נוכח כלל, זו תגובה בלתי־מותנית טבעית למזון בלבד. (ד) החלמה ספונטנית - CS לבדו לאחר מנוחה, תגובה מוחלשת.","explain":"תרגיל זה בודק זיהוי מדויק של שלבי-ההתניה-הקלאסית (רכישה/הכחדה/החלמה-ספונטנית) מתוך תיאור-תרחיש, לפי <b>מה שבפועל קורה</b> בכל שלב: <b>(א) רכישה</b> - הפעמון (CS) והמזון (UCS) מוצגים <b>יחד</b>, שוב ושוב - זה בדיוק תהליך-בניית-הקישור, המכונה רכישה. <b>(ב) הכחדה</b> - הצליל (CS) מוצג <b>לבדו, ללא</b> המזון - זה בדיוק תנאי-ההכחדה: הצגת-הגירוי-המותנה חוזרת ונשנית ללא הגירוי-הבלתי-מותנה, מה שגורם לתגובה-המותנית להיחלש בהדרגה. <b>(ג) לא שייך לשלבים כלל</b> - כשמזון מוצג <b>לבדו, ללא</b> הצליל, פשוט מתקבלת תגובה-בלתי-מותנית טבעית (ריור למראה מזון) - זה לא קשור לתהליך-ההתניה-המותנית כלל. <b>(ד) החלמה ספונטנית</b> - לאחר תקופת-מנוחה (שבוע), הצליל <b>לבדו</b> עדיין מעורר תגובה חלשה - למרות ההכחדה, הקישור לא נמחק לגמרי, רק 'נרדם' זמנית.","mnemo":"🔔🍖 (א)פעמון+בשר-ביחד=רכישה (בונים). (ב)פעמון-לבד=הכחדה (מפרקים). (ג)בשר-לבד=לא-רלוונטי (אין פעמון בסיפור). (ד)אחרי-מנוחה,פעמון-חלש=החלמה-ספונטנית (חוזר לבקר)."},{"id":"prof5_12","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי הכללה? הציגו דוגמה.","a":"הרחבה אוטומטית של תגובה מותנית לגירויים הדומים לגירוי המותנה המקורי, גם אם מעולם לא זווגו עם הגירוי הבלתי־מותנה. דוגמה: ילד שננשך על ידי כלב גדול מפחד גם מכלבים קטנים אחרים.","explain":"<b>הכללה (generalization)</b> היא הרחבה <b>אוטומטית ולא-מכוונת</b> של תגובה-מותנית לגירויים ה<b>דומים</b> לגירוי-המותנה-המקורי - גם אם הגירויים-הדומים-האלה <b>מעולם לא</b> זווגו בעצמם עם הגירוי-הבלתי-מותנה. הדוגמה: ילד שננשך על-ידי כלב <b>גדול</b> ספציפי מפתח פחד-מותנה מאותו כלב - אך הפחד 'מכליל' וחל גם על כלבים-קטנים-אחרים, שהילד מעולם לא נפגש איתם, רק בגלל שהם דומים דיו (בגודל/מראה כללי) לכלב-המקורי-שגרם-לפחד. ⚠️ הרעיון האבולוציוני מאחורי הכללה: היא מנגנון-הישרדותי מועיל - אם משהו ספציפי הוכח כמסוכן, זהיר לחשוד גם בדברים-דומים-לו, ולא רק בדיוק באותו הפרט. בשאלה הבאה נלמד את התהליך המנוגד - הבחנה.","mnemo":"🐕➡️🐕‍🦺 ננשך מכלב-גדול, מפחד גם מכלב-קטן = הפחד \"נשפך\" גם על דומים = הכללה."},{"id":"prof5_13","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי הבחנה? הציגו דוגמה.","a":"תהליך שבו האורגניזם לומד להגיב באופן שונה לגירויים דומים לגירוי המותנה, כשרק אחד מהם מנבא את הגירוי הבלתי־מותנה. דוגמה: הבחנה בין צלילים בעצמות שונות, כשרק אחד מנבא מזון.","explain":"<b>הבחנה (discrimination)</b> היא ההפך המדויק מהכללה: תהליך-למידה שבו האורגניזם לומד <b>להגיב באופן שונה</b> לגירויים-דומים-לגירוי-המותנה, כשרק <b>אחד</b> מהם באמת מנבא את הגירוי-הבלתי-מותנה. הדוגמה: כלב יכול ללמוד להבחין בין שני צלילים דומים (עוצמות/עצמות שונות במקצת) אם רק אחד מהם באופן-עקבי מנבא הגשת-מזון, בעוד השני לעולם לא מלווה במזון - כך הכלב לומד להגיב (ריור) רק לצליל-המנבא, ולא לצליל-הדומה-אך-הלא-רלוונטי. ⚠️ ההבדל מהכללה: הכללה מתרחשת <b>אוטומטית</b> (בלי אימון מיוחד) כברירת-מחדל, בעוד הבחנה דורשת <b>אימון ספציפי</b> - זיווג עקבי רק עם גירוי אחד, ואי-זיווג עם הגירוי-הדומה - זה בדיוק מה שנלמד בשאלה הבאה על אימון-כלבים למשרוקית ספציפית.","mnemo":"🎯 רק-הצליל-הנכון מנבא מזון, לא הדומים לו = הבחנה (מדייקים, לא משפכים על כולם)."},{"id":"prof5_14","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מאלף רוצה שכלב יגיב רק למשרוקית שלו, לא למשרוקיות דומות. מה עליו לעשות? (הכללה/הבחנה/התניה)","a":"לאמן בהבחנה - לזווג רק את המשרוקית המיוחדת עם הגירוי הבלתי־מותנה, ולהציג משרוקיות דומות אחרות בלעדיו, כדי שהתגובה לא תוכלל אליהן.","explain":"כדי לגרום לכלב להגיב <b>אך-ורק</b> למשרוקית הספציפית שלו, ולא למשרוקיות-דומות-אחרות, יש לאמן אותו ב<b>הבחנה</b>, לא לתת לו 'ללמוד לבד' - כי הכללה תהיה ברירת-המחדל הטבעית ללא-התערבות. תהליך-האימון הנדרש: המאמן חייב לזווג <b>אך ורק</b> את המשרוקית-המיוחדת (הקבועה) שלו עם הגירוי-הבלתי-מותנה (למשל, פינוק/פקודה שתמיד מקבלים תגובה) - ובמקביל, להציג משרוקיות-דומות-אחרות <b>ללא</b> הזיווג הזה (בלי פינוק אחריהן). לאורך זמן, הכלב ילמד <b>להבחין</b> - להגיב רק למשרוקית-שמנבאת באמת את התוצאה, ולא להכליל את התגובה למשרוקיות-דומות-לה-שלא-מנבאות-כלום.","mnemo":"🎯 שוב הדיוק (הבחנה, לא הכללה) - לזווג רק את המשרוקית המיוחדת עם התגמול."},{"id":"prof5_15","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תארו את ניסוי רסקורלה. במה הוא שונה מניסוי פבלוב? מסקנות?","a":"כלבים+צליל+הלם חשמלי. קבוצת 'מקרית' (הלם אקראי, לא תלוי בצליל) מול קבוצת 'ניבוי' (צליל תמיד מנבא הלם) - קבוצת הניבוי פיתחה פחד מותנה חזק יותר. שונה מפבלוב: לא מספיקה סמיכות זמנים - נדרש שהגירוי המותנה ינבא באופן מהימן את הבלתי־מותנה.","explain":"ניסוי <b>רסקורלה</b> הוסיף שכבת-תחכום קריטית לתיאוריית-ההתניה-הפשוטה של פבלוב: כלבים חולקו לשתי קבוצות שקיבלו <b>אותה כמות בדיוק</b> של צליל והלם-חשמלי - ההבדל היחיד היה <b>הקשר ביניהם</b>. בקבוצת-'מקרית', ההלם הגיע <b>אקראית</b>, בלי קשר לצליל (לפעמים אחרי צליל, לפעמים לא). בקבוצת-'ניבוי', <b>הצליל תמיד</b> הופיע ממש לפני ההלם - הצליל 'ניבא' באופן-מהימן את בוא-ההלם. <b>התוצאה</b>: רק קבוצת-הניבוי פיתחה פחד-מותנה חזק לצליל - קבוצת-המקרית, למרות שחוו <b>אותה כמות-חשיפה בדיוק</b> לשני הגירויים, כמעט לא פיתחו פחד כלל. <b>המסקנה המהפכנית</b>: <b>סמיכות-זמנים בלבד לא מספיקה</b> ליצירת התניה (כפי שפבלוב הניח) - נדרש שהגירוי-המותנה <b>יספק מידע אמין וממשי</b> על בוא-הגירוי-הבלתי-מותנה, לא סתם להיות קרוב-בזמן אליו.","mnemo":"🎲 מקרי (בלי-קשר-בין-צליל-להלם) = לא-לומדים-לפחד. 🔮 ניבוי (צליל-תמיד-לפני-הלם) = לומדים-לפחד. הסמיכות-בזמן לא מספיקה, צריך ניבוי אמיתי."},{"id":"prof5_16","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תארו את ניסוי קמין (חסימה). מה אפשר ללמוד ממנו, ובמה שונה מרסקורלה?","a":"חולדות למדו צליל→הלם, ואז נוסף אור יחד עם הצליל; האור לבדו לא נלמד כלל (חסימה). תנאי: הגירוי המותנה חייב להיות אינפורמטיבי (מידע חדש), לא רק מנבא. שונה מרסקורלה: לא מספיק שגירוי ינבא - הוא גם לא יילמד אם גירוי אחר כבר תפס את אותו המידע הניבויי.","explain":"ניסוי <b>קמין</b> (תופעת החסימה - blocking) מוסיף תנאי-הכרחי נוסף מעבר לניבוי-מהימן שגילה רסקורלה: חולדות למדו תחילה קישור <b>צליל→הלם</b> (התניה-רגילה, שהצליל מנבא הלם באופן-מהימן). לאחר-מכן, החוקרים <b>הוסיפו אור</b> שהופיע <b>יחד</b> עם הצליל (כלומר, גם האור עצמו 'מנבא באופן מהימן' את ההלם, בדיוק כמו הצליל). <b>התוצאה המפתיעה</b>: החולדות <b>לא למדו כלל</b> קישור בין האור לבין ההלם - למרות שהאור עמד באותם תנאי-ניבוי-מהימן שהצליל עמד בהם! <b>ההסבר</b>: מכיוון שהצליל <b>כבר 'תפס' את כל המידע הניבויי הרלוונטי</b> (החולדות כבר ידעו שהצליל=הלם-בקרוב), האור לא הביא <b>שום מידע חדש</b> - הוא היה 'מיותר', ולכן 'נחסם' מלהילמד. <b>ההבדל מרסקורלה</b>: רסקורלה הראה שניבוי-מהימן <b>הכרחי</b>; קמין הראה שניבוי-מהימן <b>לא-מספיק</b> - הגירוי צריך גם להיות <b>אינפורמטיבי</b> (להוסיף מידע חדש שעדיין לא ידוע), לא רק לנבא-נכון בפני עצמו.","mnemo":"🥇🥈 צליל=כבר-תפס-את-כל-המידע (מדליית-זהב). אור-חדש=לא-מקבל-כלום (מדליית-כסף-מיותרת) - זו חסימה."},{"id":"prof5_17","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו, בעזרת התניה קלאסית, מדוע אנשים אינם מוכנים לאכול ממתק שוקולד בצורת צואת כלבים.","a":"תגובת גועל היא תגובה קלאסית מותנה (לצורה/למראה) המכריעה את הכף על פני הידיעה הרציונלית שאין בעיה בגירוי. תגובות התניה קלאסית אינן נוצרות במודע, ולכן היגיון מודע אינו יכול לבטלן.","explain":"התופעה הזו (סירוב לאכול שוקולד בצורת-צואה, למרות ידיעה רציונלית-ברורה שזה בסך-הכל שוקולד רגיל) ממחישה עיקרון עמוק וחשוב על התניה-קלאסית: <b>תגובת-הגועל</b> שהתפתחה כלפי צורת-צואה (דרך התניה קלאסית מוקדמת בחיים, כמו קישור בין המראה לבין ריח/תוצאה שלילית) פועלת <b>אוטומטית ומיידית</b>, ו<b>מכריעה</b> על-פני הידיעה-הרציונלית-המודעת שאין כאן בעיה אמיתית עם הגירוי (זה רק שוקולד). ⚠️ הסיבה: <b>תגובות התניה-קלאסית לא נוצרות במודע</b> - הן פועלות ברמה אוטומטית, כמעט-רפלקסיבית, ולכן <b>היגיון מודע (top-down) אינו מסוגל לבטל אותן</b> ישירות - זו הוכחה חזקה לכך שתגובות-מותנות אינן 'בחירה' רציונלית שאפשר פשוט 'להחליט לבטל', אלא תהליך עמוק ואוטומטי יותר.","mnemo":"💩🍫 שוקולד בצורת צואה - הגועל (מותנה קלאסית) מנצח את ההיגיון (\"זה בסך הכל שוקולד\")."},{"id":"prof5_18","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תארו את תהליך ההתניה בניסוי אלברט הקטן (ווטסון וריינר).","a":"חולדה לבנה=גירוי ניטראלי/מותנה. רעש חזק (מוט ברזל)=גירוי בלתי־מותנה. בהלה=תגובה בלתי־מותנית. אחרי 7 זיווגים: החולדה לבדה מעוררת פחד (תגובה מותנית). הפחד הוכלל לעצמים דומים מכוסי פרווה (ארנב, כלב, מסכת סנטה קלאוס).","explain":"ניסוי אלברט-הקטן (ווטסון וריינר, 1920) הוא ההדגמה הקלאסית ביותר של יצירת פחד-מותנה בבן-אדם. יישום מדויק של מרכיבי-ההתניה: <b>חולדה לבנה</b> = גירוי-ניטרלי בהתחלה (אלברט אפילו נהנה ממנה) שהפך ל<b>גירוי-מותנה</b> לאחר-ההתניה. <b>רעש חזק</b> (הכאה על מוט-ברזל מאחורי אלברט) = <b>גירוי-בלתי-מותנה</b>, שמעורר באופן טבעי <b>בהלה</b> = <b>תגובה-בלתי-מותנית</b>. לאחר <b>שבעה זיווגים</b> (הצגת החולדה תמיד ביחד עם הרעש המפחיד) - <b>החולדה לבדה</b>, גם ללא הרעש, הפכה לעורר <b>פחד</b> = כעת <b>תגובה-מותנית</b>. ⚠️ הממצא המרתק הנוסף: הפחד <b>הוכלל</b> (בדיוק כמו שנלמד בהכללה) גם לעצמים-דומים-שמעולם-לא-זווגו-עם-הרעש - כל דבר עם פרווה או מרקם דומה (ארנב, כלב, אפילו מסכת סנטה-קלאוס עם זקן-לבן-פרוותי) עורר אצל אלברט פחד, למרות שרק החולדה עצמה עברה את תהליך-ההתניה במישרין.","mnemo":"🐁🔊😱 אלברט הקטן: חולדה(ניטרלי)+רעש-חזק(בלתי-מותנה)=בהלה. אחרי 7 פעמים: חולדה-לבד=פחד, שהתפשט גם לארנב/כלב/סנטה (הכללה לפרוותיים)."},{"id":"prof5_19","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהן הבעיות האתיות במחקר אלברט הקטן (לפי עקרונות פרק 2)?","a":"מפר Beneficence/Nonmaleficence: אין הסכמה מדעת אפשרית מתינוק; רווח מדעי לא מצדיק את הנזק הרגשי; לא בוצעה שיחת הבהרה כלל (הוצא מהניסוי לפני טיפול בפחד); פחד מותנה עמיד מאוד בפני הכחדה.","explain":"יישום עקרונות-האתיקה (מפרק 2) על מקרה-מבחן היסטורי חשוב: ניסוי אלברט-הקטן מפר את עקרון ה-<b>Beneficence and Nonmaleficence</b> (עשיית-טוב והימנעות-מנזק) במספר נקודות בו-זמנית. <b>הסכמה מדעת</b> - בלתי-אפשרית מתינוק כה צעיר; אמו נתנה הסכמה, אך אלברט-עצמו לא יכול היה להבין למה הוא מוסכם. <b>יחס עלות-תועלת</b> - הרווח המדעי (הבנת מנגנון-ההתניה) לא מצדיק את הנזק-הרגשי-הממשי שנגרם לתינוק. <b>שיחת הבהרה (debriefing)</b> - <b>כלל לא בוצעה</b>: אלברט הוצא מהניסוי (עבר עם אמו) <b>לפני</b> שניתן היה לטפל ולהכחיד את הפחד שנוצר - הותיר אותו עם פוביה לא-מטופלת. ⚠️ נקודה קלינית חשובה שמחזקת את חומרת-ההפרה: פחד-מותנה, כפי שנלמד, <b>עמיד מאוד בפני הכחדה טבעית</b> - כלומר, סביר שהנזק לא נעלם מעצמו, אלא נותר איתו לאורך זמן.","mnemo":"⚠️ 4 בעיות: תינוק-לא-יכול-להסכים, נזק>תועלת, אין-שיחת-הבהרה, הפחד-נשאר-חזק-מדי-להיעלם."},{"id":"prof5_20","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מה סביר שקרה לאלברט אחרי שיצא מהניסוי (בעזרת תרשים 6.3)?","a":"ללא חשיפה חוזרת לחולדה בלי הרעש, אין הזדמנות להכחדה - סביר שהפחד המותנה נשמר. אם כן נחשף מדי פעם ללא הרעש, ייתכנה הכחדה הדרגתית, אך גם החלמה ספונטנית (הישנות הפחד בעוצמה חלשה) בכל מפגש חדש עם עצם דומה.","explain":"שאלה זו מיישמת את הידע על שלבי-ההתניה-הקלאסית (רכישה/הכחדה/החלמה-ספונטנית) על מה שקרה-בפועל לאחר סיום-הניסוי: מכיוון שאלברט הוצא מהמחקר <b>בלי טיפול</b> (כפי שנלמד בשאלה הקודמת), לא ניתנה לו <b>אף הזדמנות להכחדה</b> - הכחדה מחייבת חשיפה חוזרת לגירוי-המותנה (החולדה) <b>ללא</b> הגירוי-הבלתי-מותנה (הרעש), שוב ושוב, כדי שהתגובה-המותנית תיחלש בהדרגה. בלי חשיפה כזו, סביר <b>שהפחד המותנה נשמר</b> כפי שהיה. ⚠️ תרחיש-משנה מעניין: <b>אם</b> אלברט כן נחשף מדי-פעם לגירויים-דומים (חתול, כלב) בלי-הרעש, ייתכן שהתרחשה הכחדה-הדרגתית - אך גם אז, בהתאם לתרשים 6.3, סביר שהייתה מתרחשת <b>החלמה ספונטנית</b> חוזרת (הישנות-הפחד בעוצמה חלשה יותר) בכל מפגש חדש עם עצם-דומה, גם אחרי שנראה כאילו הפחד 'נעלם'.","mnemo":"🐁😨 בלי הכחדה (חשיפה בלי הרעש), הפחד נשאר. אם חושפים בהדרגה - פחד יורד, אך יכול לחזור חלש (החלמה ספונטנית) בכל מפגש חדש."},{"id":"prof5_21","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"בחרו פוביה ותארו כיצד היא יכולה להתפתח בהתניה קלאסית.","a":"דוגמה: פוביה ממעליות. תקיעה במעלית (גירוי בלתי־מותנה)→פחד (תגובה בלתי־מותנית). המעלית עצמה הופכת לגירוי מותנה, מעוררת פחד (תגובה מותנית) גם ללא תקיעה נוספת. הפחד עלול להוכלל לחללים סגורים אחרים.","explain":"שאלה זו מבקשת יישום עצמאי (לא מהספר) של מרכיבי-ההתניה-הקלאסית על פוביה נבחרת - חשוב להראות את <b>כל שלושת השלבים</b>: תחילה, אירוע-טראומטי (למשל, תקיעה במעלית) = <b>גירוי-בלתי-מותנה</b>, שמעורר <b>פחד</b> = <b>תגובה-בלתי-מותנית</b> אוטומטית וטבעית. לאחר-מכן, <b>המעלית-עצמה</b> (שהייתה בהתחלה ניטרלית - סתם אמצעי-תחבורה) הופכת ל<b>גירוי-מותנה</b>, מעוררת <b>פחד</b> = כעת <b>תגובה-מותנית</b>, גם ב<b>היעדר</b> תקיעה-נוספת - סתם עצם-הכניסה למעלית מספיקה. ⚠️ יש להשלים גם את מנגנון-ה<b>הכללה</b>: הפחד עלול להתפשט מ'המעלית-הספציפית-הזו' ל<b>כל</b> חללים-סגורים-דומים (אולי אפילו מעליות אחרות, או חדרים-קטנים-ללא-חלונות) - למרות שמעולם לא נתקעו בהם ממש - זו בדיוק הדינמיקה שראינו בניסוי אלברט-הקטן.","mnemo":"🛗 תקוע-במעלית (בלתי-מותנה)→פחד. אחר-כך: המעלית-לבד(מותנה)→פחד. הפחד יכול \"לדלוף\" גם לחללים סגורים אחרים (הכללה)."},{"id":"prof5_tableau_cl_op","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"התאימו משפטים לממדים הנכונים (טבע הלומד, הקישור הנלמד, הגורם המניע) בהתניה קלאסית ואופרנטית.","a":"קלאסית: טבע הלומד=פסיבי. קישור=זיווג גירוי בלתי־מותנה עם גירוי מותנה בסמיכות. מניע=תחושה מהתגובה הבלתי־מותנית. אופרנטית: מניע=תוצאת התגובה. קישור=תגובה מובילה לתוצאה. טבע הלומד=אקטיבי.","explain":"טבלת-ההשוואה ממחישה את ההבדל התיאורטי-היסודי בין שני סוגי-ההתניה - חשוב לזכור אותה כמסגרת-שלמה, לא רק פרטים בודדים: <b>טבע-הלומד</b> - בהתניה-קלאסית, האורגניזם <b>פסיבי</b> (הגירויים 'קורים לו', והתגובה-הבלתי-מותנית מגיעה אוטומטית); באופרנטית, האורגניזם <b>אקטיבי</b> (הוא-עצמו יוזם את התגובה שגוררת תוצאה). <b>הקישור-הנלמד</b> - בקלאסית, לומדים קישור בין <b>שני גירויים</b> (CS+UCS) שמופיעים בסמיכות; באופרנטית, לומדים קישור בין <b>תגובה לתוצאה שלה</b> (מה שקורה בעקבות מה שאני עושה). <b>הגורם-המניע</b> - בקלאסית, זו התחושה-המולדת שמעוררת התגובה-הבלתי-מותנית; באופרנטית, זו <b>תוצאת-התגובה</b> עצמה (חיזוק/עונש) שקובעת אם התגובה תחזור. ⚠️ הבנה זו קריטית כי כל שאר-הפרק (חיזוקים, עונשים, תכניות) בנוי על ההנחה שהאורגניזם <b>אקטיבי ופועל</b> - זה בדיוק מה שמבדיל בין 'קורה לי' (קלאסית) ל'אני עושה' (אופרנטית).","mnemo":"😴🏃 קלאסית = פסיבי (קורה לך - כלב שרוצה בכל מקרה). אופרנטית = אקטיבי (אתה פועל כדי לקבל תוצאה)."},{"id":"prof5_22","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו חיזוק חיובי ומהו חיזוק שלילי?","a":"חיזוק חיובי=הוספת גירוי נעים אחרי התגובה (מעלה הסתברות). חיזוק שלילי=הסרת גירוי לא־נעים אחרי התגובה (גם מעלה הסתברות). שניהם מגבירים את התגובה - ההבדל הוא הוספה מול הסרה.","explain":"<b>חיזוק</b> (בשני סוגיו) תמיד <b>מעלה</b> את הסתברות-החזרה של ההתנהגות - זה מה שמאחד את שני המושגים, למרות שנשמעים הפוכים. ההבדל הוא רק <b>הוספה מול הסרה</b>: <b>חיזוק חיובי</b> - <b>הוספת</b> גירוי-נעים אחרי התגובה (למשל, שבח/כסף/פינוק) - התגובה מתגברת כי משהו-טוב 'נוסף'. <b>חיזוק שלילי</b> - <b>הסרת</b> גירוי-לא-נעים אחרי התגובה (למשל, כאב, רעש מציק) - התגובה מתגברת כי משהו-רע 'הוסר'. ⚠️ טעות נפוצה מאוד: לבלבל 'חיזוק שלילי' עם 'עונש' - <b>חיזוק שלילי אינו עונש כלל</b>! חיזוק שלילי <b>מגביר</b> התנהגות (בדיוק כמו חיזוק חיובי), רק שהמנגנון הוא הסרת-משהו-רע ולא הוספת-משהו-טוב. הדוגמה הקלאסית: לוקחים אספירין (התנהגות) כדי <b>להסיר</b> כאב-ראש (גירוי-לא-נעים) - וזה מחזק/מגביר את הנטייה לקחת אספירין בעתיד.","mnemo":"➕😊➖😖 חיזוק חיובי=מוסיפים-נעים (ממתק). חיזוק שלילי=מסירים-לא-נעים (מכבים אזעקה). שניהם מגבירים!"},{"id":"prof5_23","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו עונש חיובי ומהו עונש שלילי?","a":"עונש חיובי=הוספת גירוי לא־נעים אחרי התגובה (מקטין הסתברות). עונש שלילי=הסרת גירוי נעים אחרי התגובה (גם מקטין הסתברות). שניהם מפחיתים את התגובה.","explain":"בדיוק כמו בחיזוק, <b>עונש</b> (בשני סוגיו) תמיד <b>מפחית</b> את הסתברות-החזרה של ההתנהגות - ההבדל בין שני הסוגים הוא, שוב, <b>הוספה מול הסרה</b>: <b>עונש חיובי</b> - <b>הוספת</b> גירוי-לא-נעים אחרי התגובה (למשל, נזיפה, קנס) - ההתנהגות פוחתת כי משהו-רע 'נוסף' כתגובה אליה. <b>עונש שלילי</b> - <b>הסרת</b> גירוי-נעים אחרי התגובה (למשל, לקיחת-צעצוע, ביטול-הרשאה) - ההתנהגות פוחתת כי משהו-טוב 'הוסר' כעונש. ⚠️ המילים 'חיובי/שלילי' בכל ארבעת המושגים (חיזוק/עונש × חיובי/שלילי) <b>לעולם לא</b> מתייחסות ל'טוב/רע' מבחינה מוסרית - הן מתייחסות אך-ורק למתמטיקה של <b>הוספה (+) מול הסרה (-)</b>. זה הטריק החשוב ביותר לזכירה בכל הפרק.","mnemo":"➕😖➖😊 עונש חיובי=מוסיפים-לא-נעים (מכה). עונש שלילי=מסירים-נעים (לוקחים טאבלט). שניהם מפחיתים!"},{"id":"prof5_24","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מלאו את טבלה 2: ארבעת סוגי התוצאות (חיזוק/עונש × חיובי/שלילי).","a":"הגברת הסתברות+הוספה=חיזוק חיובי. הגברת הסתברות+הסרה=חיזוק שלילי. הקטנת הסתברות+הוספה=עונש חיובי. הקטנת הסתברות+הסרה=עונש שלילי.","explain":"טבלה זו ממזגת את שני הצירים שנלמדו בשתי השאלות הקודמות לכדי מבנה-שלם אחד, שממנו נגזרים <b>כל</b> ארבעת המושגים: הציר הראשון - <b>מה קורה להסתברות-ההתנהגות</b> (עולה=חיזוק / יורדת=עונש); הציר השני - <b>מה עושים לגירוי</b> (מוסיפים=חיובי / מסירים=שלילי). כשמצליבים: <b>הגברת-הסתברות + הוספה = חיזוק חיובי</b> (מוסיפים משהו טוב, ההתנהגות עולה). <b>הגברת-הסתברות + הסרה = חיזוק שלילי</b> (מסירים משהו רע, ההתנהגות עולה). <b>הקטנת-הסתברות + הוספה = עונש חיובי</b> (מוסיפים משהו רע, ההתנהגות יורדת). <b>הקטנת-הסתברות + הסרה = עונש שלילי</b> (מסירים משהו טוב, ההתנהגות יורדת). ⚠️ שיטת-זכירה מהירה: 'חיובי/שלילי' = הוספה/הסרה בלבד; 'חיזוק/עונש' = עולה/יורדת בלבד - שני צירים בלתי-תלויים לגמרי.","mnemo":"📊 טבלה: עולה+הוספה=חיזוק-חיובי. עולה+הסרה=חיזוק-שלילי. יורד+הוספה=עונש-חיובי. יורד+הסרה=עונש-שלילי."},{"id":"prof5_reflection3","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הציעו לשלמה 4 תכניות נקודות לדיאטה: חיזוק חיובי, חיזוק שלילי, עונש חיובי, עונש שלילי.","a":"חיזוק חיובי (אכילת תפוחים): הוספת נקודה על כל תפוח. חיזוק שלילי (אכילת תפוחים): הסרת חלק ממשימה לא־נעימה על כל תפוח. עונש חיובי (הפסקת חטיפים): הוספת זמן ריצה על כל חטיף. עונש שלילי (הפסקת חטיפים): הסרת נקודות שנצברו על כל חטיף.","explain":"יישום מעשי של ארבעת-סוגי-התוצאות על תרחיש-דיאטה אמיתי - חשוב לשים-לב שבכל תרחיש נדרש להפעיל <b>סוג-תוצאה שונה על התנהגות אחרת</b>: <b>לעודד</b> אכילת-תפוחים (התנהגות רצויה, רוצים להגביר) - אפשר דרך <b>חיזוק חיובי</b> (הוספת נקודה על כל תפוח שנאכל) או <b>חיזוק שלילי</b> (הסרת חלק ממשימה-לא-נעימה, כמו הפחתת-מטלות-בית, על כל תפוח). <b>להפחית</b> אכילת-חטיפים (התנהגות בלתי-רצויה, רוצים להקטין) - אפשר דרך <b>עונש חיובי</b> (הוספת זמן-ריצה בעקבות כל חטיף שנאכל) או <b>עונש שלילי</b> (הסרת נקודות שכבר נצברו, בעקבות כל חטיף). ⚠️ שימו לב שלכל אחד מארבעת-הסוגים יש יישום הגיוני אחר - אין 'שיטה אחת נכונה', והבחירה תלויה במה זמין ובמה יעיל יותר בפועל עבור אותו אדם.","mnemo":"🍎 4 תוכניות לשלמה: הוסף-נקודה-על-תפוח(חיזוק+), הסר-משימה-על-תפוח(חיזוק-), הוסף-ריצה-על-חטיף(עונש+), הסר-נקודות-על-חטיף(עונש-)."},{"id":"prof5_reflection4","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"זהו את הגירוי המבחין, התגובה והתוצאה: (א) מורה נוזפת בתלמיד הקופץ בשיעור אך לא בהפסקה. (ב) נטע צופה בטלוויזיה מאוחר כשאימה לא בבית. (ג) יעל קוראת בשקיקה רק ספרות בלשית.","a":"(א) גירוי מבחין=נוכחות בשיעור. תגובה=קפיצה. תוצאה=נזיפה (רק בשיעור). (ב) גירוי מבחין=היעדרות האם. תגובה=צפייה מאוחרת. תוצאה=אין נזיפה. (ג) גירוי מבחין=ספר בלשי. תגובה=קריאה בשקיקה. תוצאה=הנאה/חיזוק חיובי.","explain":"תרגיל זה בודק זיהוי של <b>שלושת-מרכיבי-התלות-המשולשת</b> (giryu mavchin, תגובה, תוצאה) מתוך תיאורי-מצב יומיומיים - התלות-המשולשת היא המבנה הבסיסי שמנתח כל התנהגות אופרנטית. <b>(א) מורה/תלמיד</b>: <b>גירוי-מבחין</b> = נוכחות בשיעור (זה מה שמאותת שהתגובה תגרור השלכות); <b>תגובה</b> = קפיצה; <b>תוצאה</b> = נזיפה, אך <b>רק</b> בהקשר-השיעור (בהפסקה, אותה תגובה בדיוק לא גוררת תוצאה). <b>(ב) נטע/אמא</b>: <b>גירוי-מבחין</b> = היעדרות-האם (זה קובע מתי ההתנהגות 'בטוחה'); <b>תגובה</b> = צפייה-מאוחרת; <b>תוצאה</b> = אין-נזיפה (כי האם לא נוכחת לגלות). <b>(ג) יעל</b>: <b>גירוי-מבחין</b> = ספר-בלשי (מזהה את סוג-הטקסט המבטיח הנאה); <b>תגובה</b> = קריאה-בשקיקה; <b>תוצאה</b> = הנאה, שמהווה חיזוק-חיובי. ⚠️ המסר המרכזי: גירוי-מבחין <b>אינו</b> גורם ישירות להתנהגות (כמו ב-CS בהתניה-קלאסית) - הוא רק 'מאותת' <b>מתי</b> ההתנהגות תגרור תוצאה מסוימת.","mnemo":"🏫🌙📚 (א)שיעור=גירוי-מבחין. (ב)אמא-לא-בבית=גירוי-מבחין. (ג)ספר-בלשי=גירוי-מבחין. בכל מקרה: מתי מסוים→תגובה→תוצאה."},{"id":"prof5_26","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד מסייעים עקרונות ההתניה האופרנטית להבין התנהגות אנטי־חברתית של ילדים?","a":"מודל הכפייה (פטרסון): הורים מאיימים אך לא מממשים איומים על התנהגויות שוליות, אך לעיתים מגיבים באלימות/משמעת נוקשה על אותן התנהגויות. הילד לומד שפעולות תוקפניות משיגות מטרות - מה שמגביר התנהגות אנטי־חברתית.","explain":"<b>מודל הכפייה (coercion model)</b> של <b>פטרסון</b> מסביר איך התניה-אופרנטית, בלי-כוונה, יכולה 'לאמן' ילדים להיות תוקפניים יותר: הורים לעיתים <b>מאיימים</b> בעונש על התנהגויות-שוליות (למשל, 'אם לא תפסיק לצעוק אכעס') אך <b>לא-ממשים</b> את האיום בפועל (בגלל עייפות, חוסר-עקביות, או ויתור) - כלומר, האיום 'ריק'. אך <b>לעיתים אחרות</b>, אותם הורים מגיבים <b>באלימות/משמעת-נוקשה</b> יתר-על-המידה על אותן ההתנהגויות בדיוק. <b>התוצאה</b>: הילד לומד דרך התניה-אופרנטית (חוויה חוזרת) ש<b>פעולות תוקפניות משיגות את מטרתו</b> - הוא מקבל מה שרוצה כי ההורה מוותר תחת לחץ, או שהוא לומד לצפות שרק תגובה-קיצונית-משלו תזכה בתשומת-לב אמיתית. חוסר-העקביות ההורי, פרדוקסלית, הוא בדיוק מה שמחזק את ההתנהגות האנטי-חברתית לאורך זמן.","mnemo":"🎭 הורה \"מאיים-ריק\" אבל מגיב חזק רק לתוקפנות אמיתית - הילד לומד: \"תוקפנות=הדרך שעובדת\" (מודל הכפייה)."},{"id":"prof5_27","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהם רווחים משניים וכיצד הם מסבירים התנהגויות בלתי רצויות?","a":"תגמולים עקיפים (תשומת־לב, אהדה, פטור מאחריות) המתקבלים כתוצאה מהתנהגות, גם לא־רציונלית/הרסנית. מחזקים את ההתנהגות הלא־רצויה (למשל, סימפטומים שאינם חולפים, או ביישנות) אף שהאדם היה מעדיף אחרת.","explain":"<b>רווחים משניים (secondary gains)</b> הם תגמולים <b>עקיפים</b> - תשומת-לב, אהדה, פטור-מאחריות, דאגה-של-הסביבה - המתקבלים <b>כתוצאה</b> מהתנהגות מסוימת, גם אם ההתנהגות-עצמה <b>לא-רציונלית או אפילו הרסנית</b>. הרעיון המפתיע: הרווחים-המשניים האלה <b>מחזקים באופן לא-מודע</b> את ההתנהגות-הבלתי-רצויה (למשל, סימפטום-פיזי שלא חולף, או ביישנות שמונעת ממישהו להתמודד עם מצבים חברתיים) - <b>גם כאשר</b> האדם-עצמו, אילו נשאל ישירות, היה מעדיף בהחלט להיפטר מהבעיה. ⚠️ הנקודה הקלינית החשובה: זה מסביר למה תסמינים מסוימים 'מתעקשים להישאר' למרות רצון-כן-ואמיתי להחלים - אם התסמין (למשל, כאב-גב כרוני) ממשיך לגרור תשומת-לב/דאגה/פטור-ממטלות, יש חיזוק לא-מודע ברור שממשיך להזין אותו, גם בניגוד לרצון המודע להחלים.","mnemo":"🎁 רווח-משני = מתנה-נסתרת - תשומת-לב/אהדה שמגיעה \"בחינם\" בגלל בעיה, ומחזקת אותה בלי כוונה."},{"id":"prof5_reflection5","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"זהו התנהגות, תוצאה וגירוי מבחין: (א) ילד בכיתה מול הפסקה. (ב) הורים מאיימים אך לא תמיד מממשים, לעיתים ענישה אלימה.","a":"(א) התנהגות=ישיבה בשקט. גירוי מבחין=נוכחות בכיתה/שיעור. (ב) התנהגות=פעולות תוקפניות של הילד. תוצאה=לא עקבית (איום ריק לעומת ענישה אלימה). אין גירוי מבחין ברור - זו בדיוק הבעיה, התגובה שרירותית ובלתי צפויה.","explain":"המשך התרגיל על התלות-המשולשת, הפעם עם דגש על זיהוי מקרה שבו <b>אין</b> גירוי-מבחין ברור - וזו בדיוק הבעיה שהשאלה מדגישה. <b>(א)</b> ילד שיושב-בשקט בכיתה מול מתפרע בהפסקה: <b>התנהגות</b> = ישיבה-בשקט; <b>גירוי-מבחין</b> = נוכחות-בכיתה/בשיעור (בדיוק כמו בשאלת-ההרהור הקודמת - ההקשר קובע מה מותר). <b>(ב)</b> ההורים שמאיימים-אך-לא-תמיד-מממשים, ולעיתים מענישים באלימות: <b>התנהגות</b> = פעולות-תוקפניות-של-הילד; <b>תוצאה</b> = <b>לא-עקבית</b> - לפעמים איום-ריק (שקורא לילד להמשיך, כי אין השלכה אמיתית), לפעמים ענישה-אלימה-בפועל. <b>הנקודה המרכזית</b>: כאן <b>אין גירוי-מבחין ברור</b> - זו בדיוק הבעיה (הקושרת לשאלת-מודל-הכפייה של פטרסון): הילד לא יכול לצפות באופן-אמין מתי ההתנהגות תגרור-השלכה ומתי לא, כי תגובת-ההורים שרירותית ובלתי-צפויה - חוסר-היכולת-לחזות בדיוק הוא זה שמזין את הבעיה.","mnemo":"🎲 (ב) איום-ריק+לפעמים-ענישה = בלי גירוי-מבחין ברור - זו בדיוק הבעיה (חוסר-עקביות)."},{"id":"prof5_28","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהם מחזקים ראשוניים?","a":"מחזקים שתכונת החיזוק שלהם נקבעה באורח ביולוגי, טבועים בנו מלידה, ללא צורך בלמידה. דוגמאות: מזון ומים.","explain":"<b>מחזקים ראשוניים (primary reinforcers)</b> הם מחזקים שתכונת-החיזוק שלהם <b>נקבעה ביולוגית מלידה</b> - הם 'עובדים' על כל בעל-חיים (כולל אדם) <b>ללא כל צורך בלמידה מוקדמת</b>, כי הם קשורים ישירות לצרכי-הישרדות בסיסיים. הדוגמאות המובהקות: <b>מזון ומים</b> (מספקים צרכים פיזיולוגיים ישירים). ⚠️ הבחנה חשובה מהשאלה הבאה: מחזקים-ראשוניים תמיד יעבדו, אצל כל אורגניזם רעב/צמא, ללא תלות בתרבות/היסטוריה-אישית - זה מבדיל אותם באופן חד ממחזקים-מותנים (השאלה הבאה), שערכם-כמחזק <b>נלמד</b> ולא מולד.","mnemo":"🍞💧 מחזק ראשוני = צורך ביולוגי-בסיסי (מזון/מים) - לא צריך ללמוד למה זה טוב."},{"id":"prof5_29","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהם מחזקים מותנים?","a":"גירויים ניטרליים במקור, שרכשו כוח חיזוק דרך זיווג עם מחזק ראשוני. דוגמאות: כסף, ציונים, אישור חברתי. יישום: כלכלת אסימונים (בבתי חולים/גמילה) - אסימונים ניתנים על התנהגות רצויה, ניתנים להמרה בתגמולים.","explain":"<b>מחזקים מותנים (conditioned/secondary reinforcers)</b> הם גירויים שהיו <b>ניטרליים במקור</b> (לא-מעניינים כשלעצמם) - אך <b>רכשו</b> את כוחם-לחזק דרך זיווג חוזר עם מחזק-ראשוני. הדוגמאות: <b>כסף</b> (בעצמו רק נייר/מתכת, אך רכש ערך-חיזוקי כי אפשר להמיר אותו במזון/מוצרים), <b>ציונים</b> (רכשו ערך דרך קישור להישגים/הכרה), <b>אישור חברתי</b> (נלמד לאורך התפתחות חברתית). ⚠️ <b>יישום מעשי חשוב</b>: <b>כלכלת-אסימונים</b> (משמשת בבתי-חולים פסיכיאטריים ותוכניות-גמילה) - אסימונים (עצמם חסרי-ערך פנימי) ניתנים כתגמול מיידי על התנהגות-רצויה, וניתן להמירם בהמשך בתגמולים-אמיתיים (זמן-פנוי, מוצרים) - כך יוצרים מערכת-חיזוק שנוחה לניהול, המבוססת על עיקרון-המחזק-המותנה.","mnemo":"💰🎓 מחזק מותנה = כסף/ציונים - היו ניטרליים, \"קיבלו כוח\" רק כי נקשרו למשהו ראשוני."},{"id":"prof5_30","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו חיזוק חלקי ובמה הוא שונה מחיזוק מלא?","a":"חיזוק מלא = כל תגובה מחוזקת. חיזוק חלקי = רק חלק מהתגובות מחוזקות. תגובות שנרכשו בחיזוק חלקי עמידות יותר בפני הכחדה (השפעת החיזוק החלקי, מסקינר).","explain":"ההבדל בין <b>חיזוק מלא</b> ל<b>חיזוק חלקי</b> הוא פשוט: בחיזוק-מלא, <b>כל</b> תגובה-רצויה מחוזקת (100% מהפעמים); בחיזוק-חלקי, <b>רק חלק</b> מהתגובות מחוזקות (למשל, אחת מכל חמש פעמים). <b>הממצא המפתיע והחשוב</b> (המכונה 'השפעת-החיזוק-החלקי', שגילה סקינר): התנהגויות שנרכשו דרך חיזוק-חלקי <b>עמידות הרבה יותר בפני הכחדה</b> מהתנהגויות שנרכשו בחיזוק-מלא - כלומר, לוקח יותר-זמן לגרום להן להיעלם כשהחיזוק מפסיק לגמרי. ⚠️ זה נראה נוגד-אינטואיציה (הרי חיזוק-מלא נראה 'חזק יותר'), אך ההסבר יינתן בשאלה הבאה - הוא קשור ליכולת להבחין בין 'מצב-רגיל' ל'מצב-הכחדה'.","mnemo":"🎰 חיזוק-חלקי = כמו מכונת-מזל - אי-הוודאות גורמת להתמדה חזקה יותר מחיזוק על כל תגובה."},{"id":"prof5_31","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"סכמו את 4 תכניות החיזוקים החלקיות (יחס/רווח × קבוע/משתנה).","a":"יחס קבוע=לפי מספר תגובות קבוע, הפסקה קצרה אחרי חיזוק (למשל אנשי מכירות). יחס משתנה=לפי מספר תגובות ממוצע, שיעור התגובות הגבוה ביותר, עמיד ביותר בפני הכחדה (מכונות מזל). רווח קבוע=לפי פרק זמן קבוע, תבנית מסולסלת (בדיקת תנור). רווח משתנה=לפי פרק זמן ממוצע, קצב מתון ויציב, הכחדה איטית מאוד (מבחני פתע).","explain":"ארבע תכניות-החיזוק-החלקי נוצרות מהצלבת שני צירים: <b>מה קובע חיזוק</b> (מספר-תגובות=יחס / זמן=רווח) ו<b>האם הכמות קבועה או משתנה</b>: <b>יחס קבוע</b> - חיזוק אחרי מספר-תגובות <b>קבוע</b> (למשל, כל 10 מכירות) - יוצר תבנית של פעולה-מהירה ואז <b>הפסקה-קצרה</b> מיד-אחרי-החיזוק (כמו אנשי-מכירות שנחים אחרי עמידה-ביעד). <b>יחס משתנה</b> - חיזוק אחרי מספר-תגובות שמשתנה סביב ממוצע (בלתי-צפוי) - יוצר <b>שיעור-התגובות הגבוה ביותר מכל התכניות</b>, ו<b>עמיד ביותר בפני הכחדה</b> (הדוגמה הקלאסית: מכונות-מזל - אי-אפשר לדעת מתי הזכייה הבאה, אז ממשיכים לנסות). <b>רווח קבוע</b> - חיזוק אחרי <b>פרק-זמן קבוע</b> (למשל, כל שעה) - יוצר תבנית 'מסולסלת': פעילות-מועטה בתחילת-הפרק וגוברת-ככל שמתקרבים לזמן-החיזוק (כמו בדיקת-תנור לפני שהוא אמור להיות מוכן). <b>רווח משתנה</b> - חיזוק אחרי פרק-זמן משתנה (בלתי-צפוי) - יוצר קצב <b>מתון ויציב</b>, ו<b>הכחדה הכי-איטית מכל התכניות</b> (כמו מבחני-פתע, שגורמים ללמידה-קבועה כי אי-אפשר לדעת מתי הם יגיעו).","mnemo":"🛒⏰ יחס=כמות. רווח=זמן. קבוע=צפוי, משתנה=מפתיע. יחס-משתנה(מכונת-מזל)=הכי חזק/עמיד. רווח-קבוע(תנור)=מסולסל."},{"id":"prof5_32","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הציעו 4 תכניות לעודד ילדים לסדר את חדרם (יחס קבוע/משתנה, רווח קבוע/משתנה).","a":"יחס קבוע = תגמול אחרי מספר קבוע של פעמים שהחדר מסודר. יחס משתנה = תגמול אחרי מספר משתנה (ממוצע) של פעמים. רווח קבוע = בדיקה בזמן קבוע (כל יום ראשון). רווח משתנה = בדיקה בזמנים בלתי צפויים, בממוצע קבוע.","explain":"יישום מעשי של ארבעת-התכניות על הורות-יומיומית - חשוב להבין את ההיגיון-הפונקציונלי מאחורי כל בחירה: <b>יחס קבוע</b> = תגמול אחרי מספר-קבוע-מראש של פעמים שהחדר סודר (למשל, כל שלוש פעמים) - צפוי לילד, אבל עלול ליצור 'הפסקה' מיד-אחרי-קבלת-התגמול. <b>יחס משתנה</b> = תגמול אחרי מספר-משתנה (ממוצע-ידוע, אך בלתי-צפוי בכל פעם ספציפית) - סביר שייצור את ההתמדה-הגבוהה-ביותר, כי הילד לא-יודע-מתי-הפעם-הבאה-תזכה. <b>רווח קבוע</b> = בדיקה בזמן-קבוע (כל יום-ראשון) - צפוי, אך עלול ליצור 'זינוק' של סידור-חדר רק ממש-לפני-הבדיקה. <b>רווח משתנה</b> = בדיקות בזמנים בלתי-צפויים (ממוצע-ידוע) - סביר שייצור סדר <b>עקבי לאורך כל השבוע</b>, כי לא ניתן 'לתזמן' סידור רק-לפני-הבדיקה.","mnemo":"🧹 חדר-ילדים: יחס-קבוע=כל-X-פעמים. יחס-משתנה=ממוצע-לא-צפוי. רווח-קבוע=כל-יום-ראשון. רווח-משתנה=בדיקות-פתע."},{"id":"prof5_33","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע התניה שנרכשה בחיזוק חלקי עמידה יותר להכחדה מהתניה בחיזוק מלא?","a":"בחיזוק מלא, הפסקת התגמול בולטת ומיידית (ניגוד חד למצב הקודם). בחיזוק חלקי, האורגניזם רגיל לרצפים ללא תגמול - קשה לו להבחין בין רצף רגיל להכחדה אמיתית, ולכן ממשיך להגיב זמן רב יותר.","explain":"ההסבר לפרדוקס (למה חיזוק-חלקי עמיד יותר בפני הכחדה מחיזוק-מלא) טמון בקושי <b>להבחין</b> בין 'מצב-רגיל' ל'מצב-שהחיזוק-נפסק-לגמרי': בחיזוק-מלא, האורגניזם רגיל שכל תגובה מקבלת חיזוק - כך שברגע שהחיזוק מפסיק (הכחדה), ה<b>ניגוד חד ובולט מיד</b> - קל 'להבחין' שמשהו השתנה, ולכן ההתנהגות נחלשת מהר. בחיזוק-חלקי, לעומת זאת, האורגניזם <b>כבר רגיל</b> לחוות רצפים-ארוכים-של-תגובות-ללא-חיזוק כחלק מהמצב-הרגיל - לכן כשההכחדה-האמיתית מתחילה, קשה לו להבחין בינה לבין 'עוד רצף רגיל ללא-חיזוק' שכבר חווה קודם רבות פעמים - ולכן ממשיך להגיב זמן רב יותר לפני שהוא 'מבין' שהחיזוק אכן נעלם לצמיתות.","mnemo":"🛑 חיזוק-מלא=ההפסקה \"צורמת\" מיד (ברור). חיזוק-חלקי=כבר רגיל לרצפים-ריקים, קשה להבחין מתי זו הכחדה אמיתית."},{"id":"prof5_34","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו סחף אינסטינקטיבי וכיצד הוא משקף מגבלות ביולוגיות על התניה אופרנטית?","a":"תופעה שבה התנהגות אופרנטית נלמדת נסחפת עם הזמן לעבר התנהגות אינסטינקטיבית מולדת של המין (למשל, דביבון משפשף מטבעות כמו שהוא משפשף מאכל). מוכיחה שהגנוטיפ קובע גבולות שהחיזוקים לבדם אינם יכולים לעבור.","explain":"<b>סחף אינסטינקטיבי (instinctive drift)</b> חושף <b>מגבלה ביולוגית מולדת</b> על יכולת-הלמידה-האופרנטית: לאורך זמן, התנהגות אופרנטית שנלמדה (דרך חיזוק) עלולה 'לנסחף' בהדרגה <b>לעבר</b> התנהגות-אינסטינקטיבית-מולדת האופיינית למין. הדוגמה הקלאסית: דביבון אומן לשים מטבעות בקופסה (התנהגות-נלמדת), אך עם הזמן החל <b>לשפשף</b> את המטבעות זה-בזה במקום להפקידם - בדיוק כמו שדביבונים משפשפים <b>מזון</b> (התנהגות אינסטינקטיבית טבעית של 'שטיפת-מזון'). <b>המסקנה החשובה</b>: הגנוטיפ (המטען הגנטי-מולד) <b>קובע גבולות</b> שחיזוקים-ולמידה-אופרנטית <b>לבדם אינם יכולים לעבור</b> - אי-אפשר 'לאמן החוצה' התנהגות-מולדת-עמוקה לגמרי, גם עם חיזוק עקבי - ההתנהגות המולדת 'מנצחת' בסופו-של-דבר את ההתנהגות-הנלמדת.","mnemo":"🦝🪙 דביבון משפשף מטבעות (כמו שמשפשף אוכל) - האינסטינקט המקורי \"מנצח\" את הלמידה החדשה עם הזמן."},{"id":"prof5_35","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד אפשר ליצור התניה אופרנטית בלי סכנת סחף אינסטינקטיבי (מחזקים ראשוניים ומותנים)?","a":"לבחור מחזק ראשוני שאינו מעורר אינסטינקט מתחרה (למשל, מים במקום מזון עבור חזירים) - כך המחזק המותנה (כמו אסימון) לא יזכיר לבעל החיים התנהגות טבעית מתחרה (כמו נבירה במזון).","explain":"כדי ליצור התניה-אופרנטית יעילה בלי-סכנת-סחף-אינסטינקטיבי, יש לבחור <b>בזהירות</b> את המחזק-הראשוני: העיקרון המרכזי הוא לבחור מחזק שאינו מעורר <b>אינסטינקט-מתחרה</b> אצל אותו-מין - כלומר, מחזק שלא 'מזכיר' לבעל-החיים התנהגות-טבעית-אחרת שעלולה להתחרות עם ההתנהגות-הנלמדת. הדוגמה: עבור חזירים (שיש להם אינסטינקט חזק-במיוחד של <b>נבירה-בקרקע</b> כשמדובר במזון), עדיף לבחור <b>מים</b> כמחזק-ראשוני במקום מזון - כי מים לא מעוררים את אותו אינסטינקט-הנבירה שעלול 'לחטוף' את ההתנהגות-הנלמדת ולגרום לסחף כלפי נבירה-במקום-פעולה-רצויה. באופן דומה, המחזק-המותנה (למשל אסימון) לא יזכיר לבעל-החיים את ההתנהגות-הטבעית-המתחרה, ולכן פחות סיכוי לסחף.","mnemo":"💧 בוחרים מחזק-ראשוני שלא \"מתחרה\" עם אינסטינקט (מים לחזיר, לא אוכל) - כך נמנע סחף."},{"id":"prof5_36","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי סלידה נלמדת מטעם וכיצד היא נרכשת?","a":"למידה להימנע ממאכל שקדם להרגשת מחלה/הקאה. נרכשת בזיווג חד־פעמי בלבד (לא נדרשת חזרה), גם עם פסק זמן ארוך (12 שעות ומעלה), והקישור נשאר קבוע וחזק לאחר ניסיון אחד.","explain":"<b>סלידה נלמדת מטעם (taste aversion)</b> היא צורת-למידה מיוחדת ומרתקת: למידה <b>להימנע ממאכל</b> ספציפי שקדם להרגשת-מחלה/הקאה - אך היא <b>שונה באופן דרמטי</b> מהתניה-קלאסית 'רגילה' בשני מובנים מפתיעים: <b>נרכשת בזיווג חד-פעמי בלבד</b> (לא נדרשות חזרות רבות כמו בהתניה-קלאסית-סטנדרטית - טעימה אחת שקדמה למחלה מספיקה). <b>נרכשת גם עם פסק-זמן ארוך</b> בין הטעימה למחלה (אפילו 12 שעות ומעלה - הרבה מעבר לחלון-הזמן-הקצר-הרגיל שנדרש בהתניה-קלאסית סטנדרטית). והקישור שנוצר <b>נשאר קבוע וחזק</b> לאורך זמן רב, גם אחרי חוויה אחת בלבד. ⚠️ תופעה זו סוללת את הדרך לשאלה הבאה, שמסבירה <b>למה</b> דווקא טעם-ומחלה מתנהגים כך, בניגוד לכללי-ההתניה-הרגילים.","mnemo":"🤢 סלידה-מטעם = פעם אחת מספיקה, גם 12 שעות אחרי - זיכרון-הישרדות מיוחד, לא כמו התניה רגילה."},{"id":"prof5_37","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד סלידה נלמדת מטעם משקפת מגבלות ביולוגיות על התניה קלאסית (ניסוי גארסיה וקולינג)?","a":"חולדות נמנעו ממים ממותקים רק כשניבאו מחלה (לא הלם), ונמנעו מרעש/אור רק כשניבאו הלם (לא מחלה). מראה הטיה מולדת: טעם מקושר גנטית למחלה, גירויים חיצוניים מקושרים לכאב חיצוני - לא כל צירוף CS-UCS ניתן ללמידה באותה קלות.","explain":"ניסוי <b>גארסיה וקולינג</b> חשף שסלידה-נלמדת-מטעם משקפת <b>הטיה ביולוגית מולדת ולא-אקראית</b>, המערערת על ההנחה הקלאסית שכל צירוף CS-UCS ניתן ללמידה באותה קלות. במחקרם, חולדות נחשפו לשילוב של <b>מים-ממותקים</b> (טעם) עם <b>אור/רעש</b> (גירויים חיצוניים), ולאחר-מכן הפעילו <b>מחלה</b> (בחילה) או <b>הלם-חשמלי</b> (כאב). התוצאה המפתיעה: החולדות למדו להימנע מ<b>המים-הממותקים רק כשהם ניבאו מחלה</b> (לא כשניבאו הלם) - ולמדו להימנע <b>מהרעש/האור רק כשהם ניבאו הלם</b> (לא כשניבאו מחלה). <b>המשמעות</b>: יש <b>הטיה גנטית-אבולוציונית מולדת</b> - טעם מקושר 'טבעי'-יותר למחלה (הגיוני: הרעל בטבע נכנס דרך הפה), בעוד גירויים-חיצוניים (אור/רעש) מקושרים 'טבעי'-יותר לכאב-חיצוני (הגיוני: סכנה חיצונית מגיעה עם רעש/תנועה) - <b>לא כל</b> צירוף-CS-UCS ניתן ללמידה באותה קלות; חלק 'מוכנים ביולוגית' יותר מאחרים.","mnemo":"🍬🤢⚡😖 מים-מתוקים+מחלה=לומדים (טעם↔חולי מתאים). רעש+מחלה=לא-לומדים (לא מתאים). המוח \"מכוון\" מראש איזה זוג הגיוני."},{"id":"prof5_38","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד אפשר להכחיד סלידה נלמדת מטעם?","a":"חשיפה חוזרת למאכל בלי שהמחלה חוזרת (הכחדה טבעית, כפי שקרה אצל נשים שידעו רציונלית שהכימותרפיה גרמה לבחילה). מניעה: לתת מאכל 'שעיר לעזאזל' בטעם מוזר לפני טיפול, כדי שהסלידה תותנה רק אליו ולא למאכלים הרגילים.","explain":"כדי <b>להכחיד</b> סלידה-נלמדת-מטעם, נדרש בדיוק העיקרון-הכללי של הכחדה בהתניה-קלאסית: <b>חשיפה חוזרת</b> למאכל <b>בלי</b> שהמחלה חוזרת בפועל - עם הזמן, הקישור נחלש. ⚠️ הוכחה מרגשת לכך: נשים שעברו כימותרפיה (וידעו <b>רציונלית-במפורש</b> שהטיפול, לא המאכל, גרם לבחילה) עדיין פיתחו סלידה-חזקה ממאכלים שאכלו לפני הטיפול - אך עם חשיפה-חוזרת לאותם מאכלים ללא-הטיפול, הסלידה נחלשה בהדרגה, בדיוק כמו הכחדה רגילה. <b>יישום מונע חכם</b>: כדי למנוע-מראש סלידה מהתפריט-הרגיל, אפשר לתת <b>מאכל 'שעיר-לעזאזל'</b> - מאכל בעל טעם-מוזר-וייחודי ממש לפני טיפול (כמו כימותרפיה) - כך הסלידה שתתפתח תתמקד <b>רק</b> באותו מאכל-מיוחד, ולא 'תדביק' את המאכלים הרגילים והחשובים בתפריט-היומיומי.","mnemo":"🌭 שוב-ושוב לאכול בלי לחלות = ההכחדה. טריק: לתת \"שעיר-לעזאזל\" בטעם מוזר לפני טיפול, כדי שהסלידה \"תיפול\" עליו ולא על האוכל הרגיל."},{"id":"prof5_39","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מה למדו החולדות במבוך של טולמן ומדוע אי אפשר להסביר זאת בהתניה קלאסית/אופרנטית?","a":"החולדות פיתחו מפה קוגניטיבית פנימית של המבוך כולו, ולכן מצאו מסלול חלופי שמעולם לא קיבל חיזוק. אי אפשר להסביר בעזרת התניה, כי זו מבוססת על קשרי גירוי-תגובה-חיזוק שכבר נלמדו בעבר - לא על תגובה חדשה שמעולם לא זווגה עם חיזוק.","explain":"מבוך-טולמן הוא ניסוי-מפתח שאתגר את ההנחה שכל למידה מוסברת דרך התניה: החולדות, ששחו במבוך והכירו אותו היטב, הראו שהן פיתחו <b>מפה קוגניטיבית פנימית</b> - ייצוג-מנטלי-שלם של פריסת-המבוך כולו, לא רק 'קשרי גירוי-תגובה' ספציפיים למסלול אחד. ההוכחה: כאשר המסלול-הרגיל נחסם, החולדות מצאו <b>מיד</b> מסלול-חלופי-קצר <b>שמעולם לא קיבל חיזוק ישירות</b> - הן 'ידעו' לבחור אותו כאילו הבינו את גיאומטריית-המבוך-כולה. ⚠️ <b>למה זה מערער התניה-קלאסית/אופרנטית</b>: שתי התיאוריות מבוססות על <b>קשרים שכבר נלמדו בעבר</b> (זיווג-גירויים או תגובה-שגררה-חיזוק) - אך כאן מדובר בתגובה <b>חדשה לגמרי</b>, מסלול שמעולם לא זווג עם חיזוק ומעולם לא נוסה קודם - אי-אפשר להסביר בחירה-נכונה-מיידית שכזו רק דרך תהליכי-התניה; נדרשת הנחה שהחולדות בנו ייצוג-פנימי-קוגניטיבי (מפה) של הסביבה, לא רק אספו קשרי-גירוי-תגובה נקודתיים.","mnemo":"🗺️ חולדות טולמן = מפה שלמה בראש (לא שינון-תגובה) - לכן מוצאות קיצור-דרך שמעולם לא תוגמל."},{"id":"prof5_40","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע בדקו החוקרים את תגובות היונים גם לגירויים חדשים?","a":"כדי לבדוק אם היונים למדו קטגוריה מופשטת (למשל 'פרח' באופן כללי) ולא רק שיננו תגובות לתצלומים ספציפיים. הצלחה בתצלומים חדשים הוכיחה למידת קטגוריות אמיתית, לא שינון.","explain":"החוקרים בדקו במיוחד תגובות-היונים לגירויים <b>חדשים</b> (שלא הוצגו כלל בשלב-האימון) כדי להבחין בין שתי אפשרויות תיאורטיות שונות מאוד: <b>שינון פשוט</b> - היונים למדו רק לזהות תצלומים-ספציפיים שכבר ראו (ואז תגובתן לתצלומים חדשים תהיה אקראית, כי לא 'ראו' אותם קודם), לעומת <b>למידת-קטגוריה-מופשטת</b> - היונים למדו את המושג הכללי 'פרח' (או כל קטגוריה אחרת) עצמו, לא רק דוגמאות-ספציפיות. <b>התוצאה שנמצאה</b>: היונים הצליחו לזהות נכון גם תצלומים-חדשים-לגמרי (שמעולם לא נראו באימון) כשייכים לקטגוריה - זו הוכחה חד-משמעית ש<b>למידת-קטגוריות-אמיתית</b> התרחשה, לא סתם שינון-פרטים - זהו רמז חשוב לכך שגם חיות 'פשוטות' יחסית (יונים) מסוגלות ליצור ייצוגים-מושגיים-מופשטים, לא רק לקשור גירוי-תגובה נקודתי.","mnemo":"🕊️🌸 יונה שמזהה \"פרח\" גם בתמונה חדשה = הבינה קטגוריה כללית, לא שיננה תמונה ספציפית."},{"id":"prof5_41","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו חיזוק מתווך ומהו עונש מתווך?","a":"למידה מצפייה בתוצאות (חיזוק/עונש) שקיבל אדם אחר, בלי לחוות אותן בעצמנו. דוגמה: נוטים לטעום מאכל חדש כי מניחים שאחרים כבר טעמו ונהנו ממנו.","explain":"<b>חיזוק/עונש מתווך</b> (vicarious reinforcement/punishment) הוא מנגנון-למידה מבוסס-צפייה שחורג לחלוטין ממה שהתניה-קלאסית/אופרנטית 'רגילה' מסבירות: למידה מ<b>תוצאות שקיבל אדם-אחר</b> (חיזוק או עונש) - <b>בלי</b> שהצופה-עצמו חווה בעצמו את החיזוק/העונש הזה במישרין. הדוגמה: אנחנו נוטים לטעום מאכל-חדש במסעדה כשרואים שאחרים סביבנו כבר טעמו ונהנו ממנו - למדנו (בעקיפין, מהצפייה בהם) 'לצפות' שגם אנחנו ניהנה, בלי שקיבלנו את הפינוק/החיזוק בעצמנו כלל. השם 'מתווך' (vicarious) מרמז בדיוק על-כך: החיזוק/העונש 'עובר דרך' תצפית באדם-אחר, ומגיע אלינו-עקיף.","mnemo":"👀 חיזוק/עונש מתווך = צופה-מהצד - רואה מה קרה לאחר, לא חווה בעצמו."},{"id":"prof5_42","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע אי אפשר להסביר חיזוק/עונש מתווך בגישה הביהביוריסטית הקלאסית של סקינר?","a":"בביהביוריזם קלאסי חיזוק חייב לבוא ישירות אחרי תגובה של האורגניזם עצמו. בחיזוק מתווך, הלומד לא ביצע תגובה ולא קיבל חיזוק בעצמו - הלמידה מתרחשת דרך תיווך קוגניטיבי (זכירה, הסקת מסקנות), לא דרך התניה ישירה.","explain":"חיזוק/עונש מתווך <b>אינו ניתן להסבר</b> בגישת-הביהביוריזם-הקלאסי הטהורה של סקינר, בגלל דרישת-יסוד בתיאוריה שלו: לפי סקינר, <b>חיזוק חייב לבוא ישירות אחרי תגובה שהאורגניזם-עצמו ביצע</b> - זהו הבסיס לכל תהליך-ההתניה-האופרנטית. אך בחיזוק-מתווך, <b>הלומד-עצמו לא ביצע שום תגובה</b> (רק צפה מהצד), ו<b>לא קיבל שום חיזוק בעצמו</b> (החיזוק ניתן לאדם-האחר, לא לו). ⚠️ המסקנה החשובה: הלמידה-כאן מתרחשת דרך <b>תיווך קוגניטיבי</b> - זכירה של מה-שראה, הסקת-מסקנות ('אם זה עבד עבורו, כנראה יעבוד גם אצלי'), ציפייה-מנטלית שנבנתה - <b>לא</b> דרך התניה-ישירה. זו בדיוק הסיבה שנדרשה תוספת-תיאורטית מעבר לביהביוריזם-הטהור (התיאוריה של בנדורה, למידה-חברתית) כדי להסביר תופעה זו.","mnemo":"🚫 סקינר דורש חיזוק ישיר-אחרי-תגובה-שלי. כאן אין תגובה שלי בכלל - זה קורה \"בראש\" (קוגניטיבי), לא בהתניה טהורה."},{"id":"prof5_43","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו למידה באמצעות צפייה בעזרת המונחים חיזוק/עונש מתווך.","a":"רואים אדם אחר מקבל חיזוק/עונש על התנהגות, ולומדים לצפות לאותה תוצאה אם ננהג כמוהו. מאפשר לרכוש התנהגות מורכבת ללא ניסוי וטעייה אישי (למשל, ילד לומד מטעויות אחותו הגדולה).","explain":"למידה-באמצעות-צפייה (observational learning) בנויה כולה על עקרון חיזוק/עונש-מתווך: אנחנו רואים אדם-אחר (המודל) <b>מקבל</b> חיזוק או עונש בעקבות התנהגות מסוימת, ולומדים <b>לצפות</b> לאותה תוצאה-בדיוק אם ננהג-כמוהו. <b>היתרון האבולוציוני-מעשי העצום</b>: זה מאפשר לרכוש התנהגות מורכבת <b>בלי</b> להזדקק לניסוי-וטעייה-אישי-מסוכן-ואיטי - למשל, ילד יכול ללמוד מהטעויות של אחותו-הגדולה (למשל, רואה אותה נענשת על משהו) בלי לחוות בעצמו את התוצאה-השלילית - חוסך זמן, סיכון, וכאב. ⚠️ זהו רעיון מרכזי בתיאוריית-הלמידה-החברתית של בנדורה: אנחנו לא זקוקים לחיזוק/עונש-ישיר-אישי כדי ללמוד; תצפית-בלבד באחרים, יחד עם עיבוד-קוגניטיבי של מה-שקרה-להם, מספיקה.","mnemo":"👧➡️👶 אח קטן לומד מטעויות האחות הגדולה - בלי לחזור על הטעות בעצמו."},{"id":"prof5_44","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהם התנאים המשפרים למידה ממודלים התנהגותיים?","a":"(1) ההתנהגות נראית כמקבלת חיזוק. (2) המודל נתפס בחיוב (אהדה/כבוד). (3) דמיון בין המודל לצופה. (4) הצופה מתוגמל על תשומת לב למודל. (5) ההתנהגות גלויה ובולטת. (6) החיקוי בטווח יכולת הצופה.","explain":"ששה תנאים המשפיעים על עד-כמה סביר שנחקה בהצלחה התנהגות שראינו במודל - כל אחד מהם משפיע בכיוון עצמאי: <b>(1) ההתנהגות נראית כמקבלת חיזוק</b> - אם ראינו שההתנהגות 'עבדה' עבור המודל, סביר יותר שנחקה אותה. <b>(2) המודל נתפס בחיוב</b> - אהדה/כבוד כלפי המודל מגבירים את הסיכוי לחיקוי (למה שאנחנו מעריצים, אנחנו רוצים להידמות). <b>(3) דמיון בין המודל לצופה</b> - ככל שהמודל 'דומה יותר' לנו (גיל, מגדר, מצב), כך אנו מרגישים שההתנהגות 'רלוונטית' גם לנו. <b>(4) הצופה מתוגמל על תשומת-לב למודל</b> - אם מישהו מעודד/מתגמל אותנו על-כך שאנחנו שמים-לב למודל, נלמד ממנו יותר. <b>(5) ההתנהגות גלויה ובולטת</b> - קל יותר לחקות משהו שרואים בבירור מאשר משהו סמוי/מעורפל. <b>(6) החיקוי בטווח יכולת-הצופה</b> - אם ההתנהגות מורכבת מדי או דורשת יכולות שאין לצופה, הוא לא יוכל לחקות אותה בהצלחה, גם עם המוטיבציה הגבוהה ביותר.","mnemo":"⭐ 6 תנאים למודל טוב: מתוגמל, מוערך, דומה-לי, אני-מתוגמל-על-קשב, בולט, בטווח-היכולת-שלי."},{"id":"prof5_45","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"אילו מסקנות עולות ממחקרי השפעת הטלוויזיה על התנהגות ילדים/מתבגרים?","a":"צפייה בילדות בתכנים אלימים מנבאת תוקפנות רבה יותר בבגרות (לא להפך - קשר הפוך רופף בלבד). 3 השפעות שליליות: הגברת תוקפנות, הערכת־יתר של אלימות בעולם האמיתי, הקהיה רגשית. גם למידה פרו־חברתית אפשרית מתכנים חיוביים.","explain":"מחקרי-הטלוויזיה נחשבים בין המחקרים החברתיים-ארוכי-הטווח החשובים ביותר, כי הם עוקבים אחרי ילדים <b>עשרות שנים</b> ובודקים כיוון-סיבתי מדויק: הממצא המרכזי - <b>צפייה בילדות</b> בתכנים-אלימים <b>מנבאת</b> תוקפנות-רבה-יותר <b>בבגרות</b> - הכיוון-ההפוך (אנשים-תוקפניים-מלכתחילה בוחרים לצפות באלימות) קיים גם הוא, אך הוא <b>קשר רופף יותר</b> מהכיוון הראשון. <b>שלוש השפעות-שליליות עיקריות</b> שזוהו: <b>הגברת-תוקפנות</b> (חיקוי ישיר של דגמי-אלימות שנצפו), <b>הערכת-יתר של שכיחות-האלימות</b> בעולם-האמיתי (תפיסה מעוותת שהעולם מסוכן יותר משהוא באמת), ו<b>הקהיה רגשית</b> (חשיפה חוזרת מפחיתה את התגובה-הרגשית-הטבעית לאלימות). ⚠️ נקודה מאוזנת חשובה: הממצאים <b>לא חד-כיווניים בהכרח</b> - <b>למידה פרו-חברתית</b> (התנהגות-חיובית, אמפתיה, עזרה) אפשרית באותה מידה מתכנים-חיוביים, לפי אותו מנגנון-בדיוק של למידה-באמצעות-צפייה.","mnemo":"📺 3 נזקים מטלוויזיה אלימה: יותר תוקפנות, חושבים שהעולם אלים יותר משהוא, הקהיה (כבר לא מזעזע). גם חיובי אפשרי מתוכן חיובי."},{"id":"quiz5_1","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"צעירה מחליקה על הקרח נופלת באימון קפיצה שהיא מבצעת בדרך כלל בנקל. דוגמה ל: (חוק התוצאה / חיזוק שלילי / התניה קלאסית / הבחנה בין למידה לביצוע)","a":"הבחנה בין למידה לביצוע (ידעה לקפוץ, אך משהו הפריע לביצוע בפועל)","explain":"זו הדגמה של <b>ההבחנה בין למידה לביצוע (learning vs. performance)</b> - עיקרון חשוב שלא נדון עדיין במפורש בשאלות הקודמות: הצעירה <b>למדה</b> את הקפיצה היטב (יש לה את הידע/המיומנות - כרגיל היא מבצעת אותה בקלות), אך <b>ביצועה בפועל</b> נכשל הפעם, כי גורם-חיצוני (החלקה על הקרח) הפריע - לא בגלל שהיא 'שכחה' או לא-למדה. ⚠️ ההבחנה קריטית: <b>למידה</b> היא רכישת-ידע/יכולת (משהו פנימי, לא תמיד גלוי-לעין), בעוד <b>ביצוע</b> הוא ההפגנה-בפועל של אותה יכולת ברגע נתון - וגורמים חיצוניים (עייפות, תנאי-סביבה, מזל-רע) יכולים לפגוע-בביצוע גם כשה<b>למידה</b> עצמה שלמה ותקינה.","mnemo":"⛸️ ידעה לקפוץ (למידה קיימת), אבל נפלה עכשיו (ביצוע נכשל) = הבחנה למידה-ביצוע."},{"id":"quiz5_2","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"כאשר מתרחשת התניה קלאסית, הקשר בין הגירוי המותנה לתגובה הבלתי מותנית: (יכול להיעלם אצל אנשים מסוימים / בסופו של דבר יעלם / אף פעם לא נמחק לחלוטין / יש להצמיד את שני הגירויים שוב ושוב כל הזמן)","a":"אף פעם לא נמחק לחלוטין (גם אחרי הכחדה, הקשר עלול \"לשוב\" - החלמה ספונטנית)","explain":"עיקרון-יסוד בהתניה-קלאסית: הקשר שנוצר בין הגירוי-המותנה לתגובה (במקור, לגירוי-הבלתי-מותנה) <b>אף פעם לא נמחק לחלוטין</b>, גם לאחר תהליך-הכחדה 'מוצלח' לכאורה. ⚠️ ההוכחה החזקה ביותר לכך היא תופעת <b>ההחלמה הספונטנית</b> - שנלמדה קודם בפרק: גם אחרי שהתגובה-המותנית נראתה 'נעלמת' לגמרי בעקבות הכחדה, היא <b>שבה ומופיעה</b> (בעוצמה חלשה יותר) לאחר תקופת-מנוחה, גם ללא זיווג-מחדש. זה מוכיח שה'הכחדה' לא באמת מחקה את הזיכרון/הקישור המקורי - היא רק <b>עיכבה</b> אותו, וההיסטוריה-המלאה של הלמידה נותרת שמורה איפשהו, גם אם היא לא באה-לידי-ביטוי כרגע.","mnemo":"👻 הקשר הישן אף פעם לא נמחק לגמרי - תמיד יכול \"לרדוף\" בחזרה (החלמה ספונטנית)."},{"id":"quiz5_3","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"המחקר הראשון בהתניה קלאסית נערך על ידי: (סקינר / ווטסון / פבלוב / תורנדייק / בנדורה)","a":"פבלוב (חקר את תהליך ההתניה הקלאסית אצל כלבים)","explain":"<b>פבלוב</b> ערך את המחקר הראשון והמכונן ביותר בהתניה-קלאסית - כפי שראינו בשאלה מוקדמת יותר בפרק, הוא היה פיזיולוג שחקר עיכול-כלבים, וגילה במקרה שהם מפרישים רוק עוד <b>לפני</b> שהמזון מגיע (למראה העוזר, למשמע צעדיו) - תגלית זו הפכה לבסיס לתיאוריית-ההתניה-הקלאסית כולה. ⚠️ הבדילו מהשמות-האחרים: <b>סקינר</b> ו<b>תורנדייק</b> קשורים להתניה-<b>אופרנטית</b> (חוק-התוצאה, קופסת סקינר); <b>ווטסון</b> יישם את עקרונות-פבלוב על בני-אדם (ניסוי אלברט-הקטן), אך לא היה הראשון לחקור את התהליך-עצמו; <b>בנדורה</b> קשור ללמידה-חברתית/למידה-באמצעות-צפייה, לא להתניה-קלאסית כלל.","mnemo":"🐕💧 פבלוב = הכלב-המריר, הראשון."},{"id":"quiz5_4","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"בניסויי פבלוב, ________ שימש/ה כגירוי הבלתי־מותנה: (מראה הנסיין / ריור / צליל / אבקת אוכל)","a":"אבקת אוכל (הגירוי הטבעי שכבר גרם לריור ללא למידה)","explain":"<b>אבקת-האוכל</b> היא הגירוי-הבלתי-מותנה (UCS) בניסוי-פבלוב-הקלאסי, כי היא מעוררת <b>תגובה טבעית ואוטומטית</b> (ריור) <b>ללא כל צורך בלמידה מוקדמת</b> - כלב יריר למראה/ריח מזון גם ללא שום תהליך-התניה קודם. ⚠️ אל תתבלבלו: הצליל/פעמון הוא הגירוי-<b>המותנה</b> (הניטרלי בהתחלה, שהופך למעורר-תגובה <b>רק אחרי</b> זיווג-חוזר עם המזון) - זה בדיוק ההיפך התפקודי מהגירוי-הבלתי-מותנה, וזו הסיבה שהשאלה הבאה שואלת ספציפית על תפקיד-הצלצול.","mnemo":"🍖 אבקת-אוכל = מגיע-בטבעיות = בלתי-מותנה."},{"id":"quiz5_5","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"בניסוי הקלאסי של פבלוב הגירוי המותנה היה ה______: (הכלב / המזון / צלצול / פבלוב עצמו)","a":"צלצול (הגירוי הניטרלי שהפך \"ללמד\" את התגובה)","explain":"<b>הצלצול</b> (או הפעמון, בגרסאות שונות של הניסוי) הוא הגירוי-<b>המותנה</b> (CS) - בהתחלה, הוא היה גירוי-ניטרלי-לחלוטין, שלא עורר שום תגובה מיוחדת מהכלב. רק <b>לאחר</b> זיווג-חוזר עם המזון (הגירוי-הבלתי-מותנה), הצלצול 'למד' לעורר תגובת-ריור בעצמו - וכך הפך למותנה. ⚠️ המילה 'הפך ללמד' בהגדרת-השאלה היא הרמז המדויק: רק גירוי ש<b>עבר תהליך-למידה</b> (זיווג) כדי להשיג את כוחו-לעורר-תגובה נחשב 'מותנה' - בניגוד לגירוי-הבלתי-מותנה (המזון), שתמיד עורר תגובה, גם ללא כל למידה.","mnemo":"🔔 צלצול = היה-ניטרלי-ולמד = מותנה."},{"id":"quiz5_6","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"בסלידה נלמדת מטעם, טעם חדש משמש לעיתים קרובות כ: (תגובה מותנית / גירוי מותנה / תגובה בלתי־מותנית / גירוי בלתי־מותנה)","a":"גירוי מותנה (הטעם החדש נקשר לתחושת החולי)","explain":"בסלידה-נלמדת-מטעם, הטעם-החדש הוא הגירוי-<b>המותנה</b> (CS): הוא היה בהתחלה ניטרלי-לחלוטין (סתם טעם, בלי כל משמעות שלילית), אך לאחר שזווג (אפילו פעם אחת בלבד, כפי שראינו) עם תחושת-מחלה, הוא 'למד' לעורר תגובת-סלידה בעצמו. ⚠️ אל תתבלבלו עם 'גירוי-בלתי-מותנה' - זה יהיה תפקידה של <b>המחלה עצמה</b> (או הגורם שגרם לה), שמעוררת בחילה <b>באופן טבעי ואוטומטי</b>, ללא כל תלות-בלמידה - הטעם רק 'רוכש' משמעות-שלילית <b>דרך</b> הקישור למחלה, לא באופן-מולד.","mnemo":"🌭 טעם-חדש \"למד\" להזהיר ממחלה = גירוי-מותנה (לא בלתי-מותנה, כי לא היה מולד)."},{"id":"quiz5_7","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"אחרי הרגשת מחלה מנקניקייה, כדי להכחיד את הסלידה עליכם: (לאכול מאכלים אחרים שיגרמו לכם להרגיש רע / לאכול עוד נקניקיות / להשתמש בנקניקיות כתגמול / לקשר את הנקניקייה למאכלים שאתם אוהבים)","a":"לאכול עוד נקניקיות (חשיפה חוזרת ללא הגירוי הבלתי-מותנה מכחידה את הסלידה)","explain":"כדי <b>להכחיד</b> את הסלידה (לא לשמר אותה), נדרש בדיוק העיקרון-הכללי של הכחדה: <b>לחשוף מחדש</b> לגירוי-המותנה (הנקניקייה) <b>ללא</b> שהגירוי-הבלתי-מותנה (המחלה) חוזר בפועל - כלומר, <b>לאכול עוד נקניקיות</b>, כשהפעם הן לא-גורמות-לחולי, כדי 'ללמד מחדש' שהקישור-בין-הנקניקייה-למחלה כבר לא-תקף. ⚠️ שימו לב שזה בדיוק העיקרון-ההפוך מ'הימנעות מהטעם' - אינטואיטיבית אפשר לחשוב שכדי 'להיפטר' מהסלידה צריך להתרחק מהמאכל, אבל ההפך הוא הנכון: רק חשיפה-חוזרת-ובטוחה (בלי חוזרת-המחלה) יכולה להכחיד את הקישור השלילי שכבר נוצר.","mnemo":"🌭🌭 עוד ועוד נקניקיות בלי לחלות = מכחידים את הסלידה."},{"id":"quiz5_8","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"כלב שכנים נובח על עופר בן שש. עם הזמן עופר מפחד מכל כלב. דוגמה ל: (הבחנה בין גירויים / הכללת גירויים / התניה לאחור / החלמה ספונטנית)","a":"הכללת גירויים (הפחד עבר מכלב אחד לכל הכלבים)","explain":"<b>הכללת-גירויים</b> היא ההסבר המדויק: הפחד שנוצר מ<b>כלב-ספציפי-אחד</b> (השכנים) שנבח על עופר, <b>התפשט אוטומטית</b> לכל כלבים-אחרים - גם כאלה שעופר מעולם לא נפגש-איתם ושמעולם לא נבחו עליו. זו בדיוק ההגדרה: הרחבה-אוטומטית-לא-מכוונת של תגובה-מותנית לגירויים <b>הדומים</b> לגירוי-המותנה-המקורי. ⚠️ אל תתבלבלו עם 'הבחנה-בין-גירויים' - זה יהיה ההפך: אילו עופר היה מפחד <b>רק</b> מהכלב-הספציפי-שנבח-עליו, ולא מכלבים-אחרים-דומים, זו הייתה הבחנה, לא הכללה.","mnemo":"🐕➡️🐕‍🦺 כלב-אחד → כל-הכלבים = הכללה (התפשטות)."},{"id":"quiz5_9","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"כלב מרייר לצליל ביום א', אך לא ביום ג'. ביום ב' עבר תהליך של: (התרגלות / רכישה / רגישות יתר / הכחדה)","a":"הכחדה (הגירוי המותנה הוצג ללא הבלתי-מותנה, התגובה נחלשה)","explain":"כשהגירוי-המותנה (הצליל) מוצג <b>ללא</b> הגירוי-הבלתי-מותנה שוב-ושוב (ביום ב', הכלב לא מקבל את מה-שבדרך-כלל בא ביחד עם הצליל), התגובה-המותנית נחלשת בהדרגה - זהו בדיוק תהליך <b>ההכחדה</b>. ⚠️ אל תתבלבלו עם 'התרגלות' - זה מונח נפרד לגמרי (ירידה-בתגובתיות לגירוי-חוזר-בודד, ללא תהליך-התניה-קודם כלל), שינוי שקורה גם בלי קשר-מלכתחילה בין שני-גירויים; כאן, לעומת-זאת, <b>יש כבר</b> קישור-נלמד-קודם (הכלב כבר הריר לצליל ביום א'), וההיעדר-החוזר-של-החיזוק הוא זה שגורם להיחלשות - זהו סימן-ההיכר של הכחדה, לא התרגלות.","mnemo":"🔇 יום ב' = שקט (לא רכישה, לא הכחדה בעצם השם) - זה תהליך הכחדה בדרך."},{"id":"quiz5_10","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"בתהליך הרכישה בהתניה קלאסית קיים זיווג בין: (גירוי בלתי מותנה ותגובה בלתי מותנית / גירוי מותנה ותגובה מותנה / גירוי מותנה ובלתי מותנה / חיזוק ותגובה)","a":"גירוי מותנה ובלתי מותנה (הזיווג ביניהם יוצר את הלמידה)","explain":"שלב <b>הרכישה</b> (acquisition) בהתניה-הקלאסית מבוסס על <b>זיווג בין הגירוי-המותנה לגירוי-הבלתי-מותנה</b> - זהו שלב-הבנייה-בפועל של הקישור: הצגת שני-הגירויים יחד, שוב ושוב, עד שהמותנה 'רוכש' את הכוח לעורר-תגובה בעצמו. ⚠️ אל תתבלבלו עם 'גירוי-מותנה+תגובה-מותנה' - זה כבר <b>תוצר סופי</b> של תהליך-הרכישה, לא התהליך-עצמו; ה'זיווג' שקורה בשלב-הרכישה הוא <b>בין שני הגירויים</b> (מותנה ובלתי-מותנה) - לא בין גירוי לתגובה.","mnemo":"🔗 רכישה = הזיווג בין מותנה לבלתי-מותנה, נקודה."},{"id":"quiz5_11","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"עמיר רוצה שאור יהיה גירוי מותנה והלם חשמלי גירוי בלתי־מותנה. על האור: (להיות בקשר חוסם עם ההלם / להופיע לאחר ההלם / לנבא בצורה מהימנה את ההלם / להיות בסמיכות זמנית להלם)","a":"לנבא בצורה מהימנה את ההלם (על הגירוי המותנה לספק מידע אמין על מה שיבוא)","explain":"הממצא של רסקורלה (שנלמד קודם בפרק) הוא בדיוק התשובה כאן: לא מספיק שהאור יופיע <b>בסמיכות-זמנית</b> להלם (זו הייתה הנחת-פבלוב הפשוטה יותר) - נדרש שהאור <b>ינבא באופן מהימן ועקבי</b> את בוא-ההלם - כלומר, שכל-פעם (או כמעט-כל-פעם) שהאור מופיע, ההלם אכן מגיע בעקבותיו, ולא באקראי. ⚠️ אם ההלם מגיע גם-בלי-האור לפעמים (כמו קבוצת-'מקרית' בניסוי רסקורלה), האור לא-ילמד להיות גירוי-מותנה-אפקטיבי, גם אם הוא-עצמו קרוב-בזמן להלם באותם המקרים שהם כן מופיעים יחד.","mnemo":"🔮 חייב-לנבא, לא רק להיות-קרוב-בזמן."},{"id":"quiz5_12","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"גילה עברה לגור בעיר לפני שישה חודשים; כיום היא לא שומעת את הרעש. תופעה זו: (התרגלות / רגישות יתר / עקביות / התניה קלאסית)","a":"התרגלות (חשיפה ממושכת מפחיתה תגובה לגירוי קבוע)","explain":"אי-השמת-הלב לרעש-העיר לאחר תקופת-הסתגלות (חצי-שנה) היא דוגמה קלאסית ל<b>התרגלות</b>: ירידה הדרגתית בתגובתיות למערכת-חושית כלפי גירוי <b>קבוע וממושך</b> - הרעש עצמו לא השתנה, אך המערכת-החושית/הקשבית 'למדה' שהוא לא-רלוונטי ומפסיקה להגיב אליו במלוא-העוצמה. ⚠️ אל תתבלבלו עם 'התניה-קלאסית' - כאן <b>אין</b> קישור בין שני-גירויים-שונים (אין גירוי-מותנה שנוצר כתוצאה מזיווג) - זו פשוט ירידה-ישירה-ופשוטה ברגישות לגירוי-חוזר-בודד, ללא תהליך-התניה מסובך יותר.","mnemo":"🏙️🔇 עיר-רועשת → אחרי-חצי-שנה → לא-שומעת = התרגלות."},{"id":"quiz5_13","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"זוהר ראתה את אחותה נופלת מהאופניים ונפצעת. מאז היא נזהרת. דוגמה ל: (למידה באמצעות צפייה / התניה קלאסית / רגישות יתר / הכחדה אופרנטית)","a":"למידה באמצעות צפייה (למדה בלי חוויה ישירה, רק מלהתבונן באחר)","explain":"זוהר <b>לא חוותה</b> את הנפילה בעצמה - היא רק <b>צפתה</b> באחותה נופלת ונפצעת, ולמדה מכך להיזהר. זו בדיוק ההגדרה של <b>למידה-באמצעות-צפייה</b> (חלק מהלמידה-החברתית של בנדורה): רכישת התנהגות/זהירות דרך תצפית בתוצאות-שקיבל-אדם-אחר, ללא חוויה-ישירה-אישית. ⚠️ אל תתבלבלו עם 'התניה-קלאסית' - שם היה צריך שזוהר-עצמה תחווה זיווג בין גירוי-ניטרלי לגירוי-בלתי-מותנה (למשל, שהיא-עצמה תיפול); כאן, לעומת-זאת, כל-הלמידה קרתה <b>דרך התצפית באחר בלבד</b>.","mnemo":"🚴💥 רואה אחות נופלת, לא נופלת בעצמה, ולומדת = צפייה (בלי חוויה אישית)."},{"id":"quiz5_14","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"איזה משפט משקף באופן מיטבי את המחקר בן זמננו (על הכאה מתונה)? (החוקרים אינם יודעים מהי השפעתה של הכאה מתונה על ילדים / החוקרים אינם יכולים להעריך את עוצמתו של עונש גופני / חוקרים הראו שהכאה מתונה מביאה לתוצאות שליליות / חוקרים הראו שהכאה מתונה מביאה לתוצאות חיוביות)","a":"החוקרים אינם יודעים מהי השפעתה של הכאה מתונה על ילדים (התחום עדיין שנוי במחלוקת מחקרית)","explain":"התשובה הנכונה משקפת עמדה-מדעית-זהירה חשובה: המחקר-העדכני על השפעת הכאה-מתונה (עונש-גופני-קל) על ילדים <b>עדיין שנוי-במחלוקת</b>, וחוקרים <b>אינם יודעים בוודאות</b> את מלוא-ההשפעה שלה. ⚠️ זו לא 'חוסר-ידע כללי' - הקושי-המתודולוגי המרכזי: קשה מאוד להפריד, במחקר-מתאמי (לא-ניתן לביצוע כניסוי-אתי), בין <b>השפעת-ההכאה-עצמה</b> לבין גורמים-נלווים (כמו רמת-הלחץ-הכללית במשפחה, סגנון-ההורות-הרחב-יותר, או גורמים-סוציו-אקונומיים) שיכולים להסביר את התוצאות באותה מידה. ⚠️ אל תתבלבלו עם התשובות הקיצוניות ('תוצאות שליליות מובהקות' או 'תוצאות חיוביות') - אלו טוענות לוודאות-מדעית שהמחקר-בפועל, נכון-להיום, עדיין לא סיפק; זו בדיוק הסיבה שהתשובה-הנכונה מדגישה את חוסר-הידיעה-הוודאית, לא מסקנה חד-משמעית לכיוון כלשהו.","mnemo":"❓ עדיין-לא-ברור-במחקר = תשובת-הזהירות המדעית (לא חיובי, לא שלילי, פשוט לא-ידוע)."},{"id":"quiz5_15","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"דביבונים שפשפו מטבעות זה בזה במקום להפקידם בקופה. דוגמה ל: (הכחדה אופרנטית / עיצוב על ידי קירוב הדרגתי / סחף אינסטינקטיבי / מחזקים מותנים)","a":"סחף אינסטינקטיבי (התנהגות טבעית \"גוברת\" על ההתנהגות הנלמדת עם הזמן)","explain":"התנהגות הדביבונים המשפשפים מטבעות (במקום להפקידם, כפי שאומנו) היא דוגמה מדויקת ל<b>סחף אינסטינקטיבי</b> - שנלמד קודם בפרק: התנהגות-אופרנטית שנלמדה (הפקדת-מטבעות) 'נסחפת' עם הזמן לעבר התנהגות-מולדת-אינסטינקטיבית אופיינית-למין (שפשוף-מזון) - כלומר, ההתנהגות-הטבעית-והמולדת 'גוברת' על ההתנהגות-הנלמדת ככל שחולף הזמן. ⚠️ אל תתבלבלו עם 'הכחדה-אופרנטית' - שם ההתנהגות פשוט <b>נעלמת</b> בהיעדר-חיזוק; כאן ההתנהגות <b>לא נעלמת</b> - היא רק 'מתעוותת' לכיוון-אינסטינקטיבי-אחר, גם כשהחיזוק ממשיך.","mnemo":"🦝🪙 שוב הדביבון שמשפשף מטבעות - האינסטינקט חזר וניצח."},{"id":"quiz5_16","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"חוקר חסיד סקינר - לא תצפו שמחקרו יתמקד ב: (קשרים בין התנהגויות לתגמולים / גירויים סביבתיים הגורמים להתנהגויות / מצבים פנימיים כסיבות להתנהגות / צורות למידה שהשתמרו בכל המינים)","a":"מצבים פנימיים כסיבות להתנהגות (סקינר מתמקד רק בגורמים חיצוניים נצפים)","explain":"חוקר חסיד-סקינר, כביהביוריסט קלאסי, <b>לא</b> יתמקד ב<b>מצבים פנימיים כסיבות להתנהגות</b> - סקינר דחה (בדיוק כמו ווטסון) כל הסתמכות על תהליכים-מנטליים-פנימיים בלתי-נצפים (מחשבות, רגשות, כוונות) כהסבר-מדעי להתנהגות. הוא התמקד <b>אך-ורק</b> בגורמים <b>חיצוניים ונצפים</b>: קשרים בין תגובות לתגמולים (חיזוק/עונש), גירויים-סביבתיים, ועקרונות-למידה אוניברסליים שחלים על כל המינים. ⚠️ שלושת-האפשרויות-האחרות (קשרים תגובה-תגמול, גירויים-סביבתיים, צורות-למידה-משותפות-לכל-המינים) הן בדיוק מה-שכן מאפיין את המחקר הביהביוריסטי-הטהור - רק ה'מצבים-פנימיים' סותרים את הפילוסופיה הבסיסית של הגישה.","mnemo":"📹 מצלמת-האבטחה (ביהביוריזם) - רק חוץ, אף פעם לא \"בפנים הראש\"."},{"id":"quiz5_17","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"נועה אסורה לצפות בטלוויזיה 3 ימים; אוכלת כרוב ניצנים כדי לקבל אישור לצפייה. ההורים מכירים את: (תיאוריית החיזוק המותנה / הכחדה אופרנטית / תיאוריית מניעת־תגובה / כלכלת אסימונים)","a":"תיאוריית מניעת־תגובה (התנהגות חלופית מונעת ביצוע ההתנהגות האסורה)","explain":"<b>תיאוריית מניעת-תגובה</b> מסבירה מדוע נועה מוכנה לאכול כרוב-ניצנים (שאולי לא-אהוב עליה) כדי לקבל אישור-לצפייה: ההורים יצרו מצב שבו התנהגות-חלופית (אכילת ירק) <b>מונעת</b> את ביצוע-ההתנהגות-האסורה (צפייה-בטלוויזיה-אסורה) - כלומר, כדי לגשת לדבר-הרצוי (טלוויזיה), נועה חייבת לעבור-דרך פעולה-מסוימת שההורים דרשו. ⚠️ אל תתבלבלו עם 'כלכלת-אסימונים' - שם התגמול ניתן ב<b>אסימונים-מצטברים-ניתנים-להמרה</b>, לא בהרשאה-חד-פעמית-ישירה כמו כאן; המבנה-המושגי כאן שונה: ההתנהגות-הרצויה (אכילת-הכרוב) היא-עצמה 'המחיר' שמונע-גישה-להתנהגות-האסורה, לא צבירת-נקודות למימוש עתידי.","mnemo":"🥦📺 כרוב תמורת טלוויזיה - ההתנהגות-הפחות-רצויה \"תופסת מקום\" של האסורה (מניעת-תגובה)."},{"id":"quiz5_18","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"מקום העבודה משלם 10 ש\"ח על כל 20 תפוחים שמבריקים. מדובר ב: (עונש שלילי / חיזוק שלילי / חיזוק חיובי / עונש חיובי)","a":"חיזוק חיובי (הוספת גירוי נעים [כסף] מגבירה התנהגות)","explain":"חיזוק חיובי — כאשר בעקבות התנהגות ניתן חיזוק נעים (גירוי אפטיטיבי מתווסף). דוגמה: חולדת מחמד מסתובבת במעגלים אם בעקבות זה מקבלת מזון אהוב. חיזוק שלילי — כאשר התנהגות מלווה בהסרת גירוי לא נעים (אברסיבי). דוגמה: אדם המתעב תות־שדה יתנהג באופן שיאפשר לו לחדול מלאכול תות. שני סוגי החיזוקים מעלים את הסבירות להתרחשות התגובה — ההבדל הוא רק בכיוון: חיובי=הוספת נעים; שלילי=הסרת לא־נעים.","mnemo":"💵➕ כסף מתווסף על תפוחים מוברקים = חיזוק חיובי."},{"id":"quiz5_19","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"איזה מהמושגים אינו מרכיב בתלות המשולשת? (תוצאות גירוי / גירוי מבחין / הכחדה אופרנטית / תגובה מופקת)","a":"הכחדה אופרנטית (זו תוצאה של אי-חיזוק, לא חלק מהתלות המשולשת עצמה)","explain":"<b>התלות-המשולשת</b> (שנלמדה בפרק) מורכבת משלושה רכיבים בלבד: <b>גירוי-מבחין</b> (מה מאותת שהתגובה תגרור השלכה), <b>תגובה</b> (מה האורגניזם עושה), ו<b>תוצאות-הגירוי</b> (מה קורה בעקבות התגובה - חיזוק/עונש). ⚠️ <b>הכחדה-אופרנטית</b> <b>אינה</b> חלק ממבנה-התלות-המשולשת עצמו - היא תהליך-נפרד (מה-שקורה כשמפסיקים לתת תוצאה/חיזוק לתגובה שבעבר-כן-חוזקה), לא אחד משלושת-הרכיבים-שמרכיבים-את-המבנה-הבסיסי של ניתוח-כל-התנהגות-אופרנטית.","mnemo":"3️⃣ תלות-משולשת = 3 בלבד: גירוי-מבחין+תגובה+תוצאה. הכחדה היא לא חלק מהמשולש, היא מה שקורה בלעדיו."},{"id":"quiz5_20","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"ניתן להגדיר למידה כ: (שינוי לאורך זמן בהתנהגות המבוסס על התנסות / כל שינוי בהתנהגות / הבנה על כך שנרכש ידע חדש / תחושה פנימית לגבי תפעול גירויים)","a":"שינוי לאורך זמן בהתנהגות המבוסס על התנסות (הגדרת הלמידה - לא כל שינוי, רק זה המבוסס נסיון)","explain":"ההגדרה המדויקת של למידה, כפי שנלמדה בתחילת הפרק, כוללת שלושה מרכיבים ספציפיים - חשוב לזהות שה'שינוי' לבדו <b>לא מספיק</b>: זהו <b>שינוי לאורך-זמן</b> (יחסית-קבוע, לא רגעי) <b>בהתנהגות</b> (או בפוטנציאל-להתנהגות) <b>המבוסס-על-התנסות</b>. ⚠️ אפשרויות מסיחות: 'כל שינוי בהתנהגות' - חסר את דרישת-ה'התנסות' וה'יחסית-קבוע' (למשל, שינוי מעייפות לא-נחשב למידה); 'הבנה שנרכש ידע' - מתאר רק היבט-אחד (מודעות), לא בהכרח את מלוא-ההגדרה שכוללת שינוי-בפוטנציאל-להתנהגות; 'תחושה פנימית' - לא נוגע כלל למרכיב-ההתנסות-וה-יציבות שהם ליבת-ההגדרה.","mnemo":"🔧 שדרוג-קבוע-מהתנסות - לא כל שינוי נחשב למידה."},{"id":"quiz5_21","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"אימו של רון לא מרוצה מהאופן שהוא מדבר אליה, ומחליטה לא לאפשר לו לשחק בצעצוע האהוב עליו למשך יום. דוגמה ל: (עונש חיובי / חיזוק חיובי / חיזוק שלילי / עונש שלילי)","a":"עונש שלילי (הסרת דבר נעים [צעצוע] כדי להפחית התנהגות)","explain":"אם רון-לא-מקבל-אישור-לשחק-בצעצוע-האהוב (הסרת גירוי-נעים) בעקבות התנהגותו (דיבור-לא-נעים לאמו), במטרה <b>להפחית</b> את ההתנהגות-הזו - זו בדיוק ההגדרה של <b>עונש שלילי</b>: הסרת גירוי-נעים אחרי-התגובה, שמטרתה הקטנת-הסתברות-החזרה. ⚠️ זכרו את הכלל: 'שלילי' = <b>הסרה</b> (לא 'רע'), ו'עונש' = <b>מפחית</b> (לא 'חיזוק') - שני צירים בלתי-תלויים. כאן יש הסרה (שלילי) של דבר-נעים, שמטרתה הפחתה (עונש) - שילוב שנותן בדיוק 'עונש שלילי'.","mnemo":"🧸➖ לוקחים-את-הצעצוע (מסירים נעים) = עונש שלילי."},{"id":"quiz5_22","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"איזה מהבאים אינו מחזק מותנה? (פרס / קידום / תשומת לב / הפחתת כאב)","a":"הפחתת כאב (זהו חיזוק שלילי מולד, לא מחוזק נלמד)","explain":"<b>הפחתת כאב</b> אינה מחזק-מותנה - היא דווקא <b>חיזוק שלילי מולד</b>: הסרת-כאב (גירוי-לא-נעים-טבעי) מחזקת התנהגות באופן <b>ביולוגי-מולד</b> (למשל, לקיחת-משכך-כאבים), בלי צורך בכל למידה-מוקדמת - כאב הוא בעצמו גירוי-לא-נעים-מיסודו, לא נלמד. ⚠️ לעומת-זאת, <b>פרס, קידום, ותשומת-לב</b> - שלושתם מחזקים-מותנים אמיתיים: הם היו-ניטרליים-במקור (לא-משמעותיים כשלעצמם) ורכשו ערך-חיזוקי דרך למידה חברתית/תרבותית (קידום=כסף+יוקרה, תשומת-לב=אישור חברתי), לא ביולוגית-מולדת כמו הקלת-כאב.","mnemo":"🩹 הפחתת-כאב = מולד-ביולוגית (לא נלמד) = לא מחזק מותנה."},{"id":"quiz5_23","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"השימוש באסימונים קשור ל: (הכחדה / הצפה / חיזוק מיידי / שינוי התנהגות)","a":"שינוי התנהגות (זו המטרה הכללית של שיטת האסימונים)","explain":"כלכלת-אסימונים היא <b>שיטה כללית לשינוי-התנהגות</b> - זו המטרה-הרחבה שלשמה כל המנגנון קיים: משתמשים באסימונים (מחזק-מותנה) כדי לעצב, לחזק, ולשנות דפוסי-התנהגות לאורך-זמן (למשל, בבתי-חולים-פסיכיאטריים או תוכניות-גמילה). ⚠️ אל תתבלבלו עם 'חיזוק-מיידי' - למרות שהאסימון-עצמו ניתן מייד אחרי ההתנהגות (יתרון מעשי), זה רק <b>מנגנון-פרטי</b> בתוך המטרה-הכללית-הרחבה-יותר של שינוי-התנהגות מתמשך.","mnemo":"🎯 אסימונים = כלי, המטרה הסופית תמיד שינוי-התנהגות."},{"id":"quiz5_24","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"משכורת חודשית מהווה דוגמה ל: (תוכנית חיזוקים ברווח קבוע / ביחס קבוע / ביחס משתנה / ברווח משתנה)","a":"תוכנית חיזוקים ברווח קבוע (משכורת ניתנת בזמן קבוע, לא לפי ביצועים)","explain":"משכורת-חודשית ניתנת בפרק-זמן <b>קבוע</b> (כל חודש, באותו תאריך בדיוק) - <b>לא</b> בהתאם למספר-פעולות/ביצועים שבוצעו (זה היה הופך אותה ל'יחס'), אלא לפי <b>חלוף-זמן קבוע</b> - זו בדיוק ההגדרה של <b>תוכנית-חיזוקים-ברווח-קבוע</b>. ⚠️ שימו לב שזו דוגמה טובה להבנת ההבדל בין 'יחס' (מבוסס-כמות-פעולות) ל'רווח' (מבוסס-זמן) - משכורת משולמת גם אם עבדת יותר-או-פחות בפועל באותו חודש, כל עוד עבר-הזמן-הנדרש (חודש) - זה מה שהופך אותה לרווח, לא ליחס.","mnemo":"💰📅 משכורת = מגיעה בתאריך קבוע (לא לפי כמות עבודה) = רווח קבוע."},{"id":"quiz5_25","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"מכונות מזל מבוססות בדרך כלל על: (יחס קבוע / יחס משתנה / רווח קבוע / רווח משתנה)","a":"תוכנית חיזוקים ביחס משתנה (מספר לא-צפוי של ניסיונות - יוצר התמדה גבוהה)","explain":"מכונות-מזל מבוססות על <b>יחס-משתנה</b> - מספר-הפעולות (המשיכות-בידית) הנדרש-לזכייה הבאה משתנה בכל פעם סביב ממוצע-ידוע, אך <b>בלתי-צפוי</b> מראש בכל ניסיון-ספציפי. ⚠️ זו בדיוק הסיבה שיחס-משתנה יוצר את <b>ההתמדה-הגבוהה-ביותר וה'התמכרות'</b> מכל ארבע-התוכניות: מכיוון שאי-אפשר לדעת מתי-בדיוק תגיע הזכייה-הבאה, אין 'רגע הגיוני להפסיק' - תמיד ייתכן שהמשיכה הבאה תזכה, מה שמסביר את הכוח הפסיכולוגי העצום של מכונות-הימורים.","mnemo":"🎰 מכונת-מזל = לא-יודעים-מתי (מספר-משתנה) = יחס משתנה."},{"id":"quiz5_26","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"מחקר ווטסון וריינר על אלברט הקטן עסק בהתניה ל: (שמחה / פחד / עצב / גועל)","a":"פחד (ווטסון וריינר יצרו פחד מותנה מעכבר לבן)","explain":"ניסוי אלברט-הקטן של ווטסון וריינר עסק בהתניית <b>פחד</b> - כפי שנלמד קודם בפרק, החוקרים זיווגו חולדה-לבנה (גירוי-ניטרלי) עם רעש-חזק-ומפחיד (גירוי-בלתי-מותנה), עד שהחולדה-לבדה הפכה לעורר פחד-מותנה, שהוכלל לאחר-מכן גם לעצמים-דומים-אחרים. ⚠️ זו הייתה בכוונה בחירה-מדעית-משמעותית: ווטסון רצה להוכיח שרגשות (לא רק תגובות-פיזיולוגיות-פשוטות כמו ריור) יכולים להיווצר דרך התניה-קלאסית, ופחד הוא רגש בסיסי, אינטנסיבי, וקל-להבחין-בו - מה שהפך אותו למועמד-אידיאלי להדגמה.","mnemo":"🐁😱 שוב אלברט הקטן - פחד, לא שמחה/עצב/גועל."},{"id":"quiz5_27","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"אלעד חש בחילה אחרי גבינה מקולקלת; כעת שונא גבינות צהובות. תהליך זה מתאר: (הכחדה / החלמה ספונטנית / התניה קלאסית / התניה רגשית)","a":"התניה קלאסית (טעם ניטרלי נקשר לתחושת חולי)","explain":"טעם-חדש (גבינה-צהובה) שנקשר לתחושת-בחילה (מהגבינה-המקולקלת שנאכלה בעבר), ולכן הפך לגורם-לתגובת-סלידה גם כשהגבינה-בהחלט-תקינה - זו בדיוק ההגדרה של <b>התניה קלאסית</b> (ובאופן מדויק יותר, סלידה-נלמדת-מטעם - תת-סוג ספציפי שלה): טעם-שהיה-ניטרלי-במקור רכש משמעות-שלילית דרך זיווג עם תחושת-מחלה, גם אם הזיווג היה חד-פעמי בלבד. ⚠️ אל תתבלבלו עם 'התניה-רגשית' - זה לא מונח-רשמי-נפרד בפרק, אלא רק תיאור-כללי; הזיהוי-הטכני-המדויק לתופעה זו הוא התניה-קלאסית (סלידה-נלמדת-מטעם).","mnemo":"🧀🤢 גבינה-מקולקלת → שונא-כל-הצהובות = התניה קלאסית (טעם↔חולי)."},{"id":"quiz5_28","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"גל בת 3 הפרידה בין תותים ראויים לרקובים. ניתן לתאר זאת כ: (הבחנה בין גירויים / הכחדה / הכללת הגירוי / חיזוק חלקי)","a":"הבחנה בין גירויים (מבדילה בין שני גירויים דומים, לא מכלילה)","explain":"גל בת-3, המבדילה בין <b>תותים-ראויים לתותים-רקובים</b> - למדה להגיב באופן-שונה לגירויים דומים (שני-סוגי-תותים), כי רק אחד-מהם 'מנבא' תוצאה-רצויה (טעם-טוב) - זו בדיוק ההגדרה של <b>הבחנה-בין-גירויים</b>. ⚠️ אל תתבלבלו עם 'הכללת-הגירוי' - זה יהיה ההפך: אילו גל הייתה מתייחסת לכל התותים (רקובים וטריים גם-יחד) באותה-הדרך, בלי להבחין ביניהם, זו הייתה הכללה, לא הבחנה - כאן, ההיפך הוא הנכון: היא מבדילה בהצלחה בין שני-גירויים-דומים-אך-שונים.","mnemo":"🍓 מבדילה תות-טוב מתות-רקוב = הבחנה (לא מכלילה הכל יחד)."},{"id":"quiz5_29","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"לפי תורנדייק, קיימת סבירות גבוהה שתגובות מסוימות תחזורנה על עצמן אם הן גורמות ל: (תופעות שאינן שליליות או לא רצויות / אפשרות להשיג מידע / סיכון לתגובה שלילית כלשהי / תוצאות משביעות רצון)","a":"תוצאות משביעות רצון ⚠️ (חוק התוצאה של תורנדייק - סעיף לא נקרא במלואו בשיטת פסקה-אחר-פסקה)","explain":"⚠️ חוק-התוצאה של <b>תורנדייק</b> (Law of Effect) - אבן-היסוד ההיסטורית שקדמה לתיאוריית-ההתניה-האופרנטית-המלאה של סקינר: תגובות שגוררות <b>תוצאות משביעות-רצון</b> נוטות להתחזק ולהישנות בעתיד; תגובות שגוררות תוצאות-לא-נעימות נוטות להיחלש. זהו הרעיון הבסיסי-והמקורי-ביותר שממנו התפתח כל מושג-החיזוק המודרני (חיזוק חיובי/שלילי, עונש) שנלמד בהמשך הפרק - תורנדייק ניסח את העיקרון הכללי, וסקינר בהמשך פיתח אותו למערכת-מושגית-מפורטת-ומדויקת-יותר.","mnemo":"😊 חוק-התוצאה = תוצאה-משביעת-רצון מחזקת - זו ההגדרה עצמה, לא צריך לחשוב יותר מדי."},{"id":"prof6_01","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו כל אחד משלושת תהליכי הזיכרון: קידוד, אחסון, שליפה.","a":"קידוד=מכניס פנימה. אחסון=שומר. שליפה=מוציא החוצה.","explain":"שלושת תהליכי-הזיכרון מהווים רצף כרונולוגי-הכרחי, שכל שלב תלוי בקודמו: <b>קידוד (encoding)</b> - הפיכת מידע (מגירוי-חושי, ממחשבה) לייצוג-מנטלי שהמוח יכול לעבד ולשמור - זה 'שער-הכניסה' של המידע לזיכרון. <b>אחסון (storage)</b> - שמירת המידע-המקודד לאורך-זמן, בין רגע-הקידוד לרגע-הצורך-בו-מחדש - זה 'המחסן'. <b>שליפה (retrieval)</b> - הבאת המידע-השמור בחזרה למודעות כשצריך אותו - זה 'שער-היציאה'. ⚠️ ההבנה החשובה: כישלון-זיכרון ('שכחתי') יכול לנבוע מבעיה ב<b>כל אחד</b> מהשלבים בנפרד - ייתכן שהמידע כלל לא קודד כראוי (לא-שמתי-לב), או שהוא אוחסן אך התפוגג עם הזמן, או שהוא עדיין קיים באחסון אך פשוט לא ניתן לשליפה כרגע (חוסר-רמז מתאים) - זה בדיוק ההבדל שבין 'לא-למדתי' ל'ידעתי אבל לא-הצלחתי-להיזכר'.","mnemo":"📥📦📤 פנימה - נשאר - החוצה."},{"id":"prof6_reflection1","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"רוני כהן הוצגה לכם, ולמחרת פגשתם אותה באוטובוס וזיהיתם אותה. כיצד באים לידי ביטוי שלושת תהליכי הזיכרון?","a":"קידוד=הפיכת ההיכרות (שם+פנים) לייצוג מנטלי ברגע ההצגה. אחסון=שמירת המידע מרגע ההיכרות ועד למחרת. שליפה=זיהוי פניה באוטובוס והוצאת השם 'רוני כהן' מהזיכרון.","explain":"יישום שלושת-התהליכים על תרחיש-זיכרון-חברתי מוכר לכולם: <b>קידוד</b> קורה ברגע ההיכרות-הראשונית עצמה - כשמציגים לכם את רוני-כהן, המוח הופך את השילוב 'שם+פנים' לייצוג-מנטלי מקושר. <b>אחסון</b> הוא פרק-הזמן שחלף - מרגע-ההיכרות ועד למחרת, המידע (שם+פנים) נשמר איפשהו במוח, גם בזמן שלא חשבתם עליו כלל. <b>שליפה</b> קורית באוטובוס: זיהוי-הפנים מפעיל תהליך-חיפוש שמוציא בחזרה למודעות את השם 'רוני-כהן' המשויך לאותן פנים. ⚠️ שימו לב שזיהוי-הפנים והוצאת-השם הם שני חלקי-שליפה נפרדים - לפעמים אפשר לזהות פנים ('אני מכיר אותה!') בלי להצליח לשלוף את השם - זו דוגמה טובה לכך ששליפה-של-חלקים-שונים-מאותו-זיכרון יכולה להצליח בקלות-שונה.","mnemo":"👋 אותו רגע: לראות=קידוד, לזכור=אחסון, לזהות=שליפה."},{"id":"prof6_02","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תארו את המטלה בשני הליכי הניסוי של ספרלינג (דיווח מלא ודיווח חלקי).","a":"דיווח מלא=לדווח על כמה שיותר פריטים מכל התצוגה (3 שורות יחד). דיווח חלקי=לדווח רק על שורה אחת, לפי צליל (גבוה/בינוני/נמוך) שהופיע מיד אחרי התצוגה ומציין איזו שורה.","explain":"ניסוי ספרלינג בדק את הזיכרון-האיקוני (הזיכרון-החושי-החזותי, נמשך רק שברירי-שנייה) בעזרת שתי-שיטות-מנוגדות שחשפו יחד תובנה מפתיעה: ב<b>דיווח מלא</b>, המשתתפים התבקשו לדווח על <b>כמה שיותר</b> פריטים מתוך <b>כל</b> התצוגה (למשל, 3 שורות של אותיות שהוצגו יחד לרגע קצרצר) - מטלה קשה, כי צריך לזכור את הכל בו-זמנית. ב<b>דיווח חלקי</b>, מיד לאחר-שהתצוגה נעלמה, הושמע <b>צליל</b> (גבוה/בינוני/נמוך) שסימן <b>איזו שורה ספציפית בלבד</b> יש לדווח עליה - כך המשתתף לא צריך לזכור את הכל, רק שורה-אחת שנבחרה-אקראית-אחרי-ההצגה. ⚠️ הגאונות בשיטה: מכיוון שהמשתתף לא-ידע-מראש איזו שורה תישאל, ההצלחה-בכל-שורה-שנבחרה מעידה שהמידע מ<b>כל</b> השורות היה זמין ברגע ההצגה - לא רק בשורה שבחרו לבסוף לשאול עליה.","mnemo":"🎺 צליל=\"תדווח רק על השורה הזו\"."},{"id":"prof6_03","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד מוכיח מחקר ספרלינג את הקיבולת הגדולה של הזיכרון האיקוני?","a":"בדיווח חלקי, המשתתפים דיווחו נכון על כל שורה שנבחרה, ללא הבדל - מוכיח שכל 12 הפריטים (לא רק חלקם) היו זמינים בזיכרון האיקוני ברגע התצוגה.","explain":"ההוכחה לקיבולת-הגדולה של הזיכרון-האיקוני נשענת על ההיגיון-הסטטיסטי של שיטת-הדיווח-החלקי: מכיוון שהמשתתפים <b>לא-ידעו-מראש</b> איזו שורה (מתוך 3) יישאלו עליה - הצליל שהופיע נבחר <b>אקראית לאחר</b> שהתצוגה כבר נעלמה - וב<b>כל זאת</b> הם דיווחו בהצלחה-שווה על כל שורה שנבחרה, בלי הבדל בין השורות. <b>המסקנה הכרחית</b>: אם היו זוכרים בהצלחה רק שורה מסוימת (למשל, תמיד השורה-הראשונה), זה היה מעיד שרק חלק מהמידע היה זמין. אבל הצלחה-שווה בכל שורה מוכיחה שכל ה-12 הפריטים (לא רק חלקם) היו <b>זמינים בו-זמנית</b> בזיכרון-האיקוני ברגע-התצוגה - הקיבולת הרבה יותר גדולה ממה שנראה כשמנסים לדווח-על-הכל (דיווח-מלא), כי שם המידע פשוט מתפוגג לפני שמספיקים לדווח על הכל.","mnemo":"✅ כל שורה שנבחרה=נכונה = הכל היה שם."},{"id":"prof6_04","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד מוכיח מחקר ספרלינג את העמידות הנמוכה של הזיכרון האיקוני?","a":"בדיווח מלא, נזכרו בפחות פריטים כי המידע התפוגג לפני שהספיקו לדווח על הכול. השהיית הצליל (אות הזיהוי) הראתה ירידה הדרגתית במספר הפריטים הנזכרים ככל שההשהיה גדלה - מוכיח שהמידע נעלם במהירות רבה.","explain":"ההוכחה לעמידות-הנמוכה (ההתפוגגות-המהירה) של הזיכרון-האיקוני מגיעה משני כיוונים משלימים: <b>ראשית</b>, בדיווח-מלא (ניסיון לזכור את כל 12 הפריטים), המשתתפים הצליחו לדווח על <b>פחות</b> פריטים - לא כי המידע לא-היה-שם מלכתחילה (כפי שהוכיח דיווח-חלקי), אלא כי המידע <b>התפוגג</b> לפני שהם הספיקו לדווח על הכול - יש 'מרוץ נגד הזמן' בין המידע-הנעלם לבין קצב-הדיווח. <b>שנית</b> (הוכחה ישירה יותר): כשהחוקרים <b>השהו</b> את הצליל-מסמן-השורה (לא מיד אחרי-התצוגה, אלא אחרי-פרק-זמן שהלך-וגדל), נצפתה <b>ירידה הדרגתית</b> במספר-הפריטים-שדווחו-נכון ככל שההשהיה גדלה - הוכחה ישירה שהמידע נעלם-בפועל, לא רק ש'לא-הספיקו' לדווח עליו - ככל שמחכים יותר, פחות מידע נשאר זמין.","mnemo":"⏳ מחכים=שוכחים - הזמן \"אוכל\" את הזיכרון האיקוני."},{"id":"prof6_05","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מה ההבדל בין זיכרון צילומי לזיכרון איקוני?","a":"איקוני=כולם, חצי-שנייה. צילומי=נדיר (ילדים), נמשך יותר.","explain":"<b>זיכרון איקוני</b> - הזיכרון-החושי-החזותי הרגיל שכולנו חווים כל הזמן (כפי שהודגם בניסוי ספרלינג) - נמשך רק כ<b>חצי-שנייה</b>, ומתפוגג במהירות; זה קורה <b>לכולם</b>, ולא קשור לזיכרון-'מיוחד'. <b>זיכרון צילומי (eidetic memory)</b> - יכולת נדירה-במיוחד (מופיעה בעיקר אצל <b>ילדים</b>, ולעיתים-רחוקות ממש נעלמת בבגרות) של שמירת פרטי-תמונה חזותיים בדיוק-כמעט-מושלם למשך זמן <b>ארוך משמעותית</b> מהזיכרון-האיקוני הרגיל - כמעט כמו 'צילום-מנטלי' שנשאר זמין להסתכלות. ⚠️ ההבדל המרכזי הוא בשני מימדים: <b>שכיחות</b> (איקוני=כולם, צילומי=נדיר-ביותר) ו<b>משך-זמן</b> (איקוני=פחות-משנייה, צילומי=דקות ואף יותר).","mnemo":"📸 איקוני=רגיל+רגע. צילומי=נדיר+ארוך."},{"id":"prof6_06","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו זיכרון לטווח קצר?","a":"לא \"מקום\" - זרקור-קשב זמני על קבוצה קטנה.","explain":"אחת התובנות החשובות ביותר בפרק: <b>זיכרון לטווח-קצר</b> הוא <b>לא</b> 'מקום' פיזי-קבוע במוח שבו מידע 'יושב' - זו טעות-נפוצה בהבנה. במקום זאת, יש לראות אותו כ<b>'זרקור-קשב' זמני ופעיל</b> - חלק קטן-ומוגבל של מידע שנמצא <b>כרגע</b> במוקד-תשומת-הלב המודעת, ומוחזק שם באופן פעיל, אבל רק לזמן-קצר וכמות-מוגבלת. ⚠️ ההבחנה הזו חשובה כי היא מסבירה למה זיכרון-לטווח-קצר כל-כך שביר: זה לא ש'המידע נמחק ממקום-אחסון' - זה שה'זרקור' עצמו <b>מוגבל בקיבולת</b> (כפי שנלמד במספר-הקסם של מילר) ו<b>קצר-בזמן</b> - ברגע שהקשב עובר-הלאה או שהמידע-הנוסף 'דוחק' את הישן, מה-שהיה-ב'זרקור' פשוט נעלם, אלא-אם-כן הועבר-במכוון לזיכרון לטווח-ארוך.","mnemo":"🔦 זרקור-קשב, לא מחסן."},{"id":"prof6_07","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הציגו דוגמה לשימוש שעשיתם בזיכרון לטווח קצר היום.","a":"לדוגמה, זכירת מספר טלפון או קוד לכספומט רק לפרק הזמן הקצר שבין קריאתו לביצוע הפעולה - אם מוסחים, יש לבדוק שוב כי המידע לא נשמר לטווח ארוך.","explain":"שאלה זו מבקשת דוגמה-אישית ליישום זיכרון-לטווח-קצר - חשוב לזהות את המאפיין-המכריע: מידע שמוחזק <b>רק</b> לפרק-הזמן-הקצרצר בין הקבלה לשימוש-בפועל, ו<b>נעלם</b> אם מוסח-הקשב. הדוגמה: זכירת מספר-טלפון או קוד-לכספומט <b>בדיוק</b> לזמן שבין קריאתו לביצוע-החיוג/ההקלדה - אם משהו מסיח את הדעת (למשל, מישהו פונה אלינו) באמצע, המידע לרוב <b>נעלם לחלוטין</b>, וצריך לחזור ולבדוק אותו שוב מהמקור. ⚠️ ההבדל מזיכרון-לטווח-ארוך ברור: אם היינו מתאמצים לחזור-ולחזור (שינון) על הקוד, או לקשר אותו למשהו-משמעותי, הוא היה 'עובר' לזיכרון יציב יותר - אבל בברירת-המחדל, ללא-מאמץ-נוסף, מידע כזה נשאר רק בטווח-הקצר ונעלם מהר.","mnemo":"☎️ קוד-כספומט: זוכר רק עד שמקישים."},{"id":"prof6_08","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי קיבולת הזיכרון לטווח קצר, לפי מספר הקסם של מילר?","a":"מספר-הקסם=7, אך בפועל רק 3-5 בלי עזרה.","explain":"<b>מספר-הקסם</b> של מילר (Miller's Magic Number) - ממצא היסטורי-מפורסם בפסיכולוגיה קוגניטיבית - העריך שהקיבולת של זיכרון-לטווח-קצר עומדת על <b>7</b> (בערך 7±2) פריטי-מידע. ⚠️ <b>אבל</b> - נקודה חשובה שלא-כדאי-לפספס: מחקרים <b>עדכניים יותר</b> מציעים שהמספר-האמיתי הוא נמוך בהרבה - <b>רק 3-5 פריטים</b> כשאין שימוש בטכניקות-עזר (כמו מקבצים/שינון). המספר '7' של מילר עדיין 'תקף' בהקשר מסוים, אבל בעיקר כשמשתמשים באסטרטגיות-ארגון (כמו מקבצים - השאלה הבאה בפרק) שמגדילות את הקיבולת-האפקטיבית - הקיבולת ה'טבעית', ללא-עזרים, נמוכה משמעותית מה'מספר-הקסם' המפורסם.","mnemo":"7️⃣➡️4️⃣ מילר אמר 7, האמת קרוב ל-4."},{"id":"prof6_09","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו את שיטות השינון והארגון במקבצים להגדלת קידוד המידע בזיכרון לטווח קצר.","a":"שינון=חזרה שומרת פעיל. מקבצים=חיבור-פריטים למשמעות אחת.","explain":"שתי אסטרטגיות מרכזיות להגדלת יעילות-הקידוד בזיכרון לטווח-קצר, כל אחת פועלת במנגנון שונה: <b>שינון (rehearsal)</b> - חזרה-חוזרת ('לחזור-על-משהו בראש') על המידע - זה 'שומר אותו פעיל' בזרקור-הקשב, ומונע ממנו להתפוגג, אך <b>לא</b> מגדיל את הקיבולת-הבסיסית עצמה. <b>מקבצים (chunking)</b> - חיבור מספר-פריטים-בודדים ל<b>יחידת-משמעות-אחת</b> (למשל, במקום לזכור 10 ספרות בודדות, לזכור אותן כ-3 'קבוצות' בעלות-משמעות, כמו מספר-טלפון) - זה <b>מגדיל בפועל</b> את כמות-המידע-שאפשר-להחזיק, כי כל 'מקבץ' נחשב כפריט-אחד למרות שהוא מכיל כמה יחידות-קטנות-יותר. ⚠️ ההבדל המהותי: שינון עוזר לשמר מידע-קיים פעיל לאורך-זמן; מקבצים עוזר להכניס יותר-מידע-בכלל לתוך המגבלה-הקבועה של הקיבולת.","mnemo":"🔁➕🧩 חזרה שומרת. קיבוץ מכפיל."},{"id":"prof6_10","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו זיכרון עבודה?","a":"המשאב שמפעיל חשיבה בזמן אמת (לא רק שמירה).","explain":"<b>זיכרון עבודה (working memory)</b> הוא מושג מתקדם ומורכב יותר מ'סתם' זיכרון-לטווח-קצר: הוא <b>המשאב הקוגניטיבי הפעיל</b> שמאפשר לנו <b>לעבד ולתמרן מידע בזמן-אמת</b> - לא רק 'להחזיק' מידע פסיבית, אלא <b>לעבוד איתו</b> תוך-כדי-חשיבה (למשל, לחשב חשבון-בעל-פה, להבין משפט-מורכב תוך-כדי-קריאתו, לתכנן-תגובה תוך-כדי-שיחה). ⚠️ ההבדל התפיסתי החשוב: זיכרון-לטווח-קצר נתפס לרוב כ'מחסן-זמני-פסיבי'; זיכרון-עבודה מדגיש את ה<b>פעילות</b> - זה 'שולחן-העבודה המנטלי' שבו אנחנו-פעילים-מעבדים מידע, לא רק 'מדף' שעליו מונח-משהו לרגע. המודל המוביל לתיאורו (שנלמד בשאלה הבאה) הוא זה של באדלי.","mnemo":"🛠️ שולחן-עבודה פעיל, לא מדף אחסון."},{"id":"prof6_11","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תארו את שלושת מרכיבי זיכרון העבודה (באדלי).","a":"לולאה-פונולוגית=דיבור. לוח-חזותי-מרחבי=תמונות. בקרה-מרכזית=מנהל.","explain":"מודל באדלי מפרק את זיכרון-העבודה לשלושה תת-מרכיבים מובחנים, כל אחד אחראי על סוג-מידע אחר: <b>לולאה פונולוגית (phonological loop)</b> - אחראית על מידע <b>מבוסס-דיבור/צליל</b> (שינון-מילים, מספרים, כל דבר שאפשר 'להגיד לעצמנו בראש'). <b>לוח חזותי-מרחבי (visuospatial sketchpad)</b> - אחראי על מידע <b>חזותי ומרחבי</b> (תמונות, מפות, דמיון-של-אובייקטים-במרחב). <b>בקרה מרכזית (central executive)</b> - 'המנהל' של המערכת-כולה: מקצה-קשב, מתאם בין שני-התת-המרכיבים-האחרים, ומחליט מה-חשוב-לעבד-כרגע. ⚠️ ההוכחה לקיום שני-מסלולים-נפרדים (לולאה ולוח): אפשר לבצע שתי משימות-בו-זמנית בהצלחה יחסית אם אחת מבוססת-דיבור והשנייה מבוססת-חזותי (כי הן משתמשות במשאבים-שונים) - אבל שתי משימות מבוססות-דיבור-גם-יחד יפריעו זו-לזו הרבה יותר, כי הן 'מתחרות' על אותה לולאה-פונולוגית.","mnemo":"🗣️🖼️👔 קול + תמונה + מנהל."},{"id":"prof6_12","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד אפשר לבדוק את הקיבולת של זיכרון עבודה?","a":"מדד טווח זיכרון העבודה: קוראים בקול רם סדרת משפטים, ואז חוזרים על המילה האחרונה בכל משפט. טווח גדול=4+ מילים; טווח קטן=2.5 מילים ומטה.","explain":"השיטה-הניסויית למדידת קיבולת זיכרון-העבודה (בשונה ממדידת זיכרון-לטווח-קצר 'טהור') דורשת <b>עיבוד פעיל</b>, לא רק שינון-פסיבי: <b>מדד טווח זיכרון-העבודה</b> - המשתתף קורא <b>בקול-רם</b> סדרת-משפטים (לא רק רשימת-מילים סתמית - זה מחייב הבנה-משמעותית תוך-כדי-קריאה), ואז מתבקש <b>לחזור</b> על <b>המילה-האחרונה</b> בכל אחד מהמשפטים, לפי הסדר. ⚠️ הקושי המובנה כאן: יש צורך לבצע <b>שני דברים בו-זמנית</b> - להבין-ולעבד את המשפט הנוכחי, <b>וגם</b> לשמור-במקביל את המילים-האחרונות מהמשפטים-הקודמים - זו בדיוק ה'עבודה' האמיתית שמאפיינת זיכרון-עבודה, בניגוד לשינון-פשוט. הנורמות: <b>טווח גדול</b> = 4+ מילים שנזכרות נכון; <b>טווח קטן</b> = 2.5 מילים ומטה - הבדלים אלה מנבאים משמעותית הצלחה-אקדמית ויכולות-חשיבה-מורכבת.","mnemo":"📝 חוזרים על המילה האחרונה בכל משפט."},{"id":"prof6_13","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהם רמזי שליפה וכיצד הם משמשים אותנו?","a":"רמז שליפה = כל גירוי (חיצוני/פנימי) שעוזר לאתר זיכרון. ככל שהרמז מדויק יותר, השליפה קלה יותר.","explain":"<b>רמזי-שליפה (retrieval cues)</b> הם כל גירוי - <b>חיצוני</b> (ריח, מקום, מוזיקה) או <b>פנימי</b> (מצב-רגשי, מחשבה-קשורה) - שמסייע לאתר ולהוציא-החוצה זיכרון ספציפי מהאחסון. <b>העיקרון-המרכזי</b>: ככל שהרמז <b>מדויק וספציפי יותר</b> (קרוב יותר למידע-המקורי-שנקודד יחד-עם-הזיכרון), כך השליפה קלה ומהירה יותר. ⚠️ זה בדיוק העיקרון שממשיך ומתפתח בכל הפרק - עקרון-ייחודיות-הקידוד (שנלמד בהמשך) מסביר <b>למה</b> זה כך: רמז שדומה-יותר לתנאים-שבהם-קודד-המידע-במקור 'מפעיל' טוב-יותר את הקישורים-העצביים שנוצרו ברגע-הקידוד - זו הסיבה שריח מסוים, למשל, יכול 'להחזיר' אותנו בבת-אחת לזיכרון-ילדות שלם.","mnemo":"🔑 רמז-חד פותח מהר."},{"id":"prof6_14","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי היזכרות? הציגו דוגמה.","a":"שחזור מאפס, בלי אפשרויות (עד מתאר חשוד מהזיכרון).","explain":"<b>היזכרות (recall)</b> - שחזור-אקטיבי של מידע <b>מאפס, ללא רשימת-אפשרויות</b> להיעזר-בה - זו הצורה ה<b>קשה יותר</b> של שליפה, כי חייבים 'לייצר' את התשובה-כולה בעצמנו, מהזיכרון בלבד. הדוגמה: עד-ראייה שמתאר-בעצמו את מראה-החשוד למשטרה (בלי תמונות-להצביע-עליהן) - הוא צריך לשחזר את הפרטים (גובה, גיל, לבוש) ישירות-מהזיכרון, מילה-אחר-מילה. ⚠️ מכיוון שאין 'רמז מוכן' שכבר-מכיל-חלק-מהתשובה, היזכרות דורשת שהרמזים-הפנימיים-שיש-לנו (או שאלות-מנחות כלליות) יעוררו את <b>כל</b> המידע לבד - זו הסיבה שהיא לרוב קשה יותר ומדויקת-פחות מהחלופה (היכר), שנלמדת בשאלה הבאה.","mnemo":"🕵️ מאפס, בלי רשימה."},{"id":"prof6_15","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו היכר? הציגו דוגמה.","a":"מזהים מבין אפשרויות (עד מזהה מתמונות).","explain":"<b>היכר (recognition)</b> - זיהוי התשובה-הנכונה <b>מבין מספר-אפשרויות שכבר מוצגות</b> - זו הצורה ה<b>קלה יותר</b> של שליפה, כי לא צריך 'לייצר' את התשובה מאפס - רק לבדוק-ולהשוות מול מה-שכבר-מוצג ולזהות מה מוכר. הדוגמה: עד-ראייה שמתבקש להצביע על החשוד <b>מתוך שורת-זיהוי</b> (מספר תמונות-מוצגות) - הוא לא צריך לתאר את החשוד במילים, רק לזהות אם הוא <b>מזהה</b> אחד מהפרצופים-המוצגים כמתאים לזיכרונו. ⚠️ שאלת-רב-ברירה במבחן היא דוגמה-נוספת מוכרת: התשובה-הנכונה כבר <b>נמצאת בין האפשרויות</b> - צריך רק לזהות אותה, לא לשחזר אותה מאפס.","mnemo":"👉 מצביע מתוך אפשרויות."},{"id":"prof6_16","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו את ההבדל בביצוע בין מטלות היזכרות למטלות היכר, במונחי רמזי שליפה.","a":"היכר קל יותר כי הרמז כבר כולל את התשובה (רק לענות כן/לא). בהיזכרות הרמז חייב לעורר את כל התשובה לבד - קשה יותר.","explain":"ההסבר התיאורטי המדויק להבדל-בקושי בין היזכרות להיכר טמון ב<b>איכות-הרמז</b> שכל שיטה מספקת: ב<b>היכר</b>, הרמז ('האם זו התשובה?') <b>כבר כולל בתוכו את התשובה-האפשרית עצמה</b> - כל מה שנדרש הוא להשוות ולהחליט 'כן/לא' - מטלה קלה יחסית של השוואה. ב<b>היזכרות</b>, לעומת זאת, אין רמז-מוכן שמכיל את התשובה - הרמזים-הזמינים (שאלה כללית, הקשר-כלשהו) חייבים <b>לעורר את כל התשובה בעצמם</b>, מאפס, בלי 'עזרה חיצונית' שכבר-כוללת-את-הפתרון - זו מטלה הרבה יותר תובענית קוגניטיבית. ⚠️ זה בדיוק מסביר תופעה מוכרת: לפעמים 'לא זוכרים' תשובה בשאלה-פתוחה, אך ברגע שרואים אותה ברשימת-אפשרויות ('אה, כן, זו התשובה!') - זה לא סתירה, זה פשוט הבדל-מובנה בקלות-השליפה בין שתי השיטות.","mnemo":"✅❌ קל=לסמן. קשה=לבנות."},{"id":"prof6_17","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"חשבו על זיכרון אפיזודי המשותף לכם ולבני משפחה - איזה מידע ורמז שליפה תספקו?","a":"מידע: תיאור טיול משפחתי ספציפי (למשל, החופשה באילת 2019). רמז: זמן+מקום מדויקים של האירוע - לא עובדה כללית, אלא אפיזודה חד-פעמית.","explain":"יישום-מעשי של ההבחנה בין זיכרון-אפיזודי לזיכרון-סמנטי (שתי צורות-מרכזיות של זיכרון מוצהר/גלוי) - כאן נדרשת דוגמה ל<b>אפיזודי</b>: זיכרון של <b>אירוע-חד-פעמי, קשור לזמן-ומקום-ספציפיים</b> - למשל, טיול-משפחתי מסוים (חופשה-באילת ב-2019, לא 'אילת בכלל'). <b>הרמז המתאים</b> חייב לכלול <b>זמן+מקום מדויקים</b> - לא עובדה-כללית-על-העולם, אלא אפיזודה ספציפית-אחת שקרתה לכם-ולמשפחתכם, וניתן להיזכר-בה כאילו 'חוזרים' לאותו רגע. ⚠️ ההבדל מזיכרון-סמנטי (השאלה הבאה) הוא בדיוק ההקשר-הזמני-מרחבי - אפיזודי 'קשור' לזמן-ומקום-מסוים בחייכם, בעוד סמנטי הוא ידע-כללי שקיים 'בלי-תאריך' מסוים.","mnemo":"📅📍 מתי+איפה=אפיזודי."},{"id":"prof6_18","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"חשבו על זיכרון סמנטי המשותף לכם ולבני משפחה - איזה מידע ורמז שליפה תספקו?","a":"מידע: מתכון משפחתי מסורתי (למשל, עוגת התפוחים של סבתא). רמז: רק שם המתכון עצמו - בלי צורך בזמן/מקום שבו נלמד, כי זה ידע כללי.","explain":"בניגוד לזיכרון-אפיזודי (השאלה הקודמת), <b>זיכרון סמנטי</b> הוא ידע-כללי, עובדתי, ה<b>מנותק מהקשר-הזמן-והמקום</b> שבו נלמד - אתם 'פשוט יודעים' את זה, בלי צורך לזכור מתי-בדיוק למדתם אותו. הדוגמה: מתכון-משפחתי-מסורתי (למשל, עוגת-התפוחים של סבתא) - זו ידע קבוע ויציב, לא אירוע-חד-פעמי. <b>הרמז המתאים</b> הוא <b>רק שם המתכון עצמו</b> - אין צורך בזמן/מקום-ספציפי כדי לשלוף אותו, בניגוד לזיכרון-אפיזודי שדורש הקשר-זמני-מרחבי. ⚠️ טסט-מבחין פשוט: אם אתם יכולים 'לזכור-מתי-למדתם-את-זה', סביר שזה אפיזודי; אם זה 'סתם ידוע לכם, תמיד היה כך', זה סמנטי - גם אם למעשה למדתם אותו ברגע-מסוים-בעבר.","mnemo":"📖 רק-התוכן=סמנטי."},{"id":"prof6_19","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו עקרון ייחודיות הקידוד וכיצד הוא מסביר את הקשר בין קידוד לשליפה?","a":"זיכרונות מתעוררים ביעילות מרבית כשהקשר השליפה תואם את הקשר הקידוד. המידע מקודד יחד עם פרטי ההקשר; שינוי בהקשר (למשל, פגישת מוכר בהקשר לא צפוי) מקשה על השליפה גם אם המידע קיים.","explain":"<b>עקרון ייחודיות-הקידוד (encoding specificity)</b> - עיקרון מרכזי המקשר בין קידוד לשליפה: זיכרונות מתעוררים ביעילות-מרבית כאשר <b>הקשר-השליפה תואם את הקשר-הקידוד</b> - כי המידע לא מקודד 'בריק', אלא <b>יחד-עם</b> פרטי-ההקשר-הסובב (מקום, מצב-רגשי, סביבה חושית) שהיו-נוכחים ברגע-הלמידה. ⚠️ ההשלכה המעשית: שינוי-בהקשר בין רגע-הקידוד לרגע-הניסיון-לשלוף עלול <b>להקשות</b> על השליפה, <b>גם אם המידע עדיין קיים באחסון</b> - הדוגמה הקלאסית: פגישה במורה-שלכם-מהתיכון <b>במכולת</b> (הקשר בלתי-צפוי) עלולה לגרום ל'רגע-מוזר' שבו לא-מזהים-אותו-מיד, למרות שבתוך-הכיתה (ההקשר-המקורי) הזיהוי היה מיידי - העובדה-הרלוונטית (מיהו) לא-נעלמה, רק ההקשר-השונה הקשה על שליפתה.","mnemo":"🧩 קידוד=שליפה - אותו הקשר, זכירה טובה."},{"id":"prof6_20","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד הקשרי הקידוד משפיעים על יכולת הזכירה (לפי המחקרים)?","a":"התאמת הקשר (מים/יבשה, מוזיקה, ריח) משפרת זכירה תמיד.","explain":"ההוכחה-הניסויית לעקרון-ייחודיות-הקידוד מגיעה ממחקרים מגוונים שכולם מראים אותה תבנית: התאמת-ההקשר בין קידוד לשליפה <b>משפרת זכירה באופן עקבי</b> - ולא משנה איזה סוג-הקשר: <b>סביבה פיזית</b> (מים מול יבשה - צוללנים שלמדו מילים מתחת-למים זכרו טוב-יותר <b>כשגם נבחנו מתחת-למים</b>, בהשוואה לנבחנים-על-היבשה), <b>גירויים חושיים</b> (מוזיקת-רקע, ריח מסוים) שהיו-נוכחים בקידוד ומופיעים-שוב-בשליפה. ⚠️ המשמעות המעשית: מבחן שנערך <b>באותו חדר</b> שבו נלמד החומר, או אפילו עם <b>אותה מוזיקת-רקע</b>, יכול לשפר-ביצועים בהשוואה למבחן בהקשר-שונה-לגמרי - זו לא רק תיאוריה, זה עיקרון בעל השלכות מעשיות ברורות ללמידה.","mnemo":"🤿 מים-לומדים=מים-נזכרים."},{"id":"prof6_21","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו אפקט המיקום הסדרתי? דונו באפקט הראשונות והאחרונות.","a":"זוכרים טוב את ההתחלה (ראשונות) והסוף (אחרונות), לא האמצע.","explain":"<b>אפקט המיקום הסדרתי (serial position effect)</b> - תופעה עקבית ומוכרת: כשמנסים לזכור רשימה, זוכרים <b>הכי-טוב</b> את הפריטים ב<b>תחילת</b> הרשימה (<b>אפקט הראשונות/primacy</b>) ו<b>בסוף</b> הרשימה (<b>אפקט האחרונות/recency</b>), בעוד הפריטים ב<b>אמצע</b> הרשימה נזכרים <b>הכי-גרוע</b> - יוצר עקומה בצורת U כשמציירים את שיעור-הזכירה מול המיקום-ברשימה. ⚠️ ההסבר-התיאורטי (שיינתן בפירוט בשאלה הבאה) קשור למובחנות-בהקשר: הפריטים-בקצוות 'בולטים' יותר מבחינה זמנית/הקשרית מהפריטים-הטבועים-באמצע-ההמון, שנוטים 'להיטשטש' זה-בזה.","mnemo":"🥇🥉 התחלה+סוף זוכרים. אמצע נשכח."},{"id":"prof6_22","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו את אפקט הראשונות/האחרונות באמצעות מובחנות ההקשר וכיצד זה מחבר קידוד לשליפה.","a":"אחרון=קרוב-בזמן=ברור (כמו פס-רכבת קרוב). ראשון=פתח הקשר חדש=גם הוא בולט. אמצע=מיטשטש (כמו פסים רחוקים). מובחנות בקידוד קובעת הצלחה בשליפה.","explain":"ההסבר העמוק לאפקט-הראשונות/אחרונות משתמש במונח <b>מובחנות-ההקשר (contextual distinctiveness)</b> - וקושר את הפרק כולו יחד (עקרון-ייחודיות-הקידוד מיושם כאן): <b>אפקט-האחרונות</b> - הפריט-האחרון קרוב-בזמן לרגע-הבדיקה, ולכן עדיין נמצא בזיכרון-העבודה (הזרקור-הפעיל), 'ברור' וזמין-מיידית - כמו פס-רכבת <b>הכי-קרוב</b> אלינו, שקל להבחין-בו כי אין דבר אחר קרוב-כמוהו. <b>אפקט-הראשונות</b> - הפריט-הראשון 'פותח' הקשר-חדש-לגמרי (עוד לא היה שום דבר-אחר לפניו ברשימה) - הוא-עצמו גם-כן בולט ומובחן, אולי אף קיבל <b>יותר-שינון-חוזר</b> (כי הזמן-שהמוח-פנוי-לחזור-עליו לפני שהגיעו-פריטים-נוספים היה ארוך-יותר). <b>הפריטים באמצע</b> 'מיטשטשים' - כמו פסי-רכבת רחוקים-ודומים-זה-לזה - קשה להבחין ביניהם, כי כל-אחד 'דומה' לפריטים-הסמוכים-לו משני-הצדדים. <b>המסקנה</b>: מובחנות-בקידוד (עד-כמה פריט 'בולט' בהקשרו) קובעת ישירות הצלחה-בשליפה.","mnemo":"🚂 פסי-רכבת: קרוב=ברור, רחוק=מטושטש."},{"id":"prof6_23","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד אפשר לנצל את הידע על אפקט המיקום הסדרתי כדי לשפר את יכולת הזכירה?","a":"לחלק רשימות ארוכות לקטעים קצרים (כך שליותר פריטים תהיה 'התחלה/סוף'). להגדיל מלאכותית את המובחנות של פריטי האמצע (הפסקות/הקשר שונה). למקם מידע חשוב בתחילת/סוף החומר, לא באמצעו.","explain":"יישום מעשי-ופרקטי של הידע על אפקט-המיקום-הסדרתי לשיפור-זכירה, בשלושה כיוונים משלימים: <b>(1) חלוקת רשימות-ארוכות לקטעים-קצרים</b> - כך יותר-פריטים 'נהנים' מלהיות בקרבת-תחילה-או-סוף-של-קטע-כלשהו, ולא נטמעים באמצע-רשימה-ארוכה-אחת. <b>(2) הגדלת מובחנות-פריטי-האמצע באופן מלאכותי</b> - למשל, על-ידי הפסקות קצרות, שינוי-הקשר (עצירה, נשימה, מעבר לנושא-אחר-לרגע) שהופכות פריטי-אמצע-מסוימים ל'בולטים' יותר, בדיוק כפי שראינו שמובחנות-בקידוד קובעת שליפה. <b>(3) מיקום מידע-חשוב בתחילת/סוף-החומר</b>, לא באמצעו - אם יודעים מראש שמשהו קריטי, כדאי 'לתכנן' את מיקומו ברשימה/בהרצאה כך שייהנה מיתרון-הראשונות-או-האחרונות.","mnemo":"✂️ לחתוך רשימות ארוכות לקטנות = יותר \"התחלות/סופים\"."},{"id":"prof6_24","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"קשרו בין היזכרות/היכר לבין זיכרון גלוי/חבוי.","a":"היזכרות/היכר=גלוי (מבקשים ישירות). השלמת-מילה/הטרמה=חבוי (בעקיפין).","explain":"חיבור בין שתי דיכוטומיות-מרכזיות בפרק: היכר/היזכרות (שיטות-שליפה) מול זיכרון-גלוי/חבוי (סוגי-זיכרון): <b>היזכרות והיכר</b> שתיהן דוגמאות ל<b>זיכרון גלוי (explicit)</b> - כי בשתיהן, אנחנו <b>מבקשים ישירות</b> מהאדם לשלוף/לזהות זיכרון-מודע, והוא-עצמו מודע לכך שהוא מנסה-לזכור. <b>השלמת-מילה</b> (רואים 'סבת_' ומשלימים 'סבתא') או <b>הטרמה (priming)</b> (חשיפה קודמת למילה משפיעה על מהירות-זיהוי מאוחר-יותר) הן דוגמאות ל<b>זיכרון חבוי (implicit)</b> - כי כאן, ההשפעה על ההתנהגות קורית <b>בעקיפין</b>, בלי לבקש-ישירות 'תזכור' ולעיתים בלי שהאדם-עצמו מודע-בכלל שזיכרון-ישן משפיע עליו. ⚠️ המסר: 'איך בודקים' (ישיר/עקיף) קשור-ישירות ל'איזה-סוג-זיכרון' נחשף (מודע/לא-מודע).","mnemo":"🙋 גלוי=שואלים ישר. חבוי=בלי לשאול."},{"id":"prof6_25","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"במה עדיף שימוש בדרכי מבחן עקיפות מדיווח מפורש לבדיקת זיכרון?","a":"מבחנים עקיפים חושפים זיכרון גם כשאין למשתתף גישה מודעת אליו, או כשהוא כלל לא מודע שהוא 'זוכר' (כמו זיכרון חבוי/תהליכי). מאפשרים ללמוד על תוכן הזיכרון גם ללא הסתמכות על דיווח עצמי מודע ואמין.","explain":"מבחנים-עקיפים (הבוחנים זיכרון-חבוי, כמו הטרמה) מציעים יתרון-מתודולוגי חשוב על-פני דיווח-מפורש (זיכרון-גלוי): הם <b>חושפים זיכרון גם כשאין למשתתף גישה-מודעת אליו</b> - כלומר, גם כשהמשתתף <b>לא-יכול לדווח</b> במילים על מה-שהוא 'זוכר' (כי הוא-עצמו לא-מודע לכך שהוא זוכר משהו). דוגמה קלינית חשובה: חולי-שכחון (אמנזיה) יכולים <b>לשפר ביצוע במטלה</b> בזכות חשיפה-קודמת, למרות שהם <b>אינם זוכרים כלל</b> שנחשפו למשהו קודם - מבחן-עקיף חושף את ה'זיכרון' הזה, בעוד שאלה-ישירה ('האם ראית את זה קודם?') הייתה מקבלת 'לא' כתשובה. ⚠️ המסקנה: מבחנים-עקיפים מאפשרים ללמוד על תוכן-הזיכרון-האמיתי, גם כאשר דיווח-עצמי-מודע לא-אמין או פשוט לא-זמין.","mnemo":"🎭 מבחן עקיף תופס גם מה שלא מודעים לו."},{"id":"prof6_26","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע השתמש אבינגהאוס בהברות תפל דווקא?","a":"הברות-תפל=חסרות משמעות, כדי למדוד שכחה \"נקייה\".","explain":"<b>אבינגהאוס</b> - חלוץ מחקר-הזיכרון המדעי - השתמש ב<b>הברות-תפל (nonsense syllables)</b> - צירופי-אותיות מלאכותיים חסרי-משמעות (כמו 'זוק', 'טיב') - במקום מילים-אמיתיות, מטעם-מתודולוגי חשוב: אם משתמשים במילים-אמיתיות, הן <b>כבר קשורות</b> לרשת-עצומה של ידע-קיים, אסוציאציות, ומשמעויות אישיות שיכולים 'לעזור' לזכירה בדרכים בלתי-שוות-ובלתי-נשלטות בין-אנשים-שונים. הברות-תפל, לעומת-זאת, <b>נקיות-לחלוטין ממשמעות-קודמת</b> - כך אבינגהאוס יכל למדוד <b>שכחה 'טהורה'</b>: את קצב-השכחה-הבסיסי-ביותר של המוח, ללא-ההשפעות-המבלבלות של ידע-קודם/משמעות שהיו-מוסיפים 'רעש' לתוצאות.","mnemo":"🔤 הברות-תפל=בלי-זיכרון-ישן שמפריע."},{"id":"prof6_27","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"איזה מדד שימש את אבינגהאוס לכימות השכחה?","a":"מדד החיסכון: ההפרש בין מספר הצעדים הנדרש ללמוד רשימה בפעם הראשונה למספר הצעדים הנדרש ללמוד אותה מחדש, מחולק במספר הצעדים המקורי.","explain":"<b>מדד החיסכון (savings method)</b> - החידוש המתודולוגי-החכם של אבינגהאוס לכימות-מדויק של שכחה: מודדים את <b>ההפרש</b> בין <b>מספר-הצעדים/החזרות הנדרש ללמוד רשימה בפעם-הראשונה</b> לבין <b>מספר-הצעדים הנדרש ללמוד-אותה-מחדש</b> (אחרי פרק-זמן שחלף), ומחלקים את ההפרש-הזה <b>במספר-הצעדים המקורי</b> - כך מקבלים אחוז שמייצג כמה 'נחסך' בלמידה-החוזרת, בזכות שרידי-הזיכרון-הישן. ⚠️ הרעיון החכם: גם אם אבינגהאוס לא-הצליח <b>להיזכר במודע</b> ברשימה-הישנה, אם הוא למד-אותה-מחדש <b>מהר-יותר</b> בפעם-השנייה מאשר בפעם-הראשונה, זה <b>מוכיח</b> ששריד כלשהו של הלמידה-המקורית עדיין קיים - גם כשהיזכרות-מודעת-מלאה כבר נכשלה לגמרי.","mnemo":"💰 חיסכון = כמה צעדים חסכתי בלמידה-חוזרת."},{"id":"prof6_28","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"לפי תרשים עקומת השכחה של אבינגהאוס, מהו הגורם המסביר שכחה?","a":"רק הזמן שעבר. שכחה מהירה בהתחלה, אח\"כ איטית.","explain":"לפי עקומת-השכחה המפורסמת של אבינגהאוס, הגורם היחיד המסביר את קצב-השכחה הוא <b>הזמן-שעבר</b> בלבד - ולא, למשל, כמות-הפעילות-האחרת שביצענו בינתיים. <b>הצורה של העקומה חשובה מאוד לזכור</b>: השכחה <b>מהירה-מאוד בהתחלה</b> (מיד אחרי הלמידה, אחוז-גדול מהחומר נשכח תוך שעות-ראשונות) - ולאחר-מכן, קצב-השכחה <b>מאט משמעותית</b>, וממשיך-לרדת בקצב-איטי-מאוד לאורך-ימים ושבועות. ⚠️ המשמעות המעשית העצומה: אם רוצים לזכור-חומר-לטווח-ארוך, ה<b>חזרה-הראשונה</b> (סמוך ככל-האפשר אחרי הלמידה הראשונית) היא הכי-קריטית, כי היא 'תופסת' את החומר לפני-שהוא-נשכח-בקצב-המהיר-ביותר - זה הבסיס המדעי לשיטות-חזרה-מרווחת (spaced repetition) המומלצות ללמידה.","mnemo":"📉 צונח מהר, אז משתטח."},{"id":"prof6_29","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי הפרעה למאוחר? הציגו דוגמה.","a":"ישן מפריע לחדש (טלפון-ישן קופץ למחשבה).","explain":"<b>הפרעה למאוחר (proactive interference)</b> - מידע <b>ישן</b> (שנלמד-קודם) <b>מפריע</b> לזכירת מידע <b>חדש</b>. הדוגמה: מספר-הטלפון-הישן שלכם 'קופץ לראש' באופן אוטומטי כשמנסים לזכור/למסור את המספר-החדש - המידע-הישן-והוותיק 'תוקף' ומתערב ביכולת לשלוף בביטחון את החדש. ⚠️ המילה 'פרו-אקטיבית' (proactive) מרמזת שהמידע-הישן פועל 'קדימה' (מהעבר לעתיד) ומפריע ללמידה/שליפה-חדשה יותר - זה בדיוק ההפך המושגי מ'הפרעה למוקדם' שתילמד בשאלה הבאה, ושתי התופעות-האלה יחד מהוות זוג-מושגים חשוב שקל-להתבלבל-בו.","mnemo":"👴➡️👶 ישן דוחף חדש."},{"id":"prof6_30","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי הפרעה למוקדם? הציגו דוגמה.","a":"חדש מפריע לישן (שוכחים את הטלפון-הישן).","explain":"<b>הפרעה למוקדם (retroactive interference)</b> - ההפך המדויק מהפרעה-למאוחר: מידע <b>חדש</b> (שנלמד לאחרונה) <b>מפריע</b> לזכירת מידע <b>ישן</b> (שנלמד קודם). הדוגמה: אחרי לימוד/שינון מספר-הטלפון-החדש שלכם, אתם מוצאים את עצמכם <b>שוכחים</b> את מספר-הטלפון-הישן, שקודם ידעתם היטב-בעל-פה - המידע-החדש 'תוקף לאחור' (retro) ופוגע בזמינות-המידע-הישן. ⚠️ שיטת-הזכירה השימושית: 'פרו' (קדימה) = ישן-מפריע-לחדש; 'רטרו' (אחורה) = חדש-מפריע-לישן - כיוון-החץ במילה מרמז את כיוון-ההפרעה-בפועל.","mnemo":"👶➡️👴 חדש דוחף ישן."},{"id":"prof6_31","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מבין הפרעה למאוחר ולמוקדם, איזו עוסקת בקידוד ואיזו בשליפה?","a":"למאוחר=קידוד. למוקדם=שליפה.","explain":"הבחנה תיאורטית חשובה בין שני-סוגי-ההפרעה, לפי <b>שלב-הזיכרון</b> שבו-כל-אחת-פוגעת: <b>הפרעה למאוחר</b> (ישן מפריע לחדש) פוגעת בעיקר בשלב ה<b>קידוד</b> - המידע-הישן 'תופס מקום' ומקשה על קידוד-מוצלח וברור של המידע-החדש כשהוא נכנס לראשונה. <b>הפרעה למוקדם</b> (חדש מפריע לישן) פוגעת בעיקר בשלב ה<b>שליפה</b> - המידע-הישן היה מקודד היטב ואוחסן כבר-קודם, אך המידע-החדש-שנוסף מקשה על היכולת <b>לשלוף</b> אותו בהצלחה כעת. ⚠️ ההבחנה הזו מסבירה למה שני-סוגי-ההפרעה, למרות שנשמעים דומים ('אחד מפריע לשני'), הם למעשה שני תהליכים תיאורטיים שונים לגמרי, הפוגעים בשלבים שונים בשרשרת קידוד-אחסון-שליפה.","mnemo":"🔤 למ-אוחר=קוד. למ-וקדם=שלף."},{"id":"prof6_32","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו מידע לא מובנה ומדוע קשה לזכור אותו יותר ממידע מובנה?","a":"מידע שהקשרים בין פריטיו שרירותיים וחסרי משמעות טבעית (כמו צמדי מילים אקראיים). קשה יותר לזכור כי אין לו משמעות/מבנה מוכר לקידוד יעיל.","explain":"<b>מידע לא-מובנה</b> - מידע שהקשרים בין פריטיו <b>שרירותיים וחסרי-משמעות-טבעית</b> (הדוגמה הקלאסית: הברות-התפל של אבינגהאוס, או צמדי-מילים-אקראיים-לא-קשורים כמו 'כוס-ענן'). <b>למה קשה יותר לזכור</b>: קידוד-יעיל נשען על יצירת-קישורים למשמעות-קיימת/מבנה-מוכר - כשאין 'כלום' לתלות-בו (אין סיפור-הגיוני, אין קטגוריה-מוכרת), המוח נאלץ לזכור את הפריטים 'כשלעצמם', ללא-עזרה-חיצונית מרשתות-הידע-הקיימות שלנו - זו בדיוק הסיבה שאבינגהאוס בחר להשתמש בהברות-תפל מלכתחילה: כדי למדוד את הקושי-הבסיסי-ביותר, בלי 'עזרה' ממידע-קודם.","mnemo":"🎲 שרירותי=בלי-קשר-טבעי=קשה לזכור."},{"id":"prof6_33","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד שינון מעמיק מסייע בשיפור זכירת המידע?","a":"יוצרים סיפור/דימוי שמקשר פריטים = קידוד עשיר יותר.","explain":"<b>שינון מעמיק (elaborative rehearsal)</b> - בניגוד לשינון-פשוט (חזרה-מכנית), כאן <b>יוצרים באופן פעיל קישורים משמעותיים</b> בין הפריטים-לזכור לבין ידע-קיים, סיפור, או דימוי-ויזואלי - כך הופכים מידע-שרירותי-לא-מובנה למשהו <b>עשיר-במשמעות ומקושר</b>. <b>המנגנון</b>: כשיוצרים סיפור/דימוי המקשר פריטים-בודדים, המוח מקבל <b>מסלולי-שליפה נוספים</b> (הרמז 'איך הסיפור התפתח' יכול להוביל לזכירת-כל-הפריטים בסדר), במקום להסתמך על שינון-מכני-חוזר-ונשנה בלבד. ⚠️ זה בדיוק ההסבר מדוע שינון-מעמיק יעיל-הרבה-יותר משינון-רגיל: הוא מתמודד ישירות עם הבעיה שראינו בשאלה הקודמת - הופך מידע-לא-מובנה (קשה) למידע-מובנה-ומקושר (קל יותר).","mnemo":"📖 סיפור מקשר=זוכרים."},{"id":"prof6_reflection3","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הציעו לרונית שיטה מבוססת שינון מעמיק לזכירת: נוצה, ספר, כובע, שמש, ספינה.","a":"ליצור סיפור קטן המקשר את המילים בסדר הגיוני (למשל: נוצה נופלת על ספר, כובע מגן מהשמש, ואז מפליגים בספינה) + דימוי חזותי של הסצנה, להעשרת הקידוד.","explain":"יישום מעשי של שינון-מעמיק על רשימת-מילים-שרירותית - חשוב להראות את שתי הטכניקות המשלימות: <b>סיפור מקשר</b> - יצירת נרטיב-קטן-והגיוני שמחבר את המילים-בסדר (למשל: נוצה נופלת על ספר, כובע מגן מפני-השמש, ואז מפליגים בספינה) - הסיפור-עצמו הופך לרמז-שליפה: זוכרים 'איך הסיפור התפתח' ומזה נגזרות המילים לפי-הסדר. <b>דימוי חזותי</b> - הוספת תמונה מנטלית של הסצנה-כולה (לדמיין ממש את הנוצה-נופלת, הכובע, השמש, הספינה) - מוסיף שכבת-קידוד-נוספת (חזותית, לא רק מילולית), מה שמעשיר עוד-יותר את הזיכרון ומספק עוד ערוץ-שליפה-אפשרי. ⚠️ שילוב שתי הטכניקות (סיפור+דימוי) חזק יותר מכל-אחת-לבדה, כי הוא יוצר קידוד-רב-ממדי, לא רק-מילולי.","mnemo":"🪶📖🎩☀️🚢 נוצה-על-ספר, כובע-נגד-שמש, מפליגים-בספינה."},{"id":"prof6_34","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהן נמוניות ומדוע הן מהוות סוג של שינון מעמיק?","a":"אסטרטגיות מנטליות לקידוד רשימות ארוכות על ידי קישורן למידע מוכר, ומתן רמזי שליפה מוכנים מראש. הן סוג של שינון מעמיק כי מעשירות את הקידוד ומפחיתות שרירותיות, אך בעזרת מבנה שיטתי שניתן לשימוש חוזר.","explain":"<b>נמוניות (mnemonics)</b> הן אסטרטגיות-מנטליות שיטתיות לקידוד רשימות-ארוכות דרך קישורן למידע-מוכר-מראש, תוך <b>מתן רמזי-שליפה-מוכנים</b> (למשל, ראשי-תיבות, חריזה, מבנה-קבוע). <b>למה זה סוג של שינון-מעמיק</b>: הן <b>מעשירות את הקידוד</b> (בדיוק כמו סיפור/דימוי בשאלה הקודמת) על-ידי הוספת-קישורים-משמעותיים במקום מידע-שרירותי - <b>אבל</b>, בניגוד ל'סיפור אישי חד-פעמי' שממציאים לכל רשימה חדשה, נמוניות מספקות <b>מבנה-שיטתי-קבוע וניתן-לשימוש-חוזר</b> (למדים 'שיטה' אחת, ואפשר להחיל אותה שוב-ושוב על רשימות-שונות) - זה מפחית את השרירותיות (אין צורך 'להמציא' סיפור-חדש בכל פעם) תוך שמירה על היתרון-הקוגניטיבי-של-קישור-למשמעות.","mnemo":"🗺️ נמוניה = שינון-מעמיק עם מבנה קבוע."},{"id":"prof6_35","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו את טכניקת המקומות ומילות המפתח - מה משותף ובמה נבדלות?","a":"משותף: שתיהן נותנות רמזי-שליפה מוכנים מראש בסדר קבוע. שונה: מקומות=מסלול מרחבי מוכר. מילות-מפתח=חרוזי מספר-מילה.","explain":"שתי טכניקות-נמוניות ספציפיות שחולקות עיקרון-משותף אך שונות ביישום: <b>המשותף</b> - שתיהן מספקות <b>רמזי-שליפה מוכנים-מראש, בסדר-קבוע</b> - כלומר, פותרות מראש את בעיית-'איך-אזכור-את-הסדר' על-ידי מתן-מבנה-שיטתי שאפשר-לחזור-עליו שוב-ושוב. <b>ההבדל</b>: <b>שיטת-המקומות</b> - מבוססת על <b>מסלול מרחבי-מוכר</b> (למשל, חדרים-מוכרים בבית שלכם) - מדמיינים כל פריט-לזכירה 'מונח' במקום-ספציפי לאורך המסלול, ובשליפה 'הולכים' מנטלית לאורך אותו מסלול-מוכר. <b>שיטת-מילות-המפתח</b> - מבוססת על <b>חרוזי-צליל בין מילה למספר/מושג</b> (למשל, 'אחד-כמו-פחד', 'שתיים-כמו-אבנים') - כל מספר/פריט מקושר לצליל-שדומה-לו, ואז נבנה דימוי-קושר בין המילה-החורזת לתוכן-הנדרש. שתיהן פועלות באותה לוגיקה-בסיסית של רמזי-שליפה-מובנים, רק עם 'עוגן' שונה (מרחבי מול צלילי).","mnemo":"🚶=מקום. 🎵=מילה-חרוז."},{"id":"prof6_36","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תארו את מחקר לופטוס על עדי ראייה. האם ניתן לסמוך על עדותם?","a":"לא לגמרי - ניסוח שאלה בלבד (\"התנגשו\" מול \"נגעו\") שינה גם הערכת מהירות וגם זיכרון בדוי לזכוכית שבורה. מידע שלאחר האירוע מעוות זיכרון.","explain":"מחקרי לופטוס על עדי-ראייה מהווים אחת התרומות המדעיות-החשובות-ביותר לחשיפת שבירות-הזיכרון: הניסוי המרכזי הראה שהמשתתפים שנשאלו על מהירות-הרכבים כשהם 'התנגשו' (מילה חזקה) העריכו מהירות-גבוהה-יותר, ובנוסף (ממצא-מדהים) 'זכרו' <b>זכוכית-שבורה</b> שבפועל <b>מעולם לא-הייתה</b> בסרטון - כל זה רק בגלל <b>ניסוח-המילה בשאלה</b> ('התנגשו' מול 'נגעו'). <b>המסקנה החד-משמעית</b>: <b>לא ניתן לסמוך-בביטחון-מלא</b> על עדות-עדי-ראייה - מידע שמגיע <b>אחרי</b> האירוע (אפילו בניסוח-שאלה בלבד, בלי כוונה-רעה) יכול <b>לעוות ולשנות</b> את הזיכרון-עצמו, לא רק את הדיווח-עליו - העד 'זוכר' משהו-שלא-קרה, לא רק 'משקר' במודע.","mnemo":"💬 מילת-שאלה=משנה זיכרון."},{"id":"prof6_37","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו אפקט המידע המטעה וכיצד הוא משפיע על הזיכרון?","a":"מידע-שגוי-אחרי-האירוע מתערבב עם הזיכרון האמיתי.","explain":"<b>אפקט המידע המטעה (misinformation effect)</b> - התופעה שמחקר-לופטוס חשף באופן שיטתי: מידע-שגוי שמגיע <b>אחרי</b> אירוע (מ'שאלה מובילה', משיחה עם אנשים-אחרים, מדיווח-חדשות) <b>מתערבב פיזית עם הזיכרון-האמיתי</b> של האירוע-המקורי - עד-כדי-כך שאנשים 'זוכרים בביטחון-מלא' פרטים שמעולם-לא-קרו-בפועל. ⚠️ הנקודה המדעית-החשובה: זה <b>לא</b> רק 'בלבול' זמני או אי-ודאות - המידע-המטעה למעשה <b>משתלב לתוך</b> ייצוג-הזיכרון-עצמו, כך שהאדם חווה זיכרון-מלא-וברור (ולא 'מנחש') לגבי משהו שכלל-לא-התרחש - זו הוכחה חזקה שזיכרון הוא תהליך שחזורי-ובנייתי, לא הקלטה-מדויקת-של-העבר.","mnemo":"🔀 שקר-מאוחר מתערבב עם האמת."},{"id":"prof6_38","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע אמרו החוקרים לנבדקים שהם עומדים לשמוע מידע מוטעה (מחקר הגניבה ממשרד)?","a":"כדי לבחון תנאי מחמיר: להוכיח שהאפקט חזק גם כשהנבדקים מוזהרים ומנסים במודע להתעלם מהמידע המטעה. מכיוון שהאפקט עדיין השפיע למרות האזהרה, זה מוכיח שהבעיה היא מגבלה בסיסית של הזיכרון (קושי להבחין במקור המידע) - לא חוסר זהירות של העדים.","explain":"החוקרים בחרו במפורש להזהיר-מראש את המשתתפים (במחקר-הגניבה-ממשרד) שהם עומדים-לשמוע-מידע-שעלול-להיות-מוטעה, כדי ליצור <b>תנאי-מבחן מחמיר-במיוחד</b>: המטרה הייתה להוכיח שהאפקט <b>חזק גם כשהנבדקים מנסים במודע להתעלם</b> מהמידע-המטעה. <b>התוצאה</b>: למרות האזהרה המפורשת, האפקט <b>עדיין השפיע</b> על הזיכרון של המשתתפים. <b>המסקנה החשובה</b>: זה מוכיח שהבעיה היא <b>מגבלה בסיסית ומובנית של הזיכרון עצמו</b> - קושי-אמיתי להבחין בין 'מקור המידע' (האם זה מה-שראיתי-בעצמי, או מה-ששמעתי-אחר-כך) - <b>לא</b> פשוט חוסר-זהירות או מודעות-חסרה מצד-העדים. גם כשמנסים במאמץ-מודע להישאר-מדויקים, המוח עדיין מתקשה 'לסנן' את המידע-החדש מהזיכרון-המקורי.","mnemo":"⚠️ גם מוזהרים=עדיין נופלים - זו מגבלה, לא רשלנות."},{"id":"prof6_39","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מה הייתה מסקנתו של קרל לאשלי לגבי מקום האנגרם (הייצוג הפיזי של הזיכרון)?","a":"לא במקום אחד - מפוזר בכל קליפת המוח.","explain":"<b>קרל לאשלי</b> חיפש שנים-ארוכות את ה<b>אנגרם</b> - הייצוג-הפיזי-הספציפי של זיכרון במוח (כלומר, 'איפה בדיוק' זיכרון-מסוים 'יושב' פיזית). לשם-כך, אימן עכברים במבוכים, ואז הסיר-בכוונה חלקים-שונים-וגדלים-שונים <b>מקליפת-המוח</b> שלהם, כדי לראות אם הסרת-אזור-מסוים 'תמחק' את הזיכרון-הספציפי-של-המבוך. <b>המסקנה המפתיעה</b>: לאשלי <b>לא הצליח</b> לאתר מיקום-יחיד-ומדויק לזיכרון - הפגיעה-בזיכרון הייתה תלויה בעיקר ב<b>כמות</b> הרקמה-שהוסרה (ככל שיותר, פגיעה חמורה-יותר), <b>לא</b> ב<b>מיקום הספציפי</b> שהוסר. <b>מסקנתו הסופית</b>: הזיכרון <b>אינו ממוקם במקום-אחד ומוגדר</b> - הוא <b>מפוזר</b> באופן נרחב בכל קליפת-המוח, לא מרוכז ב'אזור-זיכרון' יחיד.","mnemo":"🌐 זיכרון מפוזר, לא נקודתי."},{"id":"prof6_40","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע משפיעה מחלת אלצהיימר על הזיכרון? מה גילה אלואיס אלצהיימר?","a":"משפיעה כי רובד (פלאק) של עמילואיד הופך מרעיל וקוטל תאי עצב. אלצהיימר גילה: מוח חולים שמתו הכיל סבך רקמה ומשקעים דביקים (הרובד).","explain":"מחלת אלצהיימר משפיעה-קשות על הזיכרון דרך מנגנון פתולוגי ספציפי: <b>רובד (פלאק)</b> של חלבון-<b>עמילואיד</b> מצטבר במוח ו<b>הופך רעיל</b>, וגורם ל<b>קטילה של תאי-עצב</b> (נוירונים) - ככל שיותר תאי-עצב נהרסים, כך התפקוד הקוגניטיבי (כולל הזיכרון) נפגע יותר. <b>אלואיס אלצהיימר</b> (שעל-שמו נקראת המחלה) גילה זאת דרך ניתוח פוסט-מורטם: מוחות של חולים שנפטרו מהמחלה הכילו <b>סבך של רקמה ומשקעים דביקים</b> - זהו הרובד-העמילואידי-הרעיל שתואר לעיל, אותו זיהה לראשונה בבדיקה-מיקרוסקופית של רקמת-המוח. ⚠️ תגלית זו של אלצהיימר, בתחילת המאה ה-20, הייתה הבסיס-ההיסטורי שממנו התפתח כל המחקר-המודרני על מנגנוני-המחלה ועל ניסיונות-הטיפול-בה שמתמקדים בהפחתת/מניעת הצטברות-הרובד.","mnemo":"🧠🕸️ רשת-דביקה = אלצהיימר."},{"id":"quiz6_1","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"שמירת המידע בזיכרון מכונה: (אחסון / קידוד / אחזור / שליפה)","a":"אחסון (שמירת המידע לאורך זמן, בין קידוד לאחזור)","explain":"<b>אחסון</b> הוא בדיוק השלב-האמצעי מבין שלושת-תהליכי-הזיכרון (קידוד→אחסון→שליפה): שמירת המידע לאורך-זמן, בין רגע-קליטתו-והפיכתו-לייצוג-מנטלי (קידוד) לבין רגע-הוצאתו-בחזרה-למודעות (שליפה/אחזור). ⚠️ אל תתבלבלו: <b>קידוד</b> הוא ה'כניסה' של המידע (עדיין לא 'שמור', רק הופך-לייצוג); <b>אחזור/שליפה</b> הוא ה'יציאה' - שני מונחים שונים המתארים שני-קצוות-שונים-של-אותה-שרשרת, ואחסון הוא הגשר-שביניהם.","mnemo":"📦 שומר=אחסון."},{"id":"quiz6_2","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"איזה תהליך אינו נכלל ביכולת לשחזר ולעשות שימוש חוזר במידע: (קידוד / שיקלוט / אחסון / אחזור)","a":"שיקלוט (זה שלב בתפיסה, לא שלב בתהליך הזיכרון עצמו)","explain":"<b>שיקלוט (perception)</b> שייך לתהליך-<b>התפיסה</b> (פרק 4) - זהו השלב שבו אנחנו הופכים גירוי-חושי-גולמי למתפס-בעל-משמעות - <b>לא</b> אחד משלושת-שלבי-הזיכרון עצמו (קידוד/אחסון/אחזור). ⚠️ חשוב להבחין בין שני-פרקים-שכנים: תפיסה (איך הופכים גירוי-פיזי למשמעות) קודמת-לוגית לזיכרון (איך שומרים ומשתמשים-מחדש-במידע), אך הם תהליכים-נפרדים-מבחינה-תיאורטית - שיקלוט לא-נחשב לחלק מהגדרת-הזיכרון-הרשמית שנלמדה בפרק.","mnemo":"👁️ שיקלוט=תפיסה, לא זיכרון."},{"id":"quiz6_3","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"מחקרים עדכניים מעריכים כי אנו מסוגלים להחזיק ___ פרטי מידע בזיכרון לטווח קצר: (שבעה / ארבעה / שניים / תשעה)","a":"ארבעה (מחקרים עדכניים מעדכנים כלפי מטה את מספרו של מילר)","explain":"מחקרים-עדכניים (כפי שנלמד בפרק, בהקשר של 'מספר-הקסם' של מילר) מעדכנים כלפי-מטה את ההערכה-המקורית: בעוד מילר-עצמו (בעבר) העריך 7±2 פריטים, מחקרים חדשים-יותר מצביעים על קיבולת אמיתית של רק כ<b>ארבעה</b> פריטים בזיכרון-לטווח-קצר, ללא-שימוש-בטכניקות-עזר כמו מקבצים. ⚠️ שימו לב שזו נקודה שקל להתבלבל-בה מול 'מספר-הקסם המסורתי' (7) - הבחינה בודקת ספציפית את ההערכה-<b>המעודכנת</b>, לא ההיסטורית.","mnemo":"4️⃣ היום: ארבע, לא שבע."},{"id":"quiz6_4","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"המידע בזיכרון עובר מ: (קצר לארוך או ארוך לקצר / ארוך לקצר ואז רק לארוך / רק ארוך לקצר / רק קצר לארוך)","a":"זורם בשני הכיוונים - קצר↔ארוך.","explain":"המידע בזיכרון <b>לא זורם רק בכיוון-אחד</b> - זו טעות-נפוצה לחשוב שהוא 'עובר' מקצר-לארוך פעם-אחת ונשאר-שם: בפועל, המידע <b>זורם בשני-הכיוונים</b> - מזיכרון-לטווח-קצר לזיכרון-לטווח-ארוך (כשלומדים/משננים משהו לצמיתות), <b>וגם</b> מזיכרון-לטווח-ארוך בחזרה לזיכרון-לטווח-קצר/עבודה (כשמשלים זיכרון-ישן כדי להשתמש-בו-כרגע, למשל לענות-על-שאלה שדורשת ידע-קודם). ⚠️ המערכת דינמית ואינטראקטיבית, לא 'צינור חד-כיווני' פשוט.","mnemo":"↔️ שני כיוונים, לא רק אחד."},{"id":"quiz6_5","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"איזה מהבאים ייראה כמקבץ אחד של מידע: (59482571 / שץנ-גיע / \"אני אוהב אותך\")","a":"\"אני אוהב אותך\" (משפט משמעותי נתפס כמקבץ אחד, לא כאותיות בודדות)","explain":"המשפט '\"אני אוהב אותך\"' נתפס כ<b>מקבץ אחד</b> - כי הוא <b>משפט משמעותי-ומוכר</b>, שהמוח מזהה-מיד כיחידה-שלמה-אחת (בזכות היכרות-מוקדמת עם המבנה-והמשמעות), לא כאוסף-של-14 אותיות-בודדות שצריך-לזכור-כל-אחת-בנפרד. ⚠️ בניגוד לכך: '59482571' (ספרות-אקראיות, ללא-דפוס-מוכר) ו'שץנ-גיע' (צירוף-אותיות-חסר-משמעות) הם <b>שרירותיים</b> - כל תו-בהם נחשב יחידת-מידע-נפרדת, כי אין מבנה-משמעותי-מוכר שהמוח יכול 'לארוז' אותם-לתוכו כמקבץ-אחד - זו בדיוק ההדגמה של מושג ה-chunking.","mnemo":"💬 משפט-שלם=מקבץ אחד."},{"id":"quiz6_6","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"באדלי ועמיתיו סיפקו עדות לכל הבאים, פרט ל: (לולאה פונולוגית / לוח חזותי מרחבי / מערכת תמרון מידע / מנגנון בקרה מרכזי)","a":"מערכת תמרון מידע (זהו שם שגוי - לא אחד ממרכיבי מודל באדלי)","explain":"'מערכת תמרון-מידע' <b>אינה</b> אחד ממרכיבי מודל-באדלי - זהו שם שגוי, לא-קיים במודל. שלושת-המרכיבים-האמיתיים (שנלמדו קודם בפרק) הם: <b>לולאה פונולוגית</b> (מידע מבוסס-דיבור/צליל), <b>לוח חזותי-מרחבי</b> (מידע חזותי/מרחבי), ו<b>מנגנון בקרה-מרכזי</b> ('המנהל' שמתאם-בין-השניים ומקצה-קשב). ⚠️ שאלה זו בעיקר בודקת שינון-מדויק-של-המונחים - חשוב לזכור בדיוק את שמות-שלושת-המרכיבים, כי שמות דומים-אך-שגויים (כמו 'מערכת תמרון-מידע') עלולים להישמע-הגיוניים אך אינם-קיימים-במודל האמיתי.","mnemo":"❌ \"תמרון-מידע\" - שם מומצא, לא קיים."},{"id":"quiz6_7","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"צוללנים למדו מילים על החוף/מתחת למים; זכרו טוב יותר: (מתחת למים / על החוף / מתחת למים כשנלמדו מתחת למים / מתחת למים אפילו כשנלמדו על החוף)","a":"מתחת למים, כאשר המילים נלמדו מתחת למים (התאמת הקשר קידוד-אחזור משפרת זיכרון)","explain":"הצוללנים (מחקר-קלאסי המדגים את עקרון-ייחודיות-הקידוד) זכרו טוב-יותר <b>מתחת-למים, כאשר המילים נלמדו מתחת-למים</b> - כלומר, ה<b>התאמה</b> בין הקשר-הקידוד (איפה למדו) להקשר-השליפה (איפה נבחנו) היא-שקבעה את הביצוע-הטוב-ביותר, לא הסביבה-עצמה (מתחת-למים) כשלעצמה. ⚠️ אם היה נבחר 'מתחת-למים תמיד עדיף' (בלי-קשר-להקשר-הלמידה), זו הייתה טעות - העיקרון האמיתי הוא ה<b>התאמה</b> בין שני-ההקשרים, לא עדיפות-אבסולוטית של סביבה-מסוימת - זו בדיוק ההוכחה שעקרון-ייחודיות-הקידוד עובד בשני-הכיוונים.","mnemo":"🤿🏖️ לא המים מנצחים - ההתאמה מנצחת (קידוד=שליפה)."},{"id":"quiz6_8","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"הפריט הממוצע, או המאפיין קטגוריה כלשהי, מכונה: (סכמה / אב טיפוס / אקזמפלר / אנגרם)","a":"אב טיפוס (הדוגמה הטיפוסית/הממוצעת ביותר של קטגוריה)","explain":"<b>אב-טיפוס (prototype)</b> הוא הפריט-הממוצע/הטיפוסי-ביותר המייצג קטגוריה מסוימת - למשל, 'ציפור טיפוסית' כמו דרור, לא-פינגווין (שהוא ציפור אך לא-טיפוסי). ⚠️ הבדילו מהמסיחים: <b>סכמה</b> - מבנה-ידע-רחב-יותר על תחום-שלם (לא רק דוגמה-אחת); <b>אקזמפלר (exemplar)</b> - דוגמה-ספציפית-ומוכרת-אחת מהקטגוריה (לא בהכרח הממוצע/הטיפוסי-ביותר); <b>אנגרם</b> - הייצוג-הפיזי-במוח של זיכרון-כלשהו (מונח שנלמד בהקשר של לאשלי, לא-קשור-לקטגוריות-כלל.","mnemo":"📊 אב-טיפוס=הממוצע."},{"id":"quiz6_9","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"סרט מתאר מתבגר החוצה באור צהוב ומתנגש. איזו שאלה מדגימה אפקט מידע מוטעה? (מהירות כשסטה לכיוון המכונית / מהירות כשפגע במכונית / מהירות כשחצה באור צהוב / מהירות כשחצה באור ירוק)","a":"מה הייתה מהירות הנסיעה כשהרכב חצה באור ירוק? (משנה עובדה [צהוב→ירוק] כדי לבדוק אם משפיע על הזיכרון)","explain":"כדי לבדוק אפקט-מידע-מטעה, יש לשנות <b>עובדה-קונקרטית</b> מהאירוע-המקורי (בסרטון, המתבגר חצה <b>באור-צהוב</b>) ולבדוק אם הנבדק 'זוכר' את הגרסה-המשונה-לאחור. השאלה 'מה הייתה מהירות-הנסיעה כשחצה <b>באור-ירוק</b>?' משנה בכוונה את הצבע (צהוב→ירוק) - אם הנבדק עונה על השאלה בלי לתקן/להתנגד לפרט-השגוי (ירוק במקום צהוב), זה מעיד שהמידע-המטעה השתלב-בזיכרונו. ⚠️ שאר-האפשרויות אינן משנות עובדה-אמיתית מהסרטון (הן שואלות על מה-שבאמת-קרה, כמו הסטייה או הפגיעה), ולכן לא-בודקות-אפקט-מטעה כלל.","mnemo":"🚦 צהוב➡️ירוק = שינוי-עובדה בשאלה."},{"id":"quiz6_10","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"תמיר עובר ליד מוכר תפוזים; מאוחר יותר מבקש תפוז ולא יודע להסביר מדוע. שימוש בזיכרון: (תהליכי / חבוי / איקוני / גלוי)","a":"חבוי (זיכרון לא-מודע המשפיע על התנהגות בלי מודעות מדוע)","explain":"תמיר מבקש-תפוז <b>בלי שהוא-עצמו יודע-להסביר-למה</b> - זה בדיוק הסימן-המובהק ל<b>זיכרון חבוי</b>: השפעה לא-מודעת של חוויה-קודמת (עברו-ליד-מוכר-התפוזים) על ההתנהגות-הנוכחית, בלי-שהאדם-עצמו מודע-לקשר. ⚠️ אל תתבלבלו עם 'תהליכי' - זה סוג-ספציפי-יותר של זיכרון-חבוי, הקשור-למיומנויות-מוטוריות (כמו רכיבה-על-אופניים); כאן מדובר בהשפעה-על-<b>העדפה/דחף</b>, לא-מיומנות-פיזית - התשובה הכללית-והמדויקת יותר היא 'חבוי'.","mnemo":"🍊 מבקש בלי לדעת למה=חבוי."},{"id":"quiz6_11","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"נועה עונה על שאלות פוליטיקה תוך כדי סיבוב כדורים. השאלות דורשות זיכרון ___, סיבוב הכדורים דורש זיכרון ___: (חבוי;מוצהר / מוצהר;תהליכי / חבוי;תהליכי / תהליכי;מוצהר)","a":"מוצהר; תהליכי (שאלות=ידע עובדתי מודע; סיבוב כדורים=מיומנות מוטורית אוטומטית)","explain":"שאלות-פוליטיקה דורשות שליפה-מודעת-של-ידע-עובדתי - זה בדיוק <b>זיכרון מוצהר</b> (declarative/explicit) - זיכרון-שאפשר-להצהיר-עליו-במילים. סיבוב-הכדורים (מיומנות מוטורית-אוטומטית) דורש <b>זיכרון תהליכי</b> (procedural) - סוג-ספציפי של זיכרון-חבוי, הקשור-ליכולות-מוטוריות שמבצעים 'בלי-לחשוב', בלי-יכולת-להסביר-במילים-מדויקות 'איך' עושים זאת. ⚠️ זו הדגמה יפה של כך ששני-סוגי-זיכרון-שונים-לגמרי יכולים לפעול-בו-זמנית, במקביל, אצל אותו-אדם - אחד מודע-ומילולי, השני אוטומטי-ולא-מילולי.","mnemo":"🗣️🤹 שאלות=מוצהר. ידיים=תהליכי."},{"id":"quiz6_12","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"מהו הסדר הנכון של התהליכים: (אחסון,קידוד,שליפה / שליפה,קידוד,אחסון / קידוד,אחסון,שליפה / קידוד,שליפה,אחסון)","a":"קידוד, אחסון, שליפה (הסדר הכרונולוגי הנכון של עיבוד הזיכרון)","explain":"הסדר הכרונולוגי-ההכרחי של תהליכי-הזיכרון הוא <b>קידוד → אחסון → שליפה</b>, ולא בשום סדר-אחר - כל שלב תלוי-בקודמו-לוגית: אי-אפשר לאחסן מידע שלא-קודד-קודם, ואי-אפשר לשלוף מידע שלא-אוחסן-קודם. ⚠️ זהו העיקרון-הבסיסי-ביותר בפרק כולו, שממנו נובעות כל ההבנות-האחרות (למשל, למה כישלון-בכל-שלב יוצר סוג-שונה של 'שכחה').","mnemo":"📥📦📤 קוד→שמור→שלוף."},{"id":"quiz6_13","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"להדגמת קיבולת הזיכרון האיקוני, ספרלינג הראה שמשתתפים ביצעו טוב יותר בשיטת: (זיכרון חבוי / הדיווח החלקי / הדיווח המלא / זיכרון תהליכי)","a":"הדיווח החלקי (שיטה שחשפה קיבולת גדולה יותר מכפי שנראה בדיווח מלא)","explain":"בניסוי ספרלינג, <b>הדיווח-החלקי</b> (לא הדיווח-המלא) הוכיח את הקיבולת-הגדולה של הזיכרון-האיקוני - כפי שנלמד בפרק, כשמבקשים לדווח רק-על-שורה-אחת (שנקבעת-אקראית-לאחר-ההצגה על-ידי צליל), משתתפים הצליחו-בכל-שורה-כמעט-שווה, מה-שהוכיח שכל-המידע (לא-רק-חלק) היה זמין-ברגע-התצוגה. ⚠️ אל תתבלבלו: דיווח-מלא <b>הראה תוצאות-נמוכות-יותר</b>, לא בגלל-חוסר-זמינות-המידע, אלא כי המידע התפוגג-מהר-מדי לפני-שהספיקו-לדווח-על-הכל - זו הייתה בדיוק הטעות-שדיווח-חלקי בא-לתקן/לחשוף.","mnemo":"🎺 חלקי ניצח את המלא."},{"id":"quiz6_14","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"בזכות יעילות רמזי שינון, ___ קל יותר מ___: (היזכרות;זיכרון אפיזודי / זיכרון סמנטי;היכר / היכר;היזכרות / היזכרות;היכר)","a":"היכר; היזכרות (לזהות תשובה נכונה קל יותר מלהיזכר בה מאפס)","explain":"<b>היכר קל-יותר מהיזכרות</b> - כפי שנלמד בפרק, בזכות איכות-הרמז: בהיכר, הרמז כבר-כולל-בתוכו את התשובה-האפשרית (רק צריך לזהות/להשוות), בעוד בהיזכרות צריך 'לייצר' את כל-התשובה מאפס, בלי-רמז-מוכן שכבר-כולל-אותה. ⚠️ אפשרויות-מסיחות עם 'זיכרון-אפיזודי/סמנטי' לא-רלוונטיות כאן כלל - השאלה עוסקת ב<b>שיטות-שליפה</b> (היכר/היזכרות), לא ב<b>סוגי-זיכרון-לפי-תוכן</b> (אפיזודי/סמנטי) - שני צירים-שונים-לגמרי בפרק שקל-לבלבל-ביניהם.","mnemo":"✅❌ לזהות קל מלהיזכר."},{"id":"quiz6_15","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"מירה זוכרת רק את שם האדם האחרון שפגשה בקבוצה. דוגמה לאפקט ה: (מובחנות ההקשר / אחרונות / ייחודיות ההקשר / ראשונות)","a":"אחרונות (הפריט האחרון שנשמע נשאר טרי בזיכרון העבודה)","explain":"מירה שזוכרת <b>רק את השם-האחרון</b> ששמעה בקבוצה היא הדגמה מובהקת ל<b>אפקט-האחרונות</b> - הפריט-האחרון עדיין 'טרי' וזמין בזיכרון-העבודה/הזרקור-הפעיל, ברגע-שנשאלת, ולכן נזכר-בקלות-רבה-יותר משאר-השמות. ⚠️ הבדילו מ'אפקט-הראשונות' (שהיה-מתאים אם היא זכרה רק את השם-הראשון, לא-האחרון) - הכיוון (אחרון מול ראשון) הוא בדיוק ההבדל בין שני-חלקי-אפקט-המיקום-הסדרתי.","mnemo":"🥉 אחרון-ששמעתי=הכי-טרי."},{"id":"quiz6_16","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"איזו שאלה על 'מיסיסיפי' דורשת עיבוד עמוק ביותר? (האם שם נהר? / כמה פעמים יוד? / מה האות הראשונה? / כמה הברות?)","a":"האם זה שם של נהר? (דורש עיבוד משמעות, לא רק צליל/מראה)","explain":"השאלה 'האם זה שם-של-נהר?' דורשת <b>עיבוד-משמעות</b> (סמנטי) - צריך לגשת לידע-עולם-ולהבין את המשמעות-של-המילה 'מיסיסיפי', לא רק את מאפייניה-הצורניים. ⚠️ שאר-האפשרויות (כמה-פעמים 'יוד', מה-האות-הראשונה, כמה-הברות) דורשות רק עיבוד-שטחי/פונטי (איך המילה נראית/נשמעת), <b>לא</b> את משמעותה - זה בדיוק ההבדל שממחיש את עקרון-'עיבוד-לפי-רמות' (levels of processing): ככל שהעיבוד-עמוק-יותר (מגיע-למשמעות, לא רק-לצורה), כך הזכירה-המאוחרת-טובה-יותר - זה בדיוק ההיגיון מאחורי שינון-מעמיק שנלמד קודם בפרק.","mnemo":"🌊 \"נהר?\"=משמעות=עמוק."},{"id":"quiz6_17","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"לפי עקומת השכחה, השכחה הגדולה ביותר צפויה בין: (יום 5 ל-10 / יום 3 ל-5 / יום 1 ל-2)","a":"יום 1 ליום 2 (השכחה הכי חדה מיד אחרי הלמידה, ואז מתמתנת)","explain":"לפי עקומת-השכחה של אבינגהאוס (שנלמדה בפרק), השכחה <b>מהירה-ביותר מיד-אחרי-הלמידה</b>, ואז מאיטה-בהדרגה - ולכן ההפרש הכי-גדול בין יום-1-ל-יום-2 (הפרק-הכי-מוקדם) מייצג את הירידה-החדה-ביותר בעקומה. ⚠️ בהשוואה, ההפרש בין יום-3-ל-5 או יום-5-ל-10 (מאוחרים-יותר בציר-הזמן) יהיה קטן-משמעותית, כי העקומה כבר 'התמתנה' באותו-שלב - זו בדיוק ההדגמה-המספרית של הצורה-האופיינית (ירידה-חדה בתחילה, השתטחות-הדרגתית בהמשך) של עקומת-אבינגהאוס.","mnemo":"📉 יום1→2 = הצניחה הכי חדה."},{"id":"quiz6_18","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"נפתלי מדמיין את מרקורי כמחבת ואת נוגה כנעליים. הוא משתמש ב: (אחסון / שיטת מילות המפתח / זיכרון איקוני / שיטת המקומות)","a":"שיטת מילות המפתח (יוצר דימוי חזותי מקשר בין מילה זרה למשמעות)","explain":"נפתלי, שמדמיין דימוי-חזותי-קושר (מרקורי=מחבת, נוגה=נעליים) כדי לזכור-מושג-כלשהו, משתמש ב<b>שיטת מילות-המפתח</b> - טכניקת-נמוניקה שבה יוצרים דימוי-חזותי-קושר בין מילה/מושג-אחד למשמעות-אחרת, לרוב לפי-דמיון-צלילי-או-מבני. ⚠️ אל תתבלבלו עם 'שיטת-המקומות' - זו הייתה מתאימה אם נפתלי היה מדמיין 'מסלול מוכר' (כמו חדרים-בבית) עם-הפריטים-מונחים-לאורכו; כאן, ההדגשה היא על <b>דימוי-קושר-בין-שתי-יחידות</b>, לא-על-מיקום-לאורך-מסלול-מרחבי - זה בדיוק המבנה-האופייני לשיטת-מילות-המפתח.","mnemo":"🥞👞 מחבת+נעליים=מילות-מפתח."},{"id":"quiz6_19","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"אבנר סובל משכחון. יכולתו לרכוש זיכרונות ___ נפגעה יותר מיכולתו לרכוש זיכרונות ___: (גלויים;חבויים / חבויים;תהליכיים / חבויים;מוצהרים / מוצהרים;גלויים)","a":"גלויים; חבויים (שכחון פוגע בזיכרון מודע/עובדתי יותר מבמיומנויות אוטומטיות)","explain":"אבנר, הסובל-משכחון, נפגע יותר ביכולתו לרכוש זיכרונות <b>גלויים</b> (מוצהרים, מודעים - כמו זכירת-אירועים/עובדות-חדשות) מאשר זיכרונות <b>חבויים</b> (כמו מיומנויות-מוטוריות-חדשות) - זהו ממצא-קליני-מוכר ועקבי בחקר-שכחון (אמנזיה). ⚠️ זה בדיוק העיקרון שנלמד קודם בפרק דרך דוגמת-חולי-השכחון שיכולים 'להשתפר' במשימה בזכות חשיפה-קודמת, למרות שאינם-זוכרים-כלל שנחשפו למשהו - שכחון פוגע קשות בזיכרון-המודע (הגלוי) בעוד המערכות-הלא-מודעות (החבויות, כמו למידה-מוטורית) נשארות יחסית-שמורות.","mnemo":"🙋❌🤹✅ מוצהר נפגע, תהליכי נשאר."},{"id":"quiz6_20","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"אלואיס אלצהיימר הצליח להראות, כי: (אפשר להשתמש ברובד למניעת אלצהיימר / רובד גורם למחלה / עמילואיד-פפטיד גורם למחלה / לאנשים שמתו ממחלה היה רובד במוח)","a":"לאנשים שמתו ממחלת אלצהיימר היה רובד (פלאק) במוח","explain":"אלואיס אלצהיימר הצליח להראות, דרך ניתוח פוסט-מורטם, ש<b>לאנשים שמתו ממחלת-אלצהיימר היה רובד (פלאק) במוח</b> - זו בדיוק התגלית ההיסטורית שתוארה בפרק: הוא זיהה סבך-רקמה ומשקעים-דביקים (הרובד-העמילואידי) במוחות-חולים-שנפטרו. ⚠️ שימו לב שהתשובות-האחרות ('רובד גורם-למחלה', 'עמילואיד-פפטיד גורם-למחלה') הן <b>מסקנות-סיבתיות</b> מאוחרות-יותר, שמעבר-למה-שאלצהיימר-עצמו-הראה בתצפיתו-הראשונית - הוא בעצם רק הראה <b>קורלציה תצפיתית</b> (רובד קיים אצל-מתים-מהמחלה), לא-הוכיח-ישירות-בעצמו קשר-סיבתי-מלא.","mnemo":"🧠🕸️ מתים-עם-רובד = התגלית של אלצהיימר."},{"id":"quiz6_21","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"עמנואל שוכח מספר טלפון לפני שמספיק לחייגו. היה עליו להשקיע יותר ב: (טווח הזיכרון / שינון / זיכרון איקוני / הפרעה למוקדם)","a":"שינון (חזרה פעילה על המידע לפני שהוא נשכח)","explain":"עמנואל, ששוכח מספר-טלפון <b>לפני</b> שמספיק לחייגו, סבל מכישלון בשמירת-המידע-הפעיל בזיכרון-לטווח-קצר - הפתרון: להשקיע יותר ב<b>שינון</b> (rehearsal) - חזרה-אקטיבית-חוזרת על המידע, ששומרת אותו 'פעיל' בזרקור-הקשב ומונעת ממנו-להתפוגג לפני שמספיקים-להשתמש-בו. ⚠️ אל תתבלבלו עם 'טווח-הזיכרון' (זו קיבולת, לא-פעולה-שאפשר-'להשקיע'-בה) או 'זיכרון-איקוני' (זה חושי-חזותי, לא-רלוונטי-למספרים-מילוליים) - שינון הוא הפתרון-המעשי-הישיר לבעיה-של-'איבוד-מידע-לפני-שימוש'.","mnemo":"🔁 היה-צריך-לחזור (שינון)."},{"id":"quiz6_22","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"קרל לאשלי אימן עכברים במבוכים והסיר כמויות שונות מ___ שלהם: (המוחון / קליפת המוח / הסטריאטום / האמיגדלה)","a":"קליפת המוח (לאשלי לא הצליח לאתר \"מקום\" יחיד לזיכרון, אלא פיזור רחב)","explain":"קרל לאשלי אימן עכברים במבוכים והסיר כמויות-שונות <b>מקליפת-המוח (הקורטקס)</b> שלהם - כפי שנלמד בפרק, זה היה מחקרו המפורסם בניסיון-לאתר את ה'אנגרם' (המיקום-הפיזי של הזיכרון), ומצא שהפגיעה-בביצוע תלויה בכמות הרקמה-שהוסרה, לא-במיקום-הספציפי - ומכאן מסקנתו שהזיכרון מפוזר בקליפת-המוח, לא-ממוקם-במקום-יחיד. ⚠️ אל תתבלבלו עם המוחון/הסטריאטום/האמיגדלה - אלו מבנים-אחרים לגמרי, לא-אלו-שלאשלי התמקד-בהם בניסוי-המבוכים המפורסם.","mnemo":"🧠✂️ לאשלי חתך מקליפת-המוח."},{"id":"quiz6_23","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"הזמן בו מוחזק המידע בזיכרון הסנסורי הינו: (מספר שעות / ללא הגבלת זמן / כדקה / פחות משנייה)","a":"פחות משנייה (זיכרון סנסורי נמשך רק רגע קצרצר לפני שנמחק/מעובד)","explain":"הזיכרון-הסנסורי (כמו הזיכרון-האיקוני, שנלמד בפרוטרוט דרך ניסוי ספרלינג) נמשך <b>פחות-משנייה</b> - זהו זיכרון קצרצר-במיוחד, שמחזיק רושם-חושי-גולמי (חזותי/שמיעתי) לרגע-החטוף בלבד לפני-שהוא נמחק או מועבר-הלאה-לעיבוד-נוסף. ⚠️ אל תתבלבלו עם זיכרון-לטווח-קצר (שנמשך שניות-עד-דקה, לא-פחות-משנייה) - זיכרון-סנסורי הוא השלב-הראשוני-והמהיר-ביותר בכל-שרשרת-הזיכרון, שקודם-אפילו-לזיכרון-לטווח-קצר, ומשמש בעיקר 'לתפוס' את הרושם-החושי-הגולמי לפני שמעבדים אותו הלאה.","mnemo":"⚡ פחות-משנייה = איקוני."},{"id":"prof7_01","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי קוגניציה?","a":"מושג כללי לכל צורות הידיעה - תכנים (מה יודעים) + תהליכים (איך משתמשים בהם).","explain":"<b>קוגניציה</b> היא מושג-מטרייה הכולל שני היבטים גם-יחד: <b>תכנים</b> (מה אנחנו יודעים - עובדות, מושגים, זיכרונות) ו<b>תהליכים</b> (איך אנחנו משתמשים בידע הזה - חשיבה, שיפוט, פתרון-בעיות, שפה). ⚠️ הבנה זו חשובה כמסגרת לכל הפרק: כל הנושאים הבאים (שפה, שיפוט, החלטות) הם דוגמאות ל'תהליכים-קוגניטיביים' ספציפיים - דרכים שונות שבהן אנחנו מפעילים ומעבדים את הידע שיש-לנו.","mnemo":"🧠 יודע + משתמש = קוגניציה."},{"id":"prof7_02","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד מוסבר הפער בזמני התגובה בין מטלה 2 למטלות 1 ו-3 (דונדרס)?","a":"מטלה 2 דרשה שני צעדי קטגוריזציה של גירויים + קטגוריזציה של תגובה, לעומת צעד אחד בלבד במטלות 1 ו-3. יותר צעדים מנטליים = יותר זמן ביצוע.","explain":"שיטת דונדרס למדידת תהליכים-מנטליים מבוססת על עיקרון פשוט: <b>יותר-צעדי-עיבוד = יותר-זמן</b>. במטלה-2, הנבדק נדרש לבצע <b>שני</b> צעדי-קטגוריזציה (לזהות-את-הגירוי, ואז לבחור-את-התגובה-המתאימה) - לעומת מטלות 1 ו-3 שדרשו רק <b>צעד אחד</b>. הפער-בזמן-התגובה בין מטלה-2 לשתי-האחרות מייצג את הזמן-הנוסף שנדרש בדיוק לביצוע-הצעד-הנוסף - זו הדגמה ישירה לכך שאפשר 'למדוד' תהליכים-מנטליים-בלתי-נראים דרך זמן-הביצוע שלהם.","mnemo":"🔢 יותר צעדים = יותר זמן."},{"id":"prof7_03","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"למה משמשת מדידה של זמני תגובה בפסיכולוגיה קוגניטיבית?","a":"לבחון תהליכים קוגניטיביים על סמך ההנחה שצעדים מנטליים נוספים מצריכים יותר זמן ביצוע.","explain":"מדידת זמני-תגובה משמשת ככלי-מחקר מרכזי בפסיכולוגיה-קוגניטיבית, מבוססת על הנחת-יסוד: <b>כל צעד-מנטלי-נוסף (עיבוד, החלטה, קטגוריזציה) מצריך זמן-ביצוע נוסף</b>. לכן, על-ידי השוואת-זמני-תגובה בין מטלות-שונות-במורכבותן (כמו שראינו אצל דונדרס), חוקרים יכולים <b>להסיק בעקיפין</b> כמה שלבים-מנטליים מעורבים בתהליך, גם בלי-יכולת-לצפות-ישירות במה-שקורה 'בתוך הראש'.","mnemo":"⏱️ זמן חושף צעדים חבויים."},{"id":"prof7_04","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהם תהליכים סדרתיים?","a":"בזה אחר זה. כמו לקרוא תפריט מנה-מנה.","explain":"<b>תהליכים סדרתיים (serial)</b> מתבצעים <b>בזה-אחר-זה</b>, אחד-שלם לפני שהבא-מתחיל - אין חפיפה בזמן ביניהם. הדוגמה: קריאת תפריט-מסעדה, מנה-אחר-מנה - קוראים-ומעבדים כל שורה בנפרד, ברצף, לא בו-זמנית. ⚠️ תהליכים-סדרתיים בדרך-כלל דורשים יותר-משאבי-קשב (כפי שנראה בהמשך), כי כל שלב 'תופס' את מלוא-תשומת-הלב לפני שהבא יכול-להתחיל.","mnemo":"1️⃣➡️2️⃣➡️3️⃣ תור, לא בלגן."},{"id":"prof7_05","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהם תהליכים מקבילים?","a":"חופפים בזמן. כמו להבין ולענות למלצר יחד.","explain":"<b>תהליכים מקבילים (parallel)</b> מתבצעים <b>חופפים-בזמן</b> - שני-תהליכים-או-יותר קורים בו-זמנית, בלי שאחד 'ממתין' לשני. הדוגמה: להבין את מה-שהמלצר-אומר <b>וגם</b> לחשוב-על-התשובה שלכם - שני-תהליכים אלה יכולים לקרות-במקביל, לא ברצף-נפרד. ⚠️ תהליכים-מקביליים בדרך-כלל דורשים פחות-משאבי-קשב, ולכן קל-יותר לשלב-אותם עם פעילויות-נוספות בו-זמנית.","mnemo":"🤹 שתיים ביחד, לא בתור."},{"id":"prof7_06","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"האם כל דוגמה מתארת תהליך סדרתי או מקבילי: שקילת קמח/סוכר; טלפון+שרוכים; ריצה+מוסיקה; קריאה+טלוויזיה?","a":"שקילה=סדרתי. טלפון+שרוכים=מקבילי. ריצה+מוסיקה=מקבילי. קריאה+טלוויזיה=סדרתי.","explain":"תרגיל-סיווג ליישום ההבחנה סדרתי/מקבילי על תרחישים-יומיומיים: <b>שקילת קמח וסוכר</b> = <b>סדרתי</b> (שוקלים-אחד, ואז-את-השני, לא-בו-זמנית על-אותו-מאזניים). <b>שיחת-טלפון תוך-כדי קשירת-שרוכים</b> = <b>מקבילי</b> (שתי פעולות-שונות-לגמרי בערוצים-שונים, יכולות-לחפוף). <b>ריצה תוך-האזנה-למוזיקה</b> = <b>מקבילי</b> (תנועה גופנית ועיבוד-שמיעתי לא-מתחרים-ישירות). <b>קריאה תוך-כדי-צפייה-בטלוויזיה</b> = <b>סדרתי</b> (שני ערוצים <b>שפתיים/תוכניים</b> מתחרים על אותם-משאבי-עיבוד-לשוני, ולכן בפועל 'קופצים' ביניהם ברצף-מהיר, לא-באמת-מבינים-את-שניהם-בו-זמנית).","mnemo":"⚖️🎵 שקילה=לבד. שיחה+הליכה=ביחד."},{"id":"prof7_reflection1","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"שרטטו את רצף האירועים (טיול, שיחה, צלצול טלפון) על ציר זמן, וסמנו תהליכים סדרתיים/מקבילים.","a":"הליכה+שיחה=מקבילי (לאורך כל הזמן). צלצול→עצירה→חיפוש בתיק=סדרתי (עצירה קודמת לחיפוש). חיפוש בתיק+סיום המשפט=מקבילי (מתרחשים יחד).","explain":"יישום מפורט של סדרתי/מקבילי על רצף-אירועים-מציאותי - חשוב לזהות כל צמד-פעולות בנפרד: <b>הליכה+שיחה</b> = <b>מקבילי</b>, לאורך כל משך-הטיול (שתי פעולות שונות-לגמרי, ללא-תחרות-ישירה על אותם-משאבים). <b>צלצול→עצירה→חיפוש-בתיק</b> = <b>סדרתי</b> - כל שלב חייב-להסתיים לפני-שהבא-מתחיל (העצירה קודמת-לוגית לחיפוש - אי-אפשר לחפש-בתיק תוך-כדי-הליכה-מהירה ברצינות). <b>חיפוש-בתיק+סיום-המשפט</b> (בשיחה עם החבר, לפני-שעונים-לטלפון) = <b>מקבילי</b> - שתי הפעולות מתרחשות-יחד, חופפות-בזמן.","mnemo":"📞🚶 עצירה חוסמת חיפוש = סדרתי. שאר הדברים = מקבילי."},{"id":"prof7_07","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע זמן תגובה מסייע להבחין בין תהליכים מקבילים לסדרתיים, אך אינו מדד מדויק?","a":"אותו זמן כולל יכול לבוא משני המקורות - נדרשת תלות הכרחית בין הצעדים כדי להכריע.","explain":"זמן-תגובה מסייע להבחין בין סדרתי/מקבילי, אך <b>אינו מדד-מדויק לחלוטין</b>, כי יש בעיה-לוגית: <b>אותו זמן-כולל</b> (למשל, 2 שניות) יכול לנבוע <b>משני-מקורות-שונים</b> - או-כי-שני-תהליכים התרחשו-ברצף (סדרתי, כל-אחד לוקח-זמן-קצר, סה'כ-מצטבר), או-כי-תהליך-אחד-איטי התרחש-לבדו (בלי-קשר-לסדרתיות-בכלל). ⚠️ כדי-להכריע-בביטחון, נדרשת בדיקה של <b>תלות הכרחית</b> בין הצעדים (האם שלב-ב' <b>חייב</b> לחכות לתוצאת-שלב-א'?) - לא רק מדידת-הזמן-הכולל בפני-עצמו.","mnemo":"⏱️❓ זמן שווה, לא תמיד ברור למה."},{"id":"prof7_08","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו את ההבדל בין תהליכים מבוקרים לאוטומטיים באמצעות משאבים מנטליים ותהליכי קשב.","a":"תהליכי קשב מחלקים משאבים מנטליים מוגבלים. תהליכים מבוקרים=דורשים קשב, תובעים משאבים רבים, קשה לבצע כמה בו־זמנית. תהליכים אוטומטיים=אינם דורשים קשב, אפשר לבצעם לצד מטלות אחרות.","explain":"ההבחנה בין תהליכים-מבוקרים לאוטומטיים נשענת על מושג ה<b>משאבים-המנטליים-המוגבלים</b> שהקשב מחלק: <b>תהליכים מבוקרים (controlled)</b> - דורשים קשב-פעיל, 'תובעים' חלק גדול ממשאבי-העיבוד המוגבלים שלנו - ולכן <b>קשה לבצע כמה מהם בו-זמנית</b> (הם מתחרים על-אותו-משאב-מוגבל). <b>תהליכים אוטומטיים (automatic)</b> - <b>אינם דורשים</b> קשב פעיל, ולכן אפשר לבצעם <b>לצד</b> מטלות-אחרות בלי-הפרעה-משמעותית - למשל, הליכה-רגילה (אוטומטית לרוב) לצד שיחה (המבוקרת יותר).","mnemo":"🏋️😌 מבוקר=כבד-משאבים. אוטומטי=קליל."},{"id":"prof7_09","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד קשורים התהליכים המבוקרים/אוטומטיים לתהליכים הסדרתיים/מקביליים?","a":"מבוקר נוטה לסדרתי (תובע משאבים). אוטומטי נוטה למקבילי (לא תובע). לא כלל מוחלט - שלוליות הופכות הליכה למבוקרת וסדרתית.","explain":"החיבור בין שני הצירים בפרק (מבוקר/אוטומטי וסדרתי/מקבילי) מגלה קשר-הדוק, אך <b>לא-מוחלט</b>: תהליך <b>מבוקר</b> נוטה להיות <b>סדרתי</b> (כי הוא תובע-משאבים, קשה לחלוק-אותם עם תהליך-נוסף בו-זמנית). תהליך <b>אוטומטי</b> נוטה להיות <b>מקבילי</b> (לא-תובע-משאבים, יכול לחפוף בקלות עם דברים-אחרים). ⚠️ אך זה <b>לא כלל-מוחלט</b> - ההוכחה: הליכה <b>רגילה</b> אוטומטית-ומקבילית (אפשר לדבר-תוך-הליכה), אבל הליכה <b>בשלוליות</b> (מצריכה זהירות מיוחדת) הופכת <b>מבוקרת וסדרתית</b> - אותה פעולה עצמה יכולה לעבור-מצב תלוי-בתנאים.","mnemo":"🏋️➡️1️⃣ 😌➡️🤹 אבל זה יכול להתחלף."},{"id":"prof7_10","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד מסבירים דאהן ואקהבין את ההבדל בין רשימת מספרים קרובים לרחוקים, ומה לומדים על תהליכים אוטומטיים?","a":"כמות המספר מעובדת אוטומטית - מפריעה יותר כשמספרים קרובים. תרגול הופך מבוקר לאוטומטי.","explain":"מחקר דאהן ואקהבין (השוואת רשימות-מספרים קרובים מול רחוקים) חושף היבט-מרתק של עיבוד-אוטומטי: כשמספרים <b>קרובים</b> זה-לזה (למשל 4 ו-5), הזיהוי <b>איטי-יותר</b> - כי <b>כמות-המספר</b> (הערך-הכמותי) מעובדת <b>אוטומטית</b> תמיד, גם כשלא-רוצים (לא ניתן 'לכבות' את זה) - וכשהמספרים קרובים, ה'הפרעה-האוטומטית' מכמות-דומה חזקה-יותר, מאטה את ההחלטה. <b>המסקנה החשובה</b> על תהליכים-אוטומטיים: <b>תרגול</b> יכול להפוך תהליך <b>מבוקר</b> ל<b>אוטומטי</b> לאורך-זמן - זה בדיוק המנגנון שהופך מיומנויות-חדשות (כמו נהיגה) מתובעניות-קשב בהתחלה, לאוטומטיות-כמעט-לגמרי אחרי-תרגול-רב.","mnemo":"🔢 קרובים=מבלבל. תרגול=אוטומטי."},{"id":"prof7_reflection2","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"זהו את המרכיב הלשוני בכל דוגמה: (א) סדר מילים משפיע על משמעות. (ב) מילה רב-משמעית (\"קרן\"). (ג) מילים נרדפות (\"שמש\"/\"חמה\"). (ד) שאלה המתפרשת כהוראה (\"להעביר מלח\"). (ה) קשר צורני בין מילים (\"מכתב\"-\"כתובת\"). (ו) שינוי הגייה (תי\"ו→צד\"י).","a":"(א) תחביר. (ב) סמנטיקה. (ג) סמנטיקה. (ד) פרגמטיקה. (ה) מורפולוגיה. (ו) פונולוגיה.","explain":"תרגיל-זיהוי חמשת-רמות-הניתוח-הלשוני (מבנה השפה עצמה) - חשוב להבחין בין הרמות השונות: <b>(א) סדר-מילים משפיע-על-משמעות</b> = <b>תחביר</b> (syntax - כללי-הסידור של מילים במשפט). <b>(ב) מילה רב-משמעית ('קרן')</b> = <b>סמנטיקה</b> (semantics - משמעות המילים). <b>(ג) מילים-נרדפות</b> = גם <b>סמנטיקה</b> (עוסק-במשמעות, גם אם המילים-שונות). <b>(ד) שאלה-המתפרשת-כהוראה</b> ('להעביר מלח' כבקשה, לא-שאלה-עובדתית) = <b>פרגמטיקה</b> (pragmatics - שימוש-בשפה בהקשר-חברתי). <b>(ה) קשר-צורני בין-מילים</b> ('מכתב'-'כתובת', מבנה-דומה) = <b>מורפולוגיה</b> (morphology - מבנה-פנימי-של-מילים). <b>(ו) שינוי-הגייה</b> = <b>פונולוגיה</b> (phonology - צלילי-השפה).","mnemo":"🔤 סדר=תחביר. משמעות=סמנטיקה. כוונה=פרגמטיקה. מבנה-מילה=מורפולוגיה. צליל=פונולוגיה."},{"id":"prof7_bihev_lang","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד תסביר הגישה הביהביוריסטית רכישת שפה?","a":"באמצעות חיקוי והתניה אופרנטית - ילד מחקה דיבור מהסביבה, ומקבל חיזוק (תשומת לב, מענה לצרכים) כשמשתמש נכון במילים. שימוש שגוי/לא מובן אינו מקבל חיזוק ופוחת.","explain":"הגישה הביהביוריסטית (בהתאם לעקרונות-סקינר וווטסון שנלמדו קודם בקורס) מסבירה רכישת-שפה <b>ללא</b> הנחת-מנגנונים-מנטליים-מולדים כלשהם - רק דרך <b>חיקוי והתניה-אופרנטית</b>: הילד <b>מחקה</b> דיבור ששומע מהסביבה (למידה-באמצעות-צפייה), ומקבל <b>חיזוק</b> (תשומת-לב-חיובית, מענה-בפועל-לצרכיו) כשהוא משתמש-נכון-במילים - החיזוק מגביר את הסבירות-לשימוש-חוזר-נכון. שימוש שגוי או לא-מובן, לעומת-זאת, <b>לא-מקבל חיזוק</b> (ההורים לא-מבינים, לא-מגיבים כרצוי) - ולכן פוחת עם-הזמן, בדיוק כפי שהתניה-אופרנטית מנבאת. ⚠️ בשאלה הבאה נראה מדוע חומסקי חלק על ההסבר-הפשוט-הזה.","mnemo":"🦜 חיקוי+תגמול, כמו תוכי."},{"id":"prof7_11","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"אילו טיעונים הציג חומסקי בעד אימוץ גישה קוגניטיבית לחקר השפה?","a":"(1) דוברים יוצרים אינסוף משפטים חדשים - לא ניתן להסביר רק בחיקוי, מעיד על מבנים תחביריים סמויים. (2) ילדים רוכשים תחביר תקין ללא שיעורים מפורשים, רק מחשיפה - אי אפשר להסביר בכללי גירוי-תגובה בלבד. מכאן: יש להניח תהליכי עיבוד קוגניטיביים פנימיים בין גירוי לתגובה.","explain":"חומסקי הציג שני טיעונים חזקים המערערים על ההסבר-הביהביוריסטי-הטהור לרכישת-שפה: <b>(1) יצירתיות-לשונית</b> - דוברים יוצרים כל-הזמן <b>משפטים-חדשים-לגמרי</b> שמעולם-לא-שמעו-קודם (ולכן לא-יכלו 'לחקות' אותם) - זה מוכיח שקיימים <b>מבנים-תחביריים-סמויים</b> (כללי-דקדוק פנימיים) שמאפשרים ייצור-אינסופי, לא רק שינון/חיקוי-של-משפטים-ספציפיים. <b>(2) רכישה ללא-הוראה-מפורשת</b> - ילדים רוכשים תחביר-תקין רק <b>מחשיפה</b> (בלי-שיעורי-דקדוק פורמליים) - זה בלתי-אפשרי-להסביר בעזרת-כללי-גירוי-תגובה-פשוטים-בלבד. <b>המסקנה</b>: יש להניח קיום <b>תהליכי-עיבוד-קוגניטיביים-פנימיים</b> (לא-רק גירוי-ותגובה-חיצוניים) שמתווכים בין-הגירוי-לתגובה - זו נקודת-המפנה שהפכה את חקר-השפה לתחום קוגניטיבי.","mnemo":"🧠 ילדים ממציאים משפטים חדשים = לא רק חיקוי."},{"id":"prof7_12","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו את הקשר בין משמעות המשפט למשמעות הדובר.","a":"משמעות המשפט=המשמעות המילולית הפשוטה והקבועה. משמעות הדובר=הכוונה האמתית של הדובר, המשתנה לפי הקשר, גם כשמשמעות המשפט זהה. דוגמה: \"החתולה על המחצלת\" יכול להביע קוד סודי, בקשה, הרגעה, או הכרזה - תלוי בהקשר.","explain":"ההבחנה בין שני 'סוגי-משמעות' חיונית להבנת-תקשורת-אנושית מלאה: <b>משמעות-המשפט</b> - המשמעות-המילולית, ה<b>פשוטה והקבועה</b>, כפי-שהמילים-עצמן-אומרות, ללא-תלות-בהקשר. <b>משמעות-הדובר</b> - ה<b>כוונה-האמתית</b> שהדובר רוצה-להעביר, שיכולה <b>להשתנות לפי-ההקשר</b>, <b>גם כשמשמעות-המשפט זהה</b>. הדוגמה: 'החתולה על-המחצלת' - יכול לשמש <b>קוד-סודי</b> מוסכם-מראש, <b>בקשה</b> (תפנה-את-החתולה), <b>הרגעה</b> (אל-תדאג, החתולה בסדר), או פשוט <b>הכרזה עובדתית</b> - אותם-המילים-בדיוק, ארבע כוונות-שונות-לגמרי, תלוי-בהקשר-השיחה.","mnemo":"📝➡️💭 מילולי מול כוונה אמיתית."},{"id":"prof7_13","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהן שאלות המחקר שחוקרי השימוש בשפה מתמקדים בהן?","a":"(1) כיצד דוברים מפיקים את המילים הנכונות להעברת כוונתם (הפקת שפה)? (2) כיצד שומעים מבינים את המסר המיועד (הבנת שפה)? בנוסף: הקשר אבולוציוני ותרבותי לשימוש בשפה.","explain":"חקר השימוש-בשפה (בניגוד לחקר-המבנה-הפנימי-שלה) מתמקד בשתי שאלות-מחקר-מרכזיות ומשלימות: <b>(1) הפקת-שפה</b> - איך דוברים <b>מפיקים</b> את המילים-הנכונות כדי-להעביר-בהצלחה את כוונתם. <b>(2) הבנת-שפה</b> - איך שומעים <b>מבינים</b> נכון את המסר-המיועד מתוך-הזרם-המילולי-שהם-שומעים. ⚠️ בנוסף לשתי-אלה, החוקרים בוחנים גם את ה<b>הקשר האבולוציוני והתרבותי</b> הרחב-יותר לשימוש-בשפה - למה בכלל התפתחה יכולת-לשונית, וכיצד תרבויות-שונות מעצבות שימוש-בה.","mnemo":"🗣️👂 איך-מדברים + איך-מבינים."},{"id":"prof7_14","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו עקרון שיתוף הפעולה? מה חשיבותו בהפקת שפה?","a":"הנחיית גרייס (1975) לדוברים ליצור מבעים המתאימים לנסיבות השיחה, לפי 4 חוקים: כמות, איכות, קשר, סגנון. חשיבותו: מאפשר תקשורת יעילה - הדובר יכול להעריך כמה מידע לספק ואיך לנסח, בהתבסס על ציפיות מדויקות מהמאזין.","explain":"<b>עקרון שיתוף-הפעולה</b> - הנחיית <b>גרייס</b> (1975) המתארת ציפייה-שקטה שדוברים <b>יוצרים מבעים המתאימים לנסיבות-השיחה</b>, לפי <b>ארבעה חוקים</b>: <b>כמות</b> (לספק מידע-מספיק, לא-יותר-מדי ולא-פחות-מדי), <b>איכות</b> (לומר-אמת, לא-לשקר), <b>קשר</b> (רלוונטיות להקשר-השיחה), ו<b>סגנון</b> (בהירות, ללא-עמימות מיותרת). <b>חשיבותו</b>: מאפשר תקשורת-יעילה-ומהירה - הדובר יכול <b>להעריך מראש</b> כמה-מידע-לספק ואיך-לנסח, בהתבסס על <b>ציפייה מדויקת</b> שהמאזין 'יפרש' את המבע לפי אותם ארבעה חוקים בדיוק - שיתוף-הפעולה 'חוסך' צורך להסביר-כל-פרט-אפשרי.","mnemo":"🤝 4 חוקי דיבור הוגן (גרייס)."},{"id":"prof7_15","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד משפיע הבסיס המשותף על בחירת התוכן של המבעים בפני המאזין?","a":"ככל שהבסיס המשותף (ידע חולק) עם המאזין קטן יותר, כך נדרש תיאור ארוך ומפורט יותר. 3 מקורות לבסיס משותף: חברות בקהילה, נוכחות משותפת בפעולות, נוכחות משותפת בתפיסה. ניסוי הוכיח: אתרים פחות מוכרים לקהילה תוארו במילים רבות יותר.","explain":"<b>הבסיס-המשותף</b> (ידע חולק בין דובר-למאזין) קובע ישירות כמה-פירוט נדרש בתיאור: ככל שהבסיס-המשותף <b>קטן-יותר</b> (פחות ידע-משותף), כך נדרש תיאור <b>ארוך ומפורט-יותר</b> - כדי-לפצות-על-חוסר-ההיכרות-המשותפת. <b>שלושה מקורות</b> לבסיס-משותף: <b>חברות-בקהילה</b> (ידע-כללי-משותף לקבוצה חברתית), <b>נוכחות-משותפת-בפעולות</b> (חוויתם-יחד אירוע), <b>נוכחות-משותפת-בתפיסה</b> (רואים-יחד-כרגע את-אותו-הדבר). <b>ההוכחה הניסויית</b>: אתרים-פחות-מוכרים-לקהילה (בסיס-משותף נמוך) תוארו במילים <b>רבות-יותר</b> מאתרים-מוכרים-היטב (בסיס-משותף גבוה, ניתן-להסתפק-בתיאור-קצר).","mnemo":"📏 פחות-משותף = יותר-מילים."},{"id":"prof7_16","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו ספונריזם? מה אפשר ללמוד ממנו על תהליכים קוגניטיביים של שפה?","a":"החלפת הצליל הראשון של שתי מילים (למשל \"שבורית זכוכה\" במקום \"זכוכית שבורה\"). מלמד ששגיאות דיבור אינן מקריות - הן מצייתות לכללי הדקדוק/הפונולוגיה של השפה (למשל, לעולם לא \"tlips of the sung\"), מוכיח ידע דקדוקי מובנה ולא מודע.","explain":"<b>ספונריזם (Spoonerism)</b> - סוג-שגיאת-דיבור נפוצה, שבה <b>הצליל-הראשון</b> של שתי-מילים מתחלף (לדוגמה: 'שבורית זכוכה' במקום 'זכוכית שבורה'). <b>מה לומדים מכך על תהליכים-קוגניטיביים</b>: שגיאות-דיבור <b>אינן מקריות-לחלוטין</b> - הן <b>מצייתות באופן-עקבי</b> לכללי-הדקדוק/הפונולוגיה של השפה (לעולם לא נשמע צירוף-בלתי-אפשרי-פונטית, כמו 'tlips of the sung' באנגלית - החלפה תמיד יוצרת צירוף-הגייתי-אפשרי). ⚠️ המסקנה: העובדה שאפילו <b>שגיאות</b> מצייתות-לכללים מוכיחה שהדוברים מחזיקים <b>ידע-דקדוקי-מובנה-ולא-מודע</b> על מבנה-השפה - הם 'יודעים' את הכללים גם כשהם טועים, כי הטעות-עצמה מציבה-להם-מגבלות.","mnemo":"🔄 שבורית-זכוכה: טעות עם כללים, לא באקראי."},{"id":"prof7_17","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תארו את שתי הטכניקות ליצירת שיבושים מלאכותיים (SLIP וזיכרון ביטויים) והממצאים/תובנות שלהן.","a":"SLIP (תהליכים): קריאת מודלים פונטיים בשקט, ואז ביטוי צמד יעד בקול. ממצא: שגיאה סבירה יותר כשהתוצאה מילה אמיתית (דירה בלה→בירה דלה, לא דלת בטון→בלת דטון). תובנה: קיים איתור/תיקון שגיאות בהפקת דיבור.\nזיכרון ביטויים (ייצוגים): קריאת צמדי ביטויים, הפסקה, הפקה מהירה מהזיכרון תחת לחץ זמן. ממצא: מיזוג ביטויים דומי-משמעות (\"קור זלעפות\"). תובנה: ביטויים דומים מקושרים בזיכרון.","explain":"שתי שיטות-מחקר מלאכותיות ליצירת שגיאות-שפה, כל-אחת חושפת שכבה-אחרת-של-עיבוד-לשוני: <b>SLIP</b> (בוחן <b>תהליכי-הפקה</b>) - הנבדק קורא-בשקט 'מודלים' פונטיים חוזרים, ואז מבטא-בקול צמד-יעד; <b>הממצא</b>: שגיאה סבירה-יותר <b>כשהתוצאה היא מילה-אמיתית</b> ('דירה בלה' במקום 'בירה דלה', לא 'דלת בטון' במקום 'בלת דטון') - <b>התובנה</b>: קיים מנגנון-איתור/תיקון-שגיאות בהפקת-הדיבור, שסינן חלק-מהשגיאות-הבלתי-אפשריות אך 'החמיץ' שגיאות-שיוצרות-מילה-תקינה-אחרת. <b>שיטת זיכרון-ביטויים</b> (בוחנת <b>ייצוגים בזיכרון</b>) - קריאת צמדי-ביטויים, הפסקה, ואז הפקה-מהירה-תחת-לחץ-זמן; <b>הממצא</b>: מיזוג בין ביטויים <b>דומי-משמעות</b> ('קור זלעפות' - מיזוג של שני ביטויים-קרובים-במשמעות); <b>התובנה</b>: ביטויים דומי-משמעות מקושרים-יחד בזיכרון.","mnemo":"🎯🔗 SLIP=תהליכים(מילה-אמיתית מנצחת). זיכרון-ביטויים=מיזוג-דומים."},{"id":"prof7_18","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד תהליכי איתור שגיאות מסבירים סבירות גבוהה יותר לשגיאה בצמד \"דירה בלה\" מ\"דלת בטון\"?","a":"תהליכי איתור שגיאות תופסים ומתקנים שגיאות המייצרות צירוף חסר משמעות (\"בלת דטון\") אך פחות יעילים כשהתוצאה היא מילה אמיתית אחרת (\"בירה דלה\") - כי הם בודקים בעיקר אם הפלט \"נשמע כמו מילה\", לא אם הוא המילה המתוכננת.","explain":"ההסבר לתופעה שגילה SLIP (שגיאה סבירה-יותר כשהתוצאה 'בירה דלה' מ'בלת דטון') טמון בטבע ה<b>תהליכי-איתור-השגיאות</b>: מנגנון-הבקרה שמפקח על הפקת-הדיבור בודק <b>בעיקר האם התוצאה 'נשמעת-כמו-מילה'</b> - לא-בהכרח האם היא <b>המילה-המתוכננת-במקור</b>. כשהשגיאה יוצרת צירוף-חסר-משמעות ('בלת דטון'), המנגנון <b>תופס ומתקן</b> אותה בקלות (זה בבירור לא-מילה). אבל כשהשגיאה יוצרת <b>מילה-אמיתית-אחרת</b> ('בירה דלה'), המנגנון <b>פחות-יעיל</b> בזיהוי-הבעיה - 'זה נשמע-כמו-מילה תקינה', ולכן חומק ביתר-קלות דרך תהליך-הבקרה, למרות שזו לא-בדיוק-המילה-שהתכוונו-אליה.","mnemo":"🚫 בודקים \"זו מילה?\" - לא \"זו המילה הנכונה?\""},{"id":"prof7_19","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע מיזגו משתתפים בין צמדי ביטויים בעלי משמעות דומה?","a":"ייצוגים של ביטויים דומי-משמעות קשורים זה לזה בזיכרון - הפעלת ביטוי אחד \"מדליקה\" גם את הביטוי הקשור, מה שגורם למיזוג ביניהם (במיוחד תחת לחץ זמן).","explain":"המיזוג בין צמדי-ביטויים דומי-משמעות (כמו 'קור זלעפות') נובע מכך ש<b>ייצוגי-הביטויים</b> בזיכרון-הסמנטי <b>אינם מבודדים</b> - הם <b>מקושרים</b> זה-לזה ברשת-אסוציאטיבית, לפי-קרבת-משמעות. כתוצאה, <b>הפעלת ביטוי-אחד 'מדליקה' באופן-אוטומטי גם את הביטוי-הקשור</b> (בגלל הקרבה-הסמנטית), ותחת <b>לחץ-זמן</b> (כשאין-מספיק-משאבי-בקרה לסנן-בדיוק), שני-הביטויים-המופעלים-יחד <b>מתמזגים</b> לכדי-ביטוי-משולב-חדש - זו הוכחה עקיפה, אך חזקה, למבנה-הרשתי-האסוציאטיבי של הזיכרון-הסמנטי.","mnemo":"🔗💡 ביטוי אחד מדליק את השני."},{"id":"prof7_20","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו את תוצאות ניסוי הייצוגים (מיזוג ביטויים) במונחי פרק הזיכרון.","a":"⚠️ הסבר סינתזה. הזיכרון הסמנטי מאורגן ברשת אסוציאטיבית - ביטויים דומי-משמעות מקושרים ומפעילים זה את זה (הפצת הפעלה). תחת לחץ זמן (פחות משאבי בקרה), הביטוי המופעל חלקית מתערבב עם המכוון - מיזוג. תואם לעקרון: שליפה מדויקת דורשת רמזים שמבודדים פריט מבין קשריו ברשת.","explain":"⚠️ סינתזה המקשרת בין פרק-הזיכרון לפרק-השפה: תוצאות ניסוי-הייצוגים (מיזוג-ביטויים) מוסברות היטב במונחי הידע-שכבר-רכשנו על <b>הזיכרון הסמנטי</b>: הוא מאורגן כ<b>רשת-אסוציאטיבית</b>, שבה ביטויים-דומי-משמעות <b>מקושרים ומפעילים זה-את-זה</b> (תופעת <b>הפצת-ההפעלה</b> - spreading activation). תחת <b>לחץ-זמן</b> (פחות משאבי-בקרה זמינים לסינון-מדויק), הביטוי-שהופעל-חלקית (בזכות-הקרבה-הסמנטית) <b>מתערבב עם</b> הביטוי-המכוון-במקור - וכך נוצר המיזוג. זה תואם היטב לעיקרון-שכבר-נלמד בפרק-הזיכרון: שליפה-מדויקת דורשת <b>רמזים שמבודדים פריט-ספציפי</b> מתוך-כל-קשריו-ברשת - ותחת-לחץ, הבידוד-הזה נכשל, ומידע-קרוב 'מזליג' לתוך התוצאה.","mnemo":"🕸️➡️🔀 רשת מקושרת + לחץ זמן = מיזוג."},{"id":"prof7_21","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי דו־משמעות מילונית? מה נדרש כדי לבטלה?","a":"מילה בודדת, כמה משמעויות (למשל \"אח\"). כולן נגישות בזיכרון בו-זמנית; ההקשר בוחר אחת.","explain":"<b>דו-משמעות מילונית</b> - מילה <b>בודדת אחת</b> בעלת כמה-משמעויות-שונות-לגמרי (למשל 'אח' = בן-משפחה, או תנור-להסקה). <b>מה קורה בעיבוד</b>: כל המשמעויות-האפשריות <b>נגישות בזיכרון בו-זמנית</b> ברגע-שנתקלים-במילה - המוח לא 'בוחר' מראש. <b>מה נדרש כדי לבטל-הדו-משמעות</b>: <b>ההקשר</b> (המשפט הסובב) הוא-שבוחר-ומכריע איזו-משמעות רלוונטית - 'האח שלי הגיע' לעומת 'הדלקתי את האח' מבהירים-מיד איזו-מהמשמעויות פעילה, גם-שהמילה-עצמה זהה.","mnemo":"🔥👨‍👩‍👧🏥 אח=קמין/משפחה/חובש - ההקשר בוחר."},{"id":"prof7_22","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי דו־משמעות מבנית? מה נדרש כדי לבטלה?","a":"אותו רצף מילים, שני ניתוחים דקדוקיים אפשריים. ההקשר מכריע.","explain":"<b>דו-משמעות מבנית</b> - שונה מדו-משמעות-מילונית: כאן <b>אותו רצף-מילים-בדיוק</b> ניתן לניתוח לפי <b>שני מבנים-דקדוקיים-שונים</b> (למשל, 'ראיתי את האיש עם המשקפת' - האם <b>אני</b> החזקתי-משקפת, או <b>האיש</b> החזיק-משקפת?). ⚠️ ההבדל ממילונית: כאן <b>אין</b> מילה-בודדת-רב-משמעית - כל-המילים-ברורות, אבל <b>אופן-חיבורן-הדקדוקי</b> ניתן-לפירוש-בשתי-דרכים. גם כאן, <b>ההקשר</b> (מה-הגיוני-יותר לפי-מה-שאנחנו-יודעים) הוא-שמכריע איזה ניתוח-דקדוקי נכון.","mnemo":"🌳🌳 שני עצי-משפט לאותו המשפט."},{"id":"prof7_23","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד הוכיחו חוקרים שהמוח פועל שונה בעיבוד משפטים דו־משמעיים לעומת חד־משמעיים?","a":"ניסוי fMRI (Rodd et al.) השווה משפטים ברעש/דו-משמעות נמוכה/דו-משמעות גבוהה. נמצאו אזורי מוח ספציפיים פעילים יותר ככל שהדו-משמעות עלתה, גם כשהמשתתפים לא היו מודעים לדו-המשמעות - עדות ביולוגית לעיבוד שונה.","explain":"ניסוי <b>Rodd ועמיתיו</b> (בעזרת fMRI) סיפק הוכחה ביולוגית-ישירה לכך שהמוח מתמודד באופן-שונה עם עיבוד-משפטים-דו-משמעיים לעומת חד-משמעיים: החוקרים השוו תגובת-מוח למשפטים <b>עמוסי-רעש/דו-משמעות-נמוכה/דו-משמעות-גבוהה</b>. <b>הממצא</b>: אזורי-מוח ספציפיים הראו <b>פעילות-גוברת</b> ככל שרמת-הדו-משמעות עלתה - <b>גם כשהמשתתפים-עצמם לא היו-מודעים</b> כלל לקיום-הדו-המשמעות במשפט. ⚠️ המשמעות: עיבוד-דו-משמעות מתרחש ברמה <b>עמוקה ואוטומטית</b> במוח, מעבר-להבנה-המודעת - יש 'עלות עיבודית' אמיתית וניתנת-למדידה-ביולוגית, גם כשלא-מרגישים-שום-קושי-סובייקטיבי.","mnemo":"🧠📸 fMRI: אזורים דולקים יותר בדו-משמעות."},{"id":"prof7_24","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהם היגדים? הציגו דוגמה.","a":"יחידות קטנות המייצגות את הרעיונות המרכזיים של מבע. דוגמה: \"החתולה נמצאת על המחצלת\" = ההיגד \"על (חתולה, מחצלת)\".","explain":"<b>היגדים (propositions)</b> - יחידות קטנות ומינימליות המייצגות את <b>הרעיון-המרכזי</b> (לא-הניסוח-המילולי-המדויק) של מבע. הדוגמה: המשפט 'החתולה נמצאת על המחצלת' מתפרק להיגד הבסיסי <b>'על(חתולה, מחצלת)'</b> - מבנה-לוגי-מופשט (פונקציה+ארגומנטים) שמייצג את <b>המשמעות</b> בלי-כל 'עטיפה' לשונית-ספציפית (סדר-מילים, זמן-הפועל, וכו'). ⚠️ זו בדיוק היחידה-הבסיסית שהמוח שומר, ולא הניסוח-המדויק - עיקרון שמוסבר עוד יותר בשאלה הבאה.","mnemo":"💡 הרעיון המרכזי, לא המילים."},{"id":"prof7_25","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"היעזרו במונח \"היגדים\" כדי להסביר מדוע קשה לזכור מילה במילה שיחה אך זוכרים את עיקרי הדברים.","a":"תהליכי השפה מחלצים את ההיגד (הרעיון המרכזי) מהמשפט, אך הצורה המילולית המדויקת שעטפה אותו הולכת לאיבוד במהירות. לכן זוכרים את המשמעות הכללית, לא את הניסוח המדויק.","explain":"ההסבר לתופעה-המוכרת (זוכרים 'על-מה-דיברו', לא-את-הניסוח-המדויק) נעוץ במושג-ההיגדים: תהליכי-השפה <b>מחלצים את ההיגד</b> (הרעיון-המרכזי-המופשט) מתוך-המשפט <b>ברגע-הבנתו</b>, אך <b>הצורה-המילולית-המדויקת</b> שעטפה-אותו (סדר-המילים-הספציפי, הבחירה-בין-מילים-נרדפות) <b>הולכת-לאיבוד במהירות</b>, כי היא לא-מקודדת-כחלק-מהזיכרון-הארוך-טווח. <b>לכן</b>, אנחנו זוכרים בקלות את ה<b>משמעות הכללית</b> (ההיגד עצמו), אבל מתקשים-מאוד לצטט-במדויק-מילה-במילה, גם-אם-שוחחנו-רק-לפני-דקות.","mnemo":"🎁📦 שומרים את התוכן, זורקים את האריזה."},{"id":"prof7_26","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהם היסקים? הציגו דוגמה.","a":"הסקות לוגיות המשלימות מידע חסר בזיכרון, מעבר למה שנאמר במפורש. דוגמה: \"אני הולך לפגוש את דנה במעדנייה. היא הבטיחה לקנות לי כריך\" - מסיקים ש\"היא\"=דנה, ושמעדנייה=מקום קניית כריכים.","explain":"<b>היסקים (inferences)</b> - הסקות-לוגיות-אוטומטיות שהמוח מבצע כדי <b>להשלים מידע-חסר</b> בזיכרון/בהבנה, <b>מעבר למה-שנאמר-במפורש</b> בטקסט. הדוגמה: 'אני הולך לפגוש-את-דנה במעדנייה. <b>היא</b> הבטיחה לקנות-לי כריך' - למרות שהמשפט-השני לא-חוזר-ואומר-מפורשות 'דנה', אנחנו מסיקים <b>אוטומטית</b> ש'היא'=דנה, וגם ש'מעדנייה'=מקום-שמוכרים-בו-כריכים (עובדת-עולם, לא-נאמרה-בטקסט) - שני היסקים-נפרדים שממלאים-פערים לוגיים כדי-ליצור-הבנה-שלמה-וקוהרנטית.","mnemo":"🧩 ממלאים את החסר מהזיכרון."},{"id":"prof7_27","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד משפיעה יכולת ההיסק על ניסוח משפטים ועל הבנתם?","a":"דוברים מנסחים משפטים קצרים יותר, סומכים שהמאזין ישלים פערים בהיסק. מאזינים מקישים רק היסקים רלוונטיים להקשר - לא את כל האפשריים. ההיסקים תלויים במודל תמונת המצב הכולל (ניסוי קרול: אישיות אלימה מול שוחרת שלום שינתה את ההיסק לאותו משפט סיום).","explain":"יכולת-ההיסק משפיעה בשני-כיוונים-משלימים על תקשורת: <b>בניסוח</b> - דוברים מנסחים משפטים <b>קצרים-יותר</b> מכפי-שהיו-נדרשים-אילו-כל-פרט-נאמר-במפורש, כי הם <b>סומכים</b> על-כך שהמאזין ישלים-בעצמו-פערים-הגיוניים דרך-היסק. <b>בהבנה</b> - מאזינים <b>לא</b> מקישים-את-כל-ההיסקים-האפשריים-תיאורטית, אלא <b>רק</b> את-אלה-הרלוונטיים-להקשר-הנוכחי. ⚠️ ההוכחה שהיסקים תלויים-בהקשר-הכולל: ניסוי <b>קרול</b> - כשתיארו דמות כ'אישיות-אלימה' מול 'שוחרת-שלום', ה<b>היסק</b> שקוראים הפיקו מ<b>אותו משפט-סיום בדיוק</b> השתנה לגמרי, בהתאם לדימוי שנבנה-קודם - ההיסק לא-'קבוע', הוא נגזר-מהמודל-הכולל-של-המצב שכבר נבנה בראש.","mnemo":"✂️ אומרים פחות, סומכים שתשלים."},{"id":"prof7_48","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו שיפוט?","a":"התהליך שבאמצעותו אנו מגבשים דעות, מגיעים למסקנות, ומעריכים אירועים ובני אדם באופן ביקורתי - לעתים קרובות באופן ספונטני.","explain":"<b>שיפוט</b> - התהליך שדרכו אנחנו <b>מגבשים דעות, מגיעים למסקנות, ומעריכים</b> אירועים ובני-אדם - <b>באופן ביקורתי</b>, לרוב <b>באופן ספונטני-ולא-מודע</b> (לא תמיד תהליך-מכוון-ומדעי). ⚠️ שימו לב לניסוח 'ביקורתי-ספונטני' - שיפוט קורה כל-הזמן, גם בלי-שנחליט-במודע-להעריך משהו (למשל, אנחנו שופטים-אינטואיטיבית אמינות-של-מישהו-חדש-שפגשנו, בלי-ניתוח-פורמלי-מכוון).","mnemo":"⚖️ מעריכים ומגבשים דעה."},{"id":"prof7_49","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי קבלת החלטות?","a":"תהליך של בחירה בין חלופות - בחירה ודחייה של אפשרויות זמינות. קשורה יותר בפעולות התנהגותיות.","explain":"<b>קבלת החלטות</b> - תהליך של <b>בחירה בין חלופות</b> - בחירה-ודחייה של אפשרויות-זמינות. ⚠️ הבדילו משיפוט: קבלת-החלטות <b>קשורה יותר לפעולות-התנהגותיות בפועל</b> (מה-אני-עושה) - בעוד שיפוט (השאלה הקודמת) עוסק בעיקר <b>בהערכה/דעה</b> (מה-אני-חושב-על-משהו), ולא-בהכרח-מוביל-מייד-לפעולה - ההבדל בין 'להעריך' ל'לבחור-בפועל' הוא ליבת ההבחנה.","mnemo":"🔀 בוחרים בין אפשרויות."},{"id":"prof7_50","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מה הקשר בין שיפוט לקבלת החלטות?","a":"זיקה הדדית - השיפוט (הערכת מצב/אדם) קודם ומשמש בסיס לקבלת ההחלטה (בחירת פעולה בפועל). דוגמה: שופטים שמישהי מעניינת (שיפוט), ואז מחליטים לקבוע איתה פגישה (החלטה).","explain":"הקשר בין שיפוט לקבלת-החלטות הוא <b>זיקה-הדדית-כרונולוגית</b>: <b>השיפוט</b> (הערכת-מצב/אדם) בדרך-כלל <b>קודם</b> ומשמש <b>בסיס</b> לקבלת-ההחלטה (בחירת-פעולה-בפועל). הדוגמה: קודם <b>שופטים</b> שמישהי-מעניינת (הערכה) - <b>ואז</b> <b>מחליטים</b> לקבוע-איתה-פגישה (בחירת-פעולה-מבוססת-על-אותו-שיפוט). ⚠️ שני התהליכים <b>נפרדים-מושגית</b> (הערכה מול בחירה) אך <b>קשורים-פונקציונלית</b> - כמעט-תמיד השיפוט הוא-שמזין-ומכוון את ההחלטה, לא הפוך.","mnemo":"⚖️➡️🔀 קודם שופטים, אז בוחרים."},{"id":"prof7_51","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהן היריסטיקות (טברסקי וכהנמן)?","a":"\"כללי אצבע\" לא פורמליים המספקים קיצורי דרך ומקטינים את מורכבות השיפוט, במקום ניתוח פורמלי מלא. נובעות מרציונליות מוגבלת (הרברט סימון) - מסתפקים בפתרונות \"טובים מספיק\", לא בהכרח האופטימליים.","explain":"<b>היריסטיקות</b> (Tversky & Kahneman) - 'כללי-אצבע' <b>לא-פורמליים</b> המספקים <b>קיצורי-דרך</b> ומקטינים את מורכבות-השיפוט, <b>במקום</b> ניתוח-פורמלי-מלא-ומאומץ. הן נובעות ממושג ה<b>רציונליות-המוגבלת</b> (הרברט סימון): בני-אדם <b>מסתפקים בפתרונות 'טובים-מספיק'</b>, לא-בהכרח ב<b>אופטימליים</b> - כי ניתוח-מלא-ומדויק-לכל-בעיה תובע-משאבי-זמן-וקוגניציה שלא-תמיד-זמינים. ⚠️ היריסטיקות הן <b>לרוב מועילות</b> (חוסכות-זמן, נותנות תוצאה-טובה-מספיק), אבל מובילות-לפעמים לשגיאות-שיטתיות-וצפויות (הנושא-המרכזי-של-שאר-הפרק).","mnemo":"👍 כלל-אצבע במקום ניתוח מלא."},{"id":"prof7_52","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע כשלים בתהליכים קוגניטיביים מסייעים לחקור את הבסיס לתהליכים אלה?","a":"בדיוק כמו שאשליות תפיסה חושפות מנגנוני תפיסה, וכשלי זיכרון חושפים מנגנוני זיכרון - שגיאות שיפוט (מהיריסטיקות) חושפות את מנגנון השיפוט התקין. אך יש להיזהר: השגיאות אינן המסקנה עצמה - רק לעתים נדירות \"נתקלים בקיר\" אמיתי.","explain":"כשלים-קוגניטיביים (הנובעים-מהיריסטיקות) מסייעים-לחקור את הבסיס-לתהליכים-התקינים, לפי <b>אותה לוגיה מדעית</b> שכבר נתקלנו-בה בפרקים-קודמים: בדיוק כמו ש<b>אשליות-תפיסה</b> חושפות מנגנוני-תפיסה (פרק 4), וכשלי-זיכרון (הפרעה, אפקט-מטעה) חושפים מנגנוני-זיכרון (פרק 6) - <b>שגיאות-שיפוט</b> (הנובעות מהיריסטיקות) חושפות את <b>מנגנון-השיפוט-התקין</b>: אם יודעים <b>מתי ולמה</b> השיפוט 'נכשל', אפשר להסיק גם <b>איך הוא פועל-בדרך-כלל</b>. ⚠️ אזהרה חשובה: יש-להיזהר מהכללת-יתר - השגיאות-עצמן <b>אינן המסקנה-הסופית</b>; רק לעיתים-נדירות 'נתקלים בקיר' שגיאה-אמיתית-וברורה - ברוב-המקרים, ההיריסטיקות עדיין נותנות תוצאות-טובות-מספיק ברוב-המצבים-היומיומיים.","mnemo":"🔍 שגיאות=חלון להבנת התהליך התקין."},{"id":"prof7_53","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי היריסטיקת הזמינות?","a":"בסיס השיפוט על מידע הזמין בזיכרון - ככל שקל יותר לחשוב על מקרים מסוג מסוים, כך שופטים אותם כשכיחים יותר. בדרך כלל מדויק, אך לא תמיד.","explain":"<b>היריסטיקת הזמינות (availability heuristic)</b> - שיפוט המבוסס על <b>מידע-הזמין-בזיכרון</b>: ככל שקל-יותר לחשוב-על-מקרים-מסוג-מסוים (הם 'קופצים-לראש' בקלות), כך שופטים אותם כ<b>שכיחים-יותר</b> במציאות. ⚠️ ברוב-המקרים זה <b>מדויק</b> - דברים-שכיחים-באמת נוטים-להיות-זמינים-יותר בזיכרון, כי נחשפנו-אליהם-הרבה - אך <b>לא-תמיד</b>: כשגורמים אחרים (כמו כיסוי-תקשורתי-מוגזם, או אירוע-רגשי-בולט-במיוחד) 'מזייפים' זמינות-גבוהה-שלא-תואמת-שכיחות-אמיתית, השיפוט נכשל.","mnemo":"🧠 מה שקל להיזכר=נשמע נכון."},{"id":"prof7_54","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד משתקפת היריסטיקת הזמינות במחקר על האות k?","a":"אנשים שפטו שיותר מילים מתחילות ב-k מאשר k כאות שלישית - למרות שבפועל ההפך נכון (פי 2). קל יותר לחשוב על מילים לפי אותן הראשונה (כך מאורגן הזיכרון) - דוגמה לזמינות מוטה מארגון הזיכרון.","explain":"המחקר על האות 'k' ממחיש בצורה-מדויקת את היריסטיקת-הזמינות: אנשים שפטו ש<b>יותר</b> מילים מתחילות ב-k מאשר יש-מילים-עם-k <b>כאות-שלישית</b> - למרות ש<b>בפועל ההפך נכון (פי 2!)</b>. ⚠️ ההסבר: <b>קל-יותר</b> לחשוב-על-מילים לפי-האות-הראשונה-שלהן (כך <b>מאורגן הזיכרון-המילוני</b> שלנו - לפי-'אינדקס' ראשי-אותיות, לא-שלישיות) - לכן מילים-עם-k-בהתחלה <b>זמינות-יותר</b> להיזכרות, מה-שיוצר תחושת-שכיחות-מוטעית. זו דוגמה מובהקת שבה <b>אופן-ארגון-הזיכרון-עצמו</b> (לא רק שכיחות-אמיתית) יוצר הטיית-זמינות.","mnemo":"🔤 K-בהתחלה קל לחשוב, K-שלישית קשה."},{"id":"prof7_55","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהן שתי הסיבות העיקריות שבגללן היריסטיקת הזמינות עלולה להוביל לשיפוט מוטעה?","a":"(א) תהליכי הזיכרון גורמים למדגם המידע שנשלף להיות מוטה (גם אם המידע עצמו נכון). (ב) המידע שאוחסן בזיכרון מלכתחילה אינו מדויק/מייצג.","explain":"שתי סיבות-שונות-לחלוטין שדרכן היריסטיקת-הזמינות עלולה להוביל לשיפוט-מוטעה - הבחנה חשובה שממשיכה בשאלות-הבאות: <b>(א) הטיה בתהליך-השליפה</b> - תהליכי-הזיכרון-עצמם (ארגון, מבנה) גורמים למדגם-המידע-שנשלף <b>להיות מוטה</b>, <b>גם אם המידע-המקורי-עצמו נכון-ומדויק</b> (כמו דוגמת-האות-k). <b>(ב) הטיה בתוכן-האחסון</b> - המידע שאוחסן-בזיכרון-מלכתחילה <b>אינו-מדויק/מייצג</b> את המציאות - הבעיה כבר-בקידוד, לא-רק-בשליפה.","mnemo":"🎣📦 (א) הדיג מוטה. (ב) המאגר עצמו מוטה."},{"id":"prof7_56","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד משתקפת היריסטיקת הזמינות במחקר מצב הרוח (Macleod & Campbell)? איזו סיבה מתוארת?","a":"מצב רוח טוב→נזכרים ביתר קלות באירועים משמחים→שופטים שיקרו יותר אירועים שמחים בעתיד. משקף סיבה א' - תהליכי הזיכרון (מושפעים ממצב רוח) מטים את מדגם המידע הנשלף.","explain":"מחקר-מצב-הרוח (MacLeod & Campbell) מדגים את <b>סיבה-א'</b> (הטיית-שליפה): כשאנשים במצב-רוח <b>טוב</b>, הם <b>נזכרים ביתר-קלות</b> באירועים-משמחים (הזיכרון-הרגשי-החיובי 'זמין-יותר' כרגע) - וכתוצאה, הם <b>שופטים שיקרו-יותר אירועים-שמחים בעתיד</b>. ⚠️ שימו-לב: זה <b>לא</b> קשור לחוסר-דיוק-במידע-שאוחסן (אירועים-משמחים-אמיתיים נשמרו-כראוי) - הבעיה היא ש<b>מצב-הרוח-הרגעי</b> משפיע-על-<b>איזה-מידע נשלף-בקלות-כרגע</b>, מה שמעוות את-השיפוט - זו בדיוק דוגמה ל'סיבה א' - תהליכי-הזיכרון-מטים-את-מדגם-המידע-הנשלף.","mnemo":"😊 מצב-רוח-טוב=זוכר-שמח=מצפה-לשמח."},{"id":"prof7_57","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד משתקפת היריסטיקת הזמינות במחקר שינוי תשובות (Kruger et al.)? איזו סיבה מתוארת?","a":"סטודנטים חושבים ששינוי תשובה מזיק, אך בפועל 51.4% שינויים משפרים לעומת 25.4% שמזיקים. משקף סיבה ב' - הזיכרון עצמו שומר יותר מקרים שליליים (שינוי לרעה) מאשר חיוביים, הטיה במה שנשמר, לא רק בשליפה.","explain":"מחקר-שינוי-תשובות (Kruger et al.) מדגים את <b>סיבה-ב'</b> (הטיית-אחסון): סטודנטים חושבים ששינוי-תשובה-במבחן <b>מזיק</b>, אך בפועל <b>51.4%</b> משינויים <b>משפרים</b> את-הציון, לעומת רק <b>25.4%</b> שמזיקים לו. ⚠️ למה קורה השיפוט-השגוי-הזה: <b>הזיכרון-עצמו שומר-יותר</b> מקרים-שליליים (שינוי-לרעה, שגורם-לכעס/חרטה-חזקים) <b>מאשר</b> מקרים-חיוביים (שינוי-לטובה, שקורה-'בשקט' בלי-רגש-בולט) - זו הטיה <b>בתוכן-מה-שנשמר-מלכתחילה</b> בזיכרון, לא-רק בשליפה - בדיוק 'סיבה-ב'' לפי ההבחנה שראינו קודם.","mnemo":"📦❌ המאגר עצמו שמור מוטה (זוכרים רע יותר מטוב)."},{"id":"prof7_58","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הציגו דוגמה אישית להשפעת היריסטיקת הזמינות על השיפוט שלכם.","a":"⚠️ דוגמה אישית - למשל, שיפוט שגוי: לחשוב שטיסה מסוכנת יותר מנסיעה ברכב אחרי צפייה בכתבות על תאונות טיסה (למרות שסטטיסטית ההפך נכון) - הזמינות (הכתבות הבולטות) מטה את השיפוט.","explain":"⚠️ דוגמה-אישית (יישום-חופשי, לא-ציטוט-מהספר) המדגימה היריסטיקת-זמינות בחיי-יומיום: לחשוב שטיסה <b>מסוכנת-יותר</b> מנסיעה-ברכב, אחרי-צפייה-בכתבות-חדשותיות בולטות-ומדאיגות על-תאונות-טיסה - למרות שסטטיסטית, ה<b>הפך הוא-הנכון</b> (נסיעה-ברכב מסוכנת-בהרבה יותר, לפי-נתונים). ⚠️ ההסבר: הכתבות-הבולטות-והדרמטיות 'זמינות' יותר בזיכרון (בגלל-החדשות המדגישות-אירועים-נדירים-אך-דרמטיים) - הזמינות-המוטה-הזו מכתיבה שיפוט-שגוי-של-הסיכון-האמיתי.","mnemo":"✈️📰 כתבות-תאונות-טיסה=נראה מסוכן, לא באמת."},{"id":"prof7_59","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי היריסטיקת היציגות?","a":"שיפוט לפי הנחה שאם לדבר תכונות טיפוסיות לקטגוריה מסוימת, הוא שייך לה. מבוסס על שימוש במידע מהעבר לשיפוט מצבים דומים בהווה (הסקה אינדוקטיבית).","explain":"<b>היריסטיקת היציגות (representativeness heuristic)</b> - שיפוט המבוסס-על <b>הנחה</b>: אם לדבר יש <b>תכונות-טיפוסיות</b> לקטגוריה-מסוימת, אז <b>הוא שייך-לה</b> (או-סביר-מאוד-ששייך-לה). מבוססת-על <b>שימוש-במידע-מהעבר</b> (מה-שאנחנו-יודעים-על-קטגוריות-טיפוסיות) לשפיטת-מצבים-דומים-בהווה - זו סוג-של <b>הסקה אינדוקטיבית</b> (מהכלל-לפרט/מדוגמאות-מוכרות-לחדשות). ⚠️ הבעיה, כפי-שנראה בשאלות-הבאות, מתעוררת כשהתמקדות-בדימוי-הטיפוסי גורמת להתעלמות-מעובדות-סטטיסטיות-רלוונטיות-יותר.","mnemo":"👔 נראה-כמו=כנראה-הוא."},{"id":"prof7_60","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד משתקפת היריסטיקת היציגות במחקר עורך הדין הירושלמי?","a":"משתתפים בחרו \"טניס\" (מייצג את הדימוי הטיפוסי) על פני \"משחק כדור\" - למרות ש\"משחק כדור\" היא הקטגוריה הרחבה הכוללת את הטניס, ולכן חייבת להיות לפחות סבירה כמוה. היציגות גרמה להזניח את מבנה הקטגוריות.","explain":"מחקר עורך-הדין-הירושלמי ממחיש את <b>הכשל</b> שנוצר מהיריסטיקת-היציגות: משתתפים בחרו ש<b>'טניס'</b> (מייצג את הדימוי-הטיפוסי של עורך-דין-מבוסס) הוא ה<b>יותר-סביר</b> על-פני <b>'משחק-כדור'</b> - למרות ש<b>לוגית-הדוקה</b>, 'משחק-כדור' היא <b>הקטגוריה-הרחבה</b> שכוללת-בתוכה את-הטניס עצמו - ולכן <b>חייבת להיות לפחות סבירה-כמו</b> טניס (אם-לא-סבירה-יותר, כי היא כוללת גם-אפשרויות-נוספות). ⚠️ <b>ההסבר</b>: היציגות (התאמה-לדימוי-הטיפוסי, 'עורכי-דין-משחקים-טניס') גרמה למשתתפים <b>להזניח לגמרי</b> את מבנה-הקטגוריות-הלוגי (כלל-כולל-פרט) - זו טעות-לוגית קלאסית שהיציגות יוצרת.","mnemo":"🎾⚽ טניס \"מרגיש\" נכון, אבל כדור כולל טניס."},{"id":"prof7_61","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הציגו דוגמה אישית להשפעת היריסטיקת היציגות על השיפוט שלכם.","a":"⚠️ דוגמה אישית - למשל, הימנעות מבחירת מספרי הגרלה עם ספרות חוזרות (כמו 333) כי \"לא נראים\" מקריים, למרות שסטטיסטית לכל שילוב אותה הסתברות מדויקת.","explain":"⚠️ דוגמה-אישית (יישום-חופשי) המדגימה היריסטיקת-יציגות: הימנעות מבחירת <b>מספרי-הגרלה עם ספרות-חוזרות</b> (כמו 333333) כי הם 'לא-נראים' מקריים-מספיק (לא-תואמים את הדימוי-הטיפוסי-שלנו ל'רצף-אקראי') - למרות ש<b>סטטיסטית</b>, לכל-שילוב-אפשרי (כולל 333333) יש בדיוק <b>אותה-הסתברות-מדויקת</b> להיבחר כמו-כל-שילוב-אחר-כלשהו. ⚠️ ההיציגות (איך-'נראה' מקרי) מטעה כאן, כי היא מתנגשת עם-המתמטיקה-האמיתית של-הסתברות-שווה-לכל-שילוב.","mnemo":"🎰 333 \"נראה\" פחות מקרי - אך אותה הסתברות."},{"id":"prof7_65","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מיינו כל משפט להיריסטיקה המתאימה: (א) תאונות דרכים מול דלקת ריאות. (ב) יניב מעריך מחיר עוגה במאפייה לפי מחיר בסופר. (ג) שולה מזוהה כעורכת דין לפי מראה.","a":"(א) היריסטיקת הזמינות (תאונות דרכים זמינות יותר בזיכרון מתקשורת, גם אם פחות שכיחות). (ב) היריסטיקת העיגון (30₪ כעוגן, תיקון בלתי מספיק ל-50₪). (ג) היריסטיקת היציגות (מראה מתאים לדימוי הטיפוסי של עורכת דין).","explain":"תרגיל-סיווג-מסכם המחבר-בין-שלוש-ההיריסטיקות שנלמדו: <b>(א) תאונות-דרכים מול דלקת-ריאות</b> = <b>היריסטיקת-הזמינות</b> - תאונות-דרכים <b>זמינות-יותר בזיכרון</b> (מדווחות-דרמטית בתקשורת), גם-אם דלקת-ריאות למעשה-גורמת-ליותר-מקרי-מוות. <b>(ב) יניב מעריך-מחיר-עוגה-במאפייה לפי-מחיר-בסופר</b> = <b>היריסטיקת-העיגון</b> - מחיר-הסופר (למשל 30₪) משמש עוגן, והתיקון-כלפי-מעלה (למחיר-האמיתי, נניח 50₪) לא-מספיק. <b>(ג) שולה מזוהה-כעורכת-דין לפי-מראה</b> = <b>היריסטיקת-היציגות</b> - המראה 'מתאים' לדימוי-הטיפוסי של עורכת-דין, ולכן משפיע-על-השיפוט, בלי-להתחשב בשיקולים-סטטיסטיים-אחרים.","mnemo":"🚗📰 (א)זמינות. 💰(ב)עיגון. 👗(ג)יציגות."},{"id":"prof7_62","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי היריסטיקת העיגון?","a":"השיפוט על ערך/תוצאה מבוסס על תיקון לא מספיק מערך התחלתי (עוגן). אנו נשארים מעוגנים חזק מדי בניחוש הראשוני, גם כשהעוגן חסר תועלת ממשית.","explain":"<b>היריסטיקת העיגון (anchoring heuristic)</b> - שיפוט על ערך/תוצאה המבוסס-על <b>תיקון-לא-מספיק</b> מ<b>ערך-התחלתי</b> (העוגן), גם-כשהעוגן-הזה <b>חסר-תועלת-ממשית</b> או-אפילו-שרירותי-לגמרי. אנחנו <b>נשארים 'מעוגנים' חזק-מדי</b> בניחוש/ברושם-הראשוני, ומתקנים <b>פחות-מדי</b> ממנו לכיוון התשובה-הנכונה-האמיתית - כאילו העוגן 'מושך' את ההערכה-הסופית לקרבתו.","mnemo":"⚓ תקוע קרוב לניחוש הראשון."},{"id":"prof7_63","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד משתקפת היריסטיקת העיגון במחקר אומדן המכפלה (1-8 מול 8-1)?","a":"אותה מכפלה בדיוק (40,320), אך קבוצה שהתחילה מ-1 אמדה חציון 512, וקבוצה שהתחילה מ-8 אמדה חציון 2,250. האומדן החלקי הראשוני (עוגן) קבע את כיוון וגודל התיקון הסופי.","explain":"מחקר אומדן-המכפלה (1×2×3×...×8 מול 8×7×6×...×1) ממחיש את-כוח-היריסטיקת-העיגון בצורה-דרמטית: <b>אותה מכפלה-בדיוק</b> (40,320) - אך <b>קבוצה שראתה 1-8 (סדר-עולה)</b> אמדה חציון של <b>512 בלבד</b>, בעוד <b>קבוצה שראתה 8-1 (סדר-יורד)</b> אמדה חציון של <b>2,250</b> - פער-עצום, למרות שהתוצאה-האמיתית זהה. ⚠️ <b>ההסבר</b>: <b>האומדן-החלקי-הראשוני</b> (מה שרואים-קודם, בשניות-הראשונות של-הכפלה-מהירה-בראש) משמש <b>עוגן</b> - מספרים-קטנים-בהתחלה (1,2,3...) יוצרים-עוגן-נמוך; מספרים-גדולים-בהתחלה (8,7,6...) יוצרים-עוגן-גבוה - העוגן-ההתחלתי קובע את <b>כיוון-וגודל-התיקון-הסופי</b>, גם שהתוצאה-האמיתית זהה-בשני-המקרים.","mnemo":"8️⃣➡️1️⃣ מתחילים גבוה=נשארים גבוה."},{"id":"prof7_64","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע עלולה היריסטיקת העיגון לגרום לטעויות בשיפוט?","a":"אנשים מתקנים באופן בלתי מספיק מהעוגן הראשוני, גם כשהעוגן אינו רלוונטי (מספרי זיהוי אקראיים השפיעו על אומדן מספר רופאים, גם עם אזהרה מפורשת). התיקון נעצר כשהתוצאה \"נשמעת סבירה\", לא כשהיא מדויקת (כמו אומדן מסלול מאדים).","explain":"היריסטיקת-העיגון גורמת לטעויות-שיפוט בשני מנגנונים-מרתקים: <b>(1)</b> אנשים מתקנים <b>באופן בלתי-מספיק</b> מהעוגן-הראשוני, <b>גם כשהעוגן ברור-כלא-רלוונטי</b> - למשל, <b>מספרי-זיהוי-אקראיים לגמרי</b> (שהוצגו למשתתפים כ'לא-קשורים' באזהרה-מפורשת) עדיין השפיעו-משמעותית על אומדן-'כמה-רופאים-יש-בעיר', <b>למרות</b> האזהרה. <b>(2)</b> התיקון <b>נעצר</b> כאשר התוצאה 'נשמעת-סבירה' (מרגישה-נכון סובייקטיבית), <b>לא</b> כשהיא באמת-מדויקת - כפי-שהודגם בדוגמת <b>אומדן-מסלול-מאדים</b> (שגם שם הפער-בין-האמת-לניחוש-נעצר-מוקדם-מדי, ברגע-שהתשובה 'הרגישה-נכון').","mnemo":"🛑 מפסיקים לתקן כשזה \"נשמע סביר\", לא כשזה מדויק."},{"id":"prof7_66","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי \"מסגרת\" בקבלת החלטות?","a":"תיאור מסוים של בעיית בחירה. תפיסת רווח/הפסד תלויה במסגרת (ובנקודות הייחוס/הציפיות), לא רק בעובדות אובייקטיביות. דוגמה: אותה תוספת שכר (300₪) מרגישה כרווח או כהפסד, תלוי בציפיות המקוריות.","explain":"<b>מסגרת (framing)</b> בקבלת-החלטות - <b>תיאור-מסוים</b> (ניסוח, זווית-הצגה) של בעיית-בחירה. הרעיון-המרכזי: תפיסת <b>רווח/הפסד</b> תלויה ב<b>מסגרת ובנקודות-הייחוס/הציפיות</b> - <b>לא רק</b> בעובדות-האובייקטיביות-הגולמיות. הדוגמה: <b>אותה תוספת-שכר בדיוק</b> (300₪) יכולה להרגיש כ<b>רווח</b> (אם ציפו-לפחות) או כ<b>הפסד</b> (אם ציפו-ליותר) - תלוי-לגמרי בציפייה-המקורית, לא-בסכום-עצמו.","mnemo":"🖼️ אותם נתונים, מסגרת שונה."},{"id":"prof7_67","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד משפיע מסגור ההחלטה על קבלת החלטות (רווח מול הפסד)?","a":"אותם נתונים מדויקים, מנוסחים כ\"הישרדות\" (90% שורדים) לעומת \"תמותה\" (10% מתים), משפיעים דרמטית על הבחירה (18% מול 44% בחרו בהקרנות) - גם אצל רופאים מנוסים. מסגור משפיע גם על אופטימיות (תיאור בן/בת זוג כ\"רווח\" לעומת \"הפסד\").","explain":"מחקר-המסגור (רווח מול הפסד) מוכיח כמה-דרמטית ניסוח-שונה-של-אותם-נתונים-בדיוק משפיע-על-החלטות: כשמנוסח כ'<b>הישרדות</b>' (90% שורדים) לעומת '<b>תמותה</b>' (10% מתים) - <b>אותם-נתונים-מדויקים-לחלוטין</b> - הבחירה השתנתה-דרמטית (18% מול 44% בחרו-בהקרנות-רדיולוגיות) - <b>גם אצל רופאים-מנוסים</b>, שאמורים-להיות-מיומנים-בהערכה-אובייקטיבית! ⚠️ מסגור משפיע גם-מעבר-להחלטות-רפואיות: תיאור-בן/בת-זוג כ<b>'רווח'</b> (מה-שקיבלתי) לעומת <b>'הפסד'</b> (מה-שוויתרתי-עליו, כמו רווקות) משפיע גם-על-רמת-האופטימיות-הכללית כלפי-הקשר.","mnemo":"💉90%שורדים=נשמע-טוב. 10%מתים=נשמע-רע. אותו הדבר."},{"id":"prof7_68","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי רתיעה מהחלטה?","a":"נטייה להימנע מקבלת החלטה כלל, מתוך חשש מחרטה עתידית - במקום זאת מעדיפים לדחות את ההחלטה (למשל, לחכות למידע נוסף).","explain":"<b>רתיעה מהחלטה (decision avoidance)</b> - נטייה <b>להימנע מקבלת-החלטה בכלל</b>, מתוך <b>חשש מחרטה-עתידית</b> - במקום-להכריע, מעדיפים <b>לדחות</b> את-ההחלטה (למשל, 'לחכות-למידע-נוסף' גם-כשלא-ברור-שמידע-נוסף-אכן-יעזור). ⚠️ הרתיעה נובעת ישירות מפחד-רגשי (חרטה) יותר-מאשר משיקול-רציונלי-נטו - זו נקודת-החיבור בין-קבלת-החלטות לתחום-הרגש שנלמד בפרק-נפרד.","mnemo":"🙈 מפחד מחרטה=בורח מהחלטה."},{"id":"prof7_69","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע הוספת מידע/אפשרות מגדילה את הסיכוי לרתיעה מהחלטה?","a":"כשהאפשרות הנוספת יוצרת בחירה קשה (בין שני מוצרים טובים), הרתיעה עולה (34%→46%) - נוח יותר לדחות החלטה קשה. אם האפשרות הנוספת קלה להשוואה (מוצר גרוע), הרתיעה דווקא יורדת (24%).","explain":"ממצא-מפתיע לגבי רתיעה-מהחלטה: הוספת-אפשרות/מידע <b>לא-תמיד</b> מקלה על-החלטה - לפעמים <b>מגדילה</b> את הרתיעה. כשהאפשרות-הנוספת יוצרת <b>בחירה-קשה</b> (בין שני-מוצרים-טובים-כאחד), הרתיעה <b>עולה</b> (34%→46%) - כי <b>נוח-יותר לדחות</b> החלטה-שקשה-להכריע-בה. ⚠️ אבל, אם האפשרות-הנוספת <b>קלה-להשוואה</b> (למשל, מוצר-גרוע-בבירור, שקל-לדחות-אותו-מיד), הרתיעה דווקא <b>יורדת</b> (24%) - כי ההשוואה-הפכה-קלה-יותר, לא-קשה-יותר. המסקנה: <b>לא כמות-האפשרויות</b> קובעת רתיעה, אלא <b>קלות-ההשוואה</b> ביניהן.","mnemo":"⚖️ בחירה-קשה=דוחים. אופציה-גרועה=מקלה."},{"id":"prof7_70","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהם שני סוגי מקבלי ההחלטות וכיצד משפיע סגנונם על ההחלטות ועל תחושתם?","a":"\"מסתפקים\"=עוצרים באפשרות מספיק טובה. \"מחפשי שלמות\"=ממשיכים לחפש את הטובה ביותר. במחקר: מחפשי שלמות השיגו משכורת גבוהה ב-20% אך היו הרבה פחות מרוצים, יותר לחוצים ומדוכאים לאורך התהליך.","explain":"שני סגנונות-קבלת-החלטות מנוגדים, עם השלכות-מפתיעות על תוצאות ותחושה: <b>'מסתפקים' (satisficers)</b> - עוצרים ברגע שמוצאים אפשרות <b>'מספיק-טובה'</b>, לא-ממשיכים-לחפש-הלאה. <b>'מחפשי-שלמות' (maximizers)</b> - ממשיכים לחפש <b>את-הטובה-ביותר-האפשרית</b>, בודקים-כל-אופציה. ⚠️ <b>הממצא-המפתיע במחקר</b>: מחפשי-השלמות אמנם השיגו <b>משכורת גבוהה-ב-20%</b> בממוצע (תוצאה-אובייקטיבית-טובה-יותר) - <b>אך</b> היו <b>הרבה-פחות מרוצים</b>, יותר-לחוצים, ואף-יותר-מדוכאים <b>לאורך כל-תהליך-החיפוש</b>. המסר: תוצאה-אובייקטיבית-טובה-יותר <b>לא-מבטיחה</b> תחושה-סובייקטיבית-טובה-יותר - החיפוש-האינסופי-אחר-האופטימלי עצמו גובה מחיר-פסיכולוגי-משמעותי.","mnemo":"🎯😌 מחפש-שלמות=שכר-גבוה+לחוץ. מסתפק=שכר-נמוך+רגוע."},{"id":"quiz7_1","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"למשפט \"אכול מהר ארוחה הערב, בקרוב הכדורגל יתחיל\" יש: (תחביר לא מקובל אך ניתן להבין / תחביר מקובל וניתן להבנה / תחביר לא מקובל ואינו ניתן להבנה)","a":"תחביר לא מקובל, אך ניתן להבין אותו (סדר מילים שגוי דקדוקית, אך המשמעות ברורה)","explain":"המשפט 'אכול מהר ארוחה הערב' מפר כללי-סדר-מילים תקינים (תחביר) - הסדר-הנכון היה 'אכול ארוחת-ערב מהר' - <b>אך למרות זה, המשמעות ברורה לחלוטין</b>. זו הדגמה חשובה: <b>תחביר ומשמעות הם שני-דברים-נפרדים</b> - משפט יכול להיות דקדוקית-שגוי (תחביר-לא-מקובל) ועדיין מובן-לחלוטין, כי המוח משתמש גם-בידע-סמנטי ובהקשר (לא-רק-בכללי-הסדר-הפורמליים) כדי לפענח-משמעות. ⚠️ אל תתבלבלו: 'לא-מקובל' לא-אומר 'לא-מובן' - אלו שני צירים-נפרדים (תקינות-דקדוקית מול מובנות).","mnemo":"🔀✅ סדר שגוי, משמעות ברורה."},{"id":"quiz7_3","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"היתרון הבולט ביותר של שיבושי לשון הוא: (חוק התוצאה / עדות לבניה מחדש בזיכרון / הבנה על תהליכי השפה בבסיס השפה הדבורה / עדות לקשב סלקטיבי)","a":"מספקים הבנה אודות תהליכי השפה הנמצאים בבסיס השפה הדבורה (טעויות חושפות איך המוח מעבד שפה)","explain":"היתרון הבולט-ביותר של חקר שיבושי-לשון (כמו ספונריזם) הוא שהם מספקים <b>הבנה על תהליכי-השפה הנמצאים בבסיס השפה-הדבורה</b> - כפי שנלמד קודם בפרק, שגיאות-דיבור <b>אינן מקריות</b>, אלא מצייתות-לכללי-הדקדוק והפונולוגיה, מה-שחושף ידע-לשוני-מובנה-ולא-מודע. ⚠️ אל תתבלבלו עם 'עדות-לבנייה-מחדש-בזיכרון' - זה מונח-מפרק-הזיכרון (בארטלט), לא-קשור-לשיבושי-לשון; וגם לא-קשור-ל'קשב-סלקטיבי' (מסיבת-הקוקטייל, פרק-4) - שיבושי-לשון עוסקים ספציפית במנגנוני-הפקת-שפה, לא בקשב.","mnemo":"🔍🗣️ טעויות חושפות איך שפה נבנית."},{"id":"quiz7_5","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"היכולת להשתמש בהקשר לפתרון משפטים דו־משמעיים מראה ש: (אי התאמה / התאמה טובה בין הפקה להבנה / אין קשר / פגיעה בהפקה)","a":"קיימת התאמה טובה בין הפקת שפה להבנת שפה (משתמשים באותו הקשר לשני התהליכים גם יחד)","explain":"היכולת להשתמש-באותו-הקשר-בדיוק כדי-לפתור גם דו-משמעות-מילונית וגם דו-משמעות-מבנית (בהפקה ובהבנה כאחד) מראה שיש <b>התאמה טובה בין הפקת-שפה להבנת-שפה</b> - שני התהליכים (לדבר, ולהבין-מה-שמדברים) אינם-מבודדים-זה-מזה, אלא <b>חולקים משאבי-הקשר משותפים</b>: אותו מידע-הקשרי שמסייע-לדובר-לנסח בבירור, מסייע-גם-למאזין-לפרש-נכון - זו עדות לכך ששתי המערכות (הפקה והבנה) בנויות-בצורה-מתואמת ומשלימות-זו-את-זו, לא-פועלות-בנפרד-לגמרי.","mnemo":"🔗 אותו הקשר משרת גם הפקה גם הבנה."},{"id":"quiz7_8","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"שחר הוא טיפוס \"מסתפקים\", לכן נצפה ש: (יצפה בערוץ הראשון שיצוד עינו / לא יהיה מאושר למרות תוספת שכר / מבחן נהיגה בעשרות מכוניות / יטעם כל סוגי הקפה)","a":"יצפה בערוץ הטלוויזיה הראשון שיצוד את עינו (מסתפקים=בוחרים אופציה \"מספיק טובה\", לא הכי טובה)","explain":"שחר, כטיפוס 'מסתפקים' (לא 'מחפש-שלמות'), <b>יצפה בערוץ-הטלוויזיה הראשון שיצוד את עינו</b> - כי מסתפקים עוצרים ברגע שמוצאים אופציה 'מספיק-טובה', ולא-ממשיכים-לחפש-את-הטובה-ביותר-האפשרית (זו הייתה התנהגות-אופיינית-למחפש-שלמות). ⚠️ שאר-האפשרויות ('לא-יהיה מאושר למרות תוספת-שכר', 'מבחן נהיגה בעשרות מכוניות', 'יטעם כל-סוגי-הקפה') מתארות דווקא <b>מחפש-שלמות</b> - התנהגות של חיפוש-ממושך-אחר-האופציה-האופטימלית, המנוגדת-בדיוק לסגנון-ה'מסתפקים' שמאפיין את שחר.","mnemo":"📺 מסתפק=ערוץ ראשון שנראה בסדר."},{"id":"prof8_01","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי תיאוריית ייחוס?","a":"גישה המתארת כיצד אנשים משתמשים במידע כדי לגבש הסברים סיבתיים להתנהגות אחרים. מקורה בהיידר (1958) - בני אדם כ\"פסיכולוגים אינטואיטיביים\" המנתחים סיבתיות בחיי היום־יום.","explain":"תיאוריית הייחוס היא גישה כללית המתארת את הדרכים שבהן אנשים (\"התופסים החברתיים\") משתמשים במידע העומד לרשותם כדי לגבש הסברים סיבתיים להתנהגות של אחרים - כלומר, איך אנו מחליטים \"מדוע\" מישהו התנהג כפי שהתנהג. מקורותיה בעבודתו של פריץ היידר (1958), שטען שבני אדם הם, במידה מסוימת, \"פסיכולוגים אינטואיטיביים\": הם עורכים כל הזמן ניתוחי סיבתיות כחלק מניסיונם להבין את העולם החברתי, בדומה לאופן שבו חוקרים מקצועיים מנסים להבין תופעות.","mnemo":"🕵️ כולם בלשים אינטואיטיביים."},{"id":"prof8_02","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהם, לפי היידר, גורמים פנימיים וחיצוניים?","a":"פנימיים (נטייתיים) = נובעים מתכונות/אישיות/כוונות האדם עצמו. חיצוניים (מצביים) = נובעים מהנסיבות/מהסביבה, לא מהאדם.","explain":"היידר טען שהשאלה המרכזית בכל ניתוח סיבתי היא: האם מקור ההתנהגות טמון באדם עצמו, או בנסיבות/במצב שבו הוא נמצא. גורמים פנימיים (נטייתיים) - סיבות הנובעות מתכונות האופי, מהאישיות או מהכוונות של האדם עצמו. גורמים חיצוניים (מצביים) - סיבות הנובעות מהסביבה או מהנסיבות החיצוניות, שאינן תלויות באישיות האדם.","mnemo":"🧍פנימי=אני. 🌍חיצוני=הסביבה."},{"id":"prof8_03","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו את תיאוריית הייחוס של קלי (השתנות משותפת, ייחודיות, עקיבות, הסכמה).","a":"3 שאלות: ייחודיות (רק כאן?), עקיבות (תמיד?), הסכמה (גם אחרים?) - יחד קובעות ייחוס פנימי/חיצוני.","explain":"הרולד קלי (1967) הרחיב את רעיונותיו של היידר לכדי מודל מפורט יותר. לטענתו, אנשים מגבשים ייחוסים סיבתיים במצבי אי-ודאות, על ידי צבירת מידע ממספר אירועים לאורך זמן, תוך שימוש בעקרון ההשתנות המשותפת: אנו נוטים לייחס התנהגות לגורם מסוים אם אותו הגורם נוכח בעקביות כל אימת שההתנהגות מתרחשת, ונעדר כשהיא לא מתרחשת.\n\nכדי ליישם עיקרון זה, קלי הציע לבחון שלושה סוגי מידע:\nייחודיות - האם ההתנהגות ספציפית למצב מסוים בלבד, או שהיא מופיעה בהרבה הקשרים שונים?\nעקיבות - האם אותה ההתנהגות חוזרת על עצמה בכל פעם שאותו הגירוי מופיע?\nהסכמה - האם אנשים אחרים היו מגיבים באותו האופן, באותו המצב?\n\nשילוב שלושת סוגי המידע הללו מכוון את התופס לבחור בין ייחוס פנימי (הקשור לאישיות/לנטיות האדם) לייחוס חיצוני (הקשור למצב עצמו).","mnemo":"3️⃣ רק-כאן? תמיד? גם-אחרים?"},{"id":"prof8_reflection1","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"נתחו מצב אישי של ייחוס לפי מודל קלי (ייחודיות, עקיבות, הסכמה) - מה יכול לשנות את הייחוס?","a":"⚠️ דוגמה מומחשת - עמית מאחר לישיבה: ייחוס ראשוני פנימי. ייחודיות גבוהה (פעם ראשונה) או הסכמה גבוהה (אחרים גם איחרו) היו הופכים לייחוס חיצוני. השינוי נוגע בעיקר לייחודיות ולהסכמה.","explain":"⚠️ דוגמה מומחשת: קולגה בעבודה איחר לישיבת צוות. הייחוס הראשוני: פנימי (\"הוא לא מכבד את זמנם של אחרים\"). ניתוח לפי קלי: ייחודיות - אם זו פעם ראשונה (ייחודיות גבוהה), מרמז יותר על ייחוס חיצוני. עקיבות - אם הוא תמיד מאחר לישיבות מסוג זה (עקיבות גבוהה), מחזק ייחוס פנימי. הסכמה - אם עוד עמיתים איחרו גם הם (הסכמה גבוהה, אולי פקק תנועה), מסיט לכיוון ייחוס חיצוני. מה יכול לשנות את הייחוס: גילוי שזו הפעם הראשונה או שאחרים איחרו גם כן היה משנה לכיוון ייחוס חיצוני - השינוי נוגע בעיקר לייחודיות ולהסכמה.","mnemo":"🔀 ייחודיות/הסכמה גבוהה = הופך לחיצוני."},{"id":"prof8_05","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי טעות הייחוס הבסיסית?","a":"נטייה להעריך יתר גורמים פנימיים ולהעריך בחסר גורמים חיצוניים בהסבר התנהגות. הודגמה במשחק \"קרב מוחות\" (רוס) - שואלים נתפסו כחכמים יותר, מתעלמים מיתרון המצב עצמו. יש לה שורשים תרבותיים (מערב=פנימי, מזרח=חיצוני).","explain":"<b>טעות הייחוס הבסיסית (fundamental attribution error)</b> - נטייה עקבית ל<b>הערכת-יתר</b> של גורמים-<b>פנימיים</b> (אישיות, תכונות) ו<b>הערכת-חסר</b> של גורמים-<b>חיצוניים</b> (מצב, נסיבות) כשמסבירים התנהגות-של-<b>אחרים</b>. <b>ההדגמה הניסויית</b>: במשחק 'קרב-מוחות' (רוס), שואלים-שאלות נתפסו-כ<b>חכמים-יותר</b> על-ידי הצופים - למרות שתפקיד-השואל <b>מעניק-מלכתחילה יתרון-מבני</b> (יכולים-לשאול-על-מה-שהם-כבר-יודעים), הצופים התעלמו-מהיתרון-המצבי-הזה, וייחסו את-ההצלחה לחוכמה-אישית. ⚠️ יש לתופעה גם <b>שורשים תרבותיים</b>: תרבויות-מערביות (אינדיבידואליסטיות) נוטות-יותר לייחוס-פנימי, בעוד תרבויות-מזרחיות (קולקטיביסטיות) נוטות-יותר לייחוס-חיצוני/מצבי - מה שמראה שהטעות-הזו, למרות-שהיא-'בסיסית', מושפעת-גם-מתרבות.","mnemo":"👉 מאשימים אותו, לא את המצב."},{"id":"prof8_06","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הציגו דוגמה לטעות הייחוס הבסיסית והסבירו כיצד היא מבטאת הערכת יתר/חסר.","a":"⚠️ דוגמה מומחשת - נהג איטי בנתיב המהיר: ייחוס מיידי לחוסר יכולת (פנימי), תוך התעלמות מהסברים מצביים סבירים (תקלה ברכב, זהירות עם ילד ברכב) - הערכת יתר של הפנימי, הערכת חסר של החיצוני.","explain":"יישום-מעשי של טעות-הייחוס-הבסיסית: כשרואים <b>נהג-איטי</b> בנתיב-המהיר, התגובה-האוטומטית היא ייחוס <b>מיידי</b> לתכונה-פנימית (<b>חוסר-יכולת/כישרון-נהיגה</b>) - <b>תוך-התעלמות</b> מהסברים-מצביים-סבירים-לחלוטין (תקלה-ברכב, זהירות-מיוחדת כי-יש-ילד-ברכב, לחץ-דרכים). ⚠️ זו-בדיוק ההדגמה: <b>הערכת-יתר</b> של-הגורם-הפנימי (מיד-קופצים-ל'הוא-נהג-גרוע') ו<b>הערכת-חסר</b> של-הגורם-החיצוני (לא-בודקים-בכלל אם-יש-סיבה-מצבית-הגיונית) - התהליך קורה <b>אוטומטית ומהר-מדי</b>, לפני-שבודקים-חלופות.","mnemo":"🚗 נהג-איטי=\"גרוע\", לא \"אולי תקוע\"."},{"id":"prof8_07","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי הטיה בשירות העצמי?","a":"נטייה לייחס הצלחות לגורמים פנימיים (עצמנו) וכישלונות לגורמים חיצוניים. נמצא אצל סטודנטים (ציונים) ובקבוצות (הצלחת הקבוצה=אני, כישלון=אחרים) - אך נחלש כשמדובר בחברים ולא בזרים.","explain":"<b>הטיה בשירות-העצמי (self-serving bias)</b> - נטייה שיטתית לייחס <b>הצלחות</b> לגורמים <b>פנימיים</b> (כישרוני, המאמץ-שלי) ו<b>כישלונות</b> לגורמים <b>חיצוניים</b> (מזל-רע, נסיבות) - ההפך מטעות-הייחוס-הבסיסית שנלמדה-קודם (שם-מדובר בייחוס-<b>לאחרים</b>; כאן, בייחוס-<b>לעצמנו</b>). <b>ההוכחה</b>: נמצא-עקבית אצל-סטודנטים (ציון-טוב='אני-חכם', ציון-גרוע='המבחן-היה-לא-הוגן') ובקבוצות (הצלחת-הקבוצה='אני-תרמתי', כישלון='אחרים-אשמים'). ⚠️ נקודה מעניינת: ההטיה <b>נחלשת</b> כשמדובר-בהערכת <b>חברים-קרובים</b> (לא-זרים) - כלפי-מי-שאכפת-לנו-מהם, אנחנו-נוטים-להיות-הוגנים-יותר-בייחוס, לא-רק-משרתי-עצמנו.","mnemo":"🏆אני=הצלחה. 🌪️חוץ=כישלון."},{"id":"prof8_08","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הציגו מקרה אישי של הטיה בשירות העצמי.","a":"⚠️ דוגמה מומחשת - הצלחה בעבודה מיוחסת להכנה טובה (פנימי), כישלון בפרויקט אחר מיוחס לתנאים לא הוגנים (חיצוני) - במקום לבדוק אם חסרה תשומת לב לפרטים.","explain":"דוגמה-אישית מומחשת להטיה-בשירות-העצמי: הצלחה-בעבודה מיוחסת ל<b>הכנה-טובה</b> (גורם-<b>פנימי</b> - 'התאמצתי, אני-מוכשר'), בעוד כישלון-בפרויקט-אחר מיוחס ל<b>תנאים לא-הוגנים</b> (גורם-<b>חיצוני</b> - 'לא-נתנו-לי-מספיק-זמן/משאבים') - <b>במקום</b> לבדוק-בכנות אם-אולי-חסרה תשומת-לב-לפרטים (הסבר-פנימי-אלטרנטיבי, שהיה-מתאים-יותר-לכישלון). ⚠️ זו-בדיוק הדגמה למנגנון-ההגנה-העצמית שמאחורי-ההטיה: היא מגנה על-הדימוי-העצמי שלנו, גם-אם-לא-תמיד-מדויקת-אובייקטיבית.","mnemo":"✅אני-טוב. ❌תנאים-רעים."},{"id":"prof8_09","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד באים לידי ביטוי שלבי הנבואה המגשימה את עצמה (תרשים 1) באפקט פיגמליון?","a":"אמונה שרירותית (תלמידים \"מבטיחים\")→התנהגות מורים (חום, דרישות גבוהות, משוב, הזדמנויות)→תלמידים קולטים ציפייה גבוהה→ביצועים משתפרים בפועל (עלייה ב-IQ)→מאששת את האמונה המקורית.","explain":"נקודת המוצא היא אמונה שרירותית: מספר תלמידים נבחרו באקראי לחלוטין וכונו כ'בעלי פוטנציאל אינטלקטואלי מבטיח', ללא כל בסיס אובייקטיבי. מכאן מתגלגל מחזור בארבעה שלבים: (1) התנהגויות המורים כלפי מושא הרושם - המורים התייחסו לתלמידים ה'נבחרים' בחום רב יותר, הציבו דרישות גבוהות יותר, נתנו משוב מיידי וברור יותר, ויצרו הזדמנויות רבות יותר להגיב בכיתה. (2) אמונות התלמידים לגבי מה שמצופה מהם - מתוך ההתנהגות הזו, התלמידים קלטו מסר עקבי שהמורה מצפה מהם להישגים גבוהים. (3) התנהגויות התלמידים - הם השקיעו יותר, השתתפו יותר, וביצועיהם השתפרו בפועל (עלייה ממוצעת של 22 נקודות IQ אצל 30% מהם). (4) חזרה למעגל - השיפור האמיתי אישש בעיני המורים את אמונתם המקורית.","mnemo":"🔮➡️✅ אמונה יוצרת מציאות."},{"id":"prof8_10","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו כיצד גדלה מרים להיות פיזיקאית מחוננת, בעזרת מודל הנבואה המגשימה את עצמה.","a":"⚠️ סיפור מומחש - אמונת האם (כישרון) → השקעה מוגברת (ספרים, חוגים) → מרים קולטת ציפייה גבוהה → משקיעה ומתמידה מרצונה → מצטיינת בפועל → מאשש ומחזק את האמונה המקורית, במעגל נמשך.","explain":"⚠️ סיפור מומחש. אמונת האם מרגע הלידה שיש למרים כישרון מיוחד. (1) התנהגויות האם - האם החלה לספק גירויים אינטלקטואליים מוגברים: צעצועי מדע, ספרים, תשובות מפורטות לשאלות, הרשמה לחוגי מדע. (2) אמונת מרים - היא פיתחה תפיסה עצמית: 'אני טובה במדע, מצפים ממני להצטיין'. (3) התנהגויות מרים - היא השקיעה זמן במדע מרצונה, שאלה שאלות מורכבות, נרשמה לתחרויות, התמידה גם כשקשה. (4) חזרה למעגל - ההצטיינות בפועל חיזקה שוב את אמונת האם ואת אמונת מרים על עצמה, מה שהוביל להשקעה נוספת במעגל שנמשך שנים ובסופו הוביל לקריירה כפיזיקאית מחוננת.","mnemo":"🔄 אמונה→השקעה→הצלחה→אישוש."},{"id":"prof8_11","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי עמדה? הציגו דוגמה.","a":"הערכה חיובית/שלילית כלפי אנשים, עצמים או רעיונות - חלקן אינן גלויות לנו במודע. דוגמה: עמדה חיובית מאוד כלפי שחקן מוערך.","explain":"עמדה היא הערכה חיובית או שלילית כלפי אנשים, עצמים או רעיונות. חשוב לציין: לא כל העמדות שלנו גלויות לנו במודע - ייתכן שאיננו מודעים לעובדה שיש לנו עמדה מסוימת, עד שנשאלים עליה במפורש. דוגמה אישית: עמדה חיובית מאוד כלפי שחקן מוערך - הערכה גבוהה של יכולתו 'להיעלם' בתפקידים באופן משכנע.","mnemo":"👍👎 אוהב/לא-אוהב, גם בלי לדעת."},{"id":"prof8_12","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו את שלושת מקורות המידע לעמדה, ויישמו על הדמות שבחרתם.","a":"קוגניטיבי=מחשבות. רגשי=תחושות. התנהגותי=פעולות בפועל. יכולים להצביע לאותו כיוון (עקביים) או לסתור זה את זה (למשל, לומר שלא אוהבים מישהו אך עדיין לצפות בסרטיו).","explain":"מידע קוגניטיבי - המחשבות שעולות בראשנו ביחס למושא העמדה. מידע רגשי - הרגשות שמתעוררים למשמע השם/החשיבה על המושא. מידע התנהגותי - איך אנו בפועל מתנהגים ביחס למושא.\n\nהאם מצביעים לאותו כיוון: לא תמיד. לפעמים המקורות עקביים (כולם חיוביים או כולם שליליים), אך לפעמים סותרים זה את זה - למשל, אדם עשוי לומר שאינו אוהב שחקן מסוים (קוגניטיבי/מוצהר שלילי) ובכל זאת לרכוש כרטיס לסרטו (התנהגותי חיובי).","mnemo":"💭❤️🏃 חושב+מרגיש+עושה."},{"id":"prof8_13","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"ציינו 2 מצבים המחזקים את הקשר בין עמדות להתנהגות.","a":"(1) עמדה מבוססת התנסות ישירה (לא רק שמיעה/קריאה) - נגישה יותר. (2) חזרה תכופה על ניסוח העמדה (גם כשמשקרים) - מגבירה את נגישותה במחשבה.","explain":"מצב 1 - נגישות העמדה מבוססת התנסות ישירה: עמדה שנוצרה מהתנסות אישית וישירה (לא רק שמיעה/קריאה) נגישה יותר בזיכרון, ולכן מנבאת התנהגות בצורה חזקה יותר.\nמצב 2 - חזרה תכופה על ניסוח העמדה: ככל שמנסחים/חוזרים על עמדה יותר פעמים (אפילו כשמשקרים במכוון), כך העמדה האמיתית נעשית נגישה יותר במחשבה, ולכן משפיעה יותר בעקביות על ההתנהגות.","mnemo":"🖐️🔁 ניסיון-ישיר + חזרה=חזק."},{"id":"prof8_14","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מה ניתן להסיק מטבלאות 16.1 ו-16.2 על הנסיבות המחזקות קשר עמדה-התנהגות?","a":"טבלה 16.1: גם הבעת עמדה כוזבת מגבירה מתאם עמדה-התנהגות (0.54) לעומת קבוצת ביקורת (0.39) - כי מחייבת בחינה מנטלית שמגבירה נגישות. טבלה 16.2: ככל שהעמדה נמדדת ספציפית יותר (תואמת את רמת ההתנהגות הנחזית), המתאם גבוה יותר (0.08→0.57).","explain":"מטבלה 16.1: משתתפים שהביעו עמדה אמיתית חמש פעמים הראו מתאם 0.61 עם התנהגות; מי שהביע עמדה כוזבת (שיקר) חמש פעמים הראה מתאם 0.54 - שניהם גבוהים מקבוצת ביקורת ללא הבעת עמדה (0.39). מסקנה: תהליך ביטוי חוזר של עמדה (גם אם משקרים) מחייב בחינה מנטלית של העמדה האמיתית, מה שהופך אותה לנגישה יותר.\n\nמטבלה 16.2: ככל שהשאלה על העמדה ספציפית יותר (מ'עמדה כלפי אמצעי מניעה' מתאם 0.08, ועד 'עמדה כלפי שימוש בגלולות בשנתיים הקרובות' מתאם 0.57), כך המתאם עם ההתנהגות בפועל גבוה יותר.\n\nמסקנה כוללת: הקשר עמדה-התנהגות מתחזק כשהעמדה נגישה יותר, וכשהיא נמדדת באותה רמת ספציפיות כמו ההתנהגות שרוצים לנבא.","mnemo":"🎯 עמדה ספציפית=מתאם חזק."},{"id":"prof8_15","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תארו את המסלול המרכזי ואת המסלול ההיקפי לשכנוע.","a":"מרכזי=חשיבה מעמיקה, שינוי עמדה תלוי בחוזק הנימוקים (עיבוד גבוה). היקפי=תגובה לרמזים שטחיים (מי מציג, כמה אטרקטיבי), לא לתוכן עצמו (עיבוד נמוך). תלוי במוטיבציה ויכולת לעבד את המסר בזהירות.","explain":"המסלול המרכזי - מתרחש כשאנשים חושבים ברצינות ובמעמקות על תוכן מסר השכנוע, ושינוי עמדתם תלוי בעיקר בחוזק הנימוקים עצמם. זהו עיבוד גבוה.\n\nהמסלול ההיקפי - מתרחש כשאנשים אינם מתמקדים בתוכן המסר עצמו, אלא מגיבים לרמזים שטחיים סביבו (מי מציג, כמה אטרקטיבי, האווירה). זהו עיבוד נמוך.\n\nמה קובע איזה מסלול נבחר: המוטיבציה שלנו לעבד את המסר - האם אנחנו רוצים ומסוגלים לחשוב עליו בזהירות.","mnemo":"🧠 מרכזי=תוכן. 👀 היקפי=מראה."},{"id":"prof8_16","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הציעו 2 דרכי שכנוע לעיריית תל־אביב (מרכזי והיקפי) לשימוש בתחבורה ציבורית.","a":"⚠️ הצעות מומחשות. מרכזי: נתונים מפורטים על חיסכון כספי/זמן וסביבה. היקפי: דמות ציבורית אהודה נוסעת ברכבת הקלה, ללא נתונים, על בסיס אווירה וחיבה בלבד.","explain":"⚠️ הצעות מומחשות. דרך מבוססת מסלול מרכזי: קמפיין המציג נתונים סטטיסטיים מפורטים - חיסכון כספי/זמן, הפחתת זיהום אוויר, מתוך ציפייה שתושבים ישתכנעו מחוזק הטיעונים. דרך מבוססת מסלול היקפי: קמפיין המציג דמות ציבורית אהודה נוסעת ברכבת הקלה, ללא נתונים, מתוך תקווה שהתושבים ישתכנעו מחיבה לדמות ומהאווירה החיובית.","mnemo":"📊 מרכזי=נתונים. ⭐ היקפי=סלבריטי."},{"id":"prof8_17","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי התאמה בין סוג עמדה לסוג טיעון, ומה חשיבותה?","a":"טיעון מבוסס-קוגניציה משכנע יותר עמדה מבוססת-קוגניציה; טיעון מבוסס-רגש משכנע יותר עמדה מבוססת-רגש (הוכח בניסוי קפה/כרטיסי ברכה). התאמה מגבירה סיכוי לשכנוע.","explain":"התאמה פירושה ששכנוע יעיל יותר כאשר סוג הטיעון תואם את סוג המקור שעליו מבוססת העמדה: טיעונים מבוססי-קוגניציה יעילים יותר לשינוי עמדות מבוססות-קוגניציה; טיעונים מבוססי-רגש יעילים יותר לשינוי עמדות מבוססות-רגש. הוכחה מהמחקר: השוואת פרסומות לקפה (עמדה קוגניטיבית) לכרטיסי ברכה (עמדה רגשית) הראתה שהתגובה החיובית ביותר התקבלה כשסוג הפרסומת תאם את סוג העמדה. חשיבותה: מגבירה משמעותית את הסיכוי שהשכנוע יצליח.","mnemo":"🧩 טיעון תואם לסוג העמדה=משכנע יותר."},{"id":"prof8_reflection_elm","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"סכמו את ההבדלים בין מסלול מרכזי למסלול היקפי (טבלה 1).","a":"מרכזי: מעבד תוכן הטיעונים, עיבוד גבוה, דורש מוטיבציה/יכולת, מבוסס קוגניציה. היקפי: מעבד רמזים שטחיים, עיבוד נמוך, לא דורש מוטיבציה/יכולת, מבוסס רגש.","explain":"טבלת-סיכום ל<b>מודל-ELM</b> (Elaboration Likelihood Model) - שני מסלולים-אפשריים לשכנוע: <b>מסלול מרכזי</b> - מעבד את <b>תוכן-הטיעונים-עצמם</b> (איכות-ההיגיון, ראיות), <b>עיבוד-קוגניטיבי-גבוה</b>, דורש <b>מוטיבציה ויכולת</b> (זמן, עניין, ידע) - מבוסס <b>קוגניציה/חשיבה-רציונלית</b>. <b>מסלול היקפי</b> - מעבד <b>רמזים-שטחיים</b> (מי-הדובר, כמה-אנשים-מסכימים, כמה-הוא-מושך) ולא-את-הטיעון-עצמו, <b>עיבוד נמוך</b>, <b>לא-דורש</b> מוטיבציה/יכולת מיוחדת - מבוסס <b>רגש/אינטואיציה-מהירה</b>. ⚠️ המשמעות המעשית: כשאנשים <b>עסוקים/לא-מעוניינים</b>, שכנוע-יעיל-יותר דרך-רמזים-היקפיים (דובר-מושך, הרבה-אנשים); כשמעוניינים-ומרוכזים, נדרש-טיעון-איכותי-אמיתי דרך-המסלול-המרכזי.","mnemo":"🧠תוכן↔️👀שטח."},{"id":"prof8_18","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו דיסוננס קוגניטיבי?","a":"מצב לא נעים של קונפליקט בין התנהגות לעמדות/אמונות קודמות. יוצר מוטיבציה להפחית את אי־הנוחות, בדרך כלל על ידי שינוי העמדה כך שתתאים להתנהגות שכבר בוצעה.","explain":"דיסוננס קוגניטיבי הוא מצב לא נעים של קונפליקט פנימי, שאנו חווים לאחר קבלת החלטה, נקיטת פעולה, או חשיפה למידע הסותר את אמונותינו, רגשותינו או ערכינו הקודמים. פותח על ידי לאון פסטינגר (1957). כאשר יש פער בין ההתנהגות שלנו לבין העמדות/הקוגניציות שלנו, נוצרת תחושה אברסיבית שאנו מנסים באופן פעיל להפחית - לרוב על ידי שינוי העמדה עצמה כך שתתאים להתנהגות שכבר ביצענו.","mnemo":"😣 מעשה נגד אמונה=אי-נוחות."},{"id":"prof8_19","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד תומך ניסוי פסטינגר וקרלסמית' בקיום דיסוננס קוגניטיבי?","a":"סטודנטים שיקרו שהמטלה המשעממת הייתה מעניינת, תמורת 20$ או 1$ בלבד. מי שקיבל רק 1$ (הצדקה חיצונית לא מספקת) שינה בפועל את דעתו האמיתית על המטלה - הוכחה שהשינוי נבע מהפחתת דיסוננס, לא מרצון לכסף.","explain":"סטודנטים באוניברסיטת סטנפורד ביצעו מטלה משעממת במיוחד, ולאחר מכן התבקשו לשקר למשתתף אחר ולומר שהמטלה הייתה מהנה. מחצית קיבלו 20 דולר תמורת השקר, ומחצית קיבלו דולר אחד בלבד.\n\nהיגיון: 20 דולר סיפקו הצדקה חיצונית מספקת - הסטודנטים המשיכו להעריך את המטלה כמשעממת. דולר אחד לא היווה הצדקה מספקת - נותרו עם קוגניציות סותרות, וכדי להפחית את אי-הנוחות, שינו את הערכתם האמיתית ואמרו בכנות שהמטלה הייתה מעניינת.\n\nכיצד זה תומך: התוצאה שדווקא מי שקיבל פחות תגמול שינה יותר את עמדתו מוכיחה שהשינוי לא נבע מרצון 'לזכות בכסף', אלא מהצורך להפחית את הקונפליקט הבלתי נעים.","mnemo":"💵1$>$20 שיקרתי בלי סיבה טובה=באמת שיניתי דעה."},{"id":"prof8_20","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הציגו מצב אישי של דיסוננס קוגניטיבי וכיצד פתרתם אותו.","a":"⚠️ דוגמה מומחשת - רכישת מכשיר יקר בניגוד לעצת חבר, ואז הפחתת הדיסוננס על ידי הפרזה ביתרונות המכשיר וזלזול בעצת החבר.","explain":"⚠️ דוגמה מומחשת: קניתי מכשיר אלקטרוני יקר, בניגוד לעצת חבר. לאחר הרכישה, הרגשתי אי-נוחות - קוגניציה אחת אמרה 'בזבזתי כסף שלא לצורך', אך ההתנהגות (הרכישה) לא הייתה ניתנת לשינוי. פתרתי זאת על ידי הפרזה בהצדקת יתרונות המכשיר וזלזול בעצת החבר - בדיוק כמו דוגמת רכישת המכונית בספר.","mnemo":"💰🗣️ קניתי יקר→משכנע-עצמי-שזה-שווה."},{"id":"prof8_21","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע תופסים דיסוננס קוגניטיבי כתהליך שכנוע עצמי (התנהגות→עמדה, לא להפך)?","a":"בניגוד להנחה הרגילה (עמדה קובעת התנהגות), כאן ההתנהגות שכבר ננקטה (לרוב ללא הצדקה חיצונית מספקת) גורמת לשינוי העמדה כדי ליישב את הסתירה - האדם משכנע את עצמו שהעמדה החדשה נכונה, כדי להצדיק את מעשיו.","explain":"בדרך כלל אנו מניחים שהעמדות שלנו קובעות את התנהגותנו. תיאוריית הדיסוננס הופכת את כיוון הסיבתיות: כאן, ההתנהגות (שכבר ננקטה, לעיתים ללא הצדקה חיצונית מספקת) היא שגורמת לנו לשנות את העמדה, כדי שהעמדה תתיישב עם מה שכבר עשינו. במקום 'אני חושב כך ולכן פעלתי כך', הדפוס הופך ל'פעלתי כך, ולכן חייב להיות שאני חושב כך' - זהו תהליך שכנוע עצמי. חז\"ל זיהו עיקרון דומה: לאפשר לאנשים להתפלל תחילה (התנהגות) - והאמונה (עמדה) תתגבש בעקבות ההתנהגות.","mnemo":"🔄 מעשה→אמונה (לא ההפך)."},{"id":"prof8_22","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי תיאוריית התפיסה העצמית?","a":"אנו מסיקים על עמדותינו/רגשותינו מתוך תצפית על התנהגותנו שלנו, בדיוק כפי שנצפה במישהו אחר. מתרחש בעיקר במצבים לא ברורים/חדשים, שבהם טרם עיצבנו עמדה.","explain":"תיאוריית התפיסה העצמית, שפותחה על ידי דריל בם (1972), מסבירה כיצד אנו לומדים על עצמנו (אמונותינו, עמדותינו, רגשותינו) על ידי תצפית על התנהגותנו שלנו - ממש כפי שנצפה בהתנהגות של מישהו אחר כדי להסיק על מצבו הפנימי. אנו משתמשים בידע הזה כדי לחשוב על הסיבות שקבעו את התנהגותנו, במקום לבחון ישירות את מחשבותינו ורגשותינו. תהליך זה מתרחש בעיקר במצבים לא ברורים או חדשים, שבהם אנו זקוקים לברר את תחושותינו לגבי משהו שטרם עיצבנו לגביו עמדה ברורה.","mnemo":"🪞 מסתכל על עצמי כמו זר."},{"id":"prof8_23","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"השוו בין דיסוננס קוגניטיבי לתפיסה עצמית - מה משותף ומה שונה?","a":"משותף: בשתיהן ההתנהגות משפיעה על העמדה (לא להפך) - סוג של שכנוע עצמי. שונה: דיסוננס כולל קונפליקט/אי־נוחות ומוטיבציה רגשית להפחתה; תפיסה עצמית היא הסקה \"קרה\" ללא קונפליקט, במצבים לא ברורים/חדשים.","explain":"המשותף: בשתי התיאוריות, ההתנהגות שלנו משפיעה על העמדות שלנו - לא ההפך. בשתיהן מדובר בסוג של 'שכנוע עצמי'.\n\nהשוני: דיסוננס קוגניטיבי מתרחש כשיש קונפליקט/אי-נוחות ממשית בין ההתנהגות לעמדה קיימת - יש מוטיבציה רגשית חזקה להפחית תחושה בלתי נעימה. תפיסה עצמית אינה כוללת בהכרח שום קונפליקט - היא פשוט תהליך 'קר' של הסקה: מסתכלים על ההתנהגות ומסיקים ממנה מהי העמדה, בעיקר במצבים חדשים/לא ברורים.\n\nנקודה נוספת: תיאוריית התפיסה העצמית חסרה את מרכיב המוטיבציה/הרגש שקיים בתיאוריית הדיסוננס.","mnemo":"😣 דיסוננס=חם+קונפליקט. תפיסה-עצמית=קר+ללא-קונפליקט."},{"id":"prof8_24","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הציגו מצב אישי המוסבר על ידי תיאוריית התפיסה העצמית.","a":"⚠️ דוגמה מומחשת - הסקת הנאה מריצה מתוך התבוננות בהתנהגות החוזרת (יציאה לריצה מרצון חופשי, ללא כפייה חיצונית), ולא מהחלטה מודעת מראש.","explain":"יישום <b>תיאוריית התפיסה-העצמית (self-perception theory)</b> של בם: לפי-התיאוריה, אנחנו לעיתים <b>מסיקים את-עמדותינו-שלנו</b> מ<b>תצפית</b> בהתנהגותנו-החוזרת, בדיוק-כמו-שהיינו-מסיקים-על-אדם-אחר. הדוגמה: מסיק ש'אני-נהנה-מריצה' <b>לא</b> מהחלטה-מודעת-מראש ('אני-אוהב-לרוץ'), אלא מ<b>התבוננות</b> בעצם-העובדה שיוצא-לרוץ <b>שוב-ושוב מרצון-חופשי</b>, ללא-כפייה-חיצונית - 'אם אני עושה-את-זה-כל-הזמן בלי-שמישהו-מכריח-אותי, אני-בטח-נהנה מזה'. ⚠️ זה מנוגד לתפיסה-האינטואיטיבית (עמדה→התנהגות) - כאן הכיוון <b>הפוך</b>: התנהגות→הסקת-עמדה, במיוחד כשהעמדה-המקורית-הייתה-חלשה/לא-ברורה מראש.","mnemo":"🏃 \"אני רץ כל שבוע - כנראה נהנה מזה\"."},{"id":"prof8_reflection2","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"סווגו 4 דוגמאות לתפיסה עצמית או דיסוננס קוגניטיבי (יעל/ריצ'רד גיר; דני/אוניברסיטה פתוחה; ירון/שידוך; ליאת/עקיפת שיירה).","a":"יעל=תפיסה עצמית (הסקה קרה מהתנהגות). דני=דיסוננס (הצדקת החלטה מחייבת). ירון=תפיסה עצמית (הסקת רגש ממצב חדש/לא ברור). ליאת=תפיסה עצמית (הסקת מוטיבציה מהתנהגות יוצאת דופן).","explain":"יעל ('נראה לי שאני אוהבת את ריצ'רד גיר, שהרי אני אוהבת את סרטיו') - תפיסה עצמית: הסקה קרה מהתנהגות, ללא קונפליקט.\nדני (דעתו על האוניברסיטה הפתוחה השתפרה לאחר הבחירה) - דיסוננס קוגניטיבי: הצדקה בדיעבד של החלטה מחייבת.\nירון ('אם התחתנתי עם גילה סימן שאני אוהב אותה', לאחר שידוך) - תפיסה עצמית: הסקת רגש ממצב חדש/לא ברור, ללא רגשות מגובשים מראש.\nליאת (עקפה שיירה, דבר יוצא דופן, ואז חשבה 'אני חייבת להגיע בזמן') - תפיסה עצמית: הסקת מוטיבציה מהתנהגות יוצאת דופן, ללא קונפליקט ערכי.","mnemo":"🪞 יעל,ירון,ליאת=תפיסה-עצמית. דני=דיסוננס."},{"id":"prof8_25","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי נורמת ההדדיות וכיצד משפיעים באמצעותה?","a":"כלל חברתי: אם מישהו עושה משהו למעננו, אנו מחויבים לגמול לו. אפילו טובה קטנה יוצרת מחויבות להחזיר טובה גדולה. אנשי מכירות מנצלים זאת (דוגמית חינם) - אי־גמילה יוצרת אי־נוחות פסיכולוגית.","explain":"נורמת ההדדיות היא כלל חברתי בסיסי: אם מישהו עושה משהו למעננו, אנו חשים מחויבים לגמול לו. אפילו טובות קטנות מאוד יכולות לגרום לאנשים להחזיר טובות גדולות בהרבה. אנשי מכירות מנצלים זאת: הם 'עושים לנו טובה' (דוגמית חינם) - ואם איננו גומלים, אנו חשים אי-נוחות פסיכולוגית על הפרת הנורמה.","mnemo":"🎁➡️🎁 נתנו לי, אני חייב להחזיר."},{"id":"prof8_26","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי טכניקת הדלת בפרצוף ומה הקשר לנורמת ההדדיות?","a":"סירוב לבקשה גדולה מוביל להיענות רבה יותר לבקשה קטנה שבאה מיד אחריה (50% מול 17%). קשר: הוויתור על הבקשה הגדולה נתפס כטובה, המחייבת גמול לפי נורמת ההדדיות.","explain":"טכניקת הדלת בפרצוף - כאשר אדם מסרב לבקשה גדולה מאוד, הוא נוטה להיענות לבקשה צנועה יותר שמוצגת מיד לאחר מכן. הדגמה: סטודנטים שסירבו לבקשה גדולה (ליווי עבריינים שעתיים בשבוע במשך שנתיים) הסכימו ב-50% לבקשה קטנה (טיול קצר לגן חיות), לעומת 17% בלבד שנשאלו ישירות על הבקשה הקטנה. הקשר לנורמת ההדדיות: כשמבקש הבקשה מוותר על הבקשה הגדולה, זה נתפס כטובה מצדו - מה שיוצר מחויבות לגמול ולהיענות לבקשה החדשה.","mnemo":"🚪😤➡️🚪🙂 סירבתי לגדול, מוכרח להסכים לקטן."},{"id":"prof8_27","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי תחושת מחויבות וכיצד משפיעים באמצעותה?","a":"לאחר שאדם מתחייב לדבר קטן, גדל הסיכוי שיסכים לדבר גדול יותר - כי סירוב מאוחר יותר יגרום לו להיראות לא עקבי/טיפשי ביחס להתחייבותו הראשונית.","explain":"תחושת מחויבות - לאחר שאדם מסכים/מתחייב לדבר קטן, גדל הסיכוי שיסכים גם לדבר גדול יותר באותו כיוון. אנשי מכירות מנצלים זאת על ידי גרימת הלקוח לקבל החלטה ראשונית קטנה, ואז שינוי הדרגתי של העסקה - הלקוח מרגיש שאם יסרב עכשיו, הוא ייראה לא עקבי או טיפשי ביחס להתחייבותו הראשונית.","mnemo":"🔗 התחייבתי קטן=קשה לסגת."},{"id":"prof8_28","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי טכניקת רגל בדלת?","a":"היענות לבקשה קטנה מגבירה סיכוי להיענות לבקשה גדולה יותר מאוחר יותר (למשל, חתימה על עצומה → הצבת שלט גדול). מבוססת בעיקר על תחושת המחויבות/העקביות.","explain":"טכניקת רגל בדלת - אנשים שנענו לבקשה קטנה (חתימה על עצומה) נוטים אחר כך להיענות ביתר קלות לבקשה גדולה מהסוג הדומה (הצבת שלט גדול על הדשא). ⚠️ הבסיס הפסיכולוגי של טכניקה זו קרוב יותר לתחושת המחויבות מאשר לנורמת ההדדיות עצמה - ברגע ש'שמים רגל בדלת', מנצלים את תחושת המחויבות/העקביות שנוצרה כדי להגביר היענות לבקשה מאוחרת וגדולה יותר.","mnemo":"🦶🚪 רגל בפנים=אי אפשר לסגור."},{"id":"prof8_29","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו באמצעות דיסוננס קוגניטיבי מדוע טכניקת רגל בדלת עובדת.","a":"⚠️ הסבר סינתזה. הסכמה ראשונית קטנה יוצרת תפיסה עצמית כ\"תומך במטרה\". סירוב לבקשה גדולה יותר, באותו הכיוון, היה יוצר דיסוננס עם ההתנהגות הקודמת - ולכן, כדי להישאר עקבי, נוטים להיענות גם לבקשה הגדולה.","explain":"⚠️ הסבר סינתזה. לאחר שאדם מסכים לבקשה הקטנה הראשונה, הוא מפתח תפיסה עצמית חדשה: 'אני אדם התומך במטרה הזו'. כאשר לאחר מכן מתבקש בבקשה גדולה יותר באותו הכיוון, סירוב ייצור דיסוננס בין ההתנהגות הראשונה (החתימה, שהביעה תמיכה) לבין ההתנהגות השנייה (הסירוב, הסותר את התמיכה שהביע). כדי להישאר עקבי עם דימויו העצמי כתומך, האדם נוטה להיענות גם לבקשה הגדולה.","mnemo":"🔄 עקביות עם רגל-בדלת=דיסוננס אם מסרב."},{"id":"prof8_30","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו עקרון הנדירות וכיצד משפיעים באמצעותו?","a":"דברים נדירים/קשים להשגה נתפסים כערכיים יותר. הוכח בניסוי עוגיות (2 בצנצנת נתפסו כטעימות יותר מ-10 זהות). אנשי מכירות מנצלים (\"האחרון שנשאר\") כדי ליצור תחושת הזדמנות שתוחמץ.","explain":"בני אדם נוטים להעריך יותר דברים שנראים נדירים או קשים להשגה. הדגמה: משתתפים דירגו את טעמן של עוגיות זהות גבוה יותר כשהיו בצנצנת עם שתיים בלבד, לעומת צנצנת עם עשר עוגיות זהות. אנשי מכירות מנצלים זאת ('זה האחרון שנשאר לי') כדי לעורר תחושה שנחמיץ הזדמנות אם לא נרכוש עכשיו.","mnemo":"🍪2️⃣>🍪🔟 נדיר=טעים יותר."},{"id":"prof8_31","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הציעו 3 תוכניות (הדדיות, מחויבות, נדירות) לעידוד שימוש בתחבורה ציבורית.","a":"⚠️ הצעות מומחשות. הדדיות: מתנה קטנה חינם לפני הבקשה. מחויבות/רגל בדלת: התחייבות קטנה (נסיעת ניסיון) ואז הצעה גדולה (מנוי). נדירות: הנחה מוגבלת ל-500 הראשונים/שבוע בלבד.","explain":"⚠️ הצעות מומחשות. נורמת ההדדיות: נציגי העירייה מחלקים מתנה קטנה חינמית (כרטיס נסיעה יחיד) לפני שמבקשים משהו. תחושת מחויבות (רגל בדלת): מבקשים תחילה התחייבות קטנה (נסיעת ניסיון), ואז חוזרים עם הצעה גדולה (מנוי חודשי מוזל). עקרון הנדירות: הקמפיין מדגיש הצעה מוגבלת בזמן - 'רק 500 מנויי היכרות ראשונים, ההצעה מסתיימת בעוד שבוע'.","mnemo":"🎁🔗💎 מתנה/התחייבות-קטנה/מוגבל-בזמן."},{"id":"prof8_32","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי דעה קדומה?","a":"עמדה נלמדת כלפי קבוצת מטרה, המשלבת רגשות שליליים (עוינות/פחד), אמונות שליליות (סטריאוטיפים), וכוונה התנהגותית שלילית (הימנעות, שליטה, פגיעה). אינה משתנה גם מול ראיות סותרות.","explain":"דעה קדומה היא עמדה נלמדת כלפי קבוצת מטרה, המשלבת שלושה יסודות: רגשות שליליים (עוינות/פחד), אמונות שליליות (סטריאוטיפים) המצדיקות את העמדה, וכוונה התנהגותית להימנע ממגע עם בני הקבוצה, לשלוט בהם או לפגוע בהם. אמונה כוזבת נחשבת לדעה קדומה במיוחד כשהיא אינה משתנה גם כשמוצגות ראיות מוצקות המפריכות אותה.","mnemo":"😠💭🚫 שונא+חושב-רע+מתרחק."},{"id":"prof8_33","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד באים לידי ביטוי שלושת מרכיבי העמדה (ABC) בדעה קדומה?","a":"קוגניטיבי=סטריאוטיפים/אמונות שליליות. רגשי=עוינות/פחד/גועל. התנהגותי=כוונה להימנע ממגע, לשלוט, לפגוע. המרכיבים מזינים זה את זה.","explain":"מרכיב קוגניטיבי (מחשבות) - הסטריאוטיפים והאמונות השליליות כלפי קבוצת המטרה. מרכיב רגשי (רגשות) - תחושות שליליות ישירות כלפי חברי הקבוצה - עוינות, פחד, גועל. מרכיב התנהגותי (פעולות) - כוונה או נטייה להימנע ממגע, לפעול נגדם, לשלוט בהם. שלושת המרכיבים מזינים זה את זה: האמונה השלילית מצדיקה את הרגש השלילי, ושניהם יחד מובילים לכוונה להתנהגות מפלה.","mnemo":"💭😠🚫 סטריאוטיפ+עוינות+הימנעות."},{"id":"prof8_34","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע קשה להפריך דעות קדומות?","a":"עמידות בפני הפרכה היא תכונה מגדירה של דעה קדומה - היא פועלת כפילטר מוטה, המעצב את הפרשנות עוד לפני שהראיות מתקבלות, כך שראיות סותרות נבלעות במסגרת הקיימת.","explain":"מעצם ההגדרה, דעה קדומה נחשבת כזו כאשר היא אינה משתנה גם כשמציבים מולה ראיות מוצקות המפריכות אותה - כלומר, עמידות בפני הפרכה היא תכונה מגדירה שלה. הדעה הקדומה פועלת כפילטר מוטה: היא משפיעה על האופן שבו אנו תופסים ומפרשים אנשים מרגע שסיווגנו אותם לקטגוריית 'קבוצת מטרה' - כך שגם ראיות סותרות נוטות 'להיבלע' בתוך המסגרת הקיימת.","mnemo":"🧊 מסנן שמעצב את הראיות מראש."},{"id":"prof8_35","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי קטגוריזציה חברתית? דונו בקבוצות פנים/חוץ.","a":"תהליך מיון סביבתנו החברתית ל\"אנחנו\" (קבוצות פנים, מזדהים) מול \"הם\" (קבוצות חוץ). קורה במהירות רבה גם על בסיס קטגוריה שרירותית וחסרת משמעות (ניסוי צבעים בהולנד).","explain":"קטגוריזציה חברתית היא התהליך שבו בני אדם מארגנים את סביבתם החברתית על ידי מיון עצמם ואחרים לקבוצות. הצורה הפשוטה והשכיחה ביותר: קביעה האם אחרים דומים לנו - התפתחות מ'אני מול לא-אני' ל'אנחנו מול הם'.\n\nקבוצות פנים - קבוצות שאנו משתייכים אליהן ומזדהים אתן.\nקבוצות חוץ - קבוצות שאיננו מזדהים אתן.\n\nהדגמה: בניסוי בהולנד, משתתפים חולקו באקראי לחלוטין לקבוצת 'כחול' וקבוצת 'ירוק' - קטגוריה שרירותית לחלוטין. ובכל זאת, המשתתפים העריכו את חברי קבוצתם חיובית יותר, עוד לפני שהחלו לעבוד יחד - מוכיח שקטגוריזציה חברתית מתרחשת במהירות רבה.","mnemo":"👥⚔️👥 אנחנו מול הם, גם משרירותי."},{"id":"prof8_36","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי הטיית קבוצת הפנים?","a":"נטייה להעריך את קבוצתנו כטובה יותר מקבוצות אחרות. בדרך כלל מבטאת העדפה לקבוצת הפנים (רגשות חיוביים) ולא בהכרח הטיה שלילית פעילה כלפי קבוצת החוץ (רגשות ניטרליים) - אך יכולה להחמיר כשמצטרפות דעות קדומות נלמדות.","explain":"הטיית קבוצת הפנים היא הנטייה להעריך את הקבוצה שאנו משתייכים אליה כטובה יותר מקבוצות אחרות. חשוב: מרבית בני האדם מגלים בעיקר העדפה לחברי קבוצתם (רגשות חיוביים), ולא בהכרח הטיה שלילית פעילה נגד קבוצת החוץ (רגשות ניטרליים כלפיה) - אפשר לגלות הטיית קבוצת פנים מבלי שיהיו לנו רגשות שליליים היוצרים דעה קדומה ממש. עם זאת, במקרים שרגשותינו כלפי קבוצת החוץ מונחים על ידי דעות קדומות נלמדות, ההטיה עלולה להיות מזיקה הרבה יותר.","mnemo":"❤️עצמי, 😐אחרים (לא בהכרח שנאה)."},{"id":"prof8_37","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהם סטריאוטיפים?","a":"הכללות המייחסות אותם מאפיינים לכל חברי קבוצה מסוימת, ללא הבחנה בין פרטים. מקודדים ציפיות חזקות, תומכים בדעות קדומות.","explain":"סטריאוטיפים הם הכללות לגבי קבוצת בני אדם, המייחסות את אותם המאפיינים לכל חברי הקבוצה, ללא הבחנה בין פרטים. סטריאוטיפים משמשים כמבני זיכרון התומכים בדעות קדומות ומקודדים ציפיות עזות - לעיתים עד כדי כך שהם תורמים ליצירת המציאות החברתית עצמה (דרך אישור התנהגותי).","mnemo":"🏷️ תווית אחת לכולם."},{"id":"prof8_38","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו תפקיד הסטריאוטיפים במילוי נתונים חסרים?","a":"כשחסר מידע ישיר על אדם/מצב, אנו שואבים מידע מהסטריאוטיפ כדי \"למלא\" את החסר, ולהחליט/לשפוט על סמך שיוך קבוצתי בלבד, בלי לבדוק את הפרט הספציפי.","explain":"במצבים חברתיים עמומים, שבהם אין לנו את כל המידע הדרוש כדי לשפוט מצב או אדם, אנו נוטים לשאוב מידע מהסטריאוטיפים שלנו כדי להשלים את החסר - למשל, ההיגיון 'אני לא נכנס למכונית עם X כי כל בני קבוצתו הם נהגים גרועים' משתמש בסטריאוטיפ כדי 'למלא' את המידע החסר על יכולת הנהיגה האישית, בלי לבדוק זאת ישירות.","mnemo":"🧩 ממלאים חוסר-מידע בתווית."},{"id":"prof8_39","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד סטריאוטיפים על קבוצתנו משפיעים עלינו (איום סטריאוטיפ)?","a":"מודעות לסטריאוטיפ שלילי רלוונטי לקבוצתנו (גם בלי להאמין בו) פוגמת בביצועינו בפועל במצב הרלוונטי (למשל, ביצועי מבחן). גם אנשים ללא דעות קדומות מודעות עלולים לפעול אוטומטית לפי סטריאוטיפים שהפנימו.","explain":"איום הסטריאוטיפ, מונח שטבע קלוד סטיל, מתרחש כאשר אדם מוצב במצב הרלוונטי להיבט שלילי של סטריאוטיפ החל על קבוצתו - והמודעות לסטריאוטיפ הזה פוגמת בביצועיו בפועל. לדוגמה: ביצועי אפרו-אמריקנים במבחני יכולת נפגמים כאשר הם מאמינים שהתוצאה רלוונטית לסטריאוטיפ תת-הישגיות. עצם המודעות לקיום הסטריאוטיפ (גם בלי להאמין בו) יוצרת לחץ נוסף הפוגם בביצוע. נקודה נוספת: גם אנשים שאינם תופסים את עצמם כבעלי דעות קדומות עלולים לפעול באופן אוטומטי ולא מודע בהתאם לסטריאוטיפים שהפנימו מהסביבה.","mnemo":"😰 מודע-לתווית=מבצע-פחות-טוב."},{"id":"prof8_40","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"נכון/לא נכון (מחקר שריף - מחנה הקיץ): (א) מידע סותר מספיק להפריך סטריאוטיפ. (ב) די בהפגשה בין קבוצות. (ג) משימה משותפת מפחיתה דעות קדומות.","a":"(א) לא נכון - מידע נוטה \"להיבלע\" ואף מחזק את העמדה המקורית. (ב) לא נכון - מגע גרידא (אפילו לא-תחרותי) לא הפחית עוינות בין הנשרים לנחשים. (ג) נכון - מטרה משותפת הדורשת שת\"פ (משאית מקולקלת) פוגגה את העוינות.","explain":"(א) לא נכון - במחקר על דעות קדומות כלפי הומוסקסואלים, סטודנטים בעלי דעות קדומות דירגו נמוך יותר את איכות המחקר המפריך את הסטריאוטיפ, ואף דיווחו שאמונותיהם התחזקו לכיוון עמדתם המקורית.\n(ב) לא נכון - במחקר מחנה הקיץ של שריף, הנערים ('נשרים' ו'נחשים') המשיכו לחוש עוינות גם לאחר שהופגשו בסיטואציות לא תחרותיות, ואף בעת צפייה משותפת בסרט.\n(ג) נכון - כשהנסיינים יצרו מצב שדרש שיתוף פעולה הכרחי להשגת מטרה משותפת (משיכת משאית מקולקלת), העוינות התפוגגה, ואף נוצרו חברויות שחצו את גבולות הקבוצה - תומך בהשערת המגע: הפחתת דעות קדומות דורשת קשרי גומלין אישיים בתהליך הגשמת מטרה משותפת.","mnemo":"❌מידע-לבד. ❌מגע-לבד. ✅מטרה-משותפת."},{"id":"prof8_reflection3","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו את מחשבות/התנהגות הלגה (ריאיון אמיר) בעזרת קטגוריזציה חברתית, דעות קדומות וסטריאוטיפים.","a":"⚠️ יישום מומחש. קטגוריזציה: הלגה סיווגה מיידית את אמיר כ\"קבוצת חוץ\" (מוסלמי) לעומת המועמד האחר (\"קבוצת פנים\"). סטריאוטיפים: שאבה אמונות שליליות קיימות למלא מידע חסר על אמיר כפרט. דעה קדומה: העדיפה את המועמד הפחות מתאים - עמדה שלילית שגברה על עובדות (כישורים).","explain":"⚠️ יישום מומחש. קטגוריזציה חברתית: מרגע שהלגה זיהתה את אמיר כ'מוסלמי', היא סיווגה אותו מיידית לקטגוריית 'קבוצת חוץ', ואת המועמד האחר לקטגוריית 'קבוצת פנים'. סטריאוטיפים: על סמך שיוכו של אמיר, ייתכן שהלגה שאבה סטריאוטיפים קיימים כדי 'למלא' מידע חסר על אמיר כפרט, במקום להעריך את כישוריו האמיתיים. דעה קדומה: ההערכה השלילית הכוללת של הלגה כלפי אמיר, למרות כישוריו העדיפים, משקפת דעה קדומה - עמדה שלילית נלמדת שהובילה לכוונה התנהגותית מפלה.","mnemo":"🏷️➡️😠➡️❌ תווית→עוינות→בחירה מוטה."},{"id":"prof8_41","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו תפקיד חברתי?","a":"דפוס התנהגות שהחברה מגדירה, שמצפים מאדם למלא בסביבה/קבוצה נתונה. תפקידים שונים (ילד, סטודנט, חבר) קובעים אילו התנהגויות מתאימות במצב נתון.","explain":"תפקיד חברתי הוא דפוס התנהגות שהחברה מגדירה, שמצפים מאדם למלא כשהוא פועל בסביבה נתונה או בקבוצה נתונה. מצבים חברתיים שונים מזמנים תפקידים שונים - 'הילד' בבית, 'הסטודנט' בכיתה, 'החבר הכי טוב' בהזדמנויות אחרות. כל תפקיד קובע מיד אילו התנהגויות מתאימות וזמינות.","mnemo":"🎭 תפקיד=תסריט שהחברה כתבה."},{"id":"prof8_42","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"אילו תפקידים חברתיים היו בניסוי בית הכלא בסטנפורד?","a":"\"סוהרים\" ו\"אסירים\", בחלוקה אקראית (הטלת מטבע) בין מתנדבים שנבחרו כיציבים ונורמליים מראש.","explain":"בניסוי-בית-הכלא-של-סטנפורד, המתנדבים (שנבחרו-מראש כ<b>יציבים ונורמליים</b> פסיכולוגית) חולקו ל<b>שני תפקידים-חברתיים</b>: <b>'סוהרים'</b> ו<b>'אסירים'</b>, ב<b>חלוקה אקראית-לחלוטין</b> (הטלת-מטבע) - כלומר, <b>לא</b> לפי-אישיות/נטייה-מוקדמת, אלא <b>מקרית-בלבד</b>. ⚠️ עובדה זו קריטית-להבנת-משמעות-הניסוי: מכיוון-שההקצאה הייתה-אקראית (לא-נבחרו-'סוהרים-אכזריים-מטבעם'), כל ההתנהגות-הקיצונית שהתפתחה-בהמשך (כפי-שנלמד-בשאלות-הבאות) מיוחסת ל<b>כוח-התפקיד-החברתי-עצמו</b>, לא-לתכונות-אישיות-קודמות של-המשתתפים.","mnemo":"🪙 סוהר/אסיר, הטלת מטבע."},{"id":"prof8_43","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מה אפשר ללמוד מניסוי בית הכלא בסטנפורד על כוחם של תפקידים?","a":"תפקיד שהוקצה באקראי (לא תכונות אישיות) שינה דרמטית את ההתנהגות תוך שעות/ימים - סוהרים הפכו תוקפניים/סדיסטיים, אסירים פיתחו תגובות פתולוגיות אמיתיות. כוחו של המצב יכול להשתלט על אישיות וערכים.","explain":"תוך זמן קצר, התפקיד שהוקצה באקראי שינה באופן דרמטי את התנהגות המשתתפים. סטודנטים ששיחקו סוהרים הפכו לתוקפניים ואף סדיסטיים - דרשו ציות מוחלט, שללו הטבות בסיסיות, המציאו ענישות משפילות. סטודנטים יציבים נפשית שמילאו את תפקיד האסיר גילו תגובות פתולוגיות אמיתיות - בכי בלתי נשלט, דיכאון עמוק, פריחה פסיכוסומטית. הניסוי, שתוכנן לשבועיים, הופסק לאחר 6 ימים בלבד. מסקנה: כוחו של המצב (התפקיד עצמו) יכול להשתלט על אישיות, ערכים והתנהגות של אדם רגיל לגמרי.","mnemo":"🎭➡️😈 תפקיד-אקראי הפך אנשים נורמליים לאכזריים."},{"id":"prof8_44","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו ההבדל המרכזי בין בית הכלא בסטנפורד לבתי כלא אמיתיים המאפשר את המסקנות?","a":"בסטנפורד, ההקצאה לתפקידים הייתה אקראית לחלוטין (הטלת מטבע), ללא הבדלי אישיות/הכשרה מוקדמים - מבודד את \"כוח המצב\" כגורם היחיד המסביר את ההתנהגות הקיצונית.","explain":"המאפיין המכריע: יד המקרה בלבד (חלוקה אקראית מוחלטת בהטלת מטבע) קבעה איזה תפקיד ימלא כל משתתף - לא שום הבדל מוקדם באישיות, בנטיות, או ביכולת. איש גם לא לימד את המשתתפים כיצד למלא את תפקידם. בגלל ההקצאה האקראית הטהורה, אי אפשר לייחס את ההבדלים העצומים בהתנהגות לשום דבר מלבד התפקיד עצמו - מה שמבודד את 'כוח המצב' כמשתנה המסביר היחיד, בניגוד לבתי כלא אמיתיים שבהם קיימים הבדלים מובנים מראש.","mnemo":"🪙 אקראי לגמרי = בודדים את כוח-המצב."},{"id":"prof8_45","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"דונו במידה שבה ניסוי בית הכלא בסטנפורד עומד בעקרון ה-Beneficence and Nonmaleficence.","a":"⚠️ ניתוח אתי. מפר את העיקרון בבירור: נזק פסיכולוגי ממשי וחמור למשתתפים (התמוטטויות, דיכאון, פסיכוסומטיקה) הביא להפסקת הניסוי לאחר 6 ימים בלבד מתוך 14 מתוכננים.","explain":"⚠️ ניתוח אתי. הניסוי מפר באופן חמור עקרון זה. המשתתפים סבלו נזק פסיכולוגי ממשי וממוסמך במהלך הניסוי עצמו - התמוטטויות רגשיות, דיכאון עמוק, תסמינים פסיכוסומטיים חמורים - עד כדי כך שהחוקרים נאלצו לקצר את הניסוי מ-14 ימים ל-6 בלבד. הנזק המיידי והחמור שנגרם למשתתפים מעלה ספק כבד באשר לעמידה בעיקרון זה, במיוחד לאור העובדה שהחוקר הראשי עצמו נסחף לתוך הדינמיקה כ'מפקח בית הכלא'.","mnemo":"🛑6-ימים מתוך 14=נזק אמיתי."},{"id":"prof8_46","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"האם ניתן בניסוי בית הכלא בסטנפורד מענה מספק לסוגיות האתיות?","a":"⚠️ לא מספק. הסכמה מדעת חלקית (לא ניתן לצפות מראש את העוצמה). רווח מול הפסד מוטל בספק (נזק ממשי שהצריך הפסקה מוקדמת). לא הייתה הטעיה קלאסית, אך גם לא נמנע הנזק מראש. שיחת הבהרה/מעקב בוצעו, אך רק בדיעבד.","explain":"⚠️ ניתוח ביקורתי. הסכמה מדעת: חלקית - המשתתפים הסכימו להשתתף, אך לא יכלו לצפות מראש את העוצמה שבה תשתנה הדינמיקה. רווח מול הפסד: מוטל בספק חמור - הנזק הפסיכולוגי הממשי לא היה מידתי ביחס לתובנות, בייחוד לאור ההפסקה המוקדמת. הטעיה מכוונת: לא הייתה הטעיה קלאסית, אך לא הוסבר עד כמה ה'משחק' עלול להפוך מזיק בפועל. שיחת הבהרה: בוצעה בסופו של דבר, ונערך מעקב ארוך טווח - אך זה בדיעבד, לאחר שהנזק כבר נגרם. מסקנה: הניסוי אינו נותן מענה מספק - חסר מנגנון בקרה שהיה עוצר את הניסוי מוקדם יותר.","mnemo":"❌ לא הסכמה אמיתית, לא איזון נזק/תועלת."},{"id":"prof8_47","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהן נורמות חברתיות?","a":"ציפיות לגישות/התנהגויות מקובלות חברתית, המתבטאות בכללים מפורשים או משתמעים של הקבוצה - קווים מנחים כלליים או אמות מידה ספציפיות להתנהגות.","explain":"<b>נורמות חברתיות</b> - ציפיות ל<b>גישות/התנהגויות המקובלות חברתית</b> בתוך-קבוצה, המתבטאות ב<b>כללים</b> - בין-אם <b>מפורשים</b> (כתובים/נאמרים-בגלוי, כמו-חוקים) או <b>משתמעים</b> (לא-נאמרים-במפורש, אך 'מובנים-מאליהם' לחברי-הקבוצה). ⚠️ נורמות יכולות להיות <b>קווים-מנחים-כלליים</b> (למשל, 'להיות-מנומס') או <b>אמות-מידה-ספציפיות-מאוד</b> (למשל, 'לבוא-לפגישה-בזמן') - הן פועלות-ברמות-שונות-של-פירוט, אך תמיד מכוונות-התנהגות-בהתאם-לציפיות-הקבוצה.","mnemo":"📏 כללי-משחק לא-כתובים."},{"id":"prof8_48","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו את שתי דרכי ההסתגלות לנורמות (התנהגות אחידה, תוצאות שליליות).","a":"התנהגות אחידה=לומדים נורמה מתוך צפייה בהתנהגות דומה של רוב/כל חברי הקבוצה. תוצאות שליליות=לומדים נורמה מתוך צפייה בעונש/דחייה של מי שהפר אותה.","explain":"שתי דרכים-עיקריות שדרכן אנחנו-לומדים ומפנימים נורמות-חברתיות: <b>(1) התנהגות אחידה</b> - לומדים-נורמה מתוך <b>צפייה בהתנהגות-דומה</b> של רוב/כל-חברי-הקבוצה (אם כולם-עושים-X, מסיקים-שX הוא-הנורמה-המקובלת). <b>(2) תוצאות שליליות</b> - לומדים-נורמה מתוך <b>צפייה בעונש/דחייה</b> של-מי-שהפר-אותה (רואים-מישהו-נענש/נדחה-חברתית על-התנהגות-מסוימת, ומסיקים-שזו-הפרת-נורמה). ⚠️ שתי-הדרכים <b>משלימות</b> - לפעמים לומדים-מהתבוננות-ישירה-בהתנהגות-הרוב, ולפעמים דווקא מ<b>ראיית-החריגה</b> ותוצאותיה-השליליות.","mnemo":"👀רואה-שכולם-עושים. 😬רואה-מי-שנענש."},{"id":"prof8_49","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי קונפורמיות?","a":"הנטייה לאמץ את ההתנהגות והדעות של חברי קבוצה אחרים, כתוצאה מהתאמה לתפקיד חברתי/נורמה.","explain":"<b>קונפורמיות</b> - הנטייה <b>לאמץ</b> את ההתנהגות והדעות של חברי-קבוצה-אחרים, כתוצאה מהתאמה ל<b>תפקיד-חברתי או נורמה</b>. ⚠️ קונפורמיות קשורה-ישירות למושג-הנורמות שנלמד-קודם: היא בעצם ה<b>תוצאה-ההתנהגותית</b> של-קיום-נורמות - ברגע-שלמדנו-מהי-הנורמה (דרך-אחת-משתי-הדרכים-שנלמדו), קונפורמיות היא-הנטייה <b>לפעול-לפיה בפועל</b>, גם-אם-לא-בהכרח מסכימים-איתה-אישית לגמרי.","mnemo":"🐑 מתאים עצמי לקבוצה."},{"id":"prof8_50","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו את שני הכוחות המביאים לקונפורמיות (מידע ונורמה).","a":"השפעת מידע=רצון לפעול נכון במצב דו-משמעי, לומדים ממה שאחרים עושים. השפעת נורמה=רצון שיחבבו/יקבלו אותנו, מתאימים עצמנו גם במצב חד-משמעי.","explain":"השפעת המידע - הרצון לפעול נכון ולהבין את דרך הפעולה ההולמת במצב דו-משמעי שבו איננו בטוחים כיצד לנהוג. אנו מסתכלים על אחרים כמקור מידע.\nהשפעת הנורמה - הרצון שאחרים יחבבו אותנו, יקבלו אותנו ויאשרו את התנהגותנו - גם כשהמציאות ברורה וחד-משמעית, עלולים להתאים את עצמנו לדעת הרוב כדי להימנע מדחייה.","mnemo":"❓מידע=לא-בטוח-מה-נכון. 🤝נורמה=רוצה-להתקבל."},{"id":"prof8_reflection4","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"זהו 2 נורמות בקבוצה שאתם משתייכים אליה, ונתחו לפי דרכי הסתגלות/קונפורמיות.","a":"⚠️ דוגמה מומחשת - קבוצת סטודנטים: (1) לענות בכנות לשאלות בפורום, (2) לא לחלוק תשובות מבחנים מראש. נלמדות דרך התנהגות אחידה + תוצאות שליליות. קונפורמיות גבוהה - השפעת מידע (למידה מהתנהגות קיימת) והשפעת נורמה (רצון להתקבל).","explain":"⚠️ דוגמה מומחשת - קבוצת סטודנטים לפסיכולוגיה. נורמה 1: לענות בכנות לשאלות בפורום הקורס. נלמדת דרך התנהגות אחידה (רואים שכולם עונים בפירוט) ותוצאות שליליות (מי שעונה בקצרה מקבל תגובות שליליות). נורמה 2: לא לחלוק תשובות מבחנים מראש. נלמדת באופן דומה. קונפורמיות גבוהה לשתיהן - השפעת מידע (למידה מהתנהגות קיימת של סטודנטים חדשים) והשפעת נורמה (רצון להיחשב 'חבר קבוצה טוב').","mnemo":"👀🤝 רואים+רוצים-להתקבל."},{"id":"prof8_52","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מתי דיווחי קבוצה דומים יותר במצבים עמומים - פרטני או קבוצתי (ניסוי שריף)?","a":"דומים יותר בתהליך קבוצתי (חשיפה לדיווחי כולם) - האומדנים מתלכדים ונשארים גם בבדיקה פרטנית מאוחרת יותר. במצב עמום (אפקט אוטוקינטי), אנשים משתמשים בדיווחי אחרים כמקור מידע.","explain":"לפי ניסוי שריף על האפקט האוטוקינטי (תעתוע חזותי שבו נקודת אור קבועה נראית כנעה בחושך מוחלט) - כשמשתתפים דיווחו לבד, נמצא הבדל ניכר בין הערכותיהם. אך כשהובאו לחדר החשוך כקבוצה ודיווחו בקול רם, אומדניהם החלו להתלכד. כשכל משתתף נבדק שוב לבדו לאחר הצפייה הקבוצתית, הוא המשיך לדבוק בנורמה שהתגבשה.\n\nתשובה: הדיווחים דומים יותר בתהליך הקבוצתי - במצב עמום, אנשים משתמשים בדיווחי אחרים כמקור מידע (השפעת המידע) כדי לפתור אי-ודאות, מה שיוצר נורמה משותפת הנשמרת גם לאחר מכן.","mnemo":"👥 קבוצה=מתלכדים ונשארים כך."},{"id":"prof8_53","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"סכמו את ניסוי אש - מטלה, תוצאות, ו-3 גורמים משפיעים.","a":"משתתף תמים בין שותפי סוד, שענו בעקביות תשובה שגויה על אורך קווים. 50-80% התאימו עצמם לפחות פעם אחת; 25% נותרו עצמאיים לחלוטין. גורמים: (1) גודל קבוצת הרוב. (2) נוכחות שותף חולק. (3) פער בין הגירוי הנכון לגירוי שבחר הרוב.","explain":"מה נתבקשו לעשות: משתתף תמים הושב עם 6-8 'שותפי סוד' של הנסיין. הוצגו קווים בגדלים שונים, ונשאלו איזה קו שווה לקו הבסיסי. בסבבים מסוימים, שותפי הסוד ענו בעקביות תשובה שגויה בעליל.\n\nתוצאות: כרבע מהמשתתפים נותרו עצמאיים לגמרי. 50%-80% התאימו עצמם לתשובה השגויה לפחות פעם אחת; שליש נכנעו לפחות במחצית מהצעדים הקריטיים.\n\nשלושה גורמים משפיעים: (1) גודל קבוצת הרוב - אפקט חזק גם עם 3-4 אנשים. (2) נוכחות שותף החולק על דעת הרוב - אפילו בן ברית אחד הפחית משמעותית קונפורמיות. (3) הפער בין הגירוי הנכון לגירוי שבחר הרוב.","mnemo":"📏 קווים: 50-80% נכנעו לפחות פעם."},{"id":"prof8_54","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תארו את מחקר מוסקוביצ'י על השפעת המיעוט, והסבירו במונחי השפעת מידע/נורמה.","a":"שני שותפי סוד (מיעוט) טענו בעקביות שירוק=כחול. הרוב לא שינה דעתו בפומבי, אך כשנבחנו ביחידות, חלקם הזיזו את שיפוטם לכיוון הכחול. הסבר: השפעת נורמה של מיעוט חלשה (הרוב לא חושש מדחיית המיעוט), אך השפעת מידע קיימת - משפיעה בסתר, ניכרת רק כשאין לחץ חברתי גלוי.","explain":"מה נתבקשו לעשות: משתתפים זיהו צבעים (ירוק/כחול). הרוב זיהה נכון, אך שני שותפי סוד (מיעוט) טענו בעקביות שירוק הוא למעשה כחול.\n\nתוצאות: בתחילה, להתנגדות העקבית של המיעוט לא הייתה השפעה גלויה. אך כשהמשתתפים נבחנו ביחידות, חלקם שינו את שיפוטיהם, הזיזו את הגבול בין כחול לירוק קרוב יותר לכחול.\n\nהסבר: השפעת הנורמה של קבוצות מיעוט חלשה יחסית - הרוב לא מוטרד במיוחד אם המיעוט מקבל אותו. אך מיעוטים יכולים להפעיל השפעת מידע - מעוררים חשיבה מחדש. השפעה זו סמויה, ניכרת בעיקר בפרטיות (ללא לחץ חברתי גלוי).","mnemo":"🤫 מיעוט משפיע בסתר, לא בגלוי."},{"id":"prof8_55","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"סכמו את ניסוי מילגרם - מטלה, תוצאות, תנאים משפיעים.","a":"משתתף (\"מורה\") נדרש להעניש \"תלמיד\" (שחקן) בהלם חשמלי הולך וגובר (עד 450V) לפי הוראת נסיין בחלוק לבן. תוצאה: 65% המשיכו עד למקסימום, לעומת חיזוי של פחות מ-1% מפסיכיאטרים. ציות עלה כשעמית שימש מודל/קרבן רחוק פיזית; ירד כשהקרבן עצמו ביקש הלם, או כששתי סמכויות סתרו זו את זו.","explain":"מה נתבקשו לעשות: 19 ניסויים, יותר מ-1,000 משתתפים. כל משתתף היה 'מורה' שהעניש 'תלמיד' (שחקן) בהלם חשמלי הולך וגובר (15 וולט בכל פעם, עד 450 וולט מקסימום) על כל טעות בשינון מילים. הנסיין, בחלוק לבן, הורה להמשיך גם כשהמורה היסס.\n\nתוצאות: 40 פסיכיאטרים ניבאו שרוב יפסיקו סביב 150 וולט, פחות מ-1% ימשיכו ל-450. בפועל: אף משתתף לא עצר לפני 300 וולט, ו-65% המשיכו עד 450 וולט - רבים מחו במילים אך המשיכו לציית במעשה.\n\nתנאים משפיעים (תרשים 17.7): ציות עלה כשעמית שימש מודל לציות, כשהמשתתף רק סייע (לא ביצע בעצמו), כשהקרבן רחוק פיזית. ציות ירד כשהלומד עצמו דרש הלם, כששתי דמויות סמכות סתרו זו את זו, כשדמות הסמכות עצמה הייתה הקרבן.","mnemo":"⚡65% עד הסוף, למרות תחזית 1%."},{"id":"prof8_56","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו את ממצאי מילגרם באמצעות השפעת מידע ונורמה.","a":"השפעת נורמה=רצון להתקבל/להיחשב משתף פעולה. השפעת מידע=במצב דו-משמעי וזר, מחפשים רמזים מדמות מומחית ואמינה (הנסיין). גורמים נוספים: היעדר \"דרך יציאה\" קלה, והרגל ילדות של ציות עיוור לסמכות.","explain":"השפעת הנורמה - אנשים רוצים שיחבבו אותם ושיתקבלו חברתית - כדי להיות מקובלים, נוטים לעשות מה שמבקשים מהם.\nהשפעת המידע - במצב דו-משמעי וזר (כמו הניסוי), אנשים מחפשים אצל אחרים רמזים לדרך הנכונה להתנהג. הסיכוי גדל כשדמות מומחית ואמינה (הנסיין) אומרת מה לעשות.\nגורמים נוספים: היעדר דרך קלה להיחלץ מהמצב (לא היה 'כפתור יציאה'), והרגל ילדות של ציות עיוור לסמכות - היריסטיקה כללית המשרתת בדרך כלל את החברה, אך כאן יושמה באופן עיוור.","mnemo":"🥼 חלוק-לבן=מומחה=מידע. רוצה-לרצות=נורמה."},{"id":"prof8_58","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע, לפי הגישה האבולוציונית, בני אדם תוקפניים?","a":"תוקפנות משרתת מבחינה אבולוציונית נגישות לבני זוג והגנה על משאבים. לפי לורנץ, לבני אדם (בניגוד לבעלי חיים אחרים) חסרים מנגנוני עיכוב מפותחים לתוקפנות - כי עד המצאת כלי הנשק, גופם החשוף לא אפשר נזק רב, ולכן לא התפתח צורך אבולוציוני בבלמים פנימיים חזקים.","explain":"תוקפנות משרתת מבחינה אבולוציונית נגישות לבני זוג והגנה על משאבים. לפי קונרד לורנץ, לבני אדם, בניגוד לבעלי חיים אחרים, חסרים מנגנוני עיכוב מפותחים לתוקפנות - כי עד המצאת כלי הנשק המלאכותיים, גופם החשוף לא אפשר להם לגרום נזק רב זה לזה, ולכן לא התפתח לחץ אבולוציוני לפתח בלמים פנימיים חזקים. עם הופעת כלי הנשק, כוחו ההרסני של האדם גדל בפתאומיות, בעוד המנגנון לרסן אותו נותר בלתי מפותח.","mnemo":"🦁 אין בלמים - כי הגוף החשוף לא הצדיק אותם."},{"id":"prof8_59","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד משפיעה הסביבה החברתית על התנהגות תוקפנית (לפי הגישה האבולוציונית)?","a":"מחקרים הראו שיכולת הריסון האנושית גבוהה בהרבה ממה שלורנץ הניח - מידת התוקפנות בפועל תלויה בסביבה החברתית/תרבותית, המגדירה מתי תוקפנות מקובלת/נדרשת/אסורה. הפוטנציאל הביולוגי קיים, אך התרבות מעצבת את ביטויו בפועל.","explain":"מחקרים סתרו את טענת לורנץ בשתי דרכים: מינים אחרים (כמו שימפנזים) גם הם מבצעים תוקפנות קטלנית - רציפות אבולוציונית. כמו כן, יכולתם של בני האדם לרסן תוקפנות רבה בהרבה ממה שלורנץ הניח. התובנה המרכזית: מידת התוקפנות בפועל תלויה בסביבה החברתית - תרבויות שונות מגדירות נסיבות שונות שבהן תוקפנות מקובלת, נדרשת, או אסורה. הפוטנציאל הביולוגי קיים, אך התרבות מעצבת את ביטויו.","mnemo":"🎚️ פוטנציאל קיים, תרבות קובעת עוצמה."},{"id":"prof8_60","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע, לפי הגישה הביולוגית, בני אדם תוקפניים (גנטיקה, מוח, הורמונים)?","a":"גנטיקה: מסבירה 50-60% מהשונות בתוקפנות פיזית, פחות בחברתית (20%). מוח: אמיגדלה/קורטקס מווסתים רגשות; גן MAOA קשור לתוקפנות. הורמונים: סרוטונין נמוך פוגע בוויסות רגשי; קורטיזול נמוך=פחות עכבות/תגובות עקה מרסנות.","explain":"הבדלים גנטיים: מחקרי תאומים מראים מרכיב גנטי חזק - גורמים גנטיים מסבירים 50-60% מהשונות בתוקפנות פיזית, אך רק 20% בתוקפנות חברתית (המושפעת יותר מדפוסי הורות).\n\nהבדלים במוח: מבנים כמו האמיגדלה וחלקים מהקורטקס ממלאים תפקיד בוויסות רגשות. נמצא גן ספציפי (MAOA) המשמש סמן גנטי לתוקפנות, מלווה בנפח שונה של האזור הלימבי ותגובתיות שונה באמיגדלה.\n\nפעילות הורמונלית: רמות לא תואמות של סרוטונין פוגעות בוויסות רגשי. רמות נמוכות של קורטיזול (הורמון עקה) נמצאו קשורות לתוקפנות רבה יותר - ייתכן שאנשים אלה חווים פחות תגובות עקה מרסנות.","mnemo":"🧬🧠💊 גנים+מוח+הורמונים=50-60%."},{"id":"prof8_61","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"האם לסביבה החברתית יש השפעה על תוקפנות, לפי הגישה הביולוגית?","a":"כן. גם כשיש בסיס גנטי (חזק בתוקפנות פיזית, חלש יותר בחברתית), הסביבה (כמו סוג ההורות - עוררות בושה/אשמה) מספקת מודל להתנהגות ותורמת במיוחד לתוקפנות חברתית.","explain":"כן. גם כשיש בסיס גנטי חזק (כמו בתוקפנות פיזית), הסביבה עדיין ממלאת תפקיד. הנטייה של ילדים להשתמש בתוקפנות חברתית עשויה לנבוע מסוג ההורות שחוו - הורים המעוררים בושה/אשמה מספקים מודל לחיקוי. כלומר, בתוקפנות חברתית, תפקידה של הסביבה בולט יותר מזה של הגנטיקה.","mnemo":"👨‍👩‍👧 גם עם גנים, ההורות משפיעה."},{"id":"prof8_62","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"האם לאישיות השפעה על תוקפנות? הבחינו בין אימפולסיבית לאינסטרומנטלית.","a":"כן. אימפולסיבית=תגובה רגשית מיידית ללא תכנון (תגובתיות רגשית חזקה). אינסטרומנטלית=מתוכננת, מונעת מטרה, מבוססת קוגניציה (הערכה חיובית של אלימות, התנערות מאחריות מוסרית). סוגים שונים = גורמי אישיות שונים.","explain":"כן, לאישיות השפעה - אנשים בעלי פרופילים אישיות שונים נוטים להגיב בסוגי תוקפנות שונים.\n\nתוקפנות אימפולסיבית - נוצרת כתגובה מיידית למצב, מקורה רגשי, ללא תכנון מוקדם (למשל, קטטה בעקבות תאונת דרכים). אנשים הנוטים לכך מאופיינים בתגובתיות רגשית חזקה.\n\nתוקפנות אינסטרומנטלית - יש לה מטרה מוגדרת, מבוססת על קוגניציה, מתוכננת מראש (למשל, הפלת אישה כדי לגנוב תיק). אנשים הנוטים לכך מקבלים ציונים גבוהים ב'הערכה חיובית של אלימות' ונוטים להתנער מאחריות מוסרית.\n\nמסקנה: לא כל סוגי האלימות נובעים מאותם גורמי אישיות.","mnemo":"💥תגובתי-מיידי. 🎯מתוכנן-למטרה."},{"id":"prof8_63","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי השערת התסכול והתוקפנות?","a":"תסכול (מניעה/חסימה מהשגת מטרה) מגביר את הסבירות לתוקפנות. ככל שהתסכול חזק יותר, כך גדל הסיכוי לתוקפנות - אך פחות אם התסכול נגרם בתום לב (לא בכוונה).","explain":"השערת התסכול והתוקפנות (Dollard et al., 1939) קובעת שתסכול - מצב שבו נמנע מבני אדם להשיג את מטרותיהם, או שהדרך אליהן נחסמת - מגביר את הסבירות לתוקפנות. ככל שרמת התסכול עולה, כך גדל הסיכוי לתוקפנות. סייג חשוב: תסכול שנגרם בתום לב (בטעות) מקטין משמעותית את הסיכוי לתוקפנות, לעומת תסכול הנגרם בכוונה תחילה.","mnemo":"🚧 חסימה=תוקפנות (אם בכוונה)."},{"id":"prof8_64","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד יכולה השערת התסכול-תוקפנות להסביר רצח עם?","a":"⚠️ הסבר סינתזה. תנאי חיים קשים (כלכלה, פוליטיקה) יוצרים תסכול קולקטיבי נרחב. במקום להפנות תוקפנות למקור המורכב, מפנים אותה לשעיר לעזאזל (קבוצת חוץ) - התסכול המצטבר מתורגם לתוקפנות ממוקדת, שיכולה להסלים לרצח עם.","explain":"⚠️ הסבר סינתזה. לפי מודל שטאוב, נקודת המוצא היא תנאי חיים קשים (מצוקה כלכלית, תוהו פוליטי) היוצרים תסכול קולקטיבי נרחב. במקום להפנות תוקפנות למקור המורכב של המצוקה, החברה נוטה להפנות אותה לשעיר לעזאזל - קבוצת חוץ מזוהה ונגישה יותר, המואשמת (בטעות) בכל חוליי החברה. כך התסכול המצטבר מתורגם לתוקפנות ממוקדת, שיכולה להסלים עד לרמת רצח עם.","mnemo":"🐐 תסכול לאומי→שעיר-לעזאזל→פוגרום."},{"id":"prof8_65","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"האם חום גורם לתוקפנות? סכמו ממצאים והסתייגויות (פרק 2).","a":"קשר חזק נמצא (36,617 תקיפות, מיניאפוליס) - חום רב יותר=תקיפות רבות יותר, בעיקר בשעות הפנאי. הסברים: חברתי (יותר אנשים בחוץ, אלכוהול) ופסיכולוגי (טעות ייחוס - מייחסים אי-נוחות לאדם ולא לחום). הסתייגות: מחקר מתאמי בלבד - מתאם אינו מעיד סיבתיות, ייתכנו משתנים מתערבים.","explain":"ממצאים: מחקר על 36,617 מקרי תקיפה במיניאפוליס מצא קשר חזק בין טמפרטורה גבוהה לתקיפות, בעיקר בשעות הפנאי (9 בערב-3 לפנות בוקר). הסברים: חברתי (יותר אנשים בחוץ בחום, זמינות רבה יותר כקרבנות; צריכת אלכוהול בערב) ופסיכולוגי (טעות ייחוס - קשה לייחס אי-נוחות לחום, קל יותר לייחס אותה לאדם אחר, כפי שנלמד בפרק 16 על טעות הייחוס הבסיסית).\n\nהסתייגות (פרק 2): מדובר במחקר מתאמי (קורלטיבי), לא ניסויי - מתאם אינו מעיד בהכרח על סיבתיות, וייתכנו משתנים מתערבים (זמינות קרבנות, אלכוהול, שעת היום) המסבירים את הקשר.","mnemo":"🌡️ חום=יותר תקיפות, אך רק מתאם."},{"id":"prof8_66","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע, לפי הגישה התרבותית, בני אדם תוקפניים (עצמי עצמאי/תלותי, תרבות כבוד)?","a":"תפיסת עצמי תלותית (מזרח) מפחיתה תוקפנות (פגיעה באחר=פגיעה ב\"עצמי\" הקולקטיבי) - הוכח בהשוואת ילדי גן יפנים/אמריקנים. בתוך העצמי העצמאי (ארה\"ב), תרבות כבוד (דרום) יוצרת רגישות מיוחדת לעלבונות - דרומיים מנומסים יותר ללא עלבון, אך תוקפניים יותר לאחריו, לעומת צפוניים.","explain":"עצמי עצמאי/תלותי: תרבויות מזרחיות מטפחות תפיסת עצמי תלותית (הדדית) - כשאדם חש קשור לאחרים, הסיכוי שיגיב בתוקפנות קטן יותר (פגיעה באחר=פגיעה ב'עצמי' הקולקטיבי). מחקר על ילדי גן הראה שילדים יפנים (תלותיים) הראו פחות מלל/התנהגות תוקפנית מילדים אמריקנים (עצמאיים).\n\nתרבות כבוד: בתוך הקטגוריה הרחבה של 'עצמי עצמאי' (ארה\"ב), נמצא שבדרום ארה\"ב שולטת 'תרבות כבוד' - אפילו ויכוחים קטנים הופכים לתחרות על מוניטין. בניסוי, סטודנטים דרומיים היו מנומסים יותר ללא עלבון, אך הגיבו בחריפות רבה יותר לאחר עלבון מתון, לעומת סטודנטים צפוניים.","mnemo":"🌏עצמי-תלותי=פחות-תוקפני. 🤠כבוד-דרומי=רגיש-לעלבון."},{"id":"prof8_67","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד מסביר מודל התוקפנות הכללי את התוקפנות?","a":"חשיפה חוזרת לאלימות תקשורתית בונה מבני ידע כלליים: העולם מסוכן, תוקפנות=דרך הולמת להתמודד עם קונפליקטים. הוכח בניסוי: משחק וידיאו אלים→המשכי סיפור אלימים יותר מאשר לאחר משחק לא-אלים.","explain":"המודל פותח להסביר את הקשר בין חשיפה לאלימות תקשורתית (טלוויזיה, משחקי וידיאו) לבין התנהגות תוקפנית. אנשים רוכשים באמצעות חשיפה חוזרת מערך כללי של מבני ידע - כל אירוע אלים שנצפה מחזק את התפיסה שהעולם מסוכן, שתוקפנות היא דרך הולמת להתמודד עם קונפליקטים. הוכחה: סטודנטים ששיחקו משחק וידיאו אלים הציעו המשכי סיפור אלימים משמעותית יותר מאלה ששיחקו במשחק לא-אלים.","mnemo":"🎮 משחק-אלים→סיפור-אלים יותר."},{"id":"prof8_68","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"זהו תהליכי למידה המובילים לתוקפנות.","a":"⚠️ סינתזה. (1) למידה באמצעות צפייה/חיקוי מודלים תוקפניים. (2) התניה אופרנטית - ילדים לומדים שתוקפנות \"עובדת\" (מהורים המענישים פיזית). (3) בניית סכימות כלליות (מודל התוקפנות הכללי) מחשיפה חוזרת. (4) תסריט הסלמה - דפוס נלמד של החרפה הדרגתית בתגובה להתגרות.","explain":"⚠️ סינתזה. (1) למידה באמצעות צפייה - ילדים שצפו במודלים מבוגרים תוקפניים חיקו את ההתנהגות בשכיחות גבוהה יותר (מחקר בנדורה). (2) התניה אופרנטית - ילדים הנענשים ענישה גופנית לומדים שתוקפנות היא כלי אפקטיבי לשליטה. (3) בניית סכימות כלליות (מודל התוקפנות הכללי) - חשיפה חוזרת בונה 'העולם מסוכן, תוקפנות מועילה'. (4) תסריט הסלמה - דפוס תרבותי נלמד של החרפה הדרגתית בתגובה להתגרות מתמשכת.","mnemo":"👀חיקוי+💰חיזוק+🧩סכמה+📈הסלמה."},{"id":"quiz8_1","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"כיצד התנהגו רוב הנבדקים בניסוי מילגרם? (סירבו לתת הלם / נהנו לתת הלם / הראו מידה מדאיגה של ציות / הראו נכונות לסבול הלם למען הניסוי)","a":"הראו מידה מדאיגה של ציות להוראות (מילגרם - רוב הנבדקים ציית לסמכות למרות מצוקה)","explain":"מה נתבקשו לעשות: 19 ניסויים, יותר מ-1,000 משתתפים. כל משתתף היה 'מורה' שהעניש 'תלמיד' (שחקן) בהלם חשמלי הולך וגובר (15 וולט בכל פעם, עד 450 וולט מקסימום) על כל טעות בשינון מילים. הנסיין, בחלוק לבן, הורה להמשיך גם כשהמורה היסס.\n\nתוצאות: 40 פסיכיאטרים ניבאו שרוב יפסיקו סביב 150 וולט, פחות מ-1% ימשיכו ל-450. בפועל: אף משתתף לא עצר לפני 300 וולט, ו-65% המשיכו עד 450 וולט - רבים מחו במילים אך המשיכו לציית במעשה.\n\nתנאים משפיעים (תרשים 17.7): ציות עלה כשעמית שימש מודל לציות, כשהמשתתף רק סייע (לא ביצע בעצמו), כשהקרבן רחוק פיזית. ציות ירד כשהלומד עצמו דרש הלם, כששתי דמויות סמכות סתרו זו את זו, כשדמות הסמכות עצמה הייתה הקרבן.","mnemo":"⚡ ציות מדאיג, לא מרד."},{"id":"quiz8_2","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"מהי ההנחה הבסיסית בתיאוריית הדיסוננס הקוגניטיבי? (שיפוטים קיצוניים סותרי רגשות / אמונות מתערערות מסביבה לוחצת / חוסר התאמה בין עמדות, או בין עמדות להתנהגות / מערכת רגשית מתערערת)","a":"שאנשים אינם חשים בנוח במצב של חוסר התאמה בין עמדותיהם, או בין עמדותיהם לבין התנהגותם (המניע המרכזי לשינוי עמדה/רציונליזציה)","explain":"ההנחה-הבסיסית בתיאוריית-הדיסוננס-הקוגניטיבי: <b>חוסר-התאמה בין עמדות</b>, או <b>בין עמדות להתנהגות</b>, יוצר <b>אי-נוחות פסיכולוגית</b> (דיסוננס) שאנשים <b>מונעים-להפחית</b>. ⚠️ זהו-בדיוק המניע-המרכזי לתופעות-כמו שינוי-עמדה או רציונליזציה (מנגנון-הגנה שנלמד-בפרק-האישיות): כשההתנהגות-בפועל <b>לא-תואמת</b> את-מה-שחשבנו-שאנחנו-מאמינים-בו, אנחנו לרוב <b>משנים את-העמדה</b> (במקום-את-ההתנהגות שכבר-קרתה) כדי-לצמצם-את-אי-הנוחות.","mnemo":"😣 אי-התאמה=לא-נעים."},{"id":"quiz8_3","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"א' נכשל, מאשים המנחה; מסביר הצלחת חבריו במזל. דוגמה ל: (ייחוס פנימי / הטיה בשירות העצמי / טעות הייחוס הבסיסית / ציפייה מגשימה)","a":"הטייה בשירות העצמי (מייחסים כישלון לגורם חיצוני, הצלחת אחרים למזל)","explain":"א', שנכשל ומאשים-את-המנחה (גורם-חיצוני), אך מסביר את-הצלחת-חבריו-<b>במזל</b> (גם-הוא-גורם-חיצוני-לחבריו, לא-מכיר-בכישרונם) - זו <b>הטיה בשירות-העצמי</b>: מייחס <b>כישלון-עצמו</b> לגורם-חיצוני (המנחה), ו<b>הצלחת-אחרים</b> (שהייתה-מחלישה-אותו-בהשוואה) גם-היא לגורם-חיצוני-קר-ולא-מרשים (מזל, לא-כישרון) - שני-ייחוסים ששניהם-מגנים-על-הדימוי-העצמי-של-א'. ⚠️ אל-תתבלבלו עם 'טעות-הייחוס-הבסיסית' - זו-הייתה-מתאימה אם-א'-היה-מייחס את-<b>כישלון-עצמו-של-אחר</b> לתכונה-פנימית; כאן, ההטיה-בשירות-העצמי מתמקדת ב<b>הגנה-על-הדימוי-העצמי-של-א' בעצמו</b>.","mnemo":"🎲מזל-לחברים. 👤אשמה-למנחה."},{"id":"quiz8_4","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"רוני החליט לקנות אופנוע; החורף היה גשום. לפי דיסוננס קוגניטיבי, מה צפוי? (יתחרט ויציין חסרונות / יתמיד ויציין יתרונות / לא יושפע / ישנה רק אם חבריו ישנו)","a":"רוני צפוי להתמיד בהעדפתו לאופנוע ואף להדגיש עוד יותר את יתרונותיו (מפחית דיסוננס בין ההחלטה לחוויה השלילית)","explain":"דיסוננס קוגניטיבי הוא מצב לא נעים של קונפליקט פנימי, שאנו חווים לאחר קבלת החלטה, נקיטת פעולה, או חשיפה למידע הסותר את אמונותינו, רגשותינו או ערכינו הקודמים. פותח על ידי לאון פסטינגר (1957). כאשר יש פער בין ההתנהגות שלנו לבין העמדות/הקוגניציות שלנו, נוצרת תחושה אברסיבית שאנו מנסים באופן פעיל להפחית - לרוב על ידי שינוי העמדה עצמה כך שתתאים להתנהגות שכבר ביצענו.","mnemo":"🏍️ מתעקש למרות הגשם."},{"id":"quiz8_5","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"באיזו סיטואציה הקשר עמדה-התנהגות הנמוך ביותר? (עמדה נגישה / עמדה חשובה / עמדה חזקה / עמדה בלתי יציבה)","a":"כאשר העמדה בלתי יציבה (עמדה לא-יציבה חוזה פחות טוב את ההתנהגות בפועל)","explain":"הקשר-בין-עמדה-להתנהגות <b>הנמוך-ביותר</b> מתקיים כאשר העמדה <b>בלתי-יציבה</b> - עמדה-לא-יציבה (משתנה, לא-מגובשת, לא-בטוחה) חוזה <b>פחות-טוב</b> את-ההתנהגות-בפועל. ⚠️ אל-תתבלבלו עם-האפשרויות-האחרות: עמדה <b>נגישה</b> (עולה-בקלות-לתודעה), <b>חשובה</b> (משמעותית-לזהות), או <b>חזקה</b> (מוחזקת-בביטחון) - כל-אלה דווקא <b>מחזקים</b> את-הקשר-עמדה-התנהגות, כי-הן-מייצגות-עמדה-יציבה-וברורה; רק-חוסר-יציבות פוגע-בקשר-הזה-באופן-ספציפי.","mnemo":"🎈 לא-יציב=לא-חוזה."},{"id":"quiz8_6","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"מה נמצא בניסויי אש? (קשר חיובי מתמיד עם מספר הלוחצים / קונפורמיות יומיומית פחותה ממעבדה / תומך אחד מקטין מאוד קונפורמיות / כל הנבדקים הודו ששיקרו במודע)","a":"הימצאותו של אפילו תומך אחד לדעתו האמיתית של הנבדק תקטין מאוד את מידת הקונפורמיות (שובר את תחושת הבידוד מול הרוב)","explain":"בניסויי-אש (על-קונפורמיות), הממצא-המרכזי: <b>הימצאותו-של אפילו תומך-אחד</b> לדעתו-האמיתית-של-הנבדק <b>מקטינה-מאוד</b> את-מידת-הקונפורמיות. ⚠️ ההסבר: התומך-האחד <b>שובר את-תחושת-הבידוד-המוחלט</b> מול-הרוב - כשהנבדק-לא-לבד-בדעתו, גם-אם-רק-אדם-אחד-נוסף מסכים-איתו, קל-הרבה-יותר <b>לעמוד</b> מול-לחץ-הרוב, בהשוואה-למצב-שבו הוא-היחיד-שחושב-אחרת. זו-אחת-התובנות-החשובות-ביותר על-קונפורמיות: לא-נדרש-רוב-נגדי, רק <b>שותף-בודד-אחד</b> כדי-להפחית-דרמטית-את-הלחץ-להיכנע.","mnemo":"1️⃣ תומך-אחד=שובר קונפורמיות."},{"id":"quiz8_7","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"הילה אוהבת בעלה, לא אוהבת חבריו. חווה: (הטיה בשירות עצמי / נבואה מגשימה / דיסוננס קוגניטיבי / טעות ייחוס בסיסית)","a":"דיסוננס קוגניטיבי (אהבה לבעל מול אי-אהבה לחבריו - שתי עמדות סותרות)","explain":"דיסוננס קוגניטיבי הוא מצב לא נעים של קונפליקט פנימי, שאנו חווים לאחר קבלת החלטה, נקיטת פעולה, או חשיפה למידע הסותר את אמונותינו, רגשותינו או ערכינו הקודמים. פותח על ידי לאון פסטינגר (1957). כאשר יש פער בין ההתנהגות שלנו לבין העמדות/הקוגניציות שלנו, נוצרת תחושה אברסיבית שאנו מנסים באופן פעיל להפחית - לרוב על ידי שינוי העמדה עצמה כך שתתאים להתנהגות שכבר ביצענו.","mnemo":"❤️🚫 אוהב-אותו, לא-אוהב-חבריו=סתירה."},{"id":"quiz8_10","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"איזה תיאור מדגים תוקפנות אינסטרומנטלית? (מורה זרקה מחק בכעס / ילד הכה כי הקניטו אותו / אוהד תקף אוהד יריב במשחק / שחקן פוצע יריב כדי שלא ישחק במשחק הבא)","a":"שחקן בקבוצת כדורסל פוצע שחקן בקבוצה היריבה על מנת שלא יוכל לשחק במשחק הבא (תוקפנות ככלי למטרה, לא כתגובה רגשית ספונטנית)","explain":"שחקן-הפוצע-יריב <b>במכוון</b> כדי-שלא-יוכל-לשחק-במשחק-הבא הוא הדוגמה ל<b>תוקפנות אינסטרומנטלית</b> - תוקפנות המשמשת <b>ככלי למטרה-מסוימת</b> (כאן, הרחקת-מתחרה), <b>לא</b> כתגובה-רגשית-ספונטנית-לכעס/תסכול-מיידי. ⚠️ אל-תתבלבלו עם-הדוגמאות-האחרות (מורה-זורקת-מחק-בכעס, ילד-מכה-כי-הקניטו-אותו, אוהד-תוקף-יריב-במשחק) - כל-אלו הן <b>תוקפנות-רגשית/עוינת</b> (תגובה-מיידית-לרגש-שלילי) - <b>לא</b> אינסטרומנטלית, כי-אין-בהן תכנון-מכוון-להשגת-מטרה-חיצונית-מסוימת.","mnemo":"🎯 פוצע כדי שלא ישחק=מתוכנן."},{"id":"quiz8_11","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"סטריאוטיפ יכול להיות: (חיובי, שלילי או ניטראלי / שלילי בלבד / שלילי או ניטראלי / חיובי או שלילי)","a":"חיובי, שלילי או ניטראלי (סטריאוטיפ הוא הכללה, לא בהכרח שלילית)","explain":"סטריאוטיפ יכול-להיות <b>חיובי, שלילי, או ניטרלי</b> - כי הוא-בבסיסו <b>הכללה</b> (מבנה-קוגניטיבי המקשר-תכונות-לקבוצה), <b>לא</b> בהכרח-שלילית-מטבעה. ⚠️ טעות-נפוצה היא-לחשוב-שסטריאוטיפ=דעה-קדומה-שלילית באופן-אוטומטי - אך בפועל, גם-הכללה-חיובית ('קבוצה-X היא-חרוצה-במיוחד') נחשבת-סטריאוטיפ, לא-פחות-מהכללה-שלילית - ההבחנה-החשובה היא בין 'הכללה' (הסטריאוטיפ-עצמו, יכול-להיות-כל-ערך) לבין 'דעה-קדומה' (עמדה-שלילית-ספציפית שנבנית-לעיתים-על-סטריאוטיפים).","mnemo":"➕➖⚪ יכול להיות כל אחד מה-3."},{"id":"quiz8_12","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"א' נכשל באתיקה, אמר שהמנחה לא לימד כראוי. הייחוס הוא: (פנימי / חיצוני / שגוי / אמיתי)","a":"חיצוני (מאשים גורם מחוץ לעצמו - המנחה, לא את עצמו)","explain":"א', שנכשל באתיקה ואמר <b>שהמנחה-לא-לימד-כראוי</b> - זהו ייחוס <b>חיצוני</b>: מאשים גורם <b>מחוץ-לעצמו</b> (המנחה) בכישלונו, במקום-לבחון-תכונות/פעולות-אישיות-שלו-עצמו (למשל, חוסר-הכנה). ⚠️ שימו-לב שזו-בדיוק ההדגמה של הטיה-בשירות-העצמי (שנלמדה-קודם בפרק) - כישלון-עצמי מיוחס-לגורם-חיצוני, במקום-פנימי, כדי-להגן-על-הדימוי-העצמי.","mnemo":"👉 מאשים אותו (המנחה)=חיצוני."},{"id":"quiz8_13","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"עמדה יכולה לתאר התנהגות כאשר: (א. אינו מודע לדעותיו / ב. קשורה לעמדה ספציפית / ג. קשורה לניסיון אישי / ד. א+ב / ה. ב+ג)","a":"ה. ב'+ג' (עמדה חוזה התנהגות כשספציפית לה ומבוססת ניסיון אישי)","explain":"עמדה חוזה-היטב התנהגות כשהיא <b>ספציפית לעמדה (ב') וגם קשורה-לניסיון-אישי (ג')</b> - שני-תנאים-משלימים: <b>עמדה-ספציפית</b> (לא-כללית-מדי) חוזה-בדיוק את-ההתנהגות-הרלוונטית; <b>עמדה-מבוססת-על-ניסיון-אישי</b> (לא-רק-שמיעה-מאחרים) נגישה-ומגובשת-יותר, ולכן-חוזה-טוב-יותר. ⚠️ אל-תתבלבלו עם 'אינו-מודע-לדעותיו' - זה-דווקא <b>יפחית</b> את-הקשר-עמדה-התנהגות (אם-לא-מודעים-לעמדה, קשה-לחזות-ממנה-התנהגות), לא-יחזק-אותו - ולכן א' לא-נכללת בתשובה-הנכונה.","mnemo":"🎯🖐️ ספציפי+ניסיון-אישי."},{"id":"quiz8_14","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"ממחקרים על קונפורמיות בקבוצות עולה ש: (קבוצה הומוגנית מגדילה קונפורמיות / קבוצה גדולה מגדילה קונפורמיות / צריך מספר אנשים במעמד גבוה / די באדם אחד המפר את דעת הרוב)","a":"די באדם אחד המפר את דעת הרוב, כדי לגרום לירידה משמעותית במידת הקונפורמיות (שובר את האשליה של הסכמה מוחלטת בקבוצה)","explain":"מה נתבקשו לעשות: משתתף תמים הושב עם 6-8 'שותפי סוד' של הנסיין. הוצגו קווים בגדלים שונים, ונשאלו איזה קו שווה לקו הבסיסי. בסבבים מסוימים, שותפי הסוד ענו בעקביות תשובה שגויה בעליל.\n\nתוצאות: כרבע מהמשתתפים נותרו עצמאיים לגמרי. 50%-80% התאימו עצמם לתשובה השגויה לפחות פעם אחת; שליש נכנעו לפחות במחצית מהצעדים הקריטיים.\n\nשלושה גורמים משפיעים: (1) גודל קבוצת הרוב - אפקט חזק גם עם 3-4 אנשים. (2) נוכחות שותף החולק על דעת הרוב - אפילו בן ברית אחד הפחית משמעותית קונפורמיות. (3) הפער בין הגירוי הנכון לגירוי שבחר הרוב.","mnemo":"1️⃣ מפר-אחד מספיק."},{"id":"quiz8_15","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"מחקרים על תסכול ותוקפנות מצאו ש: (תסכול תמיד מוביל לתוקפנות / ישנם מצבים בהם תסכול אינו מביא לתוקפנות / מצבים רגשיים שליליים לא יובילו לתוקפנות אלא אם היעדים אינם מושגים / תסכול מוביל לדיכאון שמוביל לתוקפנות)","a":"ישנם מצבים בהם תסכול אינו מביא לתוקפנות (הקשר תסכול-תוקפנות אינו אוטומטי/מוחלט)","explain":"מחקרים-עדכניים-יותר על תסכול-ותוקפנות מצאו ש<b>ישנם-מצבים בהם תסכול אינו-מביא לתוקפנות</b> - הקשר <b>לא-אוטומטי/מוחלט</b>, כפי-שהתיאוריה-המקורית (השערת-תסכול-תוקפנות) הניחה. ⚠️ זהו עדכון-מדעי-חשוב: הגישה-הראשונית-הפשוטה טענה-שתסכול <b>תמיד</b> מוליד-תוקפנות, אך מחקר-מאוחר-יותר גילה שגורמים-נוספים (ויסות-רגשי, נורמות-חברתיות, אישיות) יכולים 'לעצור' את-הקשר-הזה - תסכול הוא <b>גורם-סיכון</b>, לא-נוסחה-דטרמיניסטית-בטוחה.","mnemo":"🚧≠😡 תסכול לא תמיד=תוקפנות."},{"id":"quiz8_16","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"בטעות ייחוס בסיסית, אנו מייחסים את כישלון חברינו ל: (היסטוריה אישית / מורים גרועים / תכונות אישיות / גורמים מחוץ לשליטתו)","a":"לתכונות האישיות שלו (טעות ייחוס בסיסית - מתעלמים מהקשר המצבי)","explain":"בטעות-הייחוס-הבסיסית, מייחסים כישלון-של-חברים ל<b>תכונות-האישיות שלהם</b> (גורם-פנימי) - <b>מתעלמים</b> מהקשר-מצבי-אפשרי (נסיבות-חיצוניות שיכלו-להסביר-את-הכישלון). ⚠️ זו-בדיוק ההגדרה שנלמדה בתחילת-הפרק: כשמסבירים <b>התנהגות-של-אחרים</b>, נוטים ל<b>הערכת-יתר</b> של-גורמים-פנימיים (תכונות-אישיות-קבועות) ו<b>הערכת-חסר</b> של-גורמים-חיצוניים (מצב/נסיבות) - זהו-הכיוון-ההפוך מהטיה-בשירות-העצמי, שם-מדובר-בייחוס-לגבי-עצמנו, לא-לגבי-אחרים.","mnemo":"🧍 מאשימים אותו, לא נסיבותיו."},{"id":"quiz8_17","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"\"עישון מגביר סיכון למחלות ריאה\" מתייחס למרכיב: (הקוגניטיבי / הרגשי / ההתנהגותי / זו אינה עמדה)","a":"הקוגניטיבי של העמדה (עובדה/אמונה על העצם, לא הרגש כלפיו)","explain":"מטבלה 16.1: משתתפים שהביעו עמדה אמיתית חמש פעמים הראו מתאם 0.61 עם התנהגות; מי שהביע עמדה כוזבת (שיקר) חמש פעמים הראה מתאם 0.54 - שניהם גבוהים מקבוצת ביקורת ללא הבעת עמדה (0.39). מסקנה: תהליך ביטוי חוזר של עמדה (גם אם משקרים) מחייב בחינה מנטלית של העמדה האמיתית, מה שהופך אותה לנגישה יותר.\n\nמטבלה 16.2: ככל שהשאלה על העמדה ספציפית יותר (מ'עמדה כלפי אמצעי מניעה' מתאם 0.08, ועד 'עמדה כלפי שימוש בגלולות בשנתיים הקרובות' מתאם 0.57), כך המתאם עם ההתנהגות בפועל גבוה יותר.\n\nמסקנה כוללת: הקשר עמדה-התנהגות מתחזק כשהעמדה נגישה יותר, וכשהיא נמדדת באותה רמת ספציפיות כמו ההתנהגות שרוצים לנבא.","mnemo":"💭 עובדה=קוגניטיבי."},{"id":"prof9_01","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"במה עוסקת הפסיכולוגיה ההתפתחותית?","a":"תחום העוסק בשינויים בתפקוד הפיזי/פסיכולוגי מרגע ההתעברות ולאורך כל החיים - מגלה כיצד ומדוע אורגניזמים משתנים, ותועד/מסביר את ההתפתחות בכל שלב.","explain":"פסיכולוגיה התפתחותית היא תחום בפסיכולוגיה העוסק בשינויים בתפקוד הפיזי והפסיכולוגי, מרגע ההתעברות ולאורך כל החיים. משימתה: לגלות כיצד אורגניזמים משתנים במרוצת הזמן ומדוע, וכן לתעד את ההתפתחות ולהסבירה. חוקרים במסגרתה בוחנים את התקופות שבהן יכולות ותפקודים שונים מופיעים לראשונה, וכיצד יכולות אלה משתנות. הנחת היסוד: תפקוד מנטלי, קשרים חברתיים והיבטים חיוניים נוספים של הטבע האנושי מתפתחים ומשתנים לאורך כל מחזור החיים - לא רק בילדות.","mnemo":"🎬 סרט-חיים אחד רץ מרחם ועד קבר"},{"id":"prof9_02","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"חשבו על 3 שינויים משמעותיים לאורך שלבי ההתפתחות, הקשורים לחומר הקורס.","a":"⚠️ דוגמאות מומחשות: (1) זיכרון - מילדות (זיכרון מוגבל) לבגרות (אסטרטגיות מורכבות) לבגרות מאוחרת (ירידה מסוימת). (2) שפה - מתינוקות (פרה-לשוני) לילדות (רכישת תחביר מהירה) להתבגרות (פרגמטיקה מתוחכמת). (3) ייחוס סיבתי - מילדים (פרשנות פשטנית) למבוגרים (ניתוח מורכב, כמו מודל קלי).","explain":"⚠️ דוגמאות מומחשות. (1) זיכרון: מילדות (זיכרון מוגבל, אסטרטגיות שינון חסרות) לבגרות (אסטרטגיות זיכרון מורכבות, נמוניות) לבגרות מאוחרת (ירידה מסוימת בקיבולת). (2) שפה: מתינוקות (שלב פרה-לשוני, בכי ומלמול) לילדות המוקדמת (רכישה מהירה של אוצר מילים ותחביר) להתבגרות/בגרות (שליטה מתוחכמת בפרגמטיקה - הבנת הקשר, אירוניה). (3) קוגניציה חברתית/ייחוס: מילדים (פרשנות פשטנית של התנהגות אחרים) למתבגרים/מבוגרים (ניתוח ייחוס מורכב, כמו מודל קלי - ייחודיות, עקיבות, הסכמה).","mnemo":"🧠 זיכרון+שפה+ייחוס - שלושה נהרות שמתפתחים"},{"id":"prof9_03","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהם מחקרים נורמטיביים?","a":"מחקרים החותרים לאפיין דמות אדם ממוצע בגיל/שלב מסוים. נאספים על ידי בחינה שיטתית של בני אדם בגילים שונים. מספקים נורמות (אמות מידה) המאפשרות השוואה בין פרטים וקבוצות.","explain":"מחקרים נורמטיביים חותרים לאפיין דמות של אדם ממוצע בגיל מסוים, או בשלב התפתחות מסוים - הופעתו החיצונית, כישוריו הקוגניטיביים וכדומה. כיצד נאספים הנתונים: חוקרים בוחנים בשיטתיות בני אדם בגילים שונים, וכך קובעים ציוני דרך בהתפתחות. מה הם באים למדוד: הנתונים מספקים נורמות - אמות מידה של התפתחות או של הישגים, המבוססות על תצפיות בבני אדם רבים - המאפשרות השוואה גם בין פרטים וגם בין קבוצות שונות.","mnemo":"📏 סרגל-נורמה מודד את \"הילד הממוצע\""},{"id":"prof9_04","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו גיל התפתחותי, ובמה הוא שונה מגיל כרונולוגי?","a":"גיל כרונולוגי=זמן שחלף מהלידה. גיל התפתחותי=הגיל הכרונולוגי שבו רוב האנשים מראים את רמת ההתפתחות שאדם מסוים מציג בפועל (למשל, ילד בן 3 עם מיומנויות מילוליות כשל בן 5 = גיל התפתחותי 5 במיומנות זו).","explain":"גיל כרונולוגי - מספר החודשים או השנים שחלפו מאז לידתו של אדם - מדד פשוט של זמן שחלף. גיל התפתחותי - הגיל הכרונולוגי שבו רוב בני האדם מראים את רמת ההתפתחות הפיזית או המנטלית המסוימת שאדם מסוים מציג. דוגמה: ילד בן שלוש בעל מיומנויות מילוליות כשל בן חמש, נחשב לבן גיל התפתחותי 5 במיומנויות מילוליות. ההבדל: הגיל הכרונולוגי הוא עובדה קבועה (זמן שחלף); הגיל ההתפתחותי הוא מדד יחסי, המשווה את רמת ההתפתחות בפועל לנורמה.","mnemo":"⏰ שעון (כרונולוגי) מול סרגל-גובה (התפתחותי)"},{"id":"prof9_reflection1","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו את תשובת הפסיכולוג לעינב לפי נורמות, גיל כרונולוגי וגיל התפתחותי.","a":"⚠️ יישום מומחש. הנורמות (ממחקרים נורמטיביים) מראות טווח רחב יחסית לתחילת דיבור - לא נקודת זמן קבועה. עינב בת שנה (גיל כרונולוגי) שעוד לא מדברת עשויה פשוט להיות בגיל התפתחותי מעט מאוחר יותר בתחום השפה, בלי שזה חריג. רק אם הפער יגדל מעבר לטווח הנורמלי (עוד 6 חודשים) יהיה מקום לדאגה אמיתית.","explain":"הפסיכולוג התייחס לנתונים על עינב באמצעות נורמות - אמות המידה שנקבעו ממחקרים נורמטיביים על אלפי תינוקות, המראות באיזה טווח גילים (לא נקודת זמן קבועה אחת) רוב התינוקות מתחילים לדבר. עינב בת שנה עדיין לא דיברה - מבחינת גילה הכרונולוגי (12 חודשים), ייתכן שהיא נראית 'מאוחרת' ביחס לתינוקות אחרים בני גילה. אך הפסיכולוג ידע, מתוך הנורמות, שטווח הזמן התקין להתחלת דיבור רחב יחסית. לכן הוא הבין שהגיל ההתפתחותי שלה בתחום השפה עשוי פשוט להיות מעט מאוחר יותר מגילה הכרונולוגי, מבלי שזה מעיד על בעיה. רק אם עינב לא תתחיל לדבר גם בתום עוד 6 חודשים - כלומר, אם הפער בין גילה הכרונולוגי לגילה ההתפתחותי בתחום השפה יהפוך גדול מדי ביחס לנורמות - יהיה מקום לחשוד בעיכוב אמיתי.","mnemo":"👶 עינב שקטה - הטווח לדיבור רחב, לא נקודה אחת"},{"id":"prof9_05","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו מחקר אורך?","a":"מערך מחקר שבו צופים באותם אנשים ובוחנים אותם שוב ושוב לאורך תקופה ארוכה (לעיתים שנים רבות).","explain":"מחקר אורך (longitudinal study) הוא מערך מחקר שבו חוקרים צופים באותם אנשים ובוחנים אותם שוב ושוב, לעתים קרובות לאורך שנים רבות. דוגמה: מחקר על תכנית High/Scope Perry בגני ילדים - החוקרים אספו נתונים על ילדים בני 3-4, ובדקו אותם שוב מדי שנה עד גיל 11, ולאחר מכן בגילים 14, 15, 19, 27 ו-40.","mnemo":"🔭 טלסקופ אחד עוקב אחר אותם אנשים לאורך שנים"},{"id":"prof9_06","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהם היתרונות והחסרונות של מחקר אורך?","a":"יתרון: אין בילבול בין שינוי תלוי-גיל לשונות חברתית-כלכלית (כולם חיו באותה תקופה). חסרונות: הכללה מוגבלת לשנתון הספציפי; יקר; נשירת משתתפים לאורך זמן.","explain":"יתרון: כל המשתתפים חיו באותה תקופה ותחת אותם תנאים חברתיים-כלכליים - אין בילבול בין שינויים תלויי-גיל לשונות הנובעת מנסיבות חברתיות שונות בין תקופות. חסרונות: (1) הכללות אפשריות רק לגבי אותו שנתון (cohort). (2) יקר מאוד - קשה להתחקות אחר משתתפים לאורך זמן. (3) נתונים אובדים בקלות - משתתפים עוזבים או נעלמים.","mnemo":"💸 יקר ונושר, אך בלי בלבול-שנתון"},{"id":"prof9_07","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו מחקר רוחב?","a":"מערך מחקר שבו בוחנים בזמן נתון אחד קבוצות משתתפים בגילים כרונולוגיים שונים, ומשווים ביניהם.","explain":"<b>מחקר-רוחב (cross-sectional)</b> - מערך-מחקר שבו בוחנים <b>בזמן-נתון-אחד</b> קבוצות-משתתפים ב<b>גילים-כרונולוגיים שונים</b>, ומשווים-ביניהם - למשל, בודקים-בו-זמנית ילדים-בני-5, בני-10, ובני-15, ומסיקים 'מגמת-התפתחות' מההבדלים-ביניהם. <b>היתרון</b>: מהיר-וזול (לא-צריך-לחכות-שנים). ⚠️ <b>המגבלה</b> (בהשוואה-למחקר-אורך שנלמד-בשאלה-סמוכה): לא-בודקים-אותם-אנשים-לאורך-זמן, אלא <b>קבוצות-שונות</b> - כך שהבדלים-שנמצאים עלולים-לנבוע <b>מהבדלי-דור (קוהורט)</b>, לא-רק-מהתפתחות-אמיתית-הקשורה-לגיל.","mnemo":"📸 תמונת-קבוצה אחת, גילאים שונים, רגע אחד"},{"id":"prof9_08","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהם היתרונות והחסרונות של מחקר רוחב?","a":"יתרון: מהיר וזול - כל הנתונים נאספים בבת אחת. חסרון: אפקט השנתון - קשה להבחין אם הבדלים נובעים מגיל או מתנאים היסטוריים/חברתיים שונים שכל קבוצת גיל חוותה.","explain":"יתרון: מהיר וזול יחסית - כל הנתונים נאספים בבת אחת, ללא מעקב ארוך שנים. חסרון מרכזי - אפקט השנתון: משווים בין פרטים השונים זה מזה גם בשנת לידתם וגם בגילם. לא ברור אילו הבדלים קשורים לגיל ואילו נובעים מהתנאים החברתיים/הפוליטיים השונים שכל שנתון חי בהם.","mnemo":"⚡ מהיר וזול, אך שנתון מבלבל"},{"id":"prof9_09","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד מחקרי אורך/רוחב משקפים את ההבחנה תוך-נבדקי/בין-נבדקי?","a":"⚠️ הקבלה. מחקר אורך=תוך-נבדקי (אותם משתתפים בכל ה\"תנאים\"/גילים). מחקר רוחב=בין-נבדקי (משתתפים שונים, כל אחד בתנאי/גיל אחד, משווים בין קבוצות).","explain":"⚠️ הקבלה. מחקר אורך משקף מערך תוך-נבדקי - אותם משתתפים נבחנים שוב ושוב לאורך זמן, בדיוק כמו במחקר תוך-נבדקי שבו כל משתתף עובר את כל התנאים הנבדקים (כאן, הגילים השונים). מחקר רוחב משקף מערך בין-נבדקי - משתתפים שונים (בגילים שונים) נבדקים ומושווים זה לזה, כמו במחקר בין-נבדקי שבו כל משתתף חשוף רק לתנאי אחד.","mnemo":"🔗 אורך=תוך-נבדקי | רוחב=בין-נבדקי"},{"id":"prof9_10","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"סכמו את ההבדלים בין מחקר אורך למחקר רוחב (טבלה 1).","a":"אורך: אותם משתתפים לאורך זמן, יקר, נשירה בעייתית, אך שולט על השפעת שנתון; מערך תוך-נבדקי. רוחב: משתתפים שונים בזמן אחד, זול ומהיר, ללא נשירה, אך סובל מאפקט שנתון; מערך בין-נבדקי.","explain":"אופן עריכה: אורך=אותם משתתפים נבחנים שוב ושוב; רוחב=משתתפים שונים בגילים שונים נבחנים פעם אחת. זמן המחקר: אורך=ממושך; רוחב=נקודת זמן אחת. נשירת נבדקים: אורך=בעיה משמעותית; רוחב=לא רלוונטי. עלות: אורך=גבוהה; רוחב=נמוכה. השפעת תרבות/היסטוריה: אורך=מבוקרת (אותו שנתון); רוחב=בעייתית (אפקט השנתון). סוג המערך: אורך=תוך-נבדקי; רוחב=בין-נבדקי.","mnemo":"📊 אורך=עמוק-איטי | רוחב=רחב-מהיר"},{"id":"prof9_21","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"אילו שינויים פיזיים מאפיינים את גיל ההתבגרות?","a":"קפיצת גדילה (גיל 10 בנות/12 בנים, הורמוני גדילה) - גדילה לא אחידה (ידיים/רגליים→זרועות→גו). התבגרות מינית: זרע חי (בנים) / תחילת ווסת (בנות, גיל 11-15). שינויי מוח: אונות המצח (תכנון/ויסות רגשי) ממשיכות להתפתח מעבר לילדות.","explain":"הסימן הראשון לתום הילדות הוא קפיצת הגדילה. בגיל 10 בקירוב אצל בנות ובגיל 12 אצל בנים זורמים הורמוני גדילה לתוך מחזור הדם. במשך שנים אחדות המתבגר עשוי לגדול 7.5-15 ס\"מ בשנה. הגדילה אינה מגיעה בבת אחת - ראשונות מגיעות לגודלן המלא כפות הידיים והרגליים, לאחר מכן הזרועות והרגליים, וקצב ההתפתחות של החלק האמצעי של הגוף הוא האטי ביותר.\n\nהתבגרות מינית (puberty) מביאה לבשלות מינית - אצל זכרים יצירת זרע חי (גיל ממוצע 12-14), אצל בנות תחילת הווסת (menarche, גיל ממוצע 12-13, טווח נורמלי 11-15).\n\nשינויים במוח: בעבר חשבו שרוב צמיחת המוח מסתיימת בשנים הראשונות. מחקרים עדכניים (הדמיית מוח) הראו שמוח המתבגר ממשיך להתפתח. אונות המצח (האחראיות על תכנון וויסות רגשות) הן האזורים שחל בהם השינוי הגדול ביותר מתקופת ההתבגרות המינית ועד לבגרות המוקדמת.","mnemo":"📈 קפיצת-גדילה+ווסת/זרע+מוח-עדיין-בבנייה"},{"id":"prof9_22","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד משפיעים השינויים המתחוללים במוחם של מתבגרים על התנהגותם?","a":"לאחר צמיחה חדשה (גיל 10-12), מתרחש סילוק קשרים עצביים לא בשימוש עד גיל 20, המשאיר מוח בוגר ויעיל. עד אז, אונות המצח (תכנון/ויסות רגשי) עדיין לא בשלות - מסביר נטילת סיכונים וקושי בוויסות רגשי אצל מתבגרים.","explain":"אחרי הצמיחה החדשה באונות המצח, המתחילה בסביבות גיל 10-12, מתרחש תהליך של סילוק קשרים עצביים שאינם בשימוש ('Use it or lose it'), הנמשך עד גיל 20. תהליך זה מותיר את הצעירים עם מוח בוגר, יעיל ומאורגן היטב.\n\nמכיוון שאונות המצח אחראיות בדיוק על תכנון וויסות רגשות, וההתפתחות שלהן נמשכת עד גיל 20 (מעבר לתקופת ההתבגרות המינית עצמה), נוצר פער בין הבשלות הפיזית/המינית המהירה של המתבגר לבין הבשלות המאוחרת יותר של אונות המצח. פער זה עשוי להסביר מאפיינים התנהגותיים אופייניים לגיל ההתבגרות - נטילת סיכונים, קושי בוויסות רגשי, וקושי יחסי בתכנון לטווח ארוך.","mnemo":"✂️ המוח גוזם קשרים מיותרים עד גיל 20"},{"id":"prof9_23","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"אילו שינויים חושיים מתחוללים במהלך הבגרות?","a":"ראייה: עדשות מצהיבות/מתקשחות - פגיעה בראיית צבעים (קצרי גל), קושי בעצמים קרובים, פגיעה בראיית לילה. שמיעה: קושי בתדרים גבוהים (בעיקר גברים), קול הדיבור עצמו נעשה גבוה יותר. רבייה: גיל המעבר בנשים (~50), ירידת איכות/נפח זרע בגברים (אחרי 40/60) - לא בהכרח פוגע בחוויה המינית.","explain":"ראייה: רובם המכריע של מבוגרים מעל גיל 65 חווים ירידה בתפקוד הראייה. עדשות העיניים מצהיבות ומאבדות מגמישותן - פוגע בראיית צבעים (בעיקר קצרי גל: סגול/כחול/ירוק), מקשה על ראיית עצמים קרובים, ופוגע בראיית לילה.\n\nשמיעה: אבדן שמיעה נפוץ בקרב בני 60+. קושי בשמיעת תדרים גבוהים, בעיקר אצל גברים - קשה להם להבין דיבור בקולות גבוהים (למרבה הפלא, קול הדיבור עצמו נעשה גבוה יותר עם הגיל, עקב התקשות מיתרי הקול).\n\nרבייה: בגיל 50 בערך חוות מרבית הנשים את גיל המעבר (הפסקת מחזור הווסת/ביוץ). אצל גברים, כמות הזרע התקין קטנה אחרי גיל 40, ונפח נוזל הזרע אחרי גיל 60 - אך שינויים אלה אינם פוגעים בהכרח בהיבטים אחרים של החוויה המינית.","mnemo":"👓 עדשות צהובות, אוזן כבדה, פוריות דועכת"},{"id":"prof9_24","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע חשוב לשמור על אורח חיים פעיל בגיל הבגרות?","a":"שינויים פיזיים רבים בבגרות נובעים מחוסר שימוש (disuse), לא מהזדקנות עצמה - \"המתמיד בפעילות שומר על חיות\". שמירה/חידוש פעילות גופנית (וגם מינית - אירובית, מעוררת, אינטראקציה חברתית) יכולה לחסוך קשיים הנתפסים כתוצאה בלתי נמנעת מהזדקנות.","explain":"שינויים פיזיים רבים בגיל הבגרות אינם נובעים מהזדקנות כשלעצמה, אלא הם תולדה של חוסר שימוש (disuse). המחקר תומך בכלל: 'המתמיד בפעילות - שומר על חיות' (Use it or lose it). מבוגרים בגיל מתקדם השומרים על משטר של פעילות גופנית (או מחדשים אותו) עשויים לחסוך מעצמם חלק מהקשיים הנתפסים לעתים קרובות כתוצאה בלתי נמנעת של ההזדקנות. גם המגע המיני מוצג כדוגמה - הוא אחד התענוגות הבריאים, ויכול לסייע בהזדקנות מוצלחת כי הוא מעורר, כולל פעילות אירובית, מגרה את הדמיון, ומהווה אינטראקציה חברתית חשובה.","mnemo":"🏃 איבר שלא משמש - נחלש, לא בגלל הגיל"},{"id":"prof9_25","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הציגו את הוויכוח בין אמפריציזם לנייטיביזם (\"טבע לעומת טיפוח\").","a":"אמפריציזם (לוק): התינוק נולד כ\"לוח חלק\" (tabula rasa), ההתפתחות נקבעת מהתנסות/סביבה. נייטיביזם (רוסו): הטבע המולד/המורשת האבולוציונית מעצבים את ההתפתחות. מסקנת הספר: יש אמת בשתיהן - ילדים מוכנים מלידה ללמוד מהתנסות (שילוב טבע+טיפוח).","explain":"נשאלת השאלה מהו ההסבר הטוב ביותר להבדלים העצומים בין תינוק שזה עתה נולד לבין ילד בן 10 - באיזו מידה ההתפתחות נקבעת על ידי התורשה (טבע) ובאיזו מידה היא תוצר של התנסויות (טיפוח).\n\nאמפריציזם (empiricism): התינוק נולד בלא ידע/מיומנויות, וההתנסות 'חורטת' מסרים על גבי הלוח החלק (tabula rasa) של תודעתו. הציע ג'ון לוק - מייחס את ההתפתחות להתנסות/לגירויים מהסביבה.\n\nנייטיביזם (nativism): הטבע המולד של האדם, או המורשת האבולוציונית שכל ילד מביא לעולם, היא התבנית המעצבת את ההתפתחות. תמך בה ז'אן ז'אק רוסו.\n\nמסקנת הספר: יש מידה של אמת בשתי האסכולות - הילדים מוכנים מלידה ללמוד מהתנסויותיהם בעולם (שילוב טבע וטיפוח).","mnemo":"📜 לוק=לוח-חלק | רוסו=זרע-מולד"},{"id":"prof9_26","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהן סכמות מנטליות לפי פיאז'ה?","a":"מבנים מנטליים המאפשרים לבני אדם להבין את העולם - אבני הבניין של השינוי ההתפתחותי. הסכמות הראשוניות הן משכל סנסורי-מוטורי (מציצה, הסתכלות, לפיתה, דחיפה).","explain":"פיאז'ה כינה בשם סכמות את המבנים המנטליים המאפשרים לבני אדם להבין את העולם - הן אבני הבניין של השינוי ההתפתחותי. פיאז'ה אפיין את הסכמות הראשוניות של הילד כמשכל סנסורי-מוטורי - מבנים מנטליים המכוונים רצפים סנסו-מוטוריים, כמו מציצה, הסתכלות, לפיתה ודחיפה.","mnemo":"🧱 לבנים ראשונות: מציצה-הבטה-לפיתה-דחיפה"},{"id":"prof9_27","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"איזה שינוי עוברות הסכמות לאורך ההתפתחות?","a":"מתחברות זו לזו, משתלבות ומתחלקות לדפוסי פעולה מגוונים ומורכבים יותר. דוגמה: ילד הדוחף עצם בלתי רצוי (סכמת דחיפה) כדי להגיע לעצם רצוי מאחוריו (סכמת הושטת יד).","explain":"<b>סכמות</b> (מבני-ידע-מנטליים, לפי-פיאז'ה) עוברות שינוי מתמשך לאורך-ההתפתחות: הן <b>מתחברות זו-לזו, משתלבות, ומתחלקות</b> לדפוסי-פעולה <b>מגוונים ומורכבים-יותר</b> עם-הזמן - לא-נשארות-נפרדות-ומבודדות. <b>הדוגמה</b>: ילד הדוחף-עצם-בלתי-רצוי מהדרך (<b>סכמת-דחיפה</b>) כדי-להגיע-לעצם-רצוי-מאחוריו, ואז מושיט-יד-לקחת-אותו (<b>סכמת-הושטת-יד</b>) - שתי-סכמות-פשוטות-ונפרדות שמתחברות ל<b>רצף-פעולה מורכב-יותר</b>, המשרת-מטרה-אחת-כוללת. ⚠️ זהו-בדיוק המנגנון (הבנוי-על אסימילציה+אקומודציה, מושגים-שנלמדים-בפרק) שדרכו-מתפתחת חשיבה-מורכבת-יותר מיכולות-פשוטות-ובסיסיות.","mnemo":"🔀 סכמות מתמזגות כמו פאזל שגדל"},{"id":"prof9_28","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהם הטמעה והתאמה, וכיצד הם מאפשרים צמיחה קוגניטיבית?","a":"הטמעה=שימוש בסכמות קיימות לארגון מידע חדש. התאמה=שינוי/ארגון מחדש של סכמות קיימות כדי להבין מידע חדש. דוגמה: מעבר משד לבקבוק (הטמעה) לקשית/כוס (התאמה נוספת). איזון בין השניים מפחית תלות במוחשי ומגביר חשיבה מופשטת.","explain":"הטמעה (assimilation) - משנה מידע חדש מהסביבה כדי שיתאים למה שכבר ידוע. הילד משתמש בסכמות קיימות כדי לארגן נתונים סנסוריים חדשים.\nהתאמה (accommodation) - מארגנת מחדש, או משנה, את הסכמות הקיימות אצל הילד כדי שמידע חדש יהיה מובן יותר.\n\nדוגמה: המעברים מיניקת שד לבקבוק לקשית לכוס. תגובת היניקה הראשונית היא רפלקס מלידה, אך על התינוק להתאימה במקצת כדי שפיו יתאים לצורת/גודל הפטמה של אמו. כשמסתגל לבקבוק, הוא משתמש ברכיבים רבים ללא שינוי (הטמעה), אך עליו לתפוס את פטמת הגומי ולהחזיק את הבקבוק בזווית מתאימה (התאמה).\n\nכיצד מאפשרים צמיחה: הפעלה מאוזנת של הטמעה והתאמה מאפשרת להתנהגות הילד ולידע שלו לצמצם את התלות במציאות המוחשית החיצונית ולהרחיב את ההישענות על חשיבה מופשטת.","mnemo":"🍼 שד→בקבוק=הטמעה | בקבוק→כוס=התאמה"},{"id":"prof9_29","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"סכמו את ארבעת שלבי פיאז'ה (גיל, מאפיינים, הישג, דוגמה, מונחים).","a":"סנסורי-מוטורי (0-2): קביעות אובייקט. קדם-אופרציונלי (2-7): אגוצנטריות, מרכוז (לא משמר - כוס גבוהה=\"יותר\"). אופרציות מוחשיות (7-11): שימור, הפיכות (מבין שכמות זהה). אופרציות פורמליות (11+): חשיבה מופשטת/דדוקטיבית.","explain":"סנסורי-מוטורי (0-2): מתחיל עם רצפים סנסוריים-מוטוריים בודדים המשתלבים בהדרגה. הישג: קביעות אובייקט (הבנה שעצמים ממשיכים להתקיים גם כשאינם נראים). דוגמה: תינוק בן 6 חודשים מאבד עניין בצעצוע מוסתר; רק בגיל שנתיים מחפש אותו בביטחון מלא.\n\nקדם-אופרציונלי (2-7): יכולת השימוש בייצוגים מנטליים/חשיבה סמלית משתפרת, אך עדיין מוגבל. מאפיינים: אגוצנטריות (אי-יכולת לראות מנקודת מבט הזולת) ומרכוז (התמקדות בממד בולט אחד). דוגמה: ילד בן 5 אומר שכוס גבוהה מכילה 'יותר' לימונדה, למרות שהכמות זהה (אינו משמר).\n\nאופרציות מוחשיות (7-11): הילד מגיע להבנת שימור ומסוגל לבצע אופרציות מנטליות על עצמים מוחשיים. מונחים: שימור (תכונות פיזיות אינן משתנות ללא הוספה/גריעה), הפיכות. דוגמה: ילד בן 7 יודע שהכמות זהה בשתי הכוסות למרות שהצורה שונה.\n\nאופרציות פורמליות (11+): מתפתחת חשיבה מופשטת והיפותטית וחשיבה דדוקטיבית מתקדמת. דוגמה: מתבגר יכול להקיש 'אם א', אזי ב'; לא ב' - אזי לא א'', גם ללא הדגמה קונקרטית.","mnemo":"🪜 סולם: חושי→קדם→מוחשי→מופשט"},{"id":"prof9_30","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מה למד ירין (בן 11 חודשים) מזריקת המוצץ החוזרת? באיזה שלב הוא נמצא?","a":"שלב סנסורי-מוטורי (0-2). ירין מתרגל את סכמת הזריקה ובונה קביעות אובייקט - לומד שהמוצץ ממשיך להתקיים גם כשנעלם מעיניו, וכי הוא יכול לפעול (לגרום לאמו) כדי להחזירו. גילו (11 חודשים) בדיוק בטווח שבו ילדים מתחילים לחפש עצמים שנעלמו.","explain":"ירין נמצא בשלב הסנסורי-מוטורי (0-2 שנים). זריקת המוצץ שוב ושוב ובקשה חוזרת מהאם להרימו היא דוגמה לתרגול חוזר ונשנה של סכמת פעולה (זריקה) והשקעה בבניית קביעות האובייקט - ירין לומד, דרך הפעולה החוזרת, שהמוצץ ממשיך להתקיים גם לאחר שנעלם מטווח ראייתו, ושהוא יכול לפעול על הסביבה (לגרום לאמו להרימו) כדי לגרום לעצם 'הנעדר' לחזור ולהיות נגיש שוב.\n\nבגיל 11 חודשים, ירין נמצא בדיוק בטווח הגילים (8-12 חודשים) שבו, לפי פיאז'ה, ילדים מתחילים לחפש עצמים שנעלמו - זה עדיין לפני גיל השנתיים, שבו יש לילדים ביטחון מלא שעצמים ממשיכים להתקיים.","mnemo":"🍭 ירין זורק-מוצץ שוב ושוב - בונה קביעות"},{"id":"prof9_31","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"איזו ביקורת מותחת בייארז'ון על תיאוריית פיאז'ה?","a":"פיאז'ה טען שקביעות אובייקט מושגת רק בגיל שנתיים. בייארז'ון הראתה (ניסוי המחיצה הרחבה/צרה) שתינוקות בני 4 חודשים כבר מפגינים הפתעה (הבטה ארוכה יותר) כשעצם \"נעלם באופן בלתי אפשרי\" - מוכיח שהיבטי קביעות אובייקט מתפתחים הרבה מוקדם יותר ממה שפיאז'ה חשב.","explain":"לפי פיאז'ה, קביעות האובייקט היא ההישג הגדול ביותר של ילד בן שנתיים. רנה בייארז'ון ועמיתיה פיתחו שיטות מחקר חדשניות שהראו שתינוקות מפתחים היבטים של קביעות האובייקט כבר בגיל 3-4 חודשים בלבד.\n\nהוכחה ניסויית: בני 4 חודשים צפו בנסיין מוריד עצם מלבני מאחורי מחיצה רחבה (יכולה להסתיר את כל העצם) או מחיצה צרה (אינה יכולה). כאשר מסך הסתיר את הרגע האחרון ואז נעלם עם יד ריקה - התינוקות שראו את המחיצה הצרה (מצב 'בלתי אפשרי' פיזית) הביטו בתצוגה 16 שניות יותר מאלה שראו את המחיצה הרחבה - מעיד שהופתעו, ולכן שמרו במידה מסוימת בזיכרונם את קיום העצם.\n\nהסתייגות: אין לראות בכך הוכחה לרכישה מלאה - ייתכן שהתינוקות רק יודעים ש'משהו אינו כשורה'. אך המסקנה הכללית היא שגם תינוקות רכים רוכשים ידע חשוב על העולם הפיזי, הרבה לפני הגיל שפיאז'ה טען.","mnemo":"👀 תינוק בן 4 חודשים כבר \"מופתע\" - מוקדם מדי לפיאז'ה"},{"id":"prof9_32","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי הפנמה לפי ויגוצקי? על איזה עיקרון של פיאז'ה היא מערערת?","a":"הפנמה=ילדים קולטים ידע מההקשר החברתי-תרבותי שלהם, המעצב את התפתחות הקוגניציה. מערערת על האוניברסליות של שלבי פיאז'ה (בעיקר אופרציות פורמליות) - מחקרים בין-תרבותיים הראו שהישגים אלה תלויים בסוג החינוך התרבותי/המדעי שהילד מקבל, לא רק בביולוגיה אוניברסלית.","explain":"לב ויגוצקי טען שילדים מתפתחים באמצעות תהליך הפנמה (internalization): הם קולטים ידע מההקשר החברתי שלהם, שיש לו השפעה ניכרת על הדרך שבה הקוגניציה מתפתחת. בניגוד לפיאז'ה שהדגיש שלבים ביולוגיים אוניברסליים, ויגוצקי הדגיש שהקוגניציה מתפתחת כדי לבצע פונקציות שבתרבות הילד נחשבות בעלות ערך.\n\nהפנמה מערערת על האוניברסליות של שלבי פיאז'ה - בעיקר שלב האופרציות הפורמליות. מחקרים בין-תרבותיים הראו שאנשים בתרבויות רבות לא סיפקו עדויות לכך שרכשו אופרציות פורמליות (לפי מטלות פיאז'ה). באחרית ימיו התחיל פיאז'ה עצמו לחשוב שההישגים שהגדיר כ'אופרציות פורמליות' תלויים בסוג חינוך מדעי ספציפי, לא בהכרח בשלבים ביולוגיים מולדים. דוגמה: ילדי פיאז'ה עצמו היו נראים 'מפגרים' אם היו מוערכים לפי הבנת מורכבויות האריגה, כפי שמוערכים ילדי שבט המאיה בגואטמלה.","mnemo":"🌍 ילד סופג תרבות כמו ספוג"},{"id":"prof9_33","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"אילו שינויים חלים במשכל בגיל הבגרות (רווחים והפסדים)?","a":"הפסד: משכל נזיל יורד יותר ממגובש, בעיקר בגלל האטת קצב העיבוד. רווח: תבונה (ידע עובדתי/תהליכי, הבנת הקשרים, התמודדות עם אי-ודאות) עולה עם החיים. פרופסורים ותיקים: ליקוי בלמידת צמדים, אך לא בזכירת סיפורים - פעילות מנטלית גבוהה מגנה.","explain":"אין הרבה עדויות לכך שהיכולות הקוגניטיביות הכלליות מידרדרות אצל זקנים בריאים - רק כ-5% מהאוכלוסייה חווים פגיעה ניכרת.\n\nהפסדים: ההידרדרות תלוית-הגיל מוגבלת לרוב ליכולות אחדות. הפרדה בין משכל מגובש (מילולי) למשכל נזיל (למידה מהירה) מראה הידרדרות רבה יותר במשכל הנזיל, המיוחסת בעיקר להאטה כללית בקצב העיבוד.\n\nרווחים: פסיכולוגים חוקרים רווחים תלויי-גיל בתבונה (wisdom) - מומחיות בהליכות החיים הבסיסיות: ידע עובדתי עשיר, ידע תהליכי עשיר, הבנת הקשרים במהלך החיים, וידע כיצד להתמודד עם אי-ודאות.\n\nדוגמה: השוואת פרופסורים בכירים (60-71) לעמיתיהם הצעירים (30-59) הראתה ליקויים תלויי-גיל בחלק מהמבחנים (למידת צמדי מילים), אך לא במדדים אחרים (זכירת סיפורים) - עיסוקם התובע פעילות מנטלית גבוהה מגן עליהם.","mnemo":"📉📈 נזיל יורד, תבונה עולה"},{"id":"prof9_34","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי אופטימיזציה בוררת עם פיצוי?","a":"אסטרטגיה להזדקנות מוצלחת (בלטס). בְרֵרה=פחות יעדים. אופטימיזציה=תרגול בתחומי עדיפות. פיצוי=דרכים חלופיות להתמודד עם הפסדים. דוגמה: רובינשטיין - פחות יצירות, יותר אימון, האטת קצב לפני קטעים מהירים.","explain":"אסטרטגיה להזדקנות מוצלחת שהציעו פול בלטס ומרגרט בלטס - הפקת המרב מהרווחים ומזעור השפעת ההפסדים הנורמליים של ההזדקנות.\n\nבְרֵרה - אנשים בוררים לעצמם פחות יעדים ומקטינים את היקפם.\nאופטימיזציה - אנשים מתרגלים/מתאמנים בתחומים שבראש סדר העדיפויות שלהם.\nפיצוי - אנשים בוחרים דרכים חלופיות להתמודד עם הפסדים.\n\nדוגמה: הפסנתרן ארתור רובינשטיין - (1) מנגן פחות יצירות (בְרֵרה). (2) מתאמן בכל יצירה לעתים קרובות יותר (אופטימיזציה). (3) מאט את קצב הנגינה לפני קטעים מהירים כדי שיישמעו מהירים יותר (פיצוי).","mnemo":"🎹 רובינשטיין: פחות שירים, יותר תרגול, האטה חכמה"},{"id":"prof9_35","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"אילו שינויים חלים בזיכרון בגיל הבגרות (שמור לעומת נפגע)?","a":"שמור: נגישות למאגר הידע הכללי וזיכרון אישי מהעבר הרחוק (90% זיהוי חברים לאחר 35 שנה). נפגע: תהליכי ארגון מידע חדש, אחסונו ושליפתו.","explain":"במבחני זיכרון אחדים, מבוגרים מעל גיל 60 מצליחים פחות ממבוגרים צעירים - זיכרונם נפגע גם אם הם בעלי השכלה רחבה.\n\nתפקודים שמורים: ההזדקנות אינה מצמצמת את הנגישות למאגר הידע הכללי, ולמידע אישי על אירועים מהעבר הרחוק. במחקר זיהוי שמות ופנים, מבוגרים בגיל העמידה זיהו 90% מחבריהם לספסל הלימודים 35 שנים אחרי סיום התיכון; מבוגרים יותר זיהו 70-80% אחרי 50 שנה.\n\nתפקודים נפגעים: ההזדקנות משפיעה על התהליכים המאפשרים לארגן מידע חדש ביעילות, לאחסן אותו ולשלפו.","mnemo":"🗄️ ישן שמור, חדש נשמט"},{"id":"prof9_36","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו את שינויי הזיכרון בהזדקנות באמצעות \"פיצוי\" ו\"הסחת דעת\".","a":"פיצוי=גיוס אזורי מוח נוספים (סימטריה בין המיספרות) משפר ביצועים - מתאם חיובי עם הצלחה. הסחת דעת=חוסר יכולת לדכא פעילות מוח לא-רלוונטית, פוגעת בביצוע. שני המנגנונים פועלים יחד במוח המזדקן.","explain":"מחקרי fMRI הראו שבמוח המזדקן קיימת סימטריה גדולה יותר בתפקוד בין שתי ההמיספרות - זקנים מפעילים אזורי מוח משני הצדדים במקביל, בעוד צעירים מפעילים בעיקר צד אחד.\n\nפיצוי: כאשר מוח מזדקן מגייס אזורים שונים מאלה שמוח צעיר משתמש בהם, מתרחשת פעילות המייצגת פיצוי על שינויים אחרים במוח. הוכחה: ככל שהאזורים הנוספים היו פעילים יותר, ביצועי הזקנים במבחן ההיכר היו טובים יותר.\n\nהסחת דעת: פעילות מוח ייחודית לזקנים עשויה לשקף חוסר יכולת לדכא פעילות מוח שאינה רלוונטית למטלה. ההופעה העקבית של פעילות מוח לא-רלוונטית מעידה שחלק מהבדלי הגיל נובעים מהסחת דעת, לא מפיצוי מועיל.\n\nמסקנה: חוקרים מצאו ראיות שפיצוי והסחת דעת כאחד פועלים במוח המזדקן - שני מנגנונים שונים התורמים לשינויים הנצפים.","mnemo":"🧠↔️🧠 שני חצאי-מוח מגייסים כוחות, אך גם מוסחים"},{"id":"prof9_37","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"אילו גורמים משפיעים על ההתפתחות החברתית - מולדים או נלמדים?","a":"⚠️ שילוב של שניהם. מולדים (ביולוגיים): בשילה/התבגרות קובעים תזמון ומסגרת (למשל, הליכה/שפה פותחות אפשרויות חברתיות חדשות). נלמדים (תרבותיים/סביבתיים): תרבות וכלכלה מעצבים את אופן ההתנהגות החברתית (למשל, אי-שוויון בין קבוצות). שני הגורמים משפיעים זה על זה במשולב.","explain":"⚠️ שילוב של שניהם. הסביבה החברתית והתרבותית וההתבגרות הביולוגית משפיעות זו על זו, ובכך יוצרות לכל תקופה בחיים אתגרים ותגמולים ייחודיים.\n\nגורמים מולדים (ביולוגיים): ההתבגרות הביולוגית (בשילה, שינויים הורמונליים, התפתחות המוח) קובעת את התזמון והמסגרת הכללית - למשל, יכולת ההליכה והשפה פותחות בפני הילד אפשרויות חדשות לחקירה ולאינטראקציה חברתית.\n\nגורמים נלמדים (סביבתיים/תרבותיים): הסביבה החברתית/תרבותית משפיעה רבות על האופן שבו מתפתחת ההתנהגות החברתית. דוגמה: אנשים בתנאים כלכליים קשים נתונים ללחצים החורגים מ'התפתחות נורמלית'. התרבות האמריקנית כופה נסיבות חיים שונות על גברים, נשים וקבוצות מיעוט - מצבן הכלכלי של נשים זקנות גרוע בדרך כלל ממצב גברים זקנים, ומצבן של נשים אפרו-אמריקניות גרוע אף יותר - הבדלים הנובעים ישירות מאי-הצדק המובנה בחברה, לא מגורמים ביולוגיים.\n\nמסקנה: משימות חייו של אדם מושפעות הן משינויים ביולוגיים, הן משינויים חברתיים-תרבותיים.","mnemo":"🚶🗣️ הליכה ושפה פותחות דלת, תרבות בוחרת מה מאחוריה"},{"id":"prof9_38","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"התאימו דמויות משמעותיות לכל שלב של אריקסון (טבלה 3).","a":"אמון=מטפל עיקרי (צרכים בסיסיים). אוטונומיה=הורים (גבולות גוף). יזמה=תגובות הורים (מול משפחה). כשירות=השוואה לבני גיל. זהות=קבוצת שווים. אינטימיות=בן/בת זוג. פוריות=מעגל משפחתי (ילדים/הורים מזדקנים). אחדות האני=מבט לאחור על חיים ואחרים משמעותיים.","explain":"1½-0 (אמון לעומת חשדנות): דמות המטפל העיקרי כמספק צרכים בסיסיים (מזון, חום).\n3-1½ (אוטונומיה לעומת ספק-עצמי): ההורים כמגדירים את גבולות ההתנהלות של הילד על גופו.\n6-3 (יזמה לעומת אשם): תגובות ההורים המשקפות את ההתנהגות המצופה מהילד מול הוריו ואחיו.\n6-התבגרות מינית (כשירות מול נחיתות): השוואה לבני קבוצת השווים, המאפשרת לילד להבין מה מקומו האינטלקטואלי והחברתי היחסי.\nגיל ההתבגרות (גיבוש זהות לעומת בלבול תפקידים): השתייכות לבני קבוצת השווים המספקת הגדרת זהות.\nבגרות מוקדמת (אינטימיות לעומת בדידות): דינמיקה של יחסים עם בני זוג, הגדרת גבולות האני וזוגיות.\nבגרות (פוריות לעומת קיפאון): המעגל המשפחתי כמוקד ההתייחסות (ילדים והורים מזדקנים).\nבגרות מאוחרת (אחדות האני לעומת ייאוש): האדם מתבונן לאחור על חייו ועל האחרים המשמעותיים שליוו אותו בדרכו.\n\nההיגיון: כל שלב מוגדר על ידי הדמות/המסגרת החברתית המרכזית באותו גיל - מטפל→הורים→משפחה קרובה→קבוצת שווים→זוגיות→משפחה מורחבת→מבט לאחור על החיים כולם.","mnemo":"👨‍👩‍👧 מטפל→הורים→משפחה→שווים→זוג→ילדים→מבט-לאחור"},{"id":"prof9_39","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו תהליך החִברוּת? הסבירו את השפעתו על מהלך ההתפתחות.","a":"תהליך הנמשך כל החיים שבו התנהגות/ערכים/עמדות מעוצבים להתאים לרצוי בחברה - באמצעות משפחה, חברים, מורים, מוסדות. למשפחה ההשפעה הגדולה ביותר - יוצרת דפוסי היענות בסיסיים ההופכים לבסיס סגנון היחס לזולת לכל החיים.","explain":"חִברוּת הוא תהליך הנמשך כל החיים, שבו דפוסי ההתנהגות של האדם, ערכיו, אמות המידה שלו, מיומנויותיו, עמדותיו ומניעיו מעוצבים כך שיתאימו למה שנחשב רצוי בחברה מסוימת. בתהליך זה מעורבים אנשים רבים - קרובי משפחה, חברים, מורים - ומוסדות, כמו בתי ספר ובתי תפילה.\n\nהשפעתו על ההתפתחות: למשפחה ההשפעה הגדולה ביותר כגורם המעצב והמווסת את החברות. יהא מבנה המשפחה אשר יהא, המשפחה מסייעת לאדם ליצור את דפוסי ההיענות הבסיסיים לאחרים - ודפוסים אלה הופכים לבסיס סגנון היחס של האדם לזולת במהלך כל שנות חייו.","mnemo":"🏫 משפחה+חברים+מורים מעצבים \"מה מקובל\""},{"id":"prof9_40","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו מזג לפי קגן וכיצד הוא בא לידי ביטוי בגילאים שונים?","a":"רמת תגובה רגשית/התנהגותית לסביבה, מבוססת ביולוגית. מאופקים (~10%, זהירים/מרוסנים) מול נטולי עכבות (~25%, חברותיים/ספונטניים) - נמצא כבר ברחם. מחקרי אורך: המשכיות מגיל 4 חודשים עד שנתיים/ארבע - נדיר לעבור לגמרי מקטגוריה לקטגוריה, גם אם העוצמה מתמתנת.","explain":"מזג הוא רמת התגובה הרגשית וההתנהגותית לסביבה, המושתתת על בסיס ביולוגי. ג'רום קגן ועמיתיו הראו שמקצת התינוקות 'נולדים ביישנים' ואחרים 'פתוחים'.\n\nתינוקות מאופקים (inhibited) - עקביים בהיותם זהירים ומאופקים רגשית מול אנשים/מצבים בלתי מוכרים.\nתינוקות נטולי עכבות (uninhibited) - עקביים בהיותם חברותיים, מביעים רגשות בספונטניות, כמעט אינם חוששים.\n\nבמדגם אחד: כ-10% מאופקים, כ-25% נטולי עכבות. נמצאו הבדלי מזג אפילו ברחם - רמות פעילות עובר גבוהות נקשרו לקשיי הסתגלות לאחר הלידה.\n\nכיצד בא לידי ביטוי בגילאים שונים: מחקרי אורך הראו המשכיות ארוכת טווח - ילדים שהפגינו תגובתיות מוטורית גבוהה ובכי בגיל 4 חודשים הראו מידת פחד גבוהה יותר במצבים בלתי מוכרים גם בגיל שנתיים וארבע. עם זאת, נדיר שילדים עוברים מקטגוריה לקטגוריה לגמרי, גם אם העוצמה מתמתנת עם הגיל.","mnemo":"🙈🙉 ביישן (10%) מול פתוח (25%) - כבר ברחם"},{"id":"prof9_41","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי היקשרות? הסבירו את תפקידה ההישרדותי.","a":"קשר רגשי הדוק, אינטנסיבי ומתמשך בין ילד לדמות מטפלת. תפקיד הישרדותי: מבטיח סיפוק צרכים בסיסיים (מזון, הגנה) שהילד אינו יכול לספק לעצמו.","explain":"ההתפתחות החברתית מתחילה ביצירת קשר רגשי הדוק בין ילד לאמו, אביו או דמות מטפלת קבועה אחרת. קשר חברתי-רגשי, אינטנסיבי ומתמשך זה מכונה היקשרות (attachment).\n\nהתפקיד ההישרדותי: מאחר שילדים אינם מסוגלים להאכיל את עצמם או להגן על עצמם, התפקיד הראשוני של ההיקשרות הוא להבטיח הישרדות - הקשר לדמות מטפלת מבטיח שהצרכים הבסיסיים (מזון, הגנה, חום) יסופקו.","mnemo":"🍼🛡️ קשר=מזון+הגנה שהתינוק לא מספק לבד"},{"id":"prof9_42","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי הטבעה? מדוע היא חיונית?","a":"קשירה אוטומטית ומיידית של היילוד לעצם הנע הראשון שהוא רואה/שומע, בתקופה קריטית, בלתי הפיכה בנקל. חיונית: מבטיחה קרבה מיידית להורה להישרדות, ללא צורך בלמידה ממושכת - אך עלולה \"לטעות\" אם העצם הראשון אינו ההורה האמיתי.","explain":"הטבעה (imprinting) - תהליך שבו יש מינים שבהם היילוד נקשר באופן אוטומטי לעצם הנע הראשון שהוא רואה או שומע. מתרחש במהירות, בתקופה קריטית, ואינו ניתן לשינוי בנקל. הדגמה: קונרד לורנץ הראה שאווז צעיר שזה עתה בקע, אם ילך בעקבות עצם זז 10 דקות, ייקשר אליו כ'אם' - גם אם זהו בן אדם.\n\nמדוע חיונית: מבטיחה שהצאצא הצעיר יישאר קרוב לדמות ההורית מיד מרגע הלידה/הבקיעה, ללא צורך בלמידה ממושכת - חיוני להישרדות מיידית. עם זאת, האוטומטיות עלולה גם ליצור בעיות - אם העצם הראשון שנצפה אינו ההורה האמיתי, ההטבעה עדיין תתרחש.","mnemo":"🦆 אווזון הולך אחרי הראשון-שזז, בלי שאלות"},{"id":"prof9_44","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"אילו התנהגויות מאוחרות אפשר לנבא מדפוס היקשרות בינקות, ומדוע?","a":"ניבוי: חברתיות/פופולריות בבית הספר, פחות חרדה חברתית, איכות קשרי אהבה בבגרות. הסבר: מודל עבודה פנימי (סכמת ציפיות מהיקשרות מוקדמת) מעצב איך הילד ניגש לקשרים עתידיים - היקשרות בטוחה=ציפייה לעולם חברתי אמין=ביטחון בקשרים חדשים.","explain":"מחקרי אורך הראו שקטגוריזציה מבחן המצב הזר - ובייחוד החלוקה הכללית לילדים בעלי היקשרות בטוחה מול לא בטוחה - חוזה ביעילות התנהגויות מאוחרות: חברתיות (ילדים עם היקשרות בטוחה בגיל 15 חודשים היו אהודים יותר בבית הספר בגיל 8-9), פחות חרדה חברתית, והמשכיות דומה נצפתה גם בגיל 10 ובגיל ההתבגרות. חוקרים משתמשים במדדי היקשרות אף כדי לנבא איכות קשרי אהבה בין מבוגרים.\n\nמדוע דווקא התנהגויות אלה: ⚠️ מודל העבודה הפנימי (סכמה שנוצרה מיחסי ההיקשרות המוקדמים) מעצב ציפיות לגבי קשרים חברתיים עתידיים. ילד עם היקשרות בטוחה בונה ציפייה שהעולם החברתי אמין ותומך, ולכן ניגש לאינטראקציות חדשות בביטחון ופתיחות - מסביר את החברתיות הרבה יותר וירידת החרדה החברתית.","mnemo":"🔮 היקשרות-מוקדמת=מפת-דרכים לקשרים עתידיים"},{"id":"prof9_45","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע אחים לאותם הורים יכולים לפתח סגנונות היקשרות שונים?","a":"⚠️ הסבר סינתזה. היקשרות נוצרת מהאינטראקציה בין מזג התינוק (מולד, שונה מילד לילד) לבין תגובת ההורה - אותה התנהגות הורית עשויה להתפרש אחרת לפי מזג הילד. גם ההורים עצמם עשויים להגיב אחרת לכל ילד בהתאם למזגו הייחודי.","explain":"⚠️ הסבר סינתזה. מכיוון שהמזג הוא מולד וייחודי לכל תינוק, וההיקשרות נוצרת מתוך האינטראקציה הספציפית בין המזג הייחודי של התינוק לבין דרכי התגובה של ההורה - שני אחים, גם אם מקבלים את אותה ההתנהגות ההורית בדיוק, עשויים לחוות אותה אחרת לחלוטין בהתאם למזגם השונה. תינוק בעל מזג 'קל' עשוי לפרש היעדרות זמנית של ההורה כבלתי מטרידה, בעוד אח בעל מזג רגיש/מאופק יותר עשוי לחוות אותה כמאיימת יותר. בנוסף, ייתכן שההורים עצמם מגיבים אחרת לכל ילד בהתאם למזגו.","mnemo":"👶👶 שני ילדים, שני מזגים - אותו הורה נתפס אחרת"},{"id":"prof9_46","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהם שני הממדים להגדרת סגנונות הורות?","a":"דרישתיות=נכונות ההורים לפעול כסוכני חברות (משמעת, כללים, סטנדרטים). היענות=הכרת ההורים באינדיווידואליות של הילד (צרכים, תקשורת פתוחה).","explain":"דרישתיות (demandingness) - נכונות ההורים לפעול כסוכני חִברות - עד כמה ההורה דורש מהילד לדבוק בכללי התנהגות, מטיל משמעת ומציב סטנדרטים.\nהיענות (responsiveness) - הכרת ההורים באינדיווידואליות של הילד - עד כמה ההורה נענה לצרכיו, לרגשותיו ולאישיותו הייחודית, ושומר על תקשורת פתוחה.","mnemo":"📏❤️ דרישתיות (גבולות) + היענות (חום)"},{"id":"prof9_47","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תארו את ארבעת סגנונות ההורות, בעזרת שני הממדים.","a":"סמכותי (דרישתי+נענה)=משמעת+תקשורת פתוחה, הכי יעיל. סמכותני (דרישתי+לא נענה)=משמעת ללא הכרה באוטונומיה. ותרני (לא דרישתי+נענה)=נענה ללא הנחיית חוקים. מזניח (לא דרישתי+לא נענה)=אדיש ולא מעורב.","explain":"סמכותי (authoritative, דרישתי+נענה): דורש דבקות בכללי התנהגות נאותים, אך בה בעת נענה - שומר על תקשורת פתוחה, מטפח את יכולת הילד לווסת התנהגות. הסבירות הגבוהה ביותר ליצור קשר יעיל.\nסמכותני (authoritarian, דרישתי+לא נענה): משליט משמעת, תשומת לב מעטה מאוד לאוטונומיית הילד - כוחני, דוחה.\nותרני (indulgent, לא דרישתי+נענה): נענה לילד, אך אינו מסייע לו ללמוד את מבנה החוקים החברתיים - ממעט בדרישות ובשליטה.\nמזניח (neglecting, לא דרישתי+לא נענה): אינו משליט משמעת וגם אינו נענה לאינדיווידואליות - מתעלם, אדיש.\n\nהסגנון הסמכותי משלב גבוה בשני הממדים גם יחד, מה שמסביר את יעילותו.","mnemo":"🎛️ שני כפתורים=4 שילובים: סמכותי/סמכותני/ותרני/מזניח"},{"id":"prof9_48","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"האם אפשר לנבא התנהגויות ספציפיות של ילדים מסגנון ההורות?","a":"לא במישרין - הורים באותו סגנון יכולים לשים דגש על מטרות חברות שונות (לימודים, ספורט, ערכים). דרכי הפעולה נוצרות לפי המטרות הספציפיות שההורה מדגיש, לא רק לפי הסגנון הכללי.","explain":"לא במידה פשוטה וישירה. הורים בעלי אותו סגנון יכולים להציב סדרי עדיפויות שונים למטרות החברות. דרכי הפעולה ההוריות נוצרות על פי מטרות מסוימות - הורים סמכותיים הרוצים בהצלחת ילדיהם בבית הספר עשויים ליצור סביבה מעודדת, ויסביר שהילד יחתור להצליח. אך מאחר שלא כל ההורים הסמכותיים מעריכים דווקא הצלחה בבית הספר - לא נוכל לנבא ביצועים רק על סמך הסגנון עצמו, ללא ידיעת המטרות הספציפיות. הן העמדות הכלליות והן ההתנהגות הספציפית חשובות.","mnemo":"🎯 סגנון=מסגרת, אבל היעד המדויק תלוי בהורה"},{"id":"prof9_49","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תארו את מחקר הארלו על מגע מנחם. תואם/סותר תיאוריית הארון?","a":"קופיפים הופרדו מאמם, ניתנה להם בחירה בין \"אם\" מחוט תיל (נתנה חלב) ו\"אם\" מבד מגבת. הקופיפים העדיפו את אם המגבת גם כשרק התיל נתן חלב - סותר את תיאוריית הארון (מזון), תומך בחשיבות המגע המנחם.","explain":"תיאוריית הארון (cupboard theory) של פרויד טענה שתינוקות נקשרים להוריהם כי הם מספקים מזון.\n\nמחקר הארלו: הפריד קופי מקוק מאמותיהם ברגע הלידה, ונתן להם נגישות לשתי 'אימהות' מלאכותיות - אחת מחוט תיל, השנייה מבד מגבת. הקופיפים התרפקו על האם מבד המגבת ושהו זמן מועט על האם מחוט התיל - גם כאשר רק התיל נתן חלב! הם השתמשו באם מבד המגבת כמקור למגע מנחם כשהיו מפוחדים, וכבסיס יציאה לחקירת גירויים חדשים.\n\nהאם תואם/סותר: סותר בבירור - אם תיאוריית הארון הייתה נכונה, הקופיפים היו אמורים להעדיף את מספקת המזון, ללא קשר לחומר. הממצאים הראו את ההפך - העדפה מוחלטת למגע מנחם על פני סיפוק מזון.","mnemo":"🧸 קוף בוחר חיבוק-בד על פני חלב-תיל"},{"id":"prof9_50","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"האם הקופים שגדלו עם \"אימהות המגבת\" התפתחו תקין?","a":"לא לגמרי. נראו תקינים בתחילה, אך בבגרותם, קופים שנמנעה מהם אינטראקציה הדדית עם קופים חיים אחרים (לא רק עם האם המלאכותית) התקשו ליצור קשרים חברתיים ומיניים נורמליים - מגע מנחם לבדו לא הספיק.","explain":"בתחילה נראה שהתפתחו באופן נורמלי. אך תמונה שונה התגלתה בבגרותם - כשהגיעה שעתן של הקופות שגדלו כך להיות לאימהות: קופים שבצעירותם נמנע מהם ליצור קשרים הדדיים עם קופים אחרים הנענים להם (לא רק עם אם מלאכותית), התקשו ליצור קשרים חברתיים ומיניים נורמליים בבגרותם. מסקנה: מגע מנחם מהאם המלאכותית לא היה מספיק לבדו - נדרשת גם אינטראקציה הדדית עם קופים אחרים חיים.","mnemo":"😔 חיבוק-בד לבד לא הכין אותם לחיים אמיתיים"},{"id":"prof9_51","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"אילו מסקנות עולות ממחקרי חסך בדמות מטפל עיקרי בבני אדם?","a":"חסך במגע/קשר קשור לפגיעה בגדילה גופנית ובסיכויי הישרדות (90% תמותה בבתי יתומים, 1915). ילדים שגדלו במוסדות: פחות היקשרות בטוחה (20% מול 74% בבית) ותגובת מוח לא נורמלית לאינטראקציה חברתית בגיל 4.","explain":"מחקרים מלמדים שהיעדר יחסי אהבה הדוקים בינקות משפיע על הגדילה הגופנית ואף על סיכויי ההישרדות. ב-1915 דווח שעל אף טיפול פיזי ראוי, 90% מהיילודים בבתי היתומים בבולטימור מתו בשנת חייהם הראשונה. מחקרים על תינוקות מאושפזים מצאו שלמרות תזונה הולמת, הילדים פיתחו דלקות דרכי נשימה, חום ממקור לא ידוע, לא עלו במשקל.\n\nמחקרים עכשוויים: השוואה בין ילדים שגדלו בבית לילדים שגדלו במוסדות (90% מחייהם) מצאה ש-74% מהילדים שגדלו בבית היו בעלי היקשרות בטוחה, לעומת 20% בלבד מהילדים שגדלו במוסדות. בנוסף, ילדים ששהו בבתי יתומים בשנה וחצי הראשונות הראו דפוס תגובת מוח לא נורמלי (ברמות הורמונליות) באינטראקציה עם זר, בגיל 4.","mnemo":"😢 בית-יתומים בלי חיבוק - תמותה גבוהה"},{"id":"prof9_52","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע אי אפשר להסיק מסקנות סיבתיות על חסך באימהות בבני אדם (פרק 2)?","a":"⚠️ מחקרים אלה הם מתאמיים בלבד - לא ניתן להקצות תינוקות באקראי לחסך/לא-חסך מטעמים אתיים. ילדים שגדלו במוסדות נבדלים מראש בגורמים נוספים (עוני, בריאות הורים, תזונה) - משתנים מתערבים אפשריים. מתאם אינו מעיד סיבתיות.","explain":"⚠️ המחקרים על חסך אצל בני אדם הם מחקרים מתאמיים (קורלטיביים), לא ניסויים מבוקרים - לא ניתן, מטעמים אתיים, להקצות באקראי תינוקות ל'קבוצת חסך' ולקבוצת ביקורת, כפי שנעשה עם קופי הארלו. ילדים שגדלו במוסדות כבר נבדלים מראש מילדים שגדלו בבית מבחינות רבות נוספות (נסיבות המסירה למוסד, עוני, בעיות בריאות הוריות, תזונה) - ייתכנו משתנים מתערבים רבים המסבירים את ההבדלים שנמצאו. בהתאם לעיקרון מפרק 2 - מתאם אינו מעיד בהכרח על סיבתיות.","mnemo":"⚖️ לא ניתן להקצות תינוקות לחסך - רק מתאם"},{"id":"prof9_53","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"סכמו את תפקידי המטפל העיקרי במהלך הילדות.","a":"⚠️ סיכום סינתזה. (1) הישרדות פיזית (מזון/הגנה). (2) מגע מנחם/ביטחון רגשי (בסיס לחקירה). (3) בניית מודל עבודה פנימי (ציפיות לקשרים עתידיים). (4) סוכן חברות (עיצוב ערכים/התנהגות). (5) מודל לחיקוי. (6) אפשור אינטראקציה הדדית לפיתוח מיומנויות חברתיות בוגרות.","explain":"⚠️ סיכום סינתזה. (1) הבטחת הישרדות פיזית - סיפוק צרכים בסיסיים (מזון, חום, הגנה). (2) מקור למגע מנחם ולביטחון רגשי - נחמה בעת פחד/מצוקה, ובסיס בטוח לחקירת הסביבה (הארלו). (3) בניית מודל עבודה פנימי - סכמת קשרים חברתיים המעצבת ציפיות לגבי קשרים עתידיים. (4) סוכן חִברוּת מרכזי - עיצוב דפוסי התנהגות/ערכים/עמדות דרך סגנון ההורות. (5) מודל לחיקוי ולמידה חברתית - ככל שההיקשרות מתרחבת לבני משפחה נוספים. (6) אפשור אינטראקציה חברתית הדדית - נדרשת (לא רק מגע חד-צדדי) לפיתוח מיומנויות חברתיות/מיניות תקינות בבגרות.","mnemo":"🛡️❤️🗺️👥 מגן+מנחם+ממפה-עתיד+סוכן-חברות"},{"id":"prof9_54","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע נקרא גיל ההתבגרות \"סער ופרץ\"?","a":"נקודת המבט המסורתית (הול, ואחריו הפרוידיאנים) רואה בהתבגרות תקופה סוערת עם שינויים קיצוניים במצב הרוח והתנהגות בלתי צפויה - חלקם טענו שסערה זו חלק מהתקינות עצמה, ושהיעדרה מעיד על עצירת התפתחות (אנה פרויד).","explain":"נקודת המבט המסורתית מנבאת תקופת חיים סוערת במיוחד, המאופיינת בשינויים קיצוניים במצב הרוח ובהתנהגות בלתי צפויה - נהוג לכנותה 'הסער והפרץ'. שורשיה עד סופרים רומנטיים בשלהי המאה ה-18 (כמו גתה). סטנלי הול, הפסיכולוג הראשון שכתב באריכות על ההתבגרות (1904), היה מהתומכים המובהקים. אחריו, תיאורטיקנים פרוידיאניים טענו שסערת רגשות עזה היא חלק מההתבגרות התקינה, ושהיעדרה מעיד על עצירת התפתחות. אנה פרויד כתבה: 'להיות נורמלי בתקופת ההתבגרות, כשהוא לעצמו, זה לא נורמלי'.","mnemo":"⛈️ הול ופרויד: התבגרות=סופה נפשית טבעית"},{"id":"prof9_55","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"ה\"סער ופרץ\" נובע מסיבות ביולוגיות או סביבתיות?","a":"בעיקר סביבתיות/תרבותיות - מיד ובנדיקט הראו שתרבויות לא-מערביות רבות אינן חוות \"סער ופרץ\" כלל (מעבר הדרגתי לאחריות בוגרים). זה סותר גישה ביולוגית טהורה. במערב, קשור לחתירה לעצמאות/זהות (אריקסון), לא לביולוגיה בלבד.","explain":"⚠️ בעיקר סביבתיות/תרבותיות. שתי אנתרופולוגיות תרבותיות, מרגרט מיד ורות בנדיקט, גרסו שתיאוריית 'הסער והפרץ' אינה חלה על רבות מהתרבויות הלא-מערביות - הן תיארו תרבויות שבהן ילדים מקבלים בהדרגה תחומי אחריות בוגרים, ללא מעבר פתאומי הכרוך במתח. מחקר בן זמננו (Arnett) אישש שחוויית ההתבגרות שונה בתרבויות שונות - סותר תיאוריות הרואות בביולוגיה גורם יחיד.\n\nעם זאת, יש גם רכיב סביבתי-חברתי ברור: מחקר שעקב אחר 1,300 מתבגרים מגיל 11-14 מצא ניגוד עמוק יותר בין המתבגרים להוריהם בגיל 14 - קשור לחתירה לעצמאות ולגיבוש זהות (אריקסון), לא לגורם ביולוגי בלבד.","mnemo":"🌍 בתרבויות אחרות - בלי סערה כלל"},{"id":"prof9_56","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"סכמו את חשיבות קבוצת השווים לבני הנוער - מרכיבים חיוביים ושליליים.","a":"קבוצת שווים (חברויות/קליקות/חבורות) מתחרה בהורים בעיצוב זהות המתבגר. חיובי: \"שעות כושר\" לתפקוד חברתי, הכנה לעתיד. שלילי: מגביר נטילת סיכונים (הוכח בניסוי משחק \"פחדן\" - השפעה הגדולה ביותר אצל מתבגרים), רגישות גבוהה לקבוצה מנבאת סיכון לסמים/אלכוהול.","explain":"גיל ההתבגרות מסמן את התקופה הראשונה שבה קבוצת השווים מתחרה בהורים בעיצוב עמדות והתנהגות. הקשרים מתנהלים בשלוש רמות: חברויות (יחידים, תמיכה), קליקות (6-12 פרטים), וחבורות (קבוצות גדולות, קשרים רופפים).\n\nמרכיבים חיוביים: קבוצת השווים מספקת 'שעות כושר' ללמוד לתפקד בנסיבות חברתיות תובעניות - הכנה לעתיד.\n\nמרכיבים שליליים: הסיכוי שמתבגרים יעשו מעשים מסוכנים עולה בהשפעת קבוצת השווים. הוכחה: במשחק וידיאו 'פחדן' (סיכוני נהיגה), מתבגרים ששיחקו בנוכחות קבוצה נטלו סיכונים רבים משמעותית יותר מלבד - ואצל המתבגרים (בהשוואה למבוגרים) הייתה ההשפעה הגדולה ביותר. מתבגרים רגישים יותר להשפעת חבריהם היו בסיכון גבוה יותר לבעיות סמים/אלכוהול כעבור שנה.","mnemo":"👫⚖️ חברים=אימון-חברתי, אך גם דחיפה לסיכון"},{"id":"prof9_57","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד מגדיר אריקסון אינטימיות וכיצד היא תורמת לרווחה?","a":"יכולת להתחייב התחייבות מלאה (מינית, רגשית, מוסרית) לאדם אחר - בחברות או ברומנטיקה, דורשת פתיחות/אומץ/התפשרות. אינטימיות חברתית היא תנאי מוקדם לרווחה פסיכולוגית - קשרי משפחה וחברים מאזנים זה את זה ומספקים רווחה קבועה לאורך החיים.","explain":"אריקסון הגדיר שתי מטלות בתקופת הבגרות: אינטימיות ופוריות. אריקסון תיאר אינטימיות כיכולת להתחייב התחייבות מלאה לאדם אחר - מינית, רגשית ומוסרית. יכולה להתרחש בקשרי חברות וברומנטיקה כאחד, מצריכה פתיחות, אומץ, חוסן מוסרי, ולרוב מידה של התפשרות.\n\nתרומתה לרווחה: המחקר אישש שוב ושוב שאינטימיות חברתית היא תנאי מוקדם לתחושת רווחה פסיכולוגית לאורך שלבי הבגרות. קשרים עם משפחה וחברים מאזנים אלה את אלה במהלך שנים ארוכות, ומספקים רמה קבועה למדי של תחושת רווחה, גם כשמקורות התמיכה משתנים עם הגיל.","mnemo":"🤝 להתחייב=לוותר על עצמאות למען קרבה"},{"id":"prof9_58","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד בא הצורך באינטימיות לידי ביטוי בבגרות המאוחרת?","a":"פחות קשרים חברתיים בכמות, אך טיב הקשרים משתנה - הצורך באינטימיות ממשיך להיענות. תיאוריית קשרי גומלין סלקטיביים (קרסטנסן): זקנים בררניים יותר, בוחרים שותפים (בעיקר משפחה/חברים ותיקים) המספקים צרכים רגשיים. איכות חשובה מכמות.","explain":"אחד הסטריאוטיפים על הבגרות המאוחרת הוא בדידות חברתית גוברת. אמנם לזקנים עשויים להיות פחות קשרים, אך טיב הקשרים משתנה, וכך הצורך באינטימיות ממשיך להיענות.\n\nתיאוריית קשרי גומלין חברתיים סלקטיביים (לורה קרסטנסן): ככל שאנשים מזדקנים, הם נעשים בררנים יותר ובוחרים שותפים חברתיים המספקים את צורכיהם הרגשיים - אמצעי לווסת חוויות רגשיות ולשמר אנרגיה פיזית. זקנים ממשיכים בקשרים מלאי חיות בעיקר עם בני משפחה וחברים ותיקים.\n\nנקודת מפתח: כמות קשרי הגומלין אינה החשוב ביותר, אלא איכותם. אדם המתקרב לבגרות המאוחרת מגן על צורכו באינטימיות דרך בחירה קפדנית יותר של מי שיספק תמיכה רגשית ישירה.","mnemo":"👴 פחות חברים, אבל כל אחד יקר יותר"},{"id":"prof9_59","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי מהות הפוריות וכיצד היא משפיעה על הרווחה הפסיכולוגית?","a":"מחויבות החורגת מהעצמי (משפחה, עבודה, חברה, דורות הבאים), שלב מכריע בשנות ה-30-40. מהותה: להיות מכוון לאחרים, אכפתי, רחום. מחקר ויאנט: גברים \"מצליחים\" ביצעו משימות יצרניות ותרמו לעולם - התכוונות לטובת הכלל יוצרת רווחה פסיכולוגית המפצה על געגוע לנעורים.","explain":"פוריות (generativity) היא מחויבות החורגת מעבר לאדם עצמו - למשפחה, לעבודה, לחברה או לדורות הבאים. לרוב שלב מכריע בשנות ה-30 וה-40.\n\nמחקר ויאנט: בקרב 95 גברים שנחקרו 30 שנה, הגברים בעלי התוצאות הטובות ביותר ביצעו משימות יצרניות, נטלו אחריות על זולתם ותרמו לעולם - בשלותם קשורה גם ליכולתם לסייע לילדיהם להסתגל.\n\nמהות הפוריות: כשנשאלו אנשים בגיל העמידה וזקנים מהי 'הסתגלות טובה', התשובה השכיחה ביותר בשתי הקבוצות הייתה: להיות 'מכוון לאחרים', אכפתי, רחום, ובעל יחסים טובים עם הסביבה.\n\nהשפעתה: ההתכוונות לטובת הכלל מאפשרת למבוגרים ליצור תחושת רווחה פסיכולוגית המפצה על כל געגוע לגיל הנעורים.","mnemo":"🌱 לדאוג-לעולם=מתכון לזקנה מאושרת"},{"id":"quiz9_1","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"כלנית נמצאת במחקר אינטליגנציה 20 שנה, מוזמנת מדי כמה שנים למעבדה. מערך המחקר: (מחקר רוחב / כרונולוגי / מהלך חיים / אורך)","a":"אורך (אותם אנשים נבדקים שוב ושוב לאורך שנים)","explain":"מחקר אורך (longitudinal study) הוא מערך מחקר שבו חוקרים צופים באותם אנשים ובוחנים אותם שוב ושוב, לעתים קרובות לאורך שנים רבות. דוגמה: מחקר על תכנית High/Scope Perry בגני ילדים - החוקרים אספו נתונים על ילדים בני 3-4, ובדקו אותם שוב מדי שנה עד גיל 11, ולאחר מכן בגילים 14, 15, 19, 27 ו-40.","mnemo":"🔬 20 שנה אותם אנשים = אורך"},{"id":"quiz9_4","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"ילד אגוצנטרי (פיאז'ה) ינהג כך: (מסביר לסבתא למה הדובון אוהב מקלחת / מאמין שגשם מגיע מחורים בענן / לא מבין למה אביו עייף מכדי לשחק איתו / מבין שלכל אחד חלום אחר)","a":"לא יבין את הסיבה לכך שאביו עייף מידי בכדי לשחק איתו (אגוצנטריות=קושי לתפוס נקודת מבט של אחר)","explain":"אגוצנטריות (שלב קדם-אופרציונלי, פיאז'ה) היא חוסר יכולת הילד לראות דברים מנקודת מבטו של הזולת. אי-הבנת עייפותו של האב (מצב פנימי נפרד, השונה מהרצון של הילד לשחק) היא הדוגמה המדויקת לכך - שלוש האפשרויות האחרות אינן קשורות לאגוצנטריות: הסבר לסבתא הוא דווקא ביטוי ליכולת תקשורתית; אמונה על מקור הגשם היא תפיסה מאגית-סיבתית, לא אגוצנטרית; והבנת חלומות שונים היא דווקא התגברות על אגוצנטריות.","mnemo":"👶 אגוצנטרי לא מבין \"אבא עייף\" - רואה רק מנקודת מבטו"},{"id":"quiz9_6","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"המינוח \"היקשרות\" מיוחס ל: (צורך בחפץ אהוב / אחיזה רפלקסיבית / יחסים חברתיים-רגשיים מתמשכים עם המטפל העיקרי / נטייה ללכת אחר עצם נע ראשון)","a":"יחסים חברתיים-רגשיים מתמשכים וחזקים, המתפתחים בין הילד למטפל העיקרי (הגדרת ההיקשרות - לא רק צורך פיזי)","explain":"המונח <b>'היקשרות' (attachment)</b> מיוחס ל<b>יחסים חברתיים-רגשיים מתמשכים וחזקים</b>, המתפתחים בין-הילד למטפל-העיקרי-שלו (לרוב-ההורה). ⚠️ ההגדרה-המדויקת חשובה כדי-להבדיל מהמסיחים: זו <b>לא</b> סתם 'צורך-בחפץ-אהוב' (זה-יהיה-קרוב-יותר-ל'אובייקט-מעבר', מושג-אחר), <b>לא</b> 'אחיזה-רפלקסיבית' (רפלקס-מולד-פשוט, לא-קשר-רגשי-מורכב), ו<b>לא</b> 'נטייה-ללכת-אחר-עצם-נע-ראשון' (זה-מתאר <b>הטבעה - imprinting</b>, תופעה-שונה-לגמרי, בעיקר-אצל-ציפורים) - היקשרות היא-ספציפית קשר-רגשי-עמוק-ומתמשך, לא-רפלקס-או-דחף-חד-פעמי.","mnemo":"🔗 היקשרות=קשר חברתי-רגשי, לא רק צורך"},{"id":"quiz9_7","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"מחקר הארלו על קופי רזוס הדגים ש: (חרדת נטישה בגיל 6 חודשים / היקשרות למספק מזון / היקשרות בטוחה רק עם הורים ביולוגיים / הפעוט מחפש מגע מנחם בפחד/מצב לא מוכר)","a":"הפעוט מחפש מגע מנחם כאשר הוא חש פחד או נמצא בסיטואציה לא מוכרת (הארלו - נוחות במגע חשובה מעבר לאספקת מזון)","explain":"תיאוריית הארון (cupboard theory) של פרויד טענה שתינוקות נקשרים להוריהם כי הם מספקים מזון.\n\nמחקר הארלו: הפריד קופי מקוק מאמותיהם ברגע הלידה, ונתן להם נגישות לשתי 'אימהות' מלאכותיות - אחת מחוט תיל, השנייה מבד מגבת. הקופיפים התרפקו על האם מבד המגבת ושהו זמן מועט על האם מחוט התיל - גם כאשר רק התיל נתן חלב! הם השתמשו באם מבד המגבת כמקור למגע מנחם כשהיו מפוחדים, וכבסיס יציאה לחקירת גירויים חדשים.\n\nהאם תואם/סותר: סותר בבירור - אם תיאוריית הארון הייתה נכונה, הקופיפים היו אמורים להעדיף את מספקת המזון, ללא קשר לחומר. הממצאים הראו את ההפך - העדפה מוחלטת למגע מנחם על פני סיפוק מזון.","mnemo":"🐒 הארלו: פחד→רץ לחיבוק, לא לאוכל"},{"id":"quiz9_8","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"ילד מתנהג זהה לזר ולאימו במצב הזר (פרידה ואיחוד). סגנון ההיקשרות: (לא בטוחה-נמנעת / ללא דפוסי היקשרות / בטוחה / לא בטוחה-אמביוולנטית)","a":"היקשרות לא בטוחה-נמנעת (חוסר הבדל בתגובה לזר/אם = הימנעות מקרבה רגשית)","explain":"מחקרי אורך הראו שקטגוריזציה מבחן המצב הזר - ובייחוד החלוקה הכללית לילדים בעלי היקשרות בטוחה מול לא בטוחה - חוזה ביעילות התנהגויות מאוחרות: חברתיות (ילדים עם היקשרות בטוחה בגיל 15 חודשים היו אהודים יותר בבית הספר בגיל 8-9), פחות חרדה חברתית, והמשכיות דומה נצפתה גם בגיל 10 ובגיל ההתבגרות. חוקרים משתמשים במדדי היקשרות אף כדי לנבא איכות קשרי אהבה בין מבוגרים.\n\nמדוע דווקא התנהגויות אלה: ⚠️ מודל העבודה הפנימי (סכמה שנוצרה מיחסי ההיקשרות המוקדמים) מעצב ציפיות לגבי קשרים חברתיים עתידיים. ילד עם היקשרות בטוחה בונה ציפייה שהעולם החברתי אמין ותומך, ולכן ניגש לאינטראקציות חדשות בביטחון ופתיחות - מסביר את החברתיות הרבה יותר וירידת החרדה החברתית.","mnemo":"🚪 זר=אמא, אותה תגובה=נמנעת"},{"id":"quiz9_10","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"ראובן מתקשה להתחייב, כמעט לא מתפשר, חסר אחריות, אין לו חברים קרובים. לפי אריקסון, לא פתר כהלכה את הקונפליקט: (אינטימיות ובדידות / פוריות וקיפאון / כשירות נחיתות / אני אחרים)","a":"אינטימיות ובדידות (קושי להתחייב=כישלון בפתרון משבר גיל הבגרות המוקדמת)","explain":"אריקסון הגדיר שתי מטלות בתקופת הבגרות: אינטימיות ופוריות. אריקסון תיאר אינטימיות כיכולת להתחייב התחייבות מלאה לאדם אחר - מינית, רגשית ומוסרית. יכולה להתרחש בקשרי חברות וברומנטיקה כאחד, מצריכה פתיחות, אומץ, חוסן מוסרי, ולרוב מידה של התפשרות.\n\nתרומתה לרווחה: המחקר אישש שוב ושוב שאינטימיות חברתית היא תנאי מוקדם לתחושת רווחה פסיכולוגית לאורך שלבי הבגרות. קשרים עם משפחה וחברים מאזנים אלה את אלה במהלך שנים ארוכות, ומספקים רמה קבועה למדי של תחושת רווחה, גם כשמקורות התמיכה משתנים עם הגיל.","mnemo":"💍 ראובן לא מתחייב=אינטימיות-מול-בדידות נכשל"},{"id":"prof10_01","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי מוטיבציה?","a":"מונח כללי לתהליכים המעורבים בהתחלת פעילויות פיזיות/פסיכולוגיות, בהכוונתן ובהתמדה בהן. מקור המילה: \"לנוע\" (movere) - מסביר תנועה לקראת/הרחקה מגירויים, הן ברמת המין והן ברמה האישית.","explain":"מוטיבציה היא מונח כללי לכל התהליכים המעורבים בהתחלת פעילויות פיזיות ופסיכולוגיות, בהכוונתן ובהתמדה בהן. מקור המילה בלטינית: movere, שפירושו \"לנוע\" - כל האורגניזמים נעים לקראת גירויים ופעילויות מסוימים ומתרחקים מאחרים, בהתאם לתכתיבי המאוויים והסלידות שלהם. תיאוריות מוטיבציה מסבירות הן את דפוסי ה\"תנועה\" הכלליים של כל המינים, והן את ההעדפות האישיות והתפקוד האישי של פרטים בתוך אותו המין.","mnemo":"🚶 movere=לנוע - הכל מתחיל מתנועה"},{"id":"prof10_02","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"סכמו את חמשת תפקידי המוטיבציה.","a":"(1) קישור ביולוגיה-התנהגות (רעב→אכילה). (2) הסבר שונות התנהגותית (מדוע ילד אחד מצליח יותר מאחר). (3) הסקת מצבים פרטיים מהתנהגות פומבית (פנימי/חיצוני). (4) ייחוס אחריות לפעולות (תלוי כוונה/כפייה חיצונית/סמים). (5) הסבר התמדה על אף מצוקה/קושי.","explain":"פסיכולוגים משתמשים במושג מוטיבציה לחמש מטרות בסיסיות:\n\n1. לקשר בין ביולוגיה להתנהגות - מצבים פנימיים של חסך (רעב, צמא, קור) מעוררים תגובות גופניות המניעות אותנו לפעול כדי להחזיר לגוף שיווי משקל.\n\n2. להסביר שונות התנהגותית - מדוע מצליחים במטלה ביום אחד ונכשלים באותה מטלה ביום אחר? פסיכולוגים משתמשים בהסברי מוטיבציה כשאי-אפשר לתלות את השונות בהבדלי יכולת, מיומנות, אימון או מזל.\n\n3. להקיש על מצבים פרטיים מתוך התנהגויות פומביות - בני אדם נוטים לעבור מצפייה בהתנהגות למסקנה על סיבה פנימית שגרמה לה, כולל שאלה אם ההתנהגות נובעת ממוטיבציה פנימית או חיצונית.\n\n4. לייחס אחריות לפעולות - אחריות אישית מניחה מראש קיום מוטיבציה פנימית ויכולת שליטה על פעולות. אחריות מופחתת כאשר: (1) התוצאות לא היו מכוונות. (2) כוחות חיצוניים חזקים עוררו את ההתנהגות. (3) הפעולות הושפעו מסמים/אלכוהול/רגשות עזים.\n\n5. להסביר התמדה על אף מצוקה - מדוע אורגניזם מבצע התנהגות כאשר קל יותר שלא לבצעה? מוטיבציה מסבירה למשל הגעה בזמן לעבודה למרות עייפות, או המשך משחק גם כשברור שאין סיכוי לנצח.","mnemo":"5️⃣ קושר-מסביר-מקיש-מייחס-מתמיד"},{"id":"prof10_reflection1","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"זהו את תפקיד המוטיבציה בכל מקרה: (א) דני שותה מים מצמא. (ב) נועה נמנעת מעוגה. (ג) אלונה מסבירה איחור בעומס. (ד) ניצן מתנגש תוך שיחה בטלפון. (ה) תאומות זהות בהישגים שונים.","a":"(א) קישור ביולוגיה-התנהגות. (ב) ייחוס אחריות (שליטה עצמית פנימית). (ג) ייחוס אחריות (הפחתה - ייחוס חיצוני/נסיבתי). (ד) ייחוס אחריות (מלאה - בחירה מודעת, ללא כפייה/סמים). (ה) הסבר שונות התנהגותית (יכולת דומה, הישגים שונים).","explain":"א. דני מתעורר מיובש בגרון, שותה מים - תפקיד 1: קישור ביולוגיה להתנהגות. מצב פנימי של חסך (צמא) מעורר תגובה גופנית המכוונת להחזרת שיווי המשקל.\n\nב. נועה נמנעת מעוגות קצפת כדי לרדת במשקל - תפקיד 4: ייחוס אחריות לפעולות. נועה מפעילה מוטיבציה פנימית ושליטה עצמית מודעת.\n\nג. אלונה לא הגישה מטלה, טוענת שהייתה עמוסה - תפקיד 4 (בכיוון הפוך): מנסה להפחית מאחריותה האישית באמצעות ייחוס לגורם חיצוני/נסיבתי.\n\nד. ניצן שוחח בטלפון בזמן נהיגה והתנגש - תפקיד 4: ייחוס אחריות. בחר במודע לשוחח, ללא כוונה שלילית, כפייה חיצונית או סמים - נושא באחריות מלאה.\n\nה. יעל ומיכל, תאומות זהות, השקעה והישגים שונים - תפקיד 2: הסבר שונות התנהגותית. יכולת דומה (תאומות זהות), אך פער בהישגים - מוטיבציה היא ההסבר המתאים.","mnemo":"🔍 5 תפקידים, 5 סיפורים - זהו איזה כובע"},{"id":"prof10_03","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד, לפי קלארק האל, דחפים מניעים התנהגות?","a":"דחפים=מצבים פנימיים המתעוררים כשמחסור פיזיולוגי מפר את האיזון (הומאוסטזיס) ויוצר מתח. הדחף מניע התנהגות (חיפוש מזון) שמפחיתה את המתח - תגובות המובילות להפחתה מקבלות חיזוק. כשהדחף מסופק, האורגניזם מפסיק לפעול.","explain":"לפי קלארק האל, דחפים (drives) הם מצבים פנימיים המתעוררים בתגובה על צרכיו הפיזיולוגיים של בעל חיים. אורגניזמים שואפים לשמור על מצב של איזון (הומאוסטזיס) במצבם הביולוגי. דחפים מתעוררים כאשר מחסור כלשהו מפר את האיזון ונוצר מתח. דחפים אלה מפעילים את האורגניזם לכיוון הפחתת המתח.\n\nמנגנון פעולה: כאשר מונעים מבעל חיים מזון במשך שעות ארוכות, מתעורר בו מצב של רעב, המניע התנהגות של חיפוש מזון ואכילה. התגובות שהובילו את בעל החיים אל האוכל מקבלות חיזוק, מכיוון שהן מתקשרות עם הפחתת המתח. כאשר הדחפים מסופקים וההומאוסטזיס מושב, האורגניזם מפסיק לפעול.","mnemo":"🌡️ מחסור→מתח→פעולה→איזון→עצור (תרמוסטט)"},{"id":"prof10_04","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד תמריצים מניעים התנהגות?","a":"תמריצים=גירויים חיצוניים/תגמולים שאינם מתקשרים ישירות לצרכים ביולוגיים (סקרנות, הנאה). הוכח בניסויים: חולדות רעבות/צמאות בחרו לחקור סביבה חדשה קודם; קופים עסקו בעצמים חדשים ללא גמול פיזיולוגי. מוכיח שהתנהגות מונעת משילוב דחפים פנימיים ותמריצים חיצוניים.","explain":"האם הפחתת מתח יכולה להסביר כל התנהגות מונעת? כנראה שלא. ניסויים חשפו את מגבלות תיאוריית הדחפים: חולדות שנמנע מהן מזון ושתייה, כשהונחו בסביבה חדשה עם שפע הזדמנויות לאכול/לשתות, העדיפו לחקור את הסביבה תחילה. בסדרת מחקרים אחרת, קופים צעירים הקדישו זמן ואנרגיה רבים לעיסוק בעצמים חדשים, כפי הנראה רק מתוך ההנאה שבהשתובבות, מבלי לקבל גמול רלוונטי לצרכים פיזיולוגיים.\n\nהמסקנה: לא רק דחפים פנימיים מניעים התנהגות - התנהגות מונעת גם על ידי תמריצים (incentives): גירויים חיצוניים או תגמולים, שאינם מתקשרים ישירות לצרכים ביולוגיים. הבסיס להתנהגויות הוא שילוב של מקורות פנימיים (דחפים) וחיצוניים (תמריצים) של מוטיבציה.","mnemo":"🐭 חולדה רעבה בוחרת לחקור לפני שאוכלת"},{"id":"prof10_05","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהם אינסטינקטים וכיצד הם מניעים התנהגות?","a":"נטיות קיימות מראש, חלק מהמטען הגנטי, חיוניות להישרדות המין (דוגמה: נדידת סלמון). לפי ג'יימס, אינסטינקטים ייעודיים (purposive) - משרתים מטרות הסתגלות לסביבה, כולל אינסטינקטים חברתיים אצל בני אדם.","explain":"אינסטינקטים הם נטיות קיימות מראש, החיוניות להישרדותו של המין - מספקים אוסף של התנהגויות שהוא חלק מהמטען הגנטי של כל בעל חיים. דוגמה: דגי אלתית (סלמון) שוחים אלפי קילומטרים בדיוק לערוץ הנחל שבו בקעו. דוגמאות נוספות: דבורים המעבירות מידע על מיקום מזון, נמלי הגדוד, ציפורים בונות קנים, עכבישים טווים קורים.\n\nכיצד מניעים התנהגות: לפי ויליאם ג'יימס (1890), אינסטינקטים ייעודיים (purposive) - נועדו לשרת מטרות או תפקידים בהסתגלות האורגניזם לסביבתו. ג'יימס טען שבני אדם נשענים, יותר מבעלי חיים אחרים, על התנהגויות אינסטינקטיביות - כולל אינסטינקטים חברתיים כמו אהדה, צניעות, חברתיות ואהבה.","mnemo":"🐟 סלמון שוחה הביתה - גנטיקה טהורה"},{"id":"prof10_06","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד, לפי פרויד, אנרגיה נפשית מניעה התנהגות?","a":"שני אינסטינקטים (חיים/מוות) מכוונים אנרגיה נפשית לסיפוק צרכים. אי-פריקת האנרגיה יוצרת מתח, הדוחף לפעולות מפחיתות מתח. פועלים בעיקר מתחת לסף המודעות, אך משפיעים עמוקות על מחשבות, רגשות והחלטות.","explain":"לפי זיגמונד פרויד (1915), בני אדם חווים מצבי דחף הנובעים משני סוגי אינסטינקטים: אינסטינקטים של חיים (כולל מיניות) ואינסטינקטים של מוות (כולל תוקפנות). פרויד האמין שדחפים אינסטינקטיביים מכוונים אנרגיה נפשית לסיפוק צרכים גופניים. כאשר אי-אפשר לפרוק אנרגיה זו, נוצר מתח, הדוחף אנשים לפעולות שיפחיתו אותו. פרויד האמין שאינסטינקט החיים ואינסטינקט המוות פועלים לרוב מתחת לסף המודעות, אך עם זאת יש להם השפעה עמוקה על המחשבות המודעות, על הרגשות ועל הפעולות.","mnemo":"⚡ שני אינסטינקטים דוחפים אנרגיה סמויה"},{"id":"prof10_07","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד קוראת האנתרופולוגיה תיגר על הנחות אינסטינקטים מולדים?","a":"בנדיקט ומיד מצאו שונות התנהגותית עצומה בין תרבויות שונות - סותר תיאוריות התומכות באוניברסליות אינסטינקטים מולדים (אם היו אוניברסליים, לא הייתה שונות כה גדולה בין תרבויות).","explain":"עד שנות ה-20 של המאה הקודמת, פסיכולוגים חיברו רשימות של למעלה מ-10,000 אינסטינקטים אנושיים. באותה עת קראו רבים תיגר על הרעיון שאינסטינקטים יכולים להסביר את כלל ההתנהגות האנושית.\n\nהאתגר האנתרופולוגי: אנתרופולוגים שהשוו בין תרבויות שונות - רות בנדיקט ומרגרט מיד - מצאו שונות התנהגותית עצומה בין תרבויות. תצפיותיהן סתרו תיאוריות שהתמקדו באוניברסליות של אינסטינקטים מולדים.","mnemo":"🌏 תרבויות שונות מדי - אינסטינקט לא מסביר הכל"},{"id":"prof10_08","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע, לפי הגישה הביהביוריסטית, \"מוטיבציה\" חסרת משמעות?","a":"התנהגות מוסברת דיה על ידי היסטוריית חיזוקים (בעל חיים אחד קיבל חיזוק, השני לא) - אין צורך במבנה פנימי נוסף שנקרא \"מוטיבציה\" כדי להסביר את ההבדל בין בעלי חיים.","explain":"יותר מכול, ערערו על הרעיונות המוקדמים על אינסטינקטים הוכחות ביהביוריסטיות אמפיריות, שלפיהן התנהגויות ורגשות חשובים הם נלמדים, ולאו דווקא מולדים.\n\nההיגיון: אם רוצים להסביר מדוע בעל חיים מסוים, ולא אחר, מבצע התנהגות כלשהי, ייתכן שאין צורך לדעת דבר מלבד העובדה שהתנהגותו של בעל חיים אחד קיבלה חיזוקים, ואילו התנהגותו של השני לא קיבלה חיזוקים. בנסיבות אלה, אין צורך בהסבר נפרד על מוטיבציה - טעות לומר שבעל חיים אחד \"מוּנע\" לעומת השני שאינו \"מוּנע\"; ההבדל טמון בהיסטוריית החיזוקים השונה שלהם.","mnemo":"🎓 חיזוק לבד מסביר הכל - \"מוטיבציה\" מיותרת"},{"id":"prof10_09","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע שילוב תורשה וסביבה מאפשר הבנה טובה יותר של התנהגות אנושית?","a":"כל אורגניזם מציג צירוף של התנהגויות נלמדות ואינסטינקטיביות. הסבר מלא דורש ידיעת (1) תולדות המין (אינסטינקטים/תורשה) וגם (2) ההיסטוריה האישית (חיזוקים/סביבה) - שילוב שני המקורות, לא אחד בלבד.","explain":"סוג ההתנהגויות שבעלי חיים נכונים ללמוד יותר מכול נקבע, בחלקו, על ידי אינסטינקטים ייחודיים למין. כל בעל חיים מציג צירוף של התנהגויות נלמדות והתנהגויות אינסטינקטיביות.\n\nכדי להסביר או לנבא התנהגות של בעל חיים, יש צורך לדעת שני דברים: (1) פרטים על תולדות המין - אילו התנהגויות הסתגלותיות הן חלק מהמטען הגנטי. (2) פרטים על ההיסטוריה האישית של בעל החיים - באיזו מערכת ייחודית של קישורים סביבתיים (חיזוקים) התנסה. במקרים אלה, המוטיבציה טמונה בהשפעות ההיסטוריה (הגנטית והאישית-סביבתית גם יחד) על ההתנהגות בהווה.","mnemo":"🧬+📖 מין (גנים) + היסטוריה-אישית (למידה) יחד"},{"id":"prof10_10","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הציעו 3 דרכים להעלות מוטיבציה לפי תיאוריית הציפיות (ורום) - כל אחת מתייחסת לקוגניציה אחרת.","a":"מוטיבציה=ציפייה×תכליתיות×ערך. (1) העלאת ציפייה (מאמץ→ביצוע): הדרכה/משוב שמראים שמאמץ באמת משפר ביצוע. (2) העלאת תכליתיות (ביצוע→תוצאה): קריטריוני הערכה שקופים וברורים. (3) העלאת ערך: התאמת התגמול למה שבאמת חשוב לאדם הספציפי.","explain":"על פי תיאוריית הציפיות (expectancy theory) של ורום (Vroom, 1964), מוטיבציה של בני אדם בעבודה תלויה בשילוב בין שלוש קוגניציות: ציפייה, תכליתיות וערך. מוטיבציה = ציפייה × תכליתיות × ערך - זוהי מכפלה, כך שאם קוגניציה כלשהי מייצגת אפס, אין מוטיבציה כלל.\n\nציפייה (Expectancy) - תפיסת העובד שמאמציו יניבו רמת ביצוע מסוימת (קשר מאמץ→ביצוע).\nתכליתיות (Instrumentality) - המידה שבה העובד מאמין שלביצוע שלו יהיו תוצאות (קשר ביצוע→תוצאה).\nערך (Valence) - המידה שבה העובד תופס את התוצאות כבעלות ערך.\n\n⚠️ שלוש דרכים מומחשות להעלאת מוטיבציה: (1) העלאת ציפייה - הדרכה/משוב בונה/תרגול מובנה, כדי שהעובד ילמד שהמאמץ שלו אכן משפר ביצוע. (2) העלאת תכליתיות - קריטריוני הערכה/קידום שקופים ואובייקטיביים, לא תלויים בפוליטיקה פנימית. (3) העלאת ערך - התאמת התגמול המוצע למה שבאמת חשוב לעובד הספציפי (שכר, גמישות, הכרה).","mnemo":"✖️ ציפייה×תכליתיות×ערך - 3 ברגים לכוונן"},{"id":"prof10_11","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי תיאוריית הצרכים של מסלו? תארו את חמשת הצרכים ועקרון המדרג.","a":"מדרג צרכים (ביולוגי→ביטחון→היקשרות→הערכה→מימוש עצמי), כל שלב חייב להיות מסופק לפני המעבר לבא. עקרון: צורך לא מסופק שולט במוטיבציה; משסופק, תשומת הלב עוברת לצורך הבא.","explain":"אברהם מסלו, המשתייך לגישה ההומניסטית, ניסח תיאוריה שלפיה המניעים הבסיסיים יוצרים מדרג של צרכים. הצרכים מאורגנים ברצף, מהפרימיטיביים ביותר עד המתקדמים ביותר, ובכל שלב הם חייבים לבוא על סיפוקם קודם שיהיה אפשר להמשיך לשלב הבא.\n\nחמשת הצרכים (מהתחתון לעליון):\n1. צרכים ביולוגיים - כמו רעב וצמא.\n2. צורכי ביטחון - כשהצרכים הביולוגיים סופקו.\n3. צורכי היקשרות - הצורך להשתייך, להתחבר, לאהוב ולהיות נאהב.\n4. צורכי הערכה - לאהוב את עצמנו, להיתפס כבעלי יכולת, לזכות בהערכת אחרים.\n5. מימוש עצמי - מיצוי הפוטנציאל במלואו; אדם המממש עצמו מודע לעצמו, מקבל את עצמו, יצירתי, ספונטני ופתוח לחידושים.\n\nעקרון המדרג: צרכים ברמה נמוכה שולטים במוטיבציה כל זמן שאינם מסופקים. מרגע שסופקו באופן משביע רצון, עוברת תשומת הלב לצרכים הגבוהים מהם.","mnemo":"🪜 ביולוגי→ביטחון→שייכות→הערכה→מימוש"},{"id":"prof10_12","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"אילו צרכים פועלים לפי עקרון ההומאוסטזיס ואילו לא?","a":"פועלים לפי הומאוסטזיס (צורכי חסר): ביולוגי, ביטחון, היקשרות - מפסיקים להטריד ברגע שסופקו. לא פועלים לפי הומאוסטזיס (צורכי גדילה): הערכה, מימוש עצמי - ככל שמסופקים יותר, כך גוברת המוטיבציה להמשיך למַ מש אותם.","explain":"שלושת הצרכים התחתונים (ביולוגי, ביטחון והיקשרות) הם צורכי חסר, ופועלים לפי עקרון ההומאוסטזיס: אם אינם מסופקים מובילים לתחושה גופנית/רגשית לא נוחה, אך מרגע שסופקו מפסיקים להיות המוקד שהמוטיבציה מכוונת אליו.\n\nלעומת זאת, שני הצרכים העליונים (הערכה ומימוש עצמי) הם צורכי גדילה, ואינם פועלים לפי הומאוסטזיס: גם כשהם מסופקים, אינם חדלים מלהיות כוח מניע - ההפך הוא הנכון, ככל שהם מסופקים יותר, כך הם מגבירים את השקעת המוטיבציה בהמשך מימושם.","mnemo":"🔄 חסר=נעצר כשמסופק | גדילה=רק גדל"},{"id":"prof10_13","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הציגו דוגמה הסותרת את מדרג מסלו.","a":"דילוג על ארוחה (צורך ביולוגי) כדי לעזור לחבר (היקשרות) - ויתור על צורך נמוך למען צורך גבוה יותר. או: יציאה למסע מסוכן במדבר (ויתור על ביטחון) כדי לחזק הערכה עצמית (שלב גבוה) - סותר את הרצף ההיררכי הנוקשה.","explain":"המדרג הקפדני של מסלו אינו מוכיח את עצמו תמיד. דוגמאות: ייתכן שדילגתם על ארוחה (צורך ביולוגי, תחתית המדרג) כדי לעזור לחבר (יחסים חברתיים/היקשרות, שלב גבוה יותר) - ויתור על צורך נמוך למען צורך גבוה. דוגמה נוספת: ייתכן שיצאתם למסע רגלי מסוכן במדבר (מוותרים על צורך ביטחון) כדי לחזק הערכה עצמית (שלב גבוה) - בחירה מודעת לסכן את עצמכם למען מטרה שלכאורה נגישה רק לאחר שביטחון כבר סופק.","mnemo":"🍽️ מוותר על ארוחה כדי לעזור לחבר - שובר את הסולם"},{"id":"prof10_reflection2","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מלאו את טבלה 1 - מקורות המוטיבציה לפי כל גישה פסיכולוגית.","a":"פסיכודינמית=אינסטינקטים/דחפים מתנגשים עם החברה. ביהביוריסטית=היסטוריית חיזוקים. הומניסטית=נטייה למימוש עצמי (מדרג מסלו). קוגניטיבית=ציפיות/פרשנות סובייקטיבית. ביולוגית=דחפים לשמירת הומאוסטזיס (גנים/מוח/הורמונים). אבולוציונית=הסתגלות לשרידה/העברת גנים. חברתית-תרבותית=נורמות/ציפיות חברתיות.","explain":"פסיכודינמית - אינסטינקטים מולדים ודחפים ביולוגיים (חיים/מוות) המתנגשים עם דרישות החברה, יוצרים אנרגיה נפשית/מתח.\nביהביוריסטית - היסטוריית חיזוקים; התנהגות מונעת על ידי גירויי סביבה וחיזוקים שהתקבלו בעבר.\nהומניסטית - נטייה מולדת למימוש עצמי ולצמיחה (מדרג צרכי מסלו).\nקוגניטיבית - ציפיות, פרשנות סובייקטיבית של המציאות, אמונות לגבי מאמץ-ביצוע-תוצאה (ורום, רוטר).\nביולוגית - דחפים פנימיים (האל) לשמירה על הומאוסטזיס, מבוססים על גנים, מבני מוח ופעילות הורמונלית/עצבית.\nאבולוציונית - תהליכי הסתגלות לסביבה מהברירה הטבעית; שרידה והתאמה לסביבה.\nחברתית-תרבותית - נורמות, ציפיות ותמריצים הנקבעים על ידי הסביבה החברתית-תרבותית.","mnemo":"🗺️ 7 גישות, 7 מקורות שונים למוטיבציה"},{"id":"prof10_vocab","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו: שובע ייחודי לחוש, מודל המרכז הכפול, אכילה מרוסנת, קצב חילוף חומרים במנוחה.","a":"שובע ייחודי לחוש=פחיתת עניין בטעם ספציפי (לא במזון כללי) לאורך ארוחה. מודל המרכז הכפול=תיאוריה (לא מאוששת) שהיפותלמוס צדי=\"רעב\", גחוני-מדיאלי=\"שובע\". אכילה מרוסנת=הגבלה מתמדת של כמות אוכל, \"תמיד בדיאטה\" - עלולה לגרום זלילה בלחץ. קצב חילוף חומרים במנוחה=קצב שריפת קלוריות בסיסי, תורשתי במידה רבה.","explain":"שובע ייחודי לחוש (sensory-specific satiety) - התופעה שבה ההתלהבות מטעמים, אפילו של מאכלים אהובים, הולכת ופוחתת במהלך הארוחה. השובע חל על טעמים ייחודיים, לא על המזון עצמו - הוכח בניסוי: משתתפים הגיעו לשובע מאננס/מלפפונים, אך גילו עניין מחודש כשהתווסף שינוי קל בטעם (קצפת בטעם וניל, מלח ופלפל).\n\nמודל המרכז הכפול (dual-center model) - תיאוריה מוקדמת שראתה בהיפותלמוס הצדי \"מרכז הרעב\" ובהיפותלמוס הגחוני-מדיאלי \"מרכז השובע\". הנתונים המאוחרים לא איששו את התיאוריה - עכברים עם פגיעה בהיפותלמוס הגחוני-מדיאלי הפריזו באכילה רק כשהמזון היה טעים, ונמנעו לגמרי ממזון לא טעים.\n\nאכילה מרוסנת (restrained eating) - לפי פוליווי והרמן, אכלנים מרוסנים מגבילים כל הזמן את כמות המזון שהם מרשים לעצמם, תמיד \"בדיאטה\", עסוקים כל הזמן באוכל - ללא קשר למשקלם בפועל. כשהופכים \"נטולי עכבות\" (בלחץ), נוטים להיכנע ולזלול מזון עתיר קלוריות.\n\nקצב חילוף החומרים במנוחה - הקצב שבו הגוף שורף קלוריות כדי לשמור על תפקודיו הבסיסיים. יש לו מידה רבה של תורשה - אנשים מסוימים נוטים מראש לשרוף יותר קלוריות, ומי ששורפים פחות נמצאים בסיכון גבוה יותר להשמנה.","mnemo":"📚 4 מונחי-אכילה - שובע/מרכז-כפול/מרוסן/חילוף-חומרים"},{"id":"prof10_reflection3","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"סווגו כל מונח/ממצא לגישה המתאימה (אבולוציוני/ביולוגי/קוגניטיבי/חברתי-תרבותי): שובע ייחודי לחוש, מודל מרכז כפול, מנות גדולות בארה\"ב, 3 ארוחות בזמן קבוע, אכילה מרוסנת, קצב חילוף חומרים, שיפוט גודל גוף.","a":"שובע ייחודי לחוש=ביולוגי. מודל מרכז כפול=ביולוגי. מנות גדולות בארה\"ב=חברתי-תרבותי. 3 ארוחות בזמן קבוע=חברתי-תרבותי. אכילה מרוסנת=קוגניטיבי. קצב חילוף חומרים=ביולוגי. שיפוט גודל גוף (ארה\"ב/גאנה)=חברתי-תרבותי.","explain":"שובע ייחודי לחוש - ביולוגי (מנגנון פיזיולוגי).\nמודל המרכז הכפול - ביולוגי (מבנה מוחי - היפותלמוס).\nמנות המזון של האמריקנים גדולות מהצרפתים - חברתי-תרבותי (נורמות תרבותיות שונות לגודל מנה).\nאמריקנים אוכלים 3 ארוחות בזמנים קבועים - חברתי-תרבותי (זמני ארוחות נשענים על נורמות חברתיות, לא אותות מהגוף).\nאכילה מרוסנת - קוגניטיבי (אופן החשיבה על אוכל, כוונות ודימוי עצמי).\nקצב חילוף החומרים במנוחה - ביולוגי (תורשתי, גופני).\nשיפוט גודל גוף (אמריקנים דירגו דמות רזה יותר מגאנים) - חברתי-תרבותי (הבדל בערכי תרבות - בגאנה \"שומן מתקשר לעושר\").","mnemo":"🏷️ מיין כל מונח לקופסה הנכונה"},{"id":"prof10_15","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד יכולים פסיכולוגים מהגישות השונות לסייע בהגברת מוטיבציה לדיאטה בהשמנת יתר?","a":"⚠️ הצעות מומחשות. פסיכודינמית=לחשוף משמעות רגשית לא מודעת של אכילה. ביהביוריסטית=חיזוקים על הצלחה בדיאטה. הומניסטית=לחבר דיאטה למימוש עצמי. קוגניטיבית=שינוי מחשבות \"הכול או כלום\". ביולוגית=טיפול הורמונלי (לפטין). אבולוציונית=ניצול שובע ייחודי לחוש (הפחתת מגוון טעמים). חברתית-תרבותית=הוזלת מזון בריא/שינוי נורמות.","explain":"⚠️ הצעות מומחשות. פסיכודינמית - לחשוף ולעבד משמעות רגשית לא מודעת הקשורה לאכילת יתר. ביהביוריסטית - לבנות מערכת חיזוקים חיוביים וברורים על התנהגויות דיאטה מוצלחות. הומניסטית - לחבר בין הירידה במשקל לצורך במימוש עצמי ובהערכה עצמית. קוגניטיבית - לשנות דפוסי חשיבה \"הכול או כלום\" לציפיות ריאליות יותר. ביולוגית - טיפול תרופתי במנגנונים גופניים (לפטין, קנבינואידים) והתאמת תזונה לקצב חילוף חומרים אישי. אבולוציונית - לנצל את הנטייה לשובע ייחודי לחוש (הפחתת מגוון טעמים בארוחה). חברתית-תרבותית - לשנות הקשר חברתי-כלכלי (הוזלת מזון בריא, שינוי נורמות).","mnemo":"🎯 7 גישות, 7 טיפים לדיאטה"},{"id":"quiz10_1","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"יונית אוכלת מזון בטעם אחד בלבד בכל ארוחה. בגלל ___, כמות המזון שהיא אוכלת לרוב ___: (שובע ייחודי לחוש;גדלה / גירוי היפותלמוס צדי;קטנה / שובע ייחודי לחוש;קטנה / התכווצויות בקיבה;גדלה)","a":"שובע ייחודי לחוש; קטנה (אכילת טעם אחד יוצרת שובע מהיר יותר לאותו הטעם)","explain":"שובע ייחודי לחוש (sensory-specific satiety) - התופעה שבה ההתלהבות מטעמים, אפילו של מאכלים אהובים, הולכת ופוחתת במהלך הארוחה. השובע חל על טעמים ייחודיים, לא על המזון עצמו - הוכח בניסוי: משתתפים הגיעו לשובע מאננס/מלפפונים, אך גילו עניין מחודש כשהתווסף שינוי קל בטעם (קצפת בטעם וניל, מלח ופלפל).\n\nמודל המרכז הכפול (dual-center model) - תיאוריה מוקדמת שראתה בהיפותלמוס הצדי \"מרכז הרעב\" ובהיפותלמוס הגחוני-מדיאלי \"מרכז השובע\". הנתונים המאוחרים לא איששו את התיאוריה - עכברים עם פגיעה בהיפותלמוס הגחוני-מדיאלי הפריזו באכילה רק כשהמזון היה טעים, ונמנעו לגמרי ממזון לא טעים.\n\nאכילה מרוסנת (restrained eating) - לפי פוליווי והרמן, אכלנים מרוסנים מגבילים כל הזמן את כמות המזון שהם מרשים לעצמם, תמיד \"בדיאטה\", עסוקים כל הזמן באוכל - ללא קשר למשקלם בפועל. כשהופכים \"נטולי עכבות\" (בלחץ), נוטים להיכנע ולזלול מזון עתיר קלוריות.\n\nקצב חילוף החומרים במנוחה - הקצב שבו הגוף שורף קלוריות כדי לשמור על תפקודיו הבסיסיים. יש לו מידה רבה של תורשה - אנשים מסוימים נוטים מראש לשרוף יותר קלוריות, ומי ששורפים פחות נמצאים בסיכון גבוה יותר להשמנה.","mnemo":"🍝 טעם אחד=שובע מהיר, כמות קטנה"},{"id":"quiz10_2","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"כאשר אכלנים מרוסנים הופכים חסרי מעצורים, הם נוטים: (להפסיק דיאטה אחת ולתמיד / להתקפי זלילה של מזון עתיר קלוריות / להמשיך ולהפחית צריכה / להתנהג כמו אכלנים לא מרוסנים)","a":"להתקפי זלילה של מזון עתיר קלוריות (איבוד השליטה מוביל לאכילת יתר קיצונית)","explain":"שובע ייחודי לחוש (sensory-specific satiety) - התופעה שבה ההתלהבות מטעמים, אפילו של מאכלים אהובים, הולכת ופוחתת במהלך הארוחה. השובע חל על טעמים ייחודיים, לא על המזון עצמו - הוכח בניסוי: משתתפים הגיעו לשובע מאננס/מלפפונים, אך גילו עניין מחודש כשהתווסף שינוי קל בטעם (קצפת בטעם וניל, מלח ופלפל).\n\nמודל המרכז הכפול (dual-center model) - תיאוריה מוקדמת שראתה בהיפותלמוס הצדי \"מרכז הרעב\" ובהיפותלמוס הגחוני-מדיאלי \"מרכז השובע\". הנתונים המאוחרים לא איששו את התיאוריה - עכברים עם פגיעה בהיפותלמוס הגחוני-מדיאלי הפריזו באכילה רק כשהמזון היה טעים, ונמנעו לגמרי ממזון לא טעים.\n\nאכילה מרוסנת (restrained eating) - לפי פוליווי והרמן, אכלנים מרוסנים מגבילים כל הזמן את כמות המזון שהם מרשים לעצמם, תמיד \"בדיאטה\", עסוקים כל הזמן באוכל - ללא קשר למשקלם בפועל. כשהופכים \"נטולי עכבות\" (בלחץ), נוטים להיכנע ולזלול מזון עתיר קלוריות.\n\nקצב חילוף החומרים במנוחה - הקצב שבו הגוף שורף קלוריות כדי לשמור על תפקודיו הבסיסיים. יש לו מידה רבה של תורשה - אנשים מסוימים נוטים מראש לשרוף יותר קלוריות, ומי ששורפים פחות נמצאים בסיכון גבוה יותר להשמנה.","mnemo":"💥 מרוסן+שחרור=זלילה קיצונית"},{"id":"quiz10_3","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"בהקשר למוטיבציה, הומאוסטזיס הוא: (מצב איזון בין מצבי הגוף / העדר נוחות פנימית מעוררת פעולה / העדר איזון הקשור למתח / צרכים פנימיים)","a":"מצב בו קיים איזון בין מצבי הגוף השונים (עקרון הבסיס של מוטיבציות ביולוגיות)","explain":"<b>הומאוסטזיס</b>, בהקשר-של-מוטיבציה, הוא <b>מצב-איזון</b> בין מצבי-הגוף-השונים (טמפרטורה, רמת-סוכר, נוזלים) - הגוף שואף-לשמר-איזון-פנימי-יציב, וכל-סטייה-ממנו (למשל, רעב=חוסר-איזון-באנרגיה) מייצרת <b>דחף-פנימי לתקן-את-הסטייה</b> ולחזור-לאיזון. ⚠️ זהו עיקרון-הבסיס להבנת <b>מוטיבציות-ביולוגיות</b> רבות (רעב, צמא, ויסות-חום) - ההתנהגות-המוטיבציונית (לאכול, לשתות) מוסברת כמנגנון שנועד <b>לשחזר</b> את-האיזון-שהופר, לא-כמטרה-בפני-עצמה.","mnemo":"⚖️ הומאוסטזיס=איזון פנימי"},{"id":"quiz10_4","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"ענבל עברה לתפריט צמחוני למרות שהיא אוהבת בשר. איזה תפקיד מוטיבציה: (הקשה על מצבים פרטיים / הסבר התמדה על אף מצוקה / קישור ביולוגיה-התנהגות / הסבר שונות התנהגותית)","a":"להסביר התמדה על אף מצוקה (ערכים אישיים גוברים על אי-נוחות פיזית)","explain":"פסיכולוגים משתמשים במושג מוטיבציה לחמש מטרות בסיסיות:\n\n1. לקשר בין ביולוגיה להתנהגות - מצבים פנימיים של חסך (רעב, צמא, קור) מעוררים תגובות גופניות המניעות אותנו לפעול כדי להחזיר לגוף שיווי משקל.\n\n2. להסביר שונות התנהגותית - מדוע מצליחים במטלה ביום אחד ונכשלים באותה מטלה ביום אחר? פסיכולוגים משתמשים בהסברי מוטיבציה כשאי-אפשר לתלות את השונות בהבדלי יכולת, מיומנות, אימון או מזל.\n\n3. להקיש על מצבים פרטיים מתוך התנהגויות פומביות - בני אדם נוטים לעבור מצפייה בהתנהגות למסקנה על סיבה פנימית שגרמה לה, כולל שאלה אם ההתנהגות נובעת ממוטיבציה פנימית או חיצונית.\n\n4. לייחס אחריות לפעולות - אחריות אישית מניחה מראש קיום מוטיבציה פנימית ויכולת שליטה על פעולות. אחריות מופחתת כאשר: (1) התוצאות לא היו מכוונות. (2) כוחות חיצוניים חזקים עוררו את ההתנהגות. (3) הפעולות הושפעו מסמים/אלכוהול/רגשות עזים.\n\n5. להסביר התמדה על אף מצוקה - מדוע אורגניזם מבצע התנהגות כאשר קל יותר שלא לבצעה? מוטיבציה מסבירה למשל הגעה בזמן לעבודה למרות עייפות, או המשך משחק גם כשברור שאין סיכוי לנצח.","mnemo":"🥦 ענבל אוהבת בשר אך מתמידה בערכים - התמדה למרות מצוקה"},{"id":"quiz10_5","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"הפסטה של רונית פחות טעימה ככל שהארוחה מתקדמת. תופעה זו: (שובע ייחודי לחוש / הרס פריפריאלי / מערכת אכילה מרכזית / תצרוכת יתר מהרגל)","a":"שובע ייחודי לחוש (ההנאה מאותו הטעם פוחתת ככל שאוכלים ממנו יותר)","explain":"שובע ייחודי לחוש (sensory-specific satiety) - התופעה שבה ההתלהבות מטעמים, אפילו של מאכלים אהובים, הולכת ופוחתת במהלך הארוחה. השובע חל על טעמים ייחודיים, לא על המזון עצמו - הוכח בניסוי: משתתפים הגיעו לשובע מאננס/מלפפונים, אך גילו עניין מחודש כשהתווסף שינוי קל בטעם (קצפת בטעם וניל, מלח ופלפל).\n\nמודל המרכז הכפול (dual-center model) - תיאוריה מוקדמת שראתה בהיפותלמוס הצדי \"מרכז הרעב\" ובהיפותלמוס הגחוני-מדיאלי \"מרכז השובע\". הנתונים המאוחרים לא איששו את התיאוריה - עכברים עם פגיעה בהיפותלמוס הגחוני-מדיאלי הפריזו באכילה רק כשהמזון היה טעים, ונמנעו לגמרי ממזון לא טעים.\n\nאכילה מרוסנת (restrained eating) - לפי פוליווי והרמן, אכלנים מרוסנים מגבילים כל הזמן את כמות המזון שהם מרשים לעצמם, תמיד \"בדיאטה\", עסוקים כל הזמן באוכל - ללא קשר למשקלם בפועל. כשהופכים \"נטולי עכבות\" (בלחץ), נוטים להיכנע ולזלול מזון עתיר קלוריות.\n\nקצב חילוף החומרים במנוחה - הקצב שבו הגוף שורף קלוריות כדי לשמור על תפקודיו הבסיסיים. יש לו מידה רבה של תורשה - אנשים מסוימים נוטים מראש לשרוף יותר קלוריות, ומי ששורפים פחות נמצאים בסיכון גבוה יותר להשמנה.","mnemo":"🍝 פסטה משעממת עם הזמן=שובע ייחודי לחוש"},{"id":"quiz10_6","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"איזה משפט אינו נכון עבור אנורקסיה נרבוזה: (שוקל פחות מ-85% ממשקל מצופה / פחד משמעותי מהשמנה / יכולה לבוא עם בולימיה / שכיחות גברים ונשים זהה)","a":"שכיחות הגברים והנשים הלוקים במחלה זהה (שגוי - למעשה נשים לוקות בשכיחות גבוהה יותר)","explain":"המשפט <b>השגוי</b> הוא ש'שכיחות-הגברים-והנשים הלוקים-במחלה זהה' - במציאות, <b>נשים לוקות בשכיחות גבוהה-משמעותית-יותר</b> מגברים באנורקסיה-נרבוזה. ⚠️ שאר-המאפיינים (משקל-נמוך-מ-85%-מהמצופה, פחד-עז-מהשמנה, אפשרות-לבוא-יחד-עם-בולימיה) הם-אכן <b>קריטריונים-אבחוניים-נכונים ומדויקים</b> להפרעה - רק הטענה-על-שכיחות-שווה-בין-המינים היא-הטעות שהשאלה-מבקשת-לזהות.","mnemo":"⚧️ אנורקסיה - נשים הרבה יותר, לא זהה"},{"id":"quiz10_7","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"האזור המוחי המשמש תפקיד מרכזי בשליטה על אכילה: (היפותלמוס / היפוקמפוס / אמיגדלה / תלמוס)","a":"היפותלמוס (מרכז השליטה המרכזי על תחושות רעב/שובע)","explain":"ה<b>היפותלמוס</b> משמש תפקיד-מרכזי בשליטה-על-אכילה - הוא <b>מרכז-השליטה-המרכזי</b> על תחושות רעב/שובע, מווסת-מתי-להתחיל-ומתי-להפסיק-לאכול, בהתבסס-על-איתותים-פיזיולוגיים (רמת-סוכר-בדם, הורמונים). ⚠️ קישור-לפרק-הביולוגיה (פרק 3): זה-בדיוק אותו-היפותלמוס שנלמד-שם כמבנה-קטן-אך-חיוני, המווסת <b>התנהגות-מוטיבציונית</b> באופן-כללי (לא-רק-אכילה - גם צמא, עוררות-מינית, ויסות-חום) ושומר-על-הומאוסטזיס - אכילה היא-רק-דוגמה-ספציפית-אחת מתפקידו-הרחב-יותר.","mnemo":"🧠 היפותלמוס=מרכז הרעב/שובע"},{"id":"quiz10_8","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"לפי תיאוריית הציפיות (ורום), ציפייה היא: (מידה שביצוע יביא תוצאות / מידה שהתוצאות בעלות ערך / מכפלת תכליתיות וערך / תפיסה שמאמצים יניבו רמת ביצוע)","a":"תפיסת העובד שלפיה מאמציו יניבו רמת ביצוע מסוימת (ציפייה=הקשר מאמץ-ביצוע, לא ביצוע-תוצאה)","explain":"על פי תיאוריית הציפיות (expectancy theory) של ורום (Vroom, 1964), מוטיבציה של בני אדם בעבודה תלויה בשילוב בין שלוש קוגניציות: ציפייה, תכליתיות וערך. מוטיבציה = ציפייה × תכליתיות × ערך - זוהי מכפלה, כך שאם קוגניציה כלשהי מייצגת אפס, אין מוטיבציה כלל.\n\nציפייה (Expectancy) - תפיסת העובד שמאמציו יניבו רמת ביצוע מסוימת (קשר מאמץ→ביצוע).\nתכליתיות (Instrumentality) - המידה שבה העובד מאמין שלביצוע שלו יהיו תוצאות (קשר ביצוע→תוצאה).\nערך (Valence) - המידה שבה העובד תופס את התוצאות כבעלות ערך.\n\n⚠️ שלוש דרכים מומחשות להעלאת מוטיבציה: (1) העלאת ציפייה - הדרכה/משוב בונה/תרגול מובנה, כדי שהעובד ילמד שהמאמץ שלו אכן משפר ביצוע. (2) העלאת תכליתיות - קריטריוני הערכה/קידום שקופים ואובייקטיביים, לא תלויים בפוליטיקה פנימית. (3) העלאת ערך - התאמת התגמול המוצע למה שבאמת חשוב לעובד הספציפי (שכר, גמישות, הכרה).","mnemo":"💪→📊 ציפייה=מאמץ מוביל לביצוע (לא לתוצאה)"},{"id":"prof11_01","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו רגש? הציגו דוגמה.","a":"דפוס מורכב של שינויים גופניים ונפשיים: עוררות פיזיולוגית, הרגשות, תהליכים קוגניטיביים, ביטויים גלויים, תגובות התנהגותיות - כלפי מצב בעל חשיבות אישית. דוגמה: שמחה=לב פועם+הרגשה חיובית+פירוש קוגניטיבי+חיוך/חיבוק. שונה ממצב רוח (עוצמה נמוכה, נמשך ימים, לא קשור לאירוע ספציפי).","explain":"פסיכולוגים בני זמננו מגדירים רגש (emotion) כדפוס מורכב של שינויים גופניים ונפשיים, הכולל: עוררות פיזיולוגית, הרגשות (feelings), תהליכים קוגניטיביים, ביטויים גלויים לעין (הבעות פנים, תנוחות גוף) ותגובות התנהגותיות ספציפיות - כלפי מצב הנתפס כבעל חשיבות אישית.\n\nדוגמה: פרץ שמחה - הלב פועם בעדינות (עוררות פיזיולוגית), ההרגשה חיובית, תהליכים קוגניטיביים (פירושים, זיכרונות, ציפיות) מאפשרים לתייג את המצב כ'שמח', והתגובות ההתנהגותיות הגלויות (חיוך, חיבוק).\n\nהבחנה מרגש למצב רוח: רגשות הם תגובות ספציפיות לאירועים ספציפיים - חולפים במהרה, עוצמתם רבה. מצבי רוח עצמתם פחותה, עשויים להימשך ימים, ולרוב אין קשר הדוק בינם לבין אירוע מעורר.","mnemo":"😊 עוררות+הרגשה+מחשבה+הבעה+פעולה = חמישיית-רגש"},{"id":"prof11_02","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"על בסיס אילו ממצאים הסיק טומקינס שמקצת התגובות הרגשיות מולדות?","a":"תינוקות מגיבים לקולות חזקים בפחד/קשיי נשימה ללא למידה מוקדמת. מחקר בין-תרבותי (ארה\"ב/יפן): תינוקות בני 5-12 חודשים הראו אותם דפוסי הבעת מצוקה ואותו שיעור ביטוי קולי שלילי - עקביות חוצת תרבויות.","explain":"סילבן טומקינס (1962, 1981) הצביע על העובדה שבלא למידה מוקדמת, תינוקות מגיבים לקולות חזקים בפחד או בקשיי נשימה - נטייה מראש להגיב לגירויים מסוימים בתגובה רגשית כללית.\n\nחיזוק ממחקר בין-תרבותי: חוקרים ביקרו בבתי תינוקות בני 5 ו-12 חודשים בארה\"ב וביפן, אחזו בפרקי ידיו של כל תינוק ושילבו אותן על בטנו. תינוקות בשתי התרבויות הניעו את שרירי פניהם באותם דפוסים שהראו הבעות מצוקה זהות, והראו שיעור דומה של ביטוי קולי שלילי ומאבק גופני - עקביות חוצת תרבויות התומכת במקור מולד.","mnemo":"👶 תינוק בוכה בלי שיעור - מולד"},{"id":"prof11_03","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"על בסיס אילו ממצאים הראה אקמן רגשות בסיסיים אוניברסליים?","a":"7 הבעות רגש (שמחה,הפתעה,כעס,שאט נפש,פחד,עצב,בוז) זוהו בעקביות ב-6 מדינות שונות. תרבות הפור (לא נחשפה למערב) זיהתה במדויק הבעות מערביות וקישרה למצבים דומים בחייהם; אמריקנים זיהו הבעות הפור. תיאוריה נוירו-תרבותית: המוח קובע ביטוי בסיסי, התרבות מוסיפה אילוצים.","explain":"אקמן טוען שכל בני האדם חולקים אותה 'שפת פנים'. הוא ועמיתיו הדגימו קיום 7 הבעות רגש המשותפות לכל בני האדם: שמחה, הפתעה, כעס, שאט נפש, פחד, עצב ובוז.\n\nהוכחות: (1) מחקרים בין-תרבותיים (הונגריה, יפן, פולין, סומטרה, ארה\"ב, וייטנאם) הראו הסכמה גדולה בזיהוי ההבעות. (2) תרבות הפור בגינאה החדשה, שכמעט לא נחשפה למערב, זיהתה בדייקנות את מצבי הרגש בפני לבנים וקישרה אותם למצבים מחייהם (פחד=חזיר בר רודף, עצב=אובדן ילד). (3) סטודנטים אמריקנים הצליחו לזהות הבעות הפור, עם אותו בלבול (פחד/הפתעה) שאירע גם אצל בני הפור.\n\nהתיאוריה הנוירו-תרבותית: המוח (תוצר אבולוציה) קובע את הביטוי הבסיסי, אך התרבות כופה אילוצים נוספים מעבר לביולוגיה האוניברסלית.","mnemo":"🌍 7 פרצופים, כל העולם מזהה אותם"},{"id":"prof11_04","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד משפיעה התרבות על ביטויי רגשות? הדגימו.","a":"תרבויות קובעות מתי/למי מותר להביע רגש. וולוף (סנגל): אצולה מאופקת, גריוט רגשניים. הלוויה סורית: מקוננות מקצועיות מחליפות זו את זו. כאב: יפנים מרוסנים יותר מאמריקנים (\"סטואיות\"), נשים מותרות יותר מגברים בשתי התרבויות.","explain":"תרבויות שונות קובעות, באמצעות חוקים חברתיים, מתי מותר להראות רגשות מסוימים ולמי. שלוש דוגמאות מהספר:\n\n1. בני הוולוף בסנגל - בני האצולה נדרשים לאיפוק רב; בני הקסטה הנמוכה (גריוט) נדרשים לרגשנות, ואף מבטאים רגשות במקום האצולה.\n\n2. הלוויה סורית-אמריקנית - נשים מקוננות מקצועיות פורצות בבכי/יללה עם כניסת כל מנחם ומפסיקות באותה פתאומיות.\n\n3. הבעת כאב, יפן מול ארה\"ב - יפנים נוחים פחות עם הבעה רגשית גלויה של כאב ('סטואיות מסורתית'). בשתי התרבויות, הבעה גלויה מקובלת יותר אצל נשים מגברים.\n\n⚠️ דוגמה אישית: במשפחות ישראליות רבות, מקובל להביע צער ואבל בקול רם ובבכי גלוי בלוויות, בניגוד לנורמה האנגלו-סקסית המערבית של איפוק והבעה מרוסנת יותר.","mnemo":"🎭 תרבות קובעת מתי מותר לבכות"},{"id":"prof11_05","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"האם הבסיס לרגשות מולד או נלמד? נסחו טיעונים ברורים.","a":"⚠️ סינתזה. מולד: דארווין (אבולוציה), טומקינס (תינוקות ללא למידה), עקביות בין-תרבותית (ארה\"ב/יפן, אקמן-7 הבעות, תרבות הפור). נלמד/תרבותי: הבדלי סין/יפן/ארה\"ב בעוצמת ביטוי, הבדלים בזיהוי הבעות ספציפיות בין מדינות, וולוף/הלוויה סורית/הבעת כאב יפן-ארה\"ב. מסקנה (תיאוריה נוירו-תרבותית, אקמן): שילוב - מנגנון בסיסי מולד, ביטוי בפועל מעוצב תרבותית.","explain":"⚠️ תשובת סינתזה.\n\nטיעונים למולד: דארווין (רגשות כמצבים מנטליים תורשתיים, תוצר אבולוציה); טומקינס (תינוקות מגיבים בפחד לקולות חזקים ללא למידה); עקביות בין-תרבותית בהבעות מצוקה (ארה\"ב/יפן); אקמן (7 הבעות מזוהות בכל תרבות שנבדקה, כולל תרבות הפור שלא נחשפה למערב); תינוקות בני 4-5 חודשים כבר מבחינים ומגיבים בהתאם למשמעות ההבעות.\n\nטיעונים לנלמד/תרבותי: ילדים סיניים בני 11 חודשים הראו פחות ביטויים רגשיים מיפנים/אמריקנים; הבדלים בין מדינות בזיהוי הבעות ספציפיות (יפנים מתקשים בכעס, וייטנאמים בשאט נפש); תרבות הוולוף, הלוויה הסורית, והבעת כאב יפן/ארה\"ב מראות הבדלים תרבותיים חדים בביטוי בפועל.\n\nמסקנת הספר (התיאוריה הנוירו-תרבותית של אקמן): שילוב - קיים בסיס מולד (המוח קובע איזו קבוצת הבעות בסיסית קיימת), אך התרבות כופה אילוצים על מתי/למי/באיזו עוצמה מותר להביע כל רגש בפועל.","mnemo":"⚖️ דארווין-מולד מול תרבות-מלמדת - שניהם צודקים"},{"id":"prof11_06","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"סכמו את תפקיד מערכת העצבים האוטונומית ברגשות (מערכת תגובת החירום).","a":"ענף סימפתטי/פרסימפתטי מאזנים לפי עוצמת/סוג הגירוי. במצב חירום (פחד/כעס): סימפתטי משחרר אפינפרין/נוראפינפרין (גלוקוזה, ל\"ד, הזעה עולים). פרסימפתטי מרגיע לאחר החלוף. עקביות בין-תרבותית (ארה\"ב/מיננגקבאו) תומכת במקור גנטי משותף.","explain":"מערכת העצבים האוטונומית מכינה את הגוף לתגובות רגשיות באמצעות פעילות הענף הסימפתטי והפרסימפתטי גם יחד. שיווי המשקל תלוי באיכות הגירוי ובעצמתו: גירוי מתון ולא נעים→סימפתטי פעיל יותר; גירוי מתון ונעים→פרסימפתטי פעיל יותר; גירוי עז מכל סוג→שני הענפים פעילים יותר.\n\nמערכת תגובת החירום: רגשות חזקים (פחד/כעס) מפעילים את מערכת תגובת החירום. מערכת העצבים הסימפתטית נוטלת פיקוד ומורה על שחרור הורמונים (אפינפרין ונוראפינפרין) מבלוטות האדרנל - גורם לאיברים הפנימיים להפריש גלוקוזה, להעלות לחץ דם, להגביר הזעה, להפחית ריור. לאחר שהחירום חולף, מערכת העצבים הפרסימפתטית מפסיקה את הפרשת ההורמונים ומרגיעה את הגוף.\n\nעדות בין-תרבותית: מחקר שהשווה אמריקנים לבני תרבות המיננגקבאו (סומטרה) מצא רמה גבוהה של דמיון בדפוסי הפעילות האוטונומית - 'חלק חשוב במטען הגנטי המשותף'.","mnemo":"🚨 סימפתטי=גז | פרסימפתטי=בלם"},{"id":"prof11_07","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"סכמו את תפקיד האמיגדלה ברגשות.","a":"שער כניסה לרגשות ומסנן לזיכרון - מצמידה משמעות למידע חושי, בעיקר לחוויות שליליות (פעילות עולה עם עצמת פחד, יורדת עם עצמת שמחה). הבדלי מגדר: גברים=אמיגדלה ימנית (מחוברת לסביבה חיצונית); נשים=שמאלית (מחוברת לסביבה פנימית).","explain":"ההיפותלמוס והמערכת הלימבית מפקחים על שילוב האספקטים ההורמונליים והעצביים של עוררות. האמיגדלה, כחלק מהמערכת הלימבית, משמשת כשער הכניסה לרגשות וכמסנן לזיכרון - מצמידה משמעות למידע חושי, בעיקר לחוויות שליליות.\n\nדוגמה: כשאנשים צופים בהבעות מפוחדות, האמיגדלה השמאלית מראה פעילות הולכת וגוברת ככל שעולה עצמת ההבעה; הבעות שמחות יוצרות פעילות הולכת ופוחתת.\n\nהבדלי מגדר: גברים מראים פעילות רבה יותר באמיגדלה הימנית, המחוברת לאזורי מוח המכוונים לסביבה החיצונית (קורטקס מוטורי/ראייה). נשים מראות פעילות רבה יותר באמיגדלה השמאלית, המחוברת לאזורים המכוונים לסביבה הפנימית (כמו ההיפותלמוס).","mnemo":"🚪 אמיגדלה=שומר-סף, בעיקר לרע"},{"id":"prof11_08","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"סכמו את תפקיד הקורטקס ברגשות - תגובות התקרבות והתרחקות.","a":"קורטקס מספק אסוציאציות/זיכרונות/משמעויות. רגשות מנוגדים=פעילות בחלקים שונים של המוח, לא מנוגדת באותו אזור. תגובות התקרבות (המיספרה שמאלית, תוכן חיובי) מול תגובות התרחקות (המיספרה ימנית, תוכן שלילי) - הוכח ב-fMRI (כלבלבים מול עכבישים).","explain":"תפקיד הקורטקס ברגשות מתבסס על-כך שהוא מספק <b>אסוציאציות, זיכרונות, ומשמעויות</b> לחוויה-הרגשית-הגולמית (הבאה-מהמערכת-הלימבית). <b>ממצא-מפתיע חשוב</b>: רגשות-מנוגדים <b>אינם</b> מיוצרים באותו-אזור-מוחי-אחד עם-כיוונים-שונים - הם מיוצגים על-ידי <b>פעילות-בחלקים-שונים-לגמרי</b> של המוח. <b>ההוכחה ב-fMRI</b>: <b>תגובות-התקרבות</b> (משיכה, רצון-להתקרב, תוכן-חיובי - כמו-תמונת-כלבלב) מפעילות בעיקר את ה<b>המיספרה השמאלית</b>; <b>תגובות-התרחקות</b> (דחייה, רצון-לברוח, תוכן-שלילי - כמו-תמונת-עכביש) מפעילות בעיקר את ה<b>המיספרה הימנית</b>. ⚠️ זו-הוכחה ביולוגית-ישירה שהמוח 'מארגן' רגשות לפי <b>כיוון-הפעולה-המונע</b> (להתקרב/להתרחק), לא-רק-לפי 'חיובי/שלילי' כתוכן-מופשט.","mnemo":"😊👈😨👉 שמאל=מתקרב-לטוב | ימין=בורח-מרע"},{"id":"prof11_reflection1","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תארו כיצד 3 תיאוריות הרגש מסבירות פחד מכלב מאיים (טבלה 1).","a":"ג'יימס-ולנגה: גוף מגיב (הזעה/דופק)→מכאן מבינים שפוחדים (גוף→רגש). קנון-בארד: פחד וגוף מגיבים בו-זמנית, ללא תלות זה בזה. הערכה קוגניטיבית: מעריכים סכנה→עוררות→מייחסים עוררות לסכנה→פחד.","explain":"ג'יימס-ולנגה (תיאוריה היקפית): הגירוי המעורר גורם לעוררות אוטונומית ולפעולות גופניות, המובילות לתחושת הרגש. ציטוט: 'אני מזיע וקצב פעימות לבי מתגבר ומכאן אני מבין שאני פוחד' - הגוף מגיב ראשון, ההבנה של הרגש מגיעה אחר כך.\n\nקנון-בארד (תהליכים עצביים מרכזיים): הגירוי מעובד במוח וגורם, בעת ובעונה אחת, לתגובה פיזית (עוררות) ולתחושת הרגש - תגובה אחת אינה סיבה לשנייה. ציטוט: 'אני פוחד ובאותו הזמן אני מזיע וקצב פעימות לבי מתגבר' - שני הדברים קורים יחד, ללא קשר סיבתי ביניהם.\n\nהערכה קוגניטיבית (שכטר/לזרוס): תחושת הרגש נובעת מתהליך הערכה קוגניטיבי המתייחס הן למאפייני הגירוי הן לעוררות הפיזיולוגית. ציטוט: 'אני מעריך שאני נמצא מול סכנה פיזית מיידית... אני מייחס את קצב הלב המוגבר... לסכנה שמולי ואני חווה פחד' - יש שלב הערכה/פרשנות מודעת של ההקשר לפני שהרגש הספציפי מתגבש.","mnemo":"🐕 גוף-קודם / בו-זמנית / פרשנות - 3 דרכים לפחד"},{"id":"prof11_09","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד תומך ניסוי דאטון וארון (הגשר) בתיאוריית ההערכה הקוגניטיבית?","a":"גברים שחצו גשר מסוכן (עוררות גבוהה) כתבו סיפורים מיניים יותר והתקשרו פי 4 לחוקרת - ייחסו בטעות את העוררות (שנבעה מהסכנה) למשיכה אליה. קבוצת ביקורת שרואיינה 10 דק' אחרי (עוררות דעכה) לא הראתה זאת - מוכיח שאותה עוררות כללית מתפרשת/מתויגת לפי הקשר, בהתאם לעקרון ההערכה הקוגניטיבית.","explain":"חוקרת ראיינה גברים שזה עתה חצו גשר יציב או גשר רעוע ומסוכן בוונקובר. היא העמידה פנים שבוחנת השפעת נוף על יצירתיות, ביקשה סיפור על תמונה דו-משמעית של אישה, והזמינה אותם להתקשר לקבלת מידע נוסף.\n\nתוצאות: הגברים שחצו את הגשר המסוכן כתבו סיפורים עם יותר דימויים מיניים, והתקשרו לחוקרת פי ארבעה יותר. קבוצת ביקורת שרואיינה 10 דקות לאחר חציית הגשר המסוכן (זמן מספיק לדעיכת העוררות) לא הראתה סימני תגובה מינית.\n\nהתמיכה בתיאוריה: הגברים הגיעו לשיפוט רגשי ('אני מעוניין באישה') על סמך ייחוס מוטעה (misattribution) של מקור העוררות - ייחסו את עוררותם (שנבעה מהסכנה) לאישה. מדגים בדיוק את עקרון התיאוריה: אותה עוררות פיזיולוגית כללית מתפרשת/מתויגת באופנים שונים בהתאם להערכה הקוגניטיבית ולרמזי ההקשר.","mnemo":"🌉 גשר מפחיד=דופק מהיר, מתפרש בטעות כמשיכה"},{"id":"prof11_10","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"אילו ממצאים תומכים בשתי הביקורות על תיאוריית ההערכה הקוגניטיבית?","a":"ביקורת 1 (מובחנות פיזיולוגית): מחקר לוונסון - דפוסי עוררות שונים לרגשות שונים (לא זהים), מפחית צורך בהערכה. ביקורת 2 (עיבוד קוגניטיבי לא הכרחי): אפקט החשיפה בלבד (זיאונץ) - גירויים לא מודעים עדיין יצרו העדפה רגשית, ללא הערכה קוגניטיבית מודעת אפשרית.","explain":"ביקורת 1 - מובחנות הביטויים הפיזיולוגיים: מחקר לוונסון ועמיתיו (1992, השוואת אמריקנים לבני תרבות המיננגקבאו) הראה שמצבי עוררות המלווים רגשות שונים אינם זהים אלא מובחנים. אם כל רגש מלווה בדפוס פיזיולוגי מובחן משלו, אין עמימות הדורשת הערכה קוגניטיבית.\n\nביקורת 2 - הצורך בעיבוד קוגניטיבי כתנאי מקדים: מחקרי אפקט החשיפה בלבד של רוברט זיאונץ - גירויים (מילים זרות, אותיות סיניות) הוצגו מהר מכדי זיהוי מודע. משתתפים דירגו גירויים 'ישנים' (שהוצגו קודם, אף שלא היו מודעים לכך) גבוה יותר מגירויים 'חדשים' - הוכחה שנוצרה תגובה רגשית (העדפה) ללא כל אפשרות לעיבוד קוגניטיבי מודע.","mnemo":"🔬 עוררויות שונות + חשיפה-בלי-מודעות = 2 חורים בתיאוריה"},{"id":"quiz11_1","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"איזו הבעה אינה נמנית עם 7 הבעות הרגש האוניברסליות? (שאט-נפש / דאגה / בוז / שמחה)","a":"דאגה (לא נמנית עם 7 ההבעות - היא רגש מורכב/משני יותר)","explain":"<b>דאגה</b> אינה נמנית עם 7-הבעות-הרגש-האוניברסליות של אקמן - היא נחשבת רגש <b>מורכב/משני-יותר</b>, לא-בסיסי. ⚠️ שבעת-הרגשות-הבסיסיים (שנלמדו-בפרק) הם: שמחה, הפתעה, כעס, שאט-נפש, פחד, עצב, ובוז - <b>דאגה</b> ('שאט-נפש' ו'בוז' כן-נכללים ברשימה-האמיתית) אינה-אחת-מהן, כי היא-נתפסת כתערובת/גרסה-מורכבת-יותר של-רגשות-בסיסיים-אחרים (כמו-פחד+עצב), לא-רגש-נפרד-ועצמאי בפני-עצמו.","mnemo":"❌ דאגה - לא באחת מ-7"},{"id":"quiz11_2","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"מהי הראיה שלא כל החוויות הרגשיות נשענות על הערכה קוגניטיבית? (הבעות פנים דומות בתרבויות / אין ביטוי כאב בתרבויות מסוימות / חווית אפקט החשיפה בלבד / מעגל נפרד לתגובות התרחקות)","a":"בני אדם חווים את אפקט החשיפה בלבד (העדפה נוצרת ללא כל עיבוד קוגניטיבי מודע)","explain":"ההוכחה שלא-כל-החוויות-הרגשיות נשענות-על-הערכה-קוגניטיבית: <b>אפקט-החשיפה-בלבד</b> (הניסוי-של-זיאונק, שנלמד-בפרק) - משתתפים פיתחו-העדפה-רגשית-חיובית לגירויים שנחשפו-אליהם, <b>גם כשהחשיפה הייתה מהירה-מדי מכדי-לזהות-במודע</b> את-הגירוי-כלל. ⚠️ אם-רגש התעורר <b>בלי אפשרות-לעיבוד-קוגניטיבי-מודע</b> (לא-היה-אפילו-סיפק-לזהות-מה-ראו), זו-הוכחה-חזקה שתגובה-רגשית יכולה-להתעורר <b>ללא</b> תהליך-הערכה-קוגניטיבית-מודעת - בניגוד-לתיאוריית-שכטר/לזרוס שטוענת-שהערכה-קוגניטיבית תמיד-נדרשת.","mnemo":"🙈 אפקט-חשיפה=העדפה בלי לדעת למה"},{"id":"quiz11_3","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"ה___ מכין/ה את הגוף להיבטים הפיזיולוגיים של תגובות רגשיות. (אמיגדלה / היפותלמוס / מערכת העצבים האוטונומית / היפוקמפוס)","a":"מערכת העצבים האוטונומית (מפעילה תגובת חירום פיזיולוגית - דופק/הזעה)","explain":"מערכת העצבים האוטונומית מכינה את הגוף לתגובות רגשיות באמצעות פעילות הענף הסימפתטי והפרסימפתטי גם יחד. שיווי המשקל תלוי באיכות הגירוי ובעצמתו: גירוי מתון ולא נעים→סימפתטי פעיל יותר; גירוי מתון ונעים→פרסימפתטי פעיל יותר; גירוי עז מכל סוג→שני הענפים פעילים יותר.\n\nמערכת תגובת החירום: רגשות חזקים (פחד/כעס) מפעילים את מערכת תגובת החירום. מערכת העצבים הסימפתטית נוטלת פיקוד ומורה על שחרור הורמונים (אפינפרין ונוראפינפרין) מבלוטות האדרנל - גורם לאיברים הפנימיים להפריש גלוקוזה, להעלות לחץ דם, להגביר הזעה, להפחית ריור. לאחר שהחירום חולף, מערכת העצבים הפרסימפתטית מפסיקה את הפרשת ההורמונים ומרגיעה את הגוף.\n\nעדות בין-תרבותית: מחקר שהשווה אמריקנים לבני תרבות המיננגקבאו (סומטרה) מצא רמה גבוהה של דמיון בדפוסי הפעילות האוטונומית - 'חלק חשוב במטען הגנטי המשותף'.","mnemo":"🚨 מערכת אוטונומית=גוף מוכן לפעולה"},{"id":"quiz11_4","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"איזה היגד נכון למצבי רוח אך לא לרגשות? (חיוביים/שליליים / נמשכים ימים אחדים / נובעים מאירועים ספציפיים / רבי עצמה)","a":"הם עשויים להימשך ימים אחדים (רגשות חולפים מהר; מצבי רוח נמשכים זמן רב)","explain":"היגד <b>נכון-למצבי-רוח אך-לא-לרגשות</b>: הם 'עשויים-להימשך <b>ימים-אחדים</b>' - מצבי-רוח הם <b>מתמשכים-וכלליים</b> (לא-קשורים-לאירוע-ספציפי-אחד, יכולים-להימשך-שעות/ימים), בעוד רגשות הם <b>חולפים-ומהירים</b> (דקות, לכל-היותר) ו<b>קשורים-ישירות</b> לאירוע-מעורר-ספציפי. ⚠️ שאר-המאפיינים (חיוביים/שליליים, נובעים-מאירועים-ספציפיים, רבי-עצמה) מתאימים <b>לרגשות</b>, לא-למצבי-רוח - מצב-רוח דווקא-פחות-קשור-לאירוע-מעורר-ספציפי-ומיידי, ולרוב-פחות-עצמתי (יותר 'רקע-כללי' מאשר 'תגובה-חדה').","mnemo":"📅 מצב-רוח נשאר, רגש חולף"},{"id":"quiz11_5","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"לפי תיאוריית ___ אנו מרגישים לאחר שגופנו מגיב. (הערכה קוגניטיבית / ג'יימס ולנגה / קנון ובארד / תגובות התקרבות)","a":"ג'יימס ולנגה (הגוף מגיב ראשון, הרגש מגיע רק אחרי)","explain":"ג'יימס-ולנגה (תיאוריה היקפית): הגירוי המעורר גורם לעוררות אוטונומית ולפעולות גופניות, המובילות לתחושת הרגש. ציטוט: 'אני מזיע וקצב פעימות לבי מתגבר ומכאן אני מבין שאני פוחד' - הגוף מגיב ראשון, ההבנה של הרגש מגיעה אחר כך.\n\nקנון-בארד (תהליכים עצביים מרכזיים): הגירוי מעובד במוח וגורם, בעת ובעונה אחת, לתגובה פיזית (עוררות) ולתחושת הרגש - תגובה אחת אינה סיבה לשנייה. ציטוט: 'אני פוחד ובאותו הזמן אני מזיע וקצב פעימות לבי מתגבר' - שני הדברים קורים יחד, ללא קשר סיבתי ביניהם.\n\nהערכה קוגניטיבית (שכטר/לזרוס): תחושת הרגש נובעת מתהליך הערכה קוגניטיבי המתייחס הן למאפייני הגירוי הן לעוררות הפיזיולוגית. ציטוט: 'אני מעריך שאני נמצא מול סכנה פיזית מיידית... אני מייחס את קצב הלב המוגבר... לסכנה שמולי ואני חווה פחד' - יש שלב הערכה/פרשנות מודעת של ההקשר לפני שהרגש הספציפי מתגבש.","mnemo":"🏃→😨 ג'יימס-ולנגה: גוף רץ קודם, רגש בא אחריו"},{"id":"quiz11_6","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"לפי אקמן, מי מהבאים אינו רגש בסיסי? (אהבה / אושר / גועל / עצב)","a":"אהבה (מורכבת מדי - אינה אחת מ-7 ההבעות הבסיסיות של אקמן)","explain":"<b>אהבה</b> אינה נמנית-עם 7-הרגשות-הבסיסיים-של אקמן - היא נחשבת <b>מורכבת-מדי</b> (כוללת מרכיבים-קוגניטיביים, חברתיים, וזמניים-ארוכים) מכדי-להיחשב 'רגש-בסיסי' יחיד-ופשוט. ⚠️ שבעת-הרגשות-הבסיסיים-האמיתיים: שמחה, הפתעה, כעס, שאט-נפש, פחד, עצב, בוז (אושר וגועל שברשימת-האפשרויות מתאימים-לשמחה/שאט-נפש) - <b>אהבה</b> אינה-ביניהם, בדיוק כמו-ש'דאגה' לא-הייתה-ברשימה-בשאלה-קודמת - שני-רגשות 'מורכבים' שלא-נכללים-בשבעת-הבסיסיים.","mnemo":"❤️ אהבה מורכבת מדי - לא בסיסית"},{"id":"quiz11_7","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"רוני ראה נמר, ברח לפני שהספיק לחשוב, הבין רק אחרי שברח. תואם לתיאוריה: (הערכה קוגניטיבית / ג'יימס ולנגה / קנון ובארד / אפקט החשיפה בלבד)","a":"התיאוריה של ג'יימס ולנגה (פעולה גופנית קדמה להבנת הרגש)","explain":"ג'יימס-ולנגה (תיאוריה היקפית): הגירוי המעורר גורם לעוררות אוטונומית ולפעולות גופניות, המובילות לתחושת הרגש. ציטוט: 'אני מזיע וקצב פעימות לבי מתגבר ומכאן אני מבין שאני פוחד' - הגוף מגיב ראשון, ההבנה של הרגש מגיעה אחר כך.\n\nקנון-בארד (תהליכים עצביים מרכזיים): הגירוי מעובד במוח וגורם, בעת ובעונה אחת, לתגובה פיזית (עוררות) ולתחושת הרגש - תגובה אחת אינה סיבה לשנייה. ציטוט: 'אני פוחד ובאותו הזמן אני מזיע וקצב פעימות לבי מתגבר' - שני הדברים קורים יחד, ללא קשר סיבתי ביניהם.\n\nהערכה קוגניטיבית (שכטר/לזרוס): תחושת הרגש נובעת מתהליך הערכה קוגניטיבי המתייחס הן למאפייני הגירוי הן לעוררות הפיזיולוגית. ציטוט: 'אני מעריך שאני נמצא מול סכנה פיזית מיידית... אני מייחס את קצב הלב המוגבר... לסכנה שמולי ואני חווה פחד' - יש שלב הערכה/פרשנות מודעת של ההקשר לפני שהרגש הספציפי מתגבש.","mnemo":"🐅 ברח לפני שחשב = ג'יימס-ולנגה"},{"id":"quiz11_8","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"תיאוריות ההערכה הקוגניטיבית לוקחות בחשבון את: (האדם בלבד / האדם והסביבה / הסביבה בלבד / מערכת העצבים בלבד)","a":"האדם והסביבה (משלבת גם את המצב החיצוני, לא רק את הפרט)","explain":"תיאוריות-ההערכה-הקוגניטיבית (כמו-של-לזרוס) לוקחות-בחשבון גם את <b>האדם וגם את-הסביבה</b> - לא-רק-את-הפרט-לבדו, ולא-רק-את-הגירוי-החיצוני-לבדו. ⚠️ ההיגיון: לפי-התיאוריה, רגש נוצר מ<b>הערכה</b> (קוגניטיבית) של-<b>הקשר</b> בין-מה-שקורה-בסביבה לבין-המשמעות-שלו-<b>עבור-האדם-הספציפי</b> (מטרותיו, ערכיו, פגיעותו) - זה-בדיוק ה'אינטראקציה' בין-אדם-וסביבה, לא-רק-אחד-מהם-בנפרד, שקובעת-איזה-רגש-יתעורר ובאיזו-עוצמה.","mnemo":"🌍+🧍 הערכה קוגניטיבית=אדם+סביבה יחד"},{"id":"quiz11_10","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"\"האם חוויה רגשית מעוררת דפוס פעילות מוגדר במע' העצבים האוטונומית?\" לפי מחקרים בין-תרבותיים: (שלילית / חיובית / לא ניתן לחקור / לא תחום מחקרים בין-תרבותיים)","a":"התשובה לכך חיובית (יש דפוסי פעילות אוטונומית עקביים חוצי-תרבויות)","explain":"מחקרים בין-תרבותיים מצאו תשובה <b>חיובית</b> - יש דפוסי-פעילות-אוטונומית (קצב-לב, הזעה, טמפרטורת-עור) <b>עקביים-חוצי-תרבויות</b> לכל רגש-בסיסי - כלומר, אותו-רגש (למשל כעס) מייצר-תבנית-פיזיולוגית-דומה בבני-אדם מתרבויות-שונות-לגמרי. ⚠️ זו-הוכחה-נוספת (בנוסף-לזיהוי-הבעות-הפנים-האוניברסלי, שנלמד-בשאלה-סמוכה) לכך <b>שלרגשות-בסיסיים יש בסיס-ביולוגי-מולד</b>, לא-רק-תרבותי-נלמד - התגובה-הפיזיולוגית-הבסיסית לרגש דומה בכל-בני-האדם, ללא-קשר-לתרבותם.","mnemo":"✅ תבניות אוטונומיות עקביות בין תרבויות"},{"id":"quiz11_11","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"לבני תרבויות שונות מראים צילומי רגשות בסיסיים. מה ניתן לומר על הזיהוי? (מזוהים נכונה בתרבויות שונות / זוהים שונה במפותחות/פרימיטיביות / רק מאומנים מזהים נכונה / כל אדם מזהה אחרת)","a":"שהם מזוהים נכונה בתרבויות שונות (תומך במקור מולד/אוניברסלי של הבעות פנים)","explain":"כשמראים לבני-תרבויות-שונות צילומי-הבעות-רגשיות-בסיסיות, נמצא שהן <b>מזוהות-נכון בתרבויות-שונות</b> - כלומר, אנשים מתרבויות-שונות-לגמרי (כולל-תרבויות-מבודדות שלא-נחשפו-להשפעה-מערבית) מזהים-נכון את-אותן-שבע-ההבעות-הבסיסיות. ⚠️ ממצא-זה תומך-חזק במקור <b>מולד/אוניברסלי</b> של-הבעות-הפנים - אם-הזיהוי היה-תלוי-בלמידה-תרבותית-ספציפית, היינו-מצפים-להבדלים-משמעותיים בין-תרבויות-שונות/מבודדות; העובדה-שהזיהוי <b>אוניברסלי ועקבי</b> מחזקת את-הטענה שהבעות-רגש-בסיסיות הן חלק מהמטען-הביולוגי-המשותף-של-המין-האנושי, לא-תוצר-של-למידה-תרבותית-בלבד.","mnemo":"🌍✅ הבעות מזוהות נכון בכל תרבות"},{"id":"prof12_reflection1","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע מאמצים תיאוריות טיפוסים מבוססות מאפיינים חיצוניים, גם כשאינן מנבאות התנהגות?","a":"⚠️ הסבר מבוסס עקרונות תפיסה. מאפיינים חיצוניים (צבע שיער) בולטים ונגישים תפיסתית - קל ומהיר לקטלג לפיהם, בניגוד לתכונות פנימיות שדורשות תצפית ממושכת. ברגע שקטגוריה חזותית קיימת, נוח \"להדביק\" אליה משמעות נוספת (מתאם מדומה), גם ללא בסיס אמפירי.","explain":"⚠️ הסבר מבוסס עקרונות תפיסה (פרק 4). מאפיינים פיזיים חיצוניים (צבע שיער, מבנה גוף) בולטים ונגישים תפיסתית - המידע הראשון והקל ביותר לעיבוד, עוד לפני שיש הזדמנות ללמוד משהו ממשי על האדם. המוח נוטה לקבץ מידע לקטגוריות אוטומטית ומהירה - קטגוריה חזותית בולטת מספקת תווית נוחה וזמינה מיד. ברגע שקטגוריה קיימת, קל 'להדביק' אליה משמעות נוספת (מתאם מדומה) גם ללא בסיס אמפירי - נוח פסיכולוגית להניח שקטגוריה תפיסתית ברורה חוזה גם תוכן פנימי.","mnemo":"🎨 שיער-צבעוני קל לקטלג מ-אישיות-עמוקה"},{"id":"prof12_02","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תארו את תיאוריית הטיפוסים של סלווי המבוססת על סדר הלידה.","a":"בכורים=נישה מוכנה מראש (אהבת הורים), מזדהים ומצייתים, שומרים על המצב הקיים. אחים צעירים=\"נולדו למרוד\" - מחפשים נישה משלהם, נכונות להתנסות/חדשנות. מבוסס על עקרון דרווין: אורגניזמים משתנים כדי למצוא נישות הישרדות.","explain":"פרנק סלווי (1996) גיבש תיאוריית טיפוסים המבוססת על סדר הלידה - בכור מול אח צעיר יותר. מבוססת על טענת דרווין שאורגניזמים משתנים בשל הצורך למצוא נישות שבהן יוכלו לשרוד. בכורים זוכים מלידה לנישה מוכנה מראש (אהבת ותשומת לב ההורים), ולכן מזדהים עם ההורים ומצייתים להם - שומרים על המצב הקיים. אחים צעירים צריכים למצוא נישה משלהם - סלווי מכנה אותם 'נולדו למרוד': חותרים להצטיינות בתחומים שאחיהם הבוגרים לא הוכיחו בהם עליונות, מפתחים נכונות להתנסות.","mnemo":"👶 בכור=שומר-מסורת | צעיר=מהפכן"},{"id":"prof12_03","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד תומך מחקר סלווי (תרשים 13.1) בחלוקה לטיפוסים לפי סדר הלידה?","a":"בחן תמיכה של 1,218 מדענים ב-23 תיאוריות מדעיות חדשניות מול מקומם בסדר הלידה. בכל גדלי המשפחה (2 עד 7+), אחים צעירים נטו לתמוך בחדשנות יותר מבכורים באופן עקבי - תומך בניבוי שסדר הלידה חוזה התנהגות בעקביות.","explain":"כדי לבחון שאחים צעירים מקדמים בברכה חידושים בעוד בכורים מעדיפים לשמר, בחן סלווי מהפכות במדע. בדק את מידת התמיכה של 1,218 מדענים ב-23 תיאוריות מדעיות חדשניות, ומקומם בסדר הלידה. הממצא: יהא גודל המשפחה אשר יהא (2 עד 7+ ילדים), אחים צעירים נטו לתמוך בתיאוריה החדשנית יותר מבכורים, בעקביות בכל קטגוריות גודל המשפחה - עדות אמפירית ישירה לניבוי המרכזי של התיאוריה.","mnemo":"📊 1,218 מדענים - הצעירים תמכו בחדש"},{"id":"prof12_04","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי תכונה? הציגו דוגמה ונמקו מדוע היא תואמת את ההגדרה.","a":"מאפיין קבוע היוצר נטייה להתנהג בעקביות במצבים שונים - ממד רציף (לא קטגוריה בדידה). דוגמה: יושר - בא לידי ביטוי בהחזרת ארנק שאבד ובאי-העתקה בבחינה - ממד רציף שיוצר עקביות במגוון רחב של מצבים שונים.","explain":"תכונה (trait) היא מהות/מאפיין קבוע, היוצר נטייה להתנהג בעקביות במצבים שונים. בניגוד לתיאוריות טיפוסים (קטגוריות בדידות), תיאוריות תכונות מציעות ממדים רציפים (continuous dimensions). דוגמה: יושר - בא לידי ביטוי בהחזרת ארנק שאבד, ובאי-העתקה בבחינה. תואם את ההגדרה כי הוא ממד רציף (יותר/פחות ישר) היוצר נטייה עקבית להתנהג באופן דומה על פני מגוון רחב של מצבים שונים.","mnemo":"🎯 יושר=ממד-רציף, לא כן/לא"},{"id":"prof12_05","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד מבטאת אמרת אלפורט (\"אותה אש ממיסה חמאה ומקשה ביצה\") את תפקיד התכונות?","a":"התכונה פועלת כמשתנה מתווך: אותו גירוי חיצוני (האש) יוצר תגובות מנוגדות (הפשרה/הקשחה) בהתאם למאפיין הפנימי היציב של החומר - כך גם אותו מצב חיצוני מעורר תגובות שונות אצל אנשים שונים, בהתאם לתכונות האישיות הפנימיות שלהם.","explain":"אלפורט ראה בתכונות אבני הבניין של האישיות - יוצרות התנהגות לכידה, כמשתנים מתווכים המקשרים בין גירויים לתגובות. האמרה ממחישה זאת: אותו הגירוי החיצוני (האש) יוצר תגובות שונות ומנוגדות (הפשרה מול הקשחה), בהתאם למאפיין הפנימי היציב של החומר (חמאה מול ביצה). באותו האופן, אותו מצב חיצוני מעורר תגובות שונות אצל בני אדם שונים, בהתאם לתכונות האישיות הפנימיות והיציבות שלהם - התכונה 'מתווכת' ומכתיבה את התגובה.","mnemo":"🔥🧈🥚 אותה אש - חמאה נמסה, ביצה מתקשה"},{"id":"prof12_06","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו את ההבדלים בין תיאוריות טיפוסים לתיאוריות תכונות.","a":"טיפוסים=קטגוריות בדידות/לא-רציפות (הכול-או-לא-כלום, כמו בכור/לא-בכור) - פשוטות אך מפספסות ניואנסים. תכונות=ממדים רציפים (כמו מופנם←→מוחצן) - מאפשרות גמישות ודרגות ביניים, מבחינות בקווים עדינים יותר של האישיות.","explain":"⚠️ סינתזה. תיאוריות טיפוסים מסווגות בני אדם לקטגוריות בדידות, לא-רציפות (הכול-או-לא-כלום) - אדם השייך לטיפוס אחד אינו יכול להיות גם בטיפוס אחר (למשל, בכור/לא-בכור). תיאוריות תכונות מציעות ממדים רציפים - אדם יכול להיות ממוקם בכל נקודה על גבי סולם (למשל יושר). תיאוריות טיפוסים פשוטות ונוחות, אך אינן מבחינות בקווים העדינים של האישיות; תיאוריות תכונות מאפשרות גמישות רבה יותר בין בני אדם.","mnemo":"🔲↔️📏 טיפוסים=קופסאות | תכונות=סרגל"},{"id":"prof12_reflection2","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"התאימו כל תכונה לגורם המתאים בחמשת הגורמים, וציינו קוטב (נמוך/גבוה).","a":"מוחצנות: גבוה=בעל מרץ/דברן/דעתן, נמוך=שקט/מופנם/ביישן. נועם הליכות: גבוה=אוהד/טוב לב/רוחש חיבה, נמוך=קר/מחרחר ריב/אכזר. מצפוניות: גבוה=מאורגן/זהיר/אחראי, נמוך=קל דעת/רשלן/חסר אחריות. נוירוטיות: גבוה=נוטה למצבי רוח/לא יציב, נמוך=יציב/רגוע/שבע רצון. פתיחות: גבוה=אינטלקטואלי/יצירתי/רחב אופקים, נמוך=לא אינטליגנטי/רדוד.","explain":"טריק לזכירה - שם החמישה: OCEAN (Openness, Conscientiousness, Extraversion, Agreeableness, Neuroticism). חשוב לזכור: כל גורם הוא ★רצף אחד★ עם שני קטבים (לא שתי קטגוריות נפרדות) - אדם ממוקם איפשהו על הסולם, לא 'שייך' רק לצד אחד. למשל, מוחצנות-מופנמות הם שני קצוות של אותו הממד, לא שתי תכונות שונות.","mnemo":"🎚️ 5 כפתורים, כל אחד גבוה/נמוך"},{"id":"prof12_07","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"במה דומים ובמה שונים תאומים מונוזיגוטים/דיזיגוטים, וכיצד בודקים תורשתיות?","a":"דומים: סביבה משותפת דומה. שונים: מונוזיגוטים=100% גנים משותפים; דיזיגוטים=50%. בדיקת תורשתיות: אם מונוזיגוטים דומים זה לזה יותר מדיזיגוטים בתכונה מסוימת (הוכח: מתאם 0.52 מול 0.23), זה מעיד על תרומה תורשתית גבוהה.","explain":"תאומים מונוזיגוטים (זהים) משתפים 100% מהמטען הגנטי. תאומים דיזיגוטים (לא-זהים) משתפים בממוצע 50%. הדמיון: שני הסוגים חולקים סביבה דומה במידה שווה. לבדיקת תורשתיות: אם תכונה תורשתית ברובה, מונוזיגוטים ידמו זה לזה יותר מדיזיגוטים. הוכחה: מתאם 0.52 (מונוזיגוטים) מול 0.23 (דיזיגוטים) בדירוגי אישיות עצמיים ושל עמיתים - אומדני תורשתיות גבוהים לכל אחד מגורמי חמשת הגורמים.","mnemo":"👯 100%=זהים | 50%=רגילים"},{"id":"prof12_08","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו פרדוקס העקיבות? הציגו דוגמה.","a":"הערכות אישיות מצופים שונים/זמנים שונים עקיביות זו עם זו, אך ההתנהגות בפועל במצבים שונים אינה עקיבה (הוכח: מתאם חלש בין שקר/רמאות אצל תלמידים). דוגמה: חבר תמיד נתפס כ\"ביישן\", אך ביישן במסיבות ובטוח בעצמו כשמלמד כיתה.","explain":"פרדוקס העקיבות (consistency paradox) - התופעה שבה הערכות אישיות מצופים שונים בזמנים שונים עקיביות זו עם זו (נתפסים כיציבים), אך ההתנהגות בפועל במצבים שונים אינה עקיבה כלל. הוכחה: מתאם חלש בין אמירת שקר לרמאות במבחן אצל תלמידים. ⚠️ דוגמה אישית: חבר תמיד נתפס כ'ביישן', אך בפועל ביישן מאוד במסיבות עם זרים ובטוח בעצמו כשמלמד קבוצת סטודנטים.","mnemo":"🎭 תיוג-קבוע מול התנהגות-משתנה"},{"id":"prof12_09","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מה משפיע על ההתנהגות לפי פרדוקס העקיבות - אישיות או מצב?","a":"שילוב שניהם, דרך קשרי \"אם...אז...\" - התנהגות עקבית (\"אם\" מצב X, \"אז\" תגובה Y). הוכח: משתתפים ניבאו במדויק שג'יין ה\"ביישנית\" תהיה חמה פחות עם זרים, יותר עם מכרים - עקביות טמונה בדפוס תלוי-מצב, לא באישיות/מצב לבד.","explain":"שילוב שניהם, דרך קשרי 'אם...אז...' ספציפיים. הוכחה (Kammrath et al.): משתתפים דמיינו סטודנטית ('ג'יין') כידידותית/ביישנית והעריכו חום ב-6 מצבים. נמצא הבדל ניכר לפי המצב - אם ביישנית, ציפו לחום פחות עם זרים מאשר עם מכרים. מסקנה: העקביות האמיתית טמונה בדפוס 'אם מצב X, אז תגובה Y' - שילוב תכונה+מצב, לא אחד לבד.","mnemo":"🔀 \"אם...אז...\" - לא תיוג קבוע"},{"id":"prof12_10","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד אפשר לפתור את פרדוקס העקיבות?","a":"להבין שעקביות אמיתית אינה זהות בכל מצב, אלא דפוס יציב של קשרי \"אם...אז...\" (חתימות אישיות) - כשבודקים התנהגות בהתאמה למצב הספציפי, מתגלה עקביות ברורה, במקום לחפש עקביות מוחלטת/זהה בכל הקשר.","explain":"להבין שהתנהגות עקבית אינה אמורה להיראות זהה בכל המצבים, אלא כדפוס עקבי של קשרי 'אם...אז...' - 'חתימות אישיות' ייחודיות. חוסר העקיבות שנצפה במחקרים המוקדמים נבע מכך שהמדידה חיפשה עקביות מוחלטת (זהה בכל מצב). כשבוחנים התנהגות בהתאמה למצב הספציפי, מתגלה עקביות ברורה ומדידה.","mnemo":"🧩 המצב הספציפי פותר את הפאזל"},{"id":"prof12_11","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"האם תכונות אישיות מולדות או נלמדות? בססו על תורשה, ביולוגיה, אבולוציה ותרבות.","a":"⚠️ סינתזה. תורשה: תאומים מונוזיגוטים דומים יותר מדיזיגוטים (0.52 מול 0.23) - תורשתיות גבוהה. ביולוגיה: מוחצנות מתואמת לפעילות אמיגדלה שונה. אבולוציה: חמשת הגורמים מוסברים כתוצר יחסי גומלין אבולוציוניים. תרבות: מבנה אוניברסלי בשפות שונות, אך ביישנות משתנה מאוד בין תרבויות (יפן גבוה, ישראל נמוך) ונלמדת גם ממשפחה תחרותית/הקנטות. מסקנה: שילוב תורשה+סביבה, כמו ברוב נושאי הקורס.","explain":"ההיגיון מאחורי מחקרי התאומים: מונוזיגוטים ודיזיגוטים חולקים סביבה דומה במידה שווה - ההבדל היחיד ביניהם הוא כמות הגנים המשותפים (100% מול 50%). לכן, אם תכונה מסוימת דומה יותר אצל מונוזיגוטים, ההסבר היחיד לכך שנשאר הוא הגנטיקה - זו הדרך שבה מבודדים את תרומת התורשה מתרומת הסביבה.","mnemo":"🧬🧠🌍🗣️ תורשה+מוח+אבולוציה+תרבות"},{"id":"prof12_12","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו את שלושת הדחפים לפי פרויד: שימור עצמי, ארוס וטנטוס.","a":"שימור עצמי=עונה על צרכים בסיסיים (רעב/צמא). ארוס=דחף מיני/הנאה מהמגע עם הזולת, פועל מלידה, מבוסס על ליבידו. טנטוס (אינסטינקט המוות)=כוח שלילי הדוחף לתוקפנות/הרס, מקום משני בתיאוריה.","explain":"שימור עצמי - דחף לשימור העצמי, עונה על צרכים בסיסיים (רעב, צמא).\nארוס - הכוח המניע הקשור ליצרים מיניים ולשימור המין - כל ניסיון להתענג/לבוא במגע פיזי עם הזולת. פרויד השתמש במונח ליבידו לאנרגיה הדוחפת למצבי עונג חושני. פועל מלידה (עונג תינוקות מגירוי אזורים ארוגניים).\nטנטוס (אינסטינקט המוות) - התווסף בעקבות תצפיות על טראומות מלחמת העולם הראשונה. כוח שלילי הדוחף לתוקפנות/הרס - נטייה לשוב למצב לא-אורגני. מקום משני, שכן ארוס הוא הכוח הראשי.","mnemo":"💧⚡☠️ שימור-עצמי+ארוס+טנטוס"},{"id":"prof12_13","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו קיבעון? דונו בגורמים ובהשלכות.","a":"חוסר יכולת להתקדם לשלב ההתפתחות הבא. גורם: סיפוק-יתר או תסכול-יתר בשלב מוקדם. השלכות: תכונות מבוגרות ספציפיות לכל שלב (אורלי=עישון/פסיביות; אנלי=קמצנות/עקשנות; פאלי=יהירות/פזיזות). מסביר מדוע התנסויות מוקדמות משפיעות מכרעות על האישיות הבוגרת.","explain":"קיבעון (fixation) - חוסר יכולת להתקדם באופן נורמלי לשלב ההתפתחות הבא. גורמים: סיפוק-יתר או תסכול-יתר באחד השלבים המוקדמים. השלכות: תכונות שונות אצל המבוגר לפי שלב הקיבעון - אורלי (גמילה מהנקה)=התנהגות אורלית (עישון, אכילת יתר), פסיביות; אנלי (גמילה מחיתולים)=אהבת סדר/קמצנות/עקשנות; פאלי (תסביך אדיפוס)=יהירות/פזיזות. מסביר מדוע התנסויות מוקדמות משפיעות מכריעות על האישיות הבוגרת.","mnemo":"🔒 תקוע בשלב=קיבעון"},{"id":"prof12_reflection3","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"השוו בין תיאוריית אריקסון לפרויד (תקופה קריטית, גיל השפעה, סוכני חברות, מקום האני, טבע האדם, מקום החברה).","a":"תקופה קריטית: פרויד=ילדות מוקדמת (0-6) בלבד; אריקסון=כל החיים. השפעה: פרויד=קיבעון קובע הכל; אריקסון=כל שלב משפיע על הבא. סוכנים: פרויד=הורים בלבד; אריקסון=משתנים (מטפל→הורים→שווים→זוג→משפחה). אני: פרויד=מתווך בין איד לסופר-אגו; אריקסון=מרכזי ופעיל. טבע אדם: פרויד=פסימי/דחפים; אריקסון=אופטימי/agency. חברה: פרויד=בניגוד לדחפים; אריקסון=הכרחית וחיובית לצמיחה.","explain":"תקופה קריטית: פרויד=ילדות מוקדמת (0-6) בלבד; אריקסון=כל מהלך החיים.\nגיל השפעה על משברים עתידיים: פרויד=קיבעון קובע הכל; אריקסון=כל שלב משפיע על הבא, לאורך החיים.\nסוכני חברות: פרויד=הורים בלבד (הקשר גופני); אריקסון=משתנים לפי שלב (מטפל→הורים→משפחה→שווים→בן/בת זוג→מעגל משפחתי).\nמקום האני: פרויד=מתווך בין סתמי לאני עליון, לא מרכזי; אריקסון=מרכזי ופעיל, פותר משברים.\nטבע האדם: פרויד=פסימי, מונע מדחפים; אריקסון=אופטימי, agency לצמיחה.\nמקום החברה: פרויד=בניגוד לדחפים, מטילה מגבלות; אריקסון=הכרחית וחיובית לצמיחה.","mnemo":"⚔️ פרויד VS אריקסון - טבלת קרב"},{"id":"prof12_14","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו תוכן גלוי ומהו תוכן חבוי? כיצד קשור למודל הטופוגרפי?","a":"תוכן גלוי=מה שאומרים/עושים בפועל, מודע במלואו. תוכן חבוי=מניעים אמיתיים מוסווים/סמליים, לא-מודעים. קשר למודל הטופוגרפי (מודע/טרום-מודע/לא-מודע): גלוי=שייך לרמת המודע; חבוי=מקורו ברמה הלא-מודעת, מגיע לביטוי רק בעקיפין.","explain":"תוכן גלוי (manifest content) - מה שאנו אומרים/עושים/תופסים בפועל, מודע במלואו. תוכן חבוי (latent content) - התוכן הנסתר, המניעים האמיתיים המבקשים ביטוי בצורה מוסווית/סמלית. קשר למודל הטופוגרפי (חלוקת הנפש למודע/טרום-מודע/לא-מודע): התוכן הגלוי שייך לרמת המודע; התוכן החבוי מקורו ברמה הלא-מודעת, ומגיע לביטוי רק בעקיפין (חלומות, פליטות פה, סימפטומים).","mnemo":"🧊 קרחון: גלוי=מעל, חבוי=מתחת"},{"id":"prof12_15","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהן שלוש הדרכים המרכזיות להתחקות אחר הלא-מודע?","a":"(1) סימפטומים נוירוטיים (מבוססי חרדה). (2) חלומות (ניתוח חלומות). (3) פליטות פה וקולמוס (פליטה פרוידיאנית) - דוגמה: כתיבת \"מענה\" בטעות במקום \"מהנה\".","explain":"(1) סימפטומים נוירוטיים (המבוססים על חרדה). (2) חלומות - פרויד ראה בהם מקור מידע חשוב על מניעים לא-מודעים; ניתוח חלומות היא טכניקה טיפולית. (3) פליטות פה וקולמוס (פליטה פרוידיאנית) - כשיצרים לא-מודעים 'מסגירים' עצמם בדיבור/כתיבה. דוגמה: כתיבת 'בילינו סוף שבוע מענה' בטעות במקום 'מהנה'.","mnemo":"3️⃣ סימפטום+חלום+פליטת-פה"},{"id":"prof12_reflection4","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תומר אמר \"החיים קשים\" במקום \"החיים יפים\" - כיצד יסביר פרויד זאת, ואילו הסברים חלופיים מציעה הפסיכולוגיה הקוגניטיבית?","a":"פרויד: פליטה פרוידיאנית - חושפת תוכן חבוי (מצוקה/תסכול לא-מודעים). קוגניטיבית (פרק 7): ⚠️ (1) הפצת הפעלה ברשת סמנטית - \"קשים\"/\"יפים\" מקושרים כהערכות כלליות על החיים, מפעילים זה את זה. (2) כשל בתהליכי איתור שגיאות (עומס/הסחת דעת), ללא תוכן נסתר. (3) נגישות גבוהה יותר של \"קשים\" בזיכרון העבודה מהקשר שיחה קודם.","explain":"הסבר פרוידיאני: פליטה פרוידיאנית - חושפת תוכן חבוי אמיתי (מצוקה/תסכול לא-מודעים שתומר אינו מוכן להודות בהם בגלוי).\n\nהסברים קוגניטיביים (⚠️ סינתזה): (1) הפצת הפעלה ברשת סמנטית - 'קשים'/'יפים' מקושרים כהערכות כלליות על החיים, מפעילים זה את זה (כמו 'קור זלעפות'). (2) כשל בתהליכי איתור שגיאות - עומס קוגניטיבי/הסחת דעת, ללא תוכן נסתר. (3) נגישות גבוהה יותר של 'קשים' בזיכרון העבודה, מהקשר שיחה קודם.","mnemo":"🗣️ \"מענה\" חושף מה שבאמת מציק"},{"id":"prof12_16","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תארו את מבני האישיות (סתמי, אני עליון, אני) והסבירו את תפקידיהם.","a":"סתמי=מאגר דחפים בסיסיים, עקרון העונג, ללא היגיון. אני עליון=ערכים/מצפון נלמד מהחברה, כולל אידיאל האני. אני=מתווך מבוסס מציאות בין השניים, עקרון המציאות - בוחר פעולות המספקות דחפים ללא תוצאות בלתי רצויות.","explain":"הסתמי (id) - מאגר הדחפים הבסיסיים, פועל בחוסר היגיון ובפרצים, שואף לסיפוק מידי. שולט בו עקרון העונג.\nהאני העליון (superego) - מאגר הערכים/עמדות מוסריות שנלמדו מהחברה (מצפון), כולל אידיאל האני. מתפתח בהפנמת איסורי ההורים. נמצא בעימות עם הסתמי.\nהאני (ego) - ההיבט המבוסס על מציאות, מתווך בין דחפי הסתמי לדרישות האני העליון. שולט בו עקרון המציאות - בוחר פעולות המספקות דחפים ללא תוצאות בלתי רצויות.","mnemo":"👹⚖️👼 סתמי-רע | אני-עליון-קדוש | אני-שופט"},{"id":"prof12_17","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"האם טוב להיעזר במנגנוני הגנה, או שהשימוש בהם מעיד על בעיה?","a":"שניהם נכונים, תלוי במידה. שימוש מתון=חיוני, מפחית חרדה, שומר דימוי עצמי חיובי. שימוש יתר=יוצר יותר בעיות מפתרונות, מותיר מעט אנרגיה לחיים פוריים - הישענות מוגזמת קשורה למחלות נפש.","explain":"שניהם נכונים, תלוי במידה. שימוש מתון - חיוני להתמודדות פסיכולוגית, מפחית חרדה ושומר על דימוי עצמי חיובי. שימוש יתר - יוצר יותר בעיות מפתרונות, מותיר מעט אנרגיה לחיים פוריים וליחסי אנוש - הישענות מוגזמת קשורה למחלות נפש. אין תשובה חד-משמעית - שימוש מאוזן חיוני, שימוש כרוני/מוגזם מעיד על בעיה.","mnemo":"⚖️ מעט=טוב | הרבה=בעיה"},{"id":"prof12_18_1","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו מנגנון ההגנה: הכחשת המציאות?","a":"סירוב לקלוט מציאות לא-נעימה, כאילו אינה קיימת.","explain":"לפי פרויד, מנגנוני-הגנה הם אסטרטגיות לא-מודעות של האני (Ego) להתמודד עם חרדה הנובעת מקונפליקט בין דחפי הסתמי (Id) לדרישות המציאות/המצפון. <b>הכחשה</b> היא המנגנון הפרימיטיבי ביותר: האדם פשוט מסרב לקלוט מציאות כואבת מדי, <b>כאילו היא לא קיימת כלל</b> - לא מדובר בשקר מודע, אלא בחסימה אמיתית של המידע מלהיכנס לתודעה. <b>הדוגמה</b>: אדם שקיבל אבחנה רפואית קשה עשוי, בימים הראשונים, להכחיש לגמרי את חומרת המצב - זו לא הכחשה קבועה, אלא מנגנון-הגנה זמני שנותן לנפש 'זמן התארגנות' לפני שהיא יכולה להתמודד עם המידע המכאיב. ⚠️ שימו לב שהכחשה שונה מהדחקה: הכחשה חוסמת מציאות <b>חיצונית</b> (עובדה בעולם), הדחקה חוסמת דחף/זיכרון <b>פנימי</b>.","mnemo":"🙈 סירוב לראות - \"זה לא קורה\""},{"id":"prof12_18_2","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו מנגנון ההגנה: התקה?","a":"פריקת רגש עצור (לרוב עוינות) על אובייקט בטוח יותר מזה שעורר אותו.","explain":"<b>התקה (Displacement)</b> - פריקת רגש עצור (לרוב עוינות/כעס) על אובייקט <b>בטוח יותר</b> מזה שבאמת עורר את הרגש, כי מול המקור האמיתי הביטוי אסור/מסוכן מדי (למשל, כעס על הבוס עלול לעלות במשרה). <b>הדוגמה</b>: אדם שכועס על בני-המשפחה שלו (אבל לא מרגיש שמותר לו לצעוק עליהם) יוצא במקום זה לריצה אינטנסיבית - הריצה 'סופגת' את האנרגיה הרגשית שבאמת מכוונת למשפחה. ⚠️ ההבדל מ<b>השלכה</b>: בהתקה, האדם עדיין מכיר ברגש שלו-עצמו (הוא יודע שהוא כועס) אבל מפנה אותו למטרה אחרת; בהשלכה, האדם מייחס את הרגש/הדחף <b>לאדם אחר לגמרי</b> ומכחיש שהוא שלו.","mnemo":"🥊 מכה את הכרית, לא את הבוס"},{"id":"prof12_18_3","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו מנגנון ההגנה: פנטזיה?","a":"סיפוק תשוקות שלא מומשו בהישגים דמיוניים.","explain":"<b>פנטזיה</b> - סיפוק תשוקות שלא מומשו במציאות באמצעות הישגים דמיוניים - האדם 'חי' בדמיונו הצלחה שלא הגיע אליה בפועל, וכך מפחית את החרדה/התסכול מכישלון או מגבלה אמיתיים. <b>הדוגמה</b>: אדם המדמיין הצלחה עתידית (למשל, לדמיין את עצמו מקבל קידום גדול) כדי לשמר מוטיבציה ולהתמודד עם קושי בהווה. ⚠️ חשוב: זו לא בהכרח פתולוגיה - פנטזיה מתונה יכולה להיות מנגנון-הגנה בריא ומועיל (מניע להתמדה), בעוד הסתמכות-יתר עליה במקום פעולה בעולם האמיתי עלולה להפוך לבעייתית.","mnemo":"💭 חלום-בהקיץ מפצה על מציאות"},{"id":"prof12_18_4","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו מנגנון ההגנה: הזדהות?","a":"הגדלת תחושת הערך העצמי דרך הזדהות עם אדם/מוסד בעל מעמד רם.","explain":"<b>הזדהות (Identification)</b> - הגדלת תחושת-הערך העצמי דרך זיהוי עצמי עם אדם או מוסד בעל מעמד/יוקרה גבוהים - האדם 'שואל' חלק מהערך של הדמות המוערכת ומרגיש טוב יותר עם עצמו כתוצאה מהקשר. <b>הדוגמה</b>: סטודנט המזדהה חזק עם מנחה-מחקר מוערך ומצליח - תחושת השייכות למישהו מצליח מעלה את ההערכה-העצמית שלו. ⚠️ הזדהות שונה משאיפה/חיקוי רגילים: כאן מדובר במנגנון <b>לא-מודע</b> שמטרתו הגנה על הדימוי-העצמי (במיוחד כשהאדם עצמו מרגיש חוסר-ביטחון), לא רק למידה מכוונת מדמות-מופת.","mnemo":"⭐ \"אני כמוהו\" - שואב כבוד מהאחר"},{"id":"prof12_18_5","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו מנגנון ההגנה: בידוד?","a":"ניתוק מטען רגשי ממצב מכאיב, או הפרדת עמדות סותרות זו מזו.","explain":"<b>בידוד (Isolation)</b> - ניתוק המטען הרגשי ממצב מכאיב, כך שהעובדות נשארות מודעות אבל הרגש שהיה אמור להתלוות אליהן נחסם - או לחלופין, הפרדת שתי עמדות/אמונות סותרות זו מזו כדי לא להתמודד עם הסתירה ביניהן. <b>הדוגמה</b>: מנתח (כירורג) שמרחיק את עצמו רגשית מסבל המטופלים כדי לתפקד מקצועית ולבצע פעולות רפואיות קשות - הוא יודע קוגניטיבית שיש כאב וסבל, אך 'מנתק' את התגובה הרגשית הטבעית שהייתה מונעת ממנו לתפקד. ⚠️ זהו בדיוק המנגנון המסביר גם את התופעה של 'בידוד' (isolation) בהקשר OCD - הרעיון הטורדני נשאר, אבל הרגש/הכוונה שמאחוריו מנותקים ממנו במודע.","mnemo":"🧊 מקפיא את הרגש, לא נוגע בו"},{"id":"prof12_18_6","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו מנגנון ההגנה: השלכה?","a":"האשמת אחרים בקשיים, או ייחוס תשוקות \"אסורות\" לאחרים.","explain":"<b>השלכה (Projection)</b> - ייחוס דחפים/תכונות/רגשות <b>אסורים או לא-מקובלים</b> משל האדם עצמו <b>לאנשים אחרים</b>, במקום להכיר בהם כשייכים לו - כך האדם 'נפטר' מהאשמה או מהחרדה שהתכונה הזו מעוררת אצלו. <b>הדוגמה</b>: אדם שחושד באופן קבוע שכולם משקרים לו - ייתכן שהוא-עצמו נוטה לשקר, אך במקום להתמודד עם התכונה הזו אצל עצמו, הוא 'משליך' אותה החוצה ורואה אותה אצל כולם מלבדו. ⚠️ ההבדל מהתקה: בהשלכה האדם לא רק מפנה את הרגש למישהו אחר - הוא <b>מכחיש שהרגש שייך לו בכלל</b> ומייחס אותו לחלוטין לצד השני.","mnemo":"👉 \"זה אתה, לא אני\""},{"id":"prof12_18_7","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו מנגנון ההגנה: רציונליזציה?","a":"ניסיון להוכיח שההתנהגות הגיונית ומוצדקת.","explain":"<b>רציונליזציה (Rationalization)</b> - ניסיון להוכיח, בטיעונים הגיוניים-לכאורה, שהתנהגות או תוצאה בלתי-נעימה היו בעצם הגיוניות ומוצדקות - כך נמנעים מלהכיר בכישלון, אכזבה או דחף לא-מקובל. <b>הדוגמה</b>: אדם שנדחה ממשרה אומר לעצמו 'המשרה הזו לא הייתה מתאימה לי בכלל' - הסבר שנשמע הגיוני, אך מטרתו האמיתית היא להגן על ההערכה-העצמית מפני כאב הדחייה, לא לשקף ניתוח אובייקטיבי. ⚠️ רציונליזציה שכיחה מאוד כי היא 'משכנעת' - האדם עצמו מאמין בהסבר שהוא ממציא, ולכן היא קשה לזיהוי-עצמי.","mnemo":"🍇 \"הענבים חמוצים\" (איזופוס)"},{"id":"prof12_18_8","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו מנגנון ההגנה: היפוך תגובה?","a":"אימוץ עמדה והתנהגות הפוכה מהתשוקה המסוכנת, כ\"מחסום\".","explain":"<b>היפוך תגובה (Reaction Formation)</b> - אימוץ עמדה והתנהגות <b>הפוכות בדיוק</b> מהתשוקה האמיתית שנתפסת כמסוכנת/אסורה, כדי ליצור 'מחסום' מפניה - ככל שהדחף האסור חזק יותר, כך ההתנהגות ההפוכה עלולה להיראות מוגזמת/קיצונית. <b>הדוגמה</b>: מטפל המרגיש שנאה עמוקה כלפי מטופל מסוים, אך מתוך זה מתנהג כלפיו באדיבות מוגזמת וחריגה - האדיבות-הקיצונית היא בדיוק המחסום מפני השנאה האמיתית שהוא לא יכול להרשות לעצמו להכיר בה. ⚠️ סימן-ההיכר לזיהוי היפוך-תגובה: העוצמה/הקיצוניות של ההתנהגות החיובית חורגת ממה שהמצב באמת דורש - 'יותר מדי טוב מכדי להיות אמיתי'.","mnemo":"🔄 שונא בפנים, מחבק בחוץ"},{"id":"prof12_18_9","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו מנגנון ההגנה: תסוגה?","a":"נסיגה לרמת התפתחות מוקדמת יותר, עם תגובות ילדותיות.","explain":"<b>תסוגה/רגרסיה (Regression)</b> - נסיגה זמנית להתנהגויות ולתגובות אופייניות לשלב-התפתחות מוקדם יותר, פחות-בוגר, כדרך להתמודד עם מצב-לחץ בהווה. <b>הדוגמה</b>: מבוגר שחווה יום מלחיץ מאוד וצופה בתוכנית-ילדות מנחמת, מבקש נחמה בדרך 'ילדותית' במקום להתמודד ישירות עם מקור-הלחץ. ⚠️ שימו לב להבדל מהותי מ<b>קיבעון</b> (fixation): קיבעון הוא הישארות <b>קבועה</b> בשלב מוקדם שהתעוררה בזמן ההתפתחות עצמה, בעוד תסוגה היא חזרה <b>זמנית</b> לשלב קודם כתגובה נקודתית למצוקה בהווה - שני מושגים שנוטים להתבלבל בבחינה.","mnemo":"🍼 חוזר להתנהג כמו ילד קטן"},{"id":"prof12_18_10","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו מנגנון ההגנה: הדחקה?","a":"דחיקת מחשבות מכאיבות/מסוכנות מהתודעה - מנגנון ההגנה הבסיסי ביותר.","explain":"<b>הדחקה (Repression)</b> - נחשבת ל<b>מנגנון ההגנה הבסיסי והחשוב ביותר</b> אצל פרויד: דחיקה לא-מודעת של מחשבות, זיכרונות או דחפים מכאיבים/מסוכנים מדי מחוץ לתודעה, כך שהאדם כלל לא-מודע לקיומם. <b>הדוגמה</b>: אדם החווה תאונה קשה עשוי 'לשכוח' זמנית פרטים טראומטיים מהאירוע, עד שהוא מוכן נפשית (למשל בעזרת טיפול מקצועי) להתמודד עמם. ⚠️ הדחקה שונה מהכחשה: בהכחשה, המידע נמצא <b>בעולם החיצון</b> והאדם מסרב לקלוט אותו; בהדחקה, המידע הוא <b>פנימי</b> (זיכרון/דחף/רגש) שכבר נחווה, אך נדחק מתחת לסף המודעות. פרויד ראה בהדחקה את הבסיס לכל שאר מנגנוני-ההגנה - הם 'עוזרים' להדחקה להישאר יעילה.","mnemo":"🔒 נועל את הכאב בארון-נעול"},{"id":"prof12_18_11","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו מנגנון ההגנה: עידון?","a":"סיפוק תשוקות מיניות/תוקפניות דרך פעולות חלופיות מקובלות חברתית.","explain":"<b>עידון (Sublimation)</b> - נחשב למנגנון-ההגנה ה<b>בוגר והבריא ביותר</b>: סיפוק תשוקות מיניות או תוקפניות <b>לא באמצעות</b> ביטוין הישיר (שאסור/לא-מקובל חברתית), אלא דרך ערוצי-פעולה חלופיים המקובלים ומוערכים חברתית. <b>הדוגמה</b>: אדם עם אנרגיה תוקפנית רבה מנתב אותה לספורט תחרותי (למשל אגרוף או כדורגל) - הדחף התוקפני מתפרק ומקבל פורקן, אך בצורה בונה ומוערכת חברתית, במקום אלימות ממשית. ⚠️ ההבדל המרכזי מרציונליזציה או היפוך-תגובה: בעידון, הדחף <b>אכן מסופק בפועל</b> (רק בערוץ חלופי), ולא רק 'מוסבר' או 'מוסווה' - זו הסיבה שפרויד ראה בעידון בסיס לחלק גדול מהיצירתיות והתרבות האנושית.","mnemo":"🎨 מפנה תוקפנות ליצירה/ספורט"},{"id":"prof12_reflection5","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"זהו את המאבק ומנגנון ההגנה בשני המקרים (דוד/התינוקת; נטע-לי/השיעור).","a":"דוד=סתמי (קנאה) מול אני עליון - מנגנון: היפוך תגובה (חיבוק חזק מדי מסווה עוינות). נטע-לי=סתמי (רצון לישון/הימנעות משיעור) מול אני עליון (אחריות) - מנגנון: רציונליזציה (מאשימה שעונים גרועים במקום לקבל אחריות).","explain":"א. דוד (בן 4) מחבק את התינוקת בחוזקה רבה: מאבק בין הסתמי (עוינות/קנאה טבעית כלפי המתחרה על תשומת לב ההורים) לאני העליון (אסור לשנוא אחות). מנגנון: היפוך תגובה - הדחף האמיתי (עוינות) הופך להיפוכו: חיבוק חזק במיוחד, המבטא אהבה מוגזמת.\n\nב. נטע-לי מסבירה איחור בכך ש'השעונים גרועים': מאבק בין הסתמי (רצון להישאר עם חברים, להימנע ממרצה קשוח) לאני העליון (אחריות להגיע לשיעור חובה). מנגנון: רציונליזציה - ייחוס הכישלון לגורם חיצוני 'הגיוני' לכאורה, במקום קבלת אחריות אישית.","mnemo":"🥊 מציאת המאבק+המנגנון בשני סיפורים"},{"id":"prof12_reflection6","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"דונו ביתרונות/תמיכה ובביקורות על תיאוריית פרויד (היקף, אופרציונליזציה, ניבוי, תמיכה מחקרית, פנטזיה/מציאות, יחס לנשים).","a":"היקף=מקיפה ומרתקת ביותר, אך: אופרציונליזציה=מושגים מעורפלים לא ניתנים להפרכה. ניבוי=\"היסטוריה טובה מדע גרוע\" - בדיעבד לא מראש. תמיכה מחקרית=תומכת ברעיון הלא-מודע (מחקר הבנות/מנגנוני הגנה) אך לא בקשר לפסיכופתולוגיה; לא כללה מחקרי ילדים. פנטזיה/מציאות=ממזערת טראומות אמיתיות כפנטזיה. נשים=הטיה אנדרוצנטרית (הורניי הציעה \"קנאת רחם\" כתיקון).","explain":"היקף ומורכבות: מקיפה ומרתקת ביותר, מכסה כמעט כל היבט של החוויה האנושית.\nאופרציונליזציה: ביקורת - מושגים מעורפלים (ליבידו, סתמי) לא ניתנים להגדרה אופרציונלית/הפרכה.\nיכולת ניבוי: ביקורת - 'היסטוריה טובה אך מדע גרוע', מיושמת בדיעבד, לא מנבאת מראש.\nתמיכה מחקרית: תומכת ברעיון הכללי של הלא-מודע (מחקר בנות דחויות ומנגנוני הגנה), אך מחלישה את הקשר הספציפי לפסיכופתולוגיה; מעולם לא כללה מחקרי ילדים בפועל.\nפנטזיה מול מציאות: ביקורת חמורה - ממזערת טראומות אמיתיות (התעללות) בפירושן כפנטזיות.\nיחס לנשים: ביקורת - הטיה אנדרוצנטרית (זכר במרכז); הורניי הציעה 'קנאת רחם' כתיקון.","mnemo":"⚖️ יתרונות מול חסרונות פרויד"},{"id":"prof12_19","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"אילו שינויים מרכזיים ערכו הפוסט-פרוידיאנים בתיאוריית פרויד?","a":"(1) הדגישו תפקודי האני (הגנות, התפתחות עצמי, שליטה עצמית) יותר מהסתמי. (2) ייחסו תפקיד גדול יותר למשתנים חברתיים (תרבות/משפחה/שווים). (3) הפחיתו חשיבות לליבידו/דחפים מיניים. (4) הרחיבו התפתחות אישיות לכל משך החיים, לא רק ילדות.","explain":"(1) הדגישו במיוחד את תפקודי האני - הגנות, התפתחות העצמי, חשיבה מודעת, שליטה עצמית. (2) ייחסו תפקיד גדול יותר למשתנים חברתיים - תרבות, משפחה, קבוצת שווים. (3) ייחסו חשיבות פחותה לדחפים מיניים כלליים ולליבידו. (4) הרחיבו את תקופת התפתחות האישיות - מהילדות בלבד לכל משך חיי האדם.","mnemo":"🔧 4 תיקונים פוסט-פרוידיאניים"},{"id":"prof12_20","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"במה שונה תיאוריית אדלר מפרויד?","a":"דחה חשיבות ארוס/עקרון העונג. טען שכל בני האדם חווים רגשי נחיתות ומפצים (לעיתים יתר) בחיפוש עליונות/ערך עצמי - סגנון חיים. קונפליקט=אי-הלימה בין לחצי סביבה לחתירה פנימית לערך, לא תחרות דחפים פנימיים.","explain":"אלפרד אדלר דחה את החשיבות שפרויד ייחס לארוס ולעקרון העונג. סבר שכל בני האדם חווים רגשי נחיתות (כילדים חסרי ישע), ומפצים על כך (לעיתים פיצוי יתר) בחיפוש דרכים להשיג עליונות/ערך עצמי - מפתחים סגנון חיים. קונפליקט נובע מאי-הלימה בין לחצי הסביבה החיצונית לחתירה הפנימית להיות בעל ערך - לא מתחרות דחפים פנימיים.","mnemo":"💪 אדלר: נחיתות→חתירה לעליונות"},{"id":"prof12_21","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"במה שונה תיאוריית קרן הורניי מפרויד?","a":"קראה תיגר על \"קנאת הפין\", הציעה במקום \"קנאת רחם\" (קנאת גברים באימהות/הנקה). הדגישה יותר גורמים תרבותיים ומבנה אופי בהווה, פחות מיניות אינפנטילית. השפיעה על תיאוריות הומניסטיות.","explain":"קראה תיגר על החשיבות שייחס פרויד לפין (קנאת הפין), והציעה במקום 'קנאת רחם' - קנאת הזכר בהיריון, באימהות ובהנקה, המביאה גברים להמעיט בערך נשים ולפצות באמצעות דחף לא-מודע לעבודה יצירתית. הדגישה יותר גורמים תרבותיים ומבנה אופי בהווה, פחות מיניות אינפנטילית. השפיעה על התפתחות תיאוריות הומניסטיות מאוחרות.","mnemo":"🤰 הורניי: קנאת-רחם, לא קנאת-פין"},{"id":"prof12_22","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"במה שונה תיאוריית יונג מפרויד?","a":"הרחיב הלא-מודע לכלול לא-מודע קולקטיבי (ארכיטיפים אוניברסליים: אנימוס/אנימה/מנדלה). פסיכולוגיה אנליטית: איזון כוחות מנוגדים. דחה חשיבות הליבידו, החליף בשני אינסטינקטים: צורך ליצור וצורך להיות שלם/קוהרנטי.","explain":"קרל יונג הרחיב את מושג הלא-מודע לכלול לא-מודע קולקטיבי - אמיתויות פסיכולוגיות משותפות לכל המין האנושי, מוסברות דרך ארכיטיפים (ייצוגים סמליים אוניברסליים: אנימוס=ארכיטיפ גברי, אנימה=ארכיטיפ נשי, מנדלה=ארכיטיפ העצמי/שלמות). פסיכולוגיה אנליטית: איזון בין כוחות מנוגדים. דחה את חשיבות הליבידו, הוסיף שני אינסטינקטים לא-מודעים: הצורך ליצור והצורך להיות אדם לכיד ושלם.","mnemo":"🌀 יונג: לא-מודע קולקטיבי+ארכיטיפים"},{"id":"prof12_23","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו מימוש עצמי ומה תפקידו בתיאוריות ההומניסטיות?","a":"שאיפה תמידית להגשמת הפוטנציאל הטבוע באדם, מיצוי יכולות/כישרונות. תפקידו: המאפיין המרכזי של כל התיאוריות ההומניסטיות - כוח בונה ומנחה, מוטיבציה מולדת+נלמדת לצמיחה חיובית (בראש מדרג צרכי מסלו). לעיתים בקונפליקט עם הצורך באישור חברתי.","explain":"שאיפה תמידית להגשמת הפוטנציאל הטבוע באדם, למיצוי יכולותיו וכישרונותיו. תפקידו: המאפיין העיקרי של כל התיאוריות ההומניסטיות - כוח בונה ומנחה, מוטיבציה מולדת ונלמדת כאחד לצמיחה חיובית. מאסלו הציב אותו בראש מדרג הצרכים. לעיתים בקונפליקט עם הצורך באישור של העצמי והזולת.","mnemo":"🌱 מימוש-עצמי=לב ההומניזם"},{"id":"prof12_24","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהם התנאים להשגת מימוש עצמי לפי קארל רוג'רס?","a":"הערכה חיובית בלתי מותנית - בילדות: הורים אוהבים תמיד, שוללים התנהגות לא הידיעה (לא את הילד עצמו). בבגרות: להעניק ולקבל הערכה בלתי מותנית מאחרים, והכי חשוב - הערכה עצמית בלתי מותנית (לקבל את עצמך למרות חולשות).","explain":"הערכה חיובית בלתי מותנית. בילדות: ילדים צריכים להרגיש שהוריהם יאהבו אותם תמיד ויקבלו אותם על אף שגיאות - לא צריכים 'להרוויח' את אהבת ההורים; ההורים צריכים לשלול את ההתנהגות, לא את הילד עצמו. בבגרות: (1) להעניק הערכה בלתי מותנית לאנשים קרובים. (2) לקבל הערכה כזאת מהם. (3) והכי חשוב - הערכה עצמית בלתי מותנית - לקבל את עצמכם על אף החולשות.","mnemo":"❤️‍🩹 הערכה בלתי-מותנית=אהבה בלי תנאים"},{"id":"prof12_25","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו הוליסטיות, נטייתיות ופנומנולוגיות בתיאוריות הומניסטיות.","a":"הוליסטיות=מסבירות פעולות דרך האישיות בכללותה, לא תכונות נפרדות. נטייתיות=מאפיינים מולדים משפיעים מכריעות, גורמי מצב=מגבלות; נטייה משתנה בכל ביטוי (לא קבועה כמו תכונה). פנומנולוגיות=מדגישות נקודת מבט סובייקטיבית, מתמקדות בהווה (לא בעבר לא-מודע).","explain":"הוליסטיות - מסבירות פעולות באמצעות האישיות בכללותה, לא תכונות נפרדות (למשל, מסלו: בני אדם מיסודם מונעים כלפי הרמות הגבוהות במדרג).\nנטייתיות - מתמקדות במאפיינים מולדים, המשפיעים מכריעות; גורמי מצב נתפסים כמגבלות/מחסומים. נטיות אינן תמות חוזרות (כמו תכונות) - הן מכוונות ליצירתיות וצמיחה, משתנות בכל ביטוי.\nפנומנולוגיות - מדגישות את מסגרת ההתייחסות הסובייקטיבית של הפרט, לא נקודת מבט חיצונית. מתמקדות בהווה - חוויות עבר חשובות רק במידה שהביאו למצב הנוכחי.","mnemo":"🌐📌👁️ שלם+מולד+סובייקטיבי"},{"id":"prof12_26","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע תיאוריית הורניי מייצגת את הגישה ההומניסטית?","a":"הוליסטיות: \"עצמי אמיתי\" שלם השואף למימוש. נטייתיות: תנאים מולדים/סביבתיים (חום, אהבה) הכרחיים למימוש; היעדרם=חרדה בסיסית. פנומנולוגיות: מתמקדת בחוויה הסובייקטיבית (עצמי אמיתי מול דימוי אידיאלי, התמודדות פנימית עם חרדה).","explain":"הוליסטיות: הגיעה למסקנה שלבני אדם 'עצמי אמיתי' שלם, הדורש תנאי סביבה חיוביים למימוש.\nנטייתיות: הדגישה תנאים מולדים/סביבתיים (חום, אהבה הורית) הכרחיים למימוש - בהיעדרם מתפתחת חרדה בסיסית.\nפנומנולוגיות: מתמקדת בחוויה הסובייקטיבית - איך האדם תופס עצמו (עצמי אמיתי מול דימוי אידיאלי), והתמודדות פנימית עם חרדה.","mnemo":"🎯 הורניי=דוגמה מושלמת ל-3 המאפיינים"},{"id":"prof12_reflection7","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"נתחו את מקרה יאיר (תחושת קושי וייאוש למרות הצלחה חיצונית) מנקודת מבט הומניסטית.","a":"⚠️ ניתוח מומחש. הצלחות חיצוניות (משפחה, קריירה) אינן מבטיחות מימוש עצמי אמיתי. רוג'רס: אולי חי לפי תנאי הערכה שהוטלו עליו (לא הערכה עצמית בלתי מותנית) - לא חי לפי עצמיו האמיתי. הורניי: \"רודנות ההכרח\" - חובות שהשית על עצמו במקום ביטוי עצמי. מאסלו: צרכי חסר מסופקים, אך צורך הגדילה (מימוש עצמי) עדיין לא ממומש - מסביר את התסכול למרות ה\"הצלחה\".","explain":"⚠️ ניתוח מומחש. הצלחות חיצוניות (משפחה, קריירה) אינן מבטיחות מימוש עצמי אמיתי - זו שאיפה פנימית, לא רשימת הישגים חברתיים.\n\nרוג'רס: ייתכן שיאיר חי לפי 'תנאי הערכה' שהוטלו עליו (ציפיות משפחה/חברה), לא לפי חתירתו האמיתית - אם קיבל בילדותו הערכה חיובית מותנית בלבד, לא פיתח הערכה עצמית בלתי מותנית, ואינו חי לפי עצמיו האמיתי.\n\nהורניי: ייתכן שיאיר נשלט על ידי 'רודנות ההכרח' - חובות שהשית על עצמו ('אני מוכרח להיות מנהל מוצלח') במקום ביטוי אמיתי של עצמיותו.\n\nמאסלו: צרכי החסר שלו (ביולוגי, ביטחון, היקשרות, הערכה) מסופקים לכאורה, אך המימוש העצמי (צורך גדילה) עדיין לא ממומש - צרכי גדילה 'דורשים' יותר ככל שמתקדמים, ואי-סיפוקם גורם לתחושת ריקנות.","mnemo":"😔 יאיר מצליח אך ריק - חי לפי ציפיות-אחרים"},{"id":"prof12_27","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"סכמו את הביקורות על התיאוריה ההומניסטית (תוקף מדעי, תהליכים כלליים, משתני סביבה, כלי חקירה).","a":"תוקף מדעי=מושגים מעורפלים, לא ניתנים לחקר מדעי מדויק (מהו מימוש עצמי? מולד/נלמד?). תהליכים כלליים=מתמקדות בטבע האדם המשותף לכולם, לא בהבדלים/ייחודיות הפרט. משתני סביבה=מוזנחים, בגלל ההדגשה על העצמי כמקור פעולה. כלי חקירה=פסיכוביוגרפיה/נרטיבים/סיפורי חיים - תרומה מתודולוגית, גם אם מוגבלת מדעית.","explain":"תוקף מדעי: מושגים מעורפלים (מהו בדיוק מימוש עצמי? מולד או נלמד?), כמעט אין אפשרות לחקור באופן מדעי.\nתהליכים כלליים: מתמקדות בטבע האדם המשותף לכולם, לא במאפיינים הייחודיים או בשורשי ההבדלים בין בני אדם.\nמשתני סביבה: מוזנחים - ההדגשה על העצמי כמקור התנסות/פעולה מזניחה משתנים סביבתיים חשובים.\nכלי חקירה: פסיכוביוגרפיה - שימוש שיטתי בתיאוריה כדי להפוך חיי אדם לסיפור לכיד (כמו שפרויד עשה עם דה וינצ'י) - כלי בעל ערך גם אם מוגבל מדעית-כמותית.","mnemo":"🔬❓🌍 לא-מדעי+כללי-מדי+מזניח-סביבה"},{"id":"prof12_28","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"על איזו ביקורת עונות תיאוריות הלמידה החברתית/הקוגניטיביות?","a":"הביקורת: תיאוריות קודמות (פסיכודינמיות/הומניסטיות/תכונות) מתארות מכלול אישיות אך לא מנבאות התנהגויות ספציפיות. תיאוריות הלמידה עונות: מתמקדות ישירות בהבדלי התנהגות ובנסיבות סביבתיות ספציפיות (חיזוקים) - קשר ישיר בין סביבה להתנהגות.","explain":"הביקורת: תיאוריות קודמות (פסיכודינמיות, הומניסטיות, תכונות) מדגישות מנגנונים פנימיים משוערים אך חסר בהן קשר ברור בין אישיות להתנהגויות ספציפיות - מתארות מכלול, לא מנבאות פעולה מסוימת. תיאוריות הלמידה החברתית/הקוגניטיביות עונות: מתמקדות ישירות בהבדלי התנהגות בין בני אדם ובנסיבות הסביבתיות (חיזוקים) השולטות בהתנהגות - קשר ישיר וניתן לניבוי בין משתני סביבה ספציפיים להתנהגות ספציפית.","mnemo":"🎯 למידה חברתית עונה: מנבאת התנהגות ספציפית"},{"id":"prof12_29","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד מסבירים דולרד ומילר את ההתנהגות (מונחי פרק 5)?","a":"דחפים נלמדים, עיכוב תגובות, הרגלים נלמדים. התנהגות המפחיתה מתח (מדחף לא-מסופק) חוזרת ונשנית והופכת להרגל נלמד, מקבל חיזוק חוזר (עקרון חיזוק/התניה אופרנטית). גם חיקוי חברתי - למידה מצפייה באחרים ללא ביצוע ישיר. אישיות=סך ההרגלים הנלמדים.","explain":"טבעו מושגים כמו דחפים נלמדים, עיכוב תגובות ודפוסי הרגלים נלמדים. עקרון הפחתת מתח (במונחים ביהביוריסטיים): אורגניזמים פועלים להפחית מתח שיוצרים דחפים לא-מסופקים. התנהגות המצליחה להפחית מתח חוזרת ונשנית והופכת להרגל נלמד, מקבלת שוב ושוב חיזוק (כמו בהתניה אופרנטית). הראו גם למידה בדרך חיקוי חברתי - מצפייה בהתנהגות אחרים, בלא צורך לבצע את התגובה בעצמם. אישיות=סך כל ההרגלים הנלמדים.","mnemo":"🎯 חיזוק=הפחתת-מתח→הרגל"},{"id":"prof12_30","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"במה שונה תיאוריית הפחתת המתח של דולרד/מילר מזו של פרויד?","a":"פרויד: מתח מדחפים אינסטינקטיביים/מולדים (ליבידו), פועל לא-מודעות, קשור למבנה נפשי מורכב (סתמי/אני/אני עליון) לא ניתן לאופרציונליזציה. דולרד/מילר: מתח מדחפים נלמדים, הפחתתו=חיזוק ביהביוריסטי רגיל - ניתן לבדיקה אמפירית, ללא הנחת מבנים נפשיים לא-מודעים.","explain":"פרויד: מתח נובע מדחפים אינסטינקטיביים ומולדים (ליבידו, ארוס, טנטוס), פועלים ברמה לא-מודעת ובלתי-נגישה לתצפית ישירה - קשור למבנה נפשי מורכב (סתמי/אני/אני עליון) שאינו ניתן לאופרציונליזציה.\nדולרד ומילר: מתח נובע מדחפים נלמדים (לא בהכרח מולדים/מיניים), והפחתתו מתפקדת פשוט כחיזוק במובן הביהביוריסטי הרגיל - ללא צורך בהנחת מבנים נפשיים לא-מודעים. ההסבר שלהם נשען על עקרונות למידה נצפים וניתנים לבדיקה אמפירית.","mnemo":"⚡ פרויד=מולד-לא-מודע | דולרד=נלמד-אופרנטי"},{"id":"prof12_31","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"אילו משתנים קובעים התנהגות לפי מישל?","a":"קידודים (סיווג מידע). ציפיות ואמונות (על עולם חברתי/יכולת). רגשות (כולל פיזיולוגיים). מטרות וערכים (תכניות חיים). יכולות ותכניות לוויסות עצמי (התנהגויות אפשריות).","explain":"חמישה משתנים אישיים:\nקידודים - הדרך שבה מסווגים מידע על עצמנו/אחרים/מצבים.\nציפיות ואמונות - לגבי העולם החברתי, תוצאות פעולות, יכולתנו להביא לתוצאות.\nרגשות - כולל תגובות פיזיולוגיות.\nמטרות וערכים - תוצאות/מצבים רגשיים שאנו מעריכים, תכניות חיים.\nיכולות ותכניות לוויסות עצמי - התנהגויות שאנו מסוגלים לבצע, תכניות להפקת תוצאות.","mnemo":"5️⃣ קידוד+ציפייה+רגש+מטרה+יכולת"},{"id":"prof12_32","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"האם לפי מישל אדם מתנהג תמיד באותו האופן?","a":"לא. התנהגות נובעת מאינטראקציה בין אדם למצב. דוגמה: ג'ון ידידותי בהיכרות ראשונה אך לא לאחר מכן; ג'ים ההפך. ממוצע ההתנהגות זהה, אך מחמיץ הבדלים תלויי-מצב חשובים.","explain":"לא. התנהגות נובעת מאינטראקציה בין אנשים למצבים, לא רק מהאישיות ה'קבועה'. דוגמה: ג'ון ידידותי מאוד בהיכרות ראשונה, נעשה גס רוח לאחר שהות ממושכת; ג'ים ביישן עם זרים, נעשה חברותי לאחר שההיכרות מעמיקה. חישוב ממוצע הידידותיות של שניהם ייתן ערכים שווים - יחמיץ הבדלים תלויי-מצב חשובים. מחקר מחנה קיץ: ילדים 'ידידותיים' צייתו כשמבוגר התרה בהם; 'עצורים' צייתו כשקבוצת שווים העמידה אותם במבחן.","mnemo":"🎭 ג'ון-חברותי-בהתחלה | ג'ים-הפוך - ממוצע מטעה"},{"id":"prof12_33","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע ישאל מישל \"באילו נסיבות\" אפרת נחמדה?","a":"תיוג כללי (\"נחמדה\") מסתיר מידע חיוני - התנהגות תלויה במצב, לא קבועה. מישל מחפש דפוס \"אם...אז...\" ספציפי (באילו מצבים היא נחמדה, ובאילו לא) - זה המידע האמיתי על אישיותה, לא תווית גורפת.","explain":"לפי מישל, דעותינו על אישיות אינן נובעות מהתנהגות ממוצעת, אלא מהתחקות אחר האופן שבו מצבים שונים מביאים להתנהגויות שונות. התיוג הכללי 'אפרת נחמדה' מסתיר מידע חשוב - ייתכן שנחמדה רק במצבים מסוימים (עם חברים קרובים), אך מתנהגת אחרת במצבים אחרים (תחת לחץ, מול זרים) - כמו ג'ון וג'ים. מישל ישאל 'באילו נסיבות' כי מחפש את דפוס ה'אם...אז...' הספציפי שלה - זהו המידע האמיתי והשימושי, לא תווית קבועה.","mnemo":"❓ \"באילו נסיבות\" לא \"כמה נחמדה\""},{"id":"prof12_reflection8","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע התיאוריה הקוגניטיבית-רגשית של מישל היא תיאוריית אישיות?","a":"⚠️ סינתזה. דפוס \"אם...אז...\" עצמו יציב ועקבי לכל אדם לאורך זמן - \"חתימת אישיות\" ייחודית (גם אם ההתנהגות הגלויה משתנה לפי מצב). 5 המשתנים האישיים (קידודים, ציפיות, רגשות, מטרות, יכולות) הם הבסיס היציב המסביר תגובות שונות של אנשים שונים לאותו מצב.","explain":"⚠️ סינתזה. לכאורה, תיאוריה המדגישה שהתנהגות משתנה לפי מצב עשויה להיראות כמכחישה קיום אישיות יציבה. אך דפוס ה'אם...אז...' עצמו הוא מה שמייחד ומאפיין כל אדם באופן יציב ועקבי לאורך זמן - 'חתימת האישיות' הייחודית שלו (ג'ון תמיד ידידותי בהיכרות ולא-ידידותי בהמשך; ג'ים ההפך). בנוסף, מישל מזהה 5 משתנים אישיים ייחודיים לכל אדם, המהווים בסיס יציב המסביר תגובות שונות לאותו מצב. האישיות אינה נעלמת - היא ממוקמת בדפוס האינטראקציה בין האדם למצב.","mnemo":"✍️ \"אם...אז...\" = חתימה יציבה"},{"id":"prof12_34","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תארו דטרמיניזם הדדי - הקשר בין אדם, סביבה והתנהגות.","a":"אדם, התנהגות וסביבה משפיעים זה על זה הדדית (לא חד-כיווני). עמדות/חיזוקי עבר + גירויי סביבה משפיעים על התנהגות; ההתנהגות משפיעה על הסביבה; הסביבה/משוב משפיעים חזרה על האישיות. דוגמה: תפיסה עצמית כלא-ספורטאי (אדם) מול ברכת שחייה זמינה (סביבה) - התנהגות חברותית יוצרת סביבה נעימה יותר.","explain":"אינטראקציה מורכבת בין גורמים הקשורים באדם, בהתנהגות ובגירויים מהסביבה - כל אחד יכול להשפיע על האחרים או לשנותם, השינוי הדדי, לא חד-כיווני. עמדות/חיזוקי עבר וגירויי סביבה משפיעים על התנהגות; מה שאנו עושים משפיע על הסביבה; הסביבה/המשוב עלינו משפיעים בחזרה על אישיותנו. דוגמה: תפיסה עצמית כלא-ספורטאי (אדם) מול ברכת שחייה זמינה (סביבה) - התנהגות חברותית סביב הברכה יוצרת סביבה נעימה יותר, המשפיעה בחזרה.","mnemo":"🔺 אדם↔️התנהגות↔️סביבה - משולש הדדי"},{"id":"prof12_35","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד למידה מצפייה משפיעה על התנהגותנו?","a":"משנים התנהגות בעקבות צפייה באחרים - לומדים איזו התנהגות מתוגמלת/נענשת/מתעלמים ממנה, מבלי להתנסות בעצמנו. מאפשר לחזות תוצאות פעולות מראש, וחוסך התנסות ישירה מסוכנת/יקרה.","explain":"תהליך שבו אדם משנה את התנהגותו בעקבות צפייה בהתנהגות אחר. מאפשר רכישת מידע רב על הסביבה החברתית - איזו התנהגות ראויה/מתוגמלת, על מה נענשים, ומה נתקל בהתעלמות. היתרון המרכזי: מאפשר לחזות תוצאות אפשריות של פעולות מבלי להתנסות בהן בפועל - רוכשים מיומנויות/עמדות/אמונות מהתבוננות באחרים, חוסך ניסוי-וטעייה מסוכן/יקר.","mnemo":"👀 רואה→לומד→בלי לנסות בעצמו"},{"id":"prof12_36","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי יעילות עצמית? דונו ב-4 מקורות המידע.","a":"תפיסת האדם שהוא יכול לתפקד כראוי במצב מסוים - משפיעה על מוטיבציה/ביצועים. 4 מקורות: (1) הישגים ממשיים. (2) ניסיון עקיף (צפייה באחרים). (3) שכנוע (מאחרים/עצמי). (4) ניטור עוררות רגשית (חרדה=ציפייה נמוכה; התרגשות=ציפייה גבוהה).","explain":"יעילות עצמית (self-efficacy) - תפיסת האדם שהוא יכול לתפקד כראוי במצב מסוים. משפיעה על מוטיבציה וביצועים - איננו מנסים/נוטלים סיכון כשמצפים שלא נהיה יעילים, גם עם יכולת/רצון בפועל.\n\nארבעת המקורות: (1) הישגים ממשיים - הצלחות/כישלונות בעבר. (2) ניסיון עקיף - צפייה בהתנהגות אחרים. (3) שכנוע - מאחרים או מעצמנו. (4) ניטור עוררות רגשית - חרדה מרמזת ציפיות נמוכות, התרגשות מרמזת ציפייה להצלחה.\n\nהוכחה: מתבגרים עם יעילות ויסות עצמי גבוהה (איטליה) הראו סיכוי נמוך ביותר להתנהגות אלימה בגילים 16 ו-18.","mnemo":"4️⃣ הישג+צפייה+שכנוע+עוררות"},{"id":"prof12_reflection9","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"נתחו את מקרה אביגיל (בחינת קבלה לתזמורת) לפי 4 מקורות היעילות העצמית.","a":"הישגים ממשיים=מלגות רבות, 15 שנות ניסיון (גבוה). ניסיון עקיף=תלמידי ביה\"ס התקבלו לתזמורות (גבוה). שכנוע=הורים/חברים מעודדים (גבוה). עוררות רגשית=חרדה (נמוך/מנוגד). 3 מתוך 4 מקורות חיוביים - סביר שתיגש, למרות החרדה.","explain":"הישגים ממשיים: מנגנת מגיל 7, זכתה במלגות הצטיינות רבות - גבוה.\nניסיון עקיף: תלמידים רבים מבית ספרה התקבלו לתזמורות - גבוה.\nשכנוע: הורים וחברים מעודדים אותה - גבוה.\nניטור עוררות רגשית: נתקפת חרדה כשחושבת על הבחינה - מרמז ציפיות נמוכות (נמוך/מנוגד).\n\nמסקנה: 3 מתוך 4 מקורות מצביעים על יעילות עצמית גבוהה - אביגיל אכן מסוגלת. החרדה עשויה לשקף חשש טבעי לגבי אירוע מכריע, לא בהכרח חוסר יכולת אמיתי. סביר שתיגש לבחינה, אף שהחרדה עלולה להקשות עליה.","mnemo":"🎻 אביגיל: 3 חזקים, 1 חלש (חרדה)"},{"id":"prof12_37","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הציגו את תיאוריית הלמידה החברתית הקוגניטיבית של בנדורה.","a":"מחברת עקרונות למידה עם אינטראקציות חברתיות ותהליכים קוגניטיביים. מרכיבים: דטרמיניזם הדדי (אדם-התנהגות-סביבה משפיעים זה על זה), למידה מצפייה (רכישת התנהגות ללא התנסות ישירה), יעילות עצמית (תפיסת יכולת לתפקד, מ-4 מקורות), ציפיות מבוססות-תוצאה (תלויות בתפיסת תמיכת הסביבה).","explain":"מחברת עקרונות למידה עם הדגשת אינטראקציות בין אנשים בסביבות חברתיות ותהליכים קוגניטיביים.\n\nדטרמיניזם הדדי - אדם, התנהגות וסביבה מקיימים אינטראקציות ומשפיעים זה על זה, לא חד-כיווני.\nלמידה מצפייה - שינוי התנהגות בעקבות צפייה באחרים, ללא התנסות ישירה.\nיעילות עצמית - תפיסת יכולת לתפקד במצב מסוים, מבוססת על 4 מקורות מידע.\nציפיות מבוססות-תוצאה - התיאוריה מכירה גם בחשיבות הסביבה: ציפייה להצלחה/כישלון תלויה גם בתפיסת תמיכת/אי-תמיכת הסביבה, לא רק בתפיסת כשירות עצמית.","mnemo":"🧩 בנדורה=למידה+חברה+קוגניציה"},{"id":"prof12_38","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"אילו ביקורות נמתחות על תיאוריות ביהביוריסטיות/קוגניטיביות (רגשות, לא-מודע, עבר)?","a":"רגשות: מוזנחים, נתפסים רק כתוצר לוואי של מחשבה/התנהגות, לא חשובים כשלעצמם (בניגוד לפסיכודינמי). לא-מודע: לא מכירות במלוא השפעתו על התנהגות/רגשות. עבר: מיעטו להתייחס למקורות התפתחותיים - התמקדות בהווה מטשטשת את חשיבות העבר.","explain":"יחס לרגשות: מעלימות עין מחשיבות מרכיב הרגש - בניגוד לפסיכודינמיות (שם רגשות כמו חרדה מרכזיים), כאן רגשות נתפסים רק כתוצר לוואי של מחשבה/התנהגות, לא חשובים כשלעצמם.\nיחס ללא-מודע: אינן מכירות במלוא השפעת המוטיבציה הלא-מודעת על התנהגות ורגשות.\nהתייחסות לעבר: מיעטו להתייחס למקורות ההתפתחות של האישיות הבוגרת - התמקדות בתפיסת ההווה מטשטשת את חשיבות העבר.\nעם זאת, תרמו תרומה חשובה: שיפור שיטות חינוך, דרכי טיפול חדשות, הבנת יחסי גומלין אדם-סביבה.","mnemo":"😶🕳️⏮️ מזניחים רגש+לא-מודע+עבר"},{"id":"prof12_table2","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"השוו בין תיאוריות האישיות (טבלה 2: תיאוריה מרכזית, תורשה/סביבה, למידה/פנימי, עבר/הווה/עתיד, מודע/לא-מודע, נטייה/מצב, כוח מניע).","a":"טיפוסים/תכונות=קטגוריות/ממדים יציבים, הווה, מודע. פסיכודינמית=דחפים לא-מודעים, עבר, תורשה. הומניסטית=מימוש עצמי, הווה/עתיד, מודע, נטייתית. ביהביוריסטית=חיזוקים, סביבה, עבר, מצב חיצוני. קוגניטיבית=תהליכי חשיבה, אינטראקציה אדם-מצב, הווה, מודע בעיקר.","explain":"טיפוסים/תכונות: קטגוריות/ממדים יציבים; הווה; מודע; נטייה פנימית.\nפסיכודינמית: קונפליקט דחפים לא-מודעים (סתמי/אני/אני עליון); עבר קובע הכל; תורשה עיקרית; נטייה פנימית; כוח מניע=אנרגיה נפשית/ליבידו.\nהומניסטית: שאיפה למימוש עצמי; הווה/עתיד; מודע; נטייתית; כוח מניע=נטייה מולדת לצמיחה.\nביהביוריסטית: סך הרגלים נלמדים; עבר (היסטוריית חיזוקים); סביבה עיקרית; מצב חיצוני; כוח מניע=חיזוקים/הפחתת מתח.\nקוגניטיבית: תהליכי חשיבה, אינטראקציה אדם-מצב (מישל, בנדורה); הווה; מודע בעיקר; אינטראקציה (לא רק אחד); כוח מניע=יעילות עצמית/דטרמיניזם הדדי.","mnemo":"📋 טבלת-על - כל תיאוריה בשורה"},{"id":"prof12_40","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מה מאפיין מבחני אישיות אובייקטיביים?","a":"הליך מתן/נקידה פשוט, כללים מוגדרים היטב, לעתים ממוחשב. ציון=מספר יחיד בסולם חד-ממדי, או קבוצת ציונים על תכונות, מושווה למדגם נורמטיבי. מבוסס על הנחות: לתכונות יש לכידות, וניתן למדוד אותן (מהימנות/תוקף).","explain":"הליך מתן ונקידה פשוטים יחסית, על פי כללים מוגדרים היטב; לעתים ממוחשב. הציון הסופי - מספר יחיד בסולם חד-ממדי (הסתגלות מול אי-הסתגלות), או קבוצת ציונים על תכונות (אימפולסיביות, תלות, מוחצנות), מדווחים בהשוואה למדגם נורמטיבי. מבוססים על 2 הנחות: לתכונות אישיות יש לכידות להתנהגות; אפשר למדוד תכונות אלה (מהימנות ותוקף).","mnemo":"📝 מבחן פשוט=ציון אחד, מושווה לנורמה"},{"id":"prof12_41","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מה מאפיין שאלוני דיווח עצמי? על אילו הנחות מודעות הם מתבססים?","a":"מבחן אובייקטיבי - הנבחן עונה על היגדים לגבי מחשבות/רגשות/פעולות (כמו MMPI, 10 סולמות קליניים+סולמות תוקף, פותח אמפירית). הנחה: האדם מודע דיו למחשבותיו/רגשותיו כדי לדווח עליהם בכנות - בעייתי לאור תהליכים לא-מודעים והטיות דיווח (לכן יש סולמות תוקף לבדיקת יושר).","explain":"מבחן אובייקטיבי שבו הנבחן עונה על שאלות בנוגע למחשבותיו, לרגשותיו ולפעולותיו - קורא היגדים ומציין מה נכון לגביו. דוגמה: MMPI. ⚠️ הנחת מודעות: מניחים שהאדם מודע דיו למחשבותיו/רגשותיו כדי לדווח עליהם בכנות ובדייקנות - הנחה בעייתית לאור תהליכים לא-מודעים (פרק פסיכודינמי) והטיות דיווח (רצייה חברתית) - לכן שאלונים כמו MMPI כוללים סולמות תוקף נפרדים לבדיקת יושר/רשלנות.","mnemo":"✍️ מדווח על עצמו, בהנחת-כנות"},{"id":"prof12_42","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מה בודק ה-MMPI?","a":"מטרתו לאבחן אנשים לפי תוויות פסיכיאטריות - 10 סולמות קליניים (סכיזופרניה, דיכאון, פרנויה וכו') המבדילים קבוצה קלינית מקבוצת ביקורת נורמלית, ועוד סולמות תוקף המזהים חוסר יושר/רשלנות/התגוננות בתשובות.","explain":"המפתח להבנת ה-MMPI: זהו שאלון \"דיווח עצמי\" - כלומר, הנבחן עונה על שאלות על עצמו (לא מבחן חיצוני אובייקטיבי). ההבדל המרכזי מ-NEO-PI: MMPI נבנה במיוחד כדי להבחין בין הפרעות קליניות (מבוסס על השוואה לחולים אמיתיים), בעוד NEO-PI מודד תכונות אישיות רגילות באוכלוסייה הכללית.","mnemo":"🏷️ MMPI=10 תוויות פסיכיאטריות"},{"id":"prof12_43","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד נבנה ה-MMPI?","a":"550 פריטים ראשוניים, נבחרו בשיטה אמפירית (לא תיאורטית) - פריט נכלל בסולם רק אם הבחין בבירור בין קבוצה קלינית (למשל סכיזופרנים) לקבוצת ביקורת נורמלית. MMPI-2 (שנות ה-80) עדכן שפה/תוכן והוסיף 15 סולמות תוכן חדשים.","explain":"פותח בשנות ה-30 (האת'אוויי ומקינלי). המבחן הראשון הכיל 550 פריטים. נבנה בשיטה אמפירית, לא תיאורטית - פריט נכלל בסולם רק אם הבחין בבירור בין קבוצה קלינית (למשל סכיזופרנים) לקבוצת ביקורת נורמלית (תשובה זהה בתוך קבוצה, שונה בין קבוצות). MMPI-2 (שנות ה-80) עדכן שפה/תוכן והוסיף 15 סולמות תוכן חדשים.","mnemo":"🔬 550 שאלות, נבחרו אמפירית לא תיאורטית"},{"id":"prof12_44","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"לאיזו אוכלוסייה מיועד ה-MMPI?","a":"בני אדם עם בעיות קליניות - משמש במרפאות לאבחון הפרעות ולהכוונת טיפול. לא מיועד עיקרית לאוכלוסייה הכללית שאינה בטיפול נפשי.","explain":"ה-<b>MMPI</b> מיועד לאוכלוסייה עם <b>בעיות-קליניות</b> - נבנה ונבחן (כוילל) מלכתחילה <b>מול-קבוצות-חולים-אמיתיות</b>, ומשמש במרפאות ל<b>אבחון הפרעות ולהכוונת-טיפול</b>. ⚠️ נקודה חשובה: הוא <b>לא-מיועד-בעיקר</b> לאוכלוסייה-הכללית שאינה-בטיפול-נפשי - אם-אדם-בריא-נפשית ייקח-אותו, התוצאות עלולות-להיות פחות-משמעותיות, כי הכלי-כויל-במיוחד להבחין בין-הפרעות-קליניות, לא-למדוד תכונות-אישיות-רגילות. זו-הסיבה שקיימים-כלים-נפרדים (כמו NEO-PI, הנלמד-בהמשך) המיועדים-ספציפית להערכת-אישיות-באוכלוסייה-הכללית-הבריאה.","mnemo":"🏥 MMPI=לחולים, לא לכולם"},{"id":"prof12_45","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהם יתרונות/חסרונות ה-MMPI?","a":"יתרונות: קל/פשוט/חסכוני, תועלת באבחון, גמיש (בניית סולמות חדשים), מאגר פרופילים עצום (50+ שנה). חסרונות: סולמות קליניים הטרוגניים מדי, לא עודכן בהתאם להתקדמות תיאורטית, שאלות פתוחות על תוקף חוצה-גזעים/אתניות.","explain":"יתרונות: קל ופשוט לתת, חסכוני, תועלת באבחון פסיכופתולוגיה, גמיש (בניית סולמות חדשים ממאגר הפריטים), מאגר פרופילים עצום שהצטבר מעל 50 שנה (מאפשר השוואות והשערות חדשות). חסרונות: סולמות קליניים הטרוגניים מדי (מודדים כמה דפוסים בבת אחת); המעבר ל-MMPI-2 לא הביא בחשבון התקדמות תיאורטית בפסיכולוגיה; שאלת תוקף חוצה-גזעים/אתניות עדיין פתוחה.","mnemo":"⚖️ קל+גמיש מול הטרוגני+ישן"},{"id":"prof12_46","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מה בודקים NEO-PI ושאלון חמשת הגדולים?","a":"NEO-PI: מודד חמשת גורמי האישיות (נוירוטיות, מוחצנות, פתיחות, נועם הליכות, מצפוניות) באוכלוסייה כללית לא-קלינית; גרסה מעודכנת מודדת 30 תכונות. שאלון חמשת הגדולים: גם מבוסס חמשת הגורמים, אך מתוכנן לתוקף בין-תרבותי, פשוט יותר (2 תכונות/גורם), כולל סולם רצייה חברתית, וקורא לגורם הראשון \"אנרגיה\" ולא \"מוחצנות\".","explain":"NEO-PI - מעריך מאפייני אישיות במבוגרים שאינם בטיפול נפשי, מודד את מודל חמשת גורמי האישיות (נוירוטיות, מוחצנות, פתיחות, נועם הליכות, מצפוניות). גרסה מעודכנת (NEO-PI-3) מודדת 30 תכונות מאורגנות בחמשת הגורמים.\n\nשאלון חמשת הגדולים (BFQ) - גם מבוסס חמשת הגורמים, תוכנן לתוקף בין-תרבותי (איטליה, ארה\"ב, ספרד ועוד). הבדלים מ-NEO-PI: הגורם הראשון נקרא 'אנרגיה' לא 'מוחצנות'; כולל סולם רצייה חברתית; פשוט יותר (2 תכונות לכל גורם, לא 6).","mnemo":"5️⃣ NEO-PI=5-הגדולים למי-שלא-חולה"},{"id":"prof12_47","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"במה שונים מבחני השלכה ממבחנים אובייקטיביים?","a":"אובייקטיביים=תשובה סגורה/מוגבלת (נכון-לא נכון, או דירוג בסולם). השלכה=גירוי מעורפל (כתם דיו/תמונה דו-משמעית), הנבחן מפרש בחופשיות ובמילותיו שלו, ללא רשימת תשובות מוכנה - כמו לראות צורות שונות בעננים.","explain":"ההבדל-המרכזי בין-שני-סוגי-המבחנים: <b>מבחנים אובייקטיביים</b> - נותנים תשובה <b>סגורה/מוגבלת-מראש</b> (נכון-לא-נכון, או דירוג-בסולם-נתון) - הנבחן בוחר מבין-אפשרויות-קבועות. <b>מבחני השלכה</b> - מציגים <b>גירוי מעורפל במתכוון</b> (כתם-דיו, תמונה דו-משמעית), והנבחן <b>מפרש בחופשיות מוחלטת, במילותיו-שלו</b>, ללא-רשימת-תשובות-מוכנה. ⚠️ ההיגיון-התיאורטי מאחורי-מבחני-השלכה: בדיוק כמו-לראות-צורות-שונות-בעננים - כשהגירוי-עמום, האדם 'משליך' עליו את-תוכני-הנפש-הפנימיים-שלו (רגשות, דחפים לא-מודעים), ובכך חושף-אותם לצופה-המיומן, במקום-להסתיר-אותם-מאחורי תשובה-מוגדרת-מראש.","mnemo":"🔓🔒 אובייקטיבי=סגור | השלכה=פתוח"},{"id":"prof12_48","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"על איזו הנחה תיאורטית נשענים מבחני ההשלכה?","a":"מאחר שהגירוי עמום ללא משמעות אובייקטיבית, התשובה נקבעת לפי מה שהאדם מביא עמו - רגשות פנימיים, מניעים, קונפליקטים מחוויות עבר, המושלכים (כמנגנון הגנה) על הגירוי. פותח על ידי פסיכואנליטיקנים לחשיפת דינמיקה לא-מודעת.","explain":"מאחר שהגירוי עמום במתכוון, ההנחה היא שהתשובות נקבעות במידה מסוימת לפי מה שהאדם מביא עמו למבחן - רגשות פנימיים, מניעים אישיים וקונפליקטים מחוויות חיים קודמות, המושלכים (projected) על הגירויים העמומים. פסיכואנליטיקנים היו הראשונים להשתמש בהם, בתקווה לחשוף את הדינמיקה הלא-מודעת של המטופל.","mnemo":"🪞 גירוי-עמום=מראה לנפש הפנימית"},{"id":"prof12_49","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"באילו שלושה מדדים משתמשים לפרש את מבחן רורשך?","a":"(1) מיקום - האם התייחס לכל הכתם או לחלק ממנו. (2) תוכן - אופי האובייקט/הפעולה שראה. (3) מגדירים - אילו היבטי הכרטיס (צבע/הצללה) עוררו את התגובה.","explain":"שלושה-מדדים מרכזיים לפרשנות-מבחן-רורשך (מבחן-ההשלכה המבוסס-על-כתמי-דיו): <b>(1) מיקום</b> - האם הנבחן התייחס <b>לכל הכתם</b> או <b>רק לחלק</b> ממנו (מעיד על-סגנון-חשיבה - כוללני-לעומת-פרטני). <b>(2) תוכן</b> - <b>אופי-האובייקט/הפעולה</b> שהנבחן ראה בכתם (מה-בדיוק תיאר - אדם, בעל-חיים, פעולה אלימה, וכו'). <b>(3) מגדירים</b> - <b>אילו היבטים ספציפיים</b> של-הכרטיס (צבע, הצללה, צורה) <b>עוררו</b> את-התגובה (מה-בדיוק 'הפעיל' את-הפרשנות-שהנבחן-נתן). ⚠️ שלושת-המדדים-יחד מרכיבים פרופיל-פרשני-מלא - לא-מסתפקים-רק-בתוכן (מה-ראה), אלא-גם-באיך (מיקום) ולמה (מגדירים) הוא-ראה-את-מה-שראה.","mnemo":"3️⃣ מיקום+תוכן+מגדירים"},{"id":"prof12_50","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מה בודק מבחן TAT וכיצד?","a":"מציג תמונות סצנות עמומות, מבקש מהנבחן להמציא סיפור (מה קורה/הוביל/יקרה). בוחן מעריך מבנה/תוכן הסיפורים ומניעי המספר - חושף צרכים מרכזיים (כוח, השתייכות, הישג). מדד תקף במיוחד לצורך בהישג.","explain":"מציג לנבחנים תמונות של סצנות עמומות, ומבקש מהם להמציא סיפורים: מה האנשים עושים/חושבים, מה הוביל לאירוע, כיצד יסתיים. הבוחן מעריך את מבנה הסיפורים, תוכנם, והתנהגות המספר - מנסה לגלות את העניינים המעסיקים את הנבחן, מניעיו ומאפייני אישיותו. משמש לגילוי הבדלים בצרכים מרכזיים (כוח, השתייכות, הישג) - מדד תקף במיוחד לצורך בהישג.","mnemo":"📖 תמונה עמומה→סיפור→מניעים נחשפים"},{"id":"quiz12_1","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"מבחן האישיות המעריך באופן הישיר ביותר את ממדי מודל חמשת הגורמים: (רורשך / מבחן התפסת הנושא / NEO-PI / MMPI-2)","a":"NEO-PI (נבנה ספציפית סביב 5 הגורמים, בניגוד ל-MMPI המיועד לאבחון קליני)","explain":"<b>NEO-PI</b> נבנה <b>במיוחד וספציפית</b> סביב מודל-חמשת-הגורמים (נוירוטיות, מוחצנות, פתיחות, נועם-הליכות, מצפוניות), ומעריך אותם <b>ישירות</b>. ⚠️ אל-תתבלבלו עם-האפשרויות-האחרות: <b>MMPI-2</b> מיועד לאבחון-<b>קליני</b> (הפרעות, לא-תכונות-רגילות), <b>רורשך</b> ו<b>מבחן-התפסת-הנושא (TAT)</b> הם מבחני-<b>השלכה</b> שאינם-מודדים גורמים-ספציפיים-במישרין (הפרשנות-שלהם-איכותנית, לא-כמותית-לפי-חמישה-ממדים-קבועים) - רק NEO-PI תוכנן-במפורש-סביב-מודל-חמשת-הגורמים.","mnemo":"🎯 NEO-PI=בנוי בדיוק ל-5-הגדולים"},{"id":"quiz12_2","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"לפי איזה משפט ביישנות היא תכונה מולדת? (הורים מונעים אהבה ללא הישגים / ילדים מלידה מאופקים יותר עם זרים / תרבויות דורשות ציות לסמכות / פעולות באינטרנט מבודדות)","a":"יש ילדים שמלידה הם מאופקים יותר בחברת אנשים לא מוכרים (תצפית על תכונה קיימת מלידה, ללא השפעה חיצונית)","explain":"מזג הוא רמת התגובה הרגשית וההתנהגותית לסביבה, המושתתת על בסיס ביולוגי. ג'רום קגן ועמיתיו הראו שמקצת התינוקות 'נולדים ביישנים' ואחרים 'פתוחים'.\n\nתינוקות מאופקים (inhibited) - עקביים בהיותם זהירים ומאופקים רגשית מול אנשים/מצבים בלתי מוכרים.\nתינוקות נטולי עכבות (uninhibited) - עקביים בהיותם חברותיים, מביעים רגשות בספונטניות, כמעט אינם חוששים.\n\nבמדגם אחד: כ-10% מאופקים, כ-25% נטולי עכבות. נמצאו הבדלי מזג אפילו ברחם - רמות פעילות עובר גבוהות נקשרו לקשיי הסתגלות לאחר הלידה.\n\nכיצד בא לידי ביטוי בגילאים שונים: מחקרי אורך הראו המשכיות ארוכת טווח - ילדים שהפגינו תגובתיות מוטורית גבוהה ובכי בגיל 4 חודשים הראו מידת פחד גבוהה יותר במצבים בלתי מוכרים גם בגיל שנתיים וארבע. עם זאת, נדיר שילדים עוברים מקטגוריה לקטגוריה לגמרי, גם אם העוצמה מתמתנת עם הגיל.","mnemo":"👶 מלידה מאופק=תכונה מולדת"},{"id":"quiz12_4","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"אבנר משכנע את יונתן שיכול לקבל משרה. אם יונתן יצליח, זה ישפיע על תחושת ___ של אבנר: (הוויסות העצמי / הדטרמיניזם ההדדי / היעילות העצמית / הליבידו)","a":"היעילות העצמית (הצלחת יונתן=ניסיון עקיף המחזק את תחושת היכולת של אבנר)","explain":"יעילות עצמית (self-efficacy) - תפיסת האדם שהוא יכול לתפקד כראוי במצב מסוים. אחד המקורות המזינים אותה הוא ניסיון עקיף - צפייה בהצלחת אדם דומה לנו (כמו יונתן). אם יונתן יצליח לקבל את המשרה, זה יחזק את תחושת היעילות העצמית של אבנר לגבי סיכוייו שלו במצבים דומים.","mnemo":"🎻 הצלחת-אחר=ניסיון-עקיף=יעילות-עצמית"},{"id":"quiz12_5","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"איזו תיאוריית אישיות מדגישה יותר חוקי התנהגות מולדים? (למידה חברתית / הומניסטית / פרוידיאנית / העצמי)","a":"התיאוריה הפרוידיאנית (מבוססת על אינסטינקטים ביולוגיים מולדים - ליבידו)","explain":"ה<b>תיאוריה הפרוידיאנית</b> (הפסיכודינמית) מדגישה <b>יותר-מכל תיאוריה-אחרת</b> חוקי-התנהגות-מולדים - מבוססת-על <b>אינסטינקטים ביולוגיים</b> (ליבידו, דחפי-ארוס-וטנטוס) <b>הקיימים-מרגע-הלידה</b> ומניעים-את-ההתנהגות לאורך-כל-החיים. ⚠️ בהשוואה: התיאוריה-<b>ההומניסטית</b> מדגישה נטייה-מולדת-לצמיחה (פחות 'מכניסטית'), <b>למידה-חברתית</b> מדגישה סביבה/תצפית (לא-מולד), ותיאוריית-<b>העצמי</b> מדגישה תפיסה-עצמית-נלמדת - רק-הפרוידיאנית מבוססת-כה-חזק על-דחפים-ביולוגיים-מולדים-כמנוע-מרכזי.","mnemo":"🧬 פרויד=אינסטינקטים מולדים"},{"id":"quiz12_7","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"לפי פרויד, בין גיל 4-5 ילדים נמצאים בשלב ה___: (פאלי / אנלי / אורלי / גניטלי)","a":"פאלי (שלב בגיל 4-5, ממוקד באיברי המין ותסביך אדיפוס)","explain":"לפי-פרויד, בין-גיל-4-5 ילדים נמצאים ב<b>שלב הפאלי</b> - שלב-התפתחות פסיכוסקסואלי, הממוקד <b>באיברי-המין</b>, שבו מתרחש (לפי-התיאוריה) <b>תסביך-אדיפוס/אלקטרה</b> - משיכה להורה-מהמין-השני, ותחרות-עם-ההורה-בן-אותו-המין. ⚠️ קישור לסדר-השלבים-הפסיכוסקסואליים (שנלמד-בפרק): אורלי (ינקות) → אנלי (גיל-2-3) → <b>פאלי (גיל-4-5)</b> → תקופת-חביון → גניטלי (התבגרות) - כל-שלב ממוקד באזור-ארוגני-אחר, והפאלי הוא-הראשון-שכולל תסביך-מורכב-כזה, ולא-רק סיפוק/תסכול-פשוט.","mnemo":"4️⃣5️⃣ גיל 4-5=פאלי"},{"id":"quiz12_8","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"למדידת צורך בהישג, המבחן הנבחר: (NEO-PI / מבחן התפסת הנושא / רורשך / MMPI-2)","a":"מבחן התפסת הנושא (TAT חושף צרכים כמו הישג דרך סיפורים על תמונות)","explain":"מבחן התפסת הנושא (TAT) - מציג לנבחן תמונות של סצנות עמומות, ומבקש ממנו להמציא סיפור על מה שקורה. לפי הנחת מבחני ההשלכה, הסיפורים חושפים צרכים לא-מודעים כמו צורך בהישג - למשל, נבחן עם צורך הישג גבוה ייטה לספר סיפורים על הצלחה, שאיפה והתגברות על מכשולים.","mnemo":"📖 TAT=צורך-בהישג"},{"id":"quiz12_9","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"איזה גורם אינו ממדי התכונות במודל חמשת הגורמים? (נועם / מוחצנות / נוירוטיות / יצירתיות)","a":"יצירתיות (זוהי תת-תכונה בתוך \"פתיחות\", לא גורם עצמאי בפני עצמו)","explain":"<b>יצירתיות</b> אינה-נמנית עם חמשת-הגורמים-העצמאיים במודל (נוירוטיות, מוחצנות, פתיחות, נועם-הליכות, מצפוניות) - היא נחשבת <b>תת-תכונה</b> בתוך הגורם '<b>פתיחות לחוויה</b>', לא-ממד-עצמאי-בפני-עצמו. ⚠️ מודל-חמשת-הגורמים (OCEAN) מדויק-מאוד-בהגדרתו - חמישה-ממדים-ראשיים-בלבד; תכונות-נוספות (כמו יצירתיות, אינטליגנציה-רגשית) עשויות-להיות-<b>קשורות</b> לאחד-מהם, אך לא-נחשבות-ממד-שישי-עצמאי.","mnemo":"🚫 יצירתיות - תת-תכונה, לא גורם"},{"id":"quiz12_10","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"הרצאה על ארכיטיפים בלא-מודע הקולקטיבי - משנתו של: (אדלר / פרויד / הורניי / יונג)","a":"קרל יונג (פיתח את מושג הלא-מודע הקולקטיבי והארכיטיפים)","explain":"קרל יונג הרחיב את מושג הלא-מודע לכלול לא-מודע קולקטיבי - אמיתויות פסיכולוגיות משותפות לכל המין האנושי, מוסברות דרך ארכיטיפים (ייצוגים סמליים אוניברסליים: אנימוס=ארכיטיפ גברי, אנימה=ארכיטיפ נשי, מנדלה=ארכיטיפ העצמי/שלמות). פסיכולוגיה אנליטית: איזון בין כוחות מנוגדים. דחה את חשיבות הליבידו, הוסיף שני אינסטינקטים לא-מודעים: הצורך ליצור והצורך להיות אדם לכיד ושלם.","mnemo":"🌀 יונג=ארכיטיפים+לא-מודע-קולקטיבי"},{"id":"quiz12_11","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"חן מאמין שהאישיות נקבעת לפני הלידה; עדי מאמין שהיא צומחת מחוויות. הממד: (נטייה פנימית/מצב חיצוני / מודע/לא מודע / תורשה/סביבה / עבר/הווה/עתיד)","a":"תורשה לעומת סביבה (המחלוקת היא בדיוק על מקור האישיות - לפני/אחרי הלידה)","explain":"טיפוסים/תכונות: קטגוריות/ממדים יציבים; הווה; מודע; נטייה פנימית.\nפסיכודינמית: קונפליקט דחפים לא-מודעים (סתמי/אני/אני עליון); עבר קובע הכל; תורשה עיקרית; נטייה פנימית; כוח מניע=אנרגיה נפשית/ליבידו.\nהומניסטית: שאיפה למימוש עצמי; הווה/עתיד; מודע; נטייתית; כוח מניע=נטייה מולדת לצמיחה.\nביהביוריסטית: סך הרגלים נלמדים; עבר (היסטוריית חיזוקים); סביבה עיקרית; מצב חיצוני; כוח מניע=חיזוקים/הפחתת מתח.\nקוגניטיבית: תהליכי חשיבה, אינטראקציה אדם-מצב (מישל, בנדורה); הווה; מודע בעיקר; אינטראקציה (לא רק אחד); כוח מניע=יעילות עצמית/דטרמיניזם הדדי.","mnemo":"⚖️ תורשה-מול-סביבה=בדיוק המחלוקת"},{"id":"quiz12_12","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"טענה עיקרית של תיאוריות הומניסטיות: בני אדם שואפים ל: (אזורים ארוגניים / שימור עצמי / עליונות / מימוש עצמי)","a":"מימוש עצמי (המושג המרכזי בכל התיאוריות ההומניסטיות)","explain":"אברהם מסלו, המשתייך לגישה ההומניסטית, ניסח תיאוריה שלפיה המניעים הבסיסיים יוצרים מדרג של צרכים. הצרכים מאורגנים ברצף, מהפרימיטיביים ביותר עד המתקדמים ביותר, ובכל שלב הם חייבים לבוא על סיפוקם קודם שיהיה אפשר להמשיך לשלב הבא.\n\nחמשת הצרכים (מהתחתון לעליון):\n1. צרכים ביולוגיים - כמו רעב וצמא.\n2. צורכי ביטחון - כשהצרכים הביולוגיים סופקו.\n3. צורכי היקשרות - הצורך להשתייך, להתחבר, לאהוב ולהיות נאהב.\n4. צורכי הערכה - לאהוב את עצמנו, להיתפס כבעלי יכולת, לזכות בהערכת אחרים.\n5. מימוש עצמי - מיצוי הפוטנציאל במלואו; אדם המממש עצמו מודע לעצמו, מקבל את עצמו, יצירתי, ספונטני ופתוח לחידושים.\n\nעקרון המדרג: צרכים ברמה נמוכה שולטים במוטיבציה כל זמן שאינם מסופקים. מרגע שסופקו באופן משביע רצון, עוברת תשומת הלב לצרכים הגבוהים מהם.","mnemo":"🌱 הומניזם=מימוש-עצמי"},{"id":"quiz12_13","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"תיאוריות הומניסטיות הן ___ כי מדגישות ראייה סובייקטיבית: (הוליסטיות / פנומנולוגיות / נטייתיות / דטרמיניסטיות)","a":"פנומנולוגיות (מתמקדות בחוויה הסובייקטיבית של הפרט, לא במציאות אובייקטיבית)","explain":"הוליסטיות - מסבירות פעולות באמצעות האישיות בכללותה, לא תכונות נפרדות (למשל, מסלו: בני אדם מיסודם מונעים כלפי הרמות הגבוהות במדרג).\nנטייתיות - מתמקדות במאפיינים מולדים, המשפיעים מכריעות; גורמי מצב נתפסים כמגבלות/מחסומים. נטיות אינן תמות חוזרות (כמו תכונות) - הן מכוונות ליצירתיות וצמיחה, משתנות בכל ביטוי.\nפנומנולוגיות - מדגישות את מסגרת ההתייחסות הסובייקטיבית של הפרט, לא נקודת מבט חיצונית. מתמקדות בהווה - חוויות עבר חשובות רק במידה שהביאו למצב הנוכחי.","mnemo":"👁️ פנומנולוגי=חוויה-סובייקטיבית"},{"id":"quiz12_14","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"איזה משפט מתייחס למשתני מטרות/ערכים (מישל)? (פנחס מזיע לפני בחינות / מרים חושבת שתשכנע אחיה / יורם מבצע כפל בלא מחשבון / עומר רוצה לסיים לימודים לפני גיל 30)","a":"עומר רוצה לסיים את לימודיו במכללה לפני שימלאו לו 30 (זוהי תכנית/יעד חיים אישי - התאמה מדויקת למשתנה)","explain":"לפי מישל, \"מטרות וערכים\" הם תוצאות/מצבים רגשיים שהאדם מעריך ותכניותיו הגדולות בחיים. הרצון של עומר לסיים לימודים לפני גיל 30 הוא בדיוק תכנית חיים/מטרה אישית - בעוד שהזעה לפני בחינות (רגש), אמונה ביכולת לשכנע (ציפיות/אמונות), וביצוע כפל ללא מחשבון (יכולות) שייכים למשתנים אחרים במודל.","mnemo":"🎯 יעד-לגיל-30=מטרות-וערכים"},{"id":"quiz12_17","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"שיפוטי יעילות עצמית חשובים כי: (תחושת מודעות עצמית / מפחיתים השפעה חברתית / משפיעים על מאמץ ומוטיבציה / כמעט לא משפיעים)","a":"והם משפיעים על מידת המאמץ והמוטיבציה (תחושת יכולת קובעת אם בכלל ננסה)","explain":"שיפוטי-יעילות-עצמית (self-efficacy) חשובים כי הם <b>משפיעים ישירות על-מידת-המאמץ וההתמדה</b> שאדם משקיע-במשימה - תחושת-יכולת <b>גבוהה</b> מובילה להשקעת-מאמץ-רב-יותר ולהתמדה-גדולה-יותר <b>מול-קשיים</b>, בעוד תחושת-יכולת <b>נמוכה</b> מובילה-לוויתור-מהיר-יותר. ⚠️ קישור לתיאוריית-בנדורה (הלמידה-החברתית) - זה-בדיוק המושג שנלמד-ביחס-ל'יעילות-עצמית' בהקשר-ההתנהגותי: תפיסת-האדם-שהוא-יכול-לתפקד-כראוי במצב-מסוים <b>קובעת-מראש</b> אם-בכלל-ינסה, לפני-שהיכולת-האמיתית-שלו-נבחנת-בפועל.","mnemo":"💪 יעילות-עצמית→קובעת אם ננסה בכלל"},{"id":"quiz12_18","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"אישה עם התנהגויות אובססיביות-קומפולסיביות, פחדים, קושי בהחלטות. ב-MMPI-2 גבוהה על: (היפוכונדריה / דיכאון / פרנויה / פסיכאסתניה)","a":"סקלת פסיכאסתניה (מודדת בדיוק אובססיביות-קומפולסיביות ופחדים)","explain":"סולם ה<b>פסיכאסתניה</b> ב-MMPI-2 נועד לזהות בדיוק את-הפרופיל-המתואר: מחשבות/פעולות <b>אובססיביות-קומפולסיביות</b>, פחדים-מוגזמים (פוביות), וחוסר-החלטיות. ⚠️ הבדילו-מהסולמות-האחרים: <b>היפוכונדריה</b> (עיסוק-בתלונות-גופניות, לא-אובססיות-כפייתיות), <b>דיכאון</b> (עצבות/ייאוש, לא-פחדים-והחלטיות), <b>פרנויה</b> (חשדנות/רדיפה, לא-אובססיביות) - כל-סולם ב-MMPI-2 מכוון לזהות-פרופיל-קליני-ספציפי-אחר, ורק-הפסיכאסתניה מתאימה-בדיוק לתסמינים-המתוארים-כאן.","mnemo":"😰 פסיכאסתניה=אובססיה+פחד"},{"id":"quiz12_19","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"איזה מבין הבאים יוצא דופן? (רורשך / TAT / מבחן השלכתי / מבחן אובייקטיבי)","a":"מבחן אובייקטיבי (כל השאר הם מבחני השלכה, לא אובייקטיביים)","explain":"מבחן אובייקטיבי שבו הנבחן עונה על שאלות בנוגע למחשבותיו, לרגשותיו ולפעולותיו - קורא היגדים ומציין מה נכון לגביו. דוגמה: MMPI. ⚠️ הנחת מודעות: מניחים שהאדם מודע דיו למחשבותיו/רגשותיו כדי לדווח עליהם בכנות ובדייקנות - הנחה בעייתית לאור תהליכים לא-מודעים (פרק פסיכודינמי) והטיות דיווח (רצייה חברתית) - לכן שאלונים כמו MMPI כוללים סולמות תוקף נפרדים לבדיקת יושר/רשלנות.","mnemo":"🎯 אובייקטיבי לבד - כל השאר השלכה"},{"id":"quiz12_20","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"הביקורת העיקרית כלפי הקוגניטיביות/למידה חברתית: (מתעלמות מתהליכים רציונליים / מתעלמות מתהליכים רגשיים / דגש רב מדי על התפתחות / דגש רב מדי על לא-מודע)","a":"מתעלמות מחשיבותם של תהליכים רגשיים (מתמקדות במחשבה/למידה, לא ברגש כשלעצמו)","explain":"הביקורת-המרכזית על-הגישות הקוגניטיבית וההתנהגותית-חברתית (למידה-חברתית): הן <b>מתעלמות מחשיבותם של תהליכים-רגשיים</b> בעיצוב-ההתנהגות - הן מתמקדות בעיקר <b>בתהליכי-חשיבה/למידה</b>, אך הרגש-עצמו <b>כמעט-ואינו-נדון</b> כגורם-בפני-עצמו-משפיע. ⚠️ זו-ביקורת-חשובה-להבנת-מגבלות-הגישות: בעוד-הן-מצליחות-להסביר איך-מחשבות/למידה מעצבות-התנהגות, הן פחות-מצליחות-להסביר את-התפקיד-העצמאי-של-רגש (למשל, למה-רגש-עז יכול-'לעקוף' חשיבה-רציונלית) - זו-בדיוק-הביקורת-שגישות-רגשיות/פסיכודינמיות-יותר מתמקדות-בה-ביתר-שאת.","mnemo":"❤️ קוגניטיבי מזניח רגש"},{"id":"quiz12_21","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"מהו קיבעון, לפי פרויד? (הישארות משום מחסור / הישארות משום עודף / א+ב נכונות / חזרה אחורה עקב קשיים בהווה)","a":"תשובות א + ב נכונות (גם עודף וגם מחסור בסיפוק יוצרים קיבעון)","explain":"לפי-פרויד, קיבעון (fixation) נובע <b>הן</b> מ<b>סיפוק-יתר</b> (עודף-פינוק) <b>והן</b> מ<b>מחסור/תסכול-יתר</b> בשלב-התפתחותי-מסוים - שני-הכיוונים-הקיצוניים (יותר-מדי או פחות-מדי) עלולים-לגרום להישארות-רגשית בשלב-שלא-נפתר-כראוי. ⚠️ אל-תתבלבלו עם-אפשרות-ד' ('חזרה-אחורה עקב-קשיים-בהווה') - זה-מתאר <b>רגרסיה/תסוגה</b>, מושג-שונה-לגמרי: קיבעון נוצר <b>בזמן</b> השלב-ההתפתחותי-עצמו, בעוד תסוגה היא חזרה-מאוחרת-יותר לשלב-קודם, כתגובה-למצוקה-בהווה.","mnemo":"➕➖ עודף וגם מחסור=קיבעון"},{"id":"quiz12_22","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"שמעון לא התקבל למשרה, אמר שהוא שמח כי השכר ממילא נמוך. מנגנון הגנה: (הדחקה / השלכה / רציונליזציה / היפוך תגובה / רגרסיה / קיבעון)","a":"רציונליזציה (מצדיק כישלון בהיגיון מומצא לאחר מעשה)","explain":"שמעון, שלא-התקבל-למשרה ואומר שהוא 'שמח כי-השכר-ממילא-נמוך' - זו <b>רציונליזציה</b>: מנגנון-הגנה שבו האדם מצדיק כישלון/אכזבה <b>בהיגיון-מומצא-לאחר-מעשה</b>, כדי-להימנע-מהודאה-בכאב/אכזבה-האמיתיים. ⚠️ אל-תתבלבלו עם-מנגנוני-הגנה-אחרים: זו <b>לא</b> הדחקה (לא-מודחק-מהתודעה, שמעון-כן-מודע-לכישלון), <b>לא</b> השלכה (לא-מייחס-את-הרגש-לאדם-אחר), ו<b>לא</b> היפוך-תגובה (לא-מתנהג-הפוך-מהתשוקה) - הוא <b>מנמק/מצדיק</b> את-המצב בהסבר-הגיוני-לכאורה, זו-בדיוק-רציונליזציה.","mnemo":"🍇 \"השכר נמוך ממילא\"=רציונליזציה"},{"id":"quiz12_23","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"שני ילדים עם הורים ביולוגיים שונים, אומצו בינקותם ע\"י אותה משפחה. תמיכה בהשפעת התורשה תימצא אם אישיותם: (דומה יותר להורים המאמצים / דומה לילדים הביולוגיים של המאמצים / דומים יותר אחד לשני מאשר לאחיהם הביולוגיים / פחות דומים זה לזה מאשר לאחיהם הביולוגיים)","a":"פחות דומה לזו של אחיהם המאומצים בהשוואה לזו של אחיהם הביולוגיים (אם גנטיקה חשובה, קרבה גנטית=דמיון, לא סביבה משותפת)","explain":"אם-שני-ילדים <b>ללא-קשר-גנטי</b> (הורים-ביולוגיים-שונים) המאומצים-על-ידי <b>אותה משפחה</b> יהיו <b>פחות-דומים</b> זה-לזה מאשר-כל-אחד-מהם לאחיו-הביולוגי (שגדל-במשפחה-אחרת) - זו תמיכה-בהשפעת-<b>התורשה</b> על-אישיות. ⚠️ ההיגיון: אם-הסביבה-המשותפת (המשפחה-המאמצת) הייתה-הגורם-המכריע, שני-הילדים-המאומצים (הגדלים-באותה-סביבה) היו-אמורים-להיות-<b>דומים-יותר</b> זה-לזה; העובדה-שהם <b>פחות-דומים</b> מקרוביהם-הביולוגיים (עמם-חולקים-גנים, לא-סביבה) מוכיחה שגנטיקה, לא-רק-סביבה-משותפת, משפיעה-על-אישיות.","mnemo":"🧬 דומה לביולוגי, לא למאמץ=תורשה"},{"id":"quiz12_24","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"לפי פרויד, הסתמי הוא: (קולו של המודע / מנגנון הגנה מפני חרדה / כולל 2 אינסטינקטים מתחרים: חיים ומוות / מתפתח קצת אחרי הלידה)","a":"כולל שני אינסטינקטים מתחרים: החיים והמוות (ארוס וטנטוס - שני הדחפים הבסיסיים לפי פרויד)","explain":"לפי זיגמונד פרויד (1915), בני אדם חווים מצבי דחף הנובעים משני סוגי אינסטינקטים: אינסטינקטים של חיים (כולל מיניות) ואינסטינקטים של מוות (כולל תוקפנות). פרויד האמין שדחפים אינסטינקטיביים מכוונים אנרגיה נפשית לסיפוק צרכים גופניים. כאשר אי-אפשר לפרוק אנרגיה זו, נוצר מתח, הדוחף אנשים לפעולות שיפחיתו אותו. פרויד האמין שאינסטינקט החיים ואינסטינקט המוות פועלים לרוב מתחת לסף המודעות, אך עם זאת יש להם השפעה עמוקה על המחשבות המודעות, על הרגשות ועל הפעולות.","mnemo":"⚡☠️ סתמי=ארוס+טנטוס"},{"id":"quiz12_25","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"לפי פרויד, תפקיד מנגנוני ההגנה: (שמירה מפני ביטויי הסתמי / הגנה מפני התנהגויות שליליות / הגנה מפני חרדה וקונפליקטים לא מודעים / שמירה שהאני עליון לא יהפוך נוקשה)","a":"להגן על האנשים מפני חרדה וקונפליקטים לא מודעים (התפקיד המרכזי של כל מנגנוני ההגנה)","explain":"לפי-פרויד, תפקידם-המרכזי-של <b>כל</b> מנגנוני-ההגנה: <b>להגן על-האדם מפני חרדה וקונפליקטים לא-מודעים</b> - הם פועלים (לרוב שלא-במודע) כדי-להפחית את-המתח-הפנימי הנוצר-מהתנגשות בין דרישות-הסתמי, האני-העליון, והמציאות. ⚠️ זהו-העיקרון-המאחד-את-כל-11-מנגנוני-ההגנה (הדחקה, השלכה, רציונליזציה, וכו') שנלמדו-בפרק - למרות-שכל-מנגנון פועל-בדרך-שונה-לגמרי, כולם משרתים <b>אותה-מטרה-בדיוק</b>: הגנה-על-הנפש מפני-חרדה-בלתי-נסבלת.","mnemo":"🛡️ מנגנון-הגנה=נגד-חרדה"},{"id":"quiz12_26","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"מי מהבאים אינו רצף בשאלון חמשת הגורמים? (פתיחות/סגירות / נועם הליכות/התנגדות / מוחצנות/מופנמות / ביטחון/חוסר ביטחון)","a":"ביטחון מול חוסר ביטחון (אינו אחד מחמשת הגורמים המוכרים - OCEAN)","explain":"'ביטחון מול-חוסר-ביטחון' <b>אינו</b> אחד-מחמשת-הגורמים-הרשמיים בשאלון-חמשת-הגדולים (OCEAN). ⚠️ חמשת-הגורמים-המוכרים-והמדויקים הם: <b>פתיחות/סגירות</b>, <b>מצפוניות/חוסר-אחריות</b>, <b>מוחצנות/מופנמות</b>, <b>נועם-הליכות/התנגדות</b>, ו<b>נוירוטיות/יציבות-רגשית</b> - 'ביטחון' עשוי-להישמע-קרוב-לנוירוטיות (יציבות-רגשית), אך זהו-שם-שגוי-שלא-מופיע-כפי-שהוא במודל-הרשמי - חשוב-לזכור-בדיוק את חמשת-השמות-הנכונים.","mnemo":"❌ ביטחון - לא באחד מ-5"},{"id":"quiz12_27","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"יונג האמין שהארכיטיפים הם: (תכונות משותפות לכולם / ייצוגים מהילדות המוקדמת / דחפים מהסתמי / דימויים-סמלים-נושאים אוניברסליים משותפים לתרבות האנושית)","a":"דימויים, סמלים ונושאים אוניברסליים, המשותפים לתרבות האנושית (חלק מהלא-מודע הקולקטיבי, לא אישי)","explain":"יונג הגדיר ארכיטיפים כחלק מהלא-מודע הקולקטיבי - לא תכונות אישיות, לא זיכרונות מהילדות האישית, ולא דחפי הסתמי (מושג פרוידיאני שיונג דחה) - אלא דימויים, סמלים ונושאים אוניברסליים (כמו הגיבור, אם האדמה) המשותפים לכל בני האנוש כתוצר המורשת הפסיכולוגית המשותפת של המין.","mnemo":"🌍 ארכיטיפים=סמלים אוניברסליים"},{"id":"quiz12_28","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"הנחה בסיסית על טבע האדם לפי הגישה ההומניסטית: (דומים בנטיות בסיסיות / מונעים מכוחות הליבידו / שואפים למימוש עצמי / תפיסות שליליות על העולם)","a":"שכל בני האדם שואפים למימוש והגשמה עצמית (ההנחה הבסיסית האופטימית של ההומניזם)","explain":"ההנחה-הבסיסית-האופטימית של-הגישה-ההומניסטית: <b>כל בני-האדם שואפים למימוש והגשמה-עצמית</b> - דחף-טבעי-ומולד להגיע-למיצוי מלוא-הפוטנציאל-האישי. ⚠️ זו-בניגוד-חד לתפיסות-אחרות שנלמדו-בפרק: <b>לא</b> נשלטים-על-ידי-דחפי-ליבידו (זו-הגישה-הפסיכודינמית), <b>לא</b> תפיסה-שלילית-כללית-על-העולם, ו<b>לא</b> רק-'דמיון-בנטיות-בסיסיות' (זה-חסר-את-הממד-האופטימי-הייחודי) - ההומניזם מייחד-את-עצמו דווקא-באמונה-החיובית-והמעודדת בכוח-הצמיחה-הטבעי-של-כל-אדם.","mnemo":"🌱 הומניזם=כולם שואפים למימוש"},{"id":"prof13_01","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"סכמו את שבעת הקריטריונים שבאמצעותם מתייגים התנהגות כהתנהגות אבנורמלית.","a":"(1) מצוקה/אי-יכולת. (2) התנהגות לא מסתגלת. (3) אי-רציונלית. (4) לא צפויה. (5) נדירה סטטיסטית+לא מקובלת. (6) אי-נוחות הצופה. (7) הפרת אמות מידה מוסריות.","explain":"(1) מצוקה או אי-יכולת - מצוקה אישית/תפקוד לקוי. (2) התנהגות לא מסתגלת - מפריעה ליעדים/רווחה. (3) התנהגות אי-רציונלית - לא הגיונית/לא מובנת. (4) התנהגות לא צפויה - תזזיתית, כאילו איבד שליטה. (5) התנהגות לא מקובלת ונדירה סטטיסטית - מפרה נורמות (אך נדירות לבדה לא מספיקה - גאונות נדירה ורצויה). (6) אי-נוחות הצופה - יוצר תחושת איום/מועקה. (7) הפרת אמות מידה מוסריות - הפרת ציפיות התנהגות מקובלת.","mnemo":"7️⃣ 7 קריטריונים לאבנורמליות"},{"id":"prof13_reflection1","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"זהו קריטריונים ב-3 סיפורים (עידן/פרידה, יותם/פרנויה, חמוטל/תאונה).","a":"עידן=מצוקה+לא מסתגלת. יותם=אי-רציונלית+לא מסתגלת. חמוטל=מצוקה+לא צפויה.","explain":"תרגיל-זיהוי הקריטריונים-לאבנורמליות (שנלמדו-בתחילת-הפרק: מצוקה, אי-הסתגלות, אי-רציונליות/מסוכנות, אי-צפיות) ביישום-על-שלושה-סיפורים: <b>עידן (פרידה)</b> - <b>מצוקה</b> (סובל רגשית באמת) + <b>לא-מסתגלת</b> (ההתנהגות פוגעת בתפקוד-היומיומי שלו). <b>יותם (פרנויה)</b> - <b>אי-רציונלית</b> (האמונות-שלו לא-מבוססות-במציאות) + <b>לא-מסתגלת</b> (ההתנהגות-הנובעת-מכך פוגעת-בו). <b>חמוטל (תאונה)</b> - <b>מצוקה</b> (סבל אמיתי) + <b>לא-צפויה</b> (התגובה חורגת-ממה-שהיה-צפוי/נורמלי בעקבות-אירוע-כזה). ⚠️ שימו-לב שכל-מקרה מדגים <b>שילוב-שונה</b> של שניים-מתוך-ארבעת-הקריטריונים - לא-כל-מקרה-אבנורמלי חייב-לכלול את-כל-הארבעה, אך צריך-לפחות-כמה-מהם-יחד כדי-להיחשב-אבנורמלי.","mnemo":"📖 3 סיפורים, 3 שילובי-קריטריונים"},{"id":"prof13_02","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מה הקושי בתיוג התנהגות אבנורמלית?","a":"אף קריטריון (מתוך 7) אינו הכרחי או מספיק לבדו (רוצח ללא מצוקה עדיין אבנורמלי; לא כל התנהגות לא-מסתגלת=אבנורמלית). ההבחנה היא מידת דמיון למערך קריטריונים, לא שני סוגים מובחנים - הפרעה=רצף, לא קטגוריה בינארית.","explain":"אף אחד מ-7 הקריטריונים, כשלעצמו, אינו מהווה תנאי הכרחי או מספיק. דוגמה לא הכרחי: רוצח ללא מצוקה אישית עדיין תויג אבנורמלי. דוגמה לא מספיק: לא כל מי שמתנהג באופן לא מסתגל יתויג אבנורמלי. ההבחנה אינה שני סוגים מובחנים, אלא מידת הדמיון למערך קריטריונים - ככל שיותר קריטריונים קיצוניים קיימים, כך מתחזק הביטחון באבנורמליות. הדרך הטובה: רצף מבריאות מיטבית ועד חולי מזערי.","mnemo":"⚖️ אף קריטריון לא מספיק לבד"},{"id":"prof13_03","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו: \"ההבחנה בין נורמלי לאבנורמלי היא יחסית\".","a":"אין קו גבול חד בין נורמלי לאבנורמלי - בריאות נפשית היא רצף, מבריאות מיטבית ועד חולי מזערי, עם דרגות ביניים הולכות וגוברות. שאלה של מידה, לא קטגוריה בינארית מוחלטת.","explain":"אין קו גבול חד וברור בין התנהגות נורמלית לאבנורמלית - יש לחשוב על בריאות נפשית כרצף (continuum): בקצה אחד בריאות נפשית מיטבית, בקצה השני בריאות נפשית מזערית, ובין הקצוות התנהגויות לא-מסתגלות במידה הולכת וגוברת בהדרגה. אין נקודת חיתוך אובייקטיבית - זוהי שאלה של מידה ודרגה, לא קטגוריה בינארית מוחלטת.","mnemo":"🌈 רצף, לא שחור-לבן"},{"id":"prof13_04","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע פסיכולוגים מוטרדים מבעיית האובייקטיביות באבחון אבנורמלי?","a":"משמעות התנהגות תלויה תמיד בהקשר (נשיקה=יחסים/ברכה/מאפיה, תלוי הקשר). דוגמאות היסטוריות (דרפטומאניה להצדקת עבדות) וניסוי רוזנהן (8 שפויים אושפזו, כל התנהגות פורשה כתומכת באבחנה) מראים ששיפוטי אבנורמליות מושפעים מגורמים מעבר להתנהגות עצמה.","explain":"ההחלטה להכריז על מישהו כלוקה בהפרעה היא תמיד שיפוט, לא עובדה אובייקטיבית טהורה - משמעות ההתנהגות תלויה תמיד בהקשר (נשיקה בין גברים=יחסים/ברכה/מאפיה, תלוי הקשר). דוגמאות היסטוריות מדאיגות: ד\"ר קרטרייט (1851) 'גילה' דרפטומאניה (שאיפת חופש אצל עבדים) כדי להצדיק עבדות. ניסוי רוזנהן הראה ששיפוטי אבנורמליות מושפעים מגורמים מעבר להתנהגות עצמה - עלולים לשקף דעות קדומות/כוח.","mnemo":"🔍 הקשר קובע הכל - נשיקה=שלום/מאפיה"},{"id":"prof13_05","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי בעיית האובייקטיביות באבחון פסיכופתולוגי? האם אפשר להתגבר עליה?","a":"אבחון הוא שיפוט, לא מדידה אובייקטיבית - משמעות התנהגות תלויה בהקשר/תרבות/מעמד המאבחן. ⚠️ אפשר לצמצם (לא לבטל) באמצעות מערכות אבחון מוסכמות (DSM) המגבירות עקביות בין מאבחנים - אך אובייקטיביות מלאה בלתי אפשרית, כי אותה התנהגות תמיד ניתנת לפרשנויות שונות לפי הקשר.","explain":"⚠️ אבחון הוא תמיד שיפוט של התנהגות, לא מדידה אובייקטיבית כמו ברפואה - משמעות ההתנהגות תלויה בהקשר/תרבות/רקע המאבחן. חלקית ניתן להתגבר: מערכות אבחון מוסכמות (DSM) מספקות קריטריונים ברורים ומגבירות עקביות בין מאבחנים. אך אובייקטיביות מלאה כנראה בלתי אפשרית - אותה התנהגות בדיוק תמיד ניתנת לפרשנויות שונות בהתאם להקשר, וגם מומחים מיומנים (רוזנהן) עלולים לפרש כל התנהגות בהתאם לתווית קיימת.","mnemo":"⚖️ שיפוט לא מדידה - DSM מצמצם לא מבטל"},{"id":"prof13_06","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תארו את מחקר רוזנהן והסבירו כיצד מדגים את בעיית האובייקטיביות.","a":"8 אנשים שפויים התאשפזו בטענה לחזיונות שווא בלבד; כולם אובחנו כסכיזופרנים/דו-קוטביים. לאחר האשפוז התנהגו נורמלית, אך הצוות פירש הכל (כולל תיעוד תצפיות) כתומך באבחנה - שוחררו רק בעזרת בני זוג, עם אבחנה \"בנסיגה\". מוכיח שתווית אבחונית מעצבת פרשנות כל התנהגות עוקבת, לא רק ראיות אובייקטיביות.","explain":"רוזנהן ועוד 7 אנשים שפויים (סה\"כ 8) התאשפזו בבתי חולים פסיכיאטריים, בטענה לסימפטום יחיד: חזיונות שווא (שמעו מילים כמו 'ריק', 'חלול'). מלבד זאת, דיווחו על חייהם האמיתיים במלואם. כולם אובחנו כסכיזופרנים/דו-קוטביים. מרגע האשפוז, התנהגו נורמלית לחלוטין - איש מהצוות לא זיהה אותם כשפויים (כ-3 שבועות בממוצע). כל התנהגות (כולל תיעוד תצפיות) פורשה בהתאם לתווית - שוחררו רק בעזרת בני זוג, עם אבחנה 'בנסיגה', לא 'בריא'. מדגים שתווית אבחונית מעצבת פרשנות כל התנהגות עוקבת, לא רק ראיות אובייקטיביות.","mnemo":"🏥 8 שפויים, כולם \"אובחנו\" - הקשר קובע"},{"id":"prof13_07","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע נזקקים לשיטת אבחון ומיון אחידה? דונו ב-3 יתרונות.","a":"שפה מקוצרת/מוסכמת=תקשורת יעילה בין אנשי מקצוע. הבנת סיבתיות=מסביר מדוע דפוסי סימפטומים מעידים על הפרעות ספציפיות. תכנית טיפול=מכוון לטיפול היעיל ביותר לכל הפרעה (תרופה לסכיזופרניה שונה מדיכאון).","explain":"שפה מקוצרת ומוסכמת - מאפשרת הבנה מהירה בין אנשי מקצוע; קטגוריה כמו 'דיכאון' מסכמת מידע מורכב.\nהבנת הסיבתיות - אבחון צריך להבהיר את הסיבות לסימפטומים, כי אותם סימפטומים עלולים לנבוע מהפרעות שונות.\nתכנית טיפול - אבחון מכוון לטיפול היעיל ביותר; תרופה לסכיזופרניה שונה מזו לדיכאון, ועלולה אף להזיק אם ניתנת בטעות.","mnemo":"3️⃣ שפה+סיבתיות+טיפול"},{"id":"prof13_08","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע קיימת הערכה מקיפה ב-DSM (לא רק המחלה עצמה)?","a":"כי אותם תסמינים יכולים לנבוע ממקורות שונים שאינם הפרעה נפשית אמיתית - אבל טבעי אחרי אבדן, או תופעות לוואי מתרופה גופנית, יכולים לחקות תסמיני דיכאון. ההערכה המקיפה (סימפטומים+מצב רפואי+גורמים פסיכו-חברתיים) נדרשת כדי למנוע אבחון שגוי המבוסס על דמיון שטחי בלבד.","explain":"כי אותם תסמינים בדיוק יכולים לנבוע ממקורות שונים שאינם הפרעה נפשית אמיתית. דוגמה: תסמיני דיכאון (לא אוכל, מדוכדך, שוכח, ישן הרבה) יכולים לנבוע מ(א) אבל טבעי אחרי אבדן אדם קרוב - לא הפרעה פתולוגית, או (ב) תופעות לוואי מתרופה ללחץ דם - בעיה רפואית-גופנית, לא נפשית. לכן יש להביא בחשבון 3 מרכיבים (סימפטומים, מצב רפואי, גורמים פסיכו-חברתיים) כדי למנוע אבחון שגוי המבוסס על דמיון שטחי בלבד.","mnemo":"🩹 תסמינים דומים, מקורות שונים (אבל/תרופה)"},{"id":"prof13_09","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי תחלואה כפולה ומה חשיבותה?","a":"הופעה בו-זמנית של יותר מהפרעה נפשית אחת (45% מהמאובחנים בהפרעה אחת מאובחנים בנוספת תוך שנה). חשיבותה: מלמדת על טיב ההבחנה בין אבחנות - אם הפרעות \"נפרדות\" תמיד מופיעות יחד, מעלה שאלות על מובחנותן האמיתית.","explain":"תחלואה כפולה (comorbidity) - הופעה בו-זמנית של יותר מהפרעה נפשית אחת. במחקר על בוגרים אמריקנים, 45% מהמאובחנים בהפרעה אחת אובחנו תוך 12 חודשים בהפרעה נוספת. חשיבותה: מלמדת על טיב ההבחנה בין אבחנות שונות - אם הפרעות 'נבדלות' תמיד מופיעות יחד, מעלה שאלות האם הן באמת מייצגות תופעות נפרדות ומובחנות, או חופפות/קשורות במקור.","mnemo":"2️⃣ תחלואה-כפולה=2+ הפרעות ביחד"},{"id":"prof13_10","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהן הסיבות לשינויים באבחנות בין מהדורות ה-DSM?","a":"(א) אימוץ גישת מחקר - הרחבת מידע, הסרת אבחנות ללא תיקוף (כמו סוגי סכיזופרניה). (ב) רצף הבריאות הנפשית - הוספת דרישה לציין חומרה (קלה/בינונית/חמורה). (ג) השפעות תרבותיות - שינויי תפיסה חברתית (הומוסקסואליות הוסרה כהפרעה), רגישות תרבותית (תסמונות תלויות-תרבות).","explain":"התמונה הגדולה: שלושת השינויים הללו משקפים התבגרות של כל תחום האבחון הפסיכיאטרי - מעבר משיפוט קליני סובייקטיבי (מה שהיה) לגישה מבוססת-מחקר (א), מהבחנה בינארית נוקשה (יש/אין הפרעה) לתפיסת רצף מדורגת יותר (ב), ומהתעלמות מהקשר תרבותי להכרה בכך שתרבות משפיעה על איך תסמינים מתבטאים (ג).","mnemo":"3️⃣ מחקר+רצף+תרבות משנים DSM"},{"id":"prof13_11","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מה הקשר בין הפרעות נפש לתרבות?","a":"תרבות משפיעה על תוכן קטגוריות האבחון וייצוג הסימפטומים. דוגמאות: הומוסקסואליות הוגדרה כהפרעה במהדורה 1, הוסרה במהדורה 3 (שינוי תרבותי-חברתי). תסמונות תלויות-תרבות (כמו פחד יפני מלהביך אחרים בגוף) נכללות כביטוי תרבותי ספציפי בתוך קטגוריות קיימות (חרדה חברתית).","explain":"התרבות משפיעה משמעותית על תוכן קטגוריות האבחון ועל האופן שבו מיוצגים סימפטומים. דוגמאות: (1) שינוי תפיסה חברתית - הומוסקסואליות הוגדרה כהפרעת נפש במהדורה הראשונה, הוסרה לחלוטין במהדורה השלישית. (2) תסמונות תלויות-תרבות - למשל, הפרעה יפנית של פחד רב-עצמה שגוף/הבעות האדם דוחים אחרים - כיום נכללת כביטוי אופייני יפני בתוך קטגוריית 'הפרעת חרדה חברתית' הקיימת. איגוד הפסיכיאטרים האמריקני רואה כיום בתרבות גורם המשפיע ישירות על ייצוג הסימפטומים.","mnemo":"🏳️‍🌈 הומוסקסואליות הוסרה - תרבות משפיעה על DSM"},{"id":"prof13_12","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהי אטיולוגיה? מדוע היא חשובה?","a":"מושג המתאר את הגורמים לבעיות נפשיות/רפואיות. חשובה כי ידע על מקורות ההפרעה יכול לסלול דרך לטיפולים חדשים, ובאופן אידיאלי - למנוע את ההפרעה מלכתחילה.","explain":"אטיולוגיה - מושג המתאר את הגורמים לבעיות נפשיות/רפואיות, או הגורמים התורמים להתפתחותן. חשיבותה: ידע על סיבת הופעתה של הפרעה, על מקורותיה, ועל האופן שבו היא משפיעה על החשיבה/רגשות/התנהגות - עשוי לסלול דרך לטיפולים חדשים, ובאופן אידיאלי, למנוע את ההפרעה.","mnemo":"🔑 אטיולוגיה=מפתח לטיפול+מניעה"},{"id":"prof13_13","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"סכמו את העקרונות האטיולוגיים המרכזיים לכל גישה (טבלה 1).","a":"ביולוגית=מבנה מוח/ביוכימיה/גנטיקה, סיבה ישירה. פסיכודינמית=הרחבת קונפליקט נפשי נורמלי (סתמי-אני-על), התנסויות ילדות. התנהגותית=נלמדת כמו כל התנהגות, נסיבות מווסתות בהווה. קוגניטיבית=עיוותי תפיסה/הסקה/פתרון בעיות. חברתית-תרבותית=תרבות מעצבת סוגי הפרעות ואבחון.","explain":"גישה ביולוגית - מודל רפואי; מייחסת הפרעות ישירות לגורמים ביולוגיים: אבנורמליות מבנית במוח, תהליכים ביוכימיים (נוירוטרנסמיטורים), השפעות גנטיות.\n\nגישה פסיכודינמית - הפרעות הן הרחבה של תהליכי קונפליקט נפשי והגנת האני הנורמליים; התנסויות מוקדמות מהילדות מעצבות התנהגות; מקור הסימפטומים בקונפליקטים בין סתמי לאני עליון.\n\nגישה התנהגותית - מתמקדת בתגובות נצפות; התנהגויות אבנורמליות נרכשות באותה הדרך כמו התנהגויות בריאות (למידה/חיזוק); מתמקדת בנסיבות המשמרות אותן כעת, לא בעבר.\n\nגישה קוגניטיבית - משלימה את ההתנהגותית; שורשי ההפרעות באופן שבו אדם תופס/חושב על עצמו/יחסיו עם הסביבה; עיוותי תפיסה, הסקה לקויה, פתרון בעיות כושל.\n\nגישה חברתית-תרבותית - מדגישה תפקיד התרבות באבחון ובאטיולוגיה גם יחד; נסיבות תרבותיות ספציפיות מגדירות סביבות המסייעות להתעוררות סוגי פסיכופתולוגיה.","mnemo":"5️⃣ 5 גישות, 5 עקרונות-סיבה"},{"id":"prof13_14","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו הקשר בין סיבות פסיכולוגיות לביולוגיות לפי הגישה המשלבת?","a":"נטייה גנטית (רמות נוירוטרנסמיטורים/הורמונים) יוצרת פגיעות/רגישות מוגברת להפרעה, אך אינה מספיקה לבדה - נדרשת גם עקה פסיכולוגית/חברתית או התנהגויות נלמדות כדי שההפרעה תתפתח במלואה. הגורם הביולוגי=פוטנציאל; הגורם הפסיכולוגי=הזרז שמפעיל אותו בפועל (מודל פגיעות-עקה).","explain":"נטייה גנטית המשפיעה על רמות הנוירוטרנסמיטורים/הורמונים (הגורם הביולוגי) עלולה לגרום לאדם להיות פגיע יותר להפרעה - אך זה לא מספיק לבדו. ייתכן שיש צורך נוסף בעקה פסיכולוגית/חברתית או בהתנהגויות נלמדות מסוימות (הגורם הפסיכולוגי/סביבתי), כדי שההפרעה תתפתח במלואה בפועל.\n\nהקשר: הגורם הביולוגי יוצר פוטנציאל/רגישות מוגברת - אך אינו מספיק כשלעצמו. הגורמים הפסיכולוגיים פועלים כטריגר/זרז שמפעיל את הפוטנציאל הביולוגי הקיים - שני סוגי הגורמים נחוצים יחד, בדפוס דו-כיווני. זהו מודל הפגיעות-עקה (diathesis-stress): פגיעות ביולוגית + טריגר פסיכולוגי-סביבתי = הפרעה בפועל.","mnemo":"🧬+😰 גנים=פגיעות, עקה=טריגר"},{"id":"prof13_15a_1","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תארו את הפרעת החרדה הכללית - סימפטומים והסבר אטיולוגי מרכזי.","a":"דאגה/חרדה כמעט תמידית, 6+ חודשים, ללא סכנה נראית-לעין; מתח שרירים, קשיי ריכוז ושינה. הסבר קוגניטיבי: רגישות-לחרדה (פירוש מפחיד לתחושות גוף) והטיית קשב לאיומים משמרות את הדאגה.","explain":"ההבחנה החשובה בהפרעת חרדה כללית (GAD): הדאגה כאן היא <b>מפושטת ולא-ממוקדת</b> - לא פחד מאובייקט/מצב ספציפי (זה יהיה פוביה), אלא תחושת חרדה כללית שנמשכת חודשים, בלי איום ברור וממשי מולה. <b>ההסבר הקוגניטיבי</b> מסביר איך זה נשמר: אנשים עם <b>רגישות-לחרדה</b> מפרשים תחושות גוף נייטרליות (למשל דופק מהיר אחרי מדרגות) כסימן-סכנה מפחיד ('אני עומד להתקף לב') - כך כל תחושה גופנית רגילה הופכת לטריגר-דאגה נוסף, ומעגל-הפחד מתחזק את עצמו. בנוסף, <b>הטיית קשב לאיומים</b> גורמת לאנשים אלו לשים לב יותר לרמזי-סכנה בסביבה, מה שמזין עוד יותר את הדאגה. <b>ההוכחה הניסויית</b>: צוערי חיל-אוויר עם רגישות-חרדה גבוהה מראש חוו התקפי-פניקה בשיעור 20%, לעומת רק 6% בקרב צוערים עם רגישות-חרדה נמוכה - מוכיח שהפרשנות הקוגניטיבית (לא רק המצב האובייקטיבי) קובעת מי יפתח את ההפרעה.","mnemo":"😰 דאגה תמידית בלי סיבה=GAD"},{"id":"prof13_15a_2","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תארו את הפרעת הפניקה (+אגורפוביה) - סימפטומים והסבר אטיולוגי מרכזי.","a":"התקפי פניקה בלתי-צפויים וחוזרים (עוררות אוטונומית קיצונית) + פחד מתמיד מהתקף הבא; לעיתים גם אגורפוביה (פחד ממקומות קשי-מנוס). הסבר ביולוגי: רמות גאבא נמוכות במוח קשורות לרגישות המוגברת להתקפים.","explain":"בהפרעת פניקה, ה<b>בלתי-צפויות</b> של ההתקפים היא בדיוק מה שהופך אותם למחלישים: האדם לא יכול לדעת מתי יגיע ההתקף הבא, ולכן מפתח <b>פחד-מהפחד</b> מתמיד - חרדה מתמשכת מפני האפשרות שהתקף יתרחש. כאשר הפחד מהתקפים גורם לאדם להימנע ממקומות שקשה לברוח מהם (תחבורה ציבורית, קניונים), מתפתחת <b>אגורפוביה</b> נלווית. <b>ההסבר הביולוגי</b> מצביע על תפקוד לקוי של הנוירוטרנסמיטר <b>גאבא</b> (GABA) - נוירוטרנסמיטר מעכב, שתפקידו הרגיל להרגיע את מערכת-העצבים; כאשר קולטני-הגאבא לא מתפקדים כראוי, המוח מתקשה 'לכבות' את תגובת-האזעקה הפיזיולוגית ברגע שהיא מופעלת, מה שמסביר את העוצמה הקיצונית של ההתקף. <b>ההוכחה הניסויית</b>: סריקות PET הראו הבדל ברור בתפקוד קולטני הגאבא בין חולי-פניקה לבין קבוצת ביקורת בריאה - עדות ישירה למנגנון הביולוגי המוצע.","mnemo":"💥 פחד-מהתקף-הבא=פניקה"},{"id":"prof13_15a_3","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תארו פוביות (חברתית/ספציפית) - סימפטומים והסבר אטיולוגי מרכזי.","a":"פחד עקשני ובלתי-רציונלי מעצם/מצב ספציפי, מוגזם ביחס לאיום האמיתי. הסבר ביולוגי: השערת המוכנות - נטייה אבולוציונית מולדת לפחד מגירויים ששימשו סכנה בעבר (עכבישים, גבהים - לא ממחטים או מעליות).","explain":"פוביה מוגדרת כפחד <b>מוגזם באופן לא-פרופורציונלי</b> לסכנה האמיתית שהאובייקט/המצב מהווה - זה בדיוק מה שמבדיל אותה מפחד רגיל (רציונלי). <b>השערת המוכנות (preparedness)</b> מציעה הסבר אבולוציוני מרתק: לאורך אבולוציית האדם, פחד מהיר ואוטומטי מגירויים מסוימים (נחשים, עכבישים, גבהים, סערות) העניק יתרון-הישרדות אמיתי לאבותינו - מי שפחד מהר מעכביש רעיל שרד יותר מ-'הסקפטיקן' שבדק תחילה אם הוא מסוכן. לכן, המוח האנושי 'מוכן' ביולוגית ללמוד פחדים כאלה מהר וביתר-קלות, יחסית לגירויים מודרניים (שקעים חשמליים, מכוניות) שלא היו קיימים בסביבה האבולוציונית. ⚠️ <b>המגבלה החשובה</b>: השערת המוכנות פשוט לא מסבירה פוביות מגירויים ללא היסטוריה אבולוציונית (פחד ממחטים, מנהיגה) - עבור אלו, ההסבר המתאים יותר הוא <b>התנייה קלאסית</b> (חוויה שלילית ישירה שיצרה את הקישור הפוביה).","mnemo":"🕷️🏔️ עכביש+גובה=מוכנות אבולוציונית"},{"id":"prof13_15a_4","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תארו את הפרעת הטורדנות-הכפייתית (OCD) - סימפטומים והסבר אטיולוגי מרכזי.","a":"מחשבות טורדניות חוזרות + פעולות כפייתיות טקסיות שמפחיתות חרדה זמנית - ולכן מתחזקות (חיזוק שלילי). קשור לרמות סרוטונין נמוכות ולאנומליות מוחיות ספציפיות (פחות מיילין בסיבי העצב).","explain":"המנגנון המרכזי ב-OCD הוא <b>לולאת חיזוק שלילי</b>: המחשבה הטורדנית (למשל 'הידיים שלי מלוכלכות') יוצרת חרדה עזה; הפעולה הכפייתית (שטיפת-ידיים) <b>מפחיתה את החרדה זמנית</b> - וההקלה הזו היא בדיוק מה שמחזק (בחיזוק שלילי - הסרת גירוי לא-נעים) את הפעולה הכפייתית, כך שבפעם הבאה שהמחשבה הטורדנית תחזור, האדם ירגיש דחף חזק עוד יותר לבצע את הטקס. ההסבר הביולוגי מצביע על <b>רמות סרוטונין נמוכות</b> (תרופות SSRI, המעלות סרוטונין, יעילות בטיפול) וכן על אנומליות מבניות במוח - פחות מיילין בסיבי-עצב מסוימים, מה שפוגע ביעילות התקשורת העצבית באזורים הקשורים לבקרת-דחפים. <b>ההוכחה הניסויית</b>: מטופלי OCD עם סימנים המתמקדים בניקיון זכרו טוב יותר עצמים שתויגו כ'מלוכלכים' לעומת 'נקיים' - מראה איך <b>הטיית-קשב</b> לתכנים הרלוונטיים-להפרעה מזינה ומשמרת את הטורדנות עצמה.","mnemo":"🔁🧼 מחשבה-חוזרת+רחיצה=OCD"},{"id":"prof13_15a_5","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תארו את הפרעת העקה הפוסט-טראומטית (PTSD) - סימפטומים והסבר אטיולוגי מרכזי.","a":"חוויה חוזרת של אירוע טראומטי (זיכרונות מייסרים, סיוטים, הבזקים-לאחור) בעקבות אירוע מסכן-חיים. מחקרי fMRI: ניצולי-טראומה בלי PTSD מראים פעילות רבה יותר באזורי עיבוד-רגשי (תלמוס קדמי) מניצולים עם PTSD.","explain":"מה שמבדיל PTSD מזיכרון-טראומטי רגיל הוא ה<b>חזרתיות הבלתי-רצונית</b> של החוויה - זיכרונות מייסרים, סיוטי-לילה, והבזקים-לאחור (flashbacks) שפורצים לתודעה שוב ושוב, כאילו האירוע קורה מחדש, בעקבות אירוע שאיים על החיים או השלמות הגופנית. <b>הממצא המפתיע והחשוב ביותר</b>: מחקרי fMRI השוו ניצולי-טראומה <b>שכן</b> פיתחו PTSD מול ניצולים <b>שלא</b> פיתחו אותה - ונמצא שדווקא אלו <b>ללא</b> PTSD הראו פעילות <b>רבה יותר</b> באזורי עיבוד-רגשי (כמו התלמוס הקדמי) בזמן עיבוד הזיכרון הטראומטי. המשמעות: יכולת לעבד את הזיכרון הטראומטי באופן רגשי-מלא (ולא לחסום אותו) דווקא <b>מגנה</b> מפני התפתחות ההפרעה - מי שהמוח שלו 'בורח' מעיבוד רגשי מלא של הטראומה הוא דווקא זה שבסיכון גבוה יותר לפתח PTSD. <b>ההוכחה הסטטיסטית</b>: כ-80% מהמבוגרים חווים אירוע טראומטי משמעותי בחייהם, אך רק 6.8% מפתחים PTSD בפועל - מוכיח שמשהו בתגובה האישית (לא רק חומרת האירוע עצמו) קובע מי יפתח את ההפרעה.","mnemo":"🎬 סרט-חוזר של הטראומה=PTSD"},{"id":"prof13_15b_1","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תארו את הפרעת הדיכאון הקשה - סימפטומים והסבר אטיולוגי מרכזי.","a":"עצב/ייאוש מתמשך, שינויי תיאבון ושינה, פיגור או אי-שקט מוטורי, אשמה, קשיי ריכוז, מחשבות התאבדות. הסבר קוגניטיבי (בק): השילוש הקוגניטיבי - דעה שלילית על העצמי, ההווה והעתיד.","explain":"המונח 'השילוש הקוגניטיבי' של אהרון בק מתאר דפוס-חשיבה אופייני לדיכאון: הערכה שלילית קבועה בשלושה מוקדים בו-זמנית - <b>העצמי</b> ('אני חסר-ערך'), <b>ההווה</b> ('הכל נורא עכשיו') ו<b>העתיד</b> ('זה לעולם לא ישתפר'). בק טען שדפוס-החשיבה הזה הוא לא רק <b>תוצאה</b> של הדיכאון אלא <b>גורם משמר</b> אותו - עיוותים קוגניטיביים (כמו הכללת-יתר, חשיבה-שחור-לבן) מסננים את המציאות כך שרק העדויות התומכות בעצב מתקבלות. <b>מחקר תומך מרכזי</b>: מרטין זליגמן חקר <b>חוסר-אונים נרכש</b> - כלבים שנחשפו למכות-חשמל <b>בלתי-נמנעות</b> (שלא יכלו להימנע מהן בשום פעולה) פיתחו בהמשך חוסר-מוטיבציה, פסיביות רגשית וקושי-למידה, <b>גם כאשר</b> ניתנה להם אפשרות אמיתית לברוח. המסקנה שזליגמן הסיק ליישום אנושי: כשאדם לומד (מניסיון חוזר) שהתנהגותו לא משפיעה על התוצאות, הוא מפתח תחושת חוסר-אונים כללית שדומה מאוד לתסמיני הדיכאון - גם כשבפועל יש לו כעת אפשרות לשנות את מצבו.","mnemo":"😢 עצב+שינה+אשמה=דיכאון-קשה"},{"id":"prof13_15b_2","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תארו את ההפרעה הדו-קוטבית - סימפטומים והסבר אטיולוגי מרכזי.","a":"תקופות דיכאון קשה המתחלפות באפיזודות מאניות - התרוממות-רוח קיצונית, ערך-עצמי מנופח, ירידה בצורך-שינה, נטילת סיכונים. הסבר ביולוגי: רמות גבוהות של סרוטונין/נוראפינפרין קשורות למאניה (רמות נמוכות קשורות לדיכאון).","explain":"ההבדל המהותי מדיכאון-קשה 'רגיל': בהפרעה הדו-קוטבית האדם <b>מתנדנד</b> בין שני קטבים קיצוניים - תקופות דיכאון עמוק, המתחלפות באפיזודות <b>מאניה</b> (התרוממות-רוח קיצונית, תחושת-ערך מנופחת עד גרנדיוזית, ירידה בצורך-שינה, נטילת סיכונים פזיזה כמו הוצאות-כספים מוגזמות). ה<b>הסבר הביולוגי</b> מבוסס על רמות נוירוטרנסמיטורים: רמות <b>גבוהות</b> של סרוטונין/נוראפינפרין נקשרות לאפיזודת המאניה, בעוד רמות <b>נמוכות</b> של אותם נוירוטרנסמיטורים נקשרות לצד הדיכאוני - כלומר, אותה מערכת ביוכימית 'נעה' בין שני קצוות במקום להישאר מאוזנת. ⚠️ נקודה קלינית חשובה: ההפרעה נדירה יותר מדיכאון-קשה (כ-3.9% מהאוכלוסייה הבוגרת, לעומת שכיחות גבוהה בהרבה של דיכאון). לרוב, אפיזודת-המאניה <b>מסתיימת בדיכאון עמוק</b>, בין השאר כי בשלב הפוסט-מאני האדם נאלץ להתמודד עם התוצאות וההשלכות (כספיות, חברתיות) של ההתנהגות הפזיזה שביצע במהלכה.","mnemo":"🎢 דיכאון↔️מאניה מתחלפים"},{"id":"prof13_15c_1","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תארו את הפרעת האישיות הגבולית - סימפטומים והסבר אטיולוגי מרכזי.","a":"חוסר-יציבות עצום ביחסים, קשיי שליטה בכעס, אימפולסיביות (כולל נזק-עצמי), פחד עז מנטישה. משלב תורשה חזקה (35% התאמה בתאומים זהים מול 7% בלא-זהים) וטראומה/התעללות מינית בילדות.","explain":"הפרעת האישיות הגבולית (BPD) מאופיינת ב<b>אי-יציבות מקיפה</b> - לא רק במצב-רוח, אלא ביחסים בין-אישיים (מעברים קיצוניים בין אידיאליזציה לביטול של אותו אדם), בדימוי-העצמי, ובשליטה-בדחפים (אימפולסיביות שעלולה לכלול פגיעה-עצמית). מאחורי כל אלו עומד <b>פחד עז מנטישה</b> - אמיתית או מדומיינת - שגורם לתגובות רגשיות קיצוניות. ⚠️ <b>הראיה החזקה ביותר</b> לאטיולוגיה המשולבת: מחקרי-תאומים מראים תורשתיות משמעותית (התאמה של 35% אצל תאומים זהים, לעומת רק 7% בלא-זהים - הבדל שמצביע על מרכיב גנטי אמיתי), <b>אך במקביל</b>, מחקר מצא ש-73.9% ממטופלות עם האבחנה דיווחו על התעללות מינית בילדות - לעומת רק 5.5% בקבוצת-ביקורת ללא ההפרעה. המסקנה: לא תורשה 'בלבד' ולא טראומה 'בלבד' - שילוב של פגיעות גנטית מולדת <b>יחד עם</b> חוויית-טראומה משמעותית בילדות הוא ההסבר המשכנע ביותר.","mnemo":"💔😱 חוסר-יציבות+פחד-נטישה=גבולית"},{"id":"prof13_15c_2","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תארו את הפרעת האישיות האנטי-חברתית - סימפטומים והסבר אטיולוגי מרכזי.","a":"דפוס מתמשך של חוסר-אחריות והפרת-חוק, בלי בושה או חרטה, מתחיל כבר בילדות. הסבר: אדישות רגשית תורשתית (מחקרי תאומים) בשילוב דפוסי הורות (דאגה הורית נמוכה, הגנת-יתר).","explain":"ההפרעה האנטי-חברתית מאופיינת בדפוס <b>עקבי וממושך</b> (לא אירוע חד-פעמי) של הפרת נורמות וחוקים חברתיים, <b>ללא</b> תחושת בושה, אשמה או חרטה על הפגיעה באחרים - וחשוב לציין שהדפוס הזה מתחיל כבר <b>בילדות</b> (לא מופיע פתאום בבגרות). ה<b>הסבר המשולב</b>: מחקרי-תאומים מצביעים על מרכיב תורשתי של <b>אדישות רגשית</b> - נטייה מולדת לתגובתיות-רגשית נמוכה (פחות פחד, פחות אמפתיה טבעית) - <b>בשילוב</b> עם דפוסי-הורות ספציפיים: דווקא <b>שני קטבים</b> נמצאו מסוכנים - הן דאגה הורית <b>נמוכה</b> מדי (הזנחה) והן הגנת-יתר <b>קיצונית</b> מדי, ששתיהן מונעות מהילד לפתח ויסות-רגשי ואחריות תקינים. ⚠️ נתון אפידמיולוגי: שכיחה משמעותית יותר בגברים (כ-3%) מאשר בנשים (כ-1%). נקודה קלינית מפתיעה: ההפרעה נמצאת לעיתים קרובות לצד <b>סיכון גבוה להתאבדות</b> - לא בגלל דיכאון בהכרח, אלא כתוצאה ישירה מהאימפולסיביות הכרונית האופיינית להפרעה.","mnemo":"🚫❤️ בלי-בושה+הפרת-חוק=אנטי-חברתית"},{"id":"prof13_15c_3","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תארו את הפרעות הניתוק (אמנזיה של ניתוק, DID) - סימפטומים והסבר אטיולוגי מרכזי.","a":"אמנזיה של ניתוק=אובדן זיכרון לחוויות אישיות חשובות, ללא הפרעה אורגנית. DID=2 אישויות מובחנות או יותר באדם אחד. הסבר פסיכודינמי: בריחה סמלית מהתעללות/טראומה קשה בילדות, דרך יצירת \"אישיות\" נפרדת שסופגת את הכאב.","explain":"שני מצבים שונים בתוך משפחת הפרעות-הניתוק: <b>אמנזיה של ניתוק</b> - אובדן זיכרון לחוויות אישיות חשובות (לרוב הקשורות לאירוע טראומטי), <b>ללא</b> כל סיבה אורגנית/נוירולוגית שיכולה להסביר את השִכחה (בניגוד לפגיעת-ראש למשל). <b>DID</b> (הפרעת-זהות-דיסוציאטיבית) - הופעת שתי 'אישיות' נבדלות או יותר, בעלות דפוסי-חשיבה והתנהגות שונים, בתוך אותו אדם. ה<b>הסבר הפסיכודינמי</b> רואה בכך מנגנון-הישרדות קיצוני: 'בריחה' סמלית ולא-מודעת מהתעללות או טראומה קשה בילדות, על-ידי יצירת 'אישיות' נפרדת שסופגת ו'מחזיקה' את הכאב הבלתי-נסבל, כך שהאישיות ה'ראשית' יכולה להמשיך לתפקד בלי לחוות אותו ישירות. ⚠️ <b>ביקורת חשובה ומהותית</b> (חובה לדעת לבחינה): קיים ויכוח מקצועי סוער סביב אבחנת DID - יש חשש מבוסס-מחקר שמטפלים 'מאמינים' עלולים, בתום-לב אך בטעות, <b>ליצור</b> את הסימפטומים בעצמם דרך שאלות מכוונות ורמיזות תחת היפנוזה או טיפול אינטנסיבי - כך שהאבחנה עצמה שנויה במחלוקת מקצועית משמעותית.","mnemo":"🎭 שכחה או ריבוי-אישויות=ניתוק"},{"id":"prof13_15d_1","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תארו את סימפטומי הסכיזופרניה - חיוביים מול שליליים.","a":"סימפטומים חיוביים (תוספת חריגה)=חזיונות שווא, מחשבות שווא, דיבור/התנהגות לא-מאורגנים. סימפטומים שליליים (חוסר בתפקוד רגיל)=נסיגה חברתית, שטיחות רגשית.","explain":"הטריק לזכירה שקל להתבלבל בו: המילים 'חיוביים' ו'שליליים' <b>לא</b> מתייחסות ל'טוב' או 'רע' מבחינה מוסרית - הן מתייחסות אך ורק ל<b>כיוון-השינוי</b> ביחס לתפקוד רגיל. <b>סימפטומים חיוביים</b> = <b>תוספת</b> חריגה של משהו שלא אמור להיות שם בתפקוד תקין - חזיונות-שווא (הזיות, למשל שמיעת קולות), מחשבות-שווא (אמונות כוזבות קבועות), דיבור או התנהגות לא-מאורגנים. <b>סימפטומים שליליים</b> = <b>חוסר</b> במשהו שכן אמור להיות קיים בתפקוד רגיל - נסיגה חברתית, שטיחות-רגשית (אפקט מוגבל, חוסר הבעת רגש בפנים/בקול), ירידה במוטיבציה. הבחנה זו חשובה קלינית כי הסימפטומים החיוביים בדרך-כלל מגיבים טוב יותר לתרופות אנטי-פסיכוטיות, בעוד הסימפטומים השליליים עמידים יותר לטיפול תרופתי.","mnemo":"➕➖ תוספת-חריגה מול חוסר-בתפקוד"},{"id":"prof13_15d_2","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהם ההסברים האטיולוגיים המרכזיים לסכיזופרניה?","a":"תורשה חזקה (מחקרי תאומים/אימוץ מבודדים גנטיקה מסביבה) יוצרת נטייה, אך גורם-עקה סביבתי נדרש כדי שההפרעה תתפרץ בפועל (השערת הנטייה-לעקה) - למשל, רגש מובע גבוה במשפחה (ביקורת/עוינות) מנבא הישנות סימפטומים.","explain":"מודל ההסבר המקובל ביותר לסכיזופרניה הוא <b>השערת הנטייה-לעקה</b> (diathesis-stress model): תורשה חזקה (מחקרי-תאומים ומחקרי-אימוץ, שמצליחים לבודד את מרכיב הגנטיקה מהסביבה) יוצרת <b>נטייה/פגיעות</b> (diathesis) מולדת להפרעה - <b>אך</b> הנטייה הגנטית לבדה <b>אינה מספיקה</b>: נדרש גם <b>גורם-עקה סביבתי</b> (stress) שיפעיל את הפוטנציאל הגנטי בפועל ויגרום להתפרצות ההפרעה. דוגמה מרכזית לגורם-עקה סביבתי: <b>רגש מובע גבוה</b> במשפחה - סביבה ביתית עתירת ביקורתיות, עוינות, או מעורבות-רגשית-יתר - נמצאה כמנבאת חזק להישנות (רלפס) סימפטומים אצל חולים שכבר אובחנו. ⚠️ <b>ההוכחה החזקה ביותר לדגם המשולב</b>: אפילו בקרבת-הדם הגנטית הגבוהה ביותר (למשל תאום זהה של חולה סכיזופרניה), הסיכון לפתח את ההפרעה נשאר <b>נמוך מ-50%</b> - כלומר, גם עם חפיפה גנטית מושלמת, יותר ממחצית לא מפתחים את ההפרעה בכלל. זו ההוכחה הברורה ביותר שגנים לבדם לא-מספיקים, וגורם-עקה סביבתי הוא הכרחי כדי ש'הכדור ייצא לירי'.","mnemo":"🧬+😰 תורשה+עקה=סכיזופרניה מתפרצת"},{"id":"prof13_17","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"במה שונים סימפטומי הפרעה דו-קוטבית מדיכאון?","a":"דיכאון=רק תקופות דיכאון. דו-קוטבית=תקופות דיכאון+אפיזודות מאניות מתחלפות (התרוממות רוח, ערך עצמי מנופח, ירידת צורך בשינה, נטילת סיכונים).","explain":"דיכאון קשה כולל רק תקופות דיכאון (עצב, ייאוש, פיגור). הפרעה דו-קוטבית כוללת גם תקופות דיכאון וגם אפיזודות מאניות מתחלפות - התרוממות רוח קיצונית (או רגזנות), ערך עצמי מנופח, ירידה בצורך בשינה, נטילת סיכונים חסרי בסיס. ההבדל המהותי: דיכאון=קוטב אחד (שלילי בלבד); דו-קוטבית=שני קטבים מנוגדים המתחלפים.","mnemo":"🎢 דו-קוטבית=דיכאון+מאניה | דיכאון=רק-למטה"},{"id":"prof13_reflection2","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"אילו עקרונות קוגניטיביים באים לידי ביטוי בתיאוריית מערכי בק?","a":"מדגימה שבעיות פסיכולוגיות נובעות מעיוותי תפיסה (מערך קוגניטיבי שלילי), לא מהמציאות עצמה - השילוש הקוגניטיבי (עצמי/הווה/עתיד) מעצב פרשנות שלילית של כל חוויה.","explain":"תיאוריית בק ממחישה את העיקרון המרכזי של הגישה הקוגניטיבית: בעיות פסיכולוגיות נובעות מעיוותים בתפיסת המציאות, לא מהמציאות האובייקטיבית עצמה. השילוש הקוגניטיבי (דעה שלילית על העצמי/ההווה/העתיד) הוא דוגמה למערך קוגניטיבי (cognitive set) - דפוס תפיסה קבוע המעצב את הפרשנות (לא את האירועים עצמם). מדגים גם את עקרון 'האופן שבו בני אדם תופסים/חושבים על עצמם' - העיקרון הכללי של הגישה הקוגניטיבית.","mnemo":"3️⃣ עצמי+הווה+עתיד שליליים=בק"},{"id":"prof13_18","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו חוסר אונים נרכש, כיצד מסביר דיכאון, ומהן סיבותיו?","a":"חוסר אונים נרכש=חוסר מוטיבציוני/רגשי/קוגניטיבי, מגירויים מכאיבים בלתי נשלטים (זליגמן). דיכאון=ציפייה שכל פעולה חסרת משמעות. סיבות סביבתיות=חוסר שליטה חוזר. סיבות קוגניטיביות=סגנון הסבר פנימי-יציב-כללי לכישלונות.","explain":"חוסר אונים נרכש (זליגמן ומאייר) - מצב שנוצר כשאורגניזם חווה גירויים מכאיבים בלתי נשלטים (ללא קשר להתנהגותו), ומפתח 3 סוגי חסר: מוטיבציוני (אטיות בפעולות), רגשי (נוקשות/פחד), קוגניטיבי (למידה דלה במצבים חדשים, אפילו כשאפשר להימלט).\n\nכיצד מסביר דיכאון: אנשים דיכאוניים שרויים במצב דומה - מצפים שכל פעולה תהיה חסרת משמעות.\n\nסיבות סביבתיות: התנסות חוזרת במצבים שבהם התוצאה אינה תלויה בהתנהגות.\n\nסיבות קוגניטיביות (סגנון הסבר): תלוי באופן שהאדם מפרש כישלון - 3 ממדים: פנימי-חיצוני, יציב-לא יציב, כללי-ספציפי. מי שמייחס כישלון לגורמים פנימיים, יציבים וכלליים מועד לדיכאון.","mnemo":"🐕⚡ כלבים+מכות-בלתי-נמנעות=חוסר-אונים"},{"id":"prof13_19","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"תארו את מחקר הזיכרונות המשמחים/עצובים ומדוע משקף הסבר קוגניטיבי לדיכאון.","a":"משתתפים בדיכאון/החלימו/ביקורת ניסו לשלוף זיכרונות משמחים/עצובים ללא לחץ זמן. משתתפים בדיכאון פעיל התקשו מאוד לשלוף זיכרונות משמחים (בניגוד להחלימו/ביקורת) - מדגים עיבוד תואם מצב רוח: הטיית זיכרון סלקטיבית למידע לא-חיובי, תואמת עקרון קוגניטיבי שעיוותי עיבוד מידע משמרים דיכאון.","explain":"26 משתתפים בדיכאון (19 החלימו) וקבוצת ביקורת (29) ניסו לדווח על האירועים המשמחים והעצובים ביותר בחייהם, ללא לחץ זמן. עוזרי מחקר (ללא ידיעת מצב המשתתף) העריכו כמה מאמץ הושקע בשליפת כל זיכרון.\n\nממצאים: משתתפים בדיכאון פעיל התקשו מאוד לשלוף זיכרונות משמחים (בהשוואה לעצובים ולקבוצות האחרות). משתתפים שהחלימו הראו דפוס דומה לביקורת. גם תוכן הזיכרונות המשמחים ששלפו הדיכאוניים היה ספציפי פחות.\n\nמדוע משקף הסבר קוגניטיבי: מדגים עיבוד תואם מצב רוח - קושי סלקטיבי לשלוף מידע חיובי שאינו תואם מצב הרוח הנוכחי - הטיית זיכרון זו תואמת את עקרון הגישה הקוגניטיבית שעיוותי עיבוד מידע (לא המציאות עצמה) יוצרים/משמרים דיכאון.","mnemo":"😊😢 דיכאוניים לא מצליחים לשלוף זיכרון-שמח"},{"id":"prof13_reflection3","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"אילו שאלות ישאלו את יהונתן פסיכולוגים מ-4 הגישות (ביולוגית, פסיכודינמית, התנהגותית, קוגניטיבית)?","a":"⚠️ שאלות מומחשות. ביולוגי=היסטוריה משפחתית/שינה/תיאבון. פסיכודינמי=אבדן לאחרונה, יחסי ילדות, כעס מודחק. התנהגותי=חיזוקים חיוביים לפני הדיכאון, תגובת סביבה. קוגניטיבי=מחשבות ספציפיות על עצמו/הווה/עתיד (השילוש הקוגניטיבי).","explain":"⚠️ שאלות מומחשות.\nביולוגי - האם יש היסטוריה משפחתית של דיכאון? שינויים בתיאבון/שינה/אנרגיה? תרופות המשפיעות על מצב הרוח?\nפסיכודינמי - האם חווית אבדן לאחרונה? כיצד היו יחסיך עם הוריך בילדות? האם אתה חש כעס המופנה כעת כלפי עצמך?\nהתנהגותי - אילו חיזוקים חיוביים היו בחייך לפני הדיכאון? כיצד הגיבה הסביבה כשהתחלת להרגיש עצוב? הפסקת פעילויות מספקות?\nקוגניטיבי - אילו מחשבות עוברות לך בראש במטלה פשוטה? מה אתה חושב על עצמך/ההווה/העתיד? מדוע אתה מפרש שאחרים מתרחקים ממך?","mnemo":"4️⃣ 4 מטפלים, 4 סוגי שאלות ליהונתן"},{"id":"prof13_20","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"אילו גישות מסבירות הבדלי דיכאון בין נשים לגברים?","a":"סביבתית - נשים חוות יותר אירועים שליליים (התעללות, עוני, נטל טיפול). קוגניטיבית - נשים נוטות יותר לחיטוט עצמי (מהרהרות בסיבות/השלכות עצב), מגביר עוצמת רגשות שליליים; גברים מסיחים דעת באמצעות פעילות.","explain":"גישה סביבתית - נשים חוות יותר אירועים שליליים/גורמי עקה: התעללות גופנית/מינית, עוני, נטל טיפול בילדים/הורים זקנים.\n\nגישה קוגניטיבית (חיטוט עצמי) - נשים נוטות יותר לחיטוט עצמי (rumination) - מהרהרות בסיבות/השלכות העצב; גברים נוטים לסלק תחושות באמצעות הסחת דעת/פעילות גופנית. חיטוט עצמי מגביר עוצמת/משך רגשות שליליים, מגביר פגיעות לדיכאון.","mnemo":"⚖️👩 נשים=חיטוט-עצמי, גברים=הסחת-דעת"},{"id":"prof13_21","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מה הקושי באבחון הפרעת אישיות?","a":"(1) חפיפה בין הפרעות - אותן התנהגויות תורמות לכמה אבחונים שונים. (2) קשה לקבוע מתי תכונה קיצונית (כמו תלות) הופכת מגיוון נורמלי להפרעה ממשית - אין גבול אובייקטיבי.","explain":"(1) חפיפה בין הפרעות - כמה מאותן ההתנהגויות תורמות לאבחונים של הפרעות שונות, מקשה להבחין ביניהן. (2) הגבול בין נורמלי לאבנורמלי - מרבית בני האדם נמצאים במידה מסוימת על כל ממד אישיות (למשל, תלות באחרים) - השאלה היא מתי תכונה קיצונית מספיק כדי להיחשב הפרעה, לא רק גיוון נורמלי. אין קו גבול אובייקטיבי וברור.","mnemo":"🔀 חפיפה+גבול-מטושטש=קושי-אבחון"},{"id":"prof13_22","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע קיים ספק לגבי קיום הפרעת זהות מנותקת?","a":"אין נתוני שכיחות מוצקים; מטפלים \"מאמינים\" עלולים ליצור את ההפרעה בעצמם (שאלות מכוונות תחת היפנוזה). מנגד, יש ראיות (נתוני התעללות) התומכות בקיום אמיתי. כנראה שילוב - חלק מקרים אמיתיים, חלק תגובה לדרישות המטפל.","explain":"ספקנים טוענים: אין נתונים מוצקים על שכיחות ההפרעה. מטפלים ה'מאמינים' ב-DID עלולים ליצור אותה בעצמם - מציגים שאלות, לעתים תחת היפנוזה, בדרך המעודדת 'הופעת' אישויות מרובות (סוגסטיה טיפולית).\n\nמנגד: פסיכולוגים אחרים טוענים שיש די ראיות (כמו נתוני התעללות מובהקים) המצדיקות אבחון אמיתי.\n\nמסקנה סבירה: בקרב המאובחנים כ-DID, כמה מקרים אמיתיים, ואחרים מופיעים בתגובה לדרישות המטפל - קשה להבחין בוודאות.","mnemo":"🤔 ספק: מטפל יוצר או חושף?"},{"id":"prof13_23","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע חשוב לבדוק הבדלי מוח בסכיזופרניה?","a":"מספק ראיה אובייקטיבית לבסיס ביולוגי מעבר להתנהגות; מבודד תרומת גורמים לא-גנטיים (תאומים זהים עם/בלי ההפרעה הראו מוח שונה); מסייע לזהות סמנים ביולוגיים לאבחון מוקדם וזיהוי סיכון.","explain":"מספק ראיה ישירה ואובייקטיבית לבסיס הביולוגי של ההפרעה (חדרי מוח מוגדלים, קליפת מוח דקה יותר), מעבר להתנהגות הנצפית בלבד. מאפשר בידוד גורמים - למשל, מחקר בתאומים זהים שרק אחד לקה בהפרעה (גנטיקה קבועה) הראה פעילות מוחית שונה - מוכיח שההבדל אינו רק גנטי. מסייע לזהות סמנים ביולוגיים - אינדיקטורים מדידים שעשויים לסייע באבחון מוקדם וזיהוי אוכלוסיות בסיכון.","mnemo":"🧬 תאום-זהה שונה=לא-רק-גנים"},{"id":"prof13_24","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מה מאפיין משפחות חולי סכיזופרניה, וכיצד קשור לאטיולוגיה?","a":"חריגות בתקשורת (פחות תגובתיות/רגישות), רגש מובע גבוה (ביקורת/מעורבות יתר/עוינות) מנבא נסיגה בסימפטומים. תומך בהשערת נטייה-לעקה: סביבה משפחתית=גורם עקה שמזרז הפרעה אצל בעלי נטייה גנטית, לא גורם יחיד. לא ברור אם משפחה גורמת או מגיבה לחולה.","explain":"משפחות מאופיינות בחריגות בתקשורת הורית - קושי לחלוק מוקד עניין משותף, לראות מנקודת מבט אחר, לתקשר בבהירות - פחות תגובתיות ורגישות בין-אישית.\n\nרגש מובע (expressed emotion) גבוה (ביקורת רבה, מעורבות רגשית מופרזת/הגנת-יתר, עוינות) קשור לנסיגה בסימפטומים (50% נסיגה במשפחות ברגש מובע גבוה, לעומת 17% בנמוך).\n\nהקשר לאטיולוגיה: תומך בהשערת נטייה-לעקה - הסביבה המשפחתית פועלת כגורם עקה המזרז/מחמיר את ההפרעה אצל מי שכבר בעל נטייה גנטית, לא כגורם יחיד. לא ברור אם הדפוסים המשפחתיים גורמים לסכיזופרניה, תגובה לחולה, או שניהם.","mnemo":"👪 משפחה-ביקורתית=רגש-מובע-גבוה"},{"id":"prof13_25","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד גורמים יחסי הגומלין בין תורשה לסביבה להתפרצותה של הפרעה נפשית?","a":"הגנוטיפ לבדו לא קובע הפרעה, וגם אירועי עקה לבדם לא - כל קבוצות הגנוטיפ חוו כמות דומה של אירועים שליליים. אך אותם אירועים בדיוק השפיעו אחרת לפי הגנוטיפ: אצל נושאי הגרסה הרגישה יותר, העקה הגבירה משמעותית סיכון לדיכאון. כלומר, תורשה קובעת רגישות/פגיעות, וסביבה (עקה) מספקת את הטריגר שמפעיל אותה בפועל - אינטראקציה, לא גורם יחיד.","explain":"⚠️ ההיגיון, לא הנתונים הספציפיים. במחקר על גן הסרוטונין (2 גרסאות) ואירועי חיים שליליים: הגנוטיפ לבדו לא קבע מי ילקה בדיכאון, וגם אירועי העקה לבדם לא - כל קבוצות הגנוטיפ חוו כמות דומה של אירועים שליליים. אך אותם אירועים בדיוק השפיעו אחרת לפי הגנוטיפ: אצל נושאי הגרסה 'הרגישה' יותר, אותם אירועים הגבירו משמעותית סיכון לדיכאון; אצל נושאי הגרסה 'הפחות רגישה' - לא.\n\nהמשמעות: הגנוטיפ אינו קובע ישירות אם אדם ילקה, אלא קובע את מידת הרגישות לאירועי סביבה שליליים. תורשה קובעת רגישות, וסביבה (עקה) מספקת את הטריגר שמפעיל אותה בפועל - אינטראקציה, לא גורם יחיד (מודל נטייה-לעקה).","mnemo":"🧬+😰 לא-לבד, לא-לבד - שילוב"},{"id":"prof13_26","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"האם יש לזכות אדם מביצוע פשע על בסיס אי-שפיות?","a":"⚠️ דיון מאוזן. בעד: אי-שפיות אמיתית (כמו מקנוטן) שוללת הבנה/שליטה - ענישה רגילה לא הגיונית; 90% מהמזוכים עדיין תחת השגחה פסיכיאטרית ממושכת, לא \"משתחררים\". נגד/הסתייגות: המושג מעורפל (לא מוגדר ב-DSM), אך נדיר בפועל (0.31% מכתבי אישום, 4.2% הצלחה) - לא \"פרצה\" נפוצה. מסקנה: הצדקה למקרים קיצוניים אמיתיים, עם קריטריונים מחמירים.","explain":"⚠️ דיון מאוזן. רקע: אי-שפיות אינה מוגדרת ב-DSM - מושג מתחום התרבות והמשפט. חוק מקנוטן (1843): לא שפוי אם אינו מבין את טיב הפעולה, או ידע אך לא ידע שאסור.\n\nבעד: מקרים ברורים (כמו מקנוטן, שהאמין שאלוהים הורה לו) - ענישה רגילה לא הגיונית ללא הבנה. כ-90% מהמזוכים נותרים תחת השגחה פסיכיאטרית ממושכת, לא 'משתחררים'.\n\nנגד/הסתייגות: הגדרה מעורפלת, קשה ליישום עקבי. אך נדיר בפועל (0.31% מכתבי אישום כוללים טענה, ורק 4.2% מצליחים) - לא ניצול נרחב לרעה. מקרים אפורים (כמו פוביה - 'יודע' אך לא שולט) מראים שהגבול בין הבנה לשליטה אינו תמיד ברור.\n\nמסקנה מאוזנת: הצדקה עקרונית למקרים חריגים וקיצוניים אמיתיים, בתנאי שהחלופה היא טיפול/השגחה, לא שחרור - עם קריטריונים ברורים ומחמירים ליישום.","mnemo":"⚖️ אי-שפיות: נדיר אך מוצדק לקיצוניים"},{"id":"prof13_27","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"איזו השפעה יש לתווית השלילית (סטיגמה) על חייהם של חולי נפש?","a":"גורמת לפיטורין (6%), סירוב השכרת דיור (10%), הימנעות חברתית (37%), פגיעה רגשית (45%) - ונשארת גם לאחר שיפור בבריאות הנפשית. יוצרת נבואה מגשימה את עצמה: ציפייה לדחייה גורמת בפועל להתנהגות פחות תקינה ותפיסה כ\"מתוח יותר\" (מחקר Farina). מגע קודם עם חולי נפש מפחית את ההשפעה השלילית.","explain":"תווית שלילית, סטיגמה (stigma) - מערך עמדות שליליות כלפי פרט, הרואות בו בלתי רצוי. אינה עומדת במבחן המציאות (46.4% מהבוגרים בארה\"ב חוו הפרעה פסיכולוגית כלשהי בחייהם - נורמלי סטטיסטית).\n\nמקורות: תקשורת המונים המציגה חולים כאלימים, בדיחות, הכחשת משפחות, מינוח משפטי.\n\nהשפעות מתועדות (84 גברים שאושפזו): 6% פוטרו מעבודה; 10% נתקלו בסירוב השכרת דיור; 37% דיווחו שאנשים נמנעו מלפגוש אותם; 45% דיווחו שמישהו השתמש בעברם הפסיכיאטרי כדי לפגוע ברגשותיהם; רק 6% לא נתקלו בדחייה כלל. גם לאחר שיפור ניכר בבריאות, התווית לא השתנתה.\n\nנבואה מגשימה את עצמה: מחקר קלאסי (Farina) - גברים שהאמינו שיועץ 'יודע' שהם חולים פסיכיאטרים לשעבר דיברו פחות, תפקדו פחות טוב, ודורגו כ'מתוחים וחרדים יותר' - ציפייה לדחייה יוצרת דחייה בפועל.\n\nנקודה מנחמת: מגע קודם עם חולי נפש מפחית משמעותית את השפעת התוויות.","mnemo":"📉 6-10-37-45% - סטיגמה פוגעת בכל תחום"},{"id":"quiz13_1","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"תפיסות חושיות הנתפסות כאמיתיות, למרות שאינן קיימות מכונות: (הלוצינציות / דלוזיות / פסיכוזה / מחלה)","a":"הלוצינציות (תפיסה חושית מלאה ללא גירוי אמיתי מאחוריה)","explain":"<b>הלוצינציות (חזיונות-שווא)</b> - תפיסות-חושיות הנחוות <b>כאמיתיות-לחלוטין</b>, למרות ש<b>אינן קיימות במציאות כלל</b> - למשל, שמיעת-קולות שאין-מקורם-בשום-גירוי-חיצוני-אמיתי. ⚠️ אל-תתבלבלו עם 'דלוזיות' (מחשבות-שווא - אמונות-כוזבות, לא-תפיסות-חושיות) - הלוצינציה היא-חוויה <b>חושית</b> (רואים/שומעים/מרגישים משהו-שלא-קיים), בעוד דלוזיה היא-<b>אמונה</b> (חושבים-משהו-שגוי-על-המציאות) - שני-תופעות-שונות-לגמרי שקל-להתבלבל-בהן.","mnemo":"👁️ הלוצינציה=רואה-מה-שלא-קיים"},{"id":"quiz13_2","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"נטייה גנטית + לחצים סביבתיים משפיעים על סיכון לסכיזופרניה. משפט זה מתאר: (תחלואה משותפת / סמן ביולוגי / סטיגמה / השערת נטייה לעקה)","a":"השערת נטייה לעקה (שילוב גנטיקה+סביבה יוצר את הסיכון בפועל)","explain":"המשפט מתאר <b>השערת הנטייה-לעקה (diathesis-stress model)</b> - עיקרון-מרכזי-בהבנת סכיזופרניה (ומחלות-נפשיות-רבות-נוספות): <b>נטייה-גנטית</b> (diathesis, פגיעות-מולדת) <b>בשילוב</b> עם <b>לחצים-סביבתיים</b> (stress) - שני-הגורמים-יחד, לא-אחד-לבדו, קובעים-את-הסיכון-בפועל להתפתחות-ההפרעה. ⚠️ אל-תתבלבלו עם 'תחלואה-משותפת' (מתאר לקות-ביותר-מהפרעה-אחת-בו-זמנית, לא-שילוב-גנטיקה-וסביבה) - השערת-הנטייה-לעקה היא-בדיוק המודל-שמסביר <b>איך</b> נוצר-הסיכון, לא-מה-קורה-כשיש-כמה-הפרעות-יחד.","mnemo":"🧬+😰 נטייה-לעקה=שילוב"},{"id":"quiz13_3","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"הפרעות אישיות ופיגור שכלי נמצאים על ציר ___ ב-DSM-IV: (I / II / III / IV)","a":"II (הפרעות אישיות/פיגור מסווגות בנפרד מהפרעות קליניות עיקריות בציר I)","explain":"הפרעות-אישיות ופיגור-שכלי נמצאים על <b>ציר II</b> ב-DSM-IV - מסווגים <b>בנפרד</b> מהפרעות-קליניות-עיקריות (כמו דיכאון, חרדה, סכיזופרניה) שנמצאות על <b>ציר I</b>. ⚠️ ההיגיון-לחלוקה: ציר-I מתאר הפרעות-אקוטיות/אפיזודיות-יותר (יש-'התקף' או 'פרק' של ההפרעה); ציר-II מתאר דפוסים <b>יציבים ומתמשכים לאורך-כל-החיים</b> (הפרעת-אישיות היא-חלק-מ'מי-שהאדם-הוא', לא-אפיזודה-חולפת) - חשוב-לזכור שאדם יכול לקבל אבחנות <b>בשני-הצירים-גם-יחד</b> (למשל, דיכאון על-ציר-I + הפרעת-אישיות-גבולית על-ציר-II).","mnemo":"2️⃣ אישיות+פיגור=ציר II"},{"id":"quiz13_4","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"באיזו הפרעה נפשית קיים שילוב של פגיעה במודעות, זיכרון וזהות אישית: (חרדה / פסיכוזה / PTSD / הפרעת ניתוק)","a":"הפרעת ניתוק (פגיעה בו-זמנית במודעות/זיכרון/זהות - ההגדרה המדויקת)","explain":"<b>הפרעת-ניתוק (dissociative disorder)</b> היא ההפרעה-הנפשית שבה קיים שילוב <b>בו-זמני</b> של פגיעה <b>במודעות, בזיכרון, ובזהות-האישית</b> - זו-בדיוק-ההגדרה-המדויקת: תחושת-ניתוק מהמציאות/מעצמך, לעיתים עד-כדי אובדן-זיכרון לחלקים-מהזהות-האישית (כמו-באמנזיה-של-ניתוק, או DID, שנלמדו-בפרק). ⚠️ אל-תתבלבלו עם-האפשרויות-האחרות (חרדה, פסיכוזה, PTSD) - כולן-כוללות-מרכיבים-מסוימים-דומים (למשל, PTSD כולל-לעיתים flashbacks), אך רק הפרעת-הניתוק מוגדרת ספציפית סביב <b>שלושת-המרכיבים-הללו-יחד</b> (מודעות+זיכרון+זהות).","mnemo":"3️⃣ מודעות+זיכרון+זהות=ניתוק"},{"id":"quiz13_6","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"איזה משפט נכון בהקשר להתאבדות: (אינם מחפשים עזרה / לא ניתן לעצור / שיחה גלויה עשויה למנוע / מי שמדבר לא יתאבד)","a":"שיחה גלויה עם אדם הסובל ממחשבות אובדניות עשויה למנוע את פעילותו (מיתוס מסוכן שדיבור \"מזמין\" התאבדות - ההפך הוא הנכון)","explain":"המשפט-הנכון: <b>שיחה גלויה</b> עם אדם-הסובל-ממחשבות-אובדניות <b>עשויה-למנוע</b> את-פעילותו-בפועל. ⚠️ זהו-תיקון-של <b>מיתוס-מסוכן ונפוץ</b> - רבים חוששים ש'לדבר-על-זה' עלול 'לזרוע-רעיון' או 'להזמין' התאבדות; המחקר-מראה <b>ההפך-בדיוק</b>: פתיחת-שיחה-כנה-וגלויה על-מחשבות-אובדניות היא-אחד-הכלים-החשובים-ביותר-במניעה, כי היא מאפשרת-לאדם להרגיש-נראה, לא-לבד, ולקבל-עזרה. שאר-האפשרויות ('אינם-מחפשים-עזרה', 'לא-ניתן-לעצור', 'מי-שמדבר-לא-יתאבד') הן-כולן <b>מיתוסים-מסוכנים-נוספים</b> שהמחקר-הפריך.","mnemo":"🗣️ שיחה גלויה מצילה, לא מזמינה"},{"id":"quiz13_7","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"מה אינו מאפיין אפיזודה מאנית: (עלייה בפעילויות מכוונות מטרה / דיבור יתר / ירידה חדה בתחושת הערך / צורך מופחת בשינה)","a":"ירידה חדה בתחושת הערך (מאניה=עלייה בערך עצמי, לא ירידה)","explain":"'ירידה-חדה-בתחושת-הערך' <b>אינה</b> מאפיינת אפיזודה-מאנית - זה <b>ההפך-המדויק</b> ממה-שקורה-במאניה: מאניה מאופיינת <b>בעלייה</b> בתחושת-הערך-העצמי (עד-כדי גרנדיוזיות, תחושת-כוח-מוגזמת), <b>לא</b> ירידה. ⚠️ שאר-המאפיינים (עלייה-בפעילויות-מכוונות-מטרה, דיבור-יתר, צורך-מופחת-בשינה) הם-כולם <b>סימפטומים-אמיתיים ונכונים</b> של-מאניה - התשובה-הנכונה היא-דווקא-זו-שמתארת-את-ההפך (ירידה-בערך-עצמי, שמאפיינת דיכאון, לא-מאניה).","mnemo":"📈 מאניה=עלייה, לא ירידה בערך"},{"id":"quiz13_8","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"התקף פניקה עשוי לכלול: (כאבים בחזה / סחרחורת / תחושת עילפון / כל התשובות נכונות)","a":"כל התשובות נכונות (כל אלה תסמינים גופניים אופייניים להתקף פניקה)","explain":"התקף-פניקה עשוי-לכלול <b>את-כל</b> התסמינים-הגופניים-שהוזכרו - כאבים-בחזה, סחרחורת, ותחושת-עילפון - <b>כולם תסמינים-אופייניים</b> להתקף-פניקה, הנובעים מ<b>עוררות אוטונומית-קיצונית</b> (הפעלת-הענף-הסימפתטי בעוצמה-חריגה). ⚠️ זו-הדגמה-חשובה לכך שהתקף-פניקה הוא-חוויה <b>פיזיולוגית-עוצמתית ורב-מערכתית</b>, לא-רק-'תחושת-פחד' פשוטה - הגוף-כולו 'מגיב' בו-זמנית במגוון-דרכים, מה-שמסביר-גם-למה אנשים-רבים בהתקף-פניקה-ראשון חושבים שהם-חווים התקף-לב.","mnemo":"💯 כל התסמינים הגופניים=פניקה"},{"id":"quiz13_9","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"ארי חושב שהוא מנהל בכיר במשרד ממשלתי. סובל ממחשבות שווא של: (רדיפה / גדלות / קנאה / דלוזיה)","a":"גדלות (אמונה כוזבת בחשיבות/כוח עצמי מופרז)","explain":"ארי, החושב-שהוא-מנהל-בכיר-במשרד-ממשלתי (למרות-שאינו-כזה), סובל ממחשבות-שווא-של <b>גדלות</b> - אמונה-כוזבת ב<b>חשיבות/כוח-עצמי-מופרז</b>, שאינה-תואמת-את-המציאות. ⚠️ הבדילו-מהמסיחים: מחשבות-שווא-של-<b>רדיפה</b> היו-מתאימות-אם-ארי-חשב-שרודפים-אותו/מנסים-לפגוע-בו; <b>קנאה</b> - אמונה-כוזבת-שבן/בת-הזוג-בוגד/ת; <b>'דלוזיה'</b> - זהו-המונח-הכללי (מחשבת-שווא) עצמו, לא-סוג-ספציפי - השאלה מבקשת-לזהות איזה <b>סוג</b> של-דלוזיה, וזה-בדיוק-גדלות.","mnemo":"👑 \"אני מנהל בכיר\"=גדלות"},{"id":"quiz13_10","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"שירי סובלת מהתנהגויות מוטוריות מוגזמות ומשונות. סביר שהיא סובלת מסכיזופרניה: (לא מאורגנת / קטטונית / פרנואידית / שרידית)","a":"קטטונית (מאופיינת בהפרעות תנועה קיצוניות - לא בסימפטומים אחרים)","explain":"שירי, הסובלת-מהתנהגויות-מוטוריות-מוגזמות-ומשונות, סביר-שסובלת מסכיזופרניה <b>קטטונית</b> - תת-סוג המאופיין-ספציפית ב<b>הפרעות-תנועה-קיצוניות</b> (קיפאון-תנועתי מוחלט, או לחלופין תנועתיות-מוגזמת-וחריגה), <b>לא</b> בסימפטומים-אחרים כמו-הזיות-או-מחשבות-שווא-בעיקר. ⚠️ הבדילו-מהתת-סוגים-האחרים: <b>לא-מאורגנת</b> (דיבור/התנהגות-מבולבלים, לא-דווקא-תנועתיים-קיצוניים), <b>פרנואידית</b> (מתמקדת-במחשבות-רדיפה/גדלות, לא-בתנועה) - קטטונית היא-הספציפית-ביותר לתסמינים-מוטוריים-חריגים.","mnemo":"🕺 תנועה מוזרה=קטטונית"},{"id":"quiz13_11","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"גליה חרדה/מוטרדת כל היום כבר למעלה משנה. לוקה, כנראה, ב: (פניקה / אגורפוביה / חרדה כללית / טורדנות-כפייתית)","a":"הפרעת חרדה כללית (דאגה נרחבת ומתמשכת, לא התקפים נקודתיים)","explain":"סימפטומים:\nהפרעת חרדה כללית - דאגה/חרדה מרבית הזמן, 6+ חודשים, ללא סכנה נראית; מתח שרירים, עייפות, אי-שקט, קשיי ריכוז/שינה.\nהפרעת פניקה (+אגורפוביה) - התקפי פניקה בלתי צפויים, עוררות אוטונומית, פחד מהתקף הבא; אגורפוביה=פחד ממקומות שקשה להימלט מהם.\nפוביות (ספציפיות/חברתית) - פחד עקשני ובלתי רציונלי מעצם/מצב/מבט זרים, מוגזם ביחס לאיום האמיתי.\nטורדנות-כפייתית (OCD) - מחשבות טורדניות חוזרות + פעולות כפייתיות טקסיות המפחיתות זמנית חרדה.\nעקה פוסט-טראומטית (PTSD) - הישנות טראומה (זיכרונות/חלומות/הבזקים), בעקבות טראומה קשה.\n\nהסברים אטיולוגיים (לפי העיקרון המרכזי של כל גישה):\nביולוגי - השערת המוכנות (נטייה אבולוציונית לפחד מגירויים ששימשו סכנה קדומה); רמות גאבא/סרוטונין נמוכות; אנומליות מוחיות ב-OCD; מרכיב גנטי.\nפסיכודינמי - פוביה/OCD כניסיון סמלי להתיק/להימנע מקונפליקט מודחק מהילדות.\nהתנהגותי - פוביות=פחד מותנה (התניה קלאסית, כמו אלברט הקטן); OCD נשמר כי הכפייתיות מפחיתה חרדה=חיזוק שלילי.\nקוגניטיבי - הפרזה בהערכת איום/המעטה ביכולת התמודדות; רגישות לחרדה (פירוש מפחיד לתחושות גופניות); הטיית קשב לגירויים מאיימים.","mnemo":"📅 שנה שלמה של דאגה=חרדה כללית"},{"id":"quiz13_12","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"מחקרי fMRI: ל-PTSD יש שיבושים ___ באזורי מוח שנועדו ל___: (מוגבלים;תכנון לעתיד / נרחבים;זיכרונות רגשיים / נרחבים;תכנון לעתיד / מוגבלים;זיכרונות רגשיים)","a":"נרחבים; זיכרונות רגשיים (PTSD פוגע באזורים המעבדים זיכרון טראומטי)","explain":"מחקרי fMRI מראים ש-PTSD קשור לשיבושים <b>נרחבים</b> באזורי-מוח שנועדו לעיבוד <b>זיכרונות-רגשיים</b> - כלומר, הפגיעה <b>אינה-מוגבלת</b> לאזור-קטן-ומבודד, אלא משפיעה-על-רשת-רחבה-של-אזורים האחראים-לעיבוד-זיכרון-בעל-מטען-רגשי (כמו-הטראומה-עצמה). ⚠️ אל-תתבלבלו עם 'תכנון-לעתיד' - זה-לא-הפוקוס-המרכזי-של-הממצאים-במחקרי-PTSD; הבעיה-המרכזית קשורה-ל<b>עיבוד-הזיכרון-הטראומטי-עצמו</b>, כפי-שנלמד-גם-בשאלה-אחרת-בפרק (ניצולי-טראומה-בלי-PTSD מראים פעילות-רבה-יותר באזורי-עיבוד-רגשי מניצולים-עם-PTSD).","mnemo":"🧠 PTSD=שיבוש נרחב בזיכרון-רגשי"},{"id":"quiz13_13","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"איזה סגנון ייחוס מגביר סיכון לדיכאון: (חיצוני-כללי-לא יציב / פנימי-כללי-יציב / חיצוני-ספציפי-לא יציב / פנימי-ספציפי-יציב)","a":"פנימי-כללי-יציב (מייחס כישלון לעצמו, לכל התחומים, לתמיד - הכי מסוכן לדיכאון)","explain":"סגנון-הייחוס <b>פנימי-כללי-יציב</b> מגביר-הכי-הרבה סיכון-לדיכאון - כלומר, מייחסים כישלון (1) ל<b>עצמם</b> (פנימי, לא-לנסיבות), (2) ל<b>כל-התחומים בחיים</b> (כללי, לא-ספציפי-לתחום-אחד), ו-(3) ל<b>לתמיד</b> (יציב, לא-זמני-וחולף). ⚠️ שילוב-שלושת-הממדים-האלה-יחד הוא-הכי-מסוכן, כי הוא-יוצר תחושה ש'אני-אשם, בכל-דבר, ולעולם-לא-ישתנה' - זהו-בדיוק-הבסיס לתיאוריית 'חוסר-האונים-הנרכש' של-זליגמן (שנלמדה-בפרק), המקשרת-בין-סגנון-ייחוס-שלילי לדיכאון.","mnemo":"🎯 אני-תמיד-בכל=הכי מסוכן"},{"id":"quiz13_14","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"טל שקוע/ה מאוד בהרהורים כשקורה משהו רע. סביר: (הסתברות שווה / פוביה ספציפית / סביר יותר אישה / סביר יותר גבר)","a":"סביר יותר שטל היא אישה (חיטוט עצמי שכיח יותר אצל נשים)","explain":"אדם השקוע-מאוד בהרהורים (rumination) כשקורה-משהו-רע - סביר-<b>יותר שזו אישה</b>. ⚠️ ממצא-אמפירי-עקבי במחקר-הפסיכולוגי: <b>חיטוט-עצמי/הרהור-חוזר-ונשנה</b> (rumination) על-בעיות-ורגשות-שליליים שכיח-יותר-סטטיסטית אצל-נשים מאשר-אצל-גברים - זו-אחת-ההסברים-המוצעים לשכיחות-הגבוהה-יותר-של-דיכאון בקרב-נשים (הרהור-ממושך נוטה-להאריך-ולהעצים מצבי-רוח-שליליים, במקום-לעזור-לפתור-אותם).","mnemo":"👩 חיטוט-עצמי=נשי יותר"},{"id":"quiz13_15","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"לדאוג יותר מכל אם לרינה תהיה צורת ___ של גן הסרוטונין, נוסף על ___ אירועי עקה: (l/l;ארבעה / s/l;שני / s/s;שלושה / s/l;שלושה)","a":"s/s; שלושה (גרסה גנטית רגישה + עקה רבה = הסיכון הגבוה ביותר)","explain":"הסיכון-הגבוה-ביותר לדאגה-מוגברת (או דיכאון) מתקבל משילוב של <b>גרסה-גנטית s/s</b> ('קצרה-קצרה') של גן-הסרוטונין <b>יחד-עם</b> <b>שלושה</b> אירועי-עקה (לא-פחות). ⚠️ זו-דוגמה-נוספת-וישירה לעיקרון השערת-הנטייה-לעקה (diathesis-stress) שנלמד-קודם בפרק: גרסה-גנטית-מסוימת (s/s) יוצרת <b>רגישות-מוגברת</b> - אך היא-לבדה <b>לא-מספיקה</b>; רק <b>בשילוב</b> עם-כמות-משמעותית-של-אירועי-עקה (כאן, שלושה) הסיכון-בפועל עולה-דרמטית - שוב, גנטיקה+סביבה גם-יחד, לא-אחד-לבדו.","mnemo":"🧬+3️⃣ s/s + 3 אירועים=סיכון מקסימלי"},{"id":"quiz13_16","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"חווה אינה לוקה בחוסר תפקוד אורגני, אך שוכחת לעתים קרובות חוויות אישיות חשובות: (סומטיזציה / אישיות תלותית / אמנזיה של ניתוק / היפוכונדריה)","a":"אמנזיה של ניתוק (שכחה פסיכולוגית, לא נזק מוחי פיזי)","explain":"חווה, שאינה-לוקה-בחוסר-תפקוד-אורגני (אין-בעיה-נוירולוגית-פיזית) אך שוכחת-לעתים-קרובות חוויות-אישיות-חשובות - סובלת <b>מאמנזיה של ניתוק</b>: שכחה <b>פסיכולוגית</b> (לא-נזק-מוחי-פיזי) לחוויות-אישיות-משמעותיות, לרוב-קשורה-לטראומה. ⚠️ המילה-המכרעת בשאלה: '<b>אינה לוקה בחוסר-תפקוד-אורגני</b>' - זה-בדיוק מה-שמבדיל אמנזיה-של-ניתוק (שכחה-נפשית-טהורה) מבעיות-זיכרון-הנובעות-מפגיעה-מוחית-פיזית (למשל, מקרה ה'מ שנלמד בפרק-הזיכרון) - כאן הבעיה-פסיכולוגית-בלבד, לא-נוירולוגית.","mnemo":"🕳️ שוכחת בלי פגיעה-מוחית=אמנזיה-ניתוק"},{"id":"quiz13_17","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"איזה מהסימפטומים הוא סימפטום שלילי של סכיזופרניה: (שפה לא ברורה / חזיונות שווא / מחשבות שווא / התרחקות מהחברה)","a":"התרחקות מהחברה (סימפטום שלילי=חיסרון בתפקוד, לא תוספת חריגה)","explain":"<b>התרחקות מהחברה</b> (נסיגה-חברתית) היא סימפטום <b>שלילי</b> של-סכיזופרניה - כלומר, <b>חיסרון</b> בתפקוד-שכן-אמור-להיות-קיים (מעורבות-חברתית-רגילה), לא-תוספת-חריגה. ⚠️ אל-תתבלבלו עם-האפשרויות-האחרות (שפה-לא-ברורה/מאורגנת, חזיונות-שווא, מחשבות-שווא) - כל-אלה הם סימפטומים <b>חיוביים</b> (תוספת חריגה שלא-אמורה-להיות-שם) - זכרו את-הטריק שנלמד-בפרק: חיוביים=תוספת (הזיות, מחשבות-שווא, דיבור-מבולבל), שליליים=חיסרון (נסיגה-חברתית, שטיחות-רגשית) - לא-קשור-ל'טוב/רע' מוסרית.","mnemo":"👥 מתרחקת=סימפטום שלילי"},{"id":"quiz13_18","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"הסבירות שמתי יחווה התפרצות מחודשת קטנה יותר אם רמת ה___ במשפחתו ___: (רגש מובע;נמוכה / רגש מובע;גבוהה / אמפתיה;נמוכה / עוינות;גבוהה)","a":"רגש מובע; נמוכה (פחות ביקורת/מעורבות יתר במשפחה=פחות הישנות)","explain":"הסבירות-שמתי-יחווה התפרצות-מחודשת (רלפס) <b>קטנה-יותר</b> אם רמת-ה<b>רגש-המובע</b> במשפחתו <b>נמוכה</b>. ⚠️ 'רגש-מובע' (expressed emotion) הוא-מדד-לסביבה-משפחתית עתירת <b>ביקורתיות, עוינות, או מעורבות-רגשית-יתר</b> - כפי-שנלמד-בפרק, רגש-מובע-<b>גבוה</b> נמצא-כמנבא-חזק להישנות-סימפטומים אצל-חולי-סכיזופרניה; לכן, רגש-מובע <b>נמוך</b> (סביבה-משפחתית-רגועה-ותומכת-יותר) מפחית-את-הסיכון-להתפרצות-חוזרת - זהו-בדיוק-הגורם-הסביבתי (stress) בהשערת-הנטייה-לעקה.","mnemo":"👪⬇️ רגש-מובע-נמוך=פחות הישנות"},{"id":"quiz13_19","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"השימוש בהגנה מחמת אי-שפיות ___ למדי וסיכויי הצלחתה ___ למדי: (נפוץ;נמוכים / נפוץ;גבוהים / נדיר;גבוהים / נדיר;נמוכים)","a":"נדיר; נמוכים (הגנת אי-שפיות נדירה בפועל ומצליחה לעיתים רחוקות)","explain":"⚠️ דיון מאוזן. רקע: אי-שפיות אינה מוגדרת ב-DSM - מושג מתחום התרבות והמשפט. חוק מקנוטן (1843): לא שפוי אם אינו מבין את טיב הפעולה, או ידע אך לא ידע שאסור.\n\nבעד: מקרים ברורים (כמו מקנוטן, שהאמין שאלוהים הורה לו) - ענישה רגילה לא הגיונית ללא הבנה. כ-90% מהמזוכים נותרים תחת השגחה פסיכיאטרית ממושכת, לא 'משתחררים'.\n\nנגד/הסתייגות: הגדרה מעורפלת, קשה ליישום עקבי. אך נדיר בפועל (0.31% מכתבי אישום כוללים טענה, ורק 4.2% מצליחים) - לא ניצול נרחב לרעה. מקרים אפורים (כמו פוביה - 'יודע' אך לא שולט) מראים שהגבול בין הבנה לשליטה אינו תמיד ברור.\n\nמסקנה מאוזנת: הצדקה עקרונית למקרים חריגים וקיצוניים אמיתיים, בתנאי שהחלופה היא טיפול/השגחה, לא שחרור - עם קריטריונים ברורים ומחמירים ליישום.","mnemo":"🎲 נדיר להשתמש, נדיר להצליח"},{"id":"quiz13_20","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"במחקר על התווית השלילית, כ-___ מהמשתתפים דיווחו שלא נתקלו במקרי דחייה: (6% / 22% / 43% / 74%)","a":"6% (רוב המוחלט כן נתקל בדחייה כלשהי בעקבות התווית)","explain":"במחקר-על-התווית-השלילית (סטיגמה), רק כ-<b>6%</b> מהמשתתפים דיווחו <b>שלא-נתקלו</b> במקרי-דחייה בעקבות-האבחנה-הפסיכיאטרית-שלהם. ⚠️ המשמעות: <b>הרוב-המוחלט</b> (94%) <b>כן-נתקל בדחייה-כלשהי</b> - נתון-מדהים המדגיש עד-כמה סטיגמה-חברתית כלפי-הפרעות-נפשיות היא-נפוצה ומהווה-מכשול-ממשי-ומשמעותי בחיי-אנשים-המתמודדים-עם-אבחנה-פסיכיאטרית, מעבר-להפרעה-עצמה.","mnemo":"6️⃣ מיעוט קטן לא נתקל בדחייה"},{"id":"quiz13_21","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"מטרת התרגיל (ריאיון אנשים שהחלימו מהפרעות פסיכולוגיות): (לדרבן השפעה יותר / להפחית בקשת טיפול / לא להשפיע / לדרבן השפעה פחות)","a":"לדרבן את הסטודנטים להיות מושפעים פחות מן התווית השלילית של מחלות נפש (מגע עם מי שהחלים מפחית סטיגמה)","explain":"תווית שלילית, סטיגמה (stigma) - מערך עמדות שליליות כלפי פרט, הרואות בו בלתי רצוי. אינה עומדת במבחן המציאות (46.4% מהבוגרים בארה\"ב חוו הפרעה פסיכולוגית כלשהי בחייהם - נורמלי סטטיסטית).\n\nמקורות: תקשורת המונים המציגה חולים כאלימים, בדיחות, הכחשת משפחות, מינוח משפטי.\n\nהשפעות מתועדות (84 גברים שאושפזו): 6% פוטרו מעבודה; 10% נתקלו בסירוב השכרת דיור; 37% דיווחו שאנשים נמנעו מלפגוש אותם; 45% דיווחו שמישהו השתמש בעברם הפסיכיאטרי כדי לפגוע ברגשותיהם; רק 6% לא נתקלו בדחייה כלל. גם לאחר שיפור ניכר בבריאות, התווית לא השתנתה.\n\nנבואה מגשימה את עצמה: מחקר קלאסי (Farina) - גברים שהאמינו שיועץ 'יודע' שהם חולים פסיכיאטרים לשעבר דיברו פחות, תפקדו פחות טוב, ודורגו כ'מתוחים וחרדים יותר' - ציפייה לדחייה יוצרת דחייה בפועל.\n\nנקודה מנחמת: מגע קודם עם חולי נפש מפחית משמעותית את השפעת התוויות.","mnemo":"🤝 מגע עם מי-שהחלים=פחות סטיגמה"},{"id":"quiz13_22","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"המושג תחלואה כפולה מתייחס ל: (הפרעה פסיכוטית עם פחד ממוות / לוקה ביותר מהפרעה אחת בו-זמנית / הפרעה נוירוטית קשה לרפא / אי-אפשר לאבחן לפי DSM-IV-TR)","a":"אדם לוקה ביותר מהפרעה פסיכולוגית אחת בו-בזמן (זו ההגדרה המדויקת של תחלואה כפולה)","explain":"<b>תחלואה כפולה (comorbidity)</b> מתייחסת ל<b>אדם הלוקה-ביותר-מהפרעה-פסיכולוגית אחת בו-זמנית</b> - למשל, דיכאון-וחרדה-גם-יחד, או הפרעת-אישיות-לצד-הפרעת-חרדה (כפי-שראינו-במקרה-המבחן על-OCD+הפרעת-אישיות-סכיזואידית בתחילת-הפרק). ⚠️ זו-ההגדרה-המדויקת-והפשוטה - <b>לא</b> קשור-לפחד-ממוות, לא-מתאר-'הפרעה-קשה-לרפא' באופן-כללי, ולא-קשור-לבעיית-אבחון-לפי-ה-DSM - פשוט: שתי (או-יותר) הפרעות-נפרדות, אצל-אותו-אדם, באותו-פרק-זמן.","mnemo":"2️⃣ שתי הפרעות ביחד=תחלואה כפולה"},{"id":"quiz13_23","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"לדעת פרופסור לוי, הפרעות פסיכולוגיות הן תוצאה של קונפליקטים לא מודעים. איזו גישה: (חברתית-תרבותית / קוגניטיבית / פסיכודינמית / התנהגותית)","a":"פסיכודינמית (קונפליקטים לא-מודעים=העיקרון המרכזי של גישה זו)","explain":"פרופסור-לוי, הטוען שהפרעות-פסיכולוגיות נובעות מ<b>קונפליקטים לא-מודעים</b>, מייצג את הגישה <b>הפסיכודינמית</b>. ⚠️ 'קונפליקטים-לא-מודעים' הוא-בדיוק-המושג-המרכזי בגישה-הפסיכודינמית (שמקורה-בפרויד) - בניגוד-לגישות-האחרות: <b>קוגניטיבית</b> תדגיש מחשבות-מודעות/עיוותי-חשיבה, <b>התנהגותית</b> תדגיש למידה/חיזוקים, <b>חברתית-תרבותית</b> תדגיש נורמות-חברתיות - רק-הפסיכודינמית מתמקדת-ספציפית ב<b>כוחות-לא-מודעים</b> כמקור-להפרעה.","mnemo":"🧠 קונפליקטים-לא-מודעים=פסיכודינמית"},{"id":"quiz_exam_backward_cond","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"התניית ___ נרכשת כאשר גירוי מותנה מוצמד לגירוי בלתי מותנה לא נעים, הגורם לאורגניזם לנסות להימנע מהגירוי המותנה: (עכבה / בו זמנית / לאחור / הימנעות)","a":"לאחור (backward conditioning) (הגירוי הלא-נעים מוצג לפני הגירוי המותנה, בסדר הפוך)","explain":"<b>התניה לאחור (backward conditioning)</b> - וריאציה-מיוחדת של-התניה-קלאסית, שבה <b>סדר-ההצגה הפוך</b> מהרגיל: הגירוי-הבלתי-מותנה (הלא-נעים) מוצג <b>לפני</b> הגירוי-המותנה, במקום-אחריו (כמו-בהתניה-הרגילה/מושהית שנלמדה-בפרק-הלמידה). <b>התוצאה</b>: האורגניזם לומד <b>להימנע</b> מהגירוי-המותנה, כי הוא-הפך-להיות סימן-מוקדם/רמז לכך <b>שהאירוע-הלא-נעים כבר-קרה או עומד-לחזור בקרוב</b> - הקישור-הנלמד הוא-הפוך-בכיוונו-הזמני מהתניה-רגילה. ⚠️ הבדילו-מהמסיחים: 'עכבה' ו'בו-זמנית' אינם-שמות-רשמיים-לסוגי-התניה-בפרק; 'הימנעות' מתאר את-ה<b>תוצאה-ההתנהגותית</b> (מה-שהאורגניזם עושה בסוף), <b>לא</b> את-שם-הפרוצדורה-הניסויית-עצמה (שהיא-בדיוק 'התניה-לאחור', המוגדרת-לפי-<b>סדר-הצגת-הגירויים</b>).","mnemo":"⏪ סדר-הפוך=התניה-לאחור"},{"id":"quiz_exam_cbt_examanx","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"לפי שיטות טיפול קוגניטיביות, סטודנטים ירגישו פחות חרדה במבחן אם יזכרו ש: (שום דבר מהותי בעתידם לא תלוי בתוצאות המבחן / תוצאות המבחן לא ישפיעו על הערכתם כבני אדם / תוצאות המבחן אינן משקפות במאה אחוז את הידע שרכשו / יש מועד נוסף לשיפור הציון / כל הנ\"ל)","a":"כל הנ\"ל (כל אחת מהתשובות מפריכה מחשבה קטסטרופלית שונה)","explain":"הטיפול-הקוגניטיבי לחרדת-בחינות פועל <b>בדיוק</b> לפי-אותו-עיקרון-כללי של-שינוי-אמונות-שגויות שנלמד-בפרק-הטיפולים (בק, אליס): מזהים <b>מחשבות-קטסטרופליות</b> ספציפיות ומפריכים-כל-אחת-מהן-בנפרד. <b>ארבע המחשבות-השגויות</b> שכל-תשובה-מפריכה: <b>(1)</b> 'הכל תלוי-בזה' (בפועל, רוב-העתיד <b>לא</b> תלוי-במבחן-בודד-אחד). <b>(2)</b> 'זה קובע-מי-אני' (בפועל, ציון <b>לא</b> משקף-ערך-אישי/הערכה-כאדם). <b>(3)</b> 'זה משקף-הכל' (בפועל, מבחן <b>לא</b> תמיד-משקף-במדויק את-הידע-האמיתי-שנרכש). <b>(4)</b> 'אין-הזדמנות-נוספת' (בפועל, <b>יש</b> לרוב מועד-נוסף-לשיפור). ⚠️ מכיוון שכל-אחת-מהתשובות מנטרלת <b>אמונה-קטסטרופלית-שונה-לגמרי</b>, וכולן-תורמות-יחד להפחתת-החרדה, התשובה-הנכונה היא 'כל-הנ'ל' - זו-בדיוק ההדגמה-המעשית לעיקרון שנלמד-בפרק: זיהוי, אתגור, והחלפה של-כמה-אמונות-שגויות-שונות בו-זמנית.","mnemo":"💥 כל תשובה שוברת קטסטרופה אחרת"},{"id":"quiz_exam_iq_digitspan","sec":"שאלת המרצה ⭐ (תרגול)","type":"open","imp":true,"q":"רמי בן ה-17 נבחן במבחן משכל. בהנחה שיכולת הזיכרון של רמי תקינה, סביר להניח כי רמי זכר בין ___ פריטים בתת-מבחן זכירת ספרות: (1-2 / 3-5 / 5-9 / 10-13)","a":"5-9 (הטווח התקין - \"המספר הקסום\" 7±2 של מילר)","explain":"תת-מבחן <b>זכירת-ספרות (Digit Span)</b> במבחני-משכל (כמו וכסלר) בודק ישירות <b>זיכרון לטווח-קצר</b> - זהו-יישום-מעשי-קליני של-אותו-המושג-בדיוק שנלמד-בפרק-הזיכרון. הטווח-התקין (עבור-אדם-עם-זיכרון-תקין, כמו-רמי) הוא בערך <b>7±2 פריטים</b> - זהו '<b>המספר-הקסום</b>' המפורסם-של-<b>מילר</b>, שנלמד-בפירוט בפרק-הזיכרון - כלומר, טווח-של <b>5 עד-9</b> ספרות. ⚠️ קישור-חשוב: זכרו-שבפרק-הזיכרון גם-נלמד שמחקרים-עדכניים-יותר מציעים הערכה-נמוכה-יותר (כ-4 פריטים, ללא-טכניקות-עזר) - אך <b>בהקשר-הספציפי-של-מבחן-הזיכרון-הרשמי (Digit Span)</b>, הנורמה-המקובלת-והמצופה-קלינית עדיין-מבוססת-על-הטווח-הקלאסי-של-מילר (5-9), ולא-על-ההערכה-המצומצמת-יותר.","mnemo":"7️⃣±2️⃣ המספר הקסום של מילר"},{"id":"prof14_01","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מה צריך לעשות מי שמעוניין לעבוד כפסיכולוג קליני?","a":"להירשם בפנקס הפסיכולוגים (משרד הבריאות), הדורש: תואר שני לפחות בפסיכולוגיה ממוסד מוכר, תקופת התמחות ממושכת, ובחינת התמחות של משרד הבריאות (עבור קליניים).","explain":"בישראל, <b>חוק הפסיכולוגים</b> קובע שרק-מי-שרשום ב<b>פנקס הפסיכולוגים</b> (המפוקח-על-ידי משרד-הבריאות) רשאי לעסוק-בטיפול-פסיכולוגי ולשאת-בתואר 'פסיכולוג' - זו-הגנה-חוקית על-הציבור, המבטיחה שרק-אנשי-מקצוע-מוסמכים מטפלים-בנפש-אדם. הדרישות: <b>תואר-שני לפחות</b> בפסיכולוגיה ממוסד-מוכר (לא-מספיק-תואר-ראשון), <b>תקופת-התמחות ממושכת</b> תחת-פיקוח-מקצועי, ועבור-פסיכולוגים-<b>קליניים</b> ספציפית - גם <b>בחינת-התמחות</b> רשמית מטעם-משרד-הבריאות. ⚠️ קישור לשאלה-הבאה: זה-בדיוק ההבדל-המשפטי-המרכזי בין 'פסיכולוג' (תואר-מוגן-בחוק, עם-כל-הדרישות-האלה) לבין מטפלים/פסיכותרפיסטים-אחרים (תחום-פחות-מוסדר).","mnemo":"📜 תואר-שני+התמחות+בחינה=פנקס-פסיכולוגים"},{"id":"prof14_02","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מה רשאי ומה אינו רשאי לעשות מי שסיים לימודי תעודה בפסיכותרפיה?","a":"רשאי לעסוק כמטפל/פסיכותרפיסט בתחום שהוכשר בו. אינו רשאי: אין הגדרה חוקית מוסדרת לתחום זה (בניגוד לפסיכולוגיה) - אינו נושא תואר \"פסיכולוג\" ואינו רשום בפנקס הפסיכולוגים המפוקח על ידי משרד הבריאות.","explain":"מי-שסיים לימודי-תעודה-בפסיכותרפיה <b>רשאי</b> לעסוק כמטפל/פסיכותרפיסט <b>בתחום-הספציפי</b> שהוכשר-בו. אך יש-מגבלה-משמעותית: <b>אינו-רשאי</b> - כי, בניגוד-לפסיכולוגיה, <b>אין הגדרה-חוקית-מוסדרת</b> לתחום-זה בישראל - הוא <b>אינו-נושא</b> את-התואר-המוגן 'פסיכולוג', ו<b>אינו-רשום</b> בפנקס-הפסיכולוגים המפוקח-על-ידי-משרד-הבריאות. ⚠️ המשמעות המעשית: מקצועות-טיפוליים-נוספים (כמו-פסיכותרפיה) קיימים-לצד-הפסיכולוגיה, ומאפשרים-לעסוק-בטיפול - אך ללא-אותה-רמת-פיקוח-ממשלתי-ומקצועי-מובנה שחלה-על-פסיכולוגים-רשומים.","mnemo":"🚫 תעודה=מטפל, לא \"פסיכולוג\" רשמי"},{"id":"prof14_03","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהן ארבע המשימות המרכזיות של תהליך הטיפול?","a":"(1) אבחון הבעיה (סוג ההפרעה לפי DSM). (2) הצעת אטיולוגיה סבירה (מקורות הבעיה). (3) קביעת פרוגנוזה (מהלך צפוי עם/בלי טיפול). (4) קביעת וביצוע טיפול (צמצום/העלמת תסמינים ומקורותיהם).","explain":"ארבע-המשימות מסודרות ב<b>סדר-לוגי-קבוע</b>, כל-שלב-בונה-על-הקודם: <b>(1) אבחון</b> - זיהוי סוג-ההפרעה-הספציפי, לפי-קריטריונים-מוסכמים (DSM). <b>(2) אטיולוגיה</b> - הצעת-הסבר-סביר <b>למקורות</b> הבעיה (מה-גרם-לה - ביולוגיה? למידה? חוויות-ילדות?). <b>(3) פרוגנוזה</b> - הערכת <b>המהלך-הצפוי</b> - מה-יקרה עם-טיפול, ומה-יקרה-בלעדיו. <b>(4) טיפול</b> - קביעה-וביצוע ההתערבות-בפועל, שמטרתה צמצום/העלמת-התסמינים <b>ומקורותיהם</b>. ⚠️ הרצף חשוב: אי-אפשר-להציע-טיפול-יעיל (שלב-4) בלי-להבין-קודם מה-הבעיה (1), מאיפה-היא-הגיעה (2), ולאן-היא-מובילה (3) - בדיוק-כמו-ארבע-המטרות-של-הפסיכולוגיה-הכללית (פרק 1: תיאור→הסבר→ניבוי→פיקוח), רק-ביישום-קליני-ספציפי.","mnemo":"4️⃣ אבחון+סיבה+תחזית+טיפול"},{"id":"prof14_reflection1","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"העריכו את מקרה רוני (פחד מהתחייבות בכל תחומי החיים) על פי 4 משימות הטיפול.","a":"⚠️ הערכה מומחשת. אבחון: דפוס כרוני של הימנעות מהתחייבות/אינטימיות, חוצה תחומי חיים. אטיולוגיה: לחקור מקור מוקדם (היקשרות/ילדות) ותפקיד ההימנעות כהפחתת חרדה (חיזוק שלילי). פרוגנוזה: ללא טיפול - החרפה/בידוד; עם טיפול - תלוי בתובנה ומוטיבציה. טיפול: פסיכודינמי (חשיפת שורש לא-מודע) או קוגניטיבי-התנהגותי (זיהוי מחשבות אוטומטיות + חשיפה הדרגתית).","explain":"יישום ארבע-המשימות-הטיפוליות על-מקרה-קונקרטי - כל-משימה נבחנת-בנפרד: <b>אבחון</b> - זיהוי דפוס <b>כרוני</b> של הימנעות-מהתחייבות/אינטימיות, ה<b>חוצה</b> תחומי-חיים-שונים (לא-מוגבל-לתחום-אחד-בלבד). <b>אטיולוגיה</b> - חקירת מקור-מוקדם אפשרי (סגנון-היקשרות מהילדות) <b>וגם</b> תפקיד-ההימנעות-כיום כ<b>חיזוק-שלילי</b> (הימנעות מקלה-על-חרדה מיידית, מה-שמחזק-אותה-להישאר). <b>פרוגנוזה</b> - <b>ללא-טיפול</b>: סביר-שהחרפה/בידוד-חברתי; <b>עם-טיפול</b>: תלוי-במידת-התובנה-והמוטיבציה-של-רוני-עצמו. <b>טיפול</b> - שתי-גישות-אפשריות: <b>פסיכודינמי</b> (חשיפת-השורש-הלא-מודע לפחד) או <b>קוגניטיבי-התנהגותי</b> (זיהוי-מחשבות-אוטומטיות + חשיפה-הדרגתית למצבי-התחייבות). ⚠️ שימו-לב שכל-ארבע-המשימות מתקשרות-זו-לזו - האטיולוגיה (חיזוק-שלילי) מסבירה-ישירות למה-נדרשת-חשיפה-הדרגתית בטיפול.","mnemo":"💍 4 שאלות למקרה רוני (פחד-התחייבות)"},{"id":"prof14_04","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו תפקיד הפסיכואנליטיקאי בטיפול?","a":"לעזור למטופל להעלות מחשבות מודחקות לתודעה ולהגיע לתובנה על הקשר בין תסמינים לקונפליקטים חבויים - מטרה: הרמוניה תוך-נפשית (הרחבת מודעות לסתמי, הפחתת ציות לאני עליון, חיזוק האני).","explain":"תפקיד הפסיכואנליטיקאי <b>אינו</b> 'לתקן' ישירות, אלא <b>לחשוף</b>: לעזור למטופל <b>להעלות-לתודעה</b> מחשבות-מודחקות, ולהגיע-ל<b>תובנה</b> על-הקשר בין-התסמינים-הנוכחיים לבין <b>קונפליקטים-חבויים</b> (לרוב-מהילדות). <b>המטרה הסופית</b>: <b>הרמוניה תוך-נפשית</b> - איזון-בריא בין שלוש-מבני-האישיות (הסתמי, האני, האני-העליון) - מושג-דרך שלושה-מנגנונים: <b>הרחבת-מודעות</b> לתכני-הסתמי (פחות-דברים-נשארים-מודחקים), <b>הפחתת ציות-נוקשה</b> לאני-העליון (פחות-אשמה-מוגזמת), ו<b>חיזוק-האני</b> (יכולת-טובה-יותר להתמודד-במציאות עם-שני-הכוחות-האחרים). ⚠️ שימו-לב: המטפל <b>לא</b> נותן-פתרונות-ישירים - הוא-מכוון את-המטופל <b>לגלות-בעצמו</b> את-הקשרים-הלא-מודעים.","mnemo":"🔓 מטפל=פותח מנעול הלא-מודע"},{"id":"prof14_05","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע נקראת הגישה הפסיכודינמית \"טיפול תובנה\"?","a":"כי מטרת המטפל היא לעזור למטופל להגיע לתובנות על הקשר בין תסמיני ההווה למקורותיהם בעבר (ילדות מוקדמת) - החלמה מתרחשת דרך תובנה/הבנה מודעת של קשר זה, לא רק שינוי התנהגות ישיר.","explain":"הגישה-הפסיכודינמית נקראת '<b>טיפול תובנה</b>' כי המילה-המפתח היא בדיוק <b>תובנה (insight)</b>: מטרת-המטפל היא-לעזור-למטופל להגיע-להבנה-מודעת על-<b>הקשר</b> בין תסמיני-ההווה לבין <b>מקורותיהם בעבר</b> (בדרך-כלל ילדות-מוקדמת וקונפליקטים-לא-פתורים). ⚠️ ההנחה-התיאורטית-המכרעת: <b>ההחלמה עצמה מתרחשת דרך-התובנה/ההבנה-המודעת</b> - <b>לא</b> דרך-שינוי-התנהגות-ישיר (כמו-בטיפול-ההתנהגותי, הנלמד-בשאלות-הבאות) - ברגע-שהמטופל <b>מבין</b> באמת מאיפה-הבעיה-הגיעה, ההנחה-היא שהתסמינים-יחלשו-ממילא, כתוצאה-מהתובנה-עצמה.","mnemo":"💡 תובנה=החלמה, לא רק שינוי-התנהגות"},{"id":"prof14_06","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו את 4 הטכניקות הפסיכודינמיות (אסוציאציות חופשיות, התנגדות, ניתוח חלומות, העברה/העברה נגדית).","a":"אסוציאציות חופשיות=דיווח שוטף על כל מחשבה, קתרזיס משחרר רגש מודחק. התנגדות=אי-יכולת/רצון לדון בנושא=מחסום ללא-מודע, המטפל שובר אותה. ניתוח חלומות=חושף תוכן חבוי (מניעים מוסווים) מאחורי התוכן הגלוי. העברה=רגשות כלפי המטפל המזוהה עם דמות מהעבר; העברה נגדית=רגשות המטפל כלפי המטופל, עלולה לחשוף דינמיקות לא-מודעות של המטפל.","explain":"ארבע-הטכניקות-הפסיכודינמיות, כל-אחת חושפת-שכבה-אחרת-של-הלא-מודע: <b>אסוציאציות חופשיות</b> - דיווח-שוטף-ובלתי-מסונן על-כל-מחשבה-שעולה, ללא-צנזורה - יוצר <b>קתרזיס</b> (שחרור-רגשי) של-רגש-מודחק. <b>התנגדות</b> - כשהמטופל <b>מתקשה/מסרב</b> לדון-בנושא-מסוים - זה-עצמו <b>מחסום מהלא-מודע</b> שמעיד-שנגענו-בנקודה-רגישה; המטפל עובד-בעדינות <b>לשבור</b> את-ההתנגדות-הזו. <b>ניתוח חלומות</b> - חושף <b>תוכן-חבוי</b> (מניעים-מוסווים) מאחורי <b>התוכן-הגלוי</b> של-החלום, כי-האני-העליון פחות-'ער' וביקורתי בזמן-שינה, ומאפשר-לדחפים-מוסתרים-להתבטא (בצורה-מוצפנת). <b>העברה</b> - המטופל <b>מפנה</b> כלפי-המטפל רגשות המזוהים-במקור עם-דמות-אחרת מהעבר (למשל, הורה); <b>העברה-נגדית</b> - רגשות-המטפל-<b>עצמו</b> כלפי-המטופל, שעלולים לחשוף דינמיקות-לא-מודעות <b>של-המטפל-עצמו</b> - כלי-אבחוני חשוב-גם-לו.","mnemo":"4️⃣🗣️😤💭🔄 אסוציאציה+התנגדות+חלום+העברה"},{"id":"prof14_07","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו הרעיון המרכזי של הטיפול ההתנהגותי?","a":"התנהגויות אבנורמליות נרכשות באותו תהליך למידה כמו התנהגויות נורמליות - עקרונות ההתניה/חיזוק. התסמין עצמו הוא הבעיה, לא ביטוי לתהליך נסתר עמוק יותר.","explain":"הרעיון-המרכזי של-הטיפול-ההתנהגותי מהווה <b>ניגוד-קוטבי</b> לגישה-הפסיכודינמית: התנהגויות-אבנורמליות נרכשות <b>באותו-תהליך-למידה בדיוק</b> כמו-התנהגויות-נורמליות - עקרונות-ההתניה/החיזוק (שנלמדו-בפרק-הלמידה). המשמעות המהפכנית: <b>התסמין-עצמו הוא-הבעיה</b> - <b>לא</b> ביטוי-חיצוני-לתהליך-נסתר-עמוק-יותר (כפי-שהפסיכודינמית-טוענת). ⚠️ אם-התסמין-עצמו-הוא-הבעיה, מסקנה-הגיונית: אפשר <b>לטפל-ישירות</b> בהתנהגות-הבעייתית עצמה (דרך-עקרונות-התניה) - בלי-צורך-'לחפור' לקונפליקטים-לא-מודעים-מהעבר. זה-בדיוק-מה-שנבחן-אמפירית-בשאלה-הבאה (התחלפות-תסמין).","mnemo":"🎯 התסמין=הבעיה עצמה, לא קצה-קרחון"},{"id":"prof14_08","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו את ההבדל בין טיפול פסיכודינמי להתנהגותי באמצעות \"התחלפות תסמין\".","a":"פסיכודינמיים ניבאו שטיפול בהתנהגות בלבד (ללא הקונפליקט הפנימי) יגרום להתחלפות תסמין (בעיה חדשה תופיע). מחקרים הפריכו זאת - הכחדת תסמין בטיפול התנהגותי לא יצרה תסמינים חדשים, ולעיתים אף שיפרה תסמינים נוספים - תומך בהנחה שהתסמין עצמו הוא הבעיה.","explain":"'התחלפות-תסמין' הייתה <b>ניבוי-ביקורתי</b> של-הפסיכודינמיים כלפי-הגישה-ההתנהגותית: אם-לא-מטפלים-<b>בשורש</b> (הקונפליקט-הפנימי-הלא-מודע), אלא-רק-בהתנהגות-הגלויה, הבעיה 'תברח' ו<b>תופיע-מחדש</b> בצורת-תסמין-חדש-אחר (כי-הקונפליקט-המקורי עדיין-לא-נפתר). <b>המחקרים הפריכו את-הניבוי-הזה</b>: הכחדת-תסמין בטיפול-התנהגותי <b>לא</b> יצרה תסמינים-חדשים - ולעיתים אף <b>שיפרה תסמינים-נוספים</b> (השפעה-חיובית-רוחבית, לא-שלילית). ⚠️ המסקנה: ממצא-זה <b>תומך ישירות</b> בהנחה-המרכזית-של-הטיפול-ההתנהגותי (שנלמדה-בשאלה-הקודמת) - שהתסמין-עצמו הוא-הבעיה, ולא-רק-'כיסוי' לבעיה-עמוקה-יותר.","mnemo":"❌🔄 הפרכה: לא מופיע תסמין-חלופי"},{"id":"prof14_09","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו את טכניקות הטיפול ההתנהגותי (התניה נגד, ניהול התרחשויות מותנות, למידה חברתית).","a":"התניה נגד (קלאסית)=חשיפה/הרתעה מחליפים תגובה מותנית ישנה (הקהיה שיטתית, הצפה, מניעת תגובה). ניהול התרחשויות מותנות (אופרנטית)=חיזוקים חיוביים (עיצוב, כלכלת אסימונים) או הכחדה (הפסקת חיזוק בלתי-מכוון). למידה חברתית (בנדורה)=חיקוי מודלים (משתתף/סמלי) + אימון מיומנויות חברתיות (תרגול התנהגותי).","explain":"שלוש קטגוריות-טכניקות בטיפול-ההתנהגותי, כל-אחת מבוססת-על-סוג-התניה-אחר שכבר-נלמד-בקורס: <b>התניה-נגד (מבוססת-קלאסית)</b> - חשיפה/הרתעה שמחליפות תגובה-מותנית-ישנה-בעייתית - כוללת: <b>הקהיה-שיטתית</b> (חשיפה-הדרגתית-ומבוקרת + הרפיה), <b>הצפה</b> (חשיפה-מלאה-ומיידית), <b>מניעת-תגובה</b> (מונעים-את-הפעולה-הכפייתית-הרגילה). <b>ניהול-התרחשויות-מותנות (מבוססת-אופרנטית)</b> - <b>חיזוקים-חיוביים</b> (עיצוב-הדרגתי, כלכלת-אסימונים) או <b>הכחדה</b> (הפסקת-חיזוק-בלתי-מכוון שהיה-מזין-את-ההתנהגות-הבעייתית). <b>למידה-חברתית (בנדורה)</b> - <b>חיקוי-מודלים</b> (משתתף בעצמו, או סמלי דרך-צפייה) + <b>אימון-מיומנויות-חברתיות</b> (תרגול-התנהגותי-ישיר). ⚠️ שלושת-הקטגוריות מכסות את שלושת-סוגי-הלמידה-העיקריים שנלמדו-בפרק-הלמידה - כל-אחת מיושמת-כאן קלינית-לטיפול-ממוקד.","mnemo":"3️⃣ נגד+אופרנטי+חברתי"},{"id":"prof14_reflection2","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"באיזו שיטת טיפול התנהגותי תבחרו ב-4 מצבים (יניב/מגבת, תמר/פחד רכב, רונית/כסיסת ציפורניים, עידן/ביישנות)?","a":"⚠️ יישומים מומחשים. יניב=חיזוקים חיוביים (אסימונים על תלית מגבת). תמר=הקהיה שיטתית (מדרג חרדה+הרפיה+חשיפה הדרגתית). רונית=אסטרטגיית הכחדה (זיהוי והפסקת חיזוק בלתי-מכוון לכסיסה). עידן=אימון מיומנויות חברתיות (תרגול התנהגותי הדרגתי).","explain":"יישום-ישיר של-שלוש-הקטגוריות-הטיפוליות על-ארבעה-מצבים-שונים - בכל-מקרה נבחרת-הטכניקה-המתאימה-ביותר לאופי-הבעיה-הספציפי: <b>יניב</b> (צריך-הרגל-פשוט) - <b>חיזוקים-חיוביים</b> (אסימונים-על-תלית-מגבת). <b>תמר</b> (פחד-ספציפי-מרכב) - <b>הקהיה-שיטתית</b> (בניית-מדרג-חרדה + הרפיה + חשיפה-הדרגתית). <b>רונית</b> (הרגל-המשמר-עצמו-בחיזוק-נסתר, כסיסת-ציפורניים) - <b>אסטרטגיית-הכחדה</b> (זיהוי-והפסקת-החיזוק-הבלתי-מכוון שמזין-את-ההרגל). <b>עידן</b> (חוסר-מיומנות-חברתית, ביישנות) - <b>אימון-מיומנויות-חברתיות</b> (תרגול-הדרגתי-ומובנה). ⚠️ העיקרון-המנחה: <b>אופי-הבעיה</b> קובע-את-הטכניקה - פחד דורש-חשיפה-הדרגתית; הרגל-נשמר-בחיזוק דורש-הכחדה; חוסר-כישור דורש-אימון, לא-חיזוק/הכחדה.","mnemo":"4️⃣ 4 בעיות, 4 טכניקות מתאימות"},{"id":"prof14_10","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"השוו בין הטיפול הפסיכודינמי לטיפול ההתנהגותי (טבלה 15.3).","a":"פסיכואנליזה: אינסטינקטים ביולוגיים, קונפליקט/קיבעון, מטרה=בגרות פסיכוסקסואלית, מוקד=מניעים/רגשות/עבר, לא-מודע מרכזי, תובנה חיונית, מטפל=בלש ניטרלי. התנהגותי: יכולת למידה, למידה לא-רצויה, מטרה=מיגור תסמין, מוקד=התנהגות גלויה/הווה, אין עיסוק בלא-מודע, תובנה לא נחוצה, מטפל=מאמן.","explain":"טבלת-ההשוואה (טבלה 15.3) ממחישה שתי-פילוסופיות-שלמות ומנוגדות על-טבע-האדם, לא-רק שתי 'שיטות-טכניות': <b>פסיכואנליזה</b> - מבוססת-על <b>אינסטינקטים ביולוגיים</b>; ההפרעה נובעת-מ<b>קונפליקט/קיבעון</b>; המטרה הסופית <b>בגרות-פסיכוסקסואלית</b>; המוקד <b>במניעים/רגשות מהעבר</b>; ה<b>לא-מודע</b> מרכזי-לגמרי; <b>תובנה חיונית</b> להחלמה; המטפל מתפקד כ<b>'בלש-ניטרלי'</b> (מפרש-רמזים, לא-מכוון-ישירות). <b>התנהגותי</b> - מבוסס-על <b>יכולת-למידה כללית</b>; ההפרעה היא <b>למידה-לא-רצויה</b> (לא-קונפליקט-עמוק); המטרה <b>מיגור-התסמין</b> עצמו; המוקד <b>בהתנהגות-גלויה-בהווה</b>; <b>אין עיסוק בלא-מודע כלל</b>; <b>תובנה לא-נחוצה</b> להחלמה; המטפל מתפקד כ<b>'מאמן'</b> (מלמד-ומדריך-ישירות). ⚠️ ההשוואה מדגישה שההבדל <b>עמוק-מהטכניקות-בלבד</b> - זו-מחלוקת-פילוסופית שלמה על-מקור-ההפרעה ומהות-ההחלמה.","mnemo":"⚔️ טבלת-קרב: פסיכודינמי VS התנהגותי"},{"id":"prof14_11","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"במה מתמקדים בטיפול קוגניטיבי?","a":"בשינוי האופן שבו הלקוח חושב על חוויות משמעותיות בחייו - תוכן קוגניטיבי (מה חושבים) ותהליך קוגניטיבי (איך חושבים), באמצעות בנייה קוגניטיבית מחדש.","explain":"הטיפול-הקוגניטיבי מתמקד ב<b>שינוי האופן שבו הלקוח חושב</b> על חוויות-משמעותיות-בחייו - לא-בהתנהגות-הגלויה (כמו-בטיפול-ההתנהגותי), ולא-בלא-מודע (כמו-בפסיכודינמי), אלא <b>ישירות במחשבה-המודעת</b>. שני-רכיבים: <b>תוכן-קוגניטיבי</b> (מה-בדיוק-חושבים - התוכן-הספציפי-של-המחשבה, כמו 'אני-כישלון') ו<b>תהליך-קוגניטיבי</b> (איך-חושבים - הדפוס/הצורה-הכללית של-החשיבה, כמו הכללת-יתר או חשיבה-קיצונית). ⚠️ הכלי-המרכזי לביצוע-השינוי: <b>בנייה-קוגניטיבית-מחדש</b> - תהליך פעיל-ומובנה של-זיהוי-מחשבות-בעייתיות והחלפתן-במחשבות-מדויקות/מועילות-יותר - זהו-בדיוק-הגשר-לשתי-הגישות-הקוגניטיביות-הספציפיות (בק ואליס) שנלמדות-בשאלות-הבאות.","mnemo":"🧠 מה+איך חושבים=מיקוד קוגניטיבי"},{"id":"prof14_12","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו את טכניקות הטיפול הקוגניטיבי (שינוי אמונות שגויות, קוגניטיבי-התנהגותי).","a":"שינוי אמונות שגויות=מזהים ומאתגרים עמדות בלתי-מתקבלות/הנחות שגויות/כללים נוקשים היוצרים מצוקה. קוגניטיבי-התנהגותי=בנייה קוגניטיבית מחדש (אמירות עצמיות שליליות→בונות) + חיזוקים מותנים ליעילות עצמית - הצבת יעדים בני-השגה מגבירה שליטה/מאמץ/התמדה.","explain":"שתי-רמות-טכניקה בטיפול-הקוגניטיבי, מהכללי-לספציפי: <b>שינוי אמונות-שגויות</b> - העיקרון-הכללי: מזהים-ומאתגרים <b>עמדות בלתי-מתקבלות, הנחות-שגויות, וכללים-נוקשים</b> (כמו 'אני חייב-להצליח-בכל-דבר') <b>היוצרים-בעצמם</b> את-המצוקה-הרגשית. <b>קוגניטיבי-התנהגותי</b> - יישום-מעשי-משולב: <b>בנייה-קוגניטיבית-מחדש</b> (החלפת אמירות-עצמיות-שליליות באמירות-בונות ומציאותיות-יותר) <b>בשילוב</b> חיזוקים-מותנים-ל<b>יעילות-עצמית</b> - הצבת <b>יעדים-בני-השגה</b> (לא-שאפתניים-מדי) מגבירה תחושת-שליטה, ומכאן-מאמץ-והתמדה. ⚠️ שתי-שיטות-הבק-ואליס (השאלות-הבאות) הן דוגמאות-קונקרטיות ל'שינוי-אמונות-שגויות', כל-אחת בגישה-מעט-שונה.","mnemo":"2️⃣ אמונות-שגויות + CBT"},{"id":"prof14_13","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד מדגים טיפול בק בדיכאון \"שינוי אמונות שגויות\"?","a":"בק: המטפל עוזר לזהות עיוותי חשיבה (מחשבות שליליות אוטומטיות כמו \"אף אחד לא יאהב אותי\") ולנסח חוויות בדרכים מציאותיות יותר. 4 טכניקות: קריאת תיגר על הנחות, בחינת ראיות, ייחוס לגורמי מצב (לא חוסר יכולת), פתרונות חלופיים - מדגים ישירות זיהוי/אתגור/החלפת אמונות שגויות.","explain":"טיפול-<b>בק</b> בדיכאון הוא הדוגמה-הקלינית-המובהקת-ביותר לעיקרון 'שינוי-אמונות-שגויות': המטפל עוזר-למטופל <b>לזהות עיוותי-חשיבה</b> - מחשבות-שליליות-<b>אוטומטיות</b> (עולות-מעצמן, ללא-בקרה-מודעת) כמו 'אף-אחד-לא-יאהב-אותי' - ולנסח-מחדש את-החוויה <b>בדרכים מציאותיות-יותר</b>. <b>ארבע טכניקות ספציפיות</b>: <b>(1) קריאת-תיגר על-הנחות</b> (האם-זה-באמת-נכון?), <b>(2) בחינת-ראיות</b> (מה-הראיות-בפועל-תומכות/סותרות?), <b>(3) ייחוס-לגורמי-מצב</b> (במקום-'חוסר-יכולת' אישי, אולי-הנסיבות-הן-שגרמו-לכישלון), <b>(4) חיפוש פתרונות-חלופיים</b>. ⚠️ שימו-לב שארבעת-הטכניקות מדגימות <b>ישירות</b> את-שלושת-השלבים של-שינוי-אמונות-שגויות: <b>זיהוי</b> (מציאת המחשבה-האוטומטית), <b>אתגור</b> (בדיקתה-מול-ראיות), ו<b>החלפה</b> (ניסוח-מחדש מציאותי).","mnemo":"🔍 בק: מוצא-מחשבה-שלילית, מחליף במציאותית"},{"id":"prof14_14","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד מדגים טיפול RET של אליס \"שינוי אמונות שגויות\"?","a":"אליס: תגובה רגשית לאירוע נובעת מאמונה על האירוע, לא מהאירוע עצמו. מלמד לזהות ציוויים \"צריך/חייב/מוכרח\" (כללים נוקשים), מערער עליהם בעימות רציונלי, ומחליף חשיבה דוגמטית ברעיונות רציונליים - מדגים ישירות שינוי אמונות שגויות החוסמות מימוש עצמי.","explain":"טיפול <b>RET (Rational Emotive Therapy)</b> של <b>אליס</b> מבוסס-על-עיקרון-יסוד שונה-מעט-מבק, אך משיג-אותה-מטרה: <b>תגובה-רגשית לאירוע נובעת מהאמונה-על-האירוע, לא מהאירוע-עצמו</b> - שני-אנשים יכולים-לחוות-אותו-אירוע-בדיוק ולהגיב-שונה-לגמרי, תלוי-במה-שהם-מאמינים-לגביו. אליס מלמד <b>לזהות ציוויים</b> ('אני-חייב/מוכרח/צריך') - כללים-נוקשים-ובלתי-מציאותיים - <b>לערער-עליהם</b> ב<b>עימות-רציונלי</b> (מדוע-בעצם-'חייב'?), ו<b>להחליף</b> חשיבה-דוגמטית-קשיחה ב<b>רעיונות-רציונליים-וגמישים-יותר</b>. ⚠️ זה-מדגים ישירות שינוי-אמונות-שגויות, בדיוק-כמו-בק, אך מתמקד-ספציפית ב<b>ציוויים-קיצוניים</b> ('צריך/חייב') כמקור-הבעיה, לא-בעיוותי-חשיבה-כלליים.","mnemo":"❗ אליס: \"צריך/חייב\"=כללים-נוקשים לשבירה"},{"id":"prof14_15","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו את טכניקות הטיפול ההומניסטי (ממוקד בלקוח, גשטלט/כיסא ריק) ותפקיד המטפל.","a":"ממוקד בלקוח (רוג'רס): מטפל מעניק הערכה חיובית בלתי מותנית, מאזין/משקף/לא-מכוון - מסייע ללקוח לגלות מודעות עצמית ולהגיע למימוש עצמי בעצמו. גשטלט (פרלס): כיסא ריק - מטפל מנחה לקוח \"לדבר אל\" דמות/רגש מדומיין על הכיסא, כדי לבטא רגשות עצורים ולפתור קונפליקטים ישנים.","explain":"שתי-טכניקות-מובילות בטיפול-ההומניסטי, שתיהן מדגישות <b>מסע-שהלקוח-עושה-בעצמו</b>: <b>טיפול ממוקד-בלקוח</b> (רוג'רס) - המטפל מעניק <b>הערכה חיובית בלתי-מותנית</b> (קבלה-מלאה, ללא-שיפוטיות) ותפקידו <b>מאזין, משקף, ולא-מכוון</b> (לא-נותן-עצות/פתרונות ישירים) - מסייע ללקוח <b>לגלות בעצמו</b> מודעות-עצמית ולהגיע-למימוש-עצמי. <b>גשטלט (כיסא-ריק)</b> (פרלס) - המטפל מנחה-את-הלקוח '<b>לדבר-אל</b>' דמות/רגש-מדומיין המונח על-כיסא-ריק (למשל, 'לדבר עם ההורה' שלא-נוכח) - טכניקה-חוויתית, לא-רק-מילולית, שנועדה לבטא <b>רגשות-עצורים</b> ולפתור <b>קונפליקטים-ישנים</b>. ⚠️ שני-הגישות חולקות-פילוסופיה משותפת: המטפל <b>לא-פותר</b> את-הבעיה-עבור-הלקוח - הוא-יוצר-סביבה/כלי שמאפשרים ללקוח <b>למצוא-בעצמו</b> את-הפתרון.","mnemo":"👂🪑 רוג'רס=מקשיב | פרלס=כיסא-ריק"},{"id":"prof14_reflection3","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"כיצד יטפל באורן מטפל קוגניטיבי וכיצד מטפל הומניסטי?","a":"⚠️ יישום מומחש. קוגניטיבי: מזהה מחשבות אוטומטיות שגויות מאחורי הכעס, בוחן ראיות, מייחס לגורמי מצב, בונה מחדש אמירות עצמיות. הומניסטי: הערכה חיובית בלתי מותנית, מאזין/משקף (לא נותן פתרונות), מסייע לאורן לגלות בעצמו את מקור התסכול (אי-התאמה בין עצמי לציפיות חיצוניות) ולנוע לעבר מימוש עצמי.","explain":"יישום-השוואתי של-שתי-גישות-שונות (קוגניטיבית מול-הומניסטית) על-אותו-מקרה - חשוב-להראות-איך-כל-גישה 'קוראת' את-אותה-בעיה-אחרת: <b>גישה קוגניטיבית</b> - מזהה <b>מחשבות-אוטומטיות-שגויות</b> מאחורי-הכעס-של-אורן, <b>בוחנת-ראיות</b> (האם-המחשבות-מוצדקות), <b>מייחסת לגורמי-מצב</b> (לא-לחוסר-יכולת-אישי), ו<b>בונה-מחדש</b> אמירות-עצמיות - גישה <b>מובנית ומכוונת</b>, המטפל פעיל-בזיהוי-ובאתגור. <b>גישה הומניסטית</b> - <b>הערכה-חיובית-בלתי-מותנית</b>, <b>מאזין ומשקף</b> (לא-נותן-פתרונות מוכנים), מסייע-לאורן <b>לגלות בעצמו</b> את-מקור-התסכול (למשל, <b>אי-התאמה</b> בין-העצמי-האמיתי-שלו לציפיות-חיצוניות-שהוטלו-עליו), ו<b>לנוע-לעבר</b> מימוש-עצמי. ⚠️ ההבדל-המרכזי: קוגניטיבי=<b>מטפל-מכוון-ופעיל</b> באיתור-הבעיה; הומניסטי=<b>מטפל-כמלווה</b>, הלקוח-עצמו מגיע-לתובנה.","mnemo":"😡 אורן-כועס: 2 גישות, 2 דרכים"},{"id":"prof14_16","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"סכמו את פעילות ותופעות הלוואי של 4 קטגוריות התרופות (אנטי-פסיכוטיות, נוגדות דיכאון, דו-קוטבית, נוגדות חרדה).","a":"אנטי-פסיכוטיות: מפחיתות דופמין - תופעות לוואי מוטוריות/סוכרת/השמנה (פחות בחדשות). נוגדות דיכאון: מגבירות סרוטונין+נורפינפרין - בחילות/נדודי שינה/עצבנות/בעיה מינית. דו-קוטבית: ליתיום/תרופות פרכוסים, מנגנון לא ידוע. נוגדות חרדה: מגבירות גאבא - ישנוניות/בעיות קואורדינציה/פגיעה בזיכרון/סבילות והתמכרות.","explain":"ארבע-קטגוריות-תרופתיות, כל-אחת פועלת על-נוירוטרנסמיטר-אחר ונושאת-תופעות-לוואי-אופייניות-שונות: <b>אנטי-פסיכוטיות</b> (לסכיזופרניה) - <b>מפחיתות דופמין</b>; תופעות-לוואי <b>מוטוריות</b> (רעד, נוקשות-שרירים), <b>סוכרת, השמנה</b> (פחות-בתרופות-החדשות-יותר, שפועלות-בסלקטיביות-גבוהה-יותר). <b>נוגדות-דיכאון</b> - <b>מגבירות סרוטונין+נורפינפרין</b>; תופעות-לוואי <b>בחילות, נדודי-שינה, עצבנות, בעיה-מינית</b>. <b>דו-קוטבית</b> - <b>ליתיום</b> או <b>תרופות-פרכוסים</b> (אנטי-קונבולסנטים); <b>המנגנון עדיין לא-ידוע-במלואו</b>, למרות-יעילות-מוכחת. <b>נוגדות-חרדה</b> - <b>מגבירות גאבא</b> (הנוירוטרנסמיטר-המעכב-המרכזי); תופעות-לוואי <b>ישנוניות, בעיות-קואורדינציה, פגיעה-בזיכרון</b>, ובעיה-קריטית: <b>סבילות והתמכרות</b> (הרחבה בשאלת-הרהור-הבאה). ⚠️ שימו-לב לתבנית: כל-קטגוריה 'מכוונת' לנוירוטרנסמיטר-ספציפי, ותופעות-הלוואי לרוב נובעות מהשפעה-רחבה-מדי-על-אותו-נוירוטרנסמיטר-באזורי-מוח-נוספים-לא-רלוונטיים.","mnemo":"4️⃣💊 4 תרופות, 4 תופעות-לוואי"},{"id":"prof14_reflection4","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע הגוף מפתח סבילות גבוהה לתרופות, בעיקר נוגדות חרדה?","a":"⚠️ הסבר מבוסס מנגנון. חשיפה חוזרת לתרופה המגבירה גאבא מלאכותית גורמת למוח \"לפצות\" (פחות קולטנים/רגישות טבעית) - הומאוסטזיס נוירוכימי. אותו מינון מניב פחות השפעה עם הזמן, נדרש מינון עולה. מסביר גם תסמיני גמילה - המוח \"התרגל\" לרמת גאבא גבוהה, הפסקה פתאומית משאירה עיכוב עצבי נמוך מהרגיל.","explain":"⚠️ הסבר מבוסס-מנגנון-נוירוכימי: חשיפה-חוזרת לתרופה <b>המגבירה-גאבא</b> (כמו-נוגדות-חרדה) גורמת למוח '<b>לפצות</b>' על-הרמה-הגבוהה-הבלתי-טבעית - הוא <b>מקטין באופן-הדרגתי</b> את-מספר-הקולטנים/רגישותם-הטבעית לגאבא, במעין <b>הומאוסטזיס נוירוכימי</b> (המוח שואף-לאזן את-עצמו לרמת-פעילות-'רגילה'). כתוצאה, <b>אותו-מינון</b> מניב <b>פחות-השפעה</b> ככל-שעובר-הזמן - נדרש <b>מינון-עולה</b> כדי-להשיג-אותה-תוצאה (זו-הגדרת-הסבילות). זה-מסביר-גם <b>תסמיני-גמילה</b>: המוח 'התרגל' לרמת-גאבא-מלאכותית-גבוהה (ופיצה-בהתאם) - <b>הפסקה-פתאומית</b> של-התרופה משאירה את-המוח עם <b>עיכוב-עצבי נמוך-מהרגיל</b> (פחות-גאבא-פעיל מהמצב-הטבעי-המקורי), מה-שמסביר-תסמיני-חרדה-חדים-בזמן-הגמילה.","mnemo":"🧠⚖️ מוח מפצה על גאבא מלאכותי=סבילות"},{"id":"prof14_17","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"במה מתמקדים הטיפולים הביו-רפואיים הנוספים (קטיעת אונת מצח, הלם חשמלי, גרייה מגנטית)?","a":"קטיעת אונת מצח=ניתוק סיבי עצב לתלמוס/היפותלמוס, מסלק רגשות עזים אך הורס אישיות לצמיתות (בלתי הפיך). הלם חשמלי=זרם חשמלי לרקות עד פרכוס, יעיל ומהיר לדיכאון קשה, גורם ליקויי זיכרון זמניים. גרייה מגנטית=פעימות מגנטיות חוזרות, יעילה כמו הלם חשמלי לדיכאון, מנגנון לא ידוע.","explain":"שלושה-טיפולים-ביו-רפואיים-נוספים, פולשניים-בדרגות-שונות: <b>קטיעת-אונת-מצח (לובוטומיה)</b> - ניתוק <b>סיבי-עצב לתלמוס/היפותלמוס</b>; מסלק רגשות-עזים, אך <b>הורס אישיות לצמיתות</b> - <b>בלתי-הפיך</b>, ולכן כמעט-בלתי-נהוג-כיום (טיפול היסטורי-בעייתי-מבחינה-אתית). <b>הלם חשמלי (ECT)</b> - זרם-חשמלי <b>לרקות עד-פרכוס</b> מבוקר; <b>יעיל-ומהיר</b> לדיכאון-קשה-שלא-הגיב-לטיפולים-אחרים, גורם <b>ליקויי-זיכרון זמניים</b> (לא-קבועים ברוב-המקרים). <b>גרייה מגנטית (rTMS)</b> - פעימות-מגנטיות-חוזרות ולא-פולשניות; <b>יעילה כמו-הלם-חשמלי</b> לדיכאון, אך <b>המנגנון המדויק עדיין לא-ידוע</b>, ובלי-תופעות-הלוואי-הקוגניטיביות של-ECT. ⚠️ סדר-הפולשנות: לובוטומיה (בלתי-הפיך, כמעט-נזנח) > ECT (הפיך, יעיל-אך-עם-תופעות-לוואי) > rTMS (הכי-לא-פולשני, פחות-תופעות-לוואי) - התפתחות-היסטורית לכיוון-טיפולים-בטוחים-יותר.","mnemo":"✂️⚡🧲 לובוטומיה+הלם+מגנט"},{"id":"prof14_22","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מדוע חשוב לערוך מחקרים על הערכת יעילות הטיפול?","a":"אייזנק (1952) הראה ששיעורי החלמה ללא טיפול היו גבוהים כמו בפסיכואנליזה - חשף שמחקרים חייבים לכלול קבוצות ביקורת, כדי לדעת אם שיפור נובע מהטיפול עצמו או היה קורה ממילא.","explain":"מחקרו-הפורץ-דרך (וגם-שנוי-במחלוקת) של <b>אייזנק (1952)</b> חשף בעיה-מתודולוגית-קריטית: הוא הראה ש<b>שיעורי-החלמה ללא-כל-טיפול</b> היו <b>גבוהים באותה-מידה</b> כמו-שיעורי-ההחלמה אצל-מטופלים <b>שכן-עברו</b> פסיכואנליזה. <b>המשמעות המהפכנית</b>: ממצא-זה חשף שמחקרי-יעילות-טיפול <b>חייבים לכלול קבוצות-ביקורת</b> (אנשים-שלא-קיבלו-טיפול, להשוואה) - בלי-קבוצת-ביקורת, אי-אפשר-לדעת אם-שיפור-שנצפה נובע <b>מהטיפול-עצמו</b>, או שהיה-<b>קורה-ממילא</b> (החלמה-טבעית, שנלמדת-בפירוט-בשאלה-הבאה). ⚠️ זהו-בדיוק-אותו-עיקרון-מתודולוגי שנלמד-בפרק-2 (שיטות-מחקר) - חשיבות-קבוצת-הביקורת - כאן-מיושם ספציפית-על-הערכת-יעילות-טיפולים-פסיכולוגיים.","mnemo":"🔬 אייזנק: צריך קבוצת-ביקורת"},{"id":"prof14_23","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו אפקט ההחלמה הספונטנית וכיצד משפיע על מחקרי טיפול?","a":"אחוז מסוים מהסובלים מפסיכופתולוגיה משתפרים ללא כל התערבות (כ-2/3 מבעיות נוירוטיות תוך שנתיים - אייזנק). קריטריון הערכה: שיפור בעקבות טיפול חייב להיות גבוה יותר משיפור ללא טיפול - מחייב קבוצת ביקורת בכל מחקר.","explain":"<b>אפקט ההחלמה-הספונטנית</b>: אחוז-מסוים מהסובלים-מפסיכופתולוגיה <b>משתפרים ללא כל התערבות-טיפולית</b> - נתון-מדהים שמצא-אייזנק: כ-<b>2/3</b> מבעיות-נוירוטיות משתפרות <b>תוך-שנתיים</b>, גם-ללא-טיפול-כלשהו. <b>השלכה-מתודולוגית קריטית</b>: קריטריון-ההערכה-הנכון-לטיפול חייב-להיות <b>יחסי, לא-מוחלט</b> - שיפור-בעקבות-טיפול חייב-להיות <b>גבוה-יותר</b> משיפור-שהיה-קורה-<b>בלי</b>-טיפול - אחרת, אי-אפשר-לדעת-אם-הטיפול-עצמו-תרם-משהו-אמיתי, או-שפשוט-'נקלענו' לתהליך-החלמה-שהיה-קורה-ממילא. ⚠️ זה-מחייב <b>קבוצת-ביקורת בכל-מחקר-טיפולי</b> - בדיוק-כפי-שאייזנק (שנלמד בשאלה-הקודמת) הוכיח שהיה-חסר-במחקרים-מוקדמים-יותר.","mnemo":"⏳ 2/3 מחלימים גם בלי טיפול"},{"id":"prof14_24","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מהו הקשר בין אפקט ההחלמה הספונטני לאפקט פלסבו?","a":"שניהם מייצגים שיפור שאינו נובע מהמרכיב הטיפולי הייחודי - החלמה ספונטנית=ללא כל טיפול; פלסבו=מהציפייה/מהקשר הטיפולי בלבד. חוקרים חייבים להוכיח ששיטתם יעילה יותר משני קווי הבסיס הללו גם יחד.","explain":"אפקט-ההחלמה-הספונטנית ואפקט-הפלסבו <b>שניהם מייצגים שיפור שאינו-נובע מהמרכיב-הטיפולי-הייחודי</b> - שני 'קווי-בסיס' שכל-טיפול-אמיתי חייב-'לנצח': <b>החלמה-ספונטנית</b> - שיפור <b>ללא כל טיפול בכלל</b> (הזמן-עצמו/תהליכים-טבעיים מרפאים). <b>פלסבו</b> - שיפור הנובע <b>מהציפייה/מהקשר-הטיפולי-בלבד</b> (האמונה-שמקבלים-עזרה, לא-מהמרכיב-הפעיל-הספציפי). ⚠️ ההשלכה-המתודולוגית: חוקרים <b>חייבים להוכיח</b> ששיטת-הטיפול-שלהם <b>יעילה-יותר משני-קווי-הבסיס-האלה גם-יחד</b> - לא-מספיק-להראות-שיפור (זה-עשוי-להיות-סתם-החלמה-ספונטנית); לא-מספיק-אפילו-להראות-שיפור-גדול-מקבוצת-ביקורת-ללא-טיפול (זה-עשוי-להיות-רק-אפקט-פלסבו) - נדרש-להראות-יתרון-אמיתי גם-מעל-קבוצת-פלסבו (מקבלת-'טיפול-מזויף' דומה).","mnemo":"🤝 החלמה-ספונטנית+פלסבו=לא-מהטיפול-עצמו"},{"id":"prof14_25","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"מה אפשר ללמוד ממטה-אנליזה על טיפול בדיכאון (תרשים 15.3)?","a":"מטה-אנליזה=מסקנות כלליות ממחקרים רבים. ~50% מנוטלי תרופות חשים הקלה. טיפול בין-אישי, קוגניטיבי-התנהגותי ותרופתי - כולם יעילים יותר מפלסבו; אך טיפול פסיכודינמי קלאסי לא עלה על פלסבו. חוקרים מתמקדים כיום ב\"מדוע/למי\" יעיל, לא רק \"האם\".","explain":"<b>מטה-אנליזה</b> - שיטה-סטטיסטית המסכמת <b>מסקנות-כלליות ממחקרים-רבים גם-יחד</b> (לא-מסתמכת-על-מחקר-בודד) - נותנת-תמונה-מהימנה-יותר מכל-מחקר-יחיד. הממצאים-המרכזיים בתחום-הדיכאון: כ-<b>50%</b> מנוטלי-תרופות-נוגדות-דיכאון חשים-הקלה. <b>טיפול בין-אישי, קוגניטיבי-התנהגותי, ותרופתי</b> - <b>כולם יעילים-יותר מפלסבו</b> (מנצחים-את-שני-קווי-הבסיס שנלמדו-בשאלה-הקודמת). <b>אך</b> - ממצא-מפתיע-וחשוב: <b>טיפול פסיכודינמי קלאסי לא-עלה-על-פלסבו</b> במחקרים-אלה. ⚠️ כתוצאה, המחקר-העדכני <b>עבר-כיוון</b>: במקום-לשאול-רק '<b>האם</b> טיפול-X יעיל' (שאלה-כללית-מדי), חוקרים-מתמקדים-כיום ב'<b>מדוע</b> ולמי' טיפול-מסוים יעיל - הכרה שהתאמה-אישית (איזה-טיפול-לאיזה-מטופל) חשובה-יותר מ'איזה-טיפול-הכי-טוב-באופן-כללי'.","mnemo":"📊 הכל עדיף מפלסבו, חוץ מפסיכודינמי"},{"id":"prof14_26","sec":"שאלת המרצה ⭐","type":"open","imp":true,"q":"הסבירו את ההבדלים בין מניעה ראשונית, שניונית ושלישונית.","a":"ראשונית=מניעת מצב לפני שהתחיל (מיומנויות עמידות, שינוי סביבה). שניונית=הגבלת משך/חומרת הפרעה שכבר החלה (איתור מוקדם, טיפול מיידי/משולב). שלישונית=צמצום השלכות ארוכות טווח ומניעת הישנות (המשך טיפול תרופתי גם אחרי שיפור).","explain":"שלוש-רמות-מניעה, מסודרות לפי <b>שלב-ההתערבות</b> ביחס-להתפתחות-הבעיה: <b>מניעה ראשונית</b> - התערבות <b>לפני</b> שהמצב-בכלל-התחיל - מטרה: <b>למנוע</b> את-הופעתו-מלכתחילה - כוללת בניית <b>מיומנויות-עמידות</b> (חוסן-נפשי מוקדם), ו<b>שינוי-סביבה</b> (הפחתת-גורמי-סיכון). <b>מניעה שניונית</b> - התערבות כשהמצב <b>כבר-החל</b>, אך-עדיין-מוקדם - מטרה: <b>להגביל</b> את-משך/חומרת-ההפרעה - כוללת <b>איתור-מוקדם</b> (זיהוי-סימני-אזהרה-ראשונים) ו<b>טיפול-מיידי/משולב</b> (התערבות-מהירה-לפני-החרפה). <b>מניעה שלישונית</b> - התערבות <b>לאחר</b> שהבעיה-כבר-קיימת/טופלה - מטרה: <b>צמצום השלכות-ארוכות-טווח</b> ו<b>מניעת-הישנות</b> - כוללת <b>המשך-טיפול-תרופתי גם-אחרי-שיפור</b> (כדי-שהשיפור-יישאר-יציב, לא-רק-זמני). ⚠️ שיטת-זכירה: ראשונית=<b>לפני</b>; שניונית=<b>בהתחלה</b> (מוקדם-בתהליך); שלישונית=<b>אחרי</b> (שמירה-על-הישגים-שכבר-הושגו).","mnemo":"3️⃣ לפני/בהתחלה/מניעת-הישנות"}];
